// Hyperreal Chiffon Dupatta Caught Mid-Twirl Against an Alpine Slope
// p5.js 2.x + p5.brush

const SEED = 7429;
let overlapGrid = [];
const GRID_RES = 240; // 5px per cell on 1200x1200 canvas

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  angleMode(DEGREES);
  randomSeed(SEED);
  noiseSeed(SEED);

  // Scale built-in brushes per Constraint 2
  brush.scaleBrushes(3);

  // Custom brushes for hyperreal chiffon threads, atmospheric haze, and zari glints
  brush.add("gossamer", {
    type: "default",
    weight: 0.28,
    scatter: 0.12,
    sharpness: 0.45,
    grain: 9,
    opacity: 42,
    spacing: 0.14,
    pressure: [0.25, 1.0, 0.25],
    noise: 0.35
  });

  brush.add("chiffon_edge", {
    type: "default",
    weight: 0.55,
    scatter: 0.08,
    sharpness: 0.65,
    grain: 6,
    opacity: 75,
    spacing: 0.12,
    pressure: [0.2, 1.15, 0.2],
    noise: 0.25
  });

  brush.add("soft_haze", {
    type: "spray",
    weight: 16,
    scatter: 3.2,
    opacity: 20,
    spacing: 0.55,
    pressure: [0.4, 1.0, 0.4]
  });

  // Custom diagonal alpine wind vector field
  brush.addField("alpine_wind", (t, field) => {
    for (let col = 0; col < field.length; col++) {
      for (let row = 0; row < field[0].length; row++) {
        let nx = col / field.length;
        let ny = row / field[0].length;
        let swerve = sin(nx * 180 + ny * 140) * 16 + (noise(nx * 3, ny * 3) - 0.5) * 24;
        field[col][row] = -34 + swerve;
      }
    }
    return field;
  });

  initOverlapGrid();
}

function draw() {
  translate(-width / 2, -height / 2);

  // Warm, sun-drenched high-altitude ground tone
  background("#f8fbe4");

  // 1. High sunlit alpine haze & impossibly green parrot/lime meadow slope
  renderAlpineMeadowAndHaze();

  // 2. Softly blurred mid-ground meadow grass & out-of-focus buttercup bokeh
  renderBlurredMeadowBokeh();

  // 3. The Mid-Twirl Chiffon Dupatta (3 continuous interweaving sheets: B -> A -> C)
  // Built with successive translucent watercolor glazes + optical secondary-hue overlaps
  renderChiffonDupatta();

  // 4. High-altitude sunbeams & gentle atmospheric haze veil
  renderSunHazeVeil();

  // 5. Crisp foreground buttercups & sharp sunlit alpine grass blades
  renderCrispForegroundButtercups();

  noLoop();
}

// ============================================================================
// OVERLAP GRID FOR EXACT SECONDARY-HUE WATERCOLOR GLAZING AT FOLD CROSSINGS
// ============================================================================

function initOverlapGrid() {
  overlapGrid = new Array(GRID_RES * GRID_RES);
  for (let i = 0; i < overlapGrid.length; i++) {
    overlapGrid[i] = { count: 0, hue: -1, sheetId: 0 };
  }
}

function sampleOverlapGrid(x, y) {
  let gx = floor(constrain(x / width, 0, 0.999) * GRID_RES);
  let gy = floor(constrain(y / height, 0, 0.999) * GRID_RES);
  return overlapGrid[gy * GRID_RES + gx];
}

function stampSheetToGrid(sheetId, uSteps, vSteps) {
  for (let iu = 0; iu < uSteps; iu++) {
    let u0 = iu / uSteps;
    let u1 = (iu + 1) / uSteps;
    let um = (u0 + u1) * 0.5;
    for (let iv = 0; iv < vSteps; iv++) {
      let v0 = iv / vSteps;
      let v1 = (iv + 1) / vSteps;
      let vm = (v0 + v1) * 0.5;
      let p00 = evalDupattaSheet(sheetId, u0, v0);
      let p10 = evalDupattaSheet(sheetId, u1, v0);
      let p11 = evalDupattaSheet(sheetId, u1, v1);
      let p01 = evalDupattaSheet(sheetId, u0, v1);
      let pm = evalDupattaSheet(sheetId, um, vm);

      let minX = max(0, floor(min(min(p00.x, p10.x), min(p11.x, p01.x)) / 5));
      let maxX = min(GRID_RES - 1, ceil(max(max(p00.x, p10.x), max(p11.x, p01.x)) / 5));
      let minY = max(0, floor(min(min(p00.y, p10.y), min(p11.y, p01.y)) / 5));
      let maxY = min(GRID_RES - 1, ceil(max(max(p00.y, p10.y), max(p11.y, p01.y)) / 5));

      for (let gy = minY; gy <= maxY; gy++) {
        for (let gx = minX; gx <= maxX; gx++) {
          let cell = overlapGrid[gy * GRID_RES + gx];
          if (cell.sheetId !== sheetId) {
            cell.count += 1;
            cell.hue = pm.hue;
            cell.sheetId = sheetId;
          }
        }
      }
    }
  }
}

// ============================================================================
// WATERCOLOR POLYGON HELPER
// ============================================================================

function drawWatercolorShape(pts, hexCol, opacity, bleed = 0.12, bleedDir = "out", tex = 0.32, border = 0.22, curvature = 0.15) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noHatch();
  brush.noMass();
  brush.fill(hexCol, opacity);
  brush.fillBleed(bleed, bleedDir);
  brush.fillTexture(tex, border);
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noFill();
}

// ============================================================================
// 1. ALPINE MEADOW SLOPE & HIGH BRIGHT HAZE
// ============================================================================

function renderAlpineMeadowAndHaze() {
  // High bright sunlit haze at top-left / upper sky-ridge
  let skyBands = [
    { pts: [[-40, -40], [1240, -40], [1240, 380], [-40, 210]], col: "#fffef0", op: 95, bleed: 0.45 },
    { pts: [[-40, 60], [1240, 180], [1240, 480], [-40, 310]], col: "#f2faab", op: 75, bleed: 0.48 },
    { pts: [[-40, 140], [640, 220], [1240, 390], [1240, 620], [-40, 420]], col: "#dcf564", op: 82, bleed: 0.45 }
  ];
  for (let b of skyBands) {
    drawWatercolorShape(b.pts, b.col, b.op, b.bleed, "out", 0.18, 0.08, 0.2);
  }

  // Diagonal alpine slope bands from bright lime crest down to rich parrot green
  let slopePasses = [
    // Upper sunlit lime slope
    { yL: 165, yR: 390, h: 250, col: "#c7ed3b", op: 88, bleed: 0.42 },
    { yL: 230, yR: 470, h: 270, col: "#aee324", op: 85, bleed: 0.42 },
    // Mid-slope luminous parrot green
    { yL: 320, yR: 560, h: 310, col: "#85d419", op: 92, bleed: 0.40 },
    { yL: 430, yR: 670, h: 340, col: "#6bc414", op: 90, bleed: 0.40 },
    { yL: 540, yR: 790, h: 350, col: "#54b010", op: 92, bleed: 0.38 },
    // Lower slope rich warm parrot & emerald green
    { yL: 680, yR: 910, h: 360, col: "#429c10", op: 95, bleed: 0.38 },
    { yL: 820, yR: 1020, h: 380, col: "#31820d", op: 98, bleed: 0.35 },
    { yL: 960, yR: 1110, h: 320, col: "#236909", op: 105, bleed: 0.35 }
  ];

  for (let s of slopePasses) {
    let pts = [];
    let steps = 8;
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let x = -40 + t * 1280;
      let y = lerp(s.yL, s.yR, t) + sin(t * 240 + s.yL) * 28 + (noise(t * 3, s.yL * 0.01) - 0.5) * 45;
      pts.push([x, y]);
    }
    for (let i = steps; i >= 0; i--) {
      let t = i / steps;
      let x = -40 + t * 1280;
      let y = lerp(s.yL + s.h, s.yR + s.h, t) + cos(t * 200 + s.yR) * 32;
      pts.push([x, y]);
    }
    drawWatercolorShape(pts, s.col, s.op, s.bleed, "out", 0.25, 0.12, 0.25);
  }

  // Sun-drenched golden-lime diagonal glades across the slope
  let gladePatches = [
    { cx: 260, cy: 360, rx: 240, ry: 85, ang: 12, col: "#e4fa73", op: 72 },
    { cx: 780, cy: 480, rx: 280, ry: 95, ang: 14, col: "#d2f24b", op: 68 },
    { cx: 180, cy: 640, rx: 220, ry: 80, ang: 8, col: "#b8e82c", op: 65 },
    { cx: 960, cy: 710, rx: 260, ry: 90, ang: 10, col: "#9cde21", op: 70 },
    { cx: 480, cy: 860, rx: 300, ry: 110, ang: 6, col: "#78cc16", op: 65 },
    { cx: 980, cy: 980, rx: 280, ry: 120, ang: 5, col: "#1d5707", op: 80 },
    { cx: 160, cy: 1060, rx: 250, ry: 110, ang: 4, col: "#1f5c08", op: 78 }
  ];

  for (let g of gladePatches) {
    let pts = [];
    for (let a = 0; a < 360; a += 30) {
      let rMod = 1 + 0.18 * sin(a * 3 + g.cx);
      let px = cos(a) * g.rx * rMod;
      let py = sin(a) * g.ry * rMod;
      let rx = g.cx + px * cos(g.ang) - py * sin(g.ang);
      let ry = g.cy + px * sin(g.ang) + py * cos(g.ang);
      pts.push([rx, ry]);
    }
    drawWatercolorShape(pts, g.col, g.op, 0.45, "out", 0.22, 0.1, 0.3);
  }
}

// ============================================================================
// 2. SOFTLY BLURRED MEADOW TEXTURE & BUTTERCUP BOKEH
// ============================================================================

function renderBlurredMeadowBokeh() {
  // Soft wind-swept grass flow in the blurred mid-ground
  brush.field("alpine_wind");
  let hazeColors = ["#d9f556", "#b2e629", "#83d119", "#5eb811", "#3e910d", "#eafa8c"];
  for (let cIdx = 0; cIdx < hazeColors.length; cIdx++) {
    brush.set("soft_haze", hazeColors[cIdx], random(0.9, 1.45));
    let count = 24;
    for (let i = 0; i < count; i++) {
      let x = random(-20, 1220);
      let minY = map(x, 0, 1200, 170, 390) + cIdx * 95;
      let y = random(minY, min(1190, minY + 260));
      brush.flowLine(x, y, random(90, 210), random(-25, 15));
    }
  }
  brush.noField();

  // Out-of-focus buttercup & sunlit dew bokeh circles (batched by color)
  let bokehBatches = [
    { col: "#e9fc88", op: 55, bleed: 0.45, count: 16, yMin: 220, yMax: 780, rMin: 18, rMax: 44 },
    { col: "#ffd924", op: 65, bleed: 0.42, count: 18, yMin: 480, yMax: 980, rMin: 12, rMax: 32 },
    { col: "#ffea61", op: 62, bleed: 0.45, count: 16, yMin: 360, yMax: 920, rMin: 14, rMax: 36 },
    { col: "#ffb700", op: 58, bleed: 0.38, count: 12, yMin: 640, yMax: 1060, rMin: 10, rMax: 24 },
    { col: "#fffce0", op: 60, bleed: 0.48, count: 14, yMin: 150, yMax: 580, rMin: 22, rMax: 52 }
  ];

  brush.noStroke();
  for (let batch of bokehBatches) {
    brush.fill(batch.col, batch.op);
    brush.fillBleed(batch.bleed, "out");
    brush.fillTexture(0.18, 0.08);
    for (let i = 0; i < batch.count; i++) {
      let bx = random(30, 1170);
      let slopeTop = map(bx, 0, 1200, 190, 410);
      let by = random(max(slopeTop, batch.yMin), batch.yMax);
      let br = random(batch.rMin, batch.rMax);
      brush.circle(bx, by, br, 0.22);
    }
  }
  brush.noFill();
}

// ============================================================================
// 3. MATHEMATICAL MODEL OF THE THREE INTERWEAVING CHIFFON SHEETS
// ============================================================================

function evalCubicBezier(p0, p1, p2, p3, t) {
  let mt = 1 - t;
  let mt2 = mt * mt;
  let t2 = t * t;
  let x = mt2 * mt * p0[0] + 3 * mt2 * t * p1[0] + 3 * mt * t2 * p2[0] + t2 * t * p3[0];
  let y = mt2 * mt * p0[1] + 3 * mt2 * t * p1[1] + 3 * mt * t2 * p2[1] + t2 * t * p3[1];
  let dx = 3 * mt2 * (p1[0] - p0[0]) + 6 * mt * t * (p2[0] - p1[0]) + 3 * t2 * (p3[0] - p2[0]);
  let dy = 3 * mt2 * (p1[1] - p0[1]) + 6 * mt * t * (p2[1] - p1[1]) + 3 * t2 * (p3[1] - p2[1]);
  let len = sqrt(dx * dx + dy * dy) || 1;
  return { x, y, tx: dx / len, ty: dy / len, nx: -dy / len, ny: dx / len };
}

function evalDupattaSheet(sheetId, u, v) {
  let spine, widthHalf, twistAng, pleatAmp1, pleatAmp2, pleatPhase, hue;

  if (sheetId === 1) {
    // SHEET B: Upper-left sunlit billowing wing loop
    spine = evalCubicBezier(
      [540, 620],
      [210, 480],
      [350, 175],
      [810, 315],
      u
    );
    widthHalf = 85 + 95 * sin(u * 180);
    twistAng = -18 + u * 42;
    pleatAmp1 = 0.085 * sin(u * 180);
    pleatAmp2 = 0.048 * sin(u * 180 + 25);
    pleatPhase = u * 165;
    // Dye: Shocking Magenta (0.0) -> Glowing Saffron (0.5) -> Peacock Blue (0.9)
    hue = constrain(0.08 + 0.58 * u + 0.26 * (1 - v) - 0.14 * sin(u * 180), 0, 1);

  } else if (sheetId === 2) {
    // SHEET A: Lower-left pallu entry sweeping up-right into the central twist
    spine = evalCubicBezier(
      [-55, 1055],
      [220, 825],
      [485, 585],
      [775, 365],
      u
    );
    widthHalf = lerp(195, 72, pow(u, 0.85)) + 32 * sin(u * 360);
    twistAng = u * 115; // Spirals into the mid-air twist node
    pleatAmp1 = 0.095 * (1 - 0.35 * u);
    pleatAmp2 = 0.052;
    pleatPhase = u * 210 + 40;
    // Dye: Peacock Blue (1.0) at lower-left pallu -> Saffron (0.5) -> Shocking Magenta (0.0)
    hue = constrain(1.05 - 1.22 * u + 0.18 * (v - 0.5), 0, 1);

  } else {
    // SHEET C: Grand foreground spiral & soaring upper-right gold-zari pallu
    spine = evalCubicBezier(
      [355, 895],
      [515, 650],
      [740, 365],
      [1155, 195],
      u
    );
    let flare = pow(max(0, (u - 0.6) / 0.4), 1.5) * 95;
    widthHalf = 95 + 88 * sin(u * 165) + flare;
    twistAng = -32 + u * 58;
    pleatAmp1 = 0.092 * (0.65 + 0.35 * sin(u * 180));
    pleatAmp2 = 0.054;
    pleatPhase = -u * 195 + 15;
    // Dye: Shocking Magenta (0.0) -> Saffron (0.5) -> Peacock Blue (1.0) at upper-right pallu
    // with a warm magenta-saffron contrast along the lower border (v > 0.78)
    let borderShift = v > 0.72 ? -0.38 * ((v - 0.72) / 0.28) : 0;
    hue = constrain(-0.08 + 1.18 * u + borderShift + 0.08 * sin(v * 360), 0, 1);
  }

  // Whitney fold S-pleat modulation across v in [0, 1]
  let vc = v - 0.5;
  let w1 = sin(v * 360 * 2.5 + pleatPhase);
  let w2 = sin(v * 360 * 5.0 - pleatPhase * 0.7 + 50);
  let dw1 = (2.5 * TWO_PI) * pleatAmp1 * cos(v * 360 * 2.5 + pleatPhase);
  let dw2 = (5.0 * TWO_PI) * pleatAmp2 * cos(v * 360 * 5.0 - pleatPhase * 0.7 + 50);

  // Derivative ds/dv tells us where the chiffon folds back on itself (ds/dv < 0.25)
  let dsdv = 1.0 + dw1 + dw2;
  let s = vc + pleatAmp1 * w1 + pleatAmp2 * w2;

  // Lift along spine tangent & normal to create billowing 3D arches
  let billowLift = sin(v * 180) * (28 + 24 * sin(u * 180)) + w1 * 14 + w2 * 7;
  let edgeRipple = (v < 0.08 || v > 0.92) ? sin(u * 360 * 4.5 + sheetId * 70) * 8 : 0;

  let cosT = cos(twistAng);
  let sinT = sin(twistAng);
  let dirX = spine.nx * cosT + spine.tx * sinT * 0.38;
  let dirY = spine.ny * cosT + spine.ty * sinT * 0.38;

  let x = spine.x + dirX * (s * widthHalf * 2.0) - spine.nx * (billowLift + edgeRipple) * 0.45 + spine.tx * w1 * 11;
  let y = spine.y + dirY * (s * widthHalf * 2.0) - spine.ny * (billowLift + edgeRipple) * 0.65 + spine.ty * w1 * 11;

  // Optical edge factor (high when fabric turns tangent to camera at pleat crests)
  let edgeFactor = constrain(1.0 - abs(dsdv) / 1.15, 0, 1);
  let isFolded = dsdv < 0.18;

  // Sun-facing value (high alpine sun at top-left)
  let sunLit = constrain(0.55 - 0.32 * w1 - 0.22 * dw1 + 0.18 * sin(u * 180), 0, 1);

  return { x, y, hue, edgeFactor, isFolded, sunLit, dsdv, w1, tx: spine.tx, ty: spine.ty, nx: dirX, ny: dirY };
}

// ============================================================================
// COLOR PALETTE & OPTICAL SECONDARY GLAZE MIXING
// ============================================================================

function getSingleLayerColor(hueVal, sunLit = 0.5) {
  // 0.0 = Shocking Magenta, 0.28 = Fiery Coral-Magenta, 0.52 = Saffron, 0.76 = Sunlit Turquoise-Teal, 1.0 = Peacock Blue
  if (hueVal < 0.22) {
    return sunLit > 0.62 ? "#ff1f80" : "#e60065"; // Shocking Magenta
  } else if (hueVal < 0.38) {
    return sunLit > 0.60 ? "#ff424e" : "#eb1c3a"; // Magenta-Saffron transition (Coral-Vermilion)
  } else if (hueVal < 0.64) {
    return sunLit > 0.62 ? "#ffaa14" : "#ff8800"; // Luminous Saffron
  } else if (hueVal < 0.80) {
    return sunLit > 0.60 ? "#12a67c" : "#008c6e"; // Saffron-Peacock transition (Emerald-Teal)
  } else {
    return sunLit > 0.62 ? "#009eb5" : "#007b94"; // Peacock Blue
  }
}

function getSecondaryOverlapColor(h1, h2) {
  let lo = min(h1, h2);
  let hi = max(h1, h2);

  // Both layers Shocking Magenta -> Deep Ruby Wine
  if (hi < 0.28) return "#8c003b";
  // Both layers Saffron -> Deep Burnt Marigold Amber
  if (lo >= 0.28 && hi <= 0.68) return "#c74300";
  // Both layers Peacock Blue -> Deep Abyssal Peacock
  if (lo > 0.68) return "#004259";
  // Shocking Magenta + Saffron -> Fiery Vermilion Crimson
  if (lo < 0.32 && hi <= 0.70) return "#cc1420";
  // Saffron + Peacock Blue -> Rich Viridian Emerald
  if (lo >= 0.28 && hi > 0.68) return "#006e47";
  // Shocking Magenta + Peacock Blue -> Deep Royal Mulberry Violet
  return "#4d0b6e";
}

// ============================================================================
// 4. RENDERING THE CHIFFON DUPATTA (GLAZES, PLEATS, WEAVE & ZARI DOTS)
// ============================================================================

function renderChiffonDupatta() {
  // Soft warm ambient shadow cast by the lower sweep onto the meadow
  let shadowPts = [
    [-40, 1090], [290, 880], [560, 740], [490, 960], [180, 1170], [-40, 1190]
  ];
  drawWatercolorShape(shadowPts, "#194d05", 48, 0.45, "out", 0.22, 0.08, 0.25);

  // Render the 3 connected sheets in back-to-front order:
  // Sheet 1 (Upper-left wing) -> Sheet 2 (Lower-left to center sweep) -> Sheet 3 (Foreground spiral & upper-right pallu)
  let sheetOrder = [1, 2, 3];

  for (let sheetId of sheetOrder) {
    // A. Base translucent watercolor glazes along longitudinal fold bands
    renderSheetBaseGlazes(sheetId);

    // B. Optical secondary-hue glazes where S-pleats fold back OR where sheets cross each other
    renderSheetSecondaryOverlaps(sheetId);

    // Record this sheet onto the overlap grid so subsequent sheets know what lies underneath
    stampSheetToGrid(sheetId, 44, 18);

    // C. Chiffon micro-pleat shading, Beer-Lambert optical edge darkening & sunlit silk sheen
    renderSheetChiffonWeaveAndFolds(sheetId);

    // D. Gold zari borders, pallu bands & scattered bootis stitched in tiny metallic pen dots
    renderSheetGoldZari(sheetId);
  }
}

function renderSheetBaseGlazes(sheetId) {
  // Subdivide across v into 6 longitudinal fold ribbons and 2 length segments (12 smooth ribbons per sheet)
  let vBands = [
    [0.00, 0.19],
    [0.16, 0.36],
    [0.33, 0.53],
    [0.50, 0.70],
    [0.67, 0.86],
    [0.83, 1.00]
  ];
  let uSplits = [
    [0.00, 0.38],
    [0.34, 0.70],
    [0.66, 1.00]
  ];

  for (let vb of vBands) {
    for (let us of uSplits) {
      let pts = [];
      let steps = 12;
      let uMid = (us[0] + us[1]) * 0.5;
      let vMid = (vb[0] + vb[1]) * 0.5;
      let pMid = evalDupattaSheet(sheetId, uMid, vMid);

      for (let i = 0; i <= steps; i++) {
        let u = lerp(us[0], us[1], i / steps);
        let p = evalDupattaSheet(sheetId, u, vb[0]);
        pts.push([p.x, p.y]);
      }
      for (let i = steps; i >= 0; i--) {
        let u = lerp(us[0], us[1], i / steps);
        let p = evalDupattaSheet(sheetId, u, vb[1]);
        pts.push([p.x, p.y]);
      }

      let col = getSingleLayerColor(pMid.hue, pMid.sunLit);
      // Translucent chiffon glaze: lets meadow or underlying fabric softly glow through
      let op = pMid.isFolded ? 76 : 56;
      drawWatercolorShape(pts, col, op, 0.11, "in", 0.34, 0.24, 0.12);
    }
  }
}

function renderSheetSecondaryOverlaps(sheetId) {
  // 1. Self-overlapping S-pleat strips along the length of the sheet
  // Where the Whitney fold derivative dsdv is low/negative, the chiffon doubles over itself
  let pleatTracks = [0.21, 0.51, 0.79];
  for (let vc of pleatTracks) {
    let uSegs = [[0.04, 0.54], [0.48, 0.96]];
    for (let us of uSegs) {
      let pts = [];
      let steps = 12;
      let pMid = evalDupattaSheet(sheetId, (us[0] + us[1]) * 0.5, vc);
      let halfW = 0.045;
      for (let i = 0; i <= steps; i++) {
        let u = lerp(us[0], us[1], i / steps);
        let p = evalDupattaSheet(sheetId, u, max(0, vc - halfW));
        pts.push([p.x, p.y]);
      }
      for (let i = steps; i >= 0; i--) {
        let u = lerp(us[0], us[1], i / steps);
        let p = evalDupattaSheet(sheetId, u, min(1, vc + halfW));
        pts.push([p.x, p.y]);
      }
      // Shift second hue slightly to capture ombré fold-over deepening
      let mixCol = getSecondaryOverlapColor(pMid.hue, constrain(pMid.hue + 0.18, 0, 1));
      drawWatercolorShape(pts, mixCol, 68, 0.08, "in", 0.38, 0.32, 0.1);
    }
  }

  // 2. Inter-sheet layer crossings (where Sheet 2 or Sheet 3 crosses over an earlier sheet)
  if (sheetId > 1) {
    let vStrips = [
      [0.04, 0.36],
      [0.32, 0.68],
      [0.64, 0.96]
    ];
    let uSamples = 28;

    for (let vs of vStrips) {
      let inOverlap = false;
      let uStart = 0;
      let underHueAccum = 0;
      let overHueAccum = 0;
      let countAccum = 0;

      for (let iu = 0; iu <= uSamples; iu++) {
        let u = iu / uSamples;
        let vm = (vs[0] + vs[1]) * 0.5;
        let pm = evalDupattaSheet(sheetId, u, vm);
        let cell = sampleOverlapGrid(pm.x, pm.y);
        let hit = cell && cell.count > 0 && cell.sheetId < sheetId;

        if (hit && iu < uSamples) {
          if (!inOverlap) {
            inOverlap = true;
            uStart = u;
            underHueAccum = 0;
            overHueAccum = 0;
            countAccum = 0;
          }
          underHueAccum += cell.hue;
          overHueAccum += pm.hue;
          countAccum++;
        } else if (inOverlap) {
          let uEnd = u;
          if (uEnd - uStart >= 0.06 && countAccum > 0) {
            let pts = [];
            let segSteps = 8;
            for (let k = 0; k <= segSteps; k++) {
              let uk = lerp(uStart, uEnd, k / segSteps);
              let p = evalDupattaSheet(sheetId, uk, vs[0]);
              pts.push([p.x, p.y]);
            }
            for (let k = segSteps; k >= 0; k--) {
              let uk = lerp(uStart, uEnd, k / segSteps);
              let p = evalDupattaSheet(sheetId, uk, vs[1]);
              pts.push([p.x, p.y]);
            }
            let avgUnder = underHueAccum / countAccum;
            let avgOver = overHueAccum / countAccum;
            let secCol = getSecondaryOverlapColor(avgOver, avgUnder);
            drawWatercolorShape(pts, secCol, 82, 0.07, "in", 0.42, 0.35, 0.12);
          }
          inOverlap = false;
        }
      }
    }
  }
}

function renderSheetChiffonWeaveAndFolds(sheetId) {
  // 1. Longitudinal gossamer warp threads & Beer-Lambert optical fold-edge darkening
  let vCount = 44;
  let uSteps = 26;

  // Pre-collect splines into color batches for crisp rendering
  let darkCreaseSplines = { ruby: [], amber: [], teal: [], violet: [] };
  let sheenSplines = { pink: [], gold: [], aqua: [], white: [] };
  let midWeaveSplines = { magenta: [], saffron: [], peacock: [] };

  for (let iv = 2; iv < vCount - 2; iv++) {
    let v = iv / vCount;
    for (let seg = 0; seg < 2; seg++) {
      let u0 = seg * 0.48;
      let u1 = u0 + 0.52;
      let pts = [];
      let um = (u0 + u1) * 0.5;
      let pm = evalDupattaSheet(sheetId, um, v);

      for (let iu = 0; iu <= uSteps / 2; iu++) {
        let u = lerp(u0, u1, iu / (uSteps / 2));
        let p = evalDupattaSheet(sheetId, u, v);
        let pr = 0.4 + 0.8 * p.edgeFactor;
        pts.push([p.x, p.y, pr]);
      }

      if (pm.edgeFactor > 0.52) {
        // Grazing fold crease -> optical edge darkening
        if (pm.hue < 0.28) darkCreaseSplines.ruby.push(pts);
        else if (pm.hue < 0.65) darkCreaseSplines.amber.push(pts);
        else darkCreaseSplines.teal.push(pts);
      } else if (pm.sunLit > 0.64 && iv % 2 === 0) {
        // Sun-catching fold crest -> gossamer silk specular highlight
        if (pm.hue < 0.30) sheenSplines.pink.push(pts);
        else if (pm.hue < 0.68) sheenSplines.gold.push(pts);
        else sheenSplines.aqua.push(pts);
        if (pm.sunLit > 0.74 && iv % 4 === 0) sheenSplines.white.push(pts);
      } else if (iv % 2 === 1) {
        if (pm.hue < 0.32) midWeaveSplines.magenta.push(pts);
        else if (pm.hue < 0.68) midWeaveSplines.saffron.push(pts);
        else midWeaveSplines.peacock.push(pts);
      }
    }
  }

  // Draw mid-tone chiffon warp threads
  let midMap = [
    { key: "magenta", col: "#d9005b" },
    { key: "saffron", col: "#e67300" },
    { key: "peacock", col: "#00738c" }
  ];
  for (let m of midMap) {
    brush.set("gossamer", m.col, 0.9);
    for (let sp of midWeaveSplines[m.key]) brush.spline(sp, 0.35);
  }

  // Draw optical fold-edge darkening (Beer-Lambert tangency creases)
  let darkMap = [
    { key: "ruby", col: "#750030" },
    { key: "amber", col: "#ad2600" },
    { key: "teal", col: "#003b4f" }
  ];
  for (let d of darkMap) {
    brush.set("chiffon_edge", d.col, 1.05);
    for (let sp of darkCreaseSplines[d.key]) brush.spline(sp, 0.4);
  }

  // Draw sunlit gossamer silk sheen along crests
  let sheenMap = [
    { key: "pink", col: "#ffd1e6", w: 1.0 },
    { key: "gold", col: "#fff0b8", w: 1.0 },
    { key: "aqua", col: "#ccf9ff", w: 1.0 },
    { key: "white", col: "#ffffff", w: 0.75 }
  ];
  for (let s of sheenMap) {
    brush.set("gossamer", s.col, s.w);
    for (let sp of sheenSplines[s.key]) brush.spline(sp, 0.35);
  }

  // 2. Transverse weft crinkle lines & wind tension ripples across the width
  let weftSplines = { magenta: [], saffron: [], peacock: [], highlight: [] };
  let weftCount = 34;
  for (let iu = 1; iu < weftCount; iu++) {
    let u = iu / weftCount;
    let pts = [];
    let pMid = evalDupattaSheet(sheetId, u, 0.5);
    for (let iv = 0; iv <= 12; iv++) {
      let v = iv / 12;
      let p = evalDupattaSheet(sheetId, u, v);
      pts.push([p.x, p.y, 0.35 + 0.5 * sin(v * 180)]);
    }
    if (iu % 3 === 0) weftSplines.highlight.push(pts);
    else if (pMid.hue < 0.33) weftSplines.magenta.push(pts);
    else if (pMid.hue < 0.68) weftSplines.saffron.push(pts);
    else weftSplines.peacock.push(pts);
  }

  brush.set("gossamer", "#c90054", 0.65);
  for (let sp of weftSplines.magenta) brush.spline(sp, 0.3);
  brush.set("gossamer", "#d96200", 0.65);
  for (let sp of weftSplines.saffron) brush.spline(sp, 0.3);
  brush.set("gossamer", "#00647a", 0.65);
  for (let sp of weftSplines.peacock) brush.spline(sp, 0.3);
  brush.set("gossamer", "#fff8eb", 0.6);
  for (let sp of weftSplines.highlight) brush.spline(sp, 0.3);
}

// ============================================================================
// 5. GOLD ZARI BORDERS & PALLU STITCHED IN TINY METALLIC PEN DOTS
// ============================================================================

function renderSheetGoldZari(sheetId) {
  // A. Subtle metallic gold & bronze base ribbons under the borders so the zari has physical weight
  let borderTracks = [0.012, 0.036, 0.058, 0.942, 0.964, 0.988];
  brush.set("cpencil", "#8c5606", 1.15);
  for (let vt of borderTracks) {
    let pts = [];
    for (let iu = 0; iu <= 24; iu++) {
      let p = evalDupattaSheet(sheetId, iu / 24, vt);
      pts.push([p.x, p.y, 0.85]);
    }
    brush.spline(pts, 0.35);
  }

  // On Sheet 3 (upper-right pallu) and Sheet 2 (lower-left pallu), draw base metallic bands across the pallu
  if (sheetId === 3) {
    let palluU = [0.84, 0.865, 0.89, 0.918, 0.945, 0.97, 0.99];
    brush.set("cpencil", "#965f08", 1.25);
    for (let pu of palluU) {
      let pts = [];
      for (let iv = 0; iv <= 16; iv++) {
        let p = evalDupattaSheet(sheetId, pu, iv / 16);
        pts.push([p.x, p.y, 0.9]);
      }
      brush.spline(pts, 0.3);
    }
  } else if (sheetId === 2) {
    let palluU = [0.02, 0.05, 0.08, 0.115];
    brush.set("cpencil", "#8a5406", 1.15);
    for (let pu of palluU) {
      let pts = [];
      for (let iv = 0; iv <= 14; iv++) {
        let p = evalDupattaSheet(sheetId, pu, iv / 14);
        pts.push([p.x, p.y, 0.85]);
      }
      brush.spline(pts, 0.3);
    }
  }

  // B. Collect thousands of tiny metallic pen dots into 4 specular gold buckets:
  // 0: Shadow Bronze (#704103), 1: Antique Gold (#bf8411), 2: 24k Sunlit Gold (#f7c428), 3: White-Gold Specular (#fff8b0 / #ffffff)
  let dotBuckets = [[], [], [], []];

  function addZariDot(u, v, sparkleBias = 0) {
    let p = evalDupattaSheet(sheetId, constrain(u, 0, 1), constrain(v, 0, 1));
    let glint = p.sunLit + sparkleBias + 0.22 * sin(u * 360 * 19 + v * 360 * 13);
    let bIdx = 1;
    if (glint < 0.36) bIdx = 0;
    else if (glint < 0.64) bIdx = 1;
    else if (glint < 0.84) bIdx = 2;
    else bIdx = 3;

    // Tiny stitch vector aligned with the local fabric tangent
    let stitchLen = random(1.6, 3.1);
    let dx = p.tx * stitchLen;
    let dy = p.ty * stitchLen;
    dotBuckets[bIdx].push([p.x - dx * 0.5, p.y - dy * 0.5, p.x + dx * 0.5, p.y + dy * 0.5]);
  }

  // 1. Selvedge Borders (both edges v in [0.006..0.068] and [0.932..0.994])
  let uDotSteps = 165;
  for (let iu = 0; iu <= uDotSteps; iu++) {
    let u = iu / uDotSteps;
    let tri = (2 / PI) * asin(sin(u * 360 * 14)); // Triangle wave in [-1, 1] for diamond jaali lattice

    for (let side = 0; side < 2; side++) {
      let vBase = side === 0 ? 0.037 : 0.963;
      // Outer & inner guard tracks of tiny metallic dots
      addZariDot(u, vBase - 0.029, 0.05);
      addZariDot(u, vBase - 0.022, -0.04);
      addZariDot(u, vBase + 0.022, -0.04);
      addZariDot(u, vBase + 0.029, 0.05);

      // Diamond chevron lattice (jaali) in the center of the border
      addZariDot(u, vBase + tri * 0.016, 0.08);
      addZariDot(u, vBase - tri * 0.016, 0.02);

      // Central floral rosette jewel dot at the center of each diamond cell
      if (iu % 6 === 3) {
        addZariDot(u, vBase, 0.22);
        addZariDot(u, vBase + 0.006, 0.12);
        addZariDot(u, vBase - 0.006, 0.12);
      }
    }
  }

  // 2. Grand Ornamental Pallu on Sheet 3 (Upper-Right Billow, u in [0.83..0.995])
  if (sheetId === 3) {
    let vPalluSteps = 95;
    let palluTracks = [0.835, 0.858, 0.882, 0.908, 0.934, 0.958, 0.980, 0.993];
    for (let iv = 2; iv < vPalluSteps - 2; iv++) {
      let v = iv / vPalluSteps;
      let arch = abs(sin(v * 360 * 9));
      for (let tIdx = 0; tIdx < palluTracks.length; tIdx++) {
        let uTrack = palluTracks[tIdx];
        addZariDot(uTrack, v, 0.06);
        if (tIdx % 2 === 1) {
          addZariDot(uTrack + arch * 0.014, v, 0.14);
        }
      }
      // Paisleys / kalki diamond clusters inside the pallu bands
      if (iv % 8 === 4) {
        for (let uMotif of [0.870, 0.921, 0.969]) {
          addZariDot(uMotif, v, 0.25);
          addZariDot(uMotif + 0.006, v, 0.15);
          addZariDot(uMotif - 0.006, v, 0.15);
          addZariDot(uMotif, v + 0.010, 0.15);
          addZariDot(uMotif, v - 0.010, 0.15);
        }
      }
    }
  }

  // 3. Lower-Left Pallu on Sheet 2 (u in [0.008..0.13])
  if (sheetId === 2) {
    let vPalluSteps = 75;
    let palluTracks = [0.015, 0.038, 0.064, 0.092, 0.118];
    for (let iv = 2; iv < vPalluSteps - 2; iv++) {
      let v = iv / vPalluSteps;
      let arch = abs(sin(v * 360 * 7));
      for (let tIdx = 0; tIdx < palluTracks.length; tIdx++) {
        let uTrack = palluTracks[tIdx];
        addZariDot(uTrack, v, 0.02);
        if (tIdx % 2 === 0) {
          addZariDot(uTrack + arch * 0.012, v, 0.1);
        }
      }
    }
  }

  // 4. Scattered Gold Zari Bootis (7-dot starry rosettes) across the sheer chiffon body
  let bootiURows = 9;
  let bootiVCols = 5;
  for (let iu = 1; iu < bootiURows; iu++) {
    let u = iu / bootiURows;
    if (sheetId === 3 && u > 0.81) continue;
    if (sheetId === 2 && u < 0.14) continue;
    for (let iv = 1; iv <= bootiVCols; iv++) {
      let vOffset = (iu % 2 === 0) ? 0.07 : -0.05;
      let v = constrain(iv / (bootiVCols + 1) + vOffset, 0.13, 0.87);
      // 7-dot floral booti cluster mapped in (u, v)
      addZariDot(u, v, 0.26);
      addZariDot(u + 0.0055, v, 0.14);
      addZariDot(u - 0.0055, v, 0.14);
      addZariDot(u, v + 0.011, 0.14);
      addZariDot(u, v - 0.011, 0.14);
      addZariDot(u + 0.004, v + 0.008, 0.06);
      addZariDot(u - 0.004, v - 0.008, 0.06);
    }
  }

  // C. Render all collected metallic dots in 4 crisp color-batched passes
  let bucketStyles = [
    { brush: "rotring", col: "#6e4002", w: 0.95 },
    { brush: "rotring", col: "#c4880e", w: 1.05 },
    { brush: "pen", col: "#f7c625", w: 1.15 },
    { brush: "rotring", col: "#fff9b8", w: 1.25 }
  ];

  for (let b = 0; b < 4; b++) {
    brush.set(bucketStyles[b].brush, bucketStyles[b].col, bucketStyles[b].w);
    let segs = dotBuckets[b];
    for (let i = 0; i < segs.length; i++) {
      let s = segs[i];
      brush.line(s[0], s[1], s[2], s[3]);
    }
  }

  // Pure white-gold micro-glints on the brightest 35% of bucket 3
  brush.set("rotring", "#ffffff", 1.1);
  let brightSegs = dotBuckets[3];
  for (let i = 0; i < brightSegs.length; i += 3) {
    let s = brightSegs[i];
    brush.line(s[0], s[1], (s[0] + s[2]) * 0.5, (s[1] + s[3]) * 0.5);
  }

  // D. Fluttering Gold Kiran Fringe Tassels at the very tip of Sheet 3's upper-right pallu
  if (sheetId === 3) {
    let fringeColors = ["#b87a09", "#f2bd24", "#fff6a8"];
    for (let cIdx = 0; cIdx < fringeColors.length; cIdx++) {
      brush.set("rotring", fringeColors[cIdx], 0.85);
      for (let iv = 3; iv < 62; iv += 3) {
        let v = (iv + cIdx * 0.8) / 65;
        let p0 = evalDupattaSheet(3, 0.996, v);
        let len = random(14, 28);
        let ang = -22 + sin(v * 360 * 6) * 18;
        let x2 = p0.x + cos(ang) * len;
        let y2 = p0.y + sin(ang) * len;
        brush.line(p0.x, p0.y, x2, y2);
      }
    }
  }
}

// ============================================================================
// 6. HIGH-ALTITUDE SUNBEAMS & GENTLE ATMOSPHERIC HAZE
// ============================================================================

function renderSunHazeVeil() {
  // Diagonal warm sun-glaze ribbons streaming from top-left
  let sunBeams = [
    [[-30, -30], [520, -30], [760, 420], [180, 520]],
    [[260, -30], [880, -30], [1080, 340], [580, 420]]
  ];
  for (let sb of sunBeams) {
    drawWatercolorShape(sb, "#fffef2", 26, 0.5, "out", 0.12, 0.04, 0.25);
  }

  // Fine sunlit dust motes / pollen sparkling in the mountain air around the twirling dupatta
  let motesGold = [];
  let motesWhite = [];
  for (let i = 0; i < 85; i++) {
    let mx = random(80, 1140);
    let my = random(60, 860);
    if (i % 2 === 0) motesGold.push([mx, my]);
    else motesWhite.push([mx, my]);
  }
  brush.set("rotring", "#ffea75", 1.1);
  for (let m of motesGold) brush.line(m[0], m[1], m[0] + 1.8, m[1] - 1.2);
  brush.set("rotring", "#ffffff", 1.0);
  for (let m of motesWhite) brush.line(m[0], m[1], m[0] + 1.5, m[1] - 1.0);
}

// ============================================================================
// 7. CRISP FOREGROUND BUTTERCUPS & SUNLIT ALPINE GRASS BLADES
// ============================================================================

function renderCrispForegroundButtercups() {
  // 1. Sharp foreground alpine grass blades & buttercup stems (lower-right and lower-left clusters)
  let darkStems = [];
  let midStems = [];
  let sunlitStems = [];

  // Generate foreground grass blades swaying in the diagonal wind
  for (let i = 0; i < 68; i++) {
    let isRight = i < 46;
    let bx = isRight ? random(620, 1210) : random(-20, 370);
    let by = random(1160, 1240);
    let h = isRight ? random(140, 390) : random(120, 290);
    let lean = random(25, 115);

    let p0 = [bx, by, 1.1];
    let p1 = [bx + lean * 0.35, by - h * 0.48, 0.9];
    let p2 = [bx + lean * 0.78, by - h * 0.82, 0.65];
    let p3 = [bx + lean, by - h, 0.25];
    let sp = [p0, p1, p2, p3];

    if (i % 3 === 0) darkStems.push(sp);
    else if (i % 3 === 1) midStems.push(sp);
    else sunlitStems.push(sp);
  }

  // Hero buttercup positions (crisp, in-focus botanical blooms)
  let flowers = [
    // Right foreground cluster
    { x: 960, y: 965, r: 42, tilt: 0.78, rot: -18, stemX: 910, stemY: 1210 },
    { x: 1075, y: 1035, r: 48, tilt: 0.86, rot: 12, stemX: 1035, stemY: 1215 },
    { x: 845, y: 1055, r: 38, tilt: 0.72, rot: -28, stemX: 790, stemY: 1215 },
    { x: 1135, y: 915, r: 33, tilt: 0.68, rot: -10, stemX: 1095, stemY: 1200 },
    { x: 745, y: 1115, r: 34, tilt: 0.82, rot: 22, stemX: 710, stemY: 1215 },
    { x: 990, y: 1125, r: 44, tilt: 0.90, rot: 8, stemX: 965, stemY: 1220 },
    { x: 885, y: 920, r: 27, tilt: 0.64, rot: -32, stemX: 830, stemY: 1190 },
    // Left foreground cluster
    { x: 145, y: 1075, r: 40, tilt: 0.82, rot: 18, stemX: 105, stemY: 1215 },
    { x: 255, y: 1125, r: 35, tilt: 0.76, rot: -14, stemX: 225, stemY: 1215 },
    { x: 65, y: 1135, r: 32, tilt: 0.85, rot: 25, stemX: 40, stemY: 1215 }
  ];

  // Add stems for each hero flower
  for (let f of flowers) {
    let mx = (f.stemX + f.x) * 0.5 - 18;
    let my = (f.stemY + f.y) * 0.5;
    darkStems.push([[f.stemX, f.stemY, 1.2], [mx, my, 1.0], [f.x, f.y + f.r * 0.25, 0.8]]);
    sunlitStems.push([[f.stemX - 2.5, f.stemY, 0.8], [mx - 2.5, my, 0.7], [f.x - 2, f.y + f.r * 0.25, 0.6]]);
  }

  // Draw crisp palmate buttercup leaves in the foreground
  let leafPositions = [
    { x: 920, y: 1085, s: 48, ang: -25 },
    { x: 1040, y: 1140, s: 54, ang: 15 },
    { x: 800, y: 1145, s: 44, ang: -40 },
    { x: 185, y: 1150, s: 46, ang: 10 }
  ];
  for (let lf of leafPositions) {
    for (let lobe = -1; lobe <= 1; lobe++) {
      let la = lf.ang + lobe * 42;
      let pts = [
        [lf.x, lf.y],
        [lf.x + cos(la - 18) * lf.s * 0.65, lf.y + sin(la - 18) * lf.s * 0.65],
        [lf.x + cos(la - 6) * lf.s, lf.y + sin(la - 6) * lf.s],
        [lf.x + cos(la + 8) * lf.s * 0.92, lf.y + sin(la + 8) * lf.s * 0.92],
        [lf.x + cos(la + 20) * lf.s * 0.6, lf.y + sin(la + 20) * lf.s * 0.6]
      ];
      drawWatercolorShape(pts, lobe === 0 ? "#36850d" : "#266607", 155, 0.04, "in", 0.35, 0.4, 0.1);
    }
  }

  // Draw grass & flower stems in batched passes
  brush.set("2B", "#154204", 1.25);
  for (let sp of darkStems) brush.spline(sp, 0.35);

  brush.set("cpencil", "#4da60e", 1.15);
  for (let sp of midStems) brush.spline(sp, 0.35);

  brush.set("cpencil", "#d4fa4b", 0.95);
  for (let sp of sunlitStems) brush.spline(sp, 0.35);

  // 2. Render the 5-petal glossy buttercup blooms
  let petalBasePolys = [];
  let petalCupPolys = [];
  let petalVeinLines = [];
  let petalRimLines = [];
  let petalGlossLines = [];
  let stamenLines = [];
  let antherDots = [];
  let carpelDots = [];

  for (let f of flowers) {
    for (let pIdx = 0; pIdx < 5; pIdx++) {
      let baseAng = f.rot + pIdx * 72;
      let pPts = [];
      let cupPts = [[f.x, f.y]];

      // Cup-shaped obovate buttercup petal contour
      let angOffsets = [-31, -22, -10, 0, 10, 22, 31];
      let radFactors = [0.22, 0.72, 0.98, 1.04, 0.98, 0.72, 0.22];

      pPts.push([f.x, f.y]);
      for (let k = 0; k < angOffsets.length; k++) {
        let a = baseAng + angOffsets[k];
        let rad = f.r * radFactors[k];
        let lx = cos(a) * rad;
        let ly = sin(a) * rad * f.tilt;
        // Cup upward curvature
        let cupLift = -abs(sin(a * 0.5)) * f.r * 0.14 * (1 - f.tilt);
        pPts.push([f.x + lx, f.y + ly + cupLift]);
        if (k >= 1 && k <= 5) {
          cupPts.push([f.x + lx * 0.55, f.y + ly * 0.55 + cupLift * 0.5]);
        }
      }
      petalBasePolys.push(pPts);
      petalCupPolys.push(cupPts);

      // Fine radial striations & waxy specular gloss on upper petals
      for (let vIdx = -2; vIdx <= 2; vIdx++) {
        let va = baseAng + vIdx * 9.5;
        let x1 = f.x + cos(va) * f.r * 0.18;
        let y1 = f.y + sin(va) * f.r * 0.18 * f.tilt;
        let x2 = f.x + cos(va) * f.r * 0.88;
        let y2 = f.y + sin(va) * f.r * 0.88 * f.tilt;
        petalVeinLines.push([x1, y1, (x1 + x2) * 0.5, (y1 + y2) * 0.5]);

        // Mirror-like waxy gloss on the outer half of each petal
        let gx1 = f.x + cos(va) * f.r * 0.45;
        let gy1 = f.y + sin(va) * f.r * 0.45 * f.tilt;
        let gx2 = f.x + cos(va) * f.r * 0.86;
        let gy2 = f.y + sin(va) * f.r * 0.86 * f.tilt;
        petalGlossLines.push([gx1, gy1, gx2, gy2]);
      }

      // Crisp petal outline segment
      for (let k = 1; k < pPts.length - 1; k++) {
        petalRimLines.push([pPts[k][0], pPts[k][1], pPts[k + 1][0], pPts[k + 1][1]]);
      }
    }

    // Stamens & central lime-green carpels
    for (let s = 0; s < 22; s++) {
      let sa = s * (360 / 22) + random(-6, 6);
      let sr1 = f.r * 0.11;
      let sr2 = f.r * random(0.24, 0.34);
      let sx1 = f.x + cos(sa) * sr1;
      let sy1 = f.y + sin(sa) * sr1 * f.tilt;
      let sx2 = f.x + cos(sa) * sr2;
      let sy2 = f.y + sin(sa) * sr2 * f.tilt - 2.0;
      stamenLines.push([sx1, sy1, sx2, sy2]);
      antherDots.push([sx2, sy2, sx2 + 1.6, sy2 - 1.2]);
    }

    for (let c = 0; c < 12; c++) {
      let ca = c * 30;
      let cr = f.r * random(0.02, 0.11);
      let cx = f.x + cos(ca) * cr;
      let cy = f.y + sin(ca) * cr * f.tilt;
      carpelDots.push([cx, cy, cx + 1.8, cy + 1.4]);
    }
  }

  // Batch render buttercup petals (brilliant golden yellow + deep amber cup center)
  for (let poly of petalBasePolys) {
    drawWatercolorShape(poly, "#ffd900", 175, 0.03, "in", 0.25, 0.35, 0.18);
  }
  for (let poly of petalCupPolys) {
    drawWatercolorShape(poly, "#ff9d00", 135, 0.05, "in", 0.28, 0.3, 0.15);
  }

  // Crisp botanical detailing on buttercups
  brush.set("cpencil", "#d97200", 0.85);
  for (let l of petalVeinLines) brush.line(l[0], l[1], l[2], l[3]);

  brush.set("rotring", "#b85500", 0.75);
  for (let l of petalRimLines) brush.line(l[0], l[1], l[2], l[3]);

  // Famous waxy mirror-gloss highlights on buttercup petals
  brush.set("pen", "#fff9b8", 1.05);
  for (let i = 0; i < petalGlossLines.length; i++) {
    let l = petalGlossLines[i];
    brush.line(l[0], l[1], l[2], l[3]);
  }
  brush.set("rotring", "#ffffff", 0.9);
  for (let i = 0; i < petalGlossLines.length; i += 2) {
    let l = petalGlossLines[i];
    brush.line(l[0], l[1], (l[0] + l[2]) * 0.5, (l[1] + l[3]) * 0.5);
  }

  // Stamens, anthers & lime-green carpel centers
  brush.set("rotring", "#cc5800", 0.85);
  for (let l of stamenLines) brush.line(l[0], l[1], l[2], l[3]);

  brush.set("pen", "#4e8c0b", 1.3);
  for (let d of carpelDots) brush.line(d[0], d[1], d[2], d[3]);

  brush.set("rotring", "#b8f224", 1.0);
  for (let i = 0; i < carpelDots.length; i += 2) {
    let d = carpelDots[i];
    brush.line(d[0], d[1], d[0] + 1.2, d[1] - 1.0);
  }

  brush.set("rotring", "#fff275", 1.15);
  for (let d of antherDots) brush.line(d[0], d[1], d[2], d[3]);
}

// Hyperrealism in p5.brush: Beneath an Art Deco Sunburst Umbrella

const CX = 600;
const CY = 600;
const N_PANELS = 12;
const STEP_ANG = 360 / N_PANELS; // 30 degrees per panel
const R_CANOPY = 512;
const R_TIP = 564;

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(4219);
  noiseSeed(4219);
}

// Computes a point on panel `p` at normalized chord position `u` in [0, 1] and radial distance `r`
// Incorporates the inward catenary tension scallop characteristic of taut umbrella panels.
function panelPoint(p, u, r) {
  let a1 = p * STEP_ANG - 90;
  let a2 = (p + 1) * STEP_ANG - 90;
  let x1 = CX + r * cos(a1);
  let y1 = CY + r * sin(a1);
  let x2 = CX + r * cos(a2);
  let y2 = CY + r * sin(a2);

  let px = lerp(x1, x2, u);
  let py = lerp(y1, y2, u);

  // Parabolic inward tension sag (strongest at the outer hem, zero at the hub)
  let radialRatio = constrain(r / R_CANOPY, 0, 1.1);
  let sag = pow(radialRatio, 1.85) * 31 * (4 * u * (1 - u));

  // Subtle secondary tension curve near the ribs
  let ribPinch = pow(radialRatio, 2.2) * 3.5 * sin(u * 180);
  let totalPull = sag + ribPinch;

  let ang = atan2(py - CY, px - CX);
  return {
    x: px - totalPull * cos(ang),
    y: py - totalPull * sin(ang),
    ang: ang
  };
}

// Helper to draw a closed polygon with p5.brush from an array of {x, y} points
function drawPolyShape(pts, curvature = 0) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i].x, pts[i].y);
  }
  brush.endShape(true);
}

// Builds a quad strip patch on panel `p` between [r1, r2] and [u1, u2]
function getPanelPatch(p, r1, r2, u1, u2, steps = 6) {
  let pts = [];
  for (let i = 0; i <= steps; i++) {
    let u = lerp(u1, u2, i / steps);
    pts.push(panelPoint(p, u, r2));
  }
  for (let i = steps; i >= 0; i--) {
    let u = lerp(u1, u2, i / steps);
    pts.push(panelPoint(p, u, r1));
  }
  return pts;
}

function draw() {
  translate(-width / 2, -height / 2);

  // =========================================================================
  // 1. COOL MIDDAY SKY BACKGROUND & CORONA GLOW
  // =========================================================================
  background("#e8f3f8");

  brush.noStroke();
  brush.noHatch();

  // Deep cool cerulean-slate corners fading inward toward the bright midday corona
  const skyCornerLayers = [
    { rOuter: 920, rInner: 620, col: "#7c9fb8", op: 85 },
    { rOuter: 860, rInner: 575, col: "#9ab9ce", op: 75 },
    { rOuter: 780, rInner: 540, col: "#bdd6e6", op: 70 },
    { rOuter: 680, rInner: 500, col: "#dff0f8", op: 90 },
    { rOuter: 590, rInner: 470, col: "#f7fcff", op: 120 }
  ];

  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.45, 0.2);

  for (let layer of skyCornerLayers) {
    brush.fill(layer.col, layer.op);
    for (let p = 0; p < N_PANELS; p++) {
      let a1 = p * STEP_ANG - 90;
      let a2 = (p + 1) * STEP_ANG - 90;
      let aMid = (a1 + a2) * 0.5;
      let pts = [
        { x: CX + layer.rInner * cos(a1), y: CY + layer.rInner * sin(a1) },
        { x: CX + layer.rInner * cos(aMid), y: CY + layer.rInner * sin(aMid) },
        { x: CX + layer.rInner * cos(a2), y: CY + layer.rInner * sin(a2) },
        { x: CX + layer.rOuter * cos(a2), y: CY + layer.rOuter * sin(a2) },
        { x: CX + layer.rOuter * cos(aMid), y: CY + layer.rOuter * sin(aMid) },
        { x: CX + layer.rOuter * cos(a1), y: CY + layer.rOuter * sin(a1) }
      ];
      drawPolyShape(pts, 0.1);
    }
  }
  brush.noFill();

  // Crisp midday diffraction rays in the cool sky around the canopy
  for (let p = 0; p < N_PANELS; p++) {
    randomSeed(1000); // Strict radial symmetry across all 12 sectors
    for (let i = 0; i < 18; i++) {
      let u = (i + 0.5) / 18;
      let basePt = panelPoint(p, u, R_CANOPY - 4);
      let ang = basePt.ang + random(-3, 3);
      let len = random(65, 240);
      let col = i % 2 === 0 ? "#ffffff" : "#b4d2e4";
      brush.set("2H", col, random(0.2, 0.55));
      brush.line(
        basePt.x,
        basePt.y,
        basePt.x + len * cos(ang),
        basePt.y + len * sin(ang)
      );
    }
  }

  // =========================================================================
  // 2. DENSE GOUACHE-LIKE WATERCOLOR CANOPY PANELS
  //    (Jet black at the hub -> cool slate mid -> smoky bronze edge translucence)
  // =========================================================================
  brush.noStroke();

  // Solid base underpainting wash so the canopy has dense gouache opacity
  const baseWashBands = [
    { r1: 0,   r2: 145, col: "#090d14", op: 245 },
    { r1: 135, r2: 265, col: "#141c26", op: 235 },
    { r1: 255, r2: 365, col: "#292c30", op: 225 },
    { r1: 355, r2: 445, col: "#54473b", op: 215 },
    { r1: 435, r2: 488, col: "#856e56", op: 205 },
    { r1: 480, r2: 504, col: "#a88d6f", op: 195 }
  ];

  for (let b of baseWashBands) {
    brush.wash(b.col, b.op);
    for (let p = 0; p < N_PANELS; p++) {
      let pts = getPanelPatch(p, b.r1, b.r2, 0, 1, 8);
      drawPolyShape(pts, 0);
    }
  }
  brush.noWash();

  // Layered gouache-watercolor bands with organic bleed and pigment texture
  const gouacheBands = [
    { r1: 0,   r2: 98,  col: "#06090e", op: 210, bleed: 0.12 },
    { r1: 82,  r2: 175, col: "#0d131d", op: 185, bleed: 0.16 },
    { r1: 155, r2: 245, col: "#18222e", op: 165, bleed: 0.18 },
    { r1: 225, r2: 315, col: "#2b2f35", op: 155, bleed: 0.20 },
    { r1: 295, r2: 382, col: "#483f37", op: 155, bleed: 0.20 },
    { r1: 362, r2: 438, col: "#6e5c49", op: 150, bleed: 0.18 },
    { r1: 422, r2: 480, col: "#947b60", op: 145, bleed: 0.16 },
    { r1: 468, r2: 503, col: "#b89c7c", op: 135, bleed: 0.12 }
  ];

  for (let b of gouacheBands) {
    brush.fillBleed(b.bleed, "in");
    brush.fillTexture(0.55, 0.35);
    brush.fill(b.col, b.op);
    for (let p = 0; p < N_PANELS; p++) {
      let pts = getPanelPatch(p, b.r1, b.r2, 0, 1, 8);
      drawPolyShape(pts, 0);
    }
  }

  // Mid-panel backlit translucence blooms (smoky bronze glow brightest in panel centers
  // where nylon is stretched thinnest, contrasted with cool slate sky reflection near ribs)
  brush.fillBleed(0.22, "out");
  brush.fillTexture(0.45, 0.25);

  // Warm smoky-bronze transmitted sunlight core in the outer half of each panel
  brush.fill("#c7aa84", 95);
  for (let p = 0; p < N_PANELS; p++) {
    let pts = getPanelPatch(p, 355, 496, 0.16, 0.84, 6);
    drawPolyShape(pts, 0.15);
  }

  brush.fill("#e3c9a4", 80);
  for (let p = 0; p < N_PANELS; p++) {
    let pts = getPanelPatch(p, 425, 498, 0.24, 0.76, 6);
    drawPolyShape(pts, 0.15);
  }

  // Cool cerulean-slate skylight sheen over the mid-canopy tension zone
  brush.fill("#486278", 65);
  for (let p = 0; p < N_PANELS; p++) {
    let pts = getPanelPatch(p, 175, 340, 0.12, 0.88, 6);
    drawPolyShape(pts, 0.1);
  }

  // Darker shadow flutes hugging the ribs where fabric layers double over the seams
  brush.fillBleed(0.14, "in");
  brush.fill("#0c1118", 155);
  for (let p = 0; p < N_PANELS; p++) {
    let leftSeam = getPanelPatch(p, 80, 495, 0.0, 0.09, 3);
    let rightSeam = getPanelPatch(p, 80, 495, 0.91, 1.0, 3);
    drawPolyShape(leftSeam, 0);
    drawPolyShape(rightSeam, 0);
  }
  brush.noFill();

  // =========================================================================
  // 3. TAUT NYLON MICRO-WEAVE & CIRCUMFERENTIAL TENSION TEXTURE
  // =========================================================================
  // Circumferential weft threads following the scalloped catenary curve of each panel
  for (let r = 64; r <= 500; r += 5.5) {
    let t = (r - 64) / (500 - 64);
    let col;
    let wt;
    if (t < 0.28) {
      col = Math.floor(r) % 2 === 0 ? "#06090e" : "#1c2836";
      wt = 0.22;
    } else if (t < 0.56) {
      col = Math.floor(r) % 2 === 0 ? "#242d38" : "#4b5a68";
      wt = 0.24;
    } else if (t < 0.82) {
      col = Math.floor(r) % 2 === 0 ? "#57483b" : "#9c8468";
      wt = 0.25;
    } else {
      col = Math.floor(r) % 2 === 0 ? "#856d54" : "#dec4a2";
      wt = 0.28;
    }

    brush.set("2H", col, wt);
    for (let p = 0; p < N_PANELS; p++) {
      let splinePts = [];
      for (let s = 0; s <= 6; s++) {
        let u = s / 6;
        let pt = panelPoint(p, u, r);
        splinePts.push([pt.x, pt.y]);
      }
      brush.spline(splinePts, 0.35);
    }
  }

  // Radial warp threads catching cool zenith sky light and warm bronze transmitted light
  for (let k = 1; k < 22; k++) {
    let u = k / 22;
    let centerProx = 1 - abs(u - 0.5) * 2; // 1 at panel center, 0 at ribs

    // Inner-to-mid cool slate warp threads
    brush.set("2H", k % 2 === 0 ? "#384c5e" : "#141d28", 0.2);
    for (let p = 0; p < N_PANELS; p++) {
      let p1 = panelPoint(p, u, 85);
      let p2 = panelPoint(p, u, 345);
      brush.line(p1.x, p1.y, p2.x, p2.y);
    }

    // Outer backlit smoky-bronze and champagne warp threads
    let outerCol = centerProx > 0.45 ? "#e6cda8" : "#8c755c";
    brush.set("2H", outerCol, 0.22 + centerProx * 0.1);
    for (let p = 0; p < N_PANELS; p++) {
      let p1 = panelPoint(p, u, 330);
      let p2 = panelPoint(p, u, 501);
      brush.line(p1.x, p1.y, p2.x, p2.y);
    }
  }

  // =========================================================================
  // 4. HYPERREALISTIC TENSION WRINKLES & STRESS STRIATIONS
  // =========================================================================
  // A. Tip-pull tension wrinkles: radiating inward from every gilt tip where the nylon
  //    is stretched drum-tight onto the ferrule eye.
  const tipWrinkleSpecs = [
    { uEnd: 0.14, rEnd: 468, sag: 4,  hl: "#ebd5b3", sh: "#2b221b", wt: 0.32 },
    { uEnd: 0.24, rEnd: 484, sag: 6,  hl: "#f5e2c4", sh: "#382c22", wt: 0.36 },
    { uEnd: 0.36, rEnd: 495, sag: 7,  hl: "#dec49e", sh: "#2b221b", wt: 0.28 },
    { uEnd: 0.11, rEnd: 432, sag: 5,  hl: "#b89f80", sh: "#1e1a17", wt: 0.26 },
    { uEnd: 0.19, rEnd: 448, sag: -4, hl: "#9eb4c4", sh: "#1c242e", wt: 0.25 }
  ];

  for (let spec of tipWrinkleSpecs) {
    // Shadow crease
    brush.set("rotring", spec.sh, spec.wt);
    for (let p = 0; p < N_PANELS; p++) {
      // Left tip fan
      let a0 = panelPoint(p, 0.008, 503);
      let a1 = panelPoint(p, spec.uEnd * 0.5, lerp(503, spec.rEnd, 0.5) - spec.sag);
      let a2 = panelPoint(p, spec.uEnd, spec.rEnd);
      brush.spline([[a0.x, a0.y], [a1.x, a1.y], [a2.x, a2.y]], 0.4);

      // Right tip fan (strictly symmetric)
      let b0 = panelPoint(p, 0.992, 503);
      let b1 = panelPoint(p, 1 - spec.uEnd * 0.5, lerp(503, spec.rEnd, 0.5) - spec.sag);
      let b2 = panelPoint(p, 1 - spec.uEnd, spec.rEnd);
      brush.spline([[b0.x, b0.y], [b1.x, b1.y], [b2.x, b2.y]], 0.4);
    }

    // Crisp sunlit ridge highlight offset by 1.2px
    brush.set("rotring", spec.hl, spec.wt * 0.85);
    for (let p = 0; p < N_PANELS; p++) {
      let a0 = panelPoint(p, 0.008, 501.8);
      let a1 = panelPoint(p, spec.uEnd * 0.5, lerp(501.8, spec.rEnd - 1.2, 0.5) - spec.sag);
      let a2 = panelPoint(p, spec.uEnd, spec.rEnd - 1.2);
      brush.spline([[a0.x, a0.y], [a1.x, a1.y], [a2.x, a2.y]], 0.4);

      let b0 = panelPoint(p, 0.992, 501.8);
      let b1 = panelPoint(p, 1 - spec.uEnd * 0.5, lerp(501.8, spec.rEnd - 1.2, 0.5) - spec.sag);
      let b2 = panelPoint(p, 1 - spec.uEnd, spec.rEnd - 1.2);
      brush.spline([[b0.x, b0.y], [b1.x, b1.y], [b2.x, b2.y]], 0.4);
    }
  }

  // B. Catenary hem tension ripples bridging across the outer third of each panel
  const bridgeRipples = [
    { r: 492, u1: 0.18, u2: 0.82, dip: 3.5, hl: "#f2dec0", sh: "#3d3024" },
    { r: 478, u1: 0.22, u2: 0.78, dip: 2.8, hl: "#d9bfa0", sh: "#33281e" },
    { r: 458, u1: 0.28, u2: 0.72, dip: 2.2, hl: "#bfa484", sh: "#29211a" },
    { r: 385, u1: 0.04, u2: 0.26, dip: -3.0, hl: "#8da4b5", sh: "#171f29" },
    { r: 385, u1: 0.74, u2: 0.96, dip: -3.0, hl: "#8da4b5", sh: "#171f29" },
    { r: 242, u1: 0.04, u2: 0.28, dip: -2.5, hl: "#688296", sh: "#0d131c" },
    { r: 242, u1: 0.72, u2: 0.96, dip: -2.5, hl: "#688296", sh: "#0d131c" }
  ];

  for (let br of bridgeRipples) {
    brush.set("rotring", br.sh, 0.28);
    for (let p = 0; p < N_PANELS; p++) {
      let p1 = panelPoint(p, br.u1, br.r);
      let pMid = panelPoint(p, (br.u1 + br.u2) * 0.5, br.r + br.dip);
      let p2 = panelPoint(p, br.u2, br.r);
      brush.spline([[p1.x, p1.y], [pMid.x, pMid.y], [p2.x, p2.y]], 0.45);
    }
    brush.set("rotring", br.hl, 0.24);
    for (let p = 0; p < N_PANELS; p++) {
      let p1 = panelPoint(p, br.u1, br.r - 1.1);
      let pMid = panelPoint(p, (br.u1 + br.u2) * 0.5, br.r + br.dip - 1.1);
      let p2 = panelPoint(p, br.u2, br.r - 1.1);
      brush.spline([[p1.x, p1.y], [pMid.x, pMid.y], [p2.x, p2.y]], 0.45);
    }
  }

  // C. Hub gather pleats radiating out from the central rosette patch (r = 92 to 185)
  for (let k = 1; k <= 5; k++) {
    let u = k / 6;
    let uSkew = u + (u - 0.5) * 0.06;
    brush.set("rotring", "#05070b", 0.35);
    for (let p = 0; p < N_PANELS; p++) {
      let p1 = panelPoint(p, u, 92);
      let p2 = panelPoint(p, uSkew, 175);
      brush.line(p1.x, p1.y, p2.x, p2.y);
    }
    brush.set("rotring", "#4e667a", 0.22);
    for (let p = 0; p < N_PANELS; p++) {
      let p1 = panelPoint(p, u + 0.008, 94);
      let p2 = panelPoint(p, uSkew + 0.008, 172);
      brush.line(p1.x, p1.y, p2.x, p2.y);
    }
  }

  // =========================================================================
  // 5. BLACK HEM BINDING, ROSETTE PATCH & RAZOR-CRISP STITCHING
  // =========================================================================
  // Outer scalloped black nylon bias-tape hem (r = 502 to 513)
  brush.noStroke();
  brush.wash("#0d121a", 250);
  for (let p = 0; p < N_PANELS; p++) {
    let hemPts = getPanelPatch(p, 502, 513, 0, 1, 10);
    drawPolyShape(hemPts, 0);
  }
  brush.noWash();

  // Subtle cool sky-blue edge highlight along the outer rim of the black hem
  brush.set("rotring", "#68869c", 0.4);
  for (let p = 0; p < N_PANELS; p++) {
    let rimPts = [];
    for (let s = 0; s <= 10; s++) {
      let pt = panelPoint(p, s / 10, 512.5);
      rimPts.push([pt.x, pt.y]);
    }
    brush.spline(rimPts, 0.35);
  }

  // Inner edge crease of the hem binding
  brush.set("rotring", "#05070a", 0.45);
  for (let p = 0; p < N_PANELS; p++) {
    let innerHemPts = [];
    for (let s = 0; s <= 10; s++) {
      let pt = panelPoint(p, s / 10, 502);
      innerHemPts.push([pt.x, pt.y]);
    }
    brush.spline(innerHemPts, 0.35);
  }

  // Double row of crisp lockstitches along the scalloped hem (r = 504.5 and r = 509.5)
  const hemStitchRadii = [504.5, 509.5];
  for (let sr of hemStitchRadii) {
    // Dark needle holes / thread trough
    brush.set("rotring", "#040609", 0.32);
    for (let p = 0; p < N_PANELS; p++) {
      for (let s = 1; s < 42; s++) {
        let u1 = (s - 0.28) / 42;
        let u2 = (s + 0.28) / 42;
        let p1 = panelPoint(p, u1, sr);
        let p2 = panelPoint(p, u2, sr);
        brush.line(p1.x, p1.y, p2.x, p2.y);
      }
    }
    // Specular thread glint (cool silver-champagne) on every single stitch
    brush.set("rotring", "#b5c4cf", 0.22);
    for (let p = 0; p < N_PANELS; p++) {
      for (let s = 1; s < 42; s++) {
        let u1 = (s - 0.22) / 42;
        let u2 = (s + 0.22) / 42;
        let p1 = panelPoint(p, u1, sr - 0.5);
        let p2 = panelPoint(p, u2, sr - 0.5);
        brush.line(p1.x, p1.y, p2.x, p2.y);
      }
    }
  }

  // Gore seam stitching flanking both sides of all 12 ribs (from r = 92 to r = 500)
  for (let p = 0; p < N_PANELS; p++) {
    let a = p * STEP_ANG - 90;
    let nx = -sin(a);
    let ny = cos(a);

    // Pucker highlight along the raised seam allowance
    brush.set("2H", "#4d6070", 0.22);
    brush.line(
      CX + 95 * cos(a) + nx * 6.2, CY + 95 * sin(a) + ny * 6.2,
      CX + 498 * cos(a) + nx * 6.2, CY + 498 * sin(a) + ny * 6.2
    );
    brush.line(
      CX + 95 * cos(a) - nx * 6.2, CY + 95 * sin(a) - ny * 6.2,
      CX + 498 * cos(a) - nx * 6.2, CY + 498 * sin(a) - ny * 6.2
    );
  }

  // Individual micro-stitches along both sides of all 12 rib seams
  brush.set("rotring", "#a89882", 0.2);
  for (let p = 0; p < N_PANELS; p++) {
    let a = p * STEP_ANG - 90;
    let ca = cos(a);
    let sa = sin(a);
    let nx = -sa;
    let ny = ca;
    for (let r = 96; r <= 496; r += 7.5) {
      // Left row of stitches
      let xL = CX + r * ca - nx * 4.8;
      let yL = CY + r * sa - ny * 4.8;
      brush.line(xL, yL, xL + 3.2 * ca - 0.6 * nx, yL + 3.2 * sa - 0.6 * ny);

      // Right row of stitches
      let xR = CX + r * ca + nx * 4.8;
      let yR = CY + r * sa + ny * 4.8;
      brush.line(xR, yR, xR + 3.2 * ca + 0.6 * nx, yR + 3.2 * sa + 0.6 * ny);
    }
  }

  // Central 12-scalloped reinforcement rosette patch (r = 94)
  brush.set("rotring", "#283646", 0.35);
  for (let p = 0; p < N_PANELS; p++) {
    let pts = [];
    for (let s = 0; s <= 6; s++) {
      let pt = panelPoint(p, s / 6, 94);
      pts.push([pt.x, pt.y]);
    }
    brush.spline(pts, 0.3);
  }

  // Gold-champagne perimeter stitches on the central rosette patch
  brush.set("rotring", "#d4b872", 0.24);
  for (let p = 0; p < N_PANELS; p++) {
    for (let s = 1; s < 16; s++) {
      let p1 = panelPoint(p, (s - 0.25) / 16, 91.5);
      let p2 = panelPoint(p, (s + 0.25) / 16, 91.5);
      brush.line(p1.x, p1.y, p2.x, p2.y);
    }
  }

  // =========================================================================
  // 6. ART DECO SUNBURST MECHANISM & FINE METALLIC-GOLD HATCHING
  // =========================================================================
  // First: Fine metallic-gold hatching fans that follow the ribs' radial & catenary
  // curves at the hub, mid-strut joints, and outer tip collars (Art Deco sunburst rays)
  for (let p = 0; p < N_PANELS; p++) {
    let a1 = p * STEP_ANG - 90;
    let a2 = (p + 1) * STEP_ANG - 90;
    let aMid = (a1 + a2) * 0.5;

    // 1. Stepped Art Deco sunburst ray fan in each sector (r = 56 to r = 275)
    const rayCount = 14;
    for (let i = 0; i <= rayCount; i++) {
      let u = i / rayCount;
      let distFromCenter = abs(u - 0.5) * 2; // 0 at mid-sector, 1 at ribs
      // Stepped Art Deco architectural length profile
      let stepTier = floor(distFromCenter * 4) / 4;
      let rInner = 56;
      let rOuter = lerp(155, 265, pow(distFromCenter, 1.3)) + (i % 2 === 0 ? 12 : 0);

      let pStart = panelPoint(p, u, rInner);
      let pCtrl = panelPoint(p, lerp(u, u < 0.5 ? 0 : 1, 0.18), (rInner + rOuter) * 0.55);
      let pEnd = panelPoint(p, lerp(u, u < 0.5 ? 0 : 1, 0.35), rOuter);

      let goldCol = i % 3 === 0 ? "#f2dc94" : (i % 2 === 0 ? "#c79f3e" : "#8a681d");
      brush.set("rotring", goldCol, 0.24 + (1 - distFromCenter) * 0.08);
      brush.spline([[pStart.x, pStart.y], [pCtrl.x, pCtrl.y], [pEnd.x, pEnd.y]], 0.35);
    }

    // 2. Curved metallic-gold hatching following each rib's curve from hub to tip
    for (let side of [-1, 1]) {
      for (let h = 1; h <= 4; h++) {
        let uBase = side === 1 ? h * 0.014 : 1 - h * 0.014;
        let uMid  = side === 1 ? h * 0.022 : 1 - h * 0.022;
        let uTip  = side === 1 ? h * 0.009 : 1 - h * 0.009;

        let pt1 = panelPoint(p, uBase, 68);
        let pt2 = panelPoint(p, uMid, 240);
        let pt3 = panelPoint(p, uMid * 0.85 + (side === 1 ? 0 : 0.15), 385);
        let pt4 = panelPoint(p, uTip, 502);

        let hatchCol = h === 1 ? "#fae8a8" : (h === 2 ? "#d4af48" : (h === 3 ? "#9c7623" : "#614712"));
        brush.set("2H", hatchCol, 0.28 - h * 0.04);
        brush.spline([
          [pt1.x, pt1.y],
          [pt2.x, pt2.y],
          [pt3.x, pt3.y],
          [pt4.x, pt4.y]
        ], 0.4);
      }
    }

    // 3. Diagonal Art Deco chevron struts (3 nested gilt V-chevrons per sector)
    const chevronTiers = [
      { rRib: 148, rMid: 108, w: 3.6 },
      { rRib: 196, rMid: 142, w: 4.0 },
      { rRib: 244, rMid: 176, w: 4.5 }
    ];

    for (let tier of chevronTiers) {
      let leftRibPt  = { x: CX + tier.rRib * cos(a1), y: CY + tier.rRib * sin(a1) };
      let midApexPt  = { x: CX + tier.rMid * cos(aMid), y: CY + tier.rMid * sin(aMid) };
      let rightRibPt = { x: CX + tier.rRib * cos(a2), y: CY + tier.rRib * sin(a2) };

      let leftRibIn  = { x: CX + (tier.rRib - tier.w) * cos(a1), y: CY + (tier.rRib - tier.w) * sin(a1) };
      let midApexIn  = { x: CX + (tier.rMid - tier.w * 1.15) * cos(aMid), y: CY + (tier.rMid - tier.w * 1.15) * sin(aMid) };
      let rightRibIn = { x: CX + (tier.rRib - tier.w) * cos(a2), y: CY + (tier.rRib - tier.w) * sin(a2) };

      // Dark cast shadow beneath the chevron strut
      brush.set("rotring", "#04060a", 0.55);
      brush.line(leftRibPt.x + 1.5, leftRibPt.y + 1.5, midApexPt.x + 1.5, midApexPt.y + 1.5);
      brush.line(midApexPt.x + 1.5, midApexPt.y + 1.5, rightRibPt.x + 1.5, rightRibPt.y + 1.5);

      // Gold hatched fill inside the chevron bars
      brush.noStroke();
      brush. wash("#5e4414", 220);
      let leftBar = [leftRibPt, midApexPt, midApexIn, leftRibIn];
      let rightBar = [midApexPt, rightRibPt, rightRibIn, midApexIn];
      drawPolyShape(leftBar, 0);
      drawPolyShape(rightBar, 0);
      brush.noWash();

      brush.hatchStyle("rotring", "#e8c86b", 0.28);
      brush.hatch(2.2, aMid + 90, { rand: 0.02 });
      drawPolyShape(leftBar, 0);
      drawPolyShape(rightBar, 0);
      brush.noHatch();

      // Crisp burnished bronze & bright champagne bevel edges
      brush.set("rotring", "#9e7822", 0.35);
      brush.line(leftRibIn.x, leftRibIn.y, midApexIn.x, midApexIn.y);
      brush.line(midApexIn.x, midApexIn.y, rightRibIn.x, rightRibIn.y);

      brush.set("rotring", "#fff4c2", 0.32);
      brush.line(leftRibPt.x, leftRibPt.y, midApexPt.x, midApexPt.y);
      brush.line(midApexPt.x, midApexPt.y, rightRibPt.x, rightRibPt.y);
    }

    // Central bisector spear in each sector completing the Art Deco sunburst motif
    let spear1 = { x: CX + 58 * cos(aMid), y: CY + 58 * sin(aMid) };
    let spear2 = { x: CX + 204 * cos(aMid), y: CY + 204 * sin(aMid) };
    brush.set("rotring", "#6e5116", 0.55);
    brush.line(spear1.x + 1, spear1.y + 1, spear2.x + 1, spear2.y + 1);
    brush.set("rotring", "#d9b44a", 0.45);
    brush.line(spear1.x, spear1.y, spear2.x, spear2.y);
    brush.set("rotring", "#fff7d1", 0.25);
    brush.line(spear1.x, spear1.y, CX + 185 * cos(aMid), CY + 185 * sin(aMid));

    // Gold diamond jewel at the tip of each sunburst spear (r = 198..214)
    let dTip = { x: CX + 216 * cos(aMid), y: CY + 216 * sin(aMid) };
    let dLeft = { x: CX + 202 * cos(aMid - 1.1), y: CY + 202 * sin(aMid - 1.1) };
    let dBase = { x: CX + 190 * cos(aMid), y: CY + 190 * sin(aMid) };
    let dRight = { x: CX + 202 * cos(aMid + 1.1), y: CY + 202 * sin(aMid + 1.1) };
    brush.noStroke();
    brush.wash("#c9a038", 240);
    drawPolyShape([dTip, dRight, dBase, dLeft], 0);
    brush.noWash();
    brush.set("rotring", "#fff9db", 0.3);
    drawPolyShape([dTip, dRight, dBase, dLeft], 0);
  }

  // =========================================================================
  // 7. THE 12 MAIN GILT RIBS & PROTRUDING GILT TIPS (FERRULES)
  // =========================================================================
  for (let p = 0; p < N_PANELS; p++) {
    let a = p * STEP_ANG - 90;
    let ca = cos(a);
    let sa = sin(a);
    let nx = -sa;
    let ny = ca;

    // 1. Cast shadow of the rib onto the nylon canopy
    brush.set("rotring", "#030508", 0.7);
    brush.line(
      CX + 56 * ca + nx * 2.8, CY + 56 * sa + ny * 2.8,
      CX + 512 * ca + nx * 2.0, CY + 512 * sa + ny * 2.0
    );

    // 2. Sculpted tapered gilt rib polygon (from hub r = 54 to hem r = 513)
    let wHub = 3.4;
    let wMid = 2.6;
    let wHem = 1.8;

    let ribPoly = [
      { x: CX + 54 * ca - nx * wHub,  y: CY + 54 * sa - ny * wHub },
      { x: CX + 260 * ca - nx * wMid, y: CY + 260 * sa - ny * wMid },
      { x: CX + 513 * ca - nx * wHem, y: CY + 513 * sa - ny * wHem },
      { x: CX + 513 * ca + nx * wHem, y: CY + 513 * sa + ny * wHem },
      { x: CX + 260 * ca + nx * wMid, y: CY + 260 * sa + ny * wMid },
      { x: CX + 54 * ca + nx * wHub,  y: CY + 54 * sa + ny * wHub }
    ];

    brush.noStroke();
    brush.wash("#594010", 245);
    drawPolyShape(ribPoly, 0);
    brush.noWash();

    // Fine metallic-gold hatching aligned along the rib axis
    brush.hatchStyle("rotring", "#e0bc58", 0.3);
    brush.hatch(1.6, a, { rand: 0.01 });
    drawPolyShape(ribPoly, 0);
    brush.noHatch();

    // Cross-fluted metallic hatching along the stretcher double-beam (r = 58 to 248)
    let stretcherPoly = [
      { x: CX + 58 * ca - nx * 3.8,  y: CY + 58 * sa - ny * 3.8 },
      { x: CX + 246 * ca - nx * 3.0, y: CY + 246 * sa - ny * 3.0 },
      { x: CX + 246 * ca + nx * 3.0, y: CY + 246 * sa + ny * 3.0 },
      { x: CX + 58 * ca + nx * 3.8,  y: CY + 58 * sa + ny * 3.8 }
    ];
    brush.hatchStyle("rotring", "#f5de8e", 0.25);
    brush.hatch(3.5, a + 65, { rand: 0.01 });
    drawPolyShape(stretcherPoly, 0);
    brush.noHatch();

    // Rib bevel edges: deep antique bronze shadow on one side, burnished gold mid,
    // and razor-sharp white-gold specular glint down the spine
    brush.set("rotring", "#3b2908", 0.42);
    brush.line(
      CX + 54 * ca + nx * wHub, CY + 54 * sa + ny * wHub,
      CX + 513 * ca + nx * wHem, CY + 513 * sa + ny * wHem
    );

    brush.set("rotring", "#b8902e", 0.4);
    brush.line(
      CX + 54 * ca - nx * wHub, CY + 54 * sa - ny * wHub,
      CX + 513 * ca - nx * wHem, CY + 513 * sa - ny * wHem
    );

    brush.set("rotring", "#fff9d6", 0.38);
    brush.line(
      CX + 54 * ca - nx * 0.6, CY + 54 * sa - ny * 0.6,
      CX + 513 * ca - nx * 0.4, CY + 513 * sa - ny * 0.4
    );

    // 3. Mid-rib hinge brackets & gold thread tie-wraps (at r = 148, 196, 244, 385)
    const jointRadii = [148, 196, 244, 385];
    for (let jr of jointRadii) {
      let bw = jr === 385 ? 2.8 : 4.2;
      let bl = jr === 385 ? 5.0 : 7.0;
      let jPoly = [
        { x: CX + (jr - bl) * ca - nx * bw, y: CY + (jr - bl) * sa - ny * bw },
        { x: CX + (jr + bl) * ca - nx * bw, y: CY + (jr + bl) * sa - ny * bw },
        { x: CX + (jr + bl) * ca + nx * bw, y: CY + (jr + bl) * sa + ny * bw },
        { x: CX + (jr - bl) * ca + nx * bw, y: CY + (jr - bl) * sa + ny * bw }
      ];
      brush.noStroke();
      brush.wash("#8c6a1c", 250);
      drawPolyShape(jPoly, 0);
      brush.noWash();

      // Tiny transverse gold thread wraps / collar rings
      for (let d = -bl + 1.2; d <= bl - 1.2; d += 2.2) {
        brush.set("rotring", d < 0 ? "#fff6c4" : "#4a340b", 0.3);
        brush.line(
          CX + (jr + d) * ca - nx * (bw + 0.4), CY + (jr + d) * sa - ny * (bw + 0.4),
          CX + (jr + d) * ca + nx * (bw + 0.4), CY + (jr + d) * sa + ny * (bw + 0.4)
        );
      }
    }

    // 4. GILT-TIPPED FERRULES PROTRUDING PAST THE HEM (r = 510 to R_TIP = 564)
    // Stepped Art Deco brass base collar (r = 510 to 524)
    let collarPoly = [
      { x: CX + 510 * ca - nx * 3.8, y: CY + 510 * sa - ny * 3.8 },
      { x: CX + 524 * ca - nx * 3.2, y: CY + 524 * sa - ny * 3.2 },
      { x: CX + 524 * ca + nx * 3.2, y: CY + 524 * sa + ny * 3.2 },
      { x: CX + 510 * ca + nx * 3.8, y: CY + 510 * sa + ny * 3.8 }
    ];
    brush.noStroke();
    brush.wash("#705316", 250);
    drawPolyShape(collarPoly, 0);
    brush.noWash();

    // Sleek tapered gilt needle tip (r = 524 to 561)
    let tipPoly = [
      { x: CX + 524 * ca - nx * 2.5, y: CY + 524 * sa - ny * 2.5 },
      { x: CX + 559 * ca - nx * 0.9, y: CY + 559 * sa - ny * 0.9 },
      { x: CX + 563 * ca,            y: CY + 563 * sa },
      { x: CX + 559 * ca + nx * 0.9, y: CY + 559 * sa + ny * 0.9 },
      { x: CX + 524 * ca + nx * 2.5, y: CY + 524 * sa + ny * 2.5 }
    ];
    brush.wash("#b8912f", 250);
    drawPolyShape(tipPoly, 0);
    brush.noWash();

    brush.hatchStyle("rotring", "#fa69e", 0.25);
    brush.hatch(1.5, a, { rand: 0 });
    drawPolyShape(tipPoly, 0);
    brush.noHatch();

    // Whipping thread rings securing the hem corner to the gilt tip eyelet (r = 512..522)
    for (let tr = 512; tr <= 523; tr += 1.8) {
      brush.set("rotring", tr % 3.6 < 1.8 ? "#362506" : "#fffae0", 0.32);
      brush.line(
        CX + tr * ca - nx * 3.8, CY + tr * sa - ny * 3.8,
        CX + tr * ca + nx * 3.8, CY + tr * sa + ny * 3.8
      );
    }

    // Crisp dark contour & blazing midday sun highlight on each protruding gilt tip
    brush.set("rotring", "#332307", 0.38);
    brush.line(CX + 510 * ca + nx * 3.6, CY + 510 * sa + ny * 3.6, CX + 561 * ca + nx * 1.0, CY + 561 * sa + ny * 1.0);
    brush.line(CX + 510 * ca - nx * 3.6, CY + 510 * sa - ny * 3.6, CX + 561 * ca - nx * 1.0, CY + 561 * sa - ny * 1.0);

    brush.set("rotring", "#ffffff", 0.45);
    brush.line(CX + 512 * ca - nx * 1.1, CY + 512 * sa - ny * 1.1, CX + 561 * ca - nx * 0.3, CY + 561 * sa - ny * 0.3);

    // Turned brass finial ball at the very end of the tip (r = 562.5)
    brush.noStroke();
    brush.wash("#d4ab42", 255);
    brush.circle(CX + 562.5 * ca, CY + 562.5 * sa, 2.3, 0.05);
    brush.noWash();
    brush.set("rotring", "#ffffff", 0.4);
    brush.circle(CX + 562.5 * ca - 0.6, CY + 562.5 * sa - 0.6, 0.9, 0.02);
  }

  // =========================================================================
  // 8. CENTRAL ART DECO HUB, NOTCH CROWN & AXIAL SHAFT
  // =========================================================================
  // Outer 12-sided gilt sunburst plate (r = 58)
  let outerHubPts = [];
  let midHubPts = [];
  for (let i = 0; i < N_PANELS * 2; i++) {
    let ang = i * (STEP_ANG * 0.5) - 90;
    let rad = i % 2 === 0 ? 60 : 51;
    outerHubPts.push({ x: CX + rad * cos(ang), y: CY + rad * sin(ang) });
    midHubPts.push({ x: CX + (rad - 11) * cos(ang), y: CY + (rad - 11) * sin(ang) });
  }

  brush.noStroke();
  brush.wash("#05070c", 250);
  brush.circle(CX, CY, 63, 0.02);

  brush.wash("#6b4f15", 250);
  drawPolyShape(outerHubPts, 0);
  brush.noWash();

  brush.hatchStyle("rotring", "#f0d072", 0.28);
  brush.hatch(2.0, 45, { rand: 0.02 });
  drawPolyShape(outerHubPts, 0);
  brush.noHatch();

  brush.set("rotring", "#fff7cc", 0.38);
  drawPolyShape(outerHubPts, 0);

  // Dark obsidian recessed ring (r = 43)
  brush.noStroke();
  brush.wash("#090d14", 255);
  drawPolyShape(midHubPts, 0);
  brush.noWash();
  brush.set("rotring", "#c79e3a", 0.35);
  drawPolyShape(midHubPts, 0);

  // 12 radial hinge slots & gold pins around the runner collar (r = 40..54)
  for (let p = 0; p < N_PANELS; p++) {
    let a = p * STEP_ANG - 90;
    let ca = cos(a);
    let sa = sin(a);
    let nx = -sa;
    let ny = ca;

    brush.set("rotring", "#030508", 0.65);
    brush.line(CX + 41 * ca, CY + 41 * sa, CX + 55 * ca, CY + 55 * sa);

    // Transverse brass hinge pin
    brush.set("rotring", "#ff9a", 0.45);
    brush.line(
      CX + 48 * ca - nx * 3.5, CY + 48 * sa - ny * 3.5,
      CX + 48 * ca + nx * 3.5, CY + 48 * sa + ny * 3.5
    );
  }

  // Concentric turned brass & cool gunmetal shaft rings (r = 34 down to 0)
  const hubRings = [
    { r: 34, w: "#8f6b1e", s: "#fae296", wt: 0.4 },
    { r: 28, w: "#101722", s: "#6e889e", wt: 0.32 },
    { r: 21, w: "#b89030", s: "#fff7cc", wt: 0.38 },
    { r: 14, w: "#070b10", s: "#485e70", wt: 0.3 },
    { r: 7,  w: "#d9b448", s: "#ffffff", wt: 0.35 }
  ];

  for (let hr of hubRings) {
    brush.noStroke();
    brush.wash(hr.w, 255);
    brush.circle(CX, CY, hr.r, 0.02);
    brush.noWash();

    brush.set("rotring", hr.s, hr.wt);
    brush.circle(CX, CY, hr.r, 0.02);
  }

  // Specular axial glint across the central shaft jewel
  brush.set("rotring", "#ffffff", 0.45);
  brush.arc(CX, CY, 24, -145, -55);
  brush.arc(CX, CY, 17, 35, 125);
  brush.line(CX - 4, CY - 4, CX + 3, CY + 3);

  // =========================================================================
  // 9. THE SINGLE DROPLET TRAIL (BREAKING THE STRICT RADIAL SYMMETRY)
  //    Placed on Panel 4 (lower-right sector, ~30° to 60° below right horizontal)
  // =========================================================================
  const TRAIL_PANEL = 4;

  // Helper for trail trajectory: starts at (r=162, u=0.38) and glides down-outward
  // to the hero droplet at (r=464, u=0.61)
  function trailPos(t) {
    let r = lerp(162, 464, t);
    let u = lerp(0.38, 0.61, pow(t, 1.15)) + 0.014 * sin(t * 540);
    return panelPoint(TRAIL_PANEL, u, r);
  }

  // A. Darkened wet saturation track on the taut nylon weave
  let trailLeftPts = [];
  let trailRightPts = [];
  let trailCenterPts = [];
  const trailSteps = 32;

  for (let i = 0; i <= trailSteps; i++) {
    let t = i / trailSteps;
    let pt = trailPos(t);
    let halfW = lerp(1.1, 4.4, pow(t, 1.3)) * (1 + 0.18 * sin(t * 900));
    let perpAng = pt.ang + 90;
    trailCenterPts.push([pt.x, pt.y]);
    trailLeftPts.push({
      x: pt.x + halfW * cos(perpAng),
      y: pt.y + halfW * sin(perpAng)
    });
    trailRightPts.unshift({
      x: pt.x - halfW * cos(perpAng),
      y: pt.y - halfW * sin(perpAng)
    });
  }

  let wetTrackPoly = trailLeftPts.concat(trailRightPts);
  brush.noStroke();
  brush.fillBleed(0.06, "in");
  brush.fillTexture(0.3, 0.4);
  brush.fill("#0b1017", 145);
  drawPolyShape(wetTrackPoly, 0.2);
  brush.noFill();

  // Glistening cool sky-blue & bronze wet rim highlights along the damp track
  let leftSpline = trailLeftPts.map(p => [p.x, p.y]);
  let rightSpline = trailRightPts.map(p => [p.x, p.y]);

  brush.set("rotring", "#05080c", 0.3);
  brush.spline(rightSpline, 0.35);

  brush.set("rotring", "#a4cde0", 0.28);
  brush.spline(leftSpline, 0.35);

  brush.set("rotring", "#f5e3c2", 0.22);
  brush.spline(trailCenterPts, 0.35);

  // B. Trailing residual micro-beads along the wet path
  const microBeads = [
    { t: 0.06, rad: 1.5, uOff:  0.0 },
    { t: 0.13, rad: 2.1, uOff: -0.5 },
    { t: 0.19, rad: 1.3, uOff:  0.8 },
    { t: 0.27, rad: 2.8, uOff:  0.0 },
    { t: 0.35, rad: 1.7, uOff: -0.6 },
    { t: 0.43, rad: 3.3, uOff:  0.2 },
    { t: 0.50, rad: 1.6, uOff:  1.1 },
    { t: 0.58, rad: 3.8, uOff: -0.3 },
    { t: 0.66, rad: 2.0, uOff:  0.5 },
    { t: 0.74, rad: 4.3, uOff:  0.0 },
    { t: 0.81, rad: 2.4, uOff: -0.9 },
    { t: 0.88, rad: 5.0, uOff:  0.1 },
    { t: 0.93, rad: 2.2, uOff:  0.7 }
  ];

  for (let mb of microBeads) {
    let pt = trailPos(mb.t);
    let perpAng = pt.ang + 90;
    let bx = pt.x + mb.uOff * cos(perpAng);
    let by = pt.y + mb.uOff * sin(perpAng);
    let r = mb.rad;

    // Cast shadow on the down-slope side
    brush.noStroke();
    brush.wash("#05080d", 230);
    brush.circle(bx + r * 0.32 * cos(pt.ang), by + r * 0.32 * sin(pt.ang), r * 1.05, 0.05);

    // Dark refracted upper hemisphere (reflecting the dark inner hub)
    brush.wash("#0f1824", 240);
    brush.circle(bx, by, r, 0.04);

    // Luminous lower caustic crescent (cool sky cyan + warm smoky bronze)
    let causticCol = mb.t > 0.5 ? "#e8cfa6" : "#8ec0d8";
    brush.wash(causticCol, 220);
    brush.circle(
      bx + r * 0.25 * cos(pt.ang),
      by + r * 0.25 * sin(pt.ang),
      r * 0.68,
      0.04
    );
    brush.noWash();

    // Crisp rim & pinpoint white specular glint
    brush.set("rotring", "#d4eefc", 0.25);
    brush.arc(bx, by, r * 0.92, pt.ang - 40, pt.ang + 85);

    brush.set("rotring", "#ffffff", 0.5);
    let gx = bx - r * 0.35 * cos(pt.ang - 25);
    let gy = by - r * 0.35 * sin(pt.ang - 25);
    brush.line(gx, gy, gx + 0.8, gy + 0.8);
  }

  // C. THE HERO WATER DROPLET (at t = 1.0, r = 464, plump teardrop lens)
  let heroPt = trailPos(1.0);
  let hAng = heroPt.ang; // Direction of gravity / radial slope (~48 degrees)
  let hCa = cos(hAng);
  let hSa = sin(hAng);
  let hNx = -hSa;
  let hNy = hCa;

  // Build an organic, surface-tension teardrop contour (length ~ 28px, width ~ 18px)
  function getTeardropPts(cx, cy, lenScale, widScale, rotAng) {
    let c = cos(rotAng);
    let s = sin(rotAng);
    let nx = -s;
    let ny = c;
    let pts = [];
    const N = 24;
    for (let i = 0; i < N; i++) {
      let a = (i / N) * 360;
      // Parametric teardrop: pinched trailing tail at a = 180, plump rounded head at a = 0
      let along = cos(a); // -1 (tail) to +1 (head)
      let across = sin(a) * (0.68 + 0.32 * cos(a * 0.5)) * (along < 0 ? pow(1 + along, 0.35) * 0.85 + 0.15 : 1.0);
      let lx = along * lenScale + (along < 0 ? along * lenScale * 0.25 : 0);
      let ly = across * widScale;
      pts.push({
        x: cx + lx * c + ly * nx,
        y: cy + lx * s + ly * ny
      });
    }
    return pts;
  }

  // 1. Deep contact shadow and refracted caustic halo beneath the hero droplet
  let shadowPts = getTeardropPts(
    heroPt.x + 3.8 * hCa + 1.2 * hNx,
    heroPt.y + 3.8 * hSa + 1.2 * hNy,
    13.5, 9.2, hAng
  );
  brush.noStroke();
  brush.wash("#04060a", 235);
  drawPolyShape(shadowPts, 0.2);

  // Focused bright golden-amber caustic lens spot projected onto the nylon just ahead of the droplet
  let causticSpotPts = getTeardropPts(
    heroPt.x + 5.2 * hCa + 0.8 * hNx,
    heroPt.y + 5.2 * hSa + 0.8 * hNy,
    7.5, 5.5, hAng
  );
  brush.wash("#f7dfb2", 210);
  drawPolyShape(causticSpotPts, 0.25);

  // 2. Main droplet body (deep obsidian-indigo upper core)
  let dropBodyPts = getTeardropPts(heroPt.x, heroPt.y, 13.0, 8.8, hAng);
  brush.wash("#0b131e", 248);
  drawPolyShape(dropBodyPts, 0.2);

  // 3. Internal cool cerulean sky refraction (middle crescent)
  let cyanRefractPts = getTeardropPts(
    heroPt.x + 2.2 * hCa - 0.8 * hNx,
    heroPt.y + 2.2 * hSa - 0.8 * hNy,
    9.2, 6.6, hAng
  );
  brush.wash("#4f8db0", 215);
  drawPolyShape(cyanRefractPts, 0.2);

  let iceRefractPts = getTeardropPts(
    heroPt.x + 3.8 * hCa - 0.5 * hNx,
    heroPt.y + 3.8 * hSa - 0.5 * hNy,
    6.8, 5.0, hAng
  );
  brush.wash("#a8e0fa", 225);
  drawPolyShape(iceRefractPts, 0.2);

  // 4. Warm gilt & smoky-bronze internal base reflection (lower belly of the droplet)
  let goldRefractPts = getTeardropPts(
    heroPt.x + 5.5 * hCa + 0.6 * hNx,
    heroPt.y + 5.5 * hSa + 0.6 * hNy,
    4.6, 3.8, hAng
  );
  brush.wash("#fae09e", 230);
  drawPolyShape(goldRefractPts, 0.2);
  brush.noWash();

  // 5. Crisp glass-like outline and internal meniscus shading
  brush.set("rotring", "#04070c", 0.42);
  drawPolyShape(dropBodyPts, 0.2);

  // Reflected gilt rib curve warped inside the droplet's right flank
  brush.set("rotring", "#f5cf6e", 0.35);
  brush.arc(heroPt.x + 1.5 * hCa, heroPt.y + 1.5 * hSa, 6.8, hAng + 15, hAng + 95);

  // Cool sky-blue Fresnel rim light along the leading edge
  brush.set("rotring", "#d9f4ff", 0.38);
  brush.arc(heroPt.x + 2.8 * hCa, heroPt.y + 2.8 * hSa, 7.6, hAng - 75, hAng + 65);

  // 6. Blazing pure-white primary & secondary specular glints on the upper dome
  let glint1X = heroPt.x - 3.2 * hCa - 2.6 * hNx;
  let glint1Y = heroPt.y - 3.2 * hSa - 2.6 * hNy;
  brush.noStroke();
  brush.wash("#ffffff", 255);
  let glintPoly = getTeardropPts(glint1X, glint1Y, 3.6, 1.7, hAng - 18);
  drawPolyShape(glintPoly, 0.2);
  brush.noWash();

  brush.set("rotring", "#ffffff", 0.55);
  brush.line(
    glint1X - 2.2 * hCa, glint1Y - 2.2 * hSa,
    glint1X + 2.2 * hCa, glint1Y + 2.2 * hSa
  );

  // Secondary pinpoint highlight near the trailing tail of the droplet
  let glint2X = heroPt.x - 8.2 * hCa - 1.1 * hNx;
  let glint2Y = heroPt.y - 8.2 * hSa - 1.1 * hNy;
  brush.set("rotring", "#ffffff", 0.5);
  brush.circle(glint2X, glint2Y, 1.1, 0.02);

  noLoop();
}

// Hyperrealism in p5.brush:
// Hand-thrown Stoneware Tea Bowl (Chawan) on a Rough Cedar Plank

const CX = 530;
const RIM_Y = 430;
const BOWL_H = 305;
const FOOT_H = 38;

// 3D Surface & Illumination helpers for the hand-thrown tea bowl
function rimUndulation(theta) {
  // Natural mountain-path rim (yama-michi)
  return (
    -10 * sin(theta * 2 - 25) +
    6.5 * cos(theta * 3 + 35) -
    3.5 * sin(theta * 5 - 10)
  );
}

function thumbDentDisplacement(v, theta) {
  // Primary thumb dent on front-left hip (te-bineri)
  let d1v = (v - 0.57) / 0.13;
  let d1t = (theta - 115) / 14;
  let dist1 = d1v * d1v + d1t * d1t;
  let dent1 = dist1 < 1.0 ? -15.5 * Math.pow(1.0 - dist1, 1.8) : 0;

  // Secondary finger impression on front-right belly
  let d2v = (v - 0.47) / 0.14;
  let d2t = (theta - 55) / 16;
  let dist2 = d2v * d2v + d2t * d2t;
  let dent2 = dist2 < 1.0 ? -11.0 * Math.pow(1.0 - dist2, 1.7) : 0;

  // Subtle palm swell near upper left
  let d3v = (v - 0.30) / 0.18;
  let d3t = (theta - 140) / 22;
  let dist3 = d3v * d3v + d3t * d3t;
  let swell = dist3 < 1.0 ? 5.5 * Math.pow(1.0 - dist3, 1.5) : 0;

  return dent1 + dent2 + swell;
}

function throwingRingWave(v, theta) {
  // Spiral wheel-throwing ridges (rokuro-me)
  let spiralPhase = v * 360 * 8.5 + (theta / 360) * 360;
  let amp = 2.4 * sin(v * 180) * (1 - 0.25 * cos(theta * 2));
  // Flatten throwing rings slightly inside the thumb dents
  let dentFactor = 1.0 - Math.min(1.0, Math.abs(thumbDentDisplacement(v, theta)) / 12.0);
  return amp * sin(spiralPhase) * (0.35 + 0.65 * dentFactor);
}

function getBaseRadius(v) {
  // Profile from rim (v=0) through full belly (v=0.35), strong hip/koshi (v=0.78), to foot (v=1.0)
  if (v < 0.74) {
    let t = v / 0.74;
    return (
      276 +
      14 * sin(t * 145) -
      34 * Math.pow(t, 2.2)
    );
  } else {
    // Sharp inward turn at the hip (koshi) toward the kodai foot
    let t = (v - 0.74) / 0.26;
    let hipR = 276 + 14 * sin(145) - 34; // ~250
    let footTopR = 114;
    // Smooth curve into the foot
    return lerp(hipR, footTopR, Math.pow(t, 1.45));
  }
}

function getBaseY(v) {
  if (v < 0.74) {
    let t = v / 0.74;
    return RIM_Y + t * (BOWL_H * 0.77);
  } else {
    let t = (v - 0.74) / 0.26;
    return RIM_Y + BOWL_H * 0.77 + Math.pow(t, 0.88) * (BOWL_H * 0.23);
  }
}

function getBowlPoint(v, theta) {
  let baseR = getBaseRadius(v);
  let asymR = 5.5 * cos(theta * 2 - 40) - 3.5 * sin(theta * 3 + 15);
  let dent = thumbDentDisplacement(v, theta);
  let ring = throwingRingWave(v, theta);
  let r = baseR + asymR * (1 - v * 0.6) + dent + ring;

  // Perspective ellipse ratio increases slightly toward base
  let perspRatio = 0.315 + v * 0.045;
  let yRimOffset = rimUndulation(theta) * Math.pow(1 - v, 1.4);
  let dentY = dent * 0.22;

  let x = CX + r * cos(theta);
  let y = getBaseY(v) + r * perspRatio * sin(theta) + yRimOffset + dentY;
  return [x, y, r];
}

function getInteriorPoint(u, theta) {
  // u = 0 at rim, u = 1 at bottom of visible interior well
  let rRim = 264 + 5.5 * cos(theta * 2 - 40) - 3.5 * sin(theta * 3 + 15);
  let r = rRim * (1 - Math.pow(u, 1.15) * 0.78);
  let ring = 1.8 * sin(u * 360 * 6.5 + theta) * (1 - u * 0.5);
  r += ring;

  let perspRatio = 0.315 + u * 0.05;
  let yCenter = RIM_Y + 4 + Math.pow(u, 0.92) * 142;
  let yRimOffset = rimUndulation(theta) * Math.pow(1 - u, 1.5);

  let x = CX + r * cos(theta);
  let y = yCenter + r * perspRatio * sin(theta) + yRimOffset;
  return [x, y];
}

function getFootPoint(w, theta) {
  // w = 0 at top of kodai foot collar, w = 1 at bottom resting on cedar plank
  let rTop = 114;
  let rBot = 107;
  let r = lerp(rTop, rBot, w) + 2.0 * cos(theta * 3 + 20);
  let yTop = RIM_Y + BOWL_H - 3;
  let y = yTop + w * FOOT_H + r * 0.35 * sin(theta);
  let x = CX + r * cos(theta);
  return [x, y];
}

function getGlazeBoundaryV(theta) {
  // Natural ash glaze line around the lower belly/hip with organic runs and drips
  let baseV = 0.67 + 0.05 * sin(theta * 2.2 - 30) + 0.04 * cos(theta * 3.7 + 10);

  // Specific glaze runs that feed into glassy olive drips near the foot
  let drips = [
    { t: 152, width: 9, len: 0.17 },
    { t: 124, width: 11, len: 0.22 }, // fed by left thumb dent
    { t: 97, width: 8.5, len: 0.20 },
    { t: 74, width: 7, len: 0.08 },   // lifts above the kiln-grit pock!
    { t: 54, width: 12, len: 0.24 },  // major olive drip under right finger dent
    { t: 31, width: 8, len: 0.16 }
  ];

  let extra = 0;
  for (let d of drips) {
    let dt = (theta - d.t) / d.width;
    if (Math.abs(dt) < 1.0) {
      let profile = Math.pow(1.0 - dt * dt, 2.2);
      if (d.t === 74) {
        // Recedes slightly around theta=74 to expose the kiln-grit pock clearly
        extra -= 0.07 * profile;
      } else {
        extra += d.len * profile;
      }
    }
  }
  return constrain(baseV + extra, 0.56, 0.94);
}

// Helper to draw field-aware closed or open polygons safely without brush.polygon()
function drawPoly(pts, curvature = 0.25, close = true) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(close);
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(7482);
  noiseSeed(7482);

  // Custom fine needle brush for glaze crackle and crystalline highlights
  brush.add("glaze_needle", {
    type: "default",
    weight: 0.35,
    scatter: 0.02,
    sharpness: 0.92,
    grain: 8,
    opacity: 210,
    spacing: 0.12,
    pressure: [0.6, 1.2, 0.4],
    rotate: "natural",
    noise: 0.25
  });

  // Custom flat bristle for rough cedar wood grain
  brush.add("cedar_bristle", {
    type: "default",
    weight: 1.6,
    scatter: 0.45,
    sharpness: 0.65,
    grain: 28,
    opacity: 140,
    spacing: 0.22,
    pressure: [0.3, 1.1, 0.3],
    rotate: "natural",
    noise: 0.7
  });
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f3ede2");

  // 1. WINTER PAPER WINDOW LIGHT & WARM GREY EDGE ATMOSPHERE
  drawBackgroundAtmosphere();

  // 2. ROUGH CEDAR PLANK (Vivid heartwood fading to loose warm grey at edges)
  drawCedarPlank();

  // 3. WINTER SHADOW & GLAZE BOUNCE LIGHT ON THE PLANK
  drawBowlCastShadow();

  // 4. INTERIOR OF THE TEA BOWL (Celadon, Olive & Persimmon Washes + Throwing Rings)
  drawBowlInterior();

  // 5. EXTERIOR RAW STONEWARE CLAY & FOOT RING (Charcoal Mass + Persimmon/Umber Washes)
  drawBowlRawClayAndFoot();

  // 6. EXTERIOR NATURAL ASH GLAZE & GLASSY OLIVE DRIPS
  drawExteriorAshGlaze();

  // 7. THROWING RINGS, THUMB DENTS, KILN-GRIT POCK & HAIRLINE CRACKLE
  drawExteriorThrowingRingsAndDents();
  drawGlassyOliveDrips();
  drawKilnGritPock();
  drawHairlineCrackleAndRim();

  // 8. FINAL WINTER LIGHT GLAZING & FOREGROUND CEDAR SPLINTERS
  drawFinalHighlightsAndAtmosphere();

  noLoop();
}

// =============================================================================
// 1. BACKGROUND ATMOSPHERE & PAPER WINDOW LIGHT
// =============================================================================
function drawBackgroundAtmosphere() {
  brush.noStroke();

  // Warm grey washes at the outer margins (top-right, right, bottom, far-left)
  brush.fillBleed(0.42, "out");
  brush.fillTexture(0.75, 0.32);

  // Upper right & right edge cool-warm winter grey
  brush.fill("#8c8a84", 58);
  drawPoly([
    [520, -20], [1220, -20], [1220, 560],
    [980, 510], [740, 380], [560, 180]
  ], 0.35);

  brush.fill("#74787a", 52);
  drawPoly([
    [780, -20], [1220, -20], [1220, 680],
    [1040, 580], [880, 340]
  ], 0.35);

  // Lower margin loose warm grey fade
  brush.fill("#87827b", 64);
  drawPoly([
    [-20, 920], [320, 970], [760, 950], [1220, 880],
    [1220, 1220], [-20, 1220]
  ], 0.3);

  brush.fill("#6d6b68", 55);
  drawPoly([
    [-20, 1030], [480, 1050], [920, 1010], [1220, 960],
    [1220, 1220], [-20, 1220]
  ], 0.3);

  // Left margin soft warm grey vignette below the window light beam
  brush.fill("#948f88", 48);
  drawPoly([
    [-20, 380], [190, 460], [160, 980], [-20, 1050]
  ], 0.35);

  // Pale wintry light beam from paper shoji window (top-left)
  brush.fillBleed(0.3, "out");
  brush.fillTexture(0.45, 0.15);
  brush.fill("#fafcfb", 85);
  drawPoly([
    [-20, -20], [640, -20], [820, 390], [280, 490], [-20, 390]
  ], 0.3);

  // Subtle cool winter sky tint in the upper window glow
  brush.fill("#dce9ed", 55);
  drawPoly([
    [-20, -20], [480, -20], [620, 290], [180, 380], [-20, 260]
  ], 0.35);

  // Faint shoji paper mullion shadow bands in the upper background
  brush.fill("#9c9891", 28);
  drawPoly([
    [180, -10], [215, -10], [430, 390], [390, 400]
  ], 0.15);
  drawPoly([
    [-10, 155], [560, 85], [575, 112], [-10, 185]
  ], 0.15);

  brush.noFill();
}

// =============================================================================
// 2. ROUGH CEDAR PLANK (Sugi Wood)
// =============================================================================
function drawCedarPlank() {
  // Plank top horizon runs from (0, 505) to (1200, 445)
  // Front split edge runs around (0, 1010) to (1200, 935)
  brush.noStroke();

  // Outer plank fades into loose warm grey at left and right edges
  brush.fillBleed(0.38, "out");
  brush.fillTexture(0.72, 0.38);

  // Left edge warm grey fade on plank
  brush.fill("#858079", 72);
  drawPoly([
    [-20, 505], [310, 488], [260, 995], [-20, 1020]
  ], 0.25);

  // Right edge warm grey fade on plank
  brush.fill("#7f7c78", 76);
  drawPoly([
    [820, 462], [1220, 442], [1220, 950], [790, 970]
  ], 0.25);

  // Vivid, saturated cedar heartwood & raw umber washes in the central zone around the bowl
  brush.fillBleed(0.32, "out");
  brush.fillTexture(0.78, 0.45);

  // Warm golden-ochre sapwood base
  brush.fill("#c97b38", 68);
  drawPoly([
    [130, 495], [960, 455], [920, 945], [110, 990]
  ], 0.3);

  // Vivid burnt persimmon-cedar heartwood band running through the center
  brush.fill("#b5471f", 78);
  drawPoly([
    [190, 560], [890, 515], [870, 845], [160, 895]
  ], 0.3);

  // Deeper raw umber & roasted sienna wood grain bands
  brush.fill("#6e3316", 72);
  drawPoly([
    [230, 620], [830, 580], [810, 790], [210, 835]
  ], 0.3);

  // Saturated terracotta/persimmon glow just in front of and left of the bowl
  brush.fill("#d45826", 65);
  drawPoly([
    [220, 680], [640, 665], [610, 880], [190, 900]
  ], 0.35);

  // Front rough split thickness of the cedar plank
  brush.fill("#4a2d1b", 82);
  drawPoly([
    [150, 965], [930, 920], [910, 975], [140, 1015]
  ], 0.2);

  brush.fill("#66625e", 75);
  drawPoly([
    [-20, 985], [260, 968], [250, 1030], [-20, 1045]
  ], 0.2);
  drawPoly([
    [820, 925], [1220, 902], [1220, 968], [810, 985]
  ], 0.2);

  brush.noFill();

  // Dry charcoal & cpencil mass for rough wood relief in the center plank
  brush.mass("charcoal", "#4d2612", { precision: 0.45, strength: 0.45, gradient: 0.6, outline: false });
  drawPoly([
    [250, 690], [790, 660], [770, 815], [230, 845]
  ], 0.2);

  brush.mass("charcoal", "#2b1910", { precision: 0.5, strength: 0.55, gradient: 0.5, outline: false });
  drawPoly([
    [240, 958], [820, 922], [810, 965], [230, 995]
  ], 0.15);
  brush.noMass();

  // Detailed cedar wood grain lines, cathedral arches, and a knot at (265, 805)
  let knotX = 265;
  let knotY = 805;

  for (let i = 0; i < 92; i++) {
    let t = i / 91;
    let baseY = lerp(492, 968, t);

    // Determine horizontal span: full width for middle lines, looser/broken at edges
    let xStart = random(15, 160);
    let xEnd = random(1040, 1185);

    // Split each grain line into segments so the center is vivid umber/sienna and edges are warm grey
    let numSegs = 3;
    for (let s = 0; s < numSegs; s++) {
      let sx0 = lerp(xStart, xEnd, s / numSegs);
      let sx1 = lerp(xStart, xEnd, (s + 1) / numSegs);

      let pts = [];
      let steps = 12;
      for (let k = 0; k <= steps; k++) {
        let px = lerp(sx0, sx1, k / steps);
        let slopeY = baseY - (px - 600) * 0.052;

        // Deflect grain around the cedar knot at (knotX, knotY)
        let dx = (px - knotX) / 95;
        let dy = (slopeY - knotY) / 42;
        let d2 = dx * dx + dy * dy;
        let knotShift = 0;
        if (d2 < 2.2) {
          knotShift = (dy >= 0 ? 1 : -1) * 24 * Math.exp(-d2 * 1.35);
        }

        // Cathedral arch modulation in the central heartwood
        let arch = 9 * sin((px - 480) * 0.65 + t * 180) * sin(t * 180);
        let n = (noise(px * 0.008, t * 6.0) - 0.5) * 10;

        pts.push([px, slopeY + knotShift + arch + n]);
      }

      // Color & brush choice: warm grey at left/right edges, rich umber/sienna in center
      if (s === 1) {
        let col = i % 3 === 0 ? "#3b1b0c" : (i % 3 === 1 ? "#753215" : "#9c471f");
        let br = i % 4 === 0 ? "charcoal" : "cedar_bristle";
        brush.set(br, col, random(0.45, 1.05));
        brush.spline(pts, 0.35);

        // Raised winter light highlight just above every 4th ridge
        if (i % 4 === 0) {
          let hiPts = pts.map(p => [p[0], p[1] - 2.2]);
          brush.set("cpencil", "#edd8be", random(0.4, 0.75));
          brush.spline(hiPts, 0.35);
        }
      } else {
        // Loose warm grey grain fading at the outer plank edges
        if (random() < 0.72) {
          let edgeCol = s === 0 ? "#78736d" : "#6e6c68";
          brush.set(i % 2 === 0 ? "2B" : "cpencil", edgeCol, random(0.35, 0.8));
          brush.spline(pts, 0.35);
        }
      }
    }
  }

  // Render the weathered cedar knot at (knotX, knotY)
  brush.noStroke();
  brush.fillBleed(0.18, "in");
  brush.fill("#2b1207", 150);
  drawPoly([
    [knotX - 32, knotY + 2], [knotX - 12, knotY - 14],
    [knotX + 28, knotY - 8], [knotX + 36, knotY + 4],
    [knotX + 14, knotY + 16], [knotX - 20, knotY + 12]
  ], 0.35);
  brush.noFill();

  for (let r = 6; r <= 34; r += 5) {
    let kPts = [];
    for (let a = 0; a <= 360; a += 30) {
      let kx = knotX + r * 1.35 * cos(a);
      let ky = knotY + r * 0.52 * sin(a) - (kx - knotX) * 0.05;
      kPts.push([kx, ky]);
    }
    brush.set("charcoal", r < 18 ? "#1c0a03" : "#4d220e", 0.65);
    drawPoly(kPts, 0.4, true);
  }
  // Tiny shrinkage check crack inside the knot
  brush.set("rotring", "#120602", 0.55);
  brush.line(knotX - 22, knotY + 2, knotX + 24, knotY - 1);
  brush.set("cpencil", "#e8ccb0", 0.5);
  brush.line(knotX - 18, knotY + 4, knotX + 18, knotY + 1);

  // Deep split checks along the front edge of the cedar plank
  for (let c = 0; c < 14; c++) {
    let cx0 = random(80, 1080);
    let cy0 = 965 - (cx0 - 600) * 0.052 + random(-12, 18);
    brush.set("charcoal", "#24130a", random(0.6, 1.2));
    brush.line(cx0, cy0, cx0 + random(40, 130), cy0 - random(2, 8));
  }
}

// =============================================================================
// 3. BOWL CAST SHADOW & GLAZE BOUNCE LIGHT ON THE PLANK
// =============================================================================
function drawBowlCastShadow() {
  // Low winter light from upper-left casts a long soft shadow to the right/lower-right
  brush.noStroke();
  brush.fillBleed(0.36, "out");
  brush.fillTexture(0.68, 0.35);

  // Outer cool-umber winter shadow penumbra stretching right
  let shadowOuter = [];
  for (let a = 0; a < 360; a += 15) {
    let rx = 310 * cos(a);
    let ry = 108 * sin(a);
    shadowOuter.push([CX + 235 + rx, 755 + ry - rx * 0.04]);
  }
  brush.fill("#4a4946", 95);
  drawPoly(shadowOuter, 0.35);

  // Mid shadow layer (rich raw umber + slate)
  let shadowMid = [];
  for (let a = 0; a < 360; a += 15) {
    let rx = 225 * cos(a);
    let ry = 82 * sin(a);
    shadowMid.push([CX + 160 + rx, 758 + ry - rx * 0.03]);
  }
  brush.fill("#33241b", 125);
  drawPoly(shadowMid, 0.35);

  // Warm persimmon & olive-celadon bounce light reflected from the glossy bowl onto the plank
  brush.fillBleed(0.28, "out");
  brush.fill("#73873b", 65);
  drawPoly([
    [CX + 55, 725], [CX + 235, 710], [CX + 255, 775], [CX + 65, 790]
  ], 0.35);

  brush.fill("#b84e22", 62);
  drawPoly([
    [CX - 40, 755], [CX + 145, 750], [CX + 165, 810], [CX - 25, 805]
  ], 0.35);

  // Deepest ambient occlusion shadow directly beneath the kodai foot ring and overhanging hip
  let shadowCore = [];
  for (let a = 0; a < 360; a += 15) {
    let rx = 145 * cos(a);
    let ry = 50 * sin(a);
    shadowCore.push([CX + 32 + rx, 762 + ry]);
  }
  brush.fill("#170d07", 185);
  drawPoly(shadowCore, 0.35);
  brush.noFill();

  // Charcoal mass in the core shadow so wood grain and shadow fuse organically
  brush.mass("charcoal", "#1a0f09", { precision: 0.55, strength: 0.68, gradient: 0.45, outline: false });
  drawPoly(shadowCore, 0.3);
  brush.noMass();

  // Re-establish a few crisp dark wood grain crevices running through the cast shadow
  for (let i = 0; i < 16; i++) {
    let sy = lerp(705, 825, i / 15);
    let sx0 = CX + 10 + random(-20, 30);
    let sx1 = sx0 + random(160, 340);
    brush.set("charcoal", "#140b06", random(0.45, 0.85));
    brush.line(sx0, sy, sx1, sy - (sx1 - sx0) * 0.05);
  }
}

// =============================================================================
// 4. INTERIOR OF THE TEA BOWL (Celadon, Olive & Persimmon Washes + Rings)
// =============================================================================
function drawBowlInterior() {
  // Build full interior boundary polygon
  let rimLoop = [];
  for (let a = 0; a < 360; a += 6) {
    rimLoop.push(getInteriorPoint(0.0, a));
  }

  brush.noStroke();
  brush.fillBleed(0.24, "in");
  brush.fillTexture(0.72, 0.42);

  // Base warm stoneware/umber interior under-wash
  brush.fill("#6e3d21", 145);
  drawPoly(rimLoop, 0.3);

  // Lit right/back-right interior wall: vivid celadon wash catching the winter window light
  let rightLitWall = [];
  for (let a = 245; a <= 395; a += 8) rightLitWall.push(getInteriorPoint(0.02, a % 360));
  for (let a = 395; a >= 245; a -= 8) rightLitWall.push(getInteriorPoint(0.88, a % 360));
  brush.fill("#66b59b", 145);
  drawPoly(rightLitWall, 0.3);

  // Second luminous celadon-sky bloom on the far right interior wall
  let rightBright = [];
  for (let a = 280; a <= 375; a += 8) rightBright.push(getInteriorPoint(0.08, a % 360));
  for (let a = 375; a >= 280; a -= 8) rightBright.push(getInteriorPoint(0.68, a % 360));
  brush.fill("#9be0cb", 125);
  drawPoly(rightBright, 0.3);

  // Vivid persimmon & amber-ochre bloom where glaze thins on the upper back-center interior
  let backPersimmon = [];
  for (let a = 215; a <= 300; a += 8) backPersimmon.push(getInteriorPoint(0.03, a));
  for (let a = 300; a >= 215; a -= 8) backPersimmon.push(getInteriorPoint(0.55, a));
  brush.fill("#d45c26", 110);
  drawPoly(backPersimmon, 0.3);

  // Shaded left interior wall (away from window light): deep olive-celadon & raw umber
  let leftShadeWall = [];
  for (let a = 115; a <= 250; a += 8) leftShadeWall.push(getInteriorPoint(0.02, a));
  for (let a = 250; a >= 115; a -= 8) leftShadeWall.push(getInteriorPoint(0.92, a));
  brush.fill("#2d4732", 160);
  drawPoly(leftShadeWall, 0.3);

  // Deep olive-jade pool in the lower interior well (chadamari)
  let teaWell = [];
  for (let a = 160; a <= 380; a += 10) teaWell.push(getInteriorPoint(0.52, a % 360));
  for (let a = 380; a >= 160; a -= 10) teaWell.push(getInteriorPoint(0.96, a % 360));
  brush.fill("#3c5c18", 165);
  drawPoly(teaWell, 0.3);

  brush.noFill();

  // Soft charcoal mass inside the left interior shadow wall for deep 3D concavity
  let leftCoreShade = [];
  for (let a = 140; a <= 230; a += 10) leftCoreShade.push(getInteriorPoint(0.08, a));
  for (let a = 230; a >= 140; a -= 10) leftCoreShade.push(getInteriorPoint(0.82, a));
  brush.mass("charcoal", "#1b291d", { precision: 0.6, strength: 0.55, gradient: 0.5, outline: false });
  drawPoly(leftCoreShade, 0.25);
  brush.noMass();

  // Interior throwing rings (rokuro-me) visible across the back wall (theta 150..390)
  for (let r = 1; r <= 14; r++) {
    let u = r / 15.0;
    // Left shaded arc of throwing ring
    let ptsShade = [];
    for (let a = 145; a <= 255; a += 6) {
      ptsShade.push(getInteriorPoint(u, a));
    }
    brush.set(r % 2 === 0 ? "charcoal" : "2B", "#1d2e20", random(0.45, 0.85));
    brush.spline(ptsShade, 0.35);

    // Warm persimmon/umber ridge showing through thin glaze on mid-back wall
    if (r % 2 === 1) {
      let ptsWarm = [];
      for (let a = 225; a <= 325; a += 6) {
        ptsWarm.push(getInteriorPoint(u - 0.015, a));
      }
      brush.set("cpencil", "#b54b20", random(0.45, 0.8));
      brush.spline(ptsWarm, 0.35);
    }

    // Lit right arc of throwing ring (olive-celadon groove + bright winter reflection)
    let ptsLit = [];
    for (let a = 250; a <= 390; a += 6) {
      ptsLit.push(getInteriorPoint(u, a % 360));
    }
    brush.set("cpencil", r % 2 === 0 ? "#386652" : "#567824", random(0.5, 0.9));
    brush.spline(ptsLit, 0.35);

    if (r % 2 === 0 && r < 12) {
      let ptsHi = [];
      for (let a = 285; a <= 365; a += 6) {
        let p = getInteriorPoint(u - 0.012, a % 360);
        ptsHi.push([p[0], p[1] - 1.2]);
      }
      brush.set("glaze_needle", "#e8faf5", random(0.6, 1.1));
      brush.spline(ptsHi, 0.35);
    }
  }

  // Interior ash glaze vertical flow tracks descending into the well
  for (let f = 0; f < 18; f++) {
    let a = random(175, 365);
    let flowPts = [];
    let uStart = random(0.03, 0.2);
    let uEnd = random(0.55, 0.9);
    for (let s = 0; s <= 8; s++) {
      let u = lerp(uStart, uEnd, s / 8);
      let angleShift = a + sin(u * 180 + f * 30) * 3.5;
      flowPts.push(getInteriorPoint(u, angleShift % 360));
    }
    let col = a > 265 ? (f % 2 === 0 ? "#85d6be" : "#6c9129") : "#233b28";
    brush.set("cpencil", col, random(0.45, 0.9));
    brush.spline(flowPts, 0.35);
  }
}

// =============================================================================
// 5. EXTERIOR RAW STONEWARE CLAY & FOOT RING (Charcoal Mass + Persimmon/Umber)
// =============================================================================
function drawBowlRawClayAndFoot() {
  brush.noStroke();
  brush.fillBleed(0.26, "in");
  brush.fillTexture(0.78, 0.48);

  // 5A. Carved Foot Ring (Kodai)
  let footPoly = [];
  for (let a = 0; a <= 180; a += 8) footPoly.push(getFootPoint(0.0, a));
  for (let a = 180; a >= 0; a -= 8) footPoly.push(getFootPoint(1.0, a));

  // Base iron-brown clay on foot ring
  brush.fill("#4f2412", 185);
  drawPoly(footPoly, 0.25);

  // Vivid persimmon fire-blush (hidasuki) on the lit left/front of the foot ring
  let footLit = [];
  for (let a = 75; a <= 175; a += 8) footLit.push(getFootPoint(0.0, a));
  for (let a = 175; a >= 75; a -= 8) footLit.push(getFootPoint(1.0, a));
  brush.fill("#d4501e", 130);
  drawPoly(footLit, 0.25);

  // 5B. Full Exterior Body Under-Wash (Raw Umber & Iron-Brown Base)
  let extFull = [];
  for (let v = 0; v <= 1.0; v += 0.1) extFull.push(getBowlPoint(v, 0));
  for (let a = 0; a <= 180; a += 6) extFull.push(getBowlPoint(1.0, a));
  for (let v = 1.0; v >= 0; v -= 0.1) extFull.push(getBowlPoint(v, 180));
  for (let a = 180; a >= 0; a -= 6) extFull.push(getBowlPoint(0.0, a));

  brush.fill("#592b16", 155);
  drawPoly(extFull, 0.25);

  // 5C. Exposed Lower Clay Zone (between glaze boundary and foot)
  let rawClayZone = [];
  for (let a = 0; a <= 180; a += 5) {
    let gv = Math.max(0.52, getGlazeBoundaryV(a) - 0.06);
    rawClayZone.push(getBowlPoint(gv, a));
  }
  for (let a = 180; a >= 0; a -= 5) {
    rawClayZone.push(getBowlPoint(1.0, a));
  }
  brush.fill("#6b3015", 170);
  drawPoly(rawClayZone, 0.28);

  // Vivid, saturated persimmon & burnt-orange kiln flash where ash glaze meets raw clay
  let persimmonBloom = [];
  for (let a = 45; a <= 168; a += 6) {
    let gv = getGlazeBoundaryV(a) - 0.04;
    persimmonBloom.push(getBowlPoint(gv, a));
  }
  for (let a = 168; a >= 45; a -= 6) {
    let gv = Math.min(0.98, getGlazeBoundaryV(a) + 0.18);
    persimmonBloom.push(getBowlPoint(gv, a));
  }
  brush.fillBleed(0.35, "out");
  brush.fill("#e35620", 145);
  drawPoly(persimmonBloom, 0.35);

  // Second intense persimmon blush around the front hip
  let persimmonCore = [];
  for (let a = 65; a <= 140; a += 6) {
    persimmonCore.push(getBowlPoint(0.68, a));
  }
  for (let a = 140; a >= 65; a -= 6) {
    persimmonCore.push(getBowlPoint(0.92, a));
  }
  brush.fill("#f06a24", 115);
  drawPoly(persimmonCore, 0.35);

  // Deep roasted umber wash on the shaded right side of the bowl (theta 0..65)
  let rightClayShade = [];
  for (let a = 0; a <= 68; a += 6) rightClayShade.push(getBowlPoint(0.45, a));
  for (let a = 68; a >= 0; a -= 6) rightClayShade.push(getBowlPoint(1.0, a));
  brush.fillBleed(0.25, "in");
  brush.fill("#2b1309", 175);
  drawPoly(rightClayShade, 0.3);

  brush.noFill();

  // 5D. Soft Charcoal Mass modeling the heavy stoneware clay & hip overhang
  // Right hip & belly core form shadow
  let charcoalRightHip = [];
  for (let a = 0; a <= 72; a += 8) charcoalRightHip.push(getBowlPoint(0.35, a));
  for (let a = 72; a >= 0; a -= 8) charcoalRightHip.push(getBowlPoint(1.0, a));
  brush.mass("charcoal", "#241007", { precision: 0.55, strength: 0.72, gradient: 0.55, outline: false });
  drawPoly(charcoalRightHip, 0.25);

  // Underside of the hip (koshi) all the way across to model the heavy clay turn
  let charcoalUnderHip = [];
  for (let a = 10; a <= 165; a += 8) charcoalUnderHip.push(getBowlPoint(0.80, a));
  for (let a = 165; a >= 10; a -= 8) charcoalUnderHip.push(getBowlPoint(1.0, a));
  brush.mass("charcoal", "#33170b", { precision: 0.5, strength: 0.62, gradient: 0.5, outline: false });
  drawPoly(charcoalUnderHip, 0.25);

  // Shaded right half of the carved kodai foot ring
  let charcoalFootShade = [];
  for (let a = 0; a <= 95; a += 8) charcoalFootShade.push(getFootPoint(0.0, a));
  for (let a = 95; a >= 0; a -= 8) charcoalFootShade.push(getFootPoint(1.0, a));
  brush.mass("charcoal", "#1c0b05", { precision: 0.6, strength: 0.75, gradient: 0.4, outline: false });
  drawPoly(charcoalFootShade, 0.2);

  // Warm iron-sienna dry mass on the lit left hip for tactile clay tooth
  let clayToothLeft = [];
  for (let a = 90; a <= 168; a += 8) clayToothLeft.push(getBowlPoint(0.65, a));
  for (let a = 168; a >= 90; a -= 8) clayToothLeft.push(getBowlPoint(0.95, a));
  brush.mass("cpencil", "#9e3c16", { precision: 0.45, strength: 0.5, gradient: 0.5, outline: false });
  drawPoly(clayToothLeft, 0.25);

  brush.noMass();

  // 5E. Tactile details on the Kodai foot ring and raw clay:
  // Deep shadow crease directly under the hip collar (kodai-waki)
  let collarCrease = [];
  for (let a = 4; a <= 176; a += 5) {
    collarCrease.push(getFootPoint(0.08, a));
  }
  brush.set("charcoal", "#170803", 1.15);
  brush.spline(collarCrease, 0.35);

  // Horizontal trimming facets & bamboo-knife chatter marks (chirimen-jima) on the foot and hip
  for (let a = 8; a <= 172; a += 3.5) {
    let pTop = getFootPoint(0.12, a);
    let pBot = getFootPoint(0.92, a);
    let isLit = a > 88;
    brush.set("2B", isLit ? "#471e0d" : "#1a0a04", random(0.4, 0.8));
    brush.line(pTop[0], pTop[1], pBot[0], pBot[1]);

    if (isLit && random() < 0.55) {
      brush.set("cpencil", "#eb7b44", random(0.35, 0.65));
      brush.line(pTop[0] - 1, pTop[1], pBot[0] - 1, pBot[1]);
    }
  }

  // Crepe-wrinkle chatter marks (chirimen-jima) where the potter trimmed the wet lower hip
  for (let a = 14; a <= 168; a += 2.8) {
    let gv = getGlazeBoundaryV(a);
    for (let v = Math.max(0.68, gv); v <= 0.96; v += 0.065) {
      let p1 = getBowlPoint(v, a);
      let p2 = getBowlPoint(v + 0.042, a + 0.8);
      let col = a > 85 ? "#3d180a" : "#1c0a04";
      brush.set("2B", col, random(0.35, 0.65));
      brush.line(p1[0], p1[1], p2[0], p2[1]);

      if (a > 90 && random() < 0.45) {
        brush.set("cpencil", "#f28c52", 0.4);
        brush.line(p1[0] - 1.2, p1[1] - 0.5, p2[0] - 1.2, p2[1] - 0.5);
      }
    }
  }

  // Iron spots (tetsu-ten) and coarse Shigaraki/Karatsu sand grains in the raw clay
  for (let i = 0; i < 160; i++) {
    let a = random(8, 174);
    let gv = getGlazeBoundaryV(a);
    let v = random(gv - 0.03, 0.99);
    let pt = getBowlPoint(v, a);
    if (random() < 0.65) {
      // Dark roasted iron speck
      brush.set("rotring", "#1f0b04", random(0.4, 0.95));
      brush.circle(pt[0], pt[1], random(0.8, 2.2), 0.35);
    } else {
      // Pale feldspathic sand grain catching winter light
      brush.set("glaze_needle", a > 75 ? "#f5dec4" : "#9c7356", random(0.5, 0.9));
      brush.line(pt[0], pt[1], pt[0] + 1.5, pt[1] + 0.8);
    }
  }
}

// =============================================================================
// 6. EXTERIOR NATURAL ASH GLAZE (Watercolour Blooms of Celadon, Olive & Umber)
// =============================================================================
function drawExteriorAshGlaze() {
  brush.noStroke();
  brush.fillBleed(0.28, "in");
  brush.fillTexture(0.76, 0.46);

  // 6A. Full Ash Glaze Mantle from Rim (v=0) down to Glaze Boundary
  let glazeMantle = [];
  for (let a = 0; a <= 180; a += 4) {
    glazeMantle.push(getBowlPoint(0.0, a));
  }
  for (let a = 180; a >= 0; a -= 4) {
    glazeMantle.push(getBowlPoint(getGlazeBoundaryV(a), a));
  }
  // Base warm olive-celadon ash glaze
  brush.fill("#587834", 150);
  drawPoly(glazeMantle, 0.28);

  // 6B. Luminous Celadon Blooms on the Upper-Left & Center-Left (lit by winter window)
  let celadonUpperLeft = [];
  for (let a = 78; a <= 176; a += 5) celadonUpperLeft.push(getBowlPoint(0.02, a));
  for (let a = 176; a >= 78; a -= 5) {
    let v = Math.min(0.58, getGlazeBoundaryV(a) * 0.78);
    celadonUpperLeft.push(getBowlPoint(v, a));
  }
  brush.fillBleed(0.34, "out");
  brush.fill("#66b89e", 145);
  drawPoly(celadonUpperLeft, 0.32);

  // Bright icy-celadon silicate veil near the upper-left shoulder (theta 105..165)
  let celadonVeil = [];
  for (let a = 102; a <= 165; a += 6) celadonVeil.push(getBowlPoint(0.05, a));
  for (let a = 165; a >= 102; a -= 6) celadonVeil.push(getBowlPoint(0.42, a));
  brush.fill("#9ce3d0", 120);
  drawPoly(celadonVeil, 0.35);

  // 6C. Vivid Olive-Green Ash Pooling around the Mid-Belly & Glaze Fringe
  let oliveMidZone = [];
  for (let a = 22; a <= 158; a += 5) {
    oliveMidZone.push(getBowlPoint(0.32, a));
  }
  for (let a = 158; a >= 22; a -= 5) {
    oliveMidZone.push(getBowlPoint(getGlazeBoundaryV(a), a));
  }
  brush.fillBleed(0.30, "in");
  brush.fill("#4f6e16", 155);
  drawPoly(oliveMidZone, 0.3);

  // Saturated golden-olive & chartreuse-amber bloom where wood ash melted thickly in center
  let amberOliveBloom = [];
  for (let a = 62; a <= 128; a += 6) amberOliveBloom.push(getBowlPoint(0.24, a));
  for (let a = 128; a >= 62; a -= 6) amberOliveBloom.push(getBowlPoint(0.66, a));
  brush.fill("#8ca629", 115);
  drawPoly(amberOliveBloom, 0.35);

  // Raw umber & warm persimmon show-through where glaze thins near the rim and upper ribs
  let rimUmberBloom = [];
  for (let a = 25; a <= 155; a += 6) rimUmberBloom.push(getBowlPoint(0.0, a));
  for (let a = 155; a >= 25; a -= 6) rimUmberBloom.push(getBowlPoint(0.14, a));
  brush.fill("#b85224", 105);
  drawPoly(rimUmberBloom, 0.3);

  // 6D. Deep Bottle-Olive & Raw Umber Glaze Shadow on the Right Side (theta 0..68)
  let rightGlazeShade = [];
  for (let a = 0; a <= 66; a += 5) rightGlazeShade.push(getBowlPoint(0.02, a));
  for (let a = 66; a >= 0; a -= 5) rightGlazeShade.push(getBowlPoint(getGlazeBoundaryV(a), a));
  brush.fillBleed(0.24, "in");
  brush.fill("#23360d", 170);
  drawPoly(rightGlazeShade, 0.3);

  brush.noFill();

  // Dry charcoal & pastel mass to model the deep glassy curvature on the shaded right side
  let rightGlazeMass = [];
  for (let a = 4; a <= 55; a += 6) rightGlazeMass.push(getBowlPoint(0.08, a));
  for (let a = 55; a >= 4; a -= 6) rightGlazeMass.push(getBowlPoint(getGlazeBoundaryV(a) - 0.04, a));
  brush.mass("charcoal", "#172408", { precision: 0.6, strength: 0.62, gradient: 0.5, outline: false });
  drawPoly(rightGlazeMass, 0.25);
  brush.noMass();

  // Crisp, glassy fringe along the undulating lower glaze boundary where ash glaze meets raw clay
  let fringePts = [];
  for (let a = 4; a <= 176; a += 2.5) {
    fringePts.push(getBowlPoint(getGlazeBoundaryV(a), a));
  }
  // Thin dark shadow under the thick glaze lip
  let fringeShadow = fringePts.map(p => [p[0] + 1.2, p[1] + 2.4]);
  brush.set("charcoal", "#291106", 0.85);
  brush.spline(fringeShadow, 0.35);

  // Vivid persimmon-amber oxidation halo right along the glaze arrest line
  let fringeHalo = fringePts.map(p => [p[0], p[1] + 3.8]);
  brush.set("cpencil", "#e85d22", 1.1);
  brush.spline(fringeHalo, 0.35);

  // Thick olive-jade bead along the glaze edge
  brush.set("cpencil", "#354f0e", 1.15);
  brush.spline(fringePts, 0.35);
}

// =============================================================================
// 7A. THROWING RINGS (Rokuro-me) & THUMB DENTS (Te-bineri)
// =============================================================================
function drawExteriorThrowingRingsAndDents() {
  // 1. Render the two Thumb Dents with reverent 3D modeling:
  // Dent 1: Front-left hip (v=0.57, theta=115)
  // Dent 2: Front-right belly (v=0.47, theta=55)
  let dents = [
    { v: 0.57, t: 115, rv: 0.11, rt: 12, isLeft: true },
    { v: 0.47, t: 55, rv: 0.11, rt: 14, isLeft: false }
  ];

  for (let d of dents) {
    // Upper-left crescent of each dent is in shadow (recessed away from window light)
    let dentShade = [];
    for (let a = -80; a <= 110; a += 20) {
      let vv = d.v + d.rv * 0.75 * sin(a);
      let tt = d.t + d.rt * 0.75 * cos(a);
      dentShade.push(getBowlPoint(vv, tt));
    }
    for (let a = 110; a >= -80; a -= 20) {
      let vv = d.v + d.rv * 0.2 * sin(a);
      let tt = d.t + d.rt * 0.2 * cos(a);
      dentShade.push(getBowlPoint(vv, tt));
    }
    brush.noStroke();
    brush.fillBleed(0.22, "in");
    brush.fill(d.isLeft ? "#2b4214" : "#1a2908", 155);
    drawPoly(dentShade, 0.35);

    // Pooled glassy olive glaze in the bottom cradle of the thumb dent
    let dentPool = [];
    for (let a = 15; a <= 165; a += 20) {
      let vv = d.v + d.rv * 0.85 * sin(a);
      let tt = d.t + d.rt * 0.7 * cos(a);
      dentPool.push(getBowlPoint(vv, tt));
    }
    brush.fill(d.isLeft ? "#4a6e17" : "#34520d", 170);
    drawPoly(dentPool, 0.35);
    brush.noFill();

    // Charcoal contour modeling inside the thumb impression
    brush.mass("charcoal", d.isLeft ? "#263812" : "#152106", {
      precision: 0.65,
      strength: 0.55,
      gradient: 0.5,
      outline: false
    });
    drawPoly(dentShade, 0.3);
    brush.noMass();

    // Lower-right inner cup of the dent catches bright raking winter light!
    let rimHighlight = [];
    for (let a = -55; a <= 65; a += 15) {
      let vv = d.v + d.rv * 0.65 * sin(a);
      let tt = d.t - d.rt * 0.68 * cos(a);
      rimHighlight.push(getBowlPoint(vv, tt));
    }
    brush.set("cpencil", d.isLeft ? "#b8f0dc" : "#9ec94b", 1.05);
    brush.spline(rimHighlight, 0.4);

    // Subtle specular crescent on the pooled olive glaze inside the dent
    let specArc = [];
    for (let a = 35; a <= 135; a += 20) {
      let vv = d.v + d.rv * 0.55 * sin(a);
      let tt = d.t + d.rt * 0.5 * cos(a);
      specArc.push(getBowlPoint(vv, tt));
    }
    brush.set("glaze_needle", "#ebfaf7", 0.95);
    brush.spline(specArc, 0.4);
  }

  // 2. Render Exterior Throwing Rings (Rokuro-me) wrapping around the 3D volume
  let numRings = 24;
  for (let r = 1; r < numRings; r++) {
    let v = (r / numRings) * 0.94;

    // Break each ring into natural arcs across the front hemisphere (theta 6..174)
    let a = 6;
    while (a < 172) {
      let segLen = random(18, 42);
      let aEnd = Math.min(174, a + segLen);
      let ringPts = [];
      let ridgePts = [];
      let hiPts = [];

      for (let ang = a; ang <= aEnd; ang += 3.5) {
        let pt = getBowlPoint(v, ang);
        ringPts.push(pt);
        ridgePts.push([pt[0], pt[1] - 2.3]);
        hiPts.push([pt[0], pt[1] - 3.4]);
      }

      let midA = (a + aEnd) * 0.5;
      let gv = getGlazeBoundaryV(midA);
      let inGlaze = v < gv;

      if (inGlaze) {
        // Inside the ash glaze:
        // Glaze pools darker olive/celadon in the recessed groove
        let grooveCol = midA > 85 ? (r % 2 === 0 ? "#2e5945" : "#436317") : "#1c2e0a";
        brush.set("cpencil", grooveCol, random(0.55, 1.05));
        brush.spline(ringPts, 0.35);

        // Warm persimmon/raw-umber clay ridge showing through thin glaze on the crest!
        if (r % 2 === 0 && midA > 35 && midA < 155) {
          brush.set("cpencil", midA > 85 ? "#c95826" : "#7d3818", random(0.45, 0.85));
          brush.spline(ridgePts, 0.35);
        }

        // Crisp winter window specular reflection along the upper lip of the throwing ring on the lit side
        if (midA > 75 && midA < 162 && (r % 2 === 1 || v < 0.45)) {
          let specCol = v < 0.38 ? "#e4f7f2" : "#c7e67e";
          brush.set("glaze_needle", specCol, random(0.55, 1.15));
          brush.spline(hiPts, 0.35);
        }
      } else {
        // In the unglazed raw iron-brown clay near the hip/foot:
        let clayShadowCol = midA > 80 ? "#381609" : "#1a0903";
        brush.set("charcoal", clayShadowCol, random(0.5, 0.95));
        brush.spline(ringPts, 0.35);

        // Lit persimmon-ochre crest catching low winter light
        if (midA > 70) {
          brush.set("cpencil", "#e66f35", random(0.45, 0.8));
          brush.spline(ridgePts, 0.35);
        }
      }

      a = aEnd + random(2, 7);
    }
  }

  // Vertical & diagonal ash glaze flow rivulets descending across the throwing rings
  for (let f = 0; f < 28; f++) {
    let aStart = random(14, 166);
    let vStart = random(0.06, 0.32);
    let vEnd = getGlazeBoundaryV(aStart) - random(0.01, 0.08);
    if (vEnd <= vStart + 0.1) continue;

    let flowPts = [];
    let steps = 10;
    for (let s = 0; s <= steps; s++) {
      let vv = lerp(vStart, vEnd, s / steps);
      let aa = aStart + sin(vv * 220 + f * 40) * 2.2;
      flowPts.push(getBowlPoint(vv, aa));
    }

    // Milky blue-celadon or rich olive-amber silicate streak
    let streakCol;
    if (aStart > 95) {
      streakCol = f % 2 === 0 ? "#8cd9c5" : "#6b9928";
    } else if (aStart > 55) {
      streakCol = f % 2 === 0 ? "#7da329" : "#c78b2c";
    } else {
      streakCol = "#2e4710";
    }
    brush.set("cpencil", streakCol, random(0.55, 1.1));
    brush.spline(flowPts, 0.35);
  }
}

// =============================================================================
// 7B. GLASSY OLIVE DRIPS POOLING NEAR THE FOOT
// =============================================================================
function drawGlassyOliveDrips() {
  // Define the thick, arrested glassy olive ash glaze drips (tamadare) near the foot
  let dripSpecs = [
    { t: 152, vStart: 0.56, vEnd: 0.85, rad: 9.5 },
    { t: 124, vStart: 0.55, vEnd: 0.90, rad: 13.5 }, // prominent drip below left thumb dent
    { t: 118, vStart: 0.64, vEnd: 0.84, rad: 8.5 },  // companion bead
    { t: 97,  vStart: 0.58, vEnd: 0.88, rad: 12.0 }, // front-center olive drop
    { t: 54,  vStart: 0.48, vEnd: 0.91, rad: 14.5 }, // heavy drip below right finger dent
    { t: 48,  vStart: 0.62, vEnd: 0.85, rad: 9.0 },  // side companion bead
    { t: 31,  vStart: 0.56, vEnd: 0.83, rad: 10.0 }
  ];

  for (let d of dripSpecs) {
    let pTop = getBowlPoint(d.vStart, d.t);
    let pMid = getBowlPoint((d.vStart + d.vEnd) * 0.52, d.t);
    let pBot = getBowlPoint(d.vEnd, d.t);
    let rx = d.rad;
    let ry = d.rad * 1.28;

    // 1. Crisp cast shadow directly beneath the bulbous glass bead on the raw clay
    brush.noStroke();
    brush.fillBleed(0.12, "out");
    brush.fill("#140702", 210);
    let dripShadow = [];
    for (let a = -15; a <= 205; a += 25) {
      dripShadow.push([
        pBot[0] + 2.2 + rx * 0.95 * cos(a),
        pBot[1] + 4.2 + ry * 0.72 * sin(a)
      ]);
    }
    drawPoly(dripShadow, 0.35);

    // 2. Tapered glaze run channel feeding the droplet from above
    let channelPoly = [
      [pTop[0] - rx * 0.42, pTop[1]],
      [pMid[0] - rx * 0.68, pMid[1]],
      [pBot[0] - rx * 0.95, pBot[1] - ry * 0.2],
      [pBot[0], pBot[1] + ry * 0.85],
      [pBot[0] + rx * 0.95, pBot[1] - ry * 0.2],
      [pMid[0] + rx * 0.68, pMid[1]],
      [pTop[0] + rx * 0.42, pTop[1]]
    ];
    brush.fillBleed(0.15, "in");
    brush.fill("#28420b", 215);
    drawPoly(channelPoly, 0.35);

    // 3. Bulbous teardrop bead body (deep glassy bottle-olive)
    let beadPoly = [];
    for (let a = 0; a < 360; a += 20) {
      let stretch = a < 180 ? 0.85 : 1.15;
      beadPoly.push([
        pBot[0] + rx * cos(a),
        pBot[1] + ry * stretch * sin(a)
      ]);
    }
    brush.fill("#1b3006", 230);
    drawPoly(beadPoly, 0.4);

    // 4. Internal sub-surface caustic glow (vivid chartreuse-olive & golden amber in lower-right belly of drop)
    let causticPoly = [];
    for (let a = 10; a <= 155; a += 20) {
      causticPoly.push([
        pBot[0] + rx * 0.12 + rx * 0.65 * cos(a),
        pBot[1] + ry * 0.1 + ry * 0.58 * sin(a)
      ]);
    }
    brush.fill("#96bd28", 195);
    drawPoly(causticPoly, 0.4);

    // Innermost fiery golden-lime core caustic
    let coreCaustic = [];
    for (let a = 25; a <= 135; a += 25) {
      coreCaustic.push([
        pBot[0] + rx * 0.18 + rx * 0.42 * cos(a),
        pBot[1] + ry * 0.22 + ry * 0.38 * sin(a)
      ]);
    }
    brush.fill("#d4eb52", 180);
    drawPoly(coreCaustic, 0.4);

    // Milky celadon-blue opalescent veil in the upper neck of the drip
    let neckVeil = [
      [pTop[0] - rx * 0.25, pTop[1] + 6],
      [pMid[0] - rx * 0.45, pMid[1]],
      [pBot[0] - rx * 0.35, pBot[1] - ry * 0.25],
      [pBot[0] + rx * 0.25, pBot[1] - ry * 0.25],
      [pMid[0] + rx * 0.35, pMid[1]]
    ];
    brush.fill("#7dc9b5", 135);
    drawPoly(neckVeil, 0.35);

    brush.noFill();

    // 5. Crisp dark glass rim contour around the bead
    brush.set("rotring", "#101f03", 0.55);
    drawPoly(beadPoly, 0.4, true);

    // 6. Razor-sharp winter window specular reflection on the upper-left curve of the glass bead
    let specCurve = [
      [pTop[0] - rx * 0.22, pTop[1] + 10],
      [pMid[0] - rx * 0.44, pMid[1]],
      [pBot[0] - rx * 0.58, pBot[1] - ry * 0.25],
      [pBot[0] - rx * 0.32, pBot[1] + ry * 0.25]
    ];
    brush.set("glaze_needle", "#f5fcfb", 1.35);
    brush.spline(specCurve, 0.4);

    // Bright pinpoint window reflection dot on the shoulder of the bead
    brush.set("glaze_needle", "#ffffff", 1.7);
    brush.line(
      pBot[0] - rx * 0.48, pBot[1] - ry * 0.32,
      pBot[0] - rx * 0.42, pBot[1] - ry * 0.12
    );

    // Secondary bottom-edge internal reflection arc
    let botGlint = [];
    for (let a = 35; a <= 135; a += 25) {
      botGlint.push([
        pBot[0] + rx * 0.72 * cos(a),
        pBot[1] + ry * 0.68 * sin(a)
      ]);
    }
    brush.set("glaze_needle", "#d8f279", 0.9);
    brush.spline(botGlint, 0.4);
  }
}

// =============================================================================
// 7C. KILN-GRIT POCK (Ishihaze — Feldspar Stone Burst in the Raw Clay)
// =============================================================================
function drawKilnGritPock() {
  // Placed in the exposed raw clay zone at front-right-center (v=0.79, theta=74)
  let pockPt = getBowlPoint(0.79, 74);
  let px = pockPt[0];
  let py = pockPt[1];

  brush.noStroke();
  brush.fillBleed(0.15, "out");

  // Rust-persimmon iron oxidation halo around the burst crater
  let haloPts = [];
  for (let a = 0; a < 360; a += 30) {
    haloPts.push([px + 18 * cos(a), py + 13 * sin(a)]);
  }
  brush.fill("#c94518", 135);
  drawPoly(haloPts, 0.35);

  // Deep jagged crater shadow where the clay split open in the kiln
  let craterPts = [
    [px - 12, py - 2], [px - 6, py - 9], [px + 5, py - 8],
    [px + 13, py - 1], [px + 9, py + 8], [px - 3, py + 9], [px - 10, py + 4]
  ];
  brush.fill("#170602", 230);
  drawPoly(craterPts, 0.2);

  // The exposed white-cream feldspar/quartz kiln grit stone fused inside the crater
  let stonePts = [
    [px - 6.5, py - 1.5], [px - 2.5, py - 5.5], [px + 4.5, py - 4.0],
    [px + 7.0, py + 1.0], [px + 2.5, py + 5.0], [px - 4.5, py + 3.5]
  ];
  brush.fill("#f2eadc", 235);
  drawPoly(stonePts, 0.15);

  // Shaded lower-right facet of the quartz pebble
  let stoneShade = [
    [px + 0.5, py - 1.0], [px + 6.5, py + 0.5],
    [px + 2.5, py + 5.0], [px - 3.5, py + 3.5]
  ];
  brush.fill("#b8aa96", 190);
  drawPoly(stoneShade, 0.15);
  brush.noFill();

  // Sharp crystalline facet lines on the burst stone
  brush.set("rotring", "#36180b", 0.45);
  drawPoly(stonePts, 0.15, true);
  brush.set("glaze_needle", "#ffffff", 1.15);
  brush.line(px - 5, py - 2, px - 1, py - 4.5);
  brush.line(px - 1, py - 4.5, px + 3, py - 2.5);

  // Peeled-back clay lips around the lower-right of the crater catching raking winter light
  brush.set("cpencil", "#f7a272", 0.9);
  brush.spline([
    [px - 4, py + 8.5], [px + 4, py + 8], [px + 11, py + 2], [px + 9, py - 5]
  ], 0.3);

  // Radiating star-cracks (ishihaze fissures) Bursting outward into the surrounding clay
  let starAngles = [-155, -108, -32, 22, 78, 138];
  for (let ang of starAngles) {
    let len = random(16, 30);
    let cPts = [];
    for (let s = 0; s <= 4; s++) {
      let d = lerp(7, len, s / 4);
      let jitterA = ang + (noise(ang, s * 0.8) - 0.5) * 18;
      cPts.push([px + d * cos(jitterA), py + d * 0.78 * sin(jitterA)]);
    }
    brush.set("rotring", "#1a0702", 0.48);
    brush.spline(cPts, 0.25);

    // Subtle highlight along the lower/right edge of each micro-fissure
    let hiPts = cPts.map(p => [p[0] + 0.9, p[1] + 0.9]);
    brush.set("glaze_needle", "#eb8a57", 0.45);
    brush.spline(hiPts, 0.25);
  }
}

// =============================================================================
// 7D. HAIRLINE CRACKLE (Kan'nyu), RIM KILN CRACK & UNDULATING LIP
// =============================================================================
function drawHairlineCrackleAndRim() {
  // 1. Reverently rendered main Hairline Kiln Crack descending from the front-left rim (theta=103)
  let crackPts = [];
  let crackHiPts = [];
  let cTheta = 103;
  for (let s = 0; s <= 18; s++) {
    let v = (s / 18) * 0.52;
    cTheta += (noise(s * 0.45, 9.2) - 0.48) * 2.6;
    let p = getBowlPoint(v, cTheta);
    crackPts.push(p);
    crackHiPts.push([p[0] + 1.3, p[1] + 0.6]);
  }
  // Tea- and iron-stained halo along the hairline crack
  brush.set("cpencil", "#8c3b19", 0.95);
  brush.spline(crackPts, 0.25);
  // Crisp dark hairline fissure
  brush.set("rotring", "#1f0b04", 0.52);
  brush.spline(crackPts, 0.25);
  // Bright winter light glint catching the glazed edge of the crack
  brush.set("glaze_needle", "#eefaf7", 0.75);
  brush.spline(crackHiPts, 0.25);

  // Two delicate micro-branches off the main hairline crack
  for (let b of [5, 11]) {
    let bp0 = crackPts[b];
    let dir = b === 5 ? -1 : 1;
    let bPts = [
      bp0,
      [bp0[0] + dir * 14, bp0[1] + 9],
      [bp0[0] + dir * 26, bp0[1] + 16]
    ];
    brush.set("rotring", "#2b1207", 0.36);
    brush.spline(bPts, 0.25);
    brush.set("glaze_needle", "#e4f7f2", 0.45);
    brush.line(bp0[0], bp0[1] + 1, bp0[0] + dir * 18, bp0[1] + 12);
  }

  // Also show the hairline crack descending slightly down the interior wall from theta=103
  let intCrack = [];
  for (let s = 0; s <= 6; s++) {
    intCrack.push(getInteriorPoint((s / 6) * 0.34, 103 + s * 0.5));
  }
  brush.set("rotring", "#1c120b", 0.42);
  brush.spline(intCrack, 0.25);

  // 2. Network of Fine Glaze Crackle (Kan'nyu) across the Exterior Celadon & Olive Glaze
  // Build a curved grid of perturbed vertices in (v, theta) space and draw polygonal craze segments
  let rows = 8;
  let cols = 18;
  let grid = [];
  for (let r = 0; r <= rows; r++) {
    grid[r] = [];
    for (let c = 0; c <= cols; c++) {
      let baseTheta = lerp(12, 168, c / cols);
      let maxV = getGlazeBoundaryV(baseTheta) - 0.03;
      let baseV = lerp(0.04, maxV, r / rows);

      let jitT = (noise(r * 1.3, c * 1.7, 10) - 0.5) * 6.5;
      let jitV = (noise(r * 1.7, c * 1.3, 20) - 0.5) * 0.055;
      let v = constrain(baseV + jitV, 0.02, maxV);
      let t = constrain(baseTheta + jitT, 8, 172);
      grid[r][c] = { pt: getBowlPoint(v, t), v: v, t: t };
    }
  }

  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      let n1 = grid[r][c];
      let nRight = grid[r][c + 1];
      let nDown = grid[r + 1][c];

      // Horizontal-ish craze line
      if (random() < 0.78) {
        drawCrackleSegment(n1.pt, nRight.pt, n1.t);
      }
      // Vertical-ish craze line
      if (random() < 0.82) {
        drawCrackleSegment(n1.pt, nDown.pt, n1.t);
      }
    }
  }

  // Interior glaze crackle network on the lit right/back interior wall
  for (let i = 0; i < 28; i++) {
    let a1 = random(235, 375);
    let u1 = random(0.08, 0.68);
    let a2 = a1 + random(-18, 18);
    let u2 = constrain(u1 + random(-0.18, 0.18), 0.05, 0.78);
    let p1 = getInteriorPoint(u1, a1 % 360);
    let p2 = getInteriorPoint(u2, a2 % 360);
    drawCrackleSegment(p1, p2, 120);
  }

  // 3. The Undulating Rim (Kuchi-zukuri) — Tactile Lip, Iron Show-Through & Specular Glint
  // Back rim (theta 180..360) and Front rim (theta 0..180)
  for (let pass = 0; pass < 2; pass++) {
    let startA = pass === 0 ? 180 : 0;
    let endA = pass === 0 ? 360 : 180;

    let outerLip = [];
    let midLip = [];
    let innerLip = [];

    for (let a = startA; a <= endA; a += 3) {
      let pOut = getBowlPoint(0.0, a % 360);
      let pIn = getInteriorPoint(0.0, a % 360);
      outerLip.push(pOut);
      innerLip.push(pIn);
      midLip.push([
        lerp(pOut[0], pIn[0], 0.5),
        lerp(pOut[1], pIn[1], 0.5) - 1.8
      ]);
    }

    // Warm roasted iron-brown & persimmon clay peeking through the thin glaze on the rim crest
    brush.set("cpencil", "#8a3817", 1.15);
    brush.spline(midLip, 0.35);

    // Dark iron-umber inner & outer rim definition
    brush.set("charcoal", "#2e1409", 0.65);
    brush.spline(outerLip, 0.35);
    brush.set("2B", "#2b3829", 0.55);
    brush.spline(innerLip, 0.35);

    // Pooled celadon & olive glaze beads along the undulating rim dips
    for (let a = startA + 6; a < endA - 6; a += 9) {
      let ang = a % 360;
      let p = getBowlPoint(0.0, ang);
      let isLit = (ang > 70 && ang < 210) || (ang > 280 && ang < 350);
      if (isLit) {
        brush.set("glaze_needle", "#e6faf5", random(0.75, 1.35));
        let pNext = getBowlPoint(0.0, (ang + 5) % 360);
        brush.line(p[0], p[1] - 1.5, pNext[0], pNext[1] - 1.5);
      }
    }
  }
}

function drawCrackleSegment(p1, p2, theta) {
  let midX = (p1[0] + p2[0]) * 0.5 + random(-2.2, 2.2);
  let midY = (p1[1] + p2[1]) * 0.5 + random(-2.2, 2.2);
  let pts = [p1, [midX, midY], p2];

  // Subtle tea-stained hairline craze
  let stainCol = theta > 75 ? "#382210" : "#172109";
  brush.set("rotring", stainCol, random(0.22, 0.38));
  brush.spline(pts, 0.25);

  // Microscopic winter light glint along the crackle edge on the lit half
  if (theta > 60 && random() < 0.68) {
    let hiPts = pts.map(p => [p[0] + 0.85, p[1] + 0.65]);
    brush.set("glaze_needle", "#e2f5ee", random(0.28, 0.52));
    brush.spline(hiPts, 0.25);
  }
}

// =============================================================================
// 8. FINAL WINTER WINDOW HIGHLIGHTS & FOREGROUND TEXTURE
// =============================================================================
function drawFinalHighlightsAndAtmosphere() {
  // Broad, broken specular reflection of the paper shoji window across the upper-left glazed shoulder
  // Follows the throwing rings vertically down theta ≈ 118..146
  for (let r = 2; r <= 13; r++) {
    let v = (r / 24) * 0.94;
    if (v > 0.52) continue;

    // Split the window reflection into two panes (shoji paper lattice effect!)
    let panes = [
      [118, 131],
      [135, 147]
    ];
    for (let pane of panes) {
      let hiArc = [];
      for (let a = pane[0]; a <= pane[1]; a += 2.5) {
        let p = getBowlPoint(v, a);
        hiArc.push([p[0], p[1] - 1.8]);
      }
      brush.set("glaze_needle", "#f2fcfb", random(0.95, 1.55));
      brush.spline(hiArc, 0.35);
    }
  }

  // Secondary warm olive-amber sheen on the lower-center belly swells (theta 75..108)
  for (let r = 9; r <= 15; r++) {
    let v = (r / 24) * 0.94;
    let sheenArc = [];
    for (let a = 80; a <= 102; a += 3) {
      let p = getBowlPoint(v, a);
      sheenArc.push([p[0], p[1] - 1.5]);
    }
    brush.set("glaze_needle", "#d9f086", random(0.6, 1.05));
    brush.spline(sheenArc, 0.35);
  }

  // Subtle reflected cedar warmth on the shaded right profile of the glaze (theta 8..28)
  for (let v = 0.15; v <= 0.62; v += 0.08) {
    let p1 = getBowlPoint(v, 10);
    let p2 = getBowlPoint(v + 0.05, 18);
    brush.set("cpencil", "#9e5527", 0.65);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Fine graphite & charcoal sketching lines at the outer plank margins so the wood grain
  // dissolves effortlessly into the loose warm grey paper edges
  for (let i = 0; i < 24; i++) {
    let isLeft = i < 12;
    let x0 = isLeft ? random(10, 190) : random(940, 1160);
    let y0 = random(500, 960);
    let len = random(35, 95);
    brush.set("2H", "#8c8780", random(0.35, 0.7));
    brush.line(x0, y0, x0 + len, y0 - len * 0.052);
  }
}

// ============================================================================
// HYPERREAL TALAVERA SINK BASIN, PERSIAN LIMES, SOAP BEADS & BRASS TAP
// p5.js 2.x + p5.brush | 1200 x 1200 WEBGL
// ============================================================================

const SINK_CX = 615;
const SINK_CY = 635;
const SINK_RX = 382;
const SINK_ROT = -10; // degrees
const TILT_RATIO = 0.79; // vertical foreshortening from overhead angle

// Helper: safely draw a stroked line
function sLine(x1, y1, x2, y2, bName, col, w = 1) {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set(bName, col, w);
  brush.line(x1, y1, x2, y2);
}

// Helper: safely draw a stroked spline
function sSpline(pts, curv, bName, col, w = 1) {
  if (!pts || pts.length < 2) return;
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set(bName, col, w);
  brush.spline(pts, curv);
}

// Helper: safely draw a stroked arc
function sArc(x, y, r, a1, a2, bName, col, w = 1) {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set(bName, col, w);
  brush.arc(x, y, r, a1, a2);
}

// Helper: safely draw a filled custom shape (watercolor bleed/texture)
function fPoly(pts, col, op = 120, bleed = 0.08, tex = 0.25, curv = 0.15) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noWash();
  brush.noHatch();
  brush.fill(col, op);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, 0.2);
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noFill();
  brush.set("HB", "#333333", 0.5);
}

// Helper: safely draw a fast wash polygon (opaque/semi-opaque flat pass)
function wPoly(pts, col, op = 150, curv = 0.1) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.wash(col, op);
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noWash();
  brush.set("HB", "#333333", 0.5);
}

// Helper: generate polygon points for a rotated, tilted ellipse
function ellipsePts(cx, cy, rx, ry, rotDeg = 0, n = 36, rJitter = 0) {
  let pts = [];
  let c = cos(rotDeg);
  let s = sin(rotDeg);
  for (let i = 0; i < n; i++) {
    let ang = (i / n) * 360;
    let radMod = 1 + (rJitter > 0 ? (noise(cx * 0.01 + i * 0.3, cy * 0.01) - 0.5) * rJitter : 0);
    let lx = cos(ang) * rx * radMod;
    let ly = sin(ang) * ry * radMod;
    pts.push([cx + lx * c - ly * s, cy + lx * s + ly * c]);
  }
  return pts;
}

// ----------------------------------------------------------------------------
// 3D SURFACE PROJECTION FOR THE CONCAVE TALAVERA BASIN & ROLLED RIM
// rNorm: 0 = center of drain, 1.0 = inner rim edge, 1.15 = outer rim edge
// theta: angle in degrees around the basin
// ----------------------------------------------------------------------------
function basinHeightZ(rNorm) {
  if (rNorm <= 1.0) {
    // Deep concave ceramic bowl (-182px deep at drain)
    return -182 * (1 - pow(max(0, rNorm), 1.82));
  } else if (rNorm <= 1.155) {
    // Plush hand-rolled ceramic lip rising above the tile countertop
    let t = constrain((rNorm - 1.0) / 0.155, 0, 1);
    return 24 * sin(t * 180);
  }
  return 0;
}

function bowlPoint(theta, rNorm, zOffset = 0) {
  let r = rNorm * SINK_RX;
  // Subtle handmade potter's wheel irregularity
  let potterWave = 1 + 0.008 * sin(theta * 3 + 20) + 0.005 * cos(theta * 5 - 40);
  let lx = cos(theta) * r * potterWave;
  let ly = sin(theta) * r * potterWave;

  let c = cos(SINK_ROT);
  let s = sin(SINK_ROT);
  let rx = lx * c - ly * s;
  let ry = lx * s + ly * c;

  let z = basinHeightZ(rNorm) + zOffset;
  // Project 3D bowl coordinates to 2D angled overhead camera
  let sx = SINK_CX + rx - z * 0.09;
  let sy = SINK_CY + ry * TILT_RATIO - z * 0.62;
  return [sx, sy, z];
}

// Inverse approximation: estimate surface height z at any screen coordinate (x,y)
// Used so shuttered window light beams bend accurately down into the 3D sink!
function estimateSurfaceZ(x, y) {
  // Iterative unprojection
  let zEst = 0;
  for (let iter = 0; iter < 3; iter++) {
    let dx = x - SINK_CX + zEst * 0.09;
    let dy = (y - SINK_CY + zEst * 0.62) / TILT_RATIO;
    let r = sqrt(dx * dx + dy * dy);
    let rNorm = r / SINK_RX;
    if (rNorm <= 1.155) {
      zEst = basinHeightZ(rNorm);
    } else {
      zEst = 0;
    }
  }
  return zEst;
}

// Evaluate Mexican midday sunlight through shuttered window (returns 0..1 sunlight factor)
function getSunLight(x, y, z = null) {
  if (z === null) z = estimateSurfaceZ(x, y);
  // Ray-trace from (x, y, z) toward upper-left sun to z = 0 reference plane
  let wx = x + z * 0.46;
  let wy = y + z * 0.56;
  // Diagonal shutter slats oriented at -28 degrees
  let u = wx * cos(62) + wy * sin(62);
  let period = 138;
  let phase = ((u % period) + period) % period;
  // Soft penumbra transition at shutter edges
  let sun = 0;
  if (phase < 78) {
    sun = 1.0;
    if (phase < 14) sun = phase / 14;
    else if (phase > 64) sun = 1.0 - (phase - 64) / 14;
  }
  return sun;
}

// ============================================================================
// SETUP & CUSTOM BRUSHES
// ============================================================================
async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
