  });

  // 2. Glassy ridge & dark pooled edge brush
  brush.add("glaze_ridge", {
    type: "default",
    weight: 1.15,
    scatter: 0.04,
    sharpness: 0.82,
    grain: 4,
    opacity: 215,
    spacing: 0.1,
    pressure: [0.2, 1.1, 0.3],
    rotate: "natural",
    noise: 0.25
  });

  // 3. Soft pastel blender for velvety form transitions
  brush.add("pastel_soft", {
    type: "default",
    weight: 11.0,
