  });
}

// ============================================================================
// MAIN RENDER PIPELINE
// ============================================================================
function draw() {
  translate(-width / 2, -height / 2);
  background("#F5EFE6");

  // 1. Hand-molded pastel terracotta countertop tiles & mortar joints
  drawTiledCountertop();

  // 2. Exterior shadow of the sink rim on the countertop
  drawSinkExteriorShadow();

  // 3. Milky white tin-glazed basin underpainting, 3D shading & pinholes
  drawTinGlazeBasin();

  // 4. Hand-painted Talavera cobalt & ochre motifs with thick pooled glaze ridges
  drawTalaveraMotifs();

  // 5. Recessed antique brass drain & clear pooled water in the basin bottom
  drawBrassDrainAndWaterPool();

  // 6. Three cut Persian limes with translucent vesicles & wet reflections
  drawPersianLimes();

  // 7. Fluted pastel soap dish filled with translucent glass/soap beads
  drawBeadSoapDish();

  // 8. Shuttered Mexican midday sunlight & cool pastel shadow slats (3D-warped)
  drawShutteredWindowLight();

  // 9. Overhanging antique brass tap & falling water drop sequence
  drawBrassTapAndDrips();

  // 10. Hyperreal refractive water droplets across ceramic, limes & tiles
  drawAllWaterDroplets();

  noLoop();
}

// ============================================================================
// 1. TILED COUNTERTOP
// ============================================================================
function drawTiledCountertop() {
  let tileW = 162;
  let tileH = 128;
  let gap = 7;
  let c = cos(SINK_ROT);
  let s = sin(SINK_ROT);

  let pastelTileCols = [
    "#F6F0E6", "#F2E6DC", "#E9EFEA", "#EDE9F2",
    "#F5EBD9", "#EFECE6", "#E7ECE8", "#F4E8E1"
  ];

  // Draw grout/mortar bed first
  wPoly([[0, 0], [1200, 0], [1200, 1200], [0, 1200]], "#C8BEB2", 180, 0);

  for (let row = -5; row <= 6; row++) {
    for (let col = -5; col <= 6; col++) {
      let lx = col * tileW;
      let ly = row * tileH;
      let cx = 600 + lx * c - ly * s;
      let cy = 600 + lx * s + ly * c;

      // Skip tiles completely hidden inside the deep sink
      let distToSink = dist(cx, cy, SINK_CX, SINK_CY);
      if (distToSink < 290) continue;

      let hw = (tileW - gap) * 0.5;
      let hh = (tileH - gap) * 0.5;
      let cornersLocal = [
        [-hw, -hh], [hw, -hh], [hw, hh], [-hw, hh]
      ];
      let pts = [];
      for (let k = 0; k < 4; k++) {
        let jx = (noise(col * 3 + k, row * 3) - 0.5) * 3.5;
        let jy = (noise(col * 3 + k + 10, row * 3) - 0.5) * 3.5;
        let px = cx + (cornersLocal[k][0] + jx) * c - (cornersLocal[k][1] + jy) * s;
        let py = cy + (cornersLocal[k][0] + jx) * s + (cornersLocal[k][1] + jy) * c;
        pts.push([px, py]);
      }

      // Base pastel ceramic tile wash
      let colIdx = abs(col * 7 + row * 13) % pastelTileCols.length;
      let tCol = pastelTileCols[colIdx];
      wPoly(pts, tCol, 220, 0.08);
      fPoly(pts, tCol, 85, 0.06, 0.3, 0.08);

      // Subtle terracotta blush at tile corners where tin glaze thins
      if ((col + row) % 2 === 0) {
        fPoly([pts[0], pts[1], [cx, cy]], "#E8D5C8", 40, 0.12, 0.3, 0.1);
      } else {
        fPoly([pts[2], pts[3], [cx, cy]], "#DCE4E8", 45, 0.12, 0.3, 0.1);
      }

      // Grout shadow along top/left & glossy ceramic bevel highlight
      sSpline([pts[3], pts[0], pts[1]], 0.1, "2B", "#8C8175", 1.2);
      sSpline([pts[1], pts[2], pts[3]], 0.1, "2B", "#A69B8E", 0.9);

      // Bevel specular glint on handmade tile edge
      let bev0 = [lerp(pts[3][0], cx, 0.06), lerp(pts[3][1], cy, 0.06)];
      let bev1 = [lerp(pts[0][0], cx, 0.06), lerp(pts[0][1], cy, 0.06)];
      let bev2 = [lerp(pts[1][0], cx, 0.06), lerp(pts[1][1], cy, 0.06)];
      sSpline([bev0, bev1, bev2], 0.15, "specular", "#FFFDF9", 0.9);

      // Subtle painted corner Talavera accent on select countertop tiles
      if ((col + row * 2) % 3 === 0) {
        for (let k = 0; k < 4; k++) {
          let vx = lerp(pts[k][0], cx, 0.14);
          let vy = lerp(pts[k][1], cy, 0.14);
          sLine(vx - 3, vy, vx + 3, vy, "glaze_loaded", "#486FA8", 0.7);
        }
      }
    }
  }
}

// ============================================================================
// 2. SINK EXTERIOR SHADOW ON COUNTERTOP
// ============================================================================
function drawSinkExteriorShadow() {
  // Cast shadow down-right from the raised rolled ceramic rim
  for (let layer = 4; layer >= 1; layer--) {
    let expand = 1.155 + layer * 0.018;
    let shPts = [];
    for (let a = 0; a < 360; a += 6) {
      let p = bowlPoint(a, expand);
      // Offset more toward lower-right (away from upper-left sun)
      let sunPush = max(0, cos(a - 48)) * layer * 7.5;
      shPts.push([p[0] + layer * 3.2 + sunPush * 0.6, p[1] + layer * 4.2 + sunPush * 0.8]);
    }
    fPoly(shPts, layer > 2 ? "#9E9AA8" : "#6E6A7C", 38, 0.14, 0.25, 0.2);
  }

  // Crisp contact occlusion right under the outer ceramic lip
  let contactPts = [];
  for (let a = 0; a <= 360; a += 5) {
    let p = bowlPoint(a, 1.156);
    contactPts.push([p[0] + 1.5, p[1] + 2.5]);
  }
  sSpline(contactPts, 0.2, "charcoal", "#4A434E", 1.4);
}

// ============================================================================
// 3. MILKY WHITE TIN-GLAZE BASIN & 3D CONCAVE SHADING
// ============================================================================
function drawTinGlazeBasin() {
  // Opaque milky-white tin glaze foundation across entire sink
  let outerRimPts = [];
  for (let a = 0; a < 360; a += 5) {
    let p = bowlPoint(a, 1.155);
    outerRimPts.push([p[0], p[1]]);
  }
  wPoly(outerRimPts, "#F8F5EE", 250, 0.2);
  fPoly(outerRimPts, "#FAF7F2", 110, 0.04, 0.18, 0.2);

  // Build 3D concave bowl shading:
  // Upper-left interior wall faces away from upper-left sun -> cool pastel periwinkle/lavender shadow
  // Lower-right interior wall faces sun directly -> warm sunlit cream & blush ivory
  let rings = [0.98, 0.85, 0.70, 0.55, 0.40, 0.25];
  for (let rIdx = 0; rIdx < rings.length; rIdx++) {
    let rN = rings[rIdx];
    // Cool pastel shadow crescent on upper-left wall (angles 125 to 315)
    let coolPts = [];
    for (let a = 115; a <= 325; a += 8) {
      let p = bowlPoint(a, rN);
      coolPts.push([p[0], p[1]]);
    }
    for (let a = 325; a >= 115; a -= 8) {
      let p = bowlPoint(a, max(0.08, rN - 0.28));
      coolPts.push([p[0], p[1]]);
    }
    let shCol = rIdx % 2 === 0 ? "#D4DFEE" : "#DFD8EB";
    fPoly(coolPts, shCol, 42, 0.15, 0.22, 0.2);

    // Warm sunlit glow on lower-right concave wall (angles -45 to 125)
    let warmPts = [];
    for (let a = -50; a <= 130; a += 8) {
      let p = bowlPoint(a, rN);
      warmPts.push([p[0], p[1]]);
    }
    for (let a = 130; a >= -50; a -= 8) {
      let p = bowlPoint(a, max(0.08, rN - 0.28));
      warmPts.push([p[0], p[1]]);
    }
    fPoly(warmPts, "#FFFBF0", 55, 0.12, 0.15, 0.2);
  }

  // Deepening ambient shade near the bottom curve of the bowl
  let bottomPts = [];
  for (let a = 0; a < 360; a += 8) {
    let p = bowlPoint(a, 0.46);
    bottomPts.push([p[0], p[1]]);
  }
  fPoly(bottomPts, "#E5E2DC", 48, 0.14, 0.25, 0.2);

  // Rolled rim 3D shading: inner lip shadow & outer lip highlight
  let rimShadowPts = [];
  for (let a = -30; a <= 160; a += 6) {
    let p = bowlPoint(a, 1.14);
    rimShadowPts.push([p[0], p[1]]);
  }
  for (let a = 160; a >= -30; a -= 6) {
    let p = bowlPoint(a, 1.07);
    rimShadowPts.push([p[0], p[1]]);
  }
  fPoly(rimShadowPts, "#CCD4E2", 52, 0.1, 0.2, 0.2);

  // Subtle terracotta bisque warmth peeking through where tin glaze thins at the rim crest
  for (let a = 0; a < 360; a += 4) {
    let p1 = bowlPoint(a, 1.06);
    let p2 = bowlPoint(a + 3, 1.065);
    if (noise(a * 0.08) > 0.42) {
      sLine(p1[0], p1[1], p2[0], p2[1], "pastel_soft", "#EBD6C6", 0.55);
    }
  }

  // Delicate ceramic crazing (fine crackle network in the tin glaze)
  for (let i = 0; i < 28; i++) {
    let aStart = random(360);
    let rStart = random(0.22, 0.95);
    let crkPts = [];
    for (let s = 0; s < 5; s++) {
      let p = bowlPoint(aStart + s * random(-6, 6), constrain(rStart + s * random(-0.06, 0.06), 0.16, 1.1));
      crkPts.push([p[0], p[1]]);
    }
    sSpline(crkPts, 0.3, "2H", "#D8CFC4", 0.32);
  }

  // Characteristic Talavera tin-glaze pinholes (tiny craters from kiln firing)
  for (let i = 0; i < 240; i++) {
    let ang = random(360);
    let rN = sqrt(random(0.04, 1.25));
    if (rN > 1.14) continue;
    let p = bowlPoint(ang, rN);
    let pinSz = random(0.45, 1.15);
    // Warm terracotta/grey pinhole core
    sLine(p[0], p[1], p[0] + 0.6, p[1] + 0.4, "2B", "#7A685D", pinSz);
    // Minute white glaze lip on the sunlit side of the pinhole
    sLine(p[0] + 0.8, p[1] + 0.8, p[0] + 1.5, p[1] + 1.1, "specular", "#FFFFFF", pinSz * 0.7);
  }
}

// ============================================================================
// 4. HAND-PAINTED TALAVERA COBALT & OCHRE GLAZE MOTIFS
// ============================================================================

// Renders a single thick Talavera glaze brushstroke with watercolor flux bleed,
// rich mineral body, dark cobalt/ochre pooling at the stroke end, and glassy ridge highlight
function paintGlazeStroke(pts, style = "cobalt", wScale = 1.0) {
  if (!pts || pts.length < 2) return;

  let fluxCol, midCol, poolCol, ridgeLight;
  if (style === "cobalt") {
    fluxCol = "#7CA6D8";
    midCol = "#1C499C";
    poolCol = "#0A1E4E";
    ridgeLight = "#EBF5FF";
  } else if (style === "cobalt_soft") {
    fluxCol = "#96BBE4";
    midCol = "#3568B8";
    poolCol = "#143375";
    ridgeLight = "#F0F8FF";
  } else if (style === "ochre") {
    fluxCol = "#F2C678";
    midCol = "#D98224";
    poolCol = "#8A4406";
    ridgeLight = "#FFF8E6";
  } else if (style === "jade") {
    fluxCol = "#A3D4BE";
    midCol = "#4D8E72";
    poolCol = "#23523D";
    ridgeLight = "#EEFAF4";
  } else {
    // Terracotta rose pastel accent
    fluxCol = "#E8B4AC";
    midCol = "#C46458";
    poolCol = "#7A2E26";
    ridgeLight = "#FFF0EE";
  }

  // 1. Soft glaze flux halo bleeding into the tin glaze
  sSpline(pts, 0.35, "glaze_loaded", fluxCol, wScale * 1.25);

  // 2. Main thick mineral brush pass
  sSpline(pts, 0.35, "glaze_loaded", midCol, wScale * 0.92);

  // 3. Saturated dark pooling at the stroke terminus & lower ridge
  let n = pts.length;
  let poolPts = [];
  let startIdx = max(0, floor(n * 0.45));
  for (let i = startIdx; i < n; i++) {
    poolPts.push([pts[i][0] + 0.5, pts[i][1] + 0.7]);
  }
  if (poolPts.length >= 2) {
    sSpline(poolPts, 0.3, "glaze_ridge", poolCol, wScale * 1.15);
  }
  // Extra pooled bead right at the tip of the brushstroke
  let endP = pts[n - 1];
  sLine(endP[0] - 0.8, endP[1] - 0.5, endP[0] + 1.1, endP[1] + 0.9, "glaze_loaded", poolCol, wScale * 0.85);

  // 4. Crisp glassy ridge specular reflection along the upper-left edge of the raised glaze
  if (wScale >= 0.55 && n >= 2) {
    let hiPts = [];
    for (let i = 0; i < n; i++) {
      hiPts.push([pts[i][0] - 1.1 * wScale, pts[i][1] - 1.2 * wScale]);
    }
    sSpline(hiPts, 0.35, "specular", ridgeLight, wScale * 0.48);
  }
}

// Helper to paint a concentric hand-spun ceramic band around the bowl
function paintConcentricRing(rNorm, style = "cobalt", wScale = 0.85) {
  // Paint in overlapping arcs like a potter's brush on a wheel
  for (let a0 = 0; a0 < 360; a0 += 60) {
    let pts = [];
    for (let a = a0; a <= a0 + 64; a += 5) {
      let wobble = 0.0025 * sin(a * 4 + rNorm * 20);
      let p = bowlPoint(a, rNorm + wobble);
      pts.push([p[0], p[1]]);
    }
    paintGlazeStroke(pts, style, wScale);
  }
}

function drawTalaveraMotifs() {
  // --------------------------------------------------------------------------
  // BAND A: ROLLED RIM BORDER (rNorm = 1.00 .. 1.15)
  // --------------------------------------------------------------------------
  paintConcentricRing(1.135, "cobalt", 0.75);
  paintConcentricRing(1.005, "cobalt", 0.85);
  paintConcentricRing(0.978, "ochre", 0.65);

  // 36 bold comma-plumes & ochre arches along the rolled ceramic rim
  let rimCount = 36;
  for (let i = 0; i < rimCount; i++) {
    let aBase = i * (360 / rimCount);
    let aMid = aBase + 4.5;
    let aEnd = aBase + 8.2;

    // Thick cobalt S-plume stroke across the rim
    let p0 = bowlPoint(aBase + 0.8, 1.12);
    let p1 = bowlPoint(aMid, 1.07);
    let p2 = bowlPoint(aEnd, 1.025);
    paintGlazeStroke([p0, p1, p2], "cobalt", 0.82);

    // Alternating ochre & pastel-jade teardrop bud tucked beside each cobalt plume
    let pBud0 = bowlPoint(aBase + 5.2, 1.115);
    let pBud1 = bowlPoint(aBase + 7.5, 1.08);
    paintGlazeStroke([pBud0, pBud1], i % 2 === 0 ? "ochre" : "jade", 0.65);

    // Tiny terracotta/cobalt dot accent
    let pDot = bowlPoint(aBase + 2.2, 1.045);
    paintGlazeStroke([pDot, [pDot[0] + 1.2, pDot[1] + 1.0]], "rose", 0.45);
  }

  // --------------------------------------------------------------------------
  // BAND B: UPPER CONCAVE WALL — FEATHERED TALAVERA FLORAL MEDALLIONS & LATTICE
  // (rNorm = 0.67 .. 0.95)
  // --------------------------------------------------------------------------
  let numMedallions = 10;
  let stepA = 360 / numMedallions; // 36 deg per section

  for (let m = 0; m < numMedallions; m++) {
    let cA = m * stepA;

    // 1. Scalloped cobalt framing arch around each medallion
    let archPtsL = [];
    let archPtsR = [];
    for (let t = 0; t <= 1; t += 0.2) {
      let rN = lerp(0.955, 0.68, t);
      let dA = 11.5 * sin(t * 180) + 4.5 * (1 - t);
      archPtsL.push(bowlPoint(cA - dA, rN));
      archPtsR.push(bowlPoint(cA + dA, rN));
    }
    paintGlazeStroke(archPtsL, "cobalt", 0.68);
    paintGlazeStroke(archPtsR, "cobalt", 0.68);

    // 2. Central Talavera Blossom inside medallion (at cA, rNorm = 0.82)
    let fCenter = bowlPoint(cA, 0.82);
    // 8 radiating feathered petals ("plumas") around the flower center
    for (let k = 0; k < 8; k++) {
      let pAng = k * 45;
      let dTheta = cos(pAng) * 8.8;
      let dRad = sin(pAng) * 0.095;
      let ptStart = bowlPoint(cA + dTheta * 0.25, 0.82 + dRad * 0.25);
      let ptMid = bowlPoint(cA + dTheta * 0.68 + 1.8, 0.82 + dRad * 0.68);
      let ptTip = bowlPoint(cA + dTheta, 0.82 + dRad);

      // Watercolor glaze body inside petal
      let sideL = bowlPoint(cA + dTheta * 0.6 - sin(pAng) * 2.5, 0.82 + dRad * 0.6 + cos(pAng) * 0.025);
      let sideR = bowlPoint(cA + dTheta * 0.6 + sin(pAng) * 2.5, 0.82 + dRad * 0.6 - cos(pAng) * 0.025);
      fPoly([ptStart, sideL, ptTip, sideR], k % 2 === 0 ? "#4D7EC8" : "#F0B85C", 95, 0.08, 0.25, 0.25);

      paintGlazeStroke([ptStart, ptMid, ptTip], k % 2 === 0 ? "cobalt" : "ochre", 0.78);
    }
    // Ochre & rose flower heart
    let cPts = ellipsePts(fCenter[0], fCenter[1], 8.5, 6.8, SINK_ROT, 12);
    fPoly(cPts, "#E6952E", 160, 0.06, 0.2, 0.2);
    paintGlazeStroke([
      [fCenter[0] - 4, fCenter[1] - 2],
      [fCenter[0], fCenter[1] + 2],
      [fCenter[0] + 4, fCenter[1] - 1]
    ], "ochre", 0.75);

    // 3. Feathered cobalt foliage plumes ("hojas de pluma") flanking the blossom
    for (let side = -1; side <= 1; side += 2) {
      for (let f = 0; f < 3; f++) {
        let rLeaf = 0.73 + f * 0.07;
        let pStem = bowlPoint(cA + side * 6.5, rLeaf);
        let pCurve = bowlPoint(cA + side * (10.5 + f * 1.2), rLeaf + 0.025);
        let pTip = bowlPoint(cA + side * (13.2 + f * 1.4), rLeaf + 0.01);
        paintGlazeStroke([pStem, pCurve, pTip], "cobalt", 0.65);
      }
    }

    // 4. Diamond Cross-Hatch Lattice Panel between medallions (centered at cA + 18)
    let latA = cA + 18;
    for (let d = -2; d <= 2; d++) {
      let l1 = bowlPoint(latA - 5.5, constrain(0.81 + d * 0.045, 0.68, 0.94));
      let l2 = bowlPoint(latA + 5.5, constrain(0.81 + (d + 1.5) * 0.045, 0.68, 0.94));
      paintGlazeStroke([l1, l2], "cobalt_soft", 0.42);

      let r1 = bowlPoint(latA + 5.5, constrain(0.81 + d * 0.045, 0.68, 0.94));
      let r2 = bowlPoint(latA - 5.5, constrain(0.81 + (d + 1.5) * 0.045, 0.68, 0.94));
      paintGlazeStroke([r1, r2], "cobalt_soft", 0.42);
    }
    // Ochre & jade jewel dots inside lattice diamonds
    for (let rL = 0.73; rL <= 0.91; rL += 0.06) {
      let dPt = bowlPoint(latA, rL);
      paintGlazeStroke([dPt, [dPt[0] + 1.4, dPt[1] + 1.1]], "ochre", 0.55);
    }
  }

  // --------------------------------------------------------------------------
  // BAND C: MID-BOWL RINGS & INTERLACING MOORISH ARCHES (rNorm = 0.42 .. 0.65)
  // --------------------------------------------------------------------------
  paintConcentricRing(0.655, "cobalt", 0.85);
  paintConcentricRing(0.630, "ochre", 0.68);
  paintConcentricRing(0.608, "cobalt", 0.65);

  let numArches = 20;
  let archStep = 360 / numArches;
  for (let i = 0; i < numArches; i++) {
    let a0 = i * archStep;
    let aMid = a0 + archStep * 0.5;
    let a1 = a0 + archStep;

    // Moorish pointed arch sweeping from 0.60 down to 0.45
    let pL = bowlPoint(a0, 0.595);
    let pML = bowlPoint(a0 + archStep * 0.28, 0.50);
    let pApex = bowlPoint(aMid, 0.445);
    let pMR = bowlPoint(a0 + archStep * 0.72, 0.50);
    let pR = bowlPoint(a1, 0.595);

    // Soft cerulean watercolor fill inside alternating arches
    if (i % 2 === 0) {
      fPoly([pL, pML, pApex, pMR, pR], "#6D9AD0", 65, 0.09, 0.25, 0.2);
    } else {
      fPoly([pL, pML, pApex, pMR, pR], "#F2CA7E", 55, 0.09, 0.25, 0.2);
    }

    paintGlazeStroke([pL, pML, pApex], "cobalt", 0.72);
    paintGlazeStroke([pR, pMR, pApex], "cobalt", 0.72);

    // Suspended feathered drop inside each arch
    let dTop = bowlPoint(aMid, 0.575);
    let dMid = bowlPoint(aMid + 1.0, 0.53);
    let dBot = bowlPoint(aMid, 0.49);
    paintGlazeStroke([dTop, dMid, dBot], i % 2 === 0 ? "ochre" : "cobalt", 0.75);

    // Trio of pooled cobalt berries in the spandrel below the arches
    for (let b = -1; b <= 1; b++) {
      let bPt = bowlPoint(a0 + b * 2.4, 0.465 + abs(b) * 0.02);
      paintGlazeStroke([bPt, [bPt[0] + 1.1, bPt[1] + 1.1]], "cobalt", 0.52);
    }
  }

  paintConcentricRing(0.422, "cobalt", 0.8);
  paintConcentricRing(0.398, "ochre", 0.65);

  // --------------------------------------------------------------------------
  // BAND D: INNER ROSETTE AROUND THE DRAIN (rNorm = 0.16 .. 0.38)
  // --------------------------------------------------------------------------
  let numPetals = 24;
  for (let i = 0; i < numPetals; i++) {
    let a = i * (360 / numPetals);
    let pIn = bowlPoint(a, 0.175);
    let pMid = bowlPoint(a + 2.8, 0.275);
    let pOut = bowlPoint(a + 0.5, 0.372);

    let style = i % 3 === 0 ? "ochre" : (i % 3 === 1 ? "cobalt" : "jade");
    paintGlazeStroke([pIn, pMid, pOut], style, 0.78);
  }
  paintConcentricRing(0.165, "cobalt", 0.85);
}

// ============================================================================
// 5. RECESSED ANTIQUE BRASS DRAIN & SHALLOW WATER POOL
// ============================================================================
function drawBrassDrainAndWaterPool() {
  let dCenter = bowlPoint(0, 0);
  let dcx = dCenter[0];
  let dcy = dCenter[1];

  // Recessed shadow around drain lip
  let recessPts = ellipsePts(dcx, dcy, 58, 45, SINK_ROT, 32);
  fPoly(recessPts, "#4A4E58", 95, 0.08, 0.2, 0.2);

  // Antique brass flange ring
  let brassOuter = ellipsePts(dcx, dcy + 1.5, 54, 42, SINK_ROT, 32);
  wPoly(brassOuter, "#A8843E", 230, 0.2);
  fPoly(brassOuter, "#C8A456", 120, 0.05, 0.25, 0.2);

  // Tarnished bronze inner dish of drain
  let brassInner = ellipsePts(dcx, dcy + 2.5, 42, 32, SINK_ROT, 28);
  wPoly(brassInner, "#6E5222", 210, 0.2);
  fPoly(brassInner, "#4A3514", 130, 0.06, 0.3, 0.2);

  // Metallic specular arcs on brass drain rim
  sArc(dcx, dcy + 1.5, 48, 195, 330, "glaze_ridge", "#3B280D", 1.3);
  sArc(dcx, dcy + 1.5, 47, 15, 145, "specular", "#FFF8E2", 1.25);
  sArc(dcx, dcy + 2.5, 36, 200, 340, "specular", "#FCE8B2", 0.95);

  // Drain strainer holes (center + 8 surrounding perforations)
  let holeOffsets = [[0, 0]];
  for (let k = 0; k < 8; k++) {
    let a = k * 45;
    holeOffsets.push([cos(a) * 22, sin(a) * 17]);
  }
  for (let h = 0; h < holeOffsets.length; h++) {
    let hx = dcx + holeOffsets[h][0];
    let hy = dcy + 2.5 + holeOffsets[h][1];
    let hPts = ellipsePts(hx, hy, 5.8, 4.5, SINK_ROT, 12);
    wPoly(hPts, "#161412", 245, 0.2);
    // Tiny wet highlight on lower rim of each drain hole
    sArc(hx, hy, 5.2, 20, 150, "specular", "#FFF6DC", 0.65);
  }

  // Shallow clear water puddle pooled in the bottom of the basin (rNorm = 0 .. 0.44)
  let poolPts = [];
  for (let a = 0; a < 360; a += 8) {
    let rWobble = 0.42 + 0.03 * sin(a * 3 + 40);
    let p = bowlPoint(a, rWobble);
    poolPts.push([p[0], p[1]]);
  }
  fPoly(poolPts, "#D4F0EC", 28, 0.12, 0.15, 0.2);

  // Bright meniscus highlight & caustic lines along the water pool edge
  for (let a = 0; a < 360; a += 45) {
    let mPts = [];
    for (let da = 0; da <= 30; da += 6) {
      let rW = 0.42 + 0.03 * sin((a + da) * 3 + 40);
      let p = bowlPoint(a + da, rW);
      mPts.push([p[0], p[1]]);
    }
    sSpline(mPts, 0.3, "specular", "#FFFFFF", 0.75);
  }
}

// ============================================================================
// 6. THREE CUT PERSIAN LIMES (HYPERREAL BOTANICAL RENDERING)
// ============================================================================
function drawSingleCutLime(cx, cy, radius, tilt, rotDeg, showRindSide = "bottom", numSegs = 10) {
  let c = cos(rotDeg);
  let s = sin(rotDeg);
  let rx = radius;
  let ry = radius * tilt;

  // Helper to transform lime-local coordinates (lx, ly) to canvas
  function lPt(lx, ly) {
    return [cx + lx * c - ly * s, cy + lx * s + ly * c];
  }

  // 1. Cast shadow + translucent green-gold caustic reflection on the Talavera glaze
  let shPts = ellipsePts(cx + 14, cy + 18, rx * 1.05, ry * 1.05, rotDeg, 28);
  fPoly(shPts, "#2A3E48", 95, 0.14, 0.25, 0.2);
  let causticPts = ellipsePts(cx + 22, cy + 25, rx * 0.75, ry * 0.72, rotDeg, 24);
  fPoly(causticPts, "#B8E66C", 65, 0.16, 0.2, 0.2);

  // 2. Rounded Persian lime rind dome (underneath the cut face)
  let rindOffset = showRindSide === "right" ? [16, 20] : [-10, 24];
  let rindCrescent = [];
  let aStart = showRindSide === "right" ? -45 : 15;
  let aEnd = showRindSide === "right" ? 155 : 205;

  for (let a = aStart; a <= aEnd; a += 8) {
    rindCrescent.push(lPt(cos(a) * rx, sin(a) * ry));
  }
  for (let a = aEnd; a >= aStart; a -= 8) {
    let domeDepth = sin( map(a, aStart, aEnd, 0, 180) );
    rindCrescent.push(lPt(
      cos(a) * rx * 0.96 + rindOffset[0] * domeDepth,
      sin(a) * ry * 0.96 + rindOffset[1] * domeDepth * 1.35
    ));
  }
  // Base emerald-lime peel wash
  wPoly(rindCrescent, "#437C34", 240, 0.2);
  fPoly(rindCrescent, "#629E42", 130, 0.08, 0.25, 0.2);

  // Shadow & sunlit chartreuse glow on the curved rind
  let rindShadow = [];
  for (let a = aStart + 30; a <= aEnd - 15; a += 10) {
    let d = sin(map(a, aStart, aEnd, 0, 180));
    rindShadow.push(lPt(cos(a) * rx * 0.9 + rindOffset[0] * d * 0.85, sin(a) * ry * 0.9 + rindOffset[1] * d * 1.2));
  }
  if (rindShadow.length >= 3) {
    fPoly(rindShadow, "#204A1E", 110, 0.12, 0.3, 0.2);
  }

  // Stippled citrus oil-gland dimples on the rind
  for (let i = 0; i < 65; i++) {
    let a = random(aStart + 8, aEnd - 8);
    let d = sin(map(a, aStart, aEnd, 0, 180)) * random(0.25, 0.9);
    let gp = lPt(cos(a) * rx * 0.95 + rindOffset[0] * d, sin(a) * ry * 0.95 + rindOffset[1] * d * 1.25);
    sLine(gp[0], gp[1], gp[0] + 0.7, gp[1] + 0.5, "2B", "#183816", 0.9);
    if (i % 3 === 0) {
      sLine(gp[0] - 0.6, gp[1] - 0.6, gp[0], gp[1], "specular", "#DCFA98", 0.55);
    }
  }

  // 3. Outer dark-green cuticle ring of the flat cut face
  let outerFace = ellipsePts(cx, cy, rx, ry, rotDeg, 36, 0.015);
  wPoly(outerFace, "#4E8A38", 245, 0.2);

  // 4. Creamy white-pastel pith ring (albedo)
  let pithFace = ellipsePts(cx, cy, rx * 0.94, ry * 0.94, rotDeg, 36, 0.015);
  wPoly(pithFace, "#F3F7E2", 248, 0.2);
  fPoly(pithFace, "#E5ECD0", 90, 0.05, 0.2, 0.2);

  // 5. Radial translucent Persian lime juice segments
  let segStep = 360 / numSegs;
  for (let sIdx = 0; sIdx < numSegs; sIdx++) {
    let a0 = sIdx * segStep + 3.2;
    let a1 = (sIdx + 1) * segStep - 3.2;
    let aMid = (a0 + a1) * 0.5;

    // Build rounded wedge polygon for this juice segment
    let segPts = [];
    // Inner apex near central pith core
    segPts.push(lPt(cos(aMid) * rx * 0.11, sin(aMid) * ry * 0.11));
    // Left radial membrane wall
    for (let rF = 0.22; rF <= 0.80; rF += 0.28) {
      segPts.push(lPt(cos(a0) * rx * rF, sin(a0) * ry * rF));
    }
    // Rounded outer arc against pith
    for (let a = a0 + 2; a <= a1 - 2; a += 5) {
      segPts.push(lPt(cos(a) * rx * 0.86, sin(a) * ry * 0.86));
    }
    // Right radial membrane wall
    for (let rF = 0.80; rF >= 0.22; rF -= 0.28) {
      segPts.push(lPt(cos(a1) * rx * rF, sin(a1) * ry * rF));
    }

    // Translucent pastel lime-jade base fill
    let segCol = sIdx % 2 === 0 ? "#9AD15E" : "#8CC452";
    wPoly(segPts, segCol, 225, 0.18);
    fPoly(segPts, "#B8E878", 110, 0.06, 0.22, 0.18);

    // Deeper emerald-olive shading near segment perimeter for subsurface depth
    let deepArc = [];
    for (let a = a0 + 3; a <= a1 - 3; a += 6) {
      deepArc.push(lPt(cos(a) * rx * 0.84, sin(a) * ry * 0.84));
    }
    for (let a = a1 - 3; a >= a0 + 3; a -= 6) {
      deepArc.push(lPt(cos(a) * rx * 0.62, sin(a) * ry * 0.62));
    }
    fPoly(deepArc, "#5B9132", 95, 0.08, 0.25, 0.15);

    // Individual radial juice vesicles (glistening pulp sacs) inside the segment!
    for (let v = 0; v < 14; v++) {
      let vAng = random(a0 + 3, a1 - 3);
      let vR1 = random(0.18, 0.58);
      let vR2 = vR1 + random(0.14, 0.24);
      let vp1 = lPt(cos(vAng) * rx * vR1, sin(vAng) * ry * vR1);
      let vp2 = lPt(cos(vAng) * rx * vR2, sin(vAng) * ry * vR2);
      let vCol = v % 3 === 0 ? "#D8F69E" : (v % 3 === 1 ? "#6DA33B" : "#B2E26B");
      sLine(vp1[0], vp1[1], vp2[0], vp2[1], "glaze_loaded", vCol, 0.48);
    }

    // Crisp wet specular glints on cut juice vesicles
    for (let h = 0; h < 4; h++) {
      let hAng = lerp(a0 + 5, a1 - 5, (h + 0.5) / 4);
      let hR = random(0.32, 0.74);
      let hp1 = lPt(cos(hAng) * rx * hR, sin(hAng) * ry * hR);
      let hp2 = lPt(cos(hAng + 2.5) * rx * (hR + 0.06), sin(hAng + 2.5) * ry * (hR + 0.06));
      sLine(hp1[0], hp1[1], hp2[0], hp2[1], "specular", "#FFFFFF", 0.72);
    }

    // Creamy-white radial segment membrane line
    let mIn = lPt(cos(a0 - 1.6) * rx * 0.09, sin(a0 - 1.6) * ry * 0.09);
    let mOut = lPt(cos(a0 - 1.6) * rx * 0.88, sin(a0 - 1.6) * ry * 0.88);
    sLine(mIn[0], mIn[1], mOut[0], mOut[1], "glaze_ridge", "#F4F8E6", 0.82);
  }

  // 6. Central creamy pith columella core
  let corePts = ellipsePts(cx, cy, rx * 0.12, ry * 0.12, rotDeg, 14, 0.2);
  wPoly(corePts, "#F4F7E4", 245, 0.2);
  sLine(cx - 2, cy - 1, cx + 2, cy + 1, "2B", "#C8D2B0", 0.7);

  // Wet gloss ring along the sun-facing cut bevel
  let glossPts = [];
  for (let a = 195; a <= 335; a += 10) {
    glossPts.push(lPt(cos(a) * rx * 0.89, sin(a) * ry * 0.89));
  }
  sSpline(glossPts, 0.3, "specular", "#FFFFFF", 0.95);
}

function drawPersianLimes() {
  // Lime 1: Prominent cut half resting on the left-center basin slope
  drawSingleCutLime(482, 646, 76, 0.82, -16, "bottom", 10);

  // Lime 2: Cut half angled on the lower-right basin wall showing lush green rind
  drawSingleCutLime(718, 722, 72, 0.75, 28, "right", 10);

  // Lime 3: Cut half nestled near the drain in the shallow water puddle
  drawSingleCutLime(568, 784, 65, 0.78, 9, "bottom", 9);
}

// ============================================================================
// 7. BEAD-FILLED SOAP DISH (UPPER-LEFT COUNTERTOP)
// ============================================================================
function drawBeadSoapDish() {
  let dcx = 235;
  let dcy = 252;
  let drx = 122;
  let dry = 92;
  let dRot = 22;
  let c = cos(dRot);
  let s = sin(dRot);

  function dPt(lx, ly) {
    return [dcx + lx * c - ly * s, dcy + lx * s + ly * c];
  }

  // 1. Cast shadow of the ceramic soap dish on the tiled countertop
  for (let l = 3; l >= 1; l--) {
    let shPts = ellipsePts(dcx + l * 6.5, dcy + l * 8.5, drx + l * 4, dry + l * 3, dRot, 32);
    fPoly(shPts, "#7C7584", 52, 0.14, 0.25, 0.2);
  }

  // 2. Scalloped/fluted handmade pastel ceramic dish rim
  let numFlutes = 18;
  let outerDishPts = [];
  for (let i = 0; i < numFlutes * 3; i++) {
    let a = (i / (numFlutes * 3)) * 360;
    let scallop = 1 + 0.038 * cos(a * numFlutes);
    outerDishPts.push(dPt(cos(a) * drx * scallop, sin(a) * dry * scallop));
  }
  wPoly(outerDishPts, "#EBF1ED", 248, 0.25);
  fPoly(outerDishPts, "#D4E2DC", 95, 0.06, 0.22, 0.25);

  // Fluted radial shading ribs along the dish border
  for (let i = 0; i < numFlutes; i++) {
    let a = i * (360 / numFlutes);
    let pOut = dPt(cos(a) * drx * 1.02, sin(a) * dry * 1.02);
    let pIn = dPt(cos(a) * drx * 0.74, sin(a) * dry * 0.74);
    sLine(pOut[0], pOut[1], pIn[0], pIn[1], "2B", "#B0C0B8", 0.75);
    let aHi = a + 8;
    let hOut = dPt(cos(aHi) * drx * 0.98, sin(aHi) * dry * 0.98);
    let hIn = dPt(cos(aHi) * drx * 0.78, sin(aHi) * dry * 0.78);
    sLine(hOut[0], hOut[1], hIn[0], hIn[1], "specular", "#FFFFFF", 0.65);
  }

  // Hand-painted ochre & cobalt rim accent on the soap dish
  sSpline(outerDishPts.concat([outerDishPts[0]]), 0.25, "glaze_loaded", "#D88E2E", 0.62);

  // Recessed interior well of the soap dish
  let wellPts = ellipsePts(dcx, dcy + 2, drx * 0.78, dry * 0.78, dRot, 32);
  wPoly(wellPts, "#C6D4CE", 220, 0.2);
  fPoly(wellPts, "#9EAEB8", 90, 0.1, 0.25, 0.2);

  // 3. Translucent Pastel Soap & Bath Beads packed in the dish
  let beadPalettes = [
    { base: "#B2E2D4", shade: "#5E9688", glow: "#E2FFF6" }, // Seafoam jade
    { base: "#F4C6CA", shade: "#AC6E76", glow: "#FFE8EC" }, // Blush rose quartz
    { base: "#F8E59E", shade: "#B49642", glow: "#FFF8D6" }, // Buttercup lemon
    { base: "#D6CAE8", shade: "#8274A2", glow: "#F2ECFF" }, // Lavender milk
    { base: "#B6DCF2", shade: "#5E8CAE", glow: "#E8F6FF" }, // Pastel cerulean
    { base: "#F8F4EC", shade: "#A8A096", glow: "#FFFFFF" }  // Pearl white
  ];

  // Generate organically packed mound of ~62 beads, sorted back-to-front by screen Y
  let beads = [];
  let rings = [
    { rFrac: 0.64, count: 20, sz: 11.5 },
    { rFrac: 0.44, count: 15, sz: 12.8 },
    { rFrac: 0.25, count: 9, sz: 13.5 },
    { rFrac: 0.07, count: 3, sz: 14.2 },
    // Upper layer of mounded beads
    { rFrac: 0.50, count: 11, sz: 11.8, zLift: 6 },
    { rFrac: 0.22, count: 6, sz: 13.0, zLift: 10 }
  ];

  let bCounter = 0;
  for (let rObj of rings) {
    for (let k = 0; k < rObj.count; k++) {
      let a = k * (360 / rObj.count) + (rObj.zLift ? 15 : 0) + random(-7, 7);
      let rf = rObj.rFrac + random(-0.04, 0.04);
      let bp = dPt(cos(a) * drx * rf, sin(a) * dry * rf);
      let lift = rObj.zLift || 0;
      beads.push({
        x: bp[0],
        y: bp[1] - lift,
        r: rObj.sz * random(0.88, 1.12),
        pal: beadPalettes[bCounter % beadPalettes.length]
      });
      bCounter++;
    }
  }

  beads.sort((a, b) => a.y - b.y);

  for (let b of beads) {
    // Contact occlusion shadow between beads
    let occPts = ellipsePts(b.x + 2.2, b.y + 3.0, b.r * 1.02, b.r * 0.96, 0, 14);
    fPoly(occPts, "#4A4856", 95, 0.08, 0.2, 0.2);

    // Spherical bead body
    let bPts = ellipsePts(b.x, b.y, b.r, b.r * 0.96, 0, 16);
    wPoly(bPts, b.pal.base, 235, 0.2);
    fPoly(bPts, b.pal.base, 110, 0.05, 0.15, 0.2);

    // Crescent shadow on lower-right of bead
    sArc(b.x, b.y, b.r * 0.78, 15, 145, "glaze_loaded", b.pal.shade, b.r * 0.08);

    // Translucent subsurface caustic glow inside the lower-right core of the bead
    let glowPts = ellipsePts(b.x + b.r * 0.22, b.y + b.r * 0.22, b.r * 0.45, b.r * 0.42, 0, 10);
    fPoly(glowPts, b.pal.glow, 130, 0.08, 0.1, 0.2);

    // Crisp white specular highlight on upper-left of bead
    let hx = b.x - b.r * 0.34;
    let hy = b.y - b.r * 0.34;
    sLine(hx - 1.2, hy + 0.5, hx + 1.4, hy - 0.8, "specular", "#FFFFFF", b.r * 0.11);
    // Secondary rim reflection
    sArc(b.x, b.y, b.r * 0.86, 25, 110, "specular", "#FFFFFF", 0.45);
  }
}

// ============================================================================
// 8. SHUTTERED MEXICAN MIDDAY SUNLIGHT & 3D-WARPED SHADOW SLATS
// ============================================================================
function drawShutteredWindowLight() {
  // Diagonal shutter slats oriented so normal u is along 62 deg (slats run at -28 deg)
  // On the flat countertop, slats are straight; inside the concave sink, they curve with z!
  let period = 138;
  let cU = cos(62);
  let sU = sin(62);
  let cT = cos(-28);
  let sT = sin(-28);

  // Iterate over each shutter shadow band across the canvas
  for (let bandIdx = -3; bandIdx <= 12; bandIdx++) {
    let uShadowStart = bandIdx * period + 76;
    let uShadowEnd = (bandIdx + 1) * period + 2;
    let uSunMid = bandIdx * period + 38;

    // Sample points along the slat direction t from -800 to 1600
    let topEdge = [];
    let botEdge = [];
    for (let t = -750; t <= 1550; t += 24) {
      // Base world point for top and bottom edge of shadow band
      let wx1 = uShadowStart * cU + t * cT;
      let wy1 = uShadowStart * sU + t * sT;
      let z1 = estimateSurfaceZ(wx1, wy1);
      // Apply 3D depth displacement so shadow bends down into the concave bowl!
      let sx1 = wx1 - z1 * 0.44;
      let sy1 = wy1 - z1 * 0.54;
      topEdge.push([sx1, sy1]);

      let wx2 = uShadowEnd * cU + t * cT;
      let wy2 = uShadowEnd * sU + t * sT;
      let z2 = estimateSurfaceZ(wx2, wy2);
      let sx2 = wx2 - z2 * 0.44;
      let sy2 = wy2 - z2 * 0.54;
      botEdge.push([sx2, sy2]);
    }

    let shadowPoly = topEdge.concat(botEdge.slice().reverse());
    // Cool pastel periwinkle-lavender shutter shadow glaze
    fPoly(shadowPoly, "#6E78A8", 44, 0.12, 0.18, 0.2);
    fPoly(shadowPoly, "#8A82B0", 26, 0.16, 0.15, 0.2);

    // Warm golden-white midday sunbeam boost along the sunlit slat
    let sunRibbon = [];
    for (let t = -700; t <= 1500; t += 40) {
      let wx = uSunMid * cU + t * cT;
      let wy = uSunMid * sU + t * sT;
      if (wx < -20 || wx > 1220 || wy < -20 || wy > 1220) continue;
      let z = estimateSurfaceZ(wx, wy);
      sunRibbon.push([wx - z * 0.44, wy - z * 0.54]);
    }
    if (sunRibbon.length >= 2) {
      sSpline(sunRibbon, 0.3, "pastel_soft", "#FFFDF2", 1.8);
    }
  }
}

// ============================================================================
// 9. OVERHANGING ANTIQUE BRASS TAP & DRIPPING WATER SEQUENCE
// ============================================================================
function drawBrassTapAndDrips() {
  // 1. Cast shadow of the brass tap onto the countertop tiles & sink rim
  let tapShadowPts = [
    [995, 245], [1075, 295], [890, 390], [725, 520], [700, 500], [860, 355]
  ];
  fPoly(tapShadowPts, "#4A4658", 68, 0.16, 0.25, 0.25);

  // 2. Deck-mounted octagonal/bell brass escutcheon base at (985, 228)
  let baseCx = 985;
  let baseCy = 228;
  let escOuter = ellipsePts(baseCx, baseCy, 56, 44, SINK_ROT, 24);
  wPoly(escOuter, "#8C6828", 245, 0.2);
  fPoly(escOuter, "#4E3612", 120, 0.06, 0.25, 0.2);

  let escMid = ellipsePts(baseCx - 2, baseCy - 6, 44, 34, SINK_ROT, 24);
  wPoly(escMid, "#C99B42", 245, 0.2);
  sArc(baseCx - 2, baseCy - 6, 40, 185, 325, "specular", "#FFF9E6", 1.4);
  sArc(baseCx, baseCy, 52, 15, 145, "glaze_ridge", "#38240A", 1.5);

  // Subtle verdigris patina ring at the base joint
  sArc(baseCx, baseCy + 2, 54, 30, 160, "glaze_loaded", "#689882", 0.75);

  // 3. Curved Swan-Neck Brass Spout overhanging the sink from (982, 212) to (665, 435)
  let spine = [
    [982, 212],
    [945, 162],
    [872, 134],
    [785, 158],
    [716, 238],
    [678, 342],
    [665, 435]
  ];
  let radii = [24, 22, 21, 20, 19, 18.5, 21];

  // Build left and right tube contours from normals
  let upperEdge = [];
  let lowerEdge = [];
  for (let i = 0; i < spine.length; i++) {
    let pPrev = spine[max(0, i - 1)];
    let pNext = spine[min(spine.length - 1, i + 1)];
    let dx = pNext[0] - pPrev[0];
    let dy = pNext[1] - pPrev[1];
    let len = max(1, sqrt(dx * dx + dy * dy));
    let nx = -dy / len;
    let ny = dx / len;
    // Ensure normal points toward upper-left sun
    if (ny > 0) {
      nx = -nx;
      ny = -ny;
    }
    let r = radii[i];
    upperEdge.push([spine[i][0] + nx * r, spine[i][1] + ny * r]);
    lowerEdge.push([spine[i][0] - nx * r, spine[i][1] - ny * r]);
  }

  let pipePoly = upperEdge.concat(lowerEdge.slice().reverse());
  // Solid warm brass foundation
  wPoly(pipePoly, "#C6963E", 250, 0.25);
  fPoly(pipePoly, "#DDAEE5", 25, 0.06, 0.2, 0.25);
  fPoly(pipePoly, "#D8AA4E", 140, 0.05, 0.22, 0.25);

  // Longitudinal metallic reflection bands along the curved brass tube
  function offsetSpine(frac) {
    let pts = [];
    for (let i = 0; i < spine.length; i++) {
      pts.push([
        lerp(lowerEdge[i][0], upperEdge[i][0], frac),
        lerp(lowerEdge[i][1], upperEdge[i][1], frac)
      ]);
    }
    return pts;
  }

  // Dark bronze core shadow band
  sSpline(offsetSpine(0.28), 0.35, "glaze_loaded", "#3B260E", 2.2);
  sSpline(offsetSpine(0.18), 0.35, "glaze_loaded", "#5C3E18", 1.6);
  // Reflected Talavera cobalt & lime bounce light along the underside of the brass spout!
  sSpline(offsetSpine(0.08), 0.35, "glaze_loaded", "#486EA6", 1.15);
  sSpline(offsetSpine(0.12).slice(3), 0.35, "glaze_loaded", "#82B464", 0.95);
  // Rich golden mid-band
  sSpline(offsetSpine(0.55), 0.35, "glaze_loaded", "#E6BC62", 1.9);
  // Pastel sky reflection band near top edge
  sSpline(offsetSpine(0.88), 0.35, "glaze_loaded", "#D8E8F4", 1.1);
  // Razor-sharp cream-white sun specular highlight along upper crest
  sSpline(offsetSpine(0.76), 0.35, "specular", "#FFFDF6", 1.65);
  sSpline(offsetSpine(0.79), 0.35, "specular", "#FFFFFF", 1.1);

  // Decorative brass collar rings at nozzle tip (665, 435) and neck
  let nozCx = 665;
  let nozCy = 435;
  let nozCollar = ellipsePts(nozCx + 2, nozCy - 12, 23, 11, -8, 20);
  wPoly(nozCollar, "#B88832", 240, 0.2);
  sSpline(nozCollar, 0.2, "glaze_ridge", "#422B0E", 1.1);
  sArc(nozCx + 2, nozCy - 12, 21, 180, 340, "specular", "#FFFDF4", 1.15);

  // Dark nozzle opening & wet inner brass rim
  let nozMouth = ellipsePts(nozCx, nozCy, 20, 9.5, -8, 20);
  wPoly(nozMouth, "#2C1E0C", 250, 0.2);
  sArc(nozCx, nozCy, 19, 10, 170, "specular", "#FFF9E2", 1.1);

  // 4. Antique Brass Cross-Handle Valve at (1018, 178)
  let hCx = 1018;
  let hCy = 178;
  let spokes = [[-46, -18], [46, 18], [-18, 36], [18, -36]];
  for (let sp of spokes) {
    let sx = hCx + sp[0];
    let sy = hCy + sp[1];
    sLine(hCx, hCy, sx, sy, "glaze_loaded", "#4A3212", 2.4);
    sLine(hCx, hCy - 2, sx, sy - 2, "glaze_loaded", "#D6A84E", 1.8);
    sLine(hCx - 1, hCy - 3, sx - 1, sy - 3, "specular", "#FFFDF4", 0.95);
    // Turned brass finial knob at end of spoke
    let kPts = ellipsePts(sx, sy, 10, 8, 0, 12);
    wPoly(kPts, "#C8983E", 245, 0.2);
    sArc(sx, sy, 8, 190, 330, "specular", "#FFFFFF", 0.9);
  }
  // Porcelain index cap in center of cross-handle
  let capPts = ellipsePts(hCx, hCy - 2, 16, 12.5, SINK_ROT, 16);
  wPoly(capPts, "#FAF6EE", 250, 0.2);
  sArc(hCx, hCy - 2, 12, 0, 360, "glaze_ridge", "#1C499C", 0.75);
  sLine(hCx - 5, hCy - 5, hCx + 2, hCy - 6, "specular", "#FFFFFF", 0.9);

  // --------------------------------------------------------------------------
  // 5. DRIPPING WATER SEQUENCE FROM THE BRASS SPOUT
  // --------------------------------------------------------------------------
  // (a) Pendant water drop stretching from the brass nozzle at (665, 442 .. 476)
  let pendPts = [
    [656, 439], [659, 454], [655, 468], [665, 479], [675, 468], [671, 454], [674, 439]
  ];
  fPoly(pendPts, "#D8F2F8", 115, 0.04, 0.1, 0.3);
  sSpline([[656, 439], [659, 454], [655, 468], [665, 479]], 0.35, "glaze_ridge", "#2E4A62", 0.95);
  sSpline([[674, 439], [671, 454], [675, 468], [665, 479]], 0.35, "glaze_ridge", "#5C8AA8", 0.8);
  // Refracted warm brass & lime glow inside pendant drop
  fPoly(ellipsePts(667, 469, 6.5, 7.5, 0, 12), "#E8F8C8", 150, 0.05, 0.1, 0.2);
  // Razor-sharp vertical specular line on pendant drop
  sSpline([[660, 443], [661, 456], [659, 469]], 0.3, "specular", "#FFFFFF", 1.25);
  sArc(665, 469, 8.5, 20, 130, "specular", "#FFFFFF", 0.85);

  // (b) Tiny satellite micro-droplet at (664, 498)
  drawWaterDroplet(664, 498, 3.2, 4.0, 0, "#B8D8E8", false);

  // (c) Mid-air falling teardrop at (662, 536)
  let fall1 = [
    [662, 520], [654, 534], [656, 545], [662, 549], [668, 545], [670, 534]
  ];
  fPoly(fall1, "#DCF4FA", 130, 0.04, 0.1, 0.3);
  sSpline([[662, 520], [654, 534], [662, 549]], 0.35, "glaze_ridge", "#24445C", 0.9);
  fPoly(ellipsePts(664, 541, 5.5, 6.5, 0, 10), "#FFFFFF", 160, 0.04, 0.1, 0.2);
  sLine(658, 529, 658, 542, "specular", "#FFFFFF", 1.3);

  // (d) Second falling drop just above impact at (660, 596)
  drawWaterDroplet(660, 596, 6.2, 8.2, 0, "#9CC8E0", false);

  // (e) Concentric impact ripples & crown splash in the basin water at (658, 636)
  let impX = 658;
  let impY = 636;
  let rippleRadii = [12, 24, 39, 58, 82];
  for (let rIdx = 0; rIdx < rippleRadii.length; rIdx++) {
    let rr = rippleRadii[rIdx];
    let ripShadow = ellipsePts(impX, impY + 1.5, rr, rr * 0.76, SINK_ROT, 28);
    sSpline(ripShadow, 0.25, "glaze_ridge", "#4A789C", (5 - rIdx) * 0.22);

    let ripHi = [];
