    }
    sSpline(ripHi, 0.3, "specular", "#FFFFFF", (5 - rIdx) * 0.26);

    let ripHiBack = [];
    for (let a = 195; a <= 315; a += 10) {
      ripHiBack.push([impX + cos(a) * rr, impY + sin(a) * rr * 0.76]);
    }
    sSpline(ripHiBack, 0.3, "specular", "#F0FAFF", (5 - rIdx) * 0.2);
  }
  // Splash crown micro-beads kicking up around impact center
  let crownOffsets = [[-11, -8], [12, -7], [-6, -13], [7, -12], [0, -15]];
  for (let co of crownOffsets) {
    sLine(impX + co[0] * 0.5, impY + co[1] * 0.3, impX + co[0], impY + co[1], "specular", "#FFFFFF", 0.85);
    drawWaterDroplet(impX + co[0], impY + co[1] - 2, 2.4, 2.6, 0, "#D8F0FA", false);
  }
}

// ============================================================================
// 10. HYPERREAL WATER DROPLETS (CRISP HIGHLIGHT, SHADOW & INTERNAL REFRACTION)
// ============================================================================
function drawWaterDroplet(x, y, rx, ry, rotDeg = 0, causticCol = "#E8F6FF", hasCastShadow = true) {
  let c = cos(rotDeg);
  let s = sin(rotDeg);

  // 1. Cast shadow on the down-right side (away from upper-left sun)
  if (hasCastShadow) {
    let shPts = ellipsePts(x + rx * 0.42, y + ry * 0.48, rx * 0.95, ry * 0.92, rotDeg, 14);
    fPoly(shPts, "#243248", 92, 0.06, 0.15, 0.2);
  }

  // 2. Darkened upper-left interior meniscus (light refracts away from upper-left entry)
  let bodyPts = ellipsePts(x, y, rx, ry, rotDeg, 16);
  fPoly(bodyPts, "#526E8C", 55, 0.03, 0.1, 0.2);

  // Crisp dark upper-left contour edge
  let ulArc = [];
  for (let a = 155; a <= 305; a += 18) {
    let lx = cos(a) * rx;
    let ly = sin(a) * ry;
    ulArc.push([x + lx * c - ly * s, y + lx * s + ly * c]);
  }
  sSpline(ulArc, 0.3, "glaze_ridge", "#1C2D42", constrain(rx * 0.11, 0.35, 0.95));

  // 3. Focused internal caustic refraction on the lower-right interior of the droplet!
  let caustPts = ellipsePts(x + rx * 0.24, y + ry * 0.24, rx * 0.62, ry * 0.58, rotDeg, 12);
  wPoly(caustPts, causticCol, 185, 0.2);
  fPoly(caustPts, "#FFFFFF", 130, 0.04, 0.1, 0.2);

  // 4. Secondary reflected light crescent along the bottom-right rim
  let lrArc = [];
  for (let a = -15; a <= 115; a += 18) {
    let lx = cos(a) * rx * 0.92;
    let ly = sin(a) * ry * 0.92;
    lrArc.push([x + lx * c - ly * s, y + lx * s + ly * c]);
  }
  sSpline(lrArc, 0.3, "specular", "#FFFFFF", constrain(rx * 0.09, 0.3, 0.8));

  // 5. Razor-sharp primary pinpoint sun highlight on the upper-left dome
  let hx = x - rx * 0.36;
  let hy = y - ry * 0.36;
  sLine(hx - rx * 0.15, hy + ry * 0.08, hx + rx * 0.18, hy - ry * 0.12, "specular", "#FFFFFF", constrain(rx * 0.22, 0.55, 1.55));
  if (rx >= 5.0) {
    // Tiny secondary window-slat highlight dot beside primary highlight
    sLine(hx + rx * 0.25, hy + ry * 0.12, hx + rx * 0.35, hy + ry * 0.08, "specular", "#FFFFFF", rx * 0.12);
  }
}

