function draw() {
  translate(-width / 2, -height / 2);

  // Dense velvety black woodblock ink ground
  background("#0a0908");
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noField();

  // Palette: white-line wood engraving with warm bone ivory & muted earth lowlights
  const PAL = {
    ink: "#0a0908",
    earthDeep: "#4d4339",
    earthLow: "#6e6154",
    earthMid: "#948575",
    putty: "#b8a996",
    parchment: "#d6c8b6",
    ivory: "#ece2d2",
    bone: "#faf5ed"
  };

  // --- GEOMETRY & SHARED BOUNDARY CURVES ---
  function bPt(p0, p1, p2, p3, t) {
    const mt = 1 - t;
    const mt2 = mt * mt;
    const t2 = t * t;
    return [
      mt2 * mt * p0[0] + 3 * mt2 * t * p1[0] + 3 * mt * t2 * p2[0] + t2 * t * p3[0],
      mt2 * mt * p0[1] + 3 * mt2 * t * p1[1] + 3 * mt * t2 * p2[1] + t2 * t * p3[1]
    ];
  }

  function lerpPt(a, b, t) {
    return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t];
  }

  function makeCoons(cBot, cTop, cLeft, cRight, bulgeFn) {
    const p00 = cBot(0);
    const p10 = cBot(1);
    const p01 = cTop(0);
    const p11 = cTop(1);
    return function (u, v) {
      const b = cBot(u);
      const t = cTop(u);
      const l = cLeft(v);
      const r = cRight(v);
      let x =
        (1 - v) * b[0] +
        v * t[0] +
        (1 - u) * l[0] +
        u * r[0] -
        ((1 - u) * (1 - v) * p00[0] +
          u * (1 - v) * p10[0] +
          (1 - u) * v * p01[0] +
          u * v * p11[0]);
      let y =
        (1 - v) * b[1] +
        v * t[1] +
        (1 - u) * l[1] +
        u * r[1] -
        ((1 - u) * (1 - v) * p00[1] +
          u * (1 - v) * p10[1] +
          (1 - u) * v * p01[1] +
          u * v * p11[1]);
      if (bulgeFn) {
        const d = bulgeFn(u, v);
        x += d[0];
        y += d[1];
      }
      return [x, y];
    };
  }

  // Safe stroke wrapper that guarantees brush.set() and prevents degenerate spline points
  function safeSpline(pts, brushName, col, weight, curvature = 0.42) {
    if (!pts || pts.length < 2) return;
    const clean = [pts[0]];
    for (let i = 1; i < pts.length; i++) {
      const dx = pts[i][0] - clean[clean.length - 1][0];
      const dy = pts[i][1] - clean[clean.length - 1][1];
      if (dx * dx + dy * dy >= 3.2) {
        clean.push(pts[i]);
      }
    }
    if (clean.length < 2) return;
    if (clean.length === 2) {
      const pAvg = ((clean[0][2] || 0.8) + (clean[1][2] || 0.8)) * 0.5;
      brush.set(brushName, col, weight * pAvg);
      brush.line(clean[0][0], clean[0][1], clean[1][0], clean[1][1]);
    } else {
      brush.set(brushName, col, weight);
      brush.spline(clean, curvature);
    }
  }

  function safeLine(x1, y1, x2, y2, brushName, col, weight) {
    if ((x2 - x1) * (x2 - x1) + (y2 - y1) * (y2 - y1) < 0.5) return;
    brush.set(brushName, col, weight);
    brush.line(x1, y1, x2, y2);
  }

  // Engraved multi-tier white-line renderer: converts a sampled 3D contour [{x, y, L}] into swelling burin cuts
  function renderEngravedPath(samples, minL, highlightL, baseBrush, weightScale = 1.0) {
    // Pass 1: Lowlight / earth-umber transitions (where lines thin into darkness)
    let seg = [];
    for (let i = 0; i < samples.length; i++) {
      const s = samples[i];
      if (!s.masked && s.L >= minL) {
        const p = constrain(map(s.L, minL, 0.9, 0.16, 1.05), 0.14, 1.15);
        seg.push([s.x, s.y, p]);
      } else {
        if (seg.length >= 2) {
          safeSpline(seg, "burin_hair", PAL.earthMid, 0.85 * weightScale, 0.4);
        }
        seg = [];
      }
    }
    if (seg.length >= 2) {
      safeSpline(seg, "burin_hair", PAL.earthMid, 0.85 * weightScale, 0.4);
    }

    // Pass 2: Main parchment-ivory body line
    seg = [];
    const midThresh = minL + 0.09;
    for (let i = 0; i < samples.length; i++) {
      const s = samples[i];
      if (!s.masked && s.L >= midThresh) {
        const p = constrain(map(s.L, midThresh, 0.95, 0.22, 1.18), 0.18, 1.25);
        seg.push([s.x, s.y, p]);
      } else {
        if (seg.length >= 2) {
          safeSpline(seg, baseBrush, PAL.parchment, 0.95 * weightScale, 0.42);
        }
        seg = [];
      }
    }
    if (seg.length >= 2) {
      safeSpline(seg, baseBrush, PAL.parchment, 0.95 * weightScale, 0.42);
    }

    // Pass 3: Swelling bone-white highlight core
    seg = [];
    for (let i = 0; i < samples.length; i++) {
      const s = samples[i];
      if (!s.masked && s.L >= highlightL) {
        const p = constrain(map(s.L, highlightL, 1.0, 0.28, 1.38), 0.24, 1.42);
        seg.push([s.x, s.y, p]);
      } else {
        if (seg.length >= 2) {
          safeSpline(seg, "burin_bold", PAL.bone, 1.02 * weightScale, 0.42);
        }
        seg = [];
      }
    }
    if (seg.length >= 2) {
      safeSpline(seg, "burin_bold", PAL.bone, 1.02 * weightScale, 0.42);
    }
  }

  // --- ANATOMICAL KEYVERTICES ---
