  // Unified Upper Welt Curve (t in [0, 1])
  function cWeltUpper(t) {
    if (t < 0.25) return cWelt_Counter(t / 0.25);
    if (t < 0.38) return cWelt_Arch((t - 0.25) / 0.13);
    if (t < 0.66) return cWelt_Vamp((t - 0.38) / 0.28);
