    const dy = 19 + 7 * sin(t * 180) + (t > 0.65 ? 4 * sin(((t - 0.65) / 0.35) * 180) : 0);
    return [p[0] + dx, p[1] + dy];
  }

  // Bottom of leather midsole
  function cMidsoleBot(t) {
    const p = cWeltOuter(t);
