  // --- CREASE & SURFACE DISPLACEMENT MODELS ---
  // Vamp deep leather rolls & creases
  function vampFoldWave(u, v) {
    // Coordinate aligned with diagonal flex creases of the foot
    const w = u + 0.16 * sin(v * 180) - 0.14 * (1 - v);
    const centers = [0.19, 0.42, 0.64, 0.83];
    const widths = [0.085, 0.095, 0.09, 0.075];
    const depths = [0.85, 1.0, 0.92, 0.68];

    let valleySum = 0;
    let slopeSum = 0;
    for (let k = 0; k < centers.length; k++) {
      const d = (w - centers[k]) / widths[k];
      const g = exp(-d * d * 2.2);
      // Pinched trough at center, rounded ridges on flanks
      valleySum += depths[k] * g * (1 - 0.55 * exp(-d * d * 8));
      slopeSum += depths[k] * (-2 * d) * g;
    }
    // Secondary branching crease in mid-vamp
    const dSub = (u - 0.53 - 0.08 * v) / 0.065;
    const gSub = exp(-dSub * dSub * 3.0) * sin(v * 180);
    valleySum += 0.45 * gSub;
    slopeSum += 0.45 * (-2 * dSub) * gSub;

    const env = sin(constrain(u, 0.02, 0.98) * 180) * pow(sin(constrain(v, 0.03, 0.99) * 165 + 12), 0.65);
    return {
      height: (0.48 - valleySum * 0.72) * env,
      slope: slopeSum * env
    };
  }

