      const ankleDist = sq((u - 0.44) / 0.28) + sq((v - 0.42) / 0.28);
      const ankleBulge = exp(-ankleDist * 1.8);
      const foldW = v - 0.25 * u + 0.06 * sin(u * 180);
      const fold = sin(foldW * 360 * 2.6) * sin(u * 180) * sin(v * 180);
      return [
        (-10 * ankleBulge - 4 * fold) * sin(u * 180),
        (-12 * ankleBulge + 5 * fold) * sin(v * 180)
      ];
    }
  );

  const patchVamp = makeCoons(
    cWelt_Vamp,
