    cToeSeam,
    (u, v) => {
      const f = vampFoldWave(u, v);
      const arch = sin(u * 180) * pow(v, 0.65);
      return [
        -12 * arch + f.height * 11 - f.slope * 3.5,
        -22 * arch - f.height * 16 + f.slope * 2.5
