    const samples = [];
    for (let j = 0; j <= 26; j++) {
      const v = j / 26; // v=0 at top rim, v=1 deep in dark shaft
      const pt = lerpPt(rimPt, deepPt, v);
      const curveX = pt[0] - 6 * sin(v * 180);
      const curveY = pt[1] + 4 * sin(u * 180);
      // Light catches the upper interior leather rim and fades into darkness down the shaft
      let L = pow(1 - v, 1.65) * (0.35 + 0.55 * sin(u * 180));
      // Vertical stitched seam inside back lining
      if (abs(u - 0.28) < 0.025) L *= 0.3;
      if (i % 2 === 1) L -= 0.14;
      samples.push({
        x: curveX,
        y: curveY,
        L,
        masked: false
      });
    }
    renderEngravedPath(samples, 0.16, 0.56, "burin_hair", 0.82);
  }

  // =========================================================================
  // 3. GUSSETED TONGUE & FAR QUARTER FACING (Recessed behind laces)
  // =========================================================================
  // Tongue contour lines with deep horizontal "lace-bite" indentations
  for (let row = 0; row <= 82; row++) {
    const v = row / 82; // v=0 at bottom of throat, v=1 at top crest of tongue
    const leftEdge = bPt([642, 526], [562, 435], [496, 338], [492, 224], v);
    const rightEdge = bPt([714, 492], [642, 412], [574, 315], [568, 212], v);

    // Lace-bite horizontal compression grooves
    const biteWave = sin(v * 360 * 4.2 - 35);
    const samples = [];
    for (let col = 0; col <= 34; col++) {
      const u = col / 34;
      const base = lerpPt(leftEdge, rightEdge, u);
      const archBulge = sin(u * 180);
      const x = base[0] - 8 * archBulge + 2.5 * biteWave * archBulge;
      const y = base[1] - 14 * archBulge - 4.5 * biteWave * archBulge;

      // Illumination: rounded central ridge of tongue + top crest catch overhead light
      let L =
        (0.24 + 0.52 * sin(pow(u, 0.85) * 180)) *
        (0.45 + 0.42 * biteWave + 0.28 * pow(v, 1.5));
      if (row % 2 === 1) L -= 0.15;

      const masked =
        isBehindNearQuarter(x, y) ||
        isOccludedByLace(x, y, 2.8) ||
        isOccludedByHardware(x, y, 11);
      samples.push({ x, y, L, masked });
    }
    renderEngravedPath(samples, 0.16, 0.54, "burin_fine", 0.85);
  }

  // Far Quarter Facing (holds the far row of eyelets and speed hooks)
  for (let i = 0; i <= 54; i++) {
    const v = i / 54;
    const pInner = bPt(P_throat_far, [640, 425], [572, 338], P_collar_far, v);
    const pOuter = bPt([748, 528], [672, 422], [602, 326], [546, 240], v);
    const samples = [];
    for (let j = 0; j <= 16; j++) {
      const u = j / 16;
      const pt = lerpPt(pInner, pOuter, u);
      let L = (0.28 + 0.54 * sin(u * 180)) * (0.55 + 0.35 * sin(v * 180));
      if (i % 2 === 1) L -= 0.14;
      const masked = isOccludedByLace(pt[0], pt[1], 2.5);
      samples.push({ x: pt[0], y: pt[1], L, masked });
    }
    renderEngravedPath(samples, 0.16, 0.56, "burin_fine", 0.82);
  }

  // =========================================================================
  // 4. ROLLED TOP COLLAR (Seen from slightly above)
  // =========================================================================
  for (let i = 0; i <= 92; i++) {
    const u = i / 92;
    const topRim = bPt([255, 194], [322, 224], [412, 252], [490, 262], u);
    const botRim = cCollarLower(u);
    const samples = [];
    // Cross-contour lines wrapping over the plump leather collar roll
    const wrinkle = sin(u * 360 * 9) * 0.08;
    for (let j = 0; j <= 20; j++) {
      const v = j / 20; // v=0 at top rim, v=1 at lower seam
      const base = lerpPt(topRim, botRim, v);
      const roll = sin(v * 180);
      const x = base[0] - 9 * roll;
      const y = base[1] - 7 * roll;

      // Strong overhead light on the upper-middle curve of the rolled leather collar
      let L =
        pow(sin(constrain(1 - v * 0.82, 0.05, 0.98) * 180), 0.75) *
          (0.45 + 0.52 * sin(u * 160 + 10)) +
        wrinkle;
      if (i % 2 === 1) L -= 0.16;
      samples.push({ x, y, L, masked: isOccludedByLace(x, y, 2.5) });
    }
    renderEngravedPath(samples, 0.16, 0.52, "burin_fine", 0.9);
  }

  // Longitudinal highlight lines along the top crown of the rolled collar
  for (let j = 1; j <= 8; j++) {
    const v = map(j, 1, 8, 0.12, 0.62);
    const samples = [];
    for (let i = 0; i <= 70; i++) {
      const u = i / 70;
      const topRim = bPt([255, 194], [322, 224], [412, 252], [490, 262], u);
      const botRim = cCollarLower(u);
      const base = lerpPt(topRim, botRim, v);
      const roll = sin(v * 180);
      const x = base[0] - 9 * roll;
      const y = base[1] - 7 * roll;
      const L = 0.35 + 0.58 * sin(v * 180) * sin(u * 170 + 5);
      samples.push({ x, y, L, masked: isOccludedByLace(x, y, 2.5) });
    }
    renderEngravedPath(samples, 0.32, 0.58, "burin_fine", 0.85);
  }

  // =========================================================================
  // 5. REINFORCED HEEL COUNTER & NEAR QUARTER (Side Ankle Panel)
  // =========================================================================
  // 5A. Heel Counter form-following contours
  for (let row = 0; row <= 76; row++) {
    const v = row / 76;
    const samples = [];
    const nSteps = 56;
    for (let col = 0; col <= nSteps; col++) {
      const u = col / nSteps;
      const pt = patchCounter(u, v);

      // 3D spherical lighting on heel counter cup + worn heel scuffs
      const cupLight =
        sin(pow(u, 0.72) * 165 + 15) * (0.28 + 0.68 * pow(v, 0.65));
      const scuff =
        0.12 *
        sin(u * 900 + v * 400) *
        exp(-sq((u - 0.35) / 0.22) - sq((v - 0.45) / 0.25));
      const weltRim = v < 0.09 ? 0.32 * sin((v / 0.09) * 180) : 0;
      let L = cupLight + scuff + weltRim;
      if (row % 2 === 1) L -= 0.16;

      samples.push({
        x: pt[0],
        y: pt[1],
        L,
        masked: isOccludedByLace(pt[0], pt[1], 2.6)
      });
    }
    renderEngravedPath(samples, 0.15, 0.54, "burin_fine", 0.92);
  }

  // Cross-contours on upper heel counter highlight
  for (let col = 4; col <= 34; col++) {
    const u = col / 38;
    const samples = [];
    for (let row = 18; row <= 50; row++) {
      const v = row / 50;
      const pt = patchCounter(u, v);
      const L =
        0.22 +
        0.66 * sin(pow(u, 0.75) * 160 + 15) * pow(sin(v * 150), 1.2);
      samples.push({
        x: pt[0],
        y: pt[1],
        L: col % 2 === 1 ? L - 0.15 : L,
        masked: isOccludedByLace(pt[0], pt[1], 2.6)
      });
    }
    renderEngravedPath(samples, 0.38, 0.64, "burin_hair", 0.8);
  }

  // 5B. Near Quarter Panel (Ankle bone & flex folds)
  for (let row = 0; row <= 108; row++) {
    const v = row / 108;
    const samples = [];
    const nSteps = 72;
    for (let col = 0; col <= nSteps; col++) {
      const u = col / nSteps;
      const pt = patchQuarter(u, v);

      // Ankle bone crown + 3 diagonal ankle flex creases
      const ankleCrown = exp(
        -sq((u - 0.44) / 0.32) - sq((v - 0.44) / 0.32)
      );
      const foldCoord = v - 0.26 * u + 0.06 * sin(u * 180);
      const foldWave =
        sin(foldCoord * 360 * 2.6 - 20) *
        sin(u * 180) *
        sin(constrain(v, 0.1, 0.92) * 180);

      // Facing stitch strip highlight near u=1
      const facingBand = u > 0.88 ? 0.38 * sin(((u - 0.88) / 0.12) * 180) : 0;
      // Backstay strip near u=0
      const backstay = u < 0.11 ? 0.28 * (1 - u / 0.11) : 0;

      let L =
        0.22 +
        0.48 * sin(pow(u, 0.8) * 170 + 8) * sin(v * 165 + 10) +
        0.26 * ankleCrown +
        0.28 * foldWave +
        facingBand +
        backstay;

      if (row % 2 === 1) L -= 0.16;

      samples.push({
        x: pt[0],
        y: pt[1],
        L,
        masked:
          isOccludedByLace(pt[0], pt[1], 2.6) ||
          isOccludedByHardware(pt[0], pt[1], 11.5)
      });
    }
    renderEngravedPath(samples, 0.15, 0.54, "burin_fine", 0.92);
  }

  // Cross-contour lines over the ankle bone highlight & facing strip
  for (let col = 0; col <= 52; col++) {
    const u = col / 52;
    const samples = [];
    for (let row = 0; row <= 56; row++) {
      const v = row / 56;
      const pt = patchQuarter(u, v);
      const ankleCrown = exp(
        -sq((u - 0.44) / 0.25) - sq((v - 0.44) / 0.26)
      );
      const foldCoord = v - 0.26 * u + 0.06 * sin(u * 180);
      const foldWave =
        sin(foldCoord * 360 * 2.6 - 20) * sin(u * 180) * sin(v * 180);
      let L = 0.18 + 0.52 * ankleCrown + 0.28 * max(0, foldWave);
      if (u > 0.89) L += 0.36;
      if (col % 2 === 1) L -= 0.14;
      samples.push({
        x: pt[0],
        y: pt[1],
        L,
        masked:
          isOccludedByLace(pt[0], pt[1], 2.6) ||
          isOccludedByHardware(pt[0], pt[1], 11.5)
      });
    }
    renderEngravedPath(samples, 0.36, 0.62, "burin_hair", 0.8);
  }

  // =========================================================================
  // 6. THE DEEPLY CREASED VAMP / INSTEP
  // =========================================================================
  // Longitudinal contours sweeping across the undulating leather folds
  for (let row = 0; row <= 128; row++) {
    const v = row / 128;
    const samples = [];
    const nSteps = 84;
    for (let col = 0; col <= nSteps; col++) {
      const u = col / nSteps;
      const pt = patchVamp(u, v);
      const f = vampFoldWave(u, v);

      // Overhead-left light catches the upper bridge (v -> 1) and the upper-left slopes of each fold
      const bridgeLight = 0.22 + 0.58 * pow(v, 0.68) * sin(u * 160 + 12);
      const ridgeLight = 0.42 * f.height - 0.28 * f.slope;
      // Subtle rim reflection just above the stitched storm welt
      const weltRefl = v < 0.065 ? 0.32 * sin((v / 0.065) * 180) : 0;
      // Micro leather grain
      const grain = 0.05 * sin(u * 1400 + v * 900);

      let L = bridgeLight + ridgeLight + weltRefl + grain;
      if (row % 2 === 1) L -= 0.16;

      samples.push({
        x: pt[0],
        y: pt[1],
        L,
        masked: isOccludedByLace(pt[0], pt[1], 2.6)
      });
    }
    renderEngravedPath(samples, 0.14, 0.52, "burin_fine", 0.96);
  }

  // Transverse cross-contour lines curving over the vamp ridges (densest on fold crests)
  for (let col = 0; col <= 76; col++) {
    const u = col / 76;
    const samples = [];
    for (let row = 0; row <= 68; row++) {
      const v = row / 68;
      const pt = patchVamp(u, v);
      const f = vampFoldWave(u, v);
      const bridgeLight = 0.18 + 0.52 * pow(v, 0.65) * sin(u * 160 + 12);
      const ridgeLight = 0.48 * f.height - 0.26 * f.slope;
      let L = bridgeLight + ridgeLight;
      if (col % 2 === 1) L -= 0.15;

      samples.push({
        x: pt[0],
        y: pt[1],
        L,
        masked: isOccludedByLace(pt[0], pt[1], 2.6)
      });
    }
    renderEngravedPath(samples, 0.34, 0.58, "burin_hair", 0.84);
  }

  // =========================================================================
  // 7. THE CRACKED, BATTERED BULBOUS TOE CAP
  // =========================================================================
  // Helper to evaluate crack proximity & highlight lip on the toe cap
  function evalToeCracks(u, v) {
    let darkCut = 0;
    let brightLip = 0;
    for (let k = 0; k < toeScars.length; k++) {
      const s = toeScars[k];
      const dx = s.u1 - s.u0;
      const dy = s.v1 - s.v0;
      const len2 = dx * dx + dy * dy;
      const t = constrain(((u - s.u0) * dx + (v - s.v0) * dy) / len2, 0, 1);
      const cx = s.u0 + t * dx - dy * s.bend * sin(t * 180);
      const cy = s.v0 + t * dy + dx * s.bend * sin(t * 180);
      const dist = sqrt(sq(u - cx) + sq(v - cy));
      const endTaper = sin(t * 180);

      // If right in the crack crevice -> dark knockout
      if (dist < 0.011 * endTaper) {
        darkCut = max(darkCut, s.strength);
      }
      // Lower/lit edge of the crack catches bright specular rim light
      const signedOffset = (u - cx) * 0.5 - (v - cy) * 0.86;
      if (signedOffset > 0.004 && signedOffset < 0.024 && t > 0.04 && t < 0.96) {
        brightLip = max(
          brightLip,
          s.strength * 0.48 * exp(-sq((signedOffset - 0.011) / 0.007)) * endTaper
        );
      }
    }
    return { darkCut, brightLip };
  }

  // Primary longitudinal dome contours on the Toe Cap
  for (let row = 0; row <= 136; row++) {
    const v = row / 136;
    const samples = [];
    const nSteps = 90;
    for (let col = 0; col <= nSteps; col++) {
      const u = col / nSteps;
      const pt = patchToe(u, v);

      // Strong dome illumination centered on the upper-front crown (u ~ 0.46, v ~ 0.66)
      const crownDist = sq((u - 0.46) / 0.42) + sq((v - 0.66) / 0.38);
      const domeLight = 0.2 + 0.78 * exp(-crownDist * 1.15);
      // Specular burnished leather sheen on the crown
      const spec = 0.24 * exp(-sq((u - 0.48) / 0.22) - sq((v - 0.68) / 0.2));
      // Welt rim reflection at bottom (v -> 0)
      const weltRim = v < 0.06 ? 0.36 * sin((v / 0.06) * 180) : 0;
      // Rough scuffed abrasion texture near the front nose (u > 0.72)
      const noseScuff =
        u > 0.68
          ? 0.18 *
            sin(u * 2100 + v * 1500) *
            cos(u * 950 - v * 1300) *
            ((u - 0.68) / 0.32)
          : 0;

      const crack = evalToeCracks(u, v);
      let L = domeLight + spec + weltRim + noseScuff + crack.brightLip;
      if (row % 2 === 1) L -= 0.15;

      samples.push({
        x: pt[0],
        y: pt[1],
        L,
        masked: crack.darkCut > 0.5
      });
    }
    renderEngravedPath(samples, 0.14, 0.5, "burin_fine", 1.0);
  }

  // Secondary cross-contour curves arching over the bulbous toe cap
  for (let col = 0; col <= 86; col++) {
    const u = col / 86;
    const samples = [];
    const nSteps = 74;
    for (let row = 0; row <= nSteps; row++) {
      const v = row / nSteps;
      const pt = patchToe(u, v);
      const crownDist = sq((u - 0.46) / 0.38) + sq((v - 0.66) / 0.36);
      const domeLight = 0.16 + 0.74 * exp(-crownDist * 1.25);
      const crack = evalToeCracks(u, v);
      let L = domeLight + crack.brightLip;
      if (col % 2 === 1) L -= 0.15;

      samples.push({
        x: pt[0],
        y: pt[1],
        L,
        masked: crack.darkCut > 0.5
      });
    }
    renderEngravedPath(samples, 0.32, 0.56, "burin_hair", 0.86);
  }

  // Explicit incised crack highlights & black gouge crevices on the Toe Cap
  for (let k = 0; k < toeScars.length; k++) {
    const s = toeScars[k];
    const darkPts = [];
    const litPts = [];
    const dx = s.u1 - s.u0;
    const dy = s.v1 - s.v0;
    for (let i = 0; i <= 24; i++) {
      const t = i / 24;
      const endTaper = sin(t * 180);
      const cu = s.u0 + t * dx - dy * s.bend * endTaper + 0.003 * sin(t * 720 + k * 50);
      const cv = s.v0 + t * dy + dx * s.bend * endTaper + 0.003 * cos(t * 720 + k * 50);
      const pDark = patchToe(constrain(cu, 0, 1), constrain(cv, 0, 1));
      const pLit = patchToe(
        constrain(cu + 0.007, 0, 1),
        constrain(cv - 0.011, 0, 1)
      );
      darkPts.push([pDark[0], pDark[1], 0.4 + 0.8 * endTaper]);
      litPts.push([pLit[0], pLit[1], 0.35 + 0.95 * endTaper * s.strength]);
    }
    safeSpline(darkPts, "gouge_black", PAL.ink, 1.15, 0.35);
    safeSpline(litPts, "burin_bold", PAL.bone, 0.95, 0.35);
  }

  // =========================================================================
  // 8. DOUBLE & TRIPLE LEATHER SEAM STITCHING ON THE UPPER
  // =========================================================================
  function drawUpperStitchRow(curveFn, nStitches, normalOffsetPx, lightBias = 0.75) {
    for (let i = 0; i < nStitches; i++) {
      const t0 = (i + 0.18) / nStitches;
      const t1 = (i + 0.78) / nStitches;
      const p0 = curveFn(t0);
      const p1 = curveFn(t1);
      const tx = p1[0] - p0[0];
      const ty = p1[1] - p0[1];
      const len = sqrt(tx * tx + ty * ty) || 1;
      const nx = -ty / len;
      const ny = tx / len;

      const x0 = p0[0] + nx * normalOffsetPx;
      const y0 = p0[1] + ny * normalOffsetPx;
      const x1 = p1[0] + nx * normalOffsetPx;
      const y1 = p1[1] + ny * normalOffsetPx;

      if (isOccludedByLace((x0 + x1) * 0.5, (y0 + y1) * 0.5, 2.8)) continue;

      const sLight = lightBias * (0.55 + 0.45 * sin(t0 * 180));
      const col = sLight > 0.55 ? PAL.bone : PAL.parchment;
      safeLine(x0, y0, x1, y1, "burin_fine", col, 0.82 * sLight + 0.25);
      // Second thread fiber for plump lockstitch look
      safeLine(
        x0 + nx * 1.1,
        y0 + ny * 1.1,
        x1 + nx * 1.1,
        y1 + ny * 1.1,
        "burin_hair",
        PAL.ivory,
        0.65 * sLight + 0.2
      );
    }
  }

  // Dark seam kerf + twin stitch rows on Toe Cap Seam
  const toeSeamDarkPts = [];
  const toeSeamLipPts = [];
  for (let i = 0; i <= 40; i++) {
    const v = i / 40;
    const p = cToeSeam(v);
    if (!isOccludedByLace(p[0], p[1], 2.5)) {
      toeSeamDarkPts.push([p[0] - 2, p[1], 0.9]);
      toeSeamLipPts.push([p[0] + 1.5, p[1] - 0.5, 0.5 + 0.6 * sin(v * 180)]);
    }
  }
  safeSpline(toeSeamDarkPts, "gouge_black", PAL.ink, 1.1, 0.4);
  safeSpline(toeSeamLipPts, "burin_bold", PAL.bone, 0.95, 0.4);
  drawUpperStitchRow(cToeSeam, 32, 6.0, 0.92);
  drawUpperStitchRow(cToeSeam, 32, 11.5, 0.85);

  // Quarter-to-Vamp triple-stitched sweep seam
  drawUpperStitchRow(cQuarterSeam, 24, -4.5, 0.88);
  drawUpperStitchRow(cQuarterSeam, 24, -9.5, 0.82);
  drawUpperStitchRow(cQuarterSeam, 24, -14.5, 0.75);

  // Heel Counter double-stitched arch seam
  function cFullCounterSeam(t) {
    if (t < 0.52) return cCounterUpper(t / 0.52);
    return cCounterLower(1 - (t - 0.52) / 0.48);
  }
  drawUpperStitchRow(cFullCounterSeam, 30, -4.5, 0.82);
  drawUpperStitchRow(cFullCounterSeam, 30, -9.5, 0.74);

  // =========================================================================
  // 9. STITCHED STORM WELT (Beaded Ledge & 46 Heavy Waxed Stitches)
  // =========================================================================
  // Dark crease channel where upper leather tucks into the storm welt
  for (let pass = 0; pass < 2; pass++) {
    const pts = [];
    for (let i = 0; i <= 90; i++) {
      const t = i / 90;
      const p = cWeltUpper(t);
      if (!isOccludedByLace(p[0], p[1], 2.5)) {
        pts.push([p[0], p[1] + pass * 1.4, 0.95]);
      } else {
        if (pts.length >= 2) safeSpline(pts, "gouge_black", PAL.ink, 1.1, 0.4);
        pts.length = 0;
      }
    }
    if (pts.length >= 2) safeSpline(pts, "gouge_black", PAL.ink, 1.1, 0.4);
  }

  // Engraved radial cross-lines across the Storm Welt shelf + raised inner bead highlight
  for (let i = 0; i <= 210; i++) {
    const t = i / 210;
    const pIn = cWeltUpper(t);
    const pOut = cWeltOuter(t);
    const samples = [];
    // Welt catches strong overhead light around the ball and toe cap
    const baseLight =
      0.24 +
      0.56 * pow(sin(constrain(t * 155 + 15, 0, 180)), 0.8) +
      (t > 0.6 ? 0.18 : 0);

    for (let j = 0; j <= 10; j++) {
      const s = j / 10;
      const pt = lerpPt(pIn, pOut, s);
      // Inner welt bead (s ~ 0.18) and outer welt rim (s ~ 0.88) are brightest; stitch groove (s ~ 0.52) is recessed
      const profile =
        0.55 * exp(-sq((s - 0.18) / 0.14)) +
        0.48 * exp(-sq((s - 0.88) / 0.14)) -
        0.35 * exp(-sq((s - 0.52) / 0.16));
      let L = baseLight + profile;
      if (i % 2 === 1) L -= 0.16;
      samples.push({
        x: pt[0],
        y: pt[1],
        L,
        masked: isOccludedByLace(pt[0], pt[1], 2.4)
      });
    }
    renderEngravedPath(samples, 0.18, 0.56, "burin_hair", 0.82);
  }

  // Continuous highlight along the outer rim of the Storm Welt
  for (let ring = 0; ring < 3; ring++) {
    const sPos = map(ring, 0, 2, 0.16, 0.9);
    if (ring === 1) continue; // skip middle stitch channel
    const samples = [];
    for (let i = 0; i <= 120; i++) {
      const t = i / 120;
      const pt = lerpPt(cWeltUpper(t), cWeltOuter(t), sPos);
      const L = 0.32 + 0.58 * sin(t * 165 + 10);
      samples.push({
        x: pt[0],
        y: pt[1],
        L,
        masked: isOccludedByLace(pt[0], pt[1], 2.4)
      });
    }
    renderEngravedPath(samples, 0.24, 0.54, "burin_fine", 0.9);
  }

  // 46 Individual Heavy Waxed-Linen Welt Stitches along the recessed welt groove
  const nWeltStitches = 46;
  for (let k = 0; k < nWeltStitches; k++) {
    const t0 = (k + 0.16) / nWeltStitches;
    const t1 = (k + 0.82) / nWeltStitches;
    const tHole = (k + 0.98) / nWeltStitches;

    const p0 = lerpPt(cWeltUpper(t0), cWeltOuter(t0), 0.53);
    const p1 = lerpPt(cWeltUpper(t1), cWeltOuter(t1), 0.53);
    const pHole = lerpPt(cWeltUpper(tHole), cWeltOuter(tHole), 0.53);

    const mx = (p0[0] + p1[0]) * 0.5;
    const my = (p0[1] + p1[1]) * 0.5;
    if (isOccludedByLace(mx, my, 3.0)) continue;

    // Dark awl-hole dimple between stitches
    safeLine(
      pHole[0] - 1.5,
      pHole[1] - 1.5,
      pHole[0] + 1.5,
      pHole[1] + 1.5,
      "gouge_black",
      PAL.ink,
      1.3
    );

    const tx = p1[0] - p0[0];
    const ty = p1[1] - p0[1];
    const len = sqrt(tx * tx + ty * ty) || 1;
    const nx = -ty / len;
    const ny = tx / len;

    // Plump bundle of 4 curved white thread strokes per stitch
    const stitchLight = 0.45 + 0.55 * sin(t0 * 165 + 15);
    for (let f = -1.5; f <= 1.5; f += 1.0) {
      const bow = (1 - abs(f) * 0.35) * 1.4;
      const sPts = [
        [p0[0] + nx * f * 1.15, p0[1] + ny * f * 1.15, 0.45 * stitchLight],
        [
          mx + nx * (f * 1.45 - bow),
          my + ny * (f * 1.45 - bow),
          1.25 * stitchLight
        ],
        [p1[0] + nx * f * 1.15, p1[1] + ny * f * 1.15, 0.45 * stitchLight]
      ];
      const col = abs(f) < 1.0 && stitchLight > 0.55 ? PAL.bone : PAL.parchment;
      safeSpline(sPts, "burin_bold", col, 0.9, 0.45);
    }
  }

  // =========================================================================
  // 10. LEATHER MIDSOLE, STACKED HEEL & CRISP TOOLED CROSSHATCH SOLE TREAD
  // =========================================================================
  // 10A. Continuous Leather Midsole Band (under the welt)
  for (let i = 0; i <= 220; i++) {
    const t = i / 220;
    const pTop = cWeltOuter(t);
    const pBot = cMidsoleBot(t);
    const samples = [];
    const baseL = 0.2 + 0.58 * sin(t * 165 + 10) * (t > 0.25 && t < 0.42 ? 0.55 : 1.0);
    for (let j = 0; j <= 8; j++) {
      const s = j / 8;
      const pt = lerpPt(pTop, pBot, s);
      let L = baseL * (0.45 + 0.55 * sin(s * 180));
      if (i % 2 === 1) L -= 0.14;
      samples.push({
        x: pt[0],
        y: pt[1],
        L,
        masked: isOccludedByLace(pt[0], pt[1], 2.4)
      });
    }
    renderEngravedPath(samples, 0.16, 0.54, "burin_hair", 0.84);
  }

  // Horizontal lamination grain lines along the leather midsole
  for (let layer = 1; layer <= 4; layer++) {
    const s = layer / 5;
    const samples = [];
    for (let i = 0; i <= 120; i++) {
      const t = i / 120;
      const pt = lerpPt(cWeltOuter(t), cMidsoleBot(t), s);
      let L = 0.22 + 0.55 * sin(t * 165 + 10);
      if (t > 0.25 && t < 0.42) L *= 0.55; // recessed arch shadow
      samples.push({
        x: pt[0],
        y: pt[1],
        L,
        masked: isOccludedByLace(pt[0], pt[1], 2.4)
      });
    }
    renderEngravedPath(samples, 0.2, 0.52, "burin_fine", 0.85);
  }

  // 10B. Stacked Leather Heel Lifts & Heel Lug Base (t in [0, 0.30])
  function cHeelStackTop(u) {
    return cMidsoleBot(u * 0.3);
  }
  function cHeelStackBot(u) {
    const p = cHeelStackTop(u);
    // Classic slightly underslung logger/work-boot heel stack
    const dx = lerp(-10, -8, u);
    const dy = lerp(84, 92, u);
    return [p[0] + dx, p[1] + dy];
  }

  // 4 Stacked leather heel lifts (top 62% of heel block)
  for (let lift = 0; lift < 4; lift++) {
    const v0 = (lift / 4) * 0.62;
    const v1 = ((lift + 1) / 4) * 0.62;

    // Horizontal lift seam line
    const seamSamples = [];
    for (let i = 0; i <= 45; i++) {
      const u = i / 45;
      const pt = lerpPt(cHeelStackTop(u), cHeelStackBot(u), v1);
      const L = 0.28 + 0.56 * sin(pow(u, 0.7) * 160 + 15);
      seamSamples.push({ x: pt[0], y: pt[1], L, masked: false });
    }
    renderEngravedPath(seamSamples, 0.18, 0.52, "burin_fine", 0.9);

    // Vertical compressed-leather tooling & crosshatching on each heel lift
    for (let i = 0; i <= 54; i++) {
      const u = i / 54;
      const pA = lerpPt(cHeelStackTop(u), cHeelStackBot(u), v0 + 0.03);
      const pB = lerpPt(cHeelStackTop(u), cHeelStackBot(u), v1 - 0.03);
      const L =
        (0.2 + 0.62 * sin(pow(u, 0.72) * 155 + 18)) *
        (i % 2 === 0 ? 1.0 : 0.76);
      if (L > 0.18) {
        const col = L > 0.58 ? PAL.ivory : L > 0.36 ? PAL.parchment : PAL.earthMid;
        safeLine(pA[0], pA[1], pB[0], pB[1], "burin_hair", col, 0.78 * L + 0.2);
      }
    }
  }

  // Diagonal crosshatch on the heel stack midtones
  for (let i = 0; i <= 42; i++) {
    const u0 = i / 42;
    const u1 = constrain(u0 + 0.14, 0, 1);
    const pA = lerpPt(cHeelStackTop(u0), cHeelStackBot(u0), 0.04);
    const pB = lerpPt(cHeelStackTop(u1), cHeelStackBot(u1), 0.6);
    const L = 0.22 + 0.48 * sin(u0 * 160 + 15);
    safeLine(pA[0], pA[1], pB[0], pB[1], "burin_hair", PAL.putty, 0.65 * L);
  }

  // 3D Heel Breast (the recessed vertical front face of the heel under the arch)
  const hbTopNear = lerpPt(cHeelStackTop(1), cHeelStackBot(1), 0.0);
  const hbBotNear = cHeelStackBot(1);
  const hbTopFar = [hbTopNear[0] + 44, hbTopNear[1] - 24];
  const hbBotFar = [hbBotNear[0] + 42, hbBotNear[1] - 26];

  // Crisp tooled crosshatch inside the shadowed heel breast plane
  for (let i = 0; i <= 26; i++) {
    const s = i / 26;
    const pL = lerpPt(hbTopNear, hbBotNear, s);
    const pR = lerpPt(hbTopFar, hbBotFar, s);
    safeLine(pL[0], pL[1], pR[0], pR[1], "burin_hair", PAL.earthMid, 0.72);
  }
  for (let i = 0; i <= 18; i++) {
    const u = i / 18;
    const pT = lerpPt(hbTopNear, hbTopFar, u);
    const pB = lerpPt(hbBotNear, hbBotFar, u);
    safeLine(pT[0], pT[1], pB[0], pB[1], "burin_hair", PAL.earthLow, 0.68);
  }
  for (let i = -12; i <= 18; i++) {
    const u0 = constrain(i / 18, 0, 1);
    const u1 = constrain((i + 8) / 18, 0, 1);
    const v0 = constrain(-i / 12, 0, 1);
    const v1 = constrain((18 - i) / 12, 0, 1);
    const pA = lerpPt(
      lerpPt(hbTopNear, hbTopFar, u0),
      lerpPt(hbBotNear, hbBotFar, u0),
      v0
    );
    const pB = lerpPt(
      lerpPt(hbTopNear, hbTopFar, u1),
      lerpPt(hbBotNear, hbBotFar, u1),
      v1
    );
    safeLine(pA[0], pA[1], pB[0], pB[1], "burin_hair", PAL.putty, 0.58);
  }

  // Helper to render a 3D sculpted rubber tread lug + recessed tooled crosshatch notch
  function drawTreadLugAndNotch(
    pTopL,
    pTopR,
    pBotL,
    pBotR,
    pNotchTopR,
    pNotchBotR,
    inwardVec,
    lightIntensity
  ) {
    // 1. Outer lit face of the rubber lug (crisp horizontal + vertical + diagonal crosshatch)
    const nH = 14;
    for (let r = 0; r <= nH; r++) {
      const v = r / nH;
      const a = lerpPt(pTopL, pBotL, v);
      const b = lerpPt(pTopR, pBotR, v);
      if (isOccludedByLace((a[0] + b[0]) * 0.5, (a[1] + b[1]) * 0.5, 2.5)) continue;
      const isBevel = r === 0 || r === nH || r === 1;
      const col = isBevel ? PAL.bone : lightIntensity > 0.6 ? PAL.ivory : PAL.parchment;
      const w = (isBevel ? 1.05 : 0.78) * lightIntensity;
      safeLine(a[0], a[1], b[0], b[1], isBevel ? "burin_fine" : "burin_hair", col, w);
    }

    const nV = 12;
    for (let c = 0; c <= nV; c++) {
      const u = c / nV;
      const a = lerpPt(pTopL, pTopR, u);
      const b = lerpPt(pBotL, pBotR, u);
      if (isOccludedByLace((a[0] + b[0]) * 0.5, (a[1] + b[1]) * 0.5, 2.5)) continue;
      const isEdge = c === 0 || c === nV;
      const col = isEdge ? PAL.bone : PAL.parchment;
      safeLine(
        a[0],
        a[1],
        b[0],
        b[1],
        isEdge ? "burin_fine" : "burin_hair",
        col,
        (isEdge ? 1.0 : 0.72) * lightIntensity
      );
    }

    // Crisp diagonal tooled crosshatch on the lug face
    for (let d = -6; d <= 10; d++) {
      const u0 = constrain(d / 10, 0, 1);
      const u1 = constrain((d + 5) / 10, 0, 1);
      const v0 = constrain(-d / 6, 0, 1);
      const v1 = constrain((10 - d) / 6, 0, 1);
      const a = lerpPt(lerpPt(pTopL, pTopR, u0), lerpPt(pBotL, pBotR, u0), v0);
      const b = lerpPt(lerpPt(pTopL, pTopR, u1), lerpPt(pBotL, pBotR, u1), v1);
      if (!isOccludedByLace((a[0] + b[0]) * 0.5, (a[1] + b[1]) * 0.5, 2.5)) {
        safeLine(a[0], a[1], b[0], b[1], "burin_hair", PAL.putty, 0.65 * lightIntensity);
      }
    }

    // 2. Recessed 3D tread notch channel (side wall going inward + notch roof)
    if (pNotchTopR && pNotchBotR) {
      const pInTop = [pTopR[0] + inwardVec[0], pTopR[1] + inwardVec[1]];
      const pInBot = [pBotR[0] + inwardVec[0], pBotR[1] + inwardVec[1]];

      // Side wall of lug going into the tread notch (crisp tooled crosshatch in shadow)
      for (let r = 0; r <= 10; r++) {
        const v = r / 10;
        const a = lerpPt(pTopR, pBotR, v);
        const b = lerpPt(pInTop, pInBot, v);
        if (!isOccludedByLace((a[0] + b[0]) * 0.5, (a[1] + b[1]) * 0.5, 2.5)) {
          safeLine(a[0], a[1], b[0], b[1], "burin_hair", PAL.earthMid, 0.7);
        }
      }
      for (let c = 0; c <= 7; c++) {
        const u = c / 7;
        const a = lerpPt(pTopR, pInTop, u);
        const b = lerpPt(pBotR, pInBot, u);
        if (!isOccludedByLace((a[0] + b[0]) * 0.5, (a[1] + b[1]) * 0.5, 2.5)) {
          safeLine(a[0], a[1], b[0], b[1], "burin_hair", PAL.putty, 0.65 * (1 - u * 0.4));
        }
      }
      // Back wall of notch connecting to next lug
      for (let r = 0; r <= 8; r++) {
        const v = r / 8;
        const a = lerpPt(pInTop, pInBot, v);
        const b = lerpPt(pNotchTopR, pNotchBotR, v * 0.65);
        if (!isOccludedByLace((a[0] + b[0]) * 0.5, (a[1] + b[1]) * 0.5, 2.5)) {
          safeLine(a[0], a[1], b[0], b[1], "burin_hair", PAL.earthLow, 0.6);
        }
      }
    }
  }

  // 5 Rubber Heel Lugs at the bottom of the Heel Block
  for (let k = 0; k < 5; k++) {
    const uL = (k + 0.04) / 5;
    const uR = (k + 0.66) / 5;
    const uNext = min(1, (k + 1.04) / 5);

    const pTopL = lerpPt(cHeelStackTop(uL), cHeelStackBot(uL), 0.64);
    const pTopR = lerpPt(cHeelStackTop(uR), cHeelStackBot(uR), 0.64);
    const pBotL = cHeelStackBot(uL);
    const pBotR = cHeelStackBot(uR);
    const pNextTop = lerpPt(cHeelStackTop(uNext), cHeelStackBot(uNext), 0.64);
    const pNextBot = cHeelStackBot(uNext);

    const lugLight = 0.52 + 0.42 * sin((k / 4) * 150 + 20);
    drawTreadLugAndNotch(
      pTopL,
      pTopR,
      pBotL,
      pBotR,
      k < 4 ? pNextTop : null,
      k < 4 ? pNextBot : null,
      [11, -5],
      lugLight
    );
  }

  // 10C. Forefoot Rubber Outsole Band & 10 Sculpted Commando Tread Lugs (t in [0.38, 1.0])
  function cOutsoleBase(t) {
    const p = cMidsoleBot(t);
    return [p[0] + lerp(-2, 4, t), p[1] + 13];
  }
  function cLugBottom(t) {
    const p = cOutsoleBase(t);
    const depth = 28 + 6 * sin(((t - 0.38) / 0.62) * 180);
    const dx = lerp(-3, 9, (t - 0.38) / 0.62);
    return [p[0] + dx, p[1] + depth];
  }

  // Continuous rubber outsole band between midsole and lug teeth
  for (let i = 0; i <= 140; i++) {
    const t = map(i, 0, 140, 0.3, 1.0);
    const pA = cMidsoleBot(t);
    const pB = cOutsoleBase(t);
    if (isOccludedByLace((pA[0] + pB[0]) * 0.5, (pA[1] + pB[1]) * 0.5, 2.5)) continue;
    const L = 0.35 + 0.55 * sin(t * 160 + 10);
    safeLine(pA[0], pA[1], pB[0], pB[1], "burin_hair", PAL.parchment, 0.75 * L);
  }

  // 10 Forefoot & Toe Commando Tread Lugs
  const nForeLugs = 10;
  for (let k = 0; k < nForeLugs; k++) {
    const tL = map(k + 0.05, 0, nForeLugs, 0.39, 0.99);
    const tR = map(k + 0.64, 0, nForeLugs, 0.39, 0.99);
    const tNext = map(min(nForeLugs, k + 1.05), 0, nForeLugs, 0.39, 0.99);

    const pTopL = cOutsoleBase(tL);
    const pTopR = cOutsoleBase(tR);
    const pBotL = cLugBottom(tL);
    const pBotR = cLugBottom(tR);
    const pNextTop = cOutsoleBase(tNext);
    const pNextBot = cLugBottom(tNext);

    const lugLight = 0.55 + 0.45 * sin(((k + 0.5) / nForeLugs) * 165 + 10);
    const inVec = [lerp(13, -7, k / nForeLugs), lerp(-6, -11, k / nForeLugs)];
    drawTreadLugAndNotch(
      pTopL,
      pTopR,
      pBotL,
      pBotR,
      k < nForeLugs - 1 ? pNextTop : null,
      k < nForeLugs - 1 ? pNextBot : null,
      inVec,
      lugLight
    );
  }

  // =========================================================================
  // 11. BRASS EYELETS & SPEED HOOKS
  // =========================================================================
  function drawEyeletOrHook(hw, isNear) {
    const x = hw.x;
    const y = hw.y;
    const scaleF = isNear ? 1.0 : 0.82;

    if (!hw.isHook) {
      // Heavy flanged brass eyelet: black center hole + concentric metallic white burin arcs + radial sheen ticks
      for (let r = 0; r < 6; r++) {
        const rad = map(r, 0, 5, 1.0, 5.2) * scaleF;
        brush.set("gouge_black", PAL.ink, 1.3);
        brush.circle(x, y, rad, 0.05);
      }
      for (let ring = 0; ring < 4; ring++) {
        const rad = map(ring, 0, 3, 6.2, 11.2) * scaleF;
        // Upper-left metallic highlight arc
        brush.set("burin_bold", ring < 2 ? PAL.bone : PAL.parchment, 0.95 * scaleF);
        brush.arc(x, y, rad, 165, 345);
        // Lower-right subtle rim reflection
        brush.set("burin_hair", PAL.earthMid, 0.75 * scaleF);
        brush.arc(x, y, rad, 5, 145);
      }
      // Radial metallic reflection ticks on the brass flange
      for (let a = 0; a < 16; a++) {
        const ang = a * 22.5;
        const rIn = 5.8 * scaleF;
        const rOut = 11.5 * scaleF;
        const x0 = x + cos(ang) * rIn;
        const y0 = y + sin(ang) * rIn * 0.88;
        const x1 = x + cos(ang) * rOut;
        const y1 = y + sin(ang) * rOut * 0.88;
        const spec = pow(max(0, cos(ang - 235)), 2) + 0.35 * pow(max(0, cos(ang - 55)), 2);
        if (spec > 0.2) {
          safeLine(
            x0,
            y0,
            x1,
            y1,
            spec > 0.6 ? "burin_bold" : "burin_fine",
            spec > 0.6 ? PAL.bone : PAL.parchment,
            (0.65 + 0.6 * spec) * scaleF
          );
        }
      }
    } else {
      // Heavy curved brass speed-hook (rivet base + C-curved hook catching top specular light)
      for (let ring = 0; ring < 3; ring++) {
        const rad = map(ring, 0, 2, 4.5, 8.8) * scaleF;
        brush.set("burin_fine", PAL.parchment, 0.85 * scaleF);
        brush.arc(x, y, rad, 150, 350);
      }
      // Sculpted hook arm curving out and up
      const dir = isNear ? -1 : 1;
      for (let s = -2; s <= 2; s++) {
        const off = s * 1.3 * scaleF;
        const hPts = [
          [x, y + off * 0.5, 0.6],
          [x + dir * 11 * scaleF, y - 5 * scaleF + off, 1.25],
          [x + dir * 14 * scaleF, y - 14 * scaleF + off * 0.7, 1.35],
          [x + dir * 6 * scaleF, y - 17 * scaleF + off * 0.5, 0.9]
        ];
        const col = s <= 0 ? PAL.bone : PAL.putty;
        safeSpline(hPts, s <= 0 ? "burin_bold" : "burin_fine", col, 0.92 * scaleF, 0.45);
      }
    }
  }

  for (const h of farHardware) drawEyeletOrHook(h, false);
  for (const h of nearHardware) drawEyeletOrHook(h, true);

  // =========================================================================
  // 12. BRAIDED WORK-BOOT LACE & HYPER-DETAILED FRAYED FILAMENT ENDS
  // =========================================================================
  function drawBraidedCordSegment(ctrlPts, radius, steps = 58) {
    // 1. Dark reserve core so the cord body is solid and crisp
    const spine = [];
    for (let i = 0; i <= 24; i++) {
      const t = i / 24;
      const p = bPt(ctrlPts[0], ctrlPts[1], ctrlPts[2], ctrlPts[3], t);
      spine.push([p[0], p[1], 1.1]);
    }
    safeSpline(spine, "gouge_black", PAL.ink, 2.2, 0.4);

    // 2. Longitudinal rim highlight along the lit edge of the cord + subtle shadow edge
    const litEdge = [];
    const shdEdge = [];
    for (let i = 0; i <= 32; i++) {
      const t = i / 32;
      const p = bPt(ctrlPts[0], ctrlPts[1], ctrlPts[2], ctrlPts[3], t);
      const pNext = bPt(
        ctrlPts[0],
        ctrlPts[1],
        ctrlPts[2],
        ctrlPts[3],
        min(1, t + 0.02)
      );
      const tx = pNext[0] - p[0];
      const ty = pNext[1] - p[1];
      const len = sqrt(tx * tx + ty * ty) || 1;
      let nx = -ty / len;
      let ny = tx / len;
      // Ensure normal points toward upper-left light source
      if (nx * -0.6 + ny * -0.8 < 0) {
        nx = -nx;
        ny = -ny;
      }
      litEdge.push([p[0] + nx * radius * 0.78, p[1] + ny * radius * 0.78, 0.95]);
      shdEdge.push([p[0] - nx * radius * 0.82, p[1] - ny * radius * 0.82, 0.55]);
    }
    safeSpline(shdEdge, "burin_hair", PAL.earthMid, 0.75, 0.42);
    safeSpline(litEdge, "burin_fine", PAL.ivory, 0.88, 0.42);

    // 3. Helical woven-braid cross-contour strokes wrapping around the cylindrical cord
    for (let i = 0; i <= steps; i++) {
      const t = i / steps;
      const p = bPt(ctrlPts[0], ctrlPts[1], ctrlPts[2], ctrlPts[3], t);
      const pNext = bPt(
        ctrlPts[0],
        ctrlPts[1],
        ctrlPts[2],
        ctrlPts[3],
        min(1, t + 0.015)
      );
      const tx = (pNext[0] - p[0]) / (sqrt(sq(pNext[0] - p[0]) + sq(pNext[1] - p[1])) || 1);
      const ty = (pNext[1] - p[1]) / (sqrt(sq(pNext[0] - p[0]) + sq(pNext[1] - p[1])) || 1);
      let nx = -ty;
      let ny = tx;
      if (nx * -0.6 + ny * -0.8 < 0) {
        nx = -nx;
        ny = -ny;
      }

      // Alternating V-weave braid angle
      const weaveDir = i % 2 === 0 ? 1 : -1;
      const wPts = [];
      for (let s = -1.0; s <= 1.0; s += 0.33) {
        const cyl = sqrt(max(0, 1 - s * s));
        const px =
          p[0] -
          nx * s * radius * 0.92 +
          tx * weaveDir * cyl * radius * 0.55;
        const py =
          p[1] -
          ny * s * radius * 0.92 +
          ty * weaveDir * cyl * radius * 0.55;
        // Brightest on the lit side (s < 0), tapering toward shadow side (s > 0)
        const pr = constrain(map(s, -0.9, 0.95, 1.25, 0.18), 0.15, 1.3);
        wPts.push([px, py, pr]);
      }
      safeSpline(wPts, "burin_fine", i % 3 === 0 ? PAL.bone : PAL.parchment, 0.86, 0.45);
    }

    // 4. Stray abraded micro-fuzz hairs along the worn lace body
    for (let i = 2; i < steps - 2; i += 4) {
      const t = i / steps;
      const p = bPt(ctrlPts[0], ctrlPts[1], ctrlPts[2], ctrlPts[3], t);
      const ang = noise(i * 0.7, p[0] * 0.02) * 360;
      const fuzzLen = random(4, 9.5);
      const fx1 = p[0] + cos(ang) * radius * 0.85;
      const fy1 = p[1] + sin(ang) * radius * 0.85;
      const fx2 = fx1 + cos(ang + random(-35, 35)) * fuzzLen;
      const fy2 = fy1 + sin(ang + random(-35, 35)) * fuzzLen;
      safeLine(fx1, fy1, fx2, fy2, "burin_hair", PAL.putty, 0.62);
    }
  }

  // Draw all crisscrossed throat laces, cascading foreground lace, and far loose lace
  for (const c of crossLaceCurves) drawBraidedCordSegment(c.pts, c.rad, 34);
  for (const c of farLooseLaceSegs) drawBraidedCordSegment(c.pts, c.rad, 42);
  for (const c of cascadeLaceSegs) drawBraidedCordSegment(c.pts, c.rad, 64);

  // Function to render an exploded, unraveled frayed lace tip (missing aglet)
  function drawFrayedLaceBurst(originPt, baseAngleDeg, numFilaments, maxLen, spreadDeg) {
    // 1. Unraveling outer sheath collar (split woven strands just before the burst)
    for (let s = 0; s < 14; s++) {
      const a = baseAngleDeg + map(s, 0, 13, -spreadDeg * 0.45, spreadDeg * 0.45);
      const len = random(14, 28);
      const p1 = [
        originPt[0] + cos(a) * len * 0.45,
        originPt[1] + sin(a) * len * 0.45,
        1.15
      ];
      const p2 = [
        originPt[0] + cos(a + random(-18, 18)) * len,
        originPt[1] + sin(a + random(-18, 18)) * len,
        0.55
      ];
      safeSpline(
        [[originPt[0], originPt[1], 1.2], p1, p2],
        "burin_bold",
        s % 2 === 0 ? PAL.bone : PAL.parchment,
        0.92,
        0.45
      );
    }

    // 2. Exploded tuft of kinky, curling individual thread filaments
    for (let f = 0; f < numFilaments; f++) {
      const frac = f / (numFilaments - 1);
      const startSpread = map(frac, 0, 1, -5.5, 5.5);
      const perpAngle = baseAngleDeg + 90;
      const sx = originPt[0] + cos(perpAngle) * startSpread;
      const sy = originPt[1] + sin(perpAngle) * startSpread;

      const fanAngle =
        baseAngleDeg +
        map(frac, 0, 1, -spreadDeg * 0.5, spreadDeg * 0.5) +
        random(-14, 14);
      const totalLen = maxLen * random(0.38, 1.08) * (1 - 0.28 * sq(frac - 0.5) * 2);

      const fPts = [[sx, sy, random(0.85, 1.2)]];
      let cx = sx;
      let cy = sy;
      let curAng = fanAngle;
      const nNodes = 5;

      for (let n = 1; n <= nNodes; n++) {
        const stepL = (totalLen / nNodes) * random(0.8, 1.2);
        // Natural cotton/nylon crimp & curl from braided memory
        const crimp =
          (n % 2 === 0 ? 1 : -1) * random(8, 24) +
          (noise(f * 0.35, n * 0.6) - 0.5) * 42;
        curAng += crimp;
        // Gravity pull & floor rest
        const dyFloor = sin(curAng) * stepL * 0.72 + stepL * 0.14;
        cx += cos(curAng) * stepL;
        cy += dyFloor;
        const pressure = constrain(map(n, 1, nNodes, 0.95, 0.12), 0.1, 1.1);
        fPts.push([cx, cy, pressure]);
      }

      const isBright = f % 3 === 0 || abs(frac - 0.42) < 0.18;
      const col = isBright
        ? PAL.bone
        : f % 2 === 0
        ? PAL.ivory
        : f % 5 === 0
        ? PAL.earthMid
        : PAL.parchment;
      const bName = isBright ? "burin_fine" : "burin_hair";
      safeSpline(fPts, bName, col, isBright ? 0.88 : 0.72, 0.48);
    }
  }

  // Primary foreground frayed lace burst resting on the dark ground at [878, 1036]
  drawFrayedLaceBurst([878, 1036], 12, 82, 96, 118);

  // Secondary frayed lace tip dangling over the upper vamp bridge at [848, 548]
  drawFrayedLaceBurst([848, 548], 32, 44, 52, 88);

  noLoop();
}

