// ===========================================================================
// OPTICAL LIGHTING HELPER (OVERHEAD FLUORESCENT TUBES)
// ===========================================================================
function getFluorescentLight(x, y) {
  // Twin diagonal overhead fluorescent fixture reflections at -26 deg
  let ang = -26 * (Math.PI / 180);
  let rx = (x - 600) * Math.cos(ang) - (y - 520) * Math.sin(ang);
  let ry = (x - 600) * Math.sin(ang) + (y - 520) * Math.cos(ang);

  // Distance to two parallel light tubes at ry = -75 and ry = +75
  let d1 = Math.abs(ry + 75);
  let d2 = Math.abs(ry - 75);
  let tube1 = Math.exp(-(d1 * d1) / (2 * 68 * 68)) * Math.exp(-(rx * rx) / (2 * 520 * 520));
  let tube2 = Math.exp(-(d2 * d2) / (2 * 68 * 68)) * Math.exp(-(rx * rx) / (2 * 520 * 520));

  // Secondary softer fixture reflection in lower half
  let ry2 = ry - 360;
  let rx2 = rx + 120;
  let tube3 = 0.45 * Math.exp(-(ry2 * ry2) / (2 * 95 * 95)) * Math.exp(-(rx2 * rx2) / (2 * 480 * 480));

  // Radial arena ambient falloff
  let radial = Math.exp(-((x - 590) * (x - 590) + (y - 580) * (y - 580)) / (2 * 680 * 680));

  return constrain(0.25 + 0.42 * radial + 0.55 * (tube1 + tube2 + tube3), 0.15, 1.0);
}

// ===========================================================================
// 1. DEEP ICE & SUB-SURFACE MARKINGS
