function drawSubsurfaceRinkAndCharcoalIce() {
  brush.noStroke();

  // Deep base wash
  brush.wash("#0a0f17", 255);
  brush.rect(0, 0, width, height);
  brush.noWash();

  // Sub-surface painted rink geometry (frozen 1.5 inches beneath dark ice)
