  let circleCx = -80;
  let circleCy = 680;
  let circleR = 820;

  // Painted terracotta arc (drawn as thick warm bands before burying under ice mass)
  for (let pass = 0; pass < 5; pass++) {
    let rOff = (pass - 2) * 5.5;
    brush.set("ice_charcoal", pass === 2 ? "#7a2e24" : "#59211b", 2.4);
    brush.arc(circleCx, circleCy, circleR + rOff, -48, 38);
  }
  // Warm antique ochre-gold framing edge along the sub-surface line
  brush.set("ice_charcoal", "#634824", 1.5);
  brush.arc(circleCx, circleCy, circleR - 18, -48, 38);
  brush.arc(circleCx, circleCy, circleR + 18, -48, 38);

  // Sub-surface hash mark & L-line inside the circle
  for (let i = -3; i <= 3; i++) {
    let off = i * 3.5;
    brush.set("ice_charcoal", "#682820", 1.9);
    brush.line(685 + off, 200, 815 + off, 145);
    brush.line(410, 625 + off, 545, 625 + off);
    brush.line(545 + off, 625, 545 + off, 735);
  }

  // Sub-surface warm terracotta face-off spot glow in lower-left
  brush.noStroke();
  brush.fill("#5e241d", 85);
