  // Bury the painted markings beneath dense blue-black and warm charcoal ice washes
  let iceZones = [
    { x: 0, y: 0, w: 1200, h: 1200, col: "#0b111a", op: 165 },
    { x: 80, y: 60, w: 1040, h: 1080, col: "#12151c", op: 110 },
    { x: 0, y: 380, w: 1200, h: 520, col: "#171418", op: 85 },
    { x: 220, y: 0, w: 760, h: 1200, col: "#0c131d", op: 120 }
  ];
  brush.fillBleed(0.5, "out");
