  for (let z of iceZones) {
    brush.fill(z.col, z.op);
    brush.rect(z.x, z.y, z.w, z.h);
  }
  brush.noFill();

  // Dense Charcoal Mass Passes (as specified: "deep blue-black ice is laid down as dense charcoal mass")
  let massPatches = [
    { x: -40, y: -40, w: 680, h: 680, col: "#0d131d", prec: 0.65, str: 0.65 },
    { x: 540, y: -40, w: 700, h: 680, col: "#101621", prec: 0.65, str: 0.65 },
    { x: -40, y: 540, w: 680, h: 700, col: "#131319", prec: 0.65, str: 0.65 },
    { x: 540, y: 540, w: 700, h: 700, col: "#0c121b", prec: 0.65, str: 0.65 },
    { x: 180, y: 160, w: 840, h: 880, col: "#17151a", prec: 0.72, str: 0.45 },
    { x: 60, y: 340, w: 1080, h: 520, col: "#0f1722", prec: 0.75, str: 0.45 }
  ];
  for (let mp of massPatches) {
    brush.noStroke();
