      precision: mp.prec,
      strength: mp.str,
      gradient: 0.25,
      outline: false
    });
    brush.rect(mp.x, mp.y, mp.w, mp.h);
    brush.noMass();
  }

  // Zamboni resurfacer directional grain & fine charcoal cross-hatching
