// ===========================================================================
// 2. OVERHEAD FLUORESCENT REFLECTION BANDS
// ===========================================================================
function drawFluorescentReflections() {
  let ang = -26 * (Math.PI / 180);
  let cosA = Math.cos(ang);
  let sinA = Math.sin(ang);

  // Draw two diffused tubular overhead fluorescent reflections in the polished ice
  let tubes = [
    { cx: 600, cy: 445, len: 920, w: 86, coreCol: "#434240", haloCol: "#212d3b" },
    { cx: 665, cy: 580, len: 920, w: 86, coreCol: "#47433e", haloCol: "#232e3c" },
    { cx: 470, cy: 890, len: 760, w: 72, coreCol: "#343232", haloCol: "#1a232e" }
  ];

  for (let t of tubes) {
    // Soft charcoal/pastel sheen streaks along the reflection axis
    for (let i = 0; i < 95; i++) {
      let along = random(-t.len * 0.5, t.len * 0.5);
      let across = randomGaussian(0, t.w * 0.38);
      let segLen = random(65, 210);

      let x1 = t.cx + along * cosA - across * sinA;
      let y1 = t.cy + along * sinA + across * cosA;
      let x2 = x1 + segLen * cosA;
      let y2 = y1 + segLen * sinA;

      let isCore = Math.abs(across) < t.w * 0.22;
      let strokeCol = isCore ? t.coreCol : t.haloCol;
      brush.set("charcoal", strokeCol, random(0.35, 0.75));
      brush.line(x1, y1, x2, y2);
    }

    // Subtle warm phosphor mist along the core of the fluorescent reflection
    for (let i = 0; i < 45; i++) {
      let along = random(-t.len * 0.42, t.len * 0.42);
      let across = randomGaussian(0, t.w * 0.18);
      let x1 = t.cx + along * cosA - across * sinA;
      let y1 = t.cy + along * sinA + across * cosA;
      let x2 = x1 + random(35, 110) * cosA;
      let y2 = y1 + random(35, 110) * sinA;
      brush.set("2B", "#635b52", random(0.18, 0.34));
      brush.line(x1, y1, x2, y2);
    }
  }
}

// ===========================================================================
// CORE BLADE TRACK RENDERER (PHYSICS OF ICE INCISION + SHAVED SNOW RIDGES)
// ===========================================================================
function renderSkateTrack(pts, opts = {}) {
  if (!pts || pts.length < 3) return;

  let doubleEdge = opts.doubleEdge || false;
  let hollowSep = opts.hollowSep || 3.8;
  let weightMul = opts.weight || 1.0;
  let snowDensity = opts.snowDensity !== undefined ? opts.snowDensity : 1.0;
  let snowSide = opts.snowSide || 1; // +1 or -1 normal side
  let isFresh = opts.isFresh !== undefined ? opts.isFresh : true;
  let warmTint = opts.warmTint !== undefined ? opts.warmTint : 0.65;

  // Compute normals and arc lengths at each vertex
  let normals = [];
  for (let i = 0; i < pts.length; i++) {
    let pPrev = pts[Math.max(0, i - 1)];
    let pNext = pts[Math.min(pts.length - 1, i + 1)];
    let dx = pNext[0] - pPrev[0];
    let dy = pNext[1] - pPrev[1];
    let len = Math.hypot(dx, dy) || 1;
    normals.push([-dy / len, dx / len, dx / len, dy / len]);
  }

  // 1. Dark incised trough shadow (overhead light creates a crisp dark groove on the upper side)
  let shadowPts = pts.map((p, idx) => [
    p[0] - 0.9,
    p[1] - 1.1,
    (p[2] || 0.8) * 0.75 * weightMul
  ]);
  brush.set("2H", "#04060a", 0.32 * weightMul);
  brush.spline(shadowPts, 0.45);

  // 2. Sub-surface crushed ice bed (blue-slate & warm parchment grey)
  let crushedCol = random() < warmTint ? "#6e6862" : "#566678";
  brush.set("2B", crushedCol, 0.36 * weightMul);
  brush.spline(pts, 0.45);

  // 3. Main razor edge incision(s)
  if (doubleEdge) {
    let leftPts = [];
    let rightPts = [];
    for (let i = 0; i < pts.length; i++) {
      let nx = normals[i][0];
      let ny = normals[i][1];
      let pr = (pts[i][2] || 0.85) * weightMul;
      leftPts.push([pts[i][0] + nx * (hollowSep * 0.5), pts[i][1] + ny * (hollowSep * 0.5), pr]);
      rightPts.push([pts[i][0] - nx * (hollowSep * 0.5), pts[i][1] - ny * (hollowSep * 0.5), pr * 0.88]);
    }

    let col1 = isFresh ? (random() < warmTint ? "#f5ede2" : "#e3edf7") : "#9e9891";
    let col2 = isFresh ? (random() < warmTint ? "#e6dbd0" : "#cad8e6") : "#858a91";

    brush.set("blade_edge", col1, 0.32 * weightMul);
    brush.spline(leftPts, 0.45);

    brush.set("blade_edge", col2, 0.27 * weightMul);
    brush.spline(rightPts, 0.45);

    if (isFresh) {
      brush.set("rotring", "#fffaf2", 0.2 * weightMul);
      brush.spline(leftPts, 0.45);
    }
  } else {
    let mainCol = isFresh ? (random() < warmTint ? "#f7efe4" : "#e6f0fa") : "#9a958e";
    brush.set("blade_edge", mainCol, 0.35 * weightMul);
    brush.spline(pts, 0.45);

    if (isFresh) {
      brush.set("rotring", "#fffdf9", 0.22 * weightMul);
      brush.spline(pts, 0.45);
    }
  }

  // 4. Tiny Shaved Snow Ridges catching the overhead fluorescent highlight along the blade line
  if (snowDensity <= 0) return;

  for (let i = 1; i < pts.length - 1; i++) {
    let p0 = pts[i];
    let pNext = pts[i + 1];
    let segDist = Math.hypot(pNext[0] - p0[0], pNext[1] - p0[1]);
    let nx = normals[i][0] * snowSide;
    let ny = normals[i][1] * snowSide;
    let tx = normals[i][2];
    let ty = normals[i][3];
    let pr = p0[2] || 0.8;

    let steps = Math.max(1, Math.floor((segDist / 6.5) * snowDensity));
    for (let s = 0; s < steps; s++) {
      if (random() > 0.72 * snowDensity) continue;

      let t = (s + random(0.1, 0.9)) / steps;
      let bx = lerp(p0[0], pNext[0], t);
      let by = lerp(p0[1], pNext[1], t);

      let light = getFluorescentLight(bx, by);
      let ridgeDist = (doubleEdge ? hollowSep * 0.5 : 0.8) + random(0.8, 3.8 * pr);

      let rx = bx + nx * ridgeDist;
      let ry = by + ny * ridgeDist;
      let ridgeLen = random(2.2, 7.5) * pr;
      let driftAngle = random(-0.35, 0.35);
      let rtx = tx * Math.cos(driftAngle) - ty * Math.sin(driftAngle);
      let rty = tx * Math.sin(driftAngle) + ty * Math.cos(driftAngle);

      // Tiny dark relief shadow under the snow ridge
      brush.set("rotring", "#05070c", 0.24 * pr);
      brush.line(
        rx + nx * 1.1,
        ry + ny * 1.1,
        rx + nx * 1.1 + rtx * ridgeLen,
        ry + ny * 1.1 + rty * ridgeLen
      );

      // Crushed snow ridge body (warm ivory / frost white)
      let snowCol = light > 0.55
        ? (random() < 0.7 ? "#fffaf0" : "#ffffff")
        : (random() < 0.65 ? "#e3d8ca" : "#d0dce8");

      brush.set("snow_ridge", snowCol, (0.22 + 0.18 * light) * pr * weightMul);
      brush.line(rx, ry, rx + rtx * ridgeLen, ry + rty * ridgeLen);

      // Occasional tiny displaced snow crumb / crystalline burr kicked out beside the ridge
      if (random() < 0.28 * snowDensity * pr) {
        let crumbDist = ridgeDist + random(2.5, 11.0 * pr);
        let cx = bx + nx * crumbDist + rtx * random(-3, 3);
        let cy = by + ny * crumbDist + rty * random(-3, 3);
        let crumbLen = random(1.0, 2.8);
        brush.set("rotring", light > 0.5 ? "#fffdf7" : "#d9cfc3", random(0.18, 0.32));
        brush.line(cx, cy, cx + nx * crumbLen, cy + ny * crumbLen);
      }
    }
  }
}

// ===========================================================================
// 3. WEATHERED / OLDER SESSION SCRATCHES (SUB-LAYER DEPTH)
// ===========================================================================
function drawWeatheredScratches() {
  // 75 older, duller skate tracks from earlier in the session
  for (let i = 0; i < 75; i++) {
    let angle = random(-Math.PI, Math.PI);
    let cx = random(80, 1120);
    let cy = random(80, 1120);
    let len = random(180, 950);
    let curve = random(-0.0009, 0.0009);

    let pts = [];
    let steps = 14;
    let x = cx - Math.cos(angle) * (len * 0.5);
    let y = cy - Math.sin(angle) * (len * 0.5);
    let curAng = angle;
    let stepLen = len / steps;

    for (let s = 0; s <= steps; s++) {
      pts.push([x, y, random(0.35, 0.65)]);
      curAng += curve * stepLen;
      x += Math.cos(curAng) * stepLen;
      y += Math.sin(curAng) * stepLen;
    }

    let oldPalette = ["#25313f", "#344150", "#4a4847", "#5e5a56", "#3d4c5c", "#736d66"];
    let col = random(oldPalette);
    let bName = random() < 0.5 ? "2H" : "cpencil";
    brush.set(bName, col, random(0.16, 0.32));
    brush.spline(pts, 0.45);
  }
}

// ===========================================================================
// 4. FAST STRAIGHT & SWEEPING GLIDE TRACKS
// ===========================================================================
function drawFastGlideTracks() {
  let tracks = [
    // Fast diagonal edge glides cutting all the way across the rink
    { x0: -40, y0: 980, x1: 1240, y1: 140, bend: -55, doubleEdge: true, hollowSep: 4.0, w: 1.05, snow: 1.1, side: 1 },
    { x0: -40, y0: 1035, x1: 1240, y1: 195, bend: -52, doubleEdge: true, hollowSep: 3.8, w: 0.95, snow: 0.95, side: 1 },
    { x0: 110, y0: -40, x1: 1080, y1: 1240, bend: 85, doubleEdge: false, w: 0.9, snow: 0.9, side: -1 },
    { x0: 165, y0: -40, x1: 1135, y1: 1240, bend: 82, doubleEdge: true, hollowSep: 3.5, w: 0.85, snow: 0.85, side: -1 },
    { x0: -40, y0: 310, x1: 1240, y1: 685, bend: -95, doubleEdge: false, w: 0.95, snow: 1.0, side: 1 },
    { x0: 1240, y0: 465, x1: -40, y1: 790, bend: 70, doubleEdge: true, hollowSep: 4.2, w: 1.0, snow: 1.05, side: -1 },
    { x0: 420, y0: -40, x1: 95, y1: 1240, bend: -65, doubleEdge: false, w: 0.8, snow: 0.75, side: 1 },
    { x0: 880, y0: -40, x1: 490, y1: 1240, bend: 110, doubleEdge: true, hollowSep: 3.6, w: 0.85, snow: 0.8, side: 1 },
    { x0: -40, y0: 620, x1: 1240, y1: 1060, bend: 45, doubleEdge: false, w: 0.78, snow: 0.7, side: -1 },
    { x0: -40, y0: 115, x1: 1240, y1: 315, bend: 38, doubleEdge: true, hollowSep: 3.4, w: 0.75, snow: 0.65, side: 1 }
  ];

  for (let tr of tracks) {
    let pts = buildArcPoints(tr.x0, tr.y0, tr.x1, tr.y1, tr.bend, 28, 0.85);
    renderSkateTrack(pts, {
      doubleEdge: tr.doubleEdge,
      hollowSep: tr.hollowSep || 3.6,
      weight: tr.w,
      snowDensity: tr.snow,
      snowSide: tr.side,
      isFresh: true,
      warmTint: 0.7
    });
  }
}

function buildArcPoints(x0, y0, x1, y1, bend, numSteps, basePressure) {
  let pts = [];
  let dx = x1 - x0;
  let dy = y1 - y0;
  let len = Math.hypot(dx, dy) || 1;
  let nx = -dy / len;
  let ny = dx / len;

  for (let i = 0; i <= numSteps; i++) {
    let t = i / numSteps;
    let arcOffset = Math.sin(t * Math.PI) * bend;
    let x = lerp(x0, x1, t) + nx * arcOffset;
    let y = lerp(y0, y1, t) + ny * arcOffset;
    let pr = basePressure * (0.75 + 0.35 * Math.sin(t * Math.PI));
    pts.push([x, y, pr]);
  }
  return pts;
}

// ===========================================================================
// 5. BRANCHING FORKS — CROSSOVER ACCELERATION CORRIDOR
// ===========================================================================
function drawCrossoverForks() {
  // A skater accelerating along a grand curve from lower-left (60, 1140) to upper-right (1120, 60)
  // Main curving guide trajectory
  let mainSpine = buildArcPoints(45, 1160, 1140, 45, 195, 48, 0.95);

  // Draw the primary continuous inside-edge track
  renderSkateTrack(mainSpine, {
    doubleEdge: true,
    hollowSep: 3.8,
    weight: 1.05,
    snowDensity: 1.15,
    snowSide: 1,
    isFresh: true,
    warmTint: 0.72
  });

  // 5 Branching Crossover Forks where the crossing blade sets down, carves alongside,
  // and forks outward at an acute angle with a heavy push-off snow ridge
  let forkIndices = [6, 14, 22, 30, 38];
  for (let k = 0; k < forkIndices.length; k++) {
    let startIdx = forkIndices[k];
    let span = 9;
    let forkPts = [];
    let underPushPts = [];

    for (let j = 0; j <= span; j++) {
      let idx = Math.min(mainSpine.length - 2, startIdx + j);
      let p = mainSpine[idx];
      let pNext = mainSpine[idx + 1];
      let tx = pNext[0] - p[0];
      let ty = pNext[1] - p[1];
      let d = Math.hypot(tx, ty) || 1;
      tx /= d;
      ty /= d;
      let nx = -ty;
      let ny = tx;

      let u = j / span;
      // Branching fork starts crossed over (-18px) and diverges sharply (+48px)
      let lat1 = lerp(-18, 46, Math.pow(u, 1.35));
      let pr1 = u < 0.2 ? lerp(0.3, 1.0, u / 0.2) : (u > 0.8 ? lerp(1.25, 0.25, (u - 0.8) / 0.2) : 1.1);
      forkPts.push([p[0] + nx * lat1, p[1] + ny * lat1, pr1]);

      // Secondary push-off edge branching in opposite acute fork (+6px to -52px)
      let lat2 = lerp(8, -54, Math.pow(u, 1.55));
      let pr2 = u < 0.75 ? lerp(0.85, 1.3, u / 0.75) : lerp(1.3, 0.15, (u - 0.75) / 0.25);
      underPushPts.push([p[0] + nx * lat2, p[1] + ny * lat2, pr2]);
    }

    renderSkateTrack(forkPts, {
      doubleEdge: true,
      hollowSep: 3.6,
      weight: 1.05,
      snowDensity: 1.35,
      snowSide: 1,
      isFresh: true,
      warmTint: 0.75
    });

    renderSkateTrack(underPushPts, {
      doubleEdge: false,
      weight: 1.12,
      snowDensity: 1.45,
      snowSide: -1,
      isFresh: true,
      warmTint: 0.75
    });

    // At the end of each crossover push-off, add short feathered toe-flick scratches
    let tip = underPushPts[underPushPts.length - 2];
    let tipEnd = underPushPts[underPushPts.length - 1];
    for (let f = 0; f < 6; f++) {
      let ft = f / 5;
      let fx = lerp(tip[0], tipEnd[0], ft);
      let fy = lerp(tip[1], tipEnd[1], ft);
      brush.set("rotring", "#fffaf0", 0.26);
      brush.line(fx, fy, fx + random(-14, 14), fy + random(-14, 14));
    }
  }
}

// ===========================================================================
// 6. TIGHT SPIRALS — SCRATCH SPIN VORTEX
// ===========================================================================
function drawSpinVortex(cx, cy) {
  // 1. Entry spiral sweeping in from upper-left (-40, 120) into spin center (cx, cy)
  let entryPts = [];
  let totalSteps = 110;
  for (let i = 0; i <= totalSteps; i++) {
    let t = i / totalSteps;
    // Angle winds through 2.4 revolutions while radius decays from 490 down to 58
    let theta = -2.35 + Math.pow(t, 1.45) * (Math.PI * 3.6);
    let r = 490 * Math.pow(1 - t * 0.88, 1.55);
    // Slight eccentric drift as skater centers the spin
    let driftX = (1 - t) * -45;
    let driftY = (1 - t) * -30;
    let x = cx + driftX + Math.cos(theta) * r;
    let y = cy + driftY + Math.sin(theta) * r;
    let pr = lerp(0.85, 1.15, t);
    entryPts.push([x, y, pr]);
  }

  renderSkateTrack(entryPts, {
    doubleEdge: false,
    weight: 1.05,
    snowDensity: 1.25,
    snowSide: 1,
    isFresh: true,
    warmTint: 0.7
  });

  // 2. Tight Trochoidal Spin Loops (9 overlapping revolutions around the spin sweet-spot)
  // A spinning skate blade traces a trochoid (rolling circle + small loop excursion at the cusp)
  let numRevs = 9;
  for (let rev = 0; rev < numRevs; rev++) {
    let loopPts = [];
    let stepsPerRev = 38;
    let revFrac = rev / numRevs;

    // Spin radius tightens from 64px down to 14px
    let R = lerp(64, 14, Math.pow(revFrac, 0.85));
    // Eccentricity creates the signature figure-skating spin loop / three-turn cusp
    let loopEcc = R * lerp(0.58, 0.42, revFrac);
    let centerAngle = rev * 0.68;
    let ox = cx + Math.cos(centerAngle) * lerp(18, 3, revFrac);
    let oy = cy + Math.sin(centerAngle) * lerp(18, 3, revFrac);

    for (let s = 0; s <= stepsPerRev; s++) {
      let u = s / stepsPerRev;
      let phi = (rev + u) * Math.PI * 2;
      // Epitrochoid / hypotrochoid blend for authentic figure skating spin trace
      let x = ox + R * Math.cos(phi) - loopEcc * Math.cos(3 * phi + rev * 0.4);
      let y = oy + R * Math.sin(phi) - loopEcc * Math.sin(3 * phi + rev * 0.4);
      let pr = 0.75 + 0.45 * Math.abs(Math.sin(1.5 * phi));
      loopPts.push([x, y, pr]);
    }

    renderSkateTrack(loopPts, {
      doubleEdge: rev < 3,
      hollowSep: 2.8,
      weight: lerp(0.95, 0.72, revFrac),
      snowDensity: lerp(1.15, 0.85, revFrac),
      snowSide: 1,
      isFresh: true,
      warmTint: 0.75
    });

    // Toe-pick crescent stabs at the tight cusps of each spin revolution
    for (let c = 0; c < 3; c++) {
      let cuspPhi = (rev + c / 3) * Math.PI * 2;
      let tx = ox + (R - loopEcc) * Math.cos(cuspPhi);
      let ty = oy + (R - loopEcc) * Math.sin(cuspPhi);
      let pickR = random(4.5, 9.5);
      let startA = degrees(cuspPhi) - 45;
      let endA = degrees(cuspPhi) + 45;

      brush.set("2H", "#04060a", 0.35);
      brush.arc(tx - 1, ty - 1, pickR, startA, endA);
      brush.set("snow_ridge", "#fffaf0", 0.42);
      brush.arc(tx, ty, pickR, startA, endA);
      brush.set("rotring", "#ffffff", 0.28);
      brush.arc(tx, ty, pickR, startA + 10, endA - 10);
    }
  }

  // 3. Pulverized Frost Scar at Spin Center + Radial Snow Ejecta
  for (let i = 0; i < 65; i++) {
    let a = random(0, Math.PI * 2);
    let r1 = random(0, 14);
    let r2 = r1 + random(3, 18);
    let x1 = cx + Math.cos(a) * r1;
    let y1 = cy + Math.sin(a) * r1;
    let x2 = cx + Math.cos(a + random(-0.4, 0.4)) * r2;
    let y2 = cy + Math.sin(a + random(-0.4, 0.4)) * r2;
    brush.set(i % 2 === 0 ? "snow_ridge" : "rotring", i % 3 === 0 ? "#ffffff" : "#f2e7d8", random(0.22, 0.45));
    brush.line(x1, y1, x2, y2);
  }

  // Tangential shaved snow spray flung outward by centrifugal force
  for (let i = 0; i < 140; i++) {
    let a = random(0, Math.PI * 2);
    let dist = random(18, 95);
    let sx = cx + Math.cos(a) * dist;
    let sy = cy + Math.sin(a) * dist;
    let tang = a + Math.PI * 0.42 + random(-0.2, 0.2);
    let slen = random(1.2, 4.5);
    brush.set("rotring", random() < 0.7 ? "#f7efe4" : "#ffffff", random(0.16, 0.3));
    brush.line(sx, sy, sx + Math.cos(tang) * slen, sy + Math.sin(tang) * slen);
  }

  // 4. Sharp Spin Exit Edge slicing out toward lower-left
  let exitPts = buildArcPoints(cx - 8, cy + 12, -40, 890, 62, 24, 1.05);
  renderSkateTrack(exitPts, {
    doubleEdge: true,
    hollowSep: 3.8,
    weight: 1.08,
    snowDensity: 1.3,
    snowSide: -1,
    isFresh: true,
    warmTint: 0.75
  });
}

// ===========================================================================
// 7. SHORT STUBBY GOUGES — HOCKEY STOPS & CHECK STOPS
// ===========================================================================
function drawHockeyStop(cx, cy, stopAngleRad, bladeLength, footSpread) {
  // Direction of blade alignment during stop: stopAngleRad
  // Direction of sideways skid (perpendicular to blade): skidAngleRad
  let bx = Math.cos(stopAngleRad);
  let by = Math.sin(stopAngleRad);
  let sx = -by; // Skid direction
  let sy = bx;

  // Two parallel feet in a hockey stop (front foot & rear trailing foot)
  let feet = [
    { ox: cx, oy: cy, len: bladeLength, skidDist: 44, weight: 1.1 },
    { ox: cx - sx * 52 + bx * footSpread * 0.65, oy: cy - sy * 52 + by * footSpread * 0.65, len: bladeLength * 0.85, skidDist: 36, weight: 0.92 }
  ];

  for (let foot of feet) {
    // 1. Incoming curving track that whips into the stop
    let entryStart = [foot.ox - sx * 420 - bx * 260, foot.oy - sy * 420 - by * 260];
    let entryEnd = [foot.ox - bx * (foot.len * 0.35), foot.oy - by * (foot.len * 0.35)];
    let entryPts = buildArcPoints(entryStart[0], entryStart[1], entryEnd[0], entryEnd[1], -68, 22, 0.95);
    renderSkateTrack(entryPts, {
      doubleEdge: true,
      hollowSep: 3.6,
      weight: 0.92,
      snowDensity: 0.9,
      snowSide: 1,
      isFresh: true
    });

    // 2. Short Stubby Chatter Gouges (stick-slip physics as blade chatters sideways)
    let numChatterSteps = 16;
    for (let step = 0; step <= numChatterSteps; step++) {
      let u = step / numChatterSteps;
      // Blade progresses along skid direction while rotating slightly
      let skidProg = Math.pow(u, 0.85) * foot.skidDist;
      let curAngle = stopAngleRad + (u - 0.5) * 0.22;
      let cbx = Math.cos(curAngle);
      let cby = Math.sin(curAngle);
      let csx = -cby;
      let csy = cbx;

      let centerS = [foot.ox + csx * skidProg, foot.oy + csy * skidProg];

      // Draw stubby parallel gouge teeth across the blade contact length
      let numStubs = Math.floor(foot.len / 7.5);
      for (let g = 0; g < numStubs; g++) {
        if (random() < 0.22) continue;
        let alongBlade = ((g / numStubs) - 0.5) * foot.len + random(-2.5, 2.5);
        let env = Math.sin((g / numStubs) * Math.PI); // deeper in middle of blade rocker
        if (env < 0.15) continue;

        let gx = centerS[0] + cbx * alongBlade;
        let gy = centerS[1] + cby * alongBlade;
        let stubLen = random(5.5, 16.5) * env * (0.6 + 0.5 * u);

        // Dark chatter shadow
        brush.set("2H", "#04070b", 0.32 * env);
        brush.line(gx - 0.8, gy - 0.8, gx + csx * stubLen - 0.8, gy + csy * stubLen - 0.8);

        // Stubby white gouge mark
        let stubCol = u > 0.65 ? "#fffaf2" : (random() < 0.65 ? "#e8ded1" : "#d4e0ec");
        brush.set(u > 0.5 ? "snow_ridge" : "cpencil", stubCol, (0.28 + 0.22 * u) * env * foot.weight);
        brush.line(gx, gy, gx + csx * stubLen, gy + csy * stubLen);

        if (u > 0.55 && random() < 0.5) {
          brush.set("rotring", "#ffffff", 0.24 * env);
          brush.line(gx + csx * stubLen * 0.3, gy + csy * stubLen * 0.3, gx + csx * stubLen, gy + csy * stubLen);
        }
      }
    }

    // 3. Heavy Piled-Up Shaved Snow Ridge along the stopping front edge
    let ridgeCenter = [foot.ox + sx * (foot.skidDist + 4), foot.oy + sy * (foot.skidDist + 4)];
    let ridgePts = [];
    let shadowRidgePts = [];
    let numRidgePts = 28;
    for (let r = 0; r <= numRidgePts; r++) {
      let ru = (r / numRidgePts) - 0.5;
      let env = Math.sin((r / numRidgePts) * Math.PI);
      let bow = env * 12.0; // Curved snow bank
      let jitter = (noise(r * 0.6, foot.ox * 0.01) - 0.5) * 6.5;
      let px = ridgeCenter[0] + bx * (ru * foot.len * 1.04) + sx * (bow + jitter);
      let py = ridgeCenter[1] + by * (ru * foot.len * 1.04) + sy * (bow + jitter);
      ridgePts.push([px, py, env * 1.4]);
      shadowRidgePts.push([px + sx * 3.2, py + sy * 3.2, env * 1.2]);
    }

    // Cast shadow on the far side of the piled snow bank
    brush.set("charcoal", "#030508", 0.65 * foot.weight);
    brush.spline(shadowRidgePts, 0.5);

    // Mid-tone warm snow ridge base
    brush.set("snow_ridge", "#d6cabe", 0.72 * foot.weight);
    brush.spline(ridgePts, 0.5);

    // Bright chalk-white snow crest
    brush.set("snow_ridge", "#fffaf0", 0.55 * foot.weight);
    brush.spline(ridgePts, 0.5);

    // Craggy crystalline clumps and forward-sprayed snow granules
    for (let c = 0; c < 135; c++) {
      let ru = random(-0.48, 0.48);
      let env = Math.cos(ru * Math.PI);
      let forwardDist = Math.pow(random(), 1.8) * 58 * env;
      let baseP = [
        ridgeCenter[0] + bx * (ru * foot.len) + sx * (env * 10 + forwardDist),
        ridgeCenter[1] + by * (ru * foot.len) + sy * (env * 10 + forwardDist)
      ];
      let clen = random(1.5, 5.5) * (1 - forwardDist / 65);
      let cang = stopAngleRad + random(-0.6, 0.6);

      // Tiny shadow under snow clump
      brush.set("rotring", "#04060a", 0.22);
      brush.line(baseP[0] + 0.9, baseP[1] + 0.9, baseP[0] + Math.cos(cang) * clen + 0.9, baseP[1] + Math.sin(cang) * clen + 0.9);

      // Bright snow granule
      let gCol = forwardDist < 14 ? "#ffffff" : (random() < 0.7 ? "#f5ece0" : "#dce6f0");
      brush.set(forwardDist < 18 ? "snow_ridge" : "rotring", gCol, random(0.2, 0.42));
      brush.line(baseP[0], baseP[1], baseP[0] + Math.cos(cang) * clen, baseP[1] + Math.sin(cang) * clen);
    }
  }
}

function drawCheckStop(cx, cy, stopAngleRad, bladeLen) {
  // Single-blade T-stop / edge check with stubby gouges
  let bx = Math.cos(stopAngleRad);
  let by = Math.sin(stopAngleRad);
  let sx = -by;
  let sy = bx;

  let numStubs = 24;
  for (let i = 0; i < numStubs; i++) {
    let u = (i / (numStubs - 1)) - 0.5;
    let env = Math.cos(u * Math.PI);
    let gx = cx + bx * (u * bladeLen) + random(-2, 2);
    let gy = cy + by * (u * bladeLen) + random(-2, 2);
    let slen = random(8, 22) * env;

    brush.set("2H", "#04060a", 0.3 * env);
    brush.line(gx - 0.8, gy - 0.8, gx + sx * slen - 0.8, gy + sy * slen - 0.8);

    brush.set("snow_ridge", "#f5ede2", 0.38 * env);
    brush.line(gx, gy, gx + sx * slen, gy + sy * slen);

    brush.set("rotring", "#ffffff", 0.22 * env);
    brush.line(gx + sx * slen * 0.4, gy + sy * slen * 0.4, gx + sx * slen * 1.05, gy + sy * slen * 1.05);
  }
}

