// ===========================================================================
// 9A. COIN-SIZED CONCHOIDAL ICE CHIP (HYPERREAL FORENSIC FOCAL POINT)
// ===========================================================================
function drawCoinSizedChip(cx, cy, radius) {
  // A ~44px diameter coin-sized conchoidal spall crater where a hard heel/toe impact chipped out a lens of ice
  let numVerts = 28;
  let outerRim = [];
  for (let i = 0; i <= numVerts; i++) {
    let a = (i / numVerts) * Math.PI * 2;
    // Slightly scalloped crystalline polygon
    let rMod = radius * (0.88 + 0.18 * noise(Math.cos(a) * 1.8 + 10, Math.sin(a) * 1.8 + 10));
    outerRim.push([cx + Math.cos(a) * rMod, cy + Math.sin(a) * rMod, 0.95]);
  }

  // 1. Deep dark glassy pit interior (shadowed on upper-left wall by overhead light)
  brush.noStroke();
  brush.fill("#030509", 230);
  brush.fillBleed(0.05, "in");
  brush.circle(cx - 1.5, cy - 1.5, radius * 0.92, 0.08);
  brush.noFill();

  // 2. Concentric stepped conchoidal fracture rings (like chipped obsidian / dark ice glass)
  let rings = [0.82, 0.66, 0.5, 0.34, 0.18];
  for (let rIdx = 0; rIdx < rings.length; rIdx++) {
    let rf = rings[rIdx];
    let ringPts = [];
    for (let i = 0; i <= 22; i++) {
      let a = (i / 22) * Math.PI * 2;
      let rr = radius * rf * (0.85 + 0.2 * noise(i * 0.4, rIdx * 2.1));
      // Offset inner rings slightly toward impact point
      let px = cx - (1 - rf) * 3.5 + Math.cos(a) * rr;
      let py = cy - (1 - rf) * 2.5 + Math.sin(a) * rr;
      ringPts.push([px, py, 0.75]);
    }
    let ringCol = rIdx % 2 === 0 ? "#8da0b2" : "#dfd6c9";
    brush.set("rotring", ringCol, 0.22);
    brush.spline(ringPts, 0.35);
  }

  // Subtle warm amber internal bevel refraction glint on lower-right floor of crater
  brush.set("cpencil", "#d9b68c", 0.32);
  brush.arc(cx - 2, cy - 1, radius * 0.58, 15, 125);
  brush.set("rotring", "#ffffff", 0.26);
  brush.arc(cx - 2, cy - 1, radius * 0.55, 25, 110);

  // 3. Radial stress fractures & feather hackle lines inside and around the chip
  for (let i = 0; i < 24; i++) {
    let a = (i / 24) * Math.PI * 2 + random(-0.08, 0.08);
    let inR = radius * random(0.15, 0.45);
    let outR = radius * (random() < 0.45 ? random(1.15, 1.95) : random(0.88, 1.05));
    let x1 = cx + Math.cos(a) * inR;
    let y1 = cy + Math.sin(a) * inR;
    let x2 = cx + Math.cos(a + random(-0.12, 0.12)) * outR;
    let y2 = cy + Math.sin(a + random(-0.12, 0.12)) * outR;

    brush.set("rotring", outR > radius ? "#b8c6d4" : "#f0e7dc", random(0.16, 0.26));
    brush.line(x1, y1, x2, y2);
  }

  // 4. Outer Crystalline Rim (dark undercut shadow on top edge, brilliant white frost rim on bottom edge)
  brush.set("2H", "#020306", 0.42);
  brush.spline(outerRim, 0.25);

  brush.set("snow_ridge", "#f5ede2", 0.38);
  brush.spline(outerRim, 0.25);

  // Specular lower rim catching direct overhead light
  let litRim = outerRim.slice(2, 16);
  brush.set("rotring", "#ffffff", 0.34);
  brush.spline(litRim, 0.25);

  // 5. The Ejected Coin-Sized Ice Shard / Chip resting 38px away on the dark ice!
  let sx = cx + 36;
  let sy = cy + 24;
  let shardPts = [
    [sx - 11, sy - 6, 0.9],
    [sx + 2, sy - 12, 0.9],
    [sx + 13, sy - 3, 1.0],
    [sx + 9, sy + 9, 1.0],
    [sx - 5, sy + 11, 0.9],
    [sx - 13, sy + 2, 0.9],
    [sx - 11, sy - 6, 0.9]
  ];
  let shardShadow = shardPts.map(p => [p[0] + 2.2, p[1] + 2.8, p[2]]);

  // Crisp drop shadow underneath the dislodged ice chip
  brush.set("charcoal", "#020407", 0.55);
  brush.spline(shardShadow, 0.15);

  // Translucent frost body of the dislodged chip
  brush.noStroke();
  brush.fill("#b8c8d8", 95);
  brush.fillBleed(0.02, "in");
  brush.circle(sx, sy, 10, 0.2);
  brush.noFill();

  // Sharp crystalline facets on the dislodged chip
  brush.set("rotring", "#e8dfd3", 0.28);
  brush.spline(shardPts, 0.15);
  brush.set("rotring", "#ffffff", 0.28);
  brush.line(sx - 11, sy - 6, sx + 9, sy + 9);
  brush.line(sx + 2, sy - 12, sx - 5, sy + 11);
  brush.line(sx + 13, sy - 3, sx + 9, sy + 9);

  // Two tiny secondary ice splinters next to the chip
  let splinters = [
    [sx - 20, sy + 14, 4.5, 0.4],
    [sx + 19, sy - 11, 3.8, -0.7],
    [cx - 26, cy + 19, 3.2, 1.1]
  ];
  for (let sp of splinters) {
    let [px, py, sl, sa] = sp;
    brush.set("rotring", "#030508", 0.3);
    brush.line(px + 1, py + 1.2, px + Math.cos(sa) * sl + 1, py + Math.sin(sa) * sl + 1.2);
    brush.set("rotring", "#ffffff", 0.32);
    brush.line(px, py, px + Math.cos(sa) * sl, py + Math.sin(sa) * sl);
  }
}

// ===========================================================================
// 9B. DROPPED GLOVE FIBRES (HYPERREAL WARM PALETTE MICRO-INCIDENTS)
// ===========================================================================
function drawDroppedGloveFibres() {
  // Skater's knit wool/acrylic glove fibers dropped on the ice surface
  let fibres = [
    // Near the hockey stop snow bank (where a skater brushed the ice or adjusted blade)
    { x: 868, y: 392, len: 21, ang: 0.45, col: "#d93829", hiCol: "#ff7363", curl: 1.2 },   // Vivid vermilion wool
    { x: 882, y: 404, len: 13, ang: -0.85, col: "#e04836", hiCol: "#ff8575", curl: 0.9 },  // Vermilion companion strand
    { x: 804, y: 462, len: 18, ang: 2.1, col: "#e0962f", hiCol: "#ffd27d", curl: 1.1 },    // Warm ochre-mustard fiber
    // Near the coin-sized chip & spin exit
    { x: 702, y: 738, len: 23, ang: -0.32, col: "#cf3527", hiCol: "#ff6b5b", curl: 1.35 }, // Crimson-vermilion fiber
    { x: 714, y: 746, len: 11, ang: 1.15, col: "#edd6b8", hiCol: "#ffffff", curl: 0.8 },   // Warm heather-cream wool
    { x: 528, y: 538, len: 19, ang: 0.78, col: "#d47a2a", hiCol: "#ffbe73", curl: 1.15 },  // Burnt orange / amber fiber
    { x: 358, y: 852, len: 16, ang: -1.4, col: "#d93829", hiCol: "#ff7363", curl: 1.0 }    // Vermilion fiber near check stop
  ];

  for (let fb of fibres) {
    let pts = [];
    let shadowPts = [];
    let highlightPts = [];
    let numSteps = 10;

    let curX = fb.x;
    let curY = fb.y;
    let curAng = fb.ang;
    let stepLen = fb.len / numSteps;

    for (let i = 0; i <= numSteps; i++) {
      let t = i / numSteps;
      let pr = 0.7 + 0.4 * Math.sin(t * Math.PI);
      pts.push([curX, curY, pr]);
      // Overhead fluorescent light casts a tight contact shadow 1.3px below the fiber
      shadowPts.push([curX + 0.9, curY + 1.4, pr]);
      if (i >= 2 && i <= 7) {
        highlightPts.push([curX - 0.3, curY - 0.4, pr * 0.8]);
      }
      // High-frequency wool crimp / kink
      curAng += Math.sin(i * 1.65) * 0.48 * fb.curl + random(-0.22, 0.22);
      curX += Math.cos(curAng) * stepLen;
      curY += Math.sin(curAng) * stepLen;
    }

    // 1. Microscopic contact shadow on the ice
    brush.set("rotring", "#030508", 0.32);
    brush.spline(shadowPts, 0.5);

    // 2. Main wool/acrylic fiber body
    brush.set("rotring", fb.col, 0.34);
    brush.spline(pts, 0.5);
    brush.set("cpencil", fb.col, 0.26);
    brush.spline(pts, 0.5);

    // 3. Upper bend highlight catching the overhead light
    if (highlightPts.length >= 3) {
      brush.set("rotring", fb.hiCol, 0.2);
      brush.spline(highlightPts, 0.5);
    }

    // 4. Tiny frayed micro-barb + clinging frost crystal at one end of the fiber
    let midP = pts[4];
    let barbAng = fb.ang + 1.1;
    brush.set("rotring", fb.col, 0.18);
    brush.line(midP[0], midP[1], midP[0] + Math.cos(barbAng) * 3.2, midP[1] + Math.sin(barbAng) * 3.2);

    let endP = pts[pts.length - 1];
    brush.set("rotring", "#ffffff", 0.26);
    brush.line(endP[0] - 0.8, endP[1], endP[0] + 1.2, endP[1] + 0.6);
  }
}

// ===========================================================================
// 10. FINAL FROST SPECULAR GLINTS & SURFACE MICRO-INCIDENTS
// ===========================================================================
function drawSurfaceFrostGlints() {
  // Sparse, pinpoint crystalline glints where loose ice shavings catch the overhead fluorescent tubes
  for (let i = 0; i < 240; i++) {
    let x = random(20, 1180);
    let y = random(20, 1180);
    let light = getFluorescentLight(x, y);

    if (random() < light * 0.85) {
      let len = random(0.8, 2.4);
      let ang = random(0, Math.PI * 2);
      let col = random() < 0.72 ? "#fff8ed" : (random() < 0.5 ? "#ffffff" : "#f5d7b0");
      brush.set("rotring", col, random(0.15, 0.28));
      brush.line(x, y, x + Math.cos(ang) * len, y + Math.sin(ang) * len);
    }
  }
}

