  });
}

function draw() {
  translate(-width / 2, -height / 2);
  background(PAPER_CREAM);

  // 1. Bare cream archival paper texture & subtle showroom card framing
  drawPaperGround();

  // Layout geometry
  const stackX = 204;
  const stackW = 556;
  const marginX = 772; // 12px razor-straight cream paper gap between stack and white margin
  const marginW = 264;
  const startY = 84;
  const towelH = 119;
  const gapH = 12; // 12px razor-straight tape-masked bare cream paper between towels
  const totalH = SWATCHES.length * towelH + (SWATCHES.length - 1) * gapH;

  // 2. White margin to the right (opaque white card panel with razor-straight edges)
  drawWhiteMarginPanel(marginX, startY, marginW, totalH, towelH, gapH);

  // 3. Faint graphite tape-alignment registration ticks in the outer cream paper
  drawRegistrationMarks(stackX, stackW, marginX, marginW, startY, towelH, gapH, totalH);

  // 4. Render each of the 8 folded terry towels inside its razor-sharp tape mask
  for (let i = 0; i < SWATCHES.length; i++) {
    const y1 = startY + i * (towelH + gapH);
    drawTowelSwatch(i, stackX, y1, stackW, towelH, SWATCHES[i]);
  }

  // 5. Render marker-printed colour names, code numbers & clinical specs in the right margin
  for (let i = 0; i < SWATCHES.length; i++) {
    const y1 = startY + i * (towelH + gapH);
    drawMarginLabel(i, marginX, y1, marginW, towelH, SWATCHES[i]);
  }

  noLoop();
}

// ---------------------------------------------------------------------------
// 1. BARE CREAM PAPER GROUND
// ---------------------------------------------------------------------------
function drawPaperGround() {
  brush.noField();
  brush.noStroke();

  // Subtle warm paper tone variation
  brush.fill(PAPER_GRAIN_DARK, 18);
  brush.fillBleed(0.35, "in");
  brush.fillTexture(0.55, 0.1);
  brush.rect(40, 40, 1120, 1120, "corner");
  brush.noFill();

  // Fine cotton rag paper fibers
  brush.set("2H", PAPER_GRAIN_DARK, 0.22);
  for (let i = 0; i < 420; i++) {
    const px = random(30, 1170);
    const py = random(30, 1170);
    const len = random(6, 22);
    const ang = random(-15, 15);
    brush.line(px, py, px + cos(ang) * len, py + sin(ang) * len);
  }

  brush.set("2H", PAPER_GRAIN_LIGHT, 0.24);
  for (let i = 0; i < 280; i++) {
    const px = random(30, 1170);
    const py = random(30, 1170);
    const len = random(5, 16);
    const ang = random(75, 105);
    brush.line(px, py, px + cos(ang) * len, py + sin(ang) * len);
  }
}

// ---------------------------------------------------------------------------
// 2. WHITE RIGHT-HAND MARGIN PANEL
// ---------------------------------------------------------------------------
function drawWhiteMarginPanel(mx, sy, mw, totalH, towelH, gapH) {
  // Each towel row has a razor-sharp white margin block separated by the same 12px bare cream tape strip,
  // plus a continuous right-side white strip unifying the margin column.
  brush.clip([mx, sy, mx + mw, sy + totalH]);

  brush.noStroke();
  brush.wash(MARGIN_WHITE, 250);
  brush.rect(mx, sy, mw, totalH, "corner");
  brush.noWash();

  // Subtle matte white gouache pass for showroom card density
  brush.set("gouacheFlat", "#ffffff", 2.2);
  for (let y = sy + 8; y < sy + totalH; y += 18) {
    brush.line(mx + 4, y, mx + mw - 4, y);
  }

  // Faint clinical horizontal dividers aligned with the 12px tape gaps
  for (let i = 0; i < SWATCHES.length - 1; i++) {
    const gapY = sy + (i + 1) * towelH + i * gapH;
    brush.noStroke();
    brush.wash(PAPER_CREAM, 255);
    brush.rect(mx, gapY, 18, gapH, "corner");
    brush.noWash();

    // Hairline rule across the white margin aligned with the center of the tape gap
    brush.set("2H", "#dbd5c6", 0.24);
    brush.line(mx + 22, gapY + gapH * 0.5, mx + mw - 16, gapY + gapH * 0.5);
  }

  // Crisp left edge rule of the white margin
  brush.set("2H", "#ded8c8", 0.25);
  brush.line(mx + 0.5, sy, mx + 0.5, sy + totalH);
  brush.line(mx + mw - 0.5, sy, mx + mw - 0.5, sy + totalH);

  brush.noClip();
}

// ---------------------------------------------------------------------------
// 3. CLINICAL REGISTRATION MARKS & HEADER/FOOTER
// ---------------------------------------------------------------------------
function drawRegistrationMarks(sx, sw, mx, mw, sy, towelH, gapH, totalH) {
  // Subtle graphite crop/masking ticks where drafting tape was aligned
  brush.set("2H", GRAPHITE_FAINT, 0.22);

  // Vertical alignment ticks at top and bottom of stack and margin
  const xTicks = [sx, sx + sw, mx, mx + mw];
  for (const x of xTicks) {
    brush.line(x, sy - 18, x, sy - 5);
    brush.line(x, sy + totalH + 5, x, sy + totalH + 18);
  }

  // Horizontal tape-edge ticks on the left of the stack
  for (let i = 0; i < SWATCHES.length; i++) {
    const yTop = sy + i * (towelH + gapH);
    const yBot = yTop + towelH;
    brush.line(sx - 16, yTop, sx - 5, yTop);
    brush.line(sx - 16, yBot, sx - 5, yBot);
  }

  // Small header & footer notations
  drawMarkerText("TERRY PILE STANDARD // CELADON TO BOTTLE", sx, sy - 27, 6.5, "rotring", INK_MUTED, 0.24, 2.2);
  drawMarkerText("SWATCH INDEX", mx + 22, sy - 27, 6.5, "rotring", INK_MUTED, 0.24, 2.2);

  // Bottom millimeter scale bar
  const footY = sy + totalH + 28;
  brush.set("rotring", INK_MUTED, 0.25);
  brush.line(sx, footY, sx + 120, footY);
  for (let m = 0; m <= 120; m += 24) {
    brush.line(sx + m, footY - 4, sx + m, footY + 3);
  }
  drawMarkerText("0      25     50 MM", sx + 132, footY - 3.5, 5.8, "rotring", INK_MUTED, 0.22, 1.8);
  drawMarkerText("LIGHT: D65 FLAT SHOWROOM", mx + 22, footY - 3.5, 5.8, "rotring", INK_MUTED, 0.22, 1.8);

  // Single tiny red archival registration crosshair at footer right
  const cx = mx + mw - 18;
  const cy = footY - 1;
  brush.set("rotring", ACCENT_RED, 0.3);
  brush.line(cx - 5, cy, cx + 5, cy);
  brush.line(cx, cy - 5, cx, cy + 5);
  brush.circle(cx, cy, 2.8, 0.05);
}

// ---------------------------------------------------------------------------
// 4. HYPERREAL FOLDED TERRY TOWEL SWATCH
// ---------------------------------------------------------------------------
function drawTowelSwatch(idx, x1, y1, w, h, sw) {
  const x2 = x1 + w;
  const y2 = y1 + h;

  // Enforce razor-straight tape-masked edges via brush.clip
  brush.clip([x1, y1, x2, y2]);

  // Fold anatomy for this towel:
  // Each towel is folded in half horizontally with a plush U-bend on the left
  // and a central horizontal fold crease running to the right edge.
  const turnX = x1 + 44 + ((idx * 5) % 9 - 4);
  const baseCreaseRatio = 0.53 + ((idx % 2 === 0 ? 1 : -1) * 0.016);
  const baseCreaseY = y1 + h * baseCreaseRatio;
  const phase = idx * 1.9 + 0.4;

  const getCreaseY = (x) => {
    const t = constrain((x - turnX) / (w - 44), 0, 1);
    return (
      baseCreaseY +
      sin(t * 240 + phase * 40) * 1.6 +
      cos(t * 520 + idx * 70) * 0.7
    );
  };

  // Woven dobby border band across the upper ply
  const dobbyH = 14.5;
  const getDobbyTop = (x) => {
    const foldDrop = x < turnX + 20 ? pow(map(x, x1, turnX + 20, 1, 0, true), 2) * 5.5 : 0;
    return y1 + 17.5 + sin((x - x1) * 0.45 + idx * 35) * 0.65 + foldDrop;
  };

  // --- STEP A: Opaque Watercolour / Gouache Underpainting ---
  brush.noStroke();
  brush.wash(sw.base, 255);
  brush.rect(x1, y1, w, h, "corner");
  brush.noWash();

  // Layered watercolour washes pushed to opaque gouache density
  // 1. Upper ply crown highlight (flat showroom light hitting top-facing curve)
  brush.fill(sw.light, 155);
  brush.fillBleed(0.03, "in");
  brush.fillTexture(0.45, 0.18);
  brush.rect(x1 + 2, y1 + 1, w - 4, 15, "corner");
  brush.rect(x1 + 18, y1 + 33, w - 20, 16, "corner");

  // 2. Lower ply upper bulge highlight (just below the central fold crease)
  brush.rect(turnX - 6, baseCreaseY + 7, w - (turnX - x1) + 4, 21, "corner");
  brush.noFill();

  // 3. Recessed dobby border undertone & fold trough shading
  brush.fill(sw.midDark, 165);
  brush.fillBleed(0.03, "in");
  brush.fillTexture(0.5, 0.22);
  brush.rect(x1 + 2, y1 + 17, w - 4, dobbyH + 1, "corner");
  brush.rect(turnX - 8, baseCreaseY - 9, w - (turnX - x1) + 6, 15, "corner");
  brush.rect(x1 + 2, y2 - 11, w - 4, 10, "corner");
  brush.noFill();

  // 4. Dense matte gouache body strokes across the plies
  brush.set("gouacheFlat", sw.base, 1.8);
  for (let py = y1 + 6; py < y2 - 4; py += 9) {
    if (abs(py - baseCreaseY) > 6 && (py < y1 + 17 || py > y1 + 32)) {
      brush.line(x1 + 4, py, x2 - 4, py + random(-0.6, 0.6));
    }
  }

  brush.set("gouacheFlat", sw.light, 1.35);
  brush.line(x1 + 10, y1 + 8, x2 - 10, y1 + 8);
  brush.line(turnX + 8, y1 + 40, x2 - 8, y1 + 40);
  brush.line(turnX + 8, baseCreaseY + 15, x2 - 8, baseCreaseY + 15);
  brush.line(turnX + 12, baseCreaseY + 24, x2 - 12, baseCreaseY + 24);

  brush.set("gouacheFlat", sw.midDark, 1.4);
  brush.line(turnX - 4, baseCreaseY - 4, x2 - 4, baseCreaseY - 4);
  brush.line(turnX - 4, baseCreaseY + 3, x2 - 4, baseCreaseY + 3);
  brush.line(x1 + 4, y2 - 5, x2 - 4, y2 - 5);

  // Left U-bend volumetric shading (plush folded turn on the left side)
  brush.set("gouacheFlat", sw.light, 1.3);
  brush.arc(turnX + 4, baseCreaseY, 32, 115, 245);
  brush.set("gouacheFlat", sw.midDark, 1.1);
  brush.arc(turnX + 2, baseCreaseY, 16, 100, 260);

  // --- STEP B: Woven Cotton Dobby Border (Cam Border) ---
  drawDobbyBorder(idx, x1, x2, turnX, getDobbyTop, dobbyH, sw);

  // --- STEP C: Central Fold Crease & Pinched Keyhole Tuck ---
  drawFoldCrease(idx, x1, x2, turnX, baseCreaseY, getCreaseY, sw);

  // --- STEP D: Looped Terry Pile Texture in Tiny Pencil Curls ---
  drawTerryPileCurls(idx, x1, y1, x2, y2, turnX, getCreaseY, getDobbyTop, dobbyH, sw);

  // --- STEP E: Razor-Straight Tape-Masked Edge Capillary Micro-Bead ---
  brush.set("2H", sw.midDark, 0.28);
  brush.line(x1 + 0.6, y1 + 0.6, x2 - 0.6, y1 + 0.6);
  brush.line(x1 + 0.6, y2 - 0.6, x2 - 0.6, y2 - 0.6);
  brush.line(x1 + 0.6, y1 + 0.6, x1 + 0.6, y2 - 0.6);
  brush.line(x2 - 0.6, y1 + 0.6, x2 - 0.6, y2 - 0.6);

  brush.noClip();
}

// ---------------------------------------------------------------------------
// WOVEN DOBBY BORDER (RIBBED CAM BAND)
// ---------------------------------------------------------------------------
function drawDobbyBorder(idx, x1, x2, turnX, getDobbyTop, dobbyH, sw) {
  const stepX = 16;

  // 1. Satin-weave horizontal cordons at top and bottom of the dobby band
  const topPts = [];
  const midPts = [];
  const botPts = [];
  const shadowTopPts = [];
  const shadowBotPts = [];

  for (let x = x1 - 4; x <= x2 + 4; x += stepX) {
    const dt = getDobbyTop(x);
    shadowTopPts.push([x, dt - 0.8]);
    topPts.push([x, dt + 2.2]);
    midPts.push([x, dt + dobbyH * 0.5]);
    botPts.push([x, dt + dobbyH - 2.2]);
    shadowBotPts.push([x, dt + dobbyH + 0.8]);
  }

  // Micro-crevice where plush terry pile meets the flat woven dobby border
  brush.set("2B", sw.deep, 0.38);
  brush.spline(shadowTopPts, 0.3);
  brush.spline(shadowBotPts, 0.3);

  // Luminous horizontal satin border bars
  brush.set("cpencil", sw.dobbySheen, 0.55);
  brush.spline(topPts, 0.3);
  brush.spline(botPts, 0.3);

  brush.set("2H", sw.curlLight, 0.32);
  brush.spline(midPts, 0.3);

  // 2. Tight vertical cotton warp ribs across the dobby band (batched by color)
  brush.set("2H", sw.deep, 0.28);
  for (let x = x1 + 2; x < x2 - 1; x += 2.6) {
    const dt = getDobbyTop(x);
    // Slight angle follow near the left fold turn
    const tilt = x < turnX ? map(x, x1, turnX, -1.8, 0) : 0;
    brush.line(x + tilt, dt + 2.6, x - tilt * 0.5, dt + dobbyH - 2.6);
  }

  brush.set("2H", sw.curlLight, 0.3);
  for (let x = x1 + 3.3; x < x2 - 1; x += 2.6) {
    const dt = getDobbyTop(x);
    const tilt = x < turnX ? map(x, x1, turnX, -1.8, 0) : 0;
    // Twill herringbone break in the middle of the rib
    brush.line(x + tilt, dt + 2.8, x + 0.4, dt + dobbyH * 0.48);
    brush.line(x - 0.3, dt + dobbyH * 0.54, x - tilt * 0.5, dt + dobbyH - 2.8);
  }

  // 3. Benchmark Swatch 06: tiny woven vermilion-red selvedge control stitch
  if (sw.accent) {
    const stitchX1 = x2 - 19;
    const stitchX2 = x2 - 4;
    const dt = getDobbyTop(stitchX1);
    brush.set("cpencil", ACCENT_RED, 0.48);
    for (let sx = stitchX1; sx <= stitchX2; sx += 1.8) {
      brush.line(sx, dt + 3.0, sx, dt + dobbyH - 3.0);
    }
    brush.set("rotring", ACCENT_RED, 0.28);
    brush.line(stitchX1, dt + dobbyH * 0.5, stitchX2, dt + dobbyH * 0.5);
  }
}

// ---------------------------------------------------------------------------
// CENTRAL FOLD CREASE & LEFT KEYHOLE FOLD TURN
// ---------------------------------------------------------------------------
function drawFoldCrease(idx, x1, x2, turnX, baseCreaseY, getCreaseY, sw) {
  const creasePts = [];
  const upperLipPts = [];
  const lowerLipPts = [];

  for (let x = turnX - 2; x <= x2 + 4; x += 14) {
    const cy = getCreaseY(x);
    creasePts.push([x, cy + random(-0.35, 0.35)]);
    upperLipPts.push([x, cy - 2.4]);
    lowerLipPts.push([x, cy + 2.6]);
  }

  // Soft transition shadow into the fold
  brush.set("charcoal", sw.midDark, 0.55);
  brush.spline(upperLipPts, 0.4);
  brush.spline(lowerLipPts, 0.4);

  // Deep core crease where upper and lower plies press together
  brush.set("2B", sw.deep, 0.52);
  brush.spline(creasePts, 0.45);

  // Second crisp graphite/coloured-pencil pass inside the fold trough
  brush.set("cpencil", sw.deep, 0.38);
  for (let x = turnX + 2; x < x2 - 4; x += 11) {
    const cy = getCreaseY(x);
    brush.line(x, cy - 0.6, x + random(5, 9), cy + random(-0.8, 0.8));
  }

  // Pinched keyhole pocket at (turnX, baseCreaseY) where the fold bends 180 deg
  brush.set("2B", sw.deep, 0.46);
  brush.arc(turnX, baseCreaseY, 5.5, 115, 250);
  brush.line(turnX - 4, baseCreaseY - 1.5, turnX + 5, baseCreaseY);
  brush.line(turnX - 3, baseCreaseY + 2.0, turnX + 5, baseCreaseY + 0.5);

  // Subtle compression lines radiating into the left U-fold
  brush.set("cpencil", sw.midDark, 0.36);
  for (let a = 135; a <= 225; a += 18) {
    const r1 = 6;
    const r2 = 22 + random(-3, 4);
    brush.line(
      turnX + cos(a) * r1,
      baseCreaseY + sin(a) * r1 * 0.75,
      turnX + cos(a) * r2,
      baseCreaseY + sin(a) * r2 * 0.85
    );
  }
}

// ---------------------------------------------------------------------------
// LOOPED PILE TEXTURE PICKED OUT IN TINY PENCIL CURLS
// ---------------------------------------------------------------------------
function drawTerryPileCurls(idx, x1, y1, x2, y2, turnX, getCreaseY, getDobbyTop, dobbyH, sw) {
  // Generate all terry loop descriptors for this towel so we can batch by pencil color
  const loops = [];
  const rowStep = 4.6;
  const colStep = 5.4;

  for (let baseY = y1 + 3.0; baseY <= y2 - 2.2; baseY += rowStep) {
    const rowIdx = floor((baseY - y1) / rowStep);
    const xStagger = (rowIdx % 2) * (colStep * 0.5);

    for (let baseX = x1 + 2.5 + xStagger; baseX <= x2 - 2.0; baseX += colStep) {
      const lx = baseX + random(-1.35, 1.35);
      const ly = baseY + random(-1.1, 1.1);

      const dt = getDobbyTop(lx);
      const db = dt + dobbyH;

      // Skip inside the woven dobby border (except tiny fringe loops right on its edge)
      if (ly > dt + 1.0 && ly < db - 1.0) continue;

      const cy = getCreaseY(lx);
      const distToCrease = abs(ly - cy);

      // Foreshortening: loops flatten slightly as they roll into the central crease or top/bottom edges
      let squash = 1.0;
      if (lx > turnX - 6 && distToCrease < 11) {
        squash = map(distToCrease, 0, 11, 0.52, 1.0);
      } else if (ly - y1 < 7) {
        squash = map(ly - y1, 0, 7, 0.65, 1.0);
      } else if (y2 - ly < 7) {
        squash = map(y2 - ly, 0, 7, 0.65, 1.0);
      }

      // Determine local illumination zone (crown vs mid vs crease trough)
      let zone = 1; // 0 = shadow trough, 1 = mid body, 2 = bright crown
      if (lx > turnX - 4 && distToCrease < 6.5) {
        zone = 0;
      } else if (y2 - ly < 6.5) {
        zone = 0;
      } else if (
        (ly > y1 + 3 && ly < dt - 1.5) ||
        (ly > db + 2 && ly < cy - 11) ||
        (ly > cy + 8 && ly < cy + 31) ||
        (lx < turnX - 6 && dist(lx, ly, turnX, cy) < 28)
      ) {
        zone = 2;
      }

      const r = random(1.85, 3.1) * (0.82 + squash * 0.22);
      const tilt = random(-28, 28) + (lx < turnX ? map(ly, y1, y2, -25, 25) : 0);
      const isEdgeFringe = abs(ly - dt) < 2.4 || abs(ly - db) < 2.4 || distToCrease < 4.2;

      loops.push({
        x: lx,
        y: ly,
        r,
        squash,
        tilt,
        zone,
        isEdgeFringe,
        hookDir: random() < 0.5 ? 1 : -1
      });
    }
  }

  // PASS 1: Deep interstitial loop-shadow curls & root ticks (2B in sw.deep)
  brush.set("2B", sw.deep, 0.28);
  for (let i = 0; i < loops.length; i++) {
    const L = loops[i];
    if (L.zone === 0 || i % 2 === 0 || L.isEdgeFringe) {
      // Underside shadow curl where the cotton loop emerges from the backing weave
      brush.arc(
        L.x + 0.35,
        L.y + 0.85 * L.squash,
        L.r * 0.92,
        20 + L.tilt,
        165 + L.tilt
      );
    } else {
      // Quick root crevice tick for the remaining loops
      brush.line(
        L.x - L.r * 0.7,
        L.y + 1.1,
        L.x + L.r * 0.7,
        L.y + 1.3
      );
    }
  }

  // PASS 2: Mid-dark loop side curls & twist shading (cpencil in sw.midDark)
  brush.set("cpencil", sw.midDark, 0.33);
  for (let i = 0; i < loops.length; i++) {
    const L = loops[i];
    if (L.zone <= 1 || i % 2 === 1) {
      const startA = L.hookDir > 0 ? 110 + L.tilt : 310 + L.tilt;
      const endA = startA + 150;
      brush.arc(L.x, L.y + 0.3, L.r, startA, endA);
    }
  }

  // PASS 3: Primary body loops in sw.curlMid (gives dense gouache-pencil cohesion)
  brush.set("cpencil", sw.curlMid, 0.34);
  for (let i = 0; i < loops.length; i += 2) {
    const L = loops[i];
    brush.arc(L.x - 0.2, L.y, L.r * 0.95, 165 + L.tilt, 355 + L.tilt);
  }

  // PASS 4: Luminous upper loop curls catching the flat showroom light (cpencil in sw.light)
  brush.set("cpencil", sw.light, 0.36);
  for (let i = 0; i < loops.length; i++) {
    const L = loops[i];
    if (L.zone >= 1) {
      // Classic terrycloth omega / U-curl loop crest
      brush.arc(
        L.x - 0.15,
        L.y - 0.45 * L.squash,
        L.r,
        185 + L.tilt,
        365 + L.tilt
      );
      // Tiny hooked leg of the twisted cotton loop
      if (i % 3 === 0) {
        const ang = (L.hookDir > 0 ? 355 : 190) + L.tilt;
        const hx = L.x + cos(ang) * L.r;
        const hy = L.y - 0.45 * L.squash + sin(ang) * L.r;
        brush.line(hx, hy, hx - L.hookDir * 1.1, hy + 1.5 * L.squash);
      }
    }
  }

  // PASS 5: Brightest crisp pencil highlight curls on the top-most loop crests (HB in sw.curlLight)
  brush.set("HB", sw.curlLight, 0.29);
  for (let i = 0; i < loops.length; i++) {
    const L = loops[i];
    if (L.zone === 2 && (i % 2 === 0 || L.isEdgeFringe)) {
      brush.arc(
        L.x - 0.25,
        L.y - 0.75 * L.squash,
        L.r * 0.88,
        205 + L.tilt,
        345 + L.tilt
      );
    } else if (L.zone === 1 && i % 4 === 0) {
      brush.arc(
        L.x - 0.2,
        L.y - 0.6 * L.squash,
        L.r * 0.8,
        215 + L.tilt,
        330 + L.tilt
      );
    }
  }
}

// ---------------------------------------------------------------------------
// 5. MARKER-PRINTED COLOUR NAMES & CODE NUMBERS IN THE WHITE MARGIN
// ---------------------------------------------------------------------------
function drawMarginLabel(idx, mx, y1, mw, h, sw) {
  const padX = mx + 24;
  const topCodeY = y1 + 26;
  const nameY = y1 + 52;
  const specY = y1 + 83;

  // Small technical index tick on left of label cell
  brush.set("rotring", INK_MUTED, 0.25);
  brush.line(mx + 6, y1 + h * 0.5, mx + 15, y1 + h * 0.5);

  // 1. Code number (e.g. "01 / CEL-104")
  drawMarkerText(sw.code, padX, topCodeY, 8.2, "rotring", INK_MUTED, 0.3, 2.4);

  // 2. Marker-printed Colour Name (bold, tactile felt-tip marker lettering)
  drawMarkerText(sw.name, padX, nameY, 12.2, "swatchMarker", INK_DARK, 0.58, 3.2);
  // Second crisp pass for authentic dense marker ink look
  drawMarkerText(sw.name, padX + 0.25, nameY + 0.15, 12.2, "rotring", INK_DARK, 0.28, 3.2);

  // 3. Clinical textile & reflectance specification line
  drawMarkerText(sw.spec, padX, specY, 6.6, "rotring", INK_MUTED, 0.23, 1.9);

  // 4. Tiny colour-matched painted calibration chip in the far right of the white margin
  const chipX = mx + mw - 30;
  const chipY = y1 + 26;
  brush.noStroke();
  brush.wash(sw.base, 250);
  brush.rect(chipX, chipY, 12, 12, "corner");
  brush.noWash();
  brush.set("2H", sw.deep, 0.22);
  brush.rect(chipX, chipY, 12, 12, "corner");

  // 5. Single Archival Vermilion Accent on Benchmark Swatch 06 ("GLASSWORKS")
  if (sw.accent) {
    const dotX = mx + mw - 24;
    const dotY = nameY + 6;

    brush.noStroke();
    brush.wash(ACCENT_RED, 245);
    brush.circle(dotX, dotY, 4.2, 0.05);
    brush.noWash();

    brush.set("rotring", ACCENT_RED, 0.3);
    brush.circle(dotX, dotY, 6.8, 0.06);
    drawMarkerText("STD", dotX - 9, dotY + 12, 5.8, "rotring", ACCENT_RED, 0.26, 1.6);
  }
}

// ---------------------------------------------------------------------------
// STROKE-FONT RENDERER FOR MARKER & TECHNICAL PEN TYPOGRAPHY
// ---------------------------------------------------------------------------
function drawMarkerText(textStr, startX, startY, charH, brushName, col, weight, tracking) {
  brush.set(brushName, col, weight);
  const charW = charH * 0.64;
  let cursorX = startX;

  const upper = textStr.toUpperCase();
  for (let i = 0; i < upper.length; i++) {
    const ch = upper[i];
    if (ch === " ") {
      cursorX += charW * 0.75 + tracking;
      continue;
    }

    const strokes = GLYPHS[ch];
    if (strokes) {
      for (let s = 0; s < strokes.length; s++) {
        const seg = strokes[s];
        const x1 = cursorX + seg[0] * charW + random(-0.12, 0.12);
        const y1 = startY + seg[1] * charH + random(-0.12, 0.12);
        const x2 = cursorX + seg[2] * charW + random(-0.12, 0.12);
        const y2 = startY + seg[3] * charH + random(-0.12, 0.12);
        brush.line(x1, y1, x2, y2);
      }
    }
    cursorX += charW + tracking;
  }
}

