const HAND_CREASES = [
  // Thenar "life line" crease curving around thumb pad
  [532, 524, 592, 565, 11, 0.65],
  [592, 565, 616, 636, 12, 0.60],
  // Distal & proximal transverse palmar creases ("heart" & "head" lines)
  [540, 518, 645, 534, 10, 0.58],
  [585, 504, 722, 532, 10, 0.62],
  // Finger interphalangeal joint creases
  [514, 418, 542, 414, 7, 0.72],
  [500, 362, 526, 358, 7, 0.72],
  [589, 401, 617, 400, 7, 0.72],
  [586, 340, 612, 339, 7, 0.72],
  [668, 416, 696, 420, 7, 0.72],
  [680, 360, 706, 364, 7, 0.72],
  [736, 456, 762, 462, 6.5, 0.70],
  [756, 410, 782, 416, 6.5, 0.70],
  // Thumb IP crease
  [428, 568, 444, 544, 7.5, 0.68]
];

const TACK_X = 276;
const TACK_Y = 818;
const TACK_R = 26;

// Helper: distance & parameter along a tapered capsule
function capsuleEval(px, py, x1, y1, r1, x2, y2, r2) {
  let dx = x2 - x1;
  let dy = y2 - y1;
  let len2 = dx * dx + dy * dy;
  let t = len2 > 0 ? ((px - x1) * dx + (py - y1) * dy) / len2 : 0;
  t = Math.max(0, Math.min(1, t));
  let cx = x1 + t * dx;
  let cy = y1 + t * dy;
  let r = r1 + t * (r2 - r1);
  let dist = Math.hypot(px - cx, py - cy);
  return { dist, r, t, cx, cy };
}

// Evaluate the palm print field at (x, y)
function evalPalmPrint(x, y) {
  // Quick bounding box check for speed
  if (x < 330 || x > 840 || y < 245 || y > 745) {
    return { weight: 0, edgeRidge: 0, troughRim: 0, angle: 0 };
  }

  let n1 = noise(x * 0.018, y * 0.018);
  let n2 = noise(x * 0.065 + 77, y * 0.065 + 31);
  let warpX = x + (n1 - 0.5) * 14 + (n2 - 0.5) * 4;
  let warpY = y + (n1 - 0.5) * 14 + (n2 - 0.5) * 4;

  // Smooth max (blobby union) across all anatomical capsules
  let sumExp = 0;
  let weightedAngle = 0;
  let totalW = 0;
  let minNormDist = 999;
  let pushBias = 0;

  for (let i = 0; i < HAND_CAPSULES.length; i++) {
    let c = HAND_CAPSULES[i];
    let ev = capsuleEval(warpX, warpY, c[0], c[1], c[2], c[3], c[4], c[5]);
    let normD = ev.dist / ev.r;
    if (normD < minNormDist) minNormDist = normD;

    if (normD < 1.65) {
      // Soft exponential kernel for organic blending between fingers & palm pads
      let k = Math.exp(-Math.pow(normD * 1.42, 3.2)) * c[6];
      sumExp += k;
      weightedAngle += c[7] * k;
      totalW += k;

      // Upper-left push rim detection (where fingers/palm push into upright pile)
      let dirX = (warpX - ev.cx) / (ev.r + 0.001);
      let dirY = (warpY - ev.cy) / (ev.r + 0.001);
      let pushDot = -(dirX * 0.62 + dirY * 0.78);
      if (normD > 0.72 && normD < 1.22) {
        pushBias = Math.max(pushBias, pushDot * Math.exp(-Math.pow((normD - 0.96) * 5.5, 2)));
      }
    }
  }

  let rawWeight = Math.min(1.0, sumExp * 0.92);
  if (rawWeight < 0.01 && minNormDist > 1.35) {
    return { weight: 0, edgeRidge: 0, troughRim: 0, angle: 0 };
  }

  // Subtract palmar flexion creases and knuckle joint lines
  let creaseCut = 0;
  for (let i = 0; i < HAND_CREASES.length; i++) {
    let cr = HAND_CREASES[i];
    let ev = capsuleEval(warpX, warpY, cr[0], cr[1], cr[4], cr[2], cr[3], cr[4]);
    if (ev.dist < cr[4]) {
      let cw = (1 - ev.dist / cr[4]);
      creaseCut = Math.max(creaseCut, cw * cw * cr[5]);
    }
  }

  // Fine skin-ridge / drag striation texture inside the print
  let dragWave = sin((x * 0.45 - y * 0.75) * 4.5 + n1 * 90) * 0.07;
  let weight = Math.max(0, Math.min(1, rawWeight * (1 - creaseCut * 0.78) + (rawWeight > 0.25 ? dragWave : 0)));

  // Compression trough just outside the upper-left push boundary, and bright ridge inside it
  let troughRim = Math.max(0, pushBias);
  let edgeRidge = 0;
  if (minNormDist > 0.78 && minNormDist < 1.12) {
    edgeRidge = Math.exp(-Math.pow((minNormDist - 0.92) * 7.0, 2));
  }

  let baseAngle = totalW > 0 ? weightedAngle / totalW : -118;
  return {
    weight,
    edgeRidge,
    troughRim,
    angle: baseAngle + (n2 - 0.5) * 18
  };
}

// Complete 3D surface and optical model of the rolled velvet armchair arm
function getSurfaceData(x, y) {
  // 1. Spine of the rolled bolster (sweeping upper-left to lower-right)
  let xNorm = x / 1200;
  let spineY = 305 + 0.31 * x - 48 * Math.sin(xNorm * Math.PI);
  let spineSlope = 0.31 - (48 * Math.PI / 1200) * Math.cos(xNorm * Math.PI);
  let spineAngle = Math.atan2(spineSlope, 1) * (180 / Math.PI);

  // Perpendicular signed distance from bolster crest (negative = toward top-right back edge, positive = toward lower-left crease)
  let cosA = Math.cos(spineAngle * Math.PI / 180);
  let sinA = Math.sin(spineAngle * Math.PI / 180);
  let d = (y - spineY) * cosA;

  // Upper silhouette edge of the rolled arm against dark background room
  let topEdgeD = -268 - 22 * Math.sin(xNorm * Math.PI * 1.4) + 6 * (noise(x * 0.01, y * 0.01) - 0.5);
  let distToTopEdge = d - topEdgeD;
  if (distToTopEdge < 0) {
    return {
      insideArm: false,
      distToTopEdge,
      nx: 0, ny: 0, nz: 1,
      velvetLum: 0.02,
      chartreuseGlow: 0,
      troughWeight: 1.0,
      palmWeight: 0,
      palmEdgeRidge: 0,
      pileAngle: spineAngle
    };
  }

  // Lower main tuck crease where the rolled bolster meets the gathered lower scroll
  let creaseD = 365 + 42 * Math.sin((x - 150) * 0.0032);

  // Compute 3D surface normal (nx, ny, nz) of the bolster & lower scroll panel
  let nx = 0, ny = 0, nz = 1;
  let troughWeight = 0;

  if (d <= creaseD) {
    // On the main rolled bolster cylinder
    let cylNorm = (d - 30) / 335; // -0.9 to +1.0 across the bolster
    let clampedCyl = Math.max(-0.96, Math.min(0.97, cylNorm));
    let nPerp = clampedCyl;
    // Rotate perpendicular normal component by spine orientation
    nx = -nPerp * sinA - 0.14 * (1 - Math.abs(clampedCyl));
    ny = nPerp * cosA;
    nz = Math.sqrt(Math.max(0.04, 1 - nx * nx - ny * ny));

    // Deepening into the lower tuck crease
    if (d > creaseD - 95) {
      let t = (d - (creaseD - 95)) / 95;
      troughWeight = Math.max(troughWeight, Math.pow(t, 1.6));
    }
    // Slight shadow turn near the very back edge
    if (distToTopEdge < 42) {
      let tBack = 1 - distToTopEdge / 42;
      troughWeight = Math.max(troughWeight, tBack * 0.38);
    }
  } else {
    // Below the main crease: gathered lower scroll / front face of arm
    let subD = d - creaseD;
    let tCrease = Math.exp(-subD / 52);
    troughWeight = Math.max(troughWeight, tCrease * 0.95);
    let swell = Math.min(0.75, (subD - 45) / 260);
    nx = -0.25 - 0.18 * swell;
    ny = -0.55 * tCrease + 0.35 * (1 - tCrease);
    nz = Math.sqrt(Math.max(0.08, 1 - nx * nx - ny * ny));
  }

  // 2. Gathered pleats and deep dimple radiating from the Brass Upholstery Tack (276, 818)
  let dxTack = x - TACK_X;
  let dyTack = y - TACK_Y;
  let distTack = Math.hypot(dxTack, dyTack);
  let angTack = Math.atan2(dyTack, dxTack);

  if (distTack < 360) {
    let dimple = Math.exp(-distTack / 58);
    troughWeight = Math.max(troughWeight, dimple * 0.98);
    if (distTack > 8) {
      nx -= (dxTack / distTack) * dimple * 0.65;
      ny -= (dyTack / distTack) * dimple * 0.65;
    }

    // Three tension pleats radiating from the tack into the velvet bolster
    let pleatAngles = [-0.62, -1.28, 0.22];
    let pleatLengths = [340, 270, 230];
    for (let p = 0; p < 3; p++) {
      let da = Math.atan2(Math.sin(angTack - pleatAngles[p]), Math.cos(angTack - pleatAngles[p]));
      let radialFade = Math.exp(-distTack / pleatLengths[p]) * Math.min(1, distTack / 26);
      let pleatProfile = Math.exp(-Math.pow(da / 0.16, 2));
      let pleatDepth = pleatProfile * radialFade;
      troughWeight = Math.max(troughWeight, pleatDepth * 0.85);
      // Perturb surface normal across the pleat ridge & valley
      let sideDeriv = -(da / 0.08) * pleatDepth;
      nx += -Math.sin(angTack) * sideDeriv * 0.32;
      ny += Math.cos(angTack) * sideDeriv * 0.32;
    }
  }

  // Normalize (nx, ny, nz)
  let nLen = Math.hypot(nx, ny, nz) || 1;
  nx /= nLen; ny /= nLen; nz /= nLen;

  // 3. Evaluate Palm Print indentation and fibre bending
  let palm = evalPalmPrint(x, y);
  if (palm.troughRim > 0.01) {
    troughWeight = Math.min(1, troughWeight + palm.troughRim * 0.52);
    nx -= 0.25 * palm.troughRim;
    ny -= 0.25 * palm.troughRim;
    let nl = Math.hypot(nx, ny, nz) || 1;
    nx /= nl; ny /= nl; nz /= nl;
  }

  // 4. Velvet Anisotropic Lighting (Warm Lamplight from upper-left side)
  // Light vector L = normalize(-0.64, -0.48, 0.60)
  const lx = -0.64, ly = -0.48, lz = 0.60;
  let ndotl = Math.max(0, nx * lx + ny * ly + nz * lz);
  let ndotv = Math.max(0.05, nz);

  // Velvet retro-reflection / grazing rim sheen (the hallmark of real velvet)
  let grazing = Math.pow(1 - ndotv, 1.35);
  let ridgeSheen = Math.pow(ndotl, 0.85) * (0.35 + 1.45 * grazing);
  // Crown highlight band along the upper-left slope of the bolster
  let crownZone = Math.exp(-Math.pow((d + 78) / 115, 2)) * Math.exp(-Math.pow((x - 540) / 560, 2));
  let chartreuseGlow = Math.min(1.0, (ridgeSheen * 0.72 + crownZone * 0.58) * (1 - troughWeight * 0.85));

  // Overall velvet luminance (high contrast between near-black troughs and glowing crown)
  let baseVelvet = Math.pow(ndotl, 1.25) * (1 - troughWeight * 0.88);
  let velvetLum = Math.max(0.02, Math.min(1.0, baseVelvet * 0.75 + chartreuseGlow * 0.45));

  // 5. Local Velvet Pile Angle
  // Natural undisturbed nap flows along the curved arm with organic curl near pleats
  let flowCurl = (noise(x * 0.0045, y * 0.0045) - 0.5) * 26;
  let naturalAngle = spineAngle + 8 + flowCurl + (d / 380) * 18;
  if (distTack < 180) {
    let pull = Math.exp(-distTack / 75);
    let toTack = angTack * (180 / Math.PI) + 180;
    naturalAngle = naturalAngle * (1 - pull) + toTack * pull;
  }

  // Inside the palm print, fibres are bent the other way!
  let pw = palm.weight;
  let pileAngle = naturalAngle * (1 - pw) + palm.angle * pw;

  return {
    insideArm: true,
    distToTopEdge,
    d,
    creaseD,
    nx, ny, nz,
    velvetLum,
    chartreuseGlow,
    troughWeight,
    palmWeight: pw,
    palmEdgeRidge: palm.edgeRidge,
    palmTroughRim: palm.troughRim,
    pileAngle
  };
}

// Helper to draw a closed polygon with brush.beginShape / brush.vertex
function drawSmoothPoly(pts, curvature = 0.35) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(SEED);
  noiseSeed(SEED);

  // Add a custom multi-bristle velvet tuft brush for lush micro-pile texture
  brush.add("velvetTuft", {
    type: "custom",
    weight: 2.2,
    scatter: 0.45,
    opacity: 95,
    spacing: 0.35,
    pressure: [0.35, 1.15, 0.2],
    tip: (_m) => {
      _m.rect(-1.2, -0.25, 2.4, 0.5);
      _m.rect(-0.8, 0.45, 1.8, 0.35);
      _m.rect(-0.9, -0.8, 1.9, 0.35);
    },
    rotate: "natural",
    markerTip: false,
    noise: 0.7
  });

  // Register custom flowing vector field that follows the 3D bolster & reverses in the palm print
  brush.addField("velvetPileField", (t, field) => {
    let cols = field.length;
    let rows = field[0].length;
    for (let col = 0; col < cols; col++) {
      for (let row = 0; row < rows; row++) {
        let x = (col / (cols - 1)) * width;
        let y = (row / (rows - 1)) * height;
        let sd = getSurfaceData(x, y);
        field[col][row] = sd.pileAngle;
      }
    }
    return field;
  });
}

function draw() {
  translate(-width / 2, -height / 2);

  // Deepest forest-black ambient ground
  background("#030704");

  // =========================================================================
  // STAGE 1: UNDERPAINTING WASHES & WATERCOLOR FOUNDATION
  // =========================================================================
  brush.noStroke();

  // 1A. Deep forest body of the armchair arm
  brush.wash("#081409", 230);
  drawSmoothPoly([
    [-40, 20], [520, 95], [980, 260], [1240, 410],
    [1240, 1240], [-40, 1240]
  ], 0.25);
  brush.noWash();

  // 1B. Rich emerald-moss midtone volume across the upper bolster
  brush.fill("#163316", 155);
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.55, 0.25);
