    [-30, 55], [460, 145], [920, 305], [1230, 465],
    [1230, 960], [680, 810], [280, 740], [-30, 610]
  ], 0.35);

  // 1C. Warm lamplit moss-olive swell on the upper-left & center crown
  brush.fill("#335c20", 140);
