  // 1D. Glowing chartreuse highlight belt along the grazing lamplit crown
  brush.fill("#6fa332", 115);
  brush.fillBleed(0.35, "out");
  drawSmoothPoly([
    [-10, 115], [340, 178], [720, 315], [940, 435],
    [820, 525], [460, 420], [140, 310], [-10, 250]
  ], 0.45);

  brush.fill("#a8d448", 85);
  brush.fillBleed(0.3, "out");
  drawSmoothPoly([
    [10, 140], [290, 195], [580, 295], [720, 375],
    [610, 435], [320, 335], [70, 245]
  ], 0.45);

  // 1E. Foundational pale silvery-celadon washes inside the pressed palm print
  brush.fill("#6c8574", 135);
  brush.fillBleed(0.18, "out");
  brush.fillTexture(0.45, 0.35);
  // Palm body wash
  drawSmoothPoly([
    [475, 565], [530, 470], [610, 458], [685, 472], [750, 515],
    [720, 625], [685, 695], [575, 690], [490, 635]
  ], 0.4);
  // Thumb wash
  drawSmoothPoly([
    [368, 518], [435, 532], [505, 570], [488, 615], [418, 580], [362, 542]
  ], 0.4);
  // Four fingers foundational washes
  drawSmoothPoly([[485, 315], [522, 312], [545, 415], [562, 480], [522, 485], [500, 410]], 0.35);
  drawSmoothPoly([[580, 285], [618, 288], [625, 395], [630, 472], [590, 472], [586, 395]], 0.35);
  drawSmoothPoly([[685, 312], [720, 318], [708, 415], [692, 482], [654, 476], [668, 410]], 0.35);
  drawSmoothPoly([[768, 368], [802, 378], [774, 460], [748, 515], [714, 502], [738, 448]], 0.35);

  // Brighter inner silvery-sage wash on the high-pressure heel, thumb tip & fingertip pads
  brush.fill("#a8bfb0", 125);
  brush.fillBleed(0.15, "out");
  drawSmoothPoly([[495, 575], [555, 565], [608, 625], [585, 675], [512, 645]], 0.45);
  drawSmoothPoly([[650, 545], [712, 535], [705, 655], [655, 670], [642, 605]], 0.45);
  drawSmoothPoly([[372, 520], [432, 540], [422, 575], [368, 546]], 0.45);
  brush.noFill();

  // =========================================================================
  // STAGE 2: SOFT CHARCOAL MASS DEEPENING THE TROUGHS INTO NEAR-BLACK FOREST GREEN
  // =========================================================================
  // 2A. Upper-right ambient darkness beyond the rolled arm contour
  brush.mass("charcoal", "#030704", { precision: 0.75, strength: 0.92, gradient: 0.3, outline: false });
  drawSmoothPoly([
    [180, -30], [1240, -30], [1240, 425], [960, 275], [540, 115], [160, 22]
  ], 0.25);

  // 2B. Deep underside slope of the rolled bolster turning away from the lamplight
  brush.mass("charcoal", "#09170b", { precision: 0.55, strength: 0.78, gradient: 0.55, outline: false });
  drawSmoothPoly([
    [-30, 520], [260, 625], [520, 725], [860, 855], [1230, 995],
    [1230, 1230], [-30, 1230]
  ], 0.35);

  // 2C. Primary deep tuck crease running beneath the rolled bolster
