    [-30, 640], [180, 735], [276, 818], [520, 865], [880, 980], [1230, 1110],
    [1230, 1230], [740, 1140], [360, 960], [160, 860], [-30, 770]
  ], 0.35);

  // 2D. Deepest near-black forest green cavity around the brass tack & three tension pleats
  brush.mass("charcoal", "#030804", { precision: 0.70, strength: 0.98, gradient: 0.35, outline: false });
  // Pleat 1 (sweeping up-right from tack toward palm heel)
  drawSmoothPoly([
