    [470, 695], [365, 775], [285, 838]
  ], 0.35);
  // Pleat 2 (sweeping steeper up-right from tack)
  drawSmoothPoly([
    [262, 810], [312, 705], [372, 600], [398, 565],
    [352, 650], [302, 745], [278, 825]
  ], 0.35);
  // Pleat 3 (sweeping right/down-right along the lower scroll fold)
  drawSmoothPoly([
    [270, 820], [410, 835], [595, 882], [720, 935],
    [575, 922], [395, 878], [268, 848]
  ], 0.35);
  // Deep shadow pocket directly beneath the lower scroll
  drawSmoothPoly([
    [-30, 960], [240, 895], [560, 995], [980, 1150],
    [1230, 1230], [-30, 1230]
  ], 0.3);

  // 2E. Subtle charcoal mass in the compression troughs around the palm & fingers
  brush.mass("charcoal", "#0a1c0d", { precision: 0.60, strength: 0.65, gradient: 0.5, outline: false });
  // Compression rim above fingertips and thumb
  drawSmoothPoly([[342, 505], [395, 495], [452, 528], [435, 548], [378, 524]], 0.4);
  drawSmoothPoly([[476, 298], [520, 290], [535, 345], [492, 348]], 0.4);
  drawSmoothPoly([[572, 268], [618, 268], [625, 325], [580, 325]], 0.4);
  drawSmoothPoly([[678, 296], [724, 302], [718, 352], [676, 346]], 0.4);
  drawSmoothPoly([[762, 352], [806, 365], [792, 410], [755, 398]], 0.4);
  // Shadow hollow between thumb and index finger web
  drawSmoothPoly([[445, 515], [512, 445], [532, 505], [488, 565]], 0.4);
  brush.noMass();

  // =========================================================================
  // STAGE 3: CROSS-CONTOUR WOVEN UNDER-HATCHING
  // =========================================================================
  // Lay down foundational velvet weave before the dense directional pile strokes
  brush.hatchStyle("charcoal", "#0d210f", 0.9);
  brush.hatch(9, 22, { rand: 0.12, gradient: 0.35 });
  drawSmoothPoly([
    [-20, 340], [450, 480], [950, 660], [1220, 790],
    [1220, 1180], [520, 980], [-20, 780]
  ], 0.3);

  brush.hatchStyle("cpencil", "#244a1e", 0.85);
  brush.hatch(8, 18, { rand: 0.10, gradient: 0.3 });
  drawSmoothPoly([
    [-20, 150], [460, 260], [940, 440], [1220, 580],
    [1220, 860], [640, 680], [-20, 460]
  ], 0.35);

  // Under-hatching inside the palm print oriented along the reversed nap angle (-118 deg)
  brush.hatchStyle("2B", "#8fa696", 0.75);
  brush.hatch(6.5, -118, { rand: 0.08, gradient: 0.25 });
  drawSmoothPoly([
    [485, 560], [538, 478], [678, 482], [742, 525],
    [705, 665], [575, 678], [500, 628]
  ], 0.4);
  brush.noHatch();

  // =========================================================================
  // STAGE 4: DENSE SHORT DIRECTIONAL PILE HATCHING IN A FLOWING FIELD
  // =========================================================================
  // Pre-sample the canvas on a jittered grid and bin strokes by tonal/color palette
  // so we can render ~11,000 directional velvet fibres quickly in batched passes.
  const velvetPalette = [
    "#030804", // 0: Abyssal crease black-green
    "#061008", // 1: Near-black forest trough
    "#0b1a0c", // 2: Deep forest shadow
    "#112612", // 3: Dark pine velvet
    "#193618", // 4: Rich dark emerald-moss
    "#23481d", // 5: Deep moss green
    "#315d23", // 6: Mid moss green
    "#437529", // 7: Warm lamplit moss
    "#5b9131", // 8: Olive-chartreuse transition
    "#78b03b", // 9: Luminous chartreuse-moss
    "#99cf48", // 10: Bright chartreuse sheen
    "#bce65d", // 11: Shimmering chartreuse highlight
    "#dcf582", // 12: Golden-chartreuse grazing glint
    "#f4fca8"  // 13: Incandescent lamplight peak
  ];

  const silverNapPalette = [
    "#384d3e", // 0: Deep shadowed bent nap
    "#4f6656", // 1: Dark slate-moss nap
    "#67806f", // 2: Muted celadon-grey nap
    "#809988", // 3: Mid silvery-sage nap
    "#9ab3a2", // 4: Soft silver-celadon nap
    "#b4cbbd", // 5: Luminous silvery nap
    "#cce0d3", // 6: Bright silver-moss sheen
    "#e1efe5", // 7: High-contrast silvery highlight
    "#f2f9f4", // 8: Pure specular silver-white nap tip
    "#dcebd0"  // 9: Warm lamplit chartreuse-silver hybrid
  ];

  let charcoalBins = Array.from({ length: velvetPalette.length }, () => []);
  let tuftBins = Array.from({ length: velvetPalette.length }, () => []);
  let fineVelvetBins = Array.from({ length: velvetPalette.length }, () => []);

  let silverTuftBins = Array.from({ length: silverNapPalette.length }, () => []);
  let silverFineBins = Array.from({ length: silverNapPalette.length }, () => []);

  let silhouetteHairs = [];

  // Jittered stratified sampling across 1200x1200 canvas
  const step = 11.5;
  for (let gy = -10; gy < height + 10; gy += step) {
    for (let gx = -10; gx < width + 10; gx += step) {
      let x = gx + random(-4.8, 4.8);
      let y = gy + random(-4.8, 4.8);

      // Skip inside brass tack head
      if (Math.hypot(x - TACK_X, y - TACK_Y) < TACK_R - 2) continue;

      let sd = getSurfaceData(x, y);
      if (!sd.insideArm) continue;

      // Collect grazing silhouette hairs along the top-right edge of the velvet roll
      if (sd.distToTopEdge >= 0 && sd.distToTopEdge < 16) {
        silhouetteHairs.push({ x, y, sd });
      }

      let nMicro = noise(x * 0.08, y * 0.08);
      let ang = sd.pileAngle + (nMicro - 0.5) * 14;

      if (sd.palmWeight > 0.18) {
        // Inside the pressed palm print: silvery nap where fibres are bent the other way
        let silVal = sd.velvetLum * 0.65 + sd.palmWeight * 0.42 + (nMicro - 0.5) * 0.18;
        if (sd.palmEdgeRidge > 0.15) silVal += sd.palmEdgeRidge * 0.25;

        let sIdx = Math.floor(constrain(silVal * 8.8, 0, 8.99));
        // Blend warm chartreuse-silver on the upper-left lamplit fingers
        if (sd.chartreuseGlow > 0.48 && random() < 0.32) sIdx = 9;

        let len = map(sd.palmWeight, 0.18, 1.0, 12, 19) * random(0.8, 1.2);
        silverTuftBins[sIdx].push({ x, y, len, ang });

        // Add denser fine directional strokes inside the palm print for crisp bent-fibre sheen
        let fx = x + random(-3.5, 3.5);
        let fy = y + random(-3.5, 3.5);
        let fIdx = Math.min(8, Math.max(0, sIdx + (random() < 0.45 ? 1 : 0)));
        silverFineBins[fIdx].push({
          x: fx,
          y: fy,
          len: random(8, 15),
          ang: ang + random(-6, 6)
        });

        // Along the partial-pressure creases or boundary, interleave upright moss fibres
        if (sd.palmWeight < 0.62 || sd.palmEdgeRidge > 0.2) {
          let vIdx = Math.floor(constrain(sd.velvetLum * 11.5, 1, 11));
          fineVelvetBins[vIdx].push({
            x: x + random(-3, 3),
            y: y + random(-3, 3),
            len: random(7, 13),
            ang: sd.pileAngle + random(-10, 10)
          });
        }
      } else {
        // Undisturbed moss-green velvet pile
        let lum = sd.velvetLum + (nMicro - 0.5) * 0.14;
        let vIdx = Math.floor(constrain(lum * 13.2, 0, 13.99));

        // Deep troughs get soft charcoal strokes; midtones & crown get velvetTuft & fine pencil
        if (sd.troughWeight > 0.45 && vIdx <= 4) {
          charcoalBins[vIdx].push({
            x, y,
            len: random(14, 24),
            ang: ang + random(-8, 8)
          });
        } else {
          tuftBins[vIdx].push({
            x, y,
            len: random(11, 19),
            ang
          });
        }

        // Second offset sub-layer of fine directional hatching for hyperreal plush density
        if (random() < 0.85) {
          let fx = x + random(-4.2, 4.2);
          let fy = y + random(-4.2, 4.2);
          let shimmerBoost = (sd.chartreuseGlow > 0.35 && random() < 0.4) ? 1 : 0;
          let fIdx = Math.min(13, Math.max(0, vIdx + shimmerBoost + (random() < 0.25 ? -1 : 0)));
          fineVelvetBins[fIdx].push({
            x: fx,
            y: fy,
            len: random(7, 14),
            ang: ang + random(-7, 7)
          });
        }
      }
    }
  }

  // Activate our custom vector field for field-aware flowing strokes
  brush.field("velvetPileField");

  // 4A. Render deep trough charcoal pile strokes
  for (let i = 0; i < charcoalBins.length; i++) {
    let bin = charcoalBins[i];
    if (bin.length === 0) continue;
    brush.set("charcoal", velvetPalette[i], 0.85);
    for (let s of bin) {
      brush.flowLine(s.x, s.y, s.len, s.ang);
    }
  }

  // 4B. Render plush multi-bristle velvetTuft strokes across the moss-green body
  for (let i = 0; i < tuftBins.length; i++) {
    let bin = tuftBins[i];
    if (bin.length === 0) continue;
    brush.set("velvetTuft", velvetPalette[i], 0.95);
    for (let s of bin) {
      brush.flowLine(s.x, s.y, s.len, s.ang);
    }
  }

  // 4C. Render bent silvery-nap velvetTuft strokes inside the palm print
  for (let i = 0; i < silverTuftBins.length; i++) {
    let bin = silverTuftBins[i];
    if (bin.length === 0) continue;
    brush.set("velvetTuft", silverNapPalette[i], 0.9);
    for (let s of bin) {
      brush.flowLine(s.x, s.y, s.len, s.ang);
    }
  }

  brush.noField();

  // 4D. Render crisp short directional hatching ("cpencil" & "2B") for individual fibre definition
  for (let i = 0; i < fineVelvetBins.length; i++) {
    let bin = fineVelvetBins[i];
    if (bin.length === 0) continue;
    let bName = i >= 9 ? "cpencil" : "2B";
    let w = i >= 11 ? 0.68 : 0.78;
    brush.set(bName, velvetPalette[i], w);
    for (let s of bin) {
      let rad = s.ang * (Math.PI / 180);
      let x2 = s.x + Math.cos(rad) * s.len;
      let y2 = s.y + Math.sin(rad) * s.len;
      brush.line(s.x, s.y, x2, y2);
    }
  }

  // 4E. Render fine silvery-celadon fibres inside the palm print ("2B" & "HB")
  for (let i = 0; i < silverFineBins.length; i++) {
    let bin = silverFineBins[i];
    if (bin.length === 0) continue;
    let bName = i >= 6 ? "HB" : "2B";
    let w = i >= 7 ? 0.62 : 0.75;
    brush.set(bName, silverNapPalette[i], w);
    for (let s of bin) {
      let rad = s.ang * (Math.PI / 180);
      let x2 = s.x + Math.cos(rad) * s.len;
      let y2 = s.y + Math.sin(rad) * s.len;
      brush.line(s.x, s.y, x2, y2);
    }
  }

  // 4F. Extra concentrated pass of shimmering chartreuse highlights & palm-edge micro-ridges
  // This gives the grazing crown and the crushed-nap border their hyperreal tactile shimmer
  let shimmerPts = [[], [], []]; // [chartreuse-lime, golden-chartreuse, incandescent-ivory-lime]
  let ridgeSilverPts = [];
  let ridgeShadowPts = [];

  for (let i = 0; i < 2600; i++) {
    let x = random(20, 1150);
    let y = random(90, 880);
    let sd = getSurfaceData(x, y);
    if (!sd.insideArm) continue;

    // Shimmering chartreuse crown fibres
    if (sd.chartreuseGlow > 0.42 && sd.palmWeight < 0.35) {
      let tier = sd.chartreuseGlow > 0.78 ? 2 : (sd.chartreuseGlow > 0.60 ? 1 : 0);
      shimmerPts[tier].push({
        x, y,
        len: random(5, 11),
        ang: sd.pileAngle + random(-12, 12)
      });
    }

    // Crisp micro-contrast along the boundary of the palm print where bent nap meets upright pile
    if (sd.palmEdgeRidge > 0.28) {
      if (sd.palmTroughRim > 0.12 && random() < 0.55) {
        ridgeShadowPts.push({
          x, y,
          len: random(6, 12),
          ang: sd.pileAngle + random(-10, 10)
        });
      } else {
        ridgeSilverPts.push({
          x, y,
          len: random(5, 10),
          ang: sd.pileAngle + random(-8, 8)
        });
      }
    }
  }

  const shimmerColors = ["#a8db4b", "#d8f274", "#f6fcb3"];
  for (let t = 0; t < 3; t++) {
    brush.set("cpencil", shimmerColors[t], 0.58);
    for (let s of shimmerPts[t]) {
      let rad = s.ang * (Math.PI / 180);
      brush.line(s.x, s.y, s.x + Math.cos(rad) * s.len, s.y + Math.sin(rad) * s.len);
    }
  }

  brush.set("2B", "#040b05", 0.65);
  for (let s of ridgeShadowPts) {
    let rad = s.ang * (Math.PI / 180);
    brush.line(s.x, s.y, s.x + Math.cos(rad) * s.len, s.y + Math.sin(rad) * s.len);
  }

  brush.set("HB", "#edf7f0", 0.55);
  for (let s of ridgeSilverPts) {
    let rad = s.ang * (Math.PI / 180);
    brush.line(s.x, s.y, s.x + Math.cos(rad) * s.len, s.y + Math.sin(rad) * s.len);
  }

  // 4G. Grazing backlit/sidelit velvet fuzz along the upper-right silhouette contour against dark background
  for (let pass = 0; pass < 3; pass++) {
    let col = pass === 0 ? "#284f1e" : (pass === 1 ? "#7ab038" : "#d4f071");
    let w = pass === 0 ? 0.68 : (pass === 1 ? 0.52 : 0.38);
    brush.set("2B", col, w);
    for (let h of silhouetteHairs) {
      if (pass === 2 && h.x > 820) continue; // brightest golden edge-fuzz near the upper-left light
      let normalAng = -72 + (h.x / 1200) * 16 + random(-18, 18);
      let rad = normalAng * (Math.PI / 180);
      let len = random(5, 11) * (1 - pass * 0.18);
      let sx = h.x - Math.cos(rad) * 3;
      let sy = h.y - Math.sin(rad) * 3;
      brush.line(sx, sy, sx + Math.cos(rad) * len, sy + Math.sin(rad) * len);
    }
  }

  // 4H. Subtle micro-grain spray along the chartreuse sheen and silvery palm center
  brush.set("spray", "#d9f272", 0.55);
  brush.line(80, 195, 640, 365);
  brush.set("spray", "#e2efe6", 0.5);
  brush.line(530, 610, 680, 560);
  brush.line(510, 345, 700, 355);

  // =========================================================================
  // STAGE 5: SINGLE BRASS UPHOLSTERY TACK (RENDERED PRECISELY)
  // =========================================================================
  renderBrassTack(TACK_X, TACK_Y, TACK_R);

  // =========================================================================
  // STAGE 6: STRAY CAT HAIR (RENDERED PRECISELY)
  // =========================================================================
  renderStrayCatHair();

  noLoop();
}

function renderBrassTack(cx, cy, r) {
  // 1. Deep pinched velvet shadow cavity surrounding the tack head
  brush.noStroke();
  brush.wash("#010302", 245);
  brush.circle(cx + 2, cy + 3, r + 9, 0.15);
  brush.noWash();

  // Radial pinched velvet fibres pulling into the tack dimple
  for (let i = 0; i < 110; i++) {
    let ang = random(0, 360);
    let rad = ang * (Math.PI / 180);
    let rIn = r + random(-1, 3);
    let rOut = r + random(12, 34);
    let x1 = cx + Math.cos(rad) * rIn;
    let y1 = cy + Math.sin(rad) * rIn;
    let x2 = cx + Math.cos(rad) * rOut;
    let y2 = cy + Math.sin(rad) * rOut;

    // Fibres on the upper-left rim of the dimple catch emerald/chartreuse light
    let rimLight = -Math.cos((ang - 135) * Math.PI / 180);
    if (rimLight > 0.35 && random() < 0.5) {
      brush.set("2B", random() < 0.4 ? "#74a634" : "#2d5922", 0.52);
    } else {
      brush.set("charcoal", "#020603", 0.65);
    }
    brush.line(x1, y1, x2, y2);
  }

  // Cast shadow of the domed brass tack onto the lower-right velvet fold
  brush.noStroke();
  brush.wash("#010301", 235);
  drawSmoothPoly([
    [cx + 6, cy - r + 4],
    [cx + r + 11, cy - 4],
    [cx + r + 14, cy + r * 0.65],
    [cx + r * 0.55, cy + r + 13],
    [cx - 8, cy + r + 7],
    [cx - 4, cy + 4]
  ], 0.35);

  // 2. Base metallic body of the domed antique brass tack
  brush.wash("#241907", 250);
  brush.circle(cx, cy, r, 0.04);

  // Warm burnished gold-brass upper-left hemisphere
  brush.wash("#7d5c18", 210);
  drawSmoothPoly([
    [cx - r * 0.92, cy + r * 0.15],
    [cx - r * 0.72, cy - r * 0.68],
    [cx - r * 0.10, cy - r * 0.94],
    [cx + r * 0.58, cy - r * 0.72],
    [cx + r * 0.25, cy + r * 0.15],
    [cx - r * 0.35, cy + r * 0.42]
  ], 0.4);
  brush.noWash();

  // 3. Precision concentric & radial metallic shading across the brass dome
  const metalLayers = [
    // Dark bronze core shadow band curving through the center-right of the dome
    { col: "#171004", angStart: -25, angEnd: 115, radFrac: 0.68, w: 0.75, b: "2B", n: 28 },
    { col: "#2e2009", angStart: -45, angEnd: 135, radFrac: 0.78, w: 0.65, b: "cpencil", n: 32 },
    // Reflected moss-green velvet on the lower-right belly of the brass dome
    { col: "#3c5223", angStart: 15, angEnd: 110, radFrac: 0.84, w: 0.58, b: "cpencil", n: 24 },
    { col: "#5b7331", angStart: 28, angEnd: 88, radFrac: 0.88, w: 0.48, b: "cpencil", n: 16 },
    // Antique brass mid-gold transitions
    { col: "#6b4e14", angStart: 115, angEnd: 325, radFrac: 0.82, w: 0.62, b: "cpencil", n: 34 },
    { col: "#9c7521", angStart: 140, angEnd: 305, radFrac: 0.72, w: 0.58, b: "cpencil", n: 32 },
    { col: "#c99e36", angStart: 165, angEnd: 285, radFrac: 0.60, w: 0.55, b: "cpencil", n: 28 },
    { col: "#e8c458", angStart: 185, angEnd: 268, radFrac: 0.48, w: 0.50, b: "HB", n: 24 }
  ];

  for (let layer of metalLayers) {
    brush.set(layer.b, layer.col, layer.w);
    for (let i = 0; i < layer.n; i++) {
      let a1 = random(layer.angStart, layer.angEnd - 18);
      let a2 = a1 + random(14, 32);
      let rf = layer.radFrac * random(0.84, 1.06);
      brush.arc(cx, cy, r * rf, a1, a2);
    }
  }

  // Subtle green verdigris patina & crimped rim bevel at the edge of the tack
  brush.set("pen", "#567d62", 0.45);
  brush.arc(cx, cy, r * 0.96, 125, 195);
  brush.arc(cx, cy, r * 0.95, 295, 340);

  brush.set("rotring", "#0c0903", 0.55);
  brush.arc(cx, cy, r * 0.99, 0, 360);

  // Secondary warm rim glint on the lower-right bevel edge
  brush.set("pen", "#b89338", 0.45);
  brush.arc(cx, cy, r * 0.94, 20, 78);

  // 4. Blazing warm lamplight specular crescent on the upper-left dome
  brush.set("cpencil", "#fae38c", 0.65);
  for (let i = 0; i < 14; i++) {
    let rr = r * random(0.36, 0.56);
    brush.arc(cx, cy, rr, 198 + random(-8, 8), 252 + random(-8, 8));
  }

  brush.set("pen", "#fff7cc", 0.58);
  for (let i = 0; i < 10; i++) {
    let rr = r * random(0.40, 0.50);
    brush.arc(cx, cy, rr, 208, 244);
  }

  // Razor-sharp incandescent core specular glint
  brush.set("rotring", "#ffffff", 0.62);
  brush.arc(cx, cy, r * 0.45, 216, 236);
  brush.line(cx - r * 0.36, cy - r * 0.30, cx - r * 0.26, cy - r * 0.38);

  // Overlapping tiny dark velvet pile tips around the tack perimeter so it sits deep inside the tuft
  brush.set("pen", "#050d06", 0.48);
  for (let a = 0; a < 360; a += 11) {
    let rad = (a + random(-4, 4)) * (Math.PI / 180);
    let r1 = r + random(2, 6);
    let r2 = r - random(1.5, 4.0);
    brush.line(
      cx + Math.cos(rad) * r1,
      cy + Math.sin(rad) * r1,
      cx + Math.cos(rad) * r2,
      cy + Math.sin(rad) * r2
    );
  }
}

function renderStrayCatHair() {
  // Placed across the high-contrast near-black forest green trough between the tack pleats and palm heel
  const hairPts = [
    [364, 738, 0.25],
    [402, 724, 0.55],
    [446, 718, 0.75],
    [492, 725, 0.70],
    [534, 742, 0.45],
    [566, 764, 0.18]
  ];

  // 1. Whisper-thin broken cast shadow on the velvet pile tips just below the hair
  brush.set("rotring", "#010402", 0.46);
  let shadowPts = hairPts.map(p => [p[0] + 1.8, p[1] + 2.8, p[2] * 0.85]);
  brush.spline(shadowPts, 0.5);

  // 2. Warm translucent buff/ivory under-shaft of the cat hair
  brush.set("pen", "#b8ae96", 0.44);
  brush.spline(hairPts, 0.5);

  // 3. Crisp luminous cream-white core catching the warm side lamplight
  let litCorePts = [
    [366, 737.4, 0.20],
    [402, 723.5, 0.52],
    [446, 717.5, 0.68],
    [492, 724.5, 0.62],
    [534, 741.5, 0.38],
    [564, 762.8, 0.12]
  ];
  brush.set("rotring", "#f5f0e1", 0.36);
  brush.spline(litCorePts, 0.5);

  // 4. Pure specular highlight along the central arch of the hair
  let specPts = [
    [396, 725.2, 0.25],
    [438, 718.0, 0.55],
    [482, 722.2, 0.45],
    [518, 734.0, 0.20]
  ];
  brush.set("rotring", "#ffffff", 0.28);
  brush.spline(specPts, 0.5);

  // Tiny warm root bulb at the left end
  brush.set("rotring", "#dfd6be", 0.42);
  brush.line(362.5, 738.8, 365.5, 737.5);

  // 5. Embed the stray hair into the pile: a few individual moss velvet fibres overlapping it
  const overlapLocs = [
    [384, 730, 18, "#0b1e0d"],
    [468, 720, 22, "#132e15"],
    [522, 736, 25, "#0d2210"],
    [552, 754, 28, "#08170a"]
  ];
  for (let ov of overlapLocs) {
    brush.set("pen", ov[3], 0.40);
    let rad = ov[2] * (Math.PI / 180);
    brush.line(
      ov[0] - Math.cos(rad) * 4,
      ov[1] - Math.sin(rad) * 4,
      ov[0] + Math.cos(rad) * 5,
      ov[1] + Math.sin(rad) * 5
    );
  }
}

// Victorian Darkfield Rosette of Sea Salt (Halite), Sucrose Prisms & Glass Seed Beads
// Rendered in p5.js 2.x + p5.brush

const PAL = {
  bgDeep: "#03060c",
  bgMid: "#060c18",
  bgCondenser: "#0a1528",
  slateDark: "#14243b",
  slateMid: "#2c4a70",
  slateLight: "#5b82ad",
  iceBlue: "#9ec5eb",
  icePale: "#d8ecff",
  white: "#ffffff",
  warmWhite: "#fffcf2",
  ceruleanDeep: "#1268b3",
  cerulean: "#1fa2ff",
  ceruleanBright: "#5ce1ff",
  roseDeep: "#8f1d45",
  roseMadder: "#e0366b",
  roseBright: "#ff6b9d",
  amberFaint: "#ffd285",
  balsamRing: "#6f8eb3"
};

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(1886);
  noiseSeed(1886);
}

function draw() {
  translate(-width / 2, -height / 2);
  background(PAL.bgDeep);

  const cx = 600;
  const cy = 600;

  // 1. Dense Darkfield Ground & Optical Condenser Vignette
  drawDarkfieldGround(cx, cy);

  // 2. Pale Circular Slide Boundary (Canada Balsam & Cover-Glass Bevel at Edge)
  drawSlideBoundary(cx, cy, 548);

  // 3. Subtle Microscope Slide Surface Caustics & Radial Alignment Guides
  drawSubtleSlideCaustics(cx, cy);

  // 4. Outer Ring 8 (r = 500): 64-fold Micro-Salt & Ballotini Glass Bead Border
  drawOuterMicroRing(cx, cy, 500, 64);

  // 5. Ring 7 (r = 452): 32-fold Scalloped Coronet of Salt Cubes, Seed Beads & Sugar Needles
  drawCoronetRing(cx, cy, 452, 32);

  // 6. Ring 6 (r = 386): 24-fold Crown of Isometric Hopper Cubes & Beveled Sugar Tablets
  drawCrownRing(cx, cy, 386, 24);

  // 7. Ring 5 (r = 302): 16-fold Grand Monoclinic Sugar Prisms, Interstitial Salt & Twin Beads
  drawGrandSugarRing(cx, cy, 302, 16);

  // 8. Ring 4 (r = 222): 16-fold Large 3D Halite Hopper Cubes (Alternating Cube & Corner-Up)
  drawMainHaliteRing(cx, cy, 222, 16);

  // 9. Ring 3 (r = 164): 16-fold Glass Seed Bead Necklace & Tabular Sugar Diamonds
  drawBeadNecklaceRing(cx, cy, 164, 16);

  // 10. Ring 2 (r = 108): 8 Primary Sucrose Sphenoid Petals & 8 Tilted Halite Cubes
  drawInnerPetalRing(cx, cy, 108, 8);

  // 11. Ring 1 (r = 57): 8 Axial Glass Seed Beads & Micro-Salt Satellites
  drawColletBeadRing(cx, cy, 57, 8);

  // 12. Centerpiece (r = 0): Grand Stepped Hopper Crystal of Sea Salt
  drawSaltCrystal(cx, cy, 41, 18, 16, -14, {
    hopperSteps: 5,
    isCenterpiece: true,
    cleavageCount: 3,
    inclusions: 4
  });

  // 13. Final Stray Micro-Grains & Lens-Sharp Specular Prickles
  drawStrayMicroGrains(cx, cy);

  noLoop();
}

// ============================================================================
// LOW-LEVEL DRAWING HELPERS (Strict compliance with brush.set before strokes)
// ============================================================================

function fillPolyWash(pts, col, alpha) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.wash(col, alpha);
  brush.beginShape(0);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noWash();
}

function strokeLine(x1, y1, x2, y2, brushName, col, w) {
  let d = dist(x1, y1, x2, y2);
  if (d < 0.35) return;
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set(brushName, col, w);
  brush.line(x1, y1, x2, y2);
}

function strokeSpline(pts, curv, brushName, col, w) {
  if (!pts || pts.length < 2) return;
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set(brushName, col, w);
  brush.spline(pts, curv);
}

function strokeArc(x, y, r, startAng, endAng, brushName, col, w) {
  if (r < 0.5 || abs(endAng - startAng) < 1) return;
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set(brushName, col, w);
  brush.arc(x, y, r, startAng, endAng);
}

function stippleDot(x, y, col, w = 0.2, brushName = "rotring") {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set(brushName, col, w);
  let a = random(360);
  let len = random(0.55, 1.35);
  brush.line(x, y, x + cos(a) * len, y + sin(a) * len);
}

function stippleAlongSegment(x1, y1, x2, y2, count, spread, col, w = 0.18, brushName = "rotring") {
  let dx = x2 - x1;
  let dy = y2 - y1;
  let len = sqrt(dx * dx + dy * dy);
  if (len < 1) return;
  let nx = -dy / len;
  let ny = dx / len;
  for (let i = 0; i < count; i++) {
    let t = random();
    let off = randomGaussian(0, spread);
    let px = x1 + dx * t + nx * off;
    let py = y1 + dy * t + ny * off;
    stippleDot(px, py, col, w, brushName);
  }
}

function stippleQuad(q, count, col, w = 0.18, edgeBias = true) {
  // q = [p0, p1, p2, p3]
  for (let i = 0; i < count; i++) {
    let u = edgeBias ? pow(random(), 1.65) : random();
    let v = random();
    if (random() < 0.5 && edgeBias) u = 1 - u;
    let ax = lerp(q[0][0], q[1][0], u);
    let ay = lerp(q[0][1], q[1][1], u);
    let bx = lerp(q[3][0], q[2][0], u);
    let by = lerp(q[3][1], q[2][1], u);
    let px = lerp(ax, bx, v);
    let py = lerp(ay, by, v);
    stippleDot(px, py, col, w, "rotring");
  }
}

function hatchQuad(q, linesCount, col, w = 0.14, brushName = "2H", partial = 1.0) {
  for (let i = 1; i <= linesCount; i++) {
    let t = i / (linesCount + 1);
    let x1 = lerp(q[0][0], q[3][0], t);
    let y1 = lerp(q[0][1], q[3][1], t);
    let x2 = lerp(q[1][0], q[2][0], t);
    let y2 = lerp(q[1][1], q[2][1], t);
    let endT = constrain(partial * random(0.75, 1.15), 0.15, 1.0);
    let ex = lerp(x1, x2, endT);
    let ey = lerp(y1, y2, endT);
    strokeLine(x1, y1, ex, ey, brushName, col, w);
  }
}

function lerpPt(a, b, t) {
  return [lerp(a[0], b[0], t), lerp(a[1], b[1], t)];
}

// ============================================================================
// 1. DARKFIELD GROUND & SLIDE MOUNT BOUNDARY
// ============================================================================

function drawDarkfieldGround(cx, cy) {
  // Deep layered abyssal blue-black washes for optical depth
  brush.noStroke();
  brush.noFill();
  brush.noHatch();

  const rings = [
    { r: 580, col: "#040812", a: 95 },
    { r: 545, col: "#060d1c", a: 70 },
    { r: 440, col: "#081226", a: 45 },
    { r: 310, col: "#0a1730", a: 35 },
    { r: 170, col: "#0c1b36", a: 30 }
  ];

  for (let item of rings) {
    brush.wash(item.col, item.a);
    brush.circle(cx, cy, item.r, 0.02);
    brush.noWash();
  }

  // Subtle dark charcoal hatching in the extreme outer corners outside the slide ring
  for (let corner = 0; corner < 4; corner++) {
    let ang = corner * 90 + 45;
    for (let i = 0; i < 28; i++) {
      let r = random(565, 820);
      let a = ang + random(-38, 38);
      let x = cx + cos(a) * r;
      let y = cy + sin(a) * r;
      if (x > 5 && x < 1195 && y > 5 && y < 1195) {
        let tang = a + 90 + random(-8, 8);
        strokeLine(
          x - cos(tang) * 25,
          y - sin(tang) * 25,
          x + cos(tang) * 25,
          y + sin(tang) * 25,
          "charcoal",
          "#020408",
          0.6
        );
      }
    }
  }
}

function drawSlideBoundary(cx, cy, rSlide) {
  // The pale circular slide boundary: ground cover-glass bevel + Canada balsam meniscus
  // Drawn in broken concentric arcs with faint cerulean and rose madder chromatic fringes

  // Faint chromatic aberration arcs on the slide bevel
  for (let i = 0; i < 36; i++) {
    let a1 = i * 10 + random(-2, 2);
    let a2 = a1 + random(5, 9.5);
    let radShift = sin(a1 * 2) * 0.8;

    // Cerulean inner refractive fringe
    strokeArc(
      cx,
      cy,
      rSlide - 2.2 + radShift,
      a1,
      a2,
      "rotring",
      i % 2 === 0 ? PAL.ceruleanDeep : "#184f85",
      0.22
    );

    // Rose madder outer refractive fringe
    if (i % 3 !== 0) {
      strokeArc(
        cx,
        cy,
        rSlide + 9.5 + radShift,
        a1 + 1,
        a2 - 1,
        "rotring",
        PAL.roseDeep,
        0.2
      );
    }
  }

  // Primary twin bevel rings of the circular coverslip
  for (let seg = 0; seg < 72; seg++) {
    let a1 = seg * 5;
    let a2 = a1 + random(3.2, 4.9);
    // Modulate intensity based on oblique condenser angle (brightest at NW and SE)
    let lightMod = 0.5 + 0.5 * pow(cos(a1 - 135), 2);
    let colMain = lightMod > 0.72 ? PAL.iceBlue : lightMod > 0.4 ? PAL.balsamRing : PAL.slateMid;
    let wMain = map(lightMod, 0, 1, 0.16, 0.34);

    strokeArc(cx, cy, rSlide, a1, a2, "2H", colMain, wMain);
    strokeArc(cx, cy, rSlide + 8, a1 + 0.5, a2 - 0.3, "rotring", PAL.slateMid, wMain * 0.75);

    if (lightMod > 0.78 && random() < 0.65) {
      strokeArc(cx, cy, rSlide + 0.6, a1 + 0.8, a2 - 0.8, "cpencil", PAL.white, 0.24);
    }
  }

  // Fine stipple dust & microscopic balsam air-pearls along the circular boundary
  for (let i = 0; i < 420; i++) {
    let a = random(360);
    let r = rSlide + randomGaussian(3.5, 4.5);
    let x = cx + cos(a) * r;
    let y = cy + sin(a) * r;
    let col = random() < 0.18 ? PAL.icePale : random() < 0.12 ? PAL.cerulean : PAL.slateLight;
    stippleDot(x, y, col, random(0.14, 0.24), "rotring");
  }

  // A few tiny trapped spherical balsam micro-bubbles near the coverslip edge
  for (let i = 0; i < 18; i++) {
    let a = i * 20 + random(-6, 6);
    let r = rSlide + random(-6, 10);
    let bx = cx + cos(a) * r;
    let by = cy + sin(a) * r;
    let br = random(1.8, 3.8);
    strokeArc(bx, by, br, 0, 360, "rotring", PAL.slateLight, 0.18);
    strokeArc(bx, by, br + 0.7, 200, 310, "rotring", PAL.cerulean, 0.16);
    strokeArc(bx, by, br + 0.7, 20, 130, "rotring", PAL.roseMadder, 0.16);
    stippleDot(bx - br * 0.35, by - br * 0.35, PAL.white, 0.26, "cpencil");
  }
}

function drawSubtleSlideCaustics(cx, cy) {
  // Extremely delicate radial refraction lines and concentric condenser diffraction rings
  const ringRadii = [57, 108, 164, 222, 302, 386, 452, 500];
  for (let r of ringRadii) {
    for (let s = 0; s < 32; s++) {
      if (random() < 0.45) continue;
      let a1 = s * (360 / 32) + random(-2, 2);
      let a2 = a1 + random(2, 6);
      strokeArc(cx, cy, r, a1, a2, "rotring", "#162942", 0.14);
    }
  }

  // Faint microscopic surface scratches on the glass slide
  for (let i = 0; i < 24; i++) {
    let a = random(360);
    let r = random(40, 520);
    let x = cx + cos(a) * r;
    let y = cy + sin(a) * r;
    let dir = random(360);
    let len = random(8, 28);
    strokeLine(
      x,
      y,
      x + cos(dir) * len,
      y + sin(dir) * len,
      "rotring",
      "#132338",
      0.12
    );
  }
}

// ============================================================================
// 2. HYPERREAL 3D SEA SALT (HALITE) CRYSTAL RENDERER
// ============================================================================

function rotate3D(v, rx, ry, rz) {
  let [x, y, z] = v;
  // Rotate X
  let y1 = y * cos(rx) - z * sin(rx);
  let z1 = y * sin(rx) + z * cos(rx);
  let x1 = x;
  // Rotate Y
  let x2 = x1 * cos(ry) + z1 * sin(ry);
  let z2 = -x1 * sin(ry) + z1 * cos(ry);
  let y2 = y1;
  // Rotate Z
  let x3 = x2 * cos(rz) - y2 * sin(rz);
  let y3 = x2 * sin(rz) + y2 * cos(rz);
  let z3 = z2;
  return [x3, y3, z3];
}

function drawSaltCrystal(cx, cy, radius, zRot, tiltX, tiltY, opts = {}) {
  // Subtle natural cuboid proportions of a real halite crystal
  let ax = opts.ax || random(0.92, 1.08);
  let ay = opts.ay || random(0.92, 1.08);
  let az = opts.az || random(0.84, 1.04);
  let hopperSteps = opts.hopperSteps !== undefined ? opts.hopperSteps : 3;
  let cleavageCount = opts.cleavageCount !== undefined ? opts.cleavageCount : 2;
  let inclusions = opts.inclusions !== undefined ? opts.inclusions : 2;

  // 8 vertices of cube
  const rawVerts = [
    [-ax, -ay, -az], // 0
    [ax, -ay, -az],  // 1
    [ax, ay, -az],   // 2
    [-ax, ay, -az],  // 3
    [-ax, -ay, az],  // 4
    [ax, -ay, az],   // 5
    [ax, ay, az],    // 6
    [-ax, ay, az]    // 7
  ];

  const v3d = rawVerts.map(v => rotate3D(v, tiltX, tiltY, zRot));
  const v2d = v3d.map(v => [cx + v[0] * radius, cy + v[1] * radius]);

  // 6 faces with outward normals
  const faceDefs = [
    { idx: [4, 5, 6, 7], n: [0, 0, 1] },   // top (+Z)
    { idx: [0, 3, 2, 1], n: [0, 0, -1] },  // bottom (-Z)
    { idx: [1, 2, 6, 5], n: [1, 0, 0] },   // +X
    { idx: [0, 4, 7, 3], n: [-1, 0, 0] },  // -X
    { idx: [3, 7, 6, 2], n: [0, 1, 0] },   // +Y
    { idx: [0, 1, 5, 4], n: [0, -1, 0] }   // -Y
  ];

  let backFaces = [];
  let frontFaces = [];

  for (let f of faceDefs) {
    let rn = rotate3D(f.n, tiltX, tiltY, zRot);
    let pts = f.idx.map(i => v2d[i]);
    let pts3 = f.idx.map(i => v3d[i]);
    let avgZ = (pts3[0][2] + pts3[1][2] + pts3[2][2] + pts3[3][2]) / 4;
    let faceObj = { idx: f.idx, n: rn, pts, pts3, avgZ };
    if (rn[2] < 0) {
      backFaces.push(faceObj);
    } else {
      frontFaces.push(faceObj);
    }
  }

  // Sort front faces back-to-front by avgZ
  frontFaces.sort((a, b) => a.avgZ - b.avgZ);

  // --- STEP 1: Slide Caustic Halo Underneath Crystal ---
  if (radius > 10) {
    let haloAng = zRot + 45;
    strokeArc(
      cx + cos(haloAng) * (radius * 0.12),
      cy + sin(haloAng) * (radius * 0.12),
      radius * 1.18,
      haloAng - 55,
      haloAng + 55,
      "rotring",
      "#133863",
      0.18
    );
    strokeArc(
      cx - cos(haloAng) * (radius * 0.12),
      cy - sin(haloAng) * (radius * 0.12),
      radius * 1.16,
      haloAng + 125,
      haloAng + 235,
      "rotring",
      "#4d1530",
      0.18
    );
  }

  // --- STEP 2: Refracted Back Edges (Seen Through the Transparent Salt Cube) ---
  // In halite (n = 1.544), rear edges contract slightly toward the optical center and split chromatically
  const v2dRefract = v3d.map(v => [
    cx + v[0] * radius * 0.9,
    cy + v[1] * radius * 0.9
  ]);

  let drawnBackEdges = new Set();
  for (let bf of backFaces) {
    for (let k = 0; k < 4; k++) {
      let i1 = bf.idx[k];
      let i2 = bf.idx[(k + 1) % 4];
      let key = min(i1, i2) + "_" + max(i1, i2);
      if (drawnBackEdges.has(key)) continue;
      drawnBackEdges.add(key);

      let p1 = v2dRefract[i1];
      let p2 = v2dRefract[i2];

      // Chromatic dispersion of internal rear edge (cerulean & rose madder)
      strokeLine(p1[0] - 1.1, p1[1] - 0.9, p2[0] - 1.1, p2[1] - 0.9, "rotring", PAL.ceruleanDeep, 0.18);
      strokeLine(p1[0] + 1.1, p1[1] + 0.9, p2[0] + 1.1, p2[1] + 0.9, "rotring", PAL.roseDeep, 0.18);

      // Stippled ghost edge
      stippleAlongSegment(p1[0], p1[1], p2[0], p2[1], floor(radius * 0.65), 0.7, PAL.slateLight, 0.17, "rotring");
    }
  }

  // --- STEP 3: Internal 90-Degree Cleavage Fractures & Negative-Crystal Brine Inclusions ---
  if (radius > 11 && frontFaces.length > 0) {
    let mainF = frontFaces[frontFaces.length - 1];
    let q = mainF.pts;

    for (let c = 0; c < cleavageCount; c++) {
      let t = random(0.28, 0.72);
      let a1 = lerpPt(q[0], q[1], t);
      let a2 = lerpPt(q[3], q[2], t);
      let pStart = lerpPt(a1, a2, random(0.1, 0.35));
      let pEnd = lerpPt(a1, a2, random(0.65, 0.92));

      // Rainbow interference fringe along internal cleavage plane
      strokeLine(pStart[0] - 1, pStart[1] - 1, pEnd[0] - 1, pEnd[1] - 1, "rotring", PAL.cerulean, 0.2);
      strokeLine(pStart[0] + 1, pStart[1] + 1, pEnd[0] + 1, pEnd[1] + 1, "rotring", PAL.roseMadder, 0.2);
      strokeLine(pStart[0], pStart[1], pEnd[0], pEnd[1], "2H", PAL.icePale, 0.2);
      stippleAlongSegment(pStart[0], pStart[1], pEnd[0], pEnd[1], floor(radius * 0.45), 1.1, PAL.white, 0.18, "rotring");
    }

    // Rectangular brine inclusions with tiny vapour bubble highlights
    for (let inc = 0; inc < inclusions; inc++) {
      let u = random(0.25, 0.75);
      let v = random(0.25, 0.75);
      let du = random(0.06, 0.13);
      let dv = random(0.06, 0.13);
      let b0 = lerpPt(lerpPt(q[0], q[1], u), lerpPt(q[3], q[2], u), v);
      let b1 = lerpPt(lerpPt(q[0], q[1], u + du), lerpPt(q[3], q[2], u + du), v);
      let b2 = lerpPt(lerpPt(q[0], q[1], u + du), lerpPt(q[3], q[2], u + du), v + dv);
      let b3 = lerpPt(lerpPt(q[0], q[1], u), lerpPt(q[3], q[2], u), v + dv);

      strokeLine(b0[0], b0[1], b1[0], b1[1], "rotring", PAL.cerulean, 0.16);
      strokeLine(b1[0], b1[1], b2[0], b2[1], "rotring", PAL.icePale, 0.16);
      strokeLine(b2[0], b2[1], b3[0], b3[1], "rotring", PAL.roseMadder, 0.16);
      strokeLine(b3[0], b3[1], b0[0], b0[1], "rotring", PAL.slateLight, 0.16);
      stippleDot((b0[0] + b2[0]) * 0.5, (b0[1] + b2[1]) * 0.5, PAL.white, 0.28, "cpencil");
    }
  }

  // --- STEP 4: Front Facets, Translucent Washes, Hopper Terraces & Stipple Shading ---
  for (let fi = 0; fi < frontFaces.length; fi++) {
    let ff = frontFaces[fi];
    let q = ff.pts;
    let [nx, ny, nz] = ff.n;

    // Darkfield lighting physics: oblique light hits side faces strongly; top faces have dark centers and bright rims
    let obliqueLight = sqrt(nx * nx + ny * ny);
    let directional = 0.5 + 0.5 * (nx * -0.7 + ny * -0.7);
    let washCol = directional > 0.55 ? PAL.slateLight : PAL.slateDark;
    let washAlpha = map(obliqueLight, 0, 1, 18, 48) * (directional > 0.6 ? 1.15 : 0.85);

    fillPolyWash(q, washCol, constrain(washAlpha, 14, 58));

    // Fine technical-pen stipple along facet perimeter
    let stipCount = floor(constrain(radius * 1.1, 6, 48));
    stippleQuad(q, stipCount, directional > 0.5 ? PAL.iceBlue : PAL.slateLight, 0.18, true);

    // Subtle directional graphite/white-pencil hatching on steep side facets
    if (obliqueLight > 0.45 && radius > 12) {
      let hCol = directional > 0.52 ? PAL.icePale : PAL.slateLight;
      hatchQuad(q, floor(constrain(radius * 0.3, 3, 10)), hCol, 0.14, "2H", 0.45);
    }

    // HOPPER CRYSTAL STEPPED TERRACES (Signature recessed square funnels of sea salt)
    let isMainHopper = fi === frontFaces.length - 1 || (obliqueLight > 0.5 && hopperSteps >= 3);
    let stepsHere = isMainHopper ? hopperSteps : max(0, hopperSteps - 2);

    if (stepsHere > 0 && radius > 9) {
      // Hopper center shifts slightly opposite to face normal (recessed inward into the cube)
      let fcx = (q[0][0] + q[1][0] + q[2][0] + q[3][0]) * 0.25 - nx * radius * 0.18;
      let fcy = (q[0][1] + q[1][1] + q[2][1] + q[3][1]) * 0.25 - ny * radius * 0.18;

      let prevQ = q;
      for (let s = 1; s <= stepsHere; s++) {
        let t = map(s, 0, stepsHere + 1, 0.0, 0.78);
        let curQ = [
          [lerp(q[0][0], fcx, t), lerp(q[0][1], fcy, t)],
          [lerp(q[1][0], fcx, t), lerp(q[1][1], fcy, t)],
          [lerp(q[2][0], fcx, t), lerp(q[2][1], fcy, t)],
          [lerp(q[3][0], fcx, t), lerp(q[3][1], fcy, t)]
        ];

        // Corner miter lines of the sunken hopper pyramid
        for (let c = 0; c < 4; c++) {
          strokeLine(
            prevQ[c][0],
            prevQ[c][1],
            curQ[c][0],
            curQ[c][1],
            "rotring",
            c === 0 || c === 2 ? PAL.iceBlue : PAL.slateLight,
            0.16
          );
        }

        // Draw the 4 stepped terrace risers with chromatic edge dispersion & white highlights
        for (let e = 0; e < 4; e++) {
          let pA = curQ[e];
          let pB = curQ[(e + 1) % 4];
          let edx = pB[0] - pA[0];
          let edy = pB[1] - pA[1];
          let eAng = atan2(edy, edx);
          let catchLight = cos(eAng - 35) > 0;

          if (catchLight) {
            // Sunlit hopper riser: faint rose madder fringe + crisp white pencil edge
            if (s % 2 === 1 && radius > 16) {
              strokeLine(pA[0] + 0.9, pA[1] + 0.9, pB[0] + 0.9, pB[1] + 0.9, "rotring", PAL.roseMadder, 0.18);
            }
            strokeLine(pA[0], pA[1], pB[0], pB[1], "cpencil", s === 1 ? PAL.white : PAL.icePale, 0.26);
          } else {
            // Shadowed hopper riser: cerulean fringe + technical pen stipple
            if (s % 2 === 0 && radius > 16) {
              strokeLine(pA[0] - 0.9, pA[1] - 0.9, pB[0] - 0.9, pB[1] - 0.9, "rotring", PAL.cerulean, 0.18);
            }
            strokeLine(pA[0], pA[1], pB[0], pB[1], "rotring", PAL.slateLight, 0.2);
          }
        }
        prevQ = curQ;
      }

      // Deep central hopper floor glint
      if (opts.isCenterpiece) {
        stippleQuad(prevQ, 28, PAL.white, 0.22, false);
        strokeLine(prevQ[0][0], prevQ[0][1], prevQ[2][0], prevQ[2][1], "rotring", PAL.ceruleanBright, 0.18);
      }
    }
  }

  // --- STEP 5: Outer Chromatic Fringe & Hairline White-Pencil Cube Edges ---
  let edgeCountMap = new Map();
  for (let ff of frontFaces) {
    for (let k = 0; k < 4; k++) {
      let i1 = ff.idx[k];
      let i2 = ff.idx[(k + 1) % 4];
      let key = min(i1, i2) + "_" + max(i1, i2);
      edgeCountMap.set(key, (edgeCountMap.get(key) || 0) + 1);
    }
  }

  for (let [key, count] of edgeCountMap.entries()) {
    let [i1, i2] = key.split("_").map(Number);
    let p1 = v2d[i1];
    let p2 = v2d[i2];
    let isInteriorRidge = count === 2; // Shared by 2 front faces -> closest optical ridge!

    let dx = p2[0] - p1[0];
    let dy = p2[1] - p1[1];
    let len = sqrt(dx * dx + dy * dy);
    if (len < 0.5) continue;

    // Outward normal from crystal center
    let mx = (p1[0] + p2[0]) * 0.5 - cx;
    let my = (p1[1] + p2[1]) * 0.5 - cy;
    let mLen = sqrt(mx * mx + my * my) || 1;
    let onx = mx / mLen;
    let ony = my / mLen;

    if (!isInteriorRidge) {
      // Silhouette rim: rainbow dispersion fringe (cerulean on NW/NE, rose madder on SE/SW)
      let rimColor = onx + ony < 0 ? PAL.cerulean : PAL.roseMadder;
      let shift = 1.4;
      strokeLine(
        p1[0] + onx * shift,
        p1[1] + ony * shift,
        p2[0] + onx * shift,
        p2[1] + ony * shift,
        "rotring",
        rimColor,
        0.24
      );
      // Secondary softer dispersion glow
      if (radius > 16) {
        let secColor = onx + ony < 0 ? PAL.ceruleanBright : PAL.amberFaint;
        strokeLine(
          p1[0] + onx * 0.7,
          p1[1] + ony * 0.7,
          p2[0] + onx * 0.7,
          p2[1] + ony * 0.7,
          "rotring",
          secColor,
          0.16
        );
      }
      // Crisp outer cube edge
      strokeLine(p1[0], p1[1], p2[0], p2[1], "rotring", PAL.icePale, 0.28);
      strokeLine(p1[0], p1[1], p2[0], p2[1], "cpencil", PAL.white, 0.34);
    } else {
      // Interior front ridge: brightest specular white-pencil highlight
      strokeLine(p1[0] - 0.7, p1[1] - 0.7, p2[0] - 0.7, p2[1] - 0.7, "rotring", PAL.ceruleanBright, 0.2);
      strokeLine(p1[0] + 0.7, p1[1] + 0.7, p2[0] + 0.7, p2[1] + 0.7, "rotring", PAL.roseBright, 0.18);
      strokeLine(p1[0], p1[1], p2[0], p2[1], "rotring", PAL.white, 0.32);
      strokeLine(p1[0], p1[1], p2[0], p2[1], "cpencil", PAL.warmWhite, 0.44);

      // Dense stipple along the ridge for crystalline frost texture
      stippleAlongSegment(p1[0], p1[1], p2[0], p2[1], floor(radius * 0.5), 0.9, PAL.white, 0.22, "rotring");
    }
  }

  // --- STEP 6: Specular Vertex Hotspots & Microscopic Chipped Corners ---
  for (let ff of frontFaces) {
    for (let idx of ff.idx) {
      let vp = v2d[idx];
      stippleDot(vp[0], vp[1], PAL.white, 0.34, "cpencil");
      if (radius > 15 && random() < 0.45) {
        // Tiny microscopic corner fracture facet
        let cAng = atan2(vp[1] - cy, vp[0] - cx) + 90;
        let cLen = random(1.8, 3.4);
        strokeLine(
          vp[0] - cos(cAng) * cLen,
          vp[1] - sin(cAng) * cLen,
          vp[0] + cos(cAng) * cLen,
          vp[1] + sin(cAng) * cLen,
          "cpencil",
          PAL.white,
          0.32
        );
      }
    }
  }
}

// ============================================================================
// 3. HYPERREAL MONOCLINIC SUGAR (SUCROSE) CRYSTAL RENDERER
// ============================================================================

function drawSugarCrystal(cx, cy, len, wid, angle, opts = {}) {
  // Sucrose crystals are monoclinic sphenoidal prisms with asymmetric wedge bevels,
  // flat central pinacoid tables, fine growth striations, and high birefringence.
  let hl = len * 0.5;
  let hw = wid * 0.5;
  let asym = opts.asym || random(-0.12, 0.12); // Monoclinic skew

  function toWorld(lx, ly) {
    let rx = lx * cos(angle) - ly * sin(angle);
    let ry = lx * sin(angle) + ly * cos(angle);
    return [cx + rx, cy + ry];
  }

  // 8-sided outer monoclinic contour in local coordinates
  const outerLocal = [
    [-hl, -hw * 0.28],                        // 0: base left wedge
    [-hl * 0.62, -hw],                        // 1: shoulder bottom-left
    [hl * (0.58 + asym), -hw],                // 2: shoulder top-left
    [hl, -hw * 0.18],                         // 3: tip left bevel
    [hl * 0.92, hw * 0.32],                   // 4: tip right bevel (sphenoid asymmetry)
    [hl * (0.52 - asym), hw],                 // 5: shoulder top-right
    [-hl * 0.66, hw],                         // 6: shoulder bottom-right
    [-hl * 0.95, hw * 0.24]                   // 7: base right wedge
  ];

  // Upper pinacoid table (shifted slightly toward -Y for 3D perspective)
  const topScaleX = 0.58;
  const topScaleY = 0.46;
  const shiftX = hl * 0.04;
  const shiftY = -hw * 0.08;
  const topLocal = outerLocal.map(p => [p[0] * topScaleX + shiftX, p[1] * topScaleY + shiftY]);

  // Refracted bottom pinacoid table (seen through the transparent sucrose prism)
  const botLocal = outerLocal.map(p => [p[0] * 0.52 - shiftX * 1.3, p[1] * 0.42 - shiftY * 1.5]);

  const outerPts = outerLocal.map(p => toWorld(p[0], p[1]));
  const topPts = topLocal.map(p => toWorld(p[0], p[1]));
  const botPts = botLocal.map(p => toWorld(p[0], p[1]));

  // --- STEP 1: Refracted Bottom Facet Ghost Lines & Chromatic Dispersion ---
  for (let i = 0; i < 8; i++) {
    let b1 = botPts[i];
    let b2 = botPts[(i + 1) % 8];
    let o1 = outerPts[i];
    strokeLine(b1[0] - 0.9, b1[1] - 0.9, b2[0] - 0.9, b2[1] - 0.9, "rotring", PAL.ceruleanDeep, 0.17);
    strokeLine(b1[0] + 0.9, b1[1] + 0.9, b2[0] + 0.9, b2[1] + 0.9, "rotring", PAL.roseDeep, 0.17);
    stippleAlongSegment(b1[0], b1[1], b2[0], b2[1], floor(len * 0.18), 0.6, PAL.slateLight, 0.16, "rotring");
    if (i % 2 === 0) {
      stippleAlongSegment(o1[0], o1[1], b1[0], b1[1], 5, 0.5, PAL.slateMid, 0.15, "rotring");
    }
  }

  // --- STEP 2: 8 Bevel Trapezoid Facets (High Birefringence & Specular Planes) ---
  for (let i = 0; i < 8; i++) {
    let ni = (i + 1) % 8;
    let quad = [outerPts[i], outerPts[ni], topPts[ni], topPts[i]];

    // Determine facet orientation relative to condenser light
    let fAng = (angle + i * 45) % 360;
    let isSunlitSide = i === 1 || i === 2;
    let isRoseWedge = i === 3 || i === 4;
    let isCeruleanWedge = i === 7 || i === 0;

    if (isSunlitSide) {
      fillPolyWash(quad, PAL.icePale, 55);
      hatchQuad(quad, floor(constrain(len * 0.22, 4, 14)), PAL.white, 0.18, "cpencil", 0.9);
      stippleQuad(quad, floor(len * 0.35), PAL.white, 0.2, true);
    } else if (isRoseWedge) {
      fillPolyWash(quad, PAL.roseMadder, 34);
      hatchQuad(quad, 5, PAL.roseBright, 0.16, "rotring", 0.75);
      stippleQuad(quad, floor(wid * 0.6), PAL.warmWhite, 0.2, true);
    } else if (isCeruleanWedge) {
      fillPolyWash(quad, PAL.cerulean, 36);
      hatchQuad(quad, 5, PAL.ceruleanBright, 0.16, "rotring", 0.75);
      stippleQuad(quad, floor(wid * 0.6), PAL.icePale, 0.2, true);
    } else {
      fillPolyWash(quad, PAL.slateDark, 42);
      stippleQuad(quad, floor(len * 0.28), PAL.slateLight, 0.17, true);
    }
  }

  // --- STEP 3: Central Top Pinacoid Table, Growth Striations & Internal Cleavage ---
  fillPolyWash(topPts, "#182d4a", 30);

  // Longitudinal growth striations (characteristic fine parallel lines on sucrose prisms)
  let striationCount = floor(constrain(wid * 0.32, 3, 9));
  for (let s = 1; s <= striationCount; s++) {
    let t = s / (striationCount + 1);
    let pStart = lerpPt(
      lerpPt(topPts[0], topPts[7], t),
      lerpPt(topPts[1], topPts[6], t),
      0.35
    );
    let pEnd = lerpPt(
      lerpPt(topPts[3], topPts[4], t),
      lerpPt(topPts[2], topPts[5], t),
      0.35
    );
    let s1 = lerpPt(pStart, pEnd, random(0.05, 0.25));
    let s2 = lerpPt(pStart, pEnd, random(0.75, 0.95));
    strokeLine(
      s1[0],
      s1[1],
      s2[0],
      s2[1],
      "2H",
      s % 2 === 0 ? PAL.iceBlue : PAL.slateLight,
      0.13
    );
  }

  // Internal diagonal conchoidal fracture with chromatic rainbow stipple
  if (len > 22) {
    let f1 = lerpPt(topPts[1], topPts[2], random(0.3, 0.6));
    let f2 = lerpPt(topPts[6], topPts[5], random(0.4, 0.7));
    let fm = [(f1[0] + f2[0]) * 0.5 + random(-3, 3), (f1[1] + f2[1]) * 0.5 + random(-3, 3)];
    strokeSpline([f1, fm, f2], 0.4, "rotring", PAL.cerulean, 0.2);
    strokeSpline(
      [
        [f1[0] + 1.1, f1[1] + 1.1],
        [fm[0] + 1.1, fm[1] + 1.1],
        [f2[0] + 1.1, f2[1] + 1.1]
      ],
      0.4,
      "rotring",
      PAL.roseMadder,
      0.2
    );
    stippleAlongSegment(f1[0], f1[1], f2[0], f2[1], floor(wid * 0.7), 1.2, PAL.white, 0.2, "rotring");
  }

  // --- STEP 4: Rainbow Rim Fringes & Razor-Sharp White-Pencil Facet Ridges ---
  for (let i = 0; i < 8; i++) {
    let ni = (i + 1) % 8;
    let o1 = outerPts[i];
    let o2 = outerPts[ni];
    let t1 = topPts[i];
    let t2 = topPts[ni];

    // Outer chromatic dispersion fringe
    let mx = (o1[0] + o2[0]) * 0.5 - cx;
    let my = (o1[1] + o2[1]) * 0.5 - cy;
    let mLen = sqrt(mx * mx + my * my) || 1;
    let nx = mx / mLen;
    let ny = my / mLen;
    let dispCol = i < 4 ? PAL.cerulean : PAL.roseMadder;

    strokeLine(
      o1[0] + nx * 1.4,
      o1[1] + ny * 1.4,
      o2[0] + nx * 1.4,
      o2[1] + ny * 1.4,
      "rotring",
      dispCol,
      0.24
    );

    // Outer edge
    strokeLine(o1[0], o1[1], o2[0], o2[1], "rotring", PAL.icePale, 0.26);
    if (i <= 4) {
      strokeLine(o1[0], o1[1], o2[0], o2[1], "cpencil", PAL.white, 0.34);
    }

    // Spoke ridge from outer vertex to top pinacoid table vertex
    let spokeBright = i >= 1 && i <= 4;
    if (spokeBright) {
      strokeLine(o1[0] - 0.7, o1[1] - 0.7, t1[0] - 0.7, t1[1] - 0.7, "rotring", PAL.ceruleanBright, 0.18);
      strokeLine(o1[0] + 0.7, o1[1] + 0.7, t1[0] + 0.7, t1[1] + 0.7, "rotring", PAL.roseBright, 0.18);
      strokeLine(o1[0], o1[1], t1[0], t1[1], "cpencil", PAL.white, 0.38);
    } else {
      strokeLine(o1[0], o1[1], t1[0], t1[1], "rotring", PAL. iceBlue, 0.24);
    }

    // Top pinacoid table perimeter ridge (very sharp white pencil)
    strokeLine(t1[0], t1[1], t2[0], t2[1], "rotring", PAL.white, 0.28);
    strokeLine(t1[0], t1[1], t2[0], t2[1], "cpencil", PAL.warmWhite, 0.38);

    // Vertex glint
    stippleDot(t1[0], t1[1], PAL.white, 0.32, "cpencil");
    stippleDot(o1[0], o1[1], PAL.white, 0.26, "cpencil");
  }
}

// ============================================================================
// 4. TINY GLASS SEED BEAD RENDERER (Axial Torus & Radial Barrel Views)
// ============================================================================

function drawSeedBead(cx, cy, r, angle, mode = "axial", tintVariant = 0) {
  // Glass seed beads (rocaille beads) are smooth fire-polished glass toroids
  // with a central perforation hole, internal fiber-optic caustic arcs,
  // chromatic rim fringes, and curved white-pencil window highlights.

  if (mode === "axial") {
    // --- AXIAL / SLIGHTLY TILTED TORUS VIEW ---
    let holeR = r * 0.36;
    let tiltShiftX = cos(angle) * r * 0.12;
    let tiltShiftY = sin(angle) * r * 0.12;
    let hx = cx + tiltShiftX;
    let hy = cy + tiltShiftY;

    // 1. Translucent glass torus wash (sampled as 16-gon ring segments)
    let baseWash =
      tintVariant === 0
        ? "#16355c"
        : tintVariant === 1
        ? "#144978"
        : tintVariant === 2
        ? "#4d1a36"
        : "#243b4f";

    for (let s = 0; s < 12; s++) {
      let a1 = s * 30;
      let a2 = (s + 1) * 30;
      let q = [
        [cx + cos(a1) * r, cy + sin(a1) * r],
        [cx + cos(a2) * r, cy + sin(a2) * r],
        [hx + cos(a2) * holeR, hy + sin(a2) * holeR],
        [hx + cos(a1) * holeR, hy + sin(a1) * holeR]
      ];
      let segLight = 0.5 + 0.5 * cos(a1 - (angle + 180));
      fillPolyWash(q, baseWash, map(segLight, 0, 1, 22, 52));
    }

    // 2. Outer chromatic dispersion fringes (Cerulean & Rose Madder)
    strokeArc(cx, cy, r + 1.3, angle + 100, angle + 280, "rotring", PAL.cerulean, 0.24);
    strokeArc(cx, cy, r + 1.3, angle - 80, angle + 100, "rotring", PAL.roseMadder, 0.24);

    // 3. Internal Caustic Glow on the Opposite Wall of the Glass Torus
    for (let c = 0; c < 4; c++) {
      let cr = lerp(holeR * 1.25, r * 0.82, c / 3);
      let cCol =
        tintVariant === 2
          ? PAL.roseBright
          : tintVariant === 1
          ? PAL.ceruleanBright
          : c % 2 === 0
          ? PAL.cerulean
          : PAL.iceBlue;
      strokeArc(
        cx,
        cy,
        cr,
        angle - 65 + c * 6,
        angle + 65 - c * 6,
        "rotring",
        cCol,
        0.2
      );
    }

    // Stippled caustic focus inside the torus body
    let stCount = floor(constrain(r * 3.2, 14, 55));
    for (let i = 0; i < stCount; i++) {
      let a = random(360);
      let rr = random(holeR * 1.08, r * 0.94);
      let px = cx + cos(a) * rr;
      let py = cy + sin(a) * rr;
      let isCausticSide = cos(a - angle) > 0.2;
      let col = isCausticSide
        ? random() < 0.35
          ? PAL.white
          : tintVariant === 2
          ? PAL.roseBright
          : PAL.ceruleanBright
        : PAL.slateLight;
      stippleDot(px, py, col, isCausticSide ? 0.2 : 0.16, "rotring");
    }

    // 4. Central Perforation Bore (3D cylindrical tunnel inside the hole)
    // Back rim of bore visible inside the hole opening
    strokeArc(
      hx - tiltShiftX * 1.4,
      hy - tiltShiftY * 1.4,
      holeR * 0.92,
      angle + 110,
      angle + 250,
      "rotring",
      PAL.cerulean,
      0.2
    );
    strokeArc(hx, hy, holeR + 0.8, angle - 70, angle + 90, "rotring", PAL.roseMadder, 0.22);
    strokeArc(hx, hy, holeR, 0, 360, "rotring", PAL.iceBlue, 0.26);
    // Sharp white highlight on the inner hole lip catching oblique light
    strokeArc(hx, hy, holeR, angle - 55, angle + 55, "cpencil", PAL.white, 0.38);

    // 5. Outer Bead Rim & Curved Specular Window Highlight
    strokeArc(cx, cy, r, 0, 360, "rotring", PAL.icePale, 0.26);
    strokeArc(cx, cy, r, angle + 125, angle + 245, "cpencil", PAL.white, 0.38);
    // Primary curved specular crescent along the upper glass shoulder
    strokeArc(cx, cy, r * 0.74, angle + 135, angle + 225, "cpencil", PAL.white, 0.44);
    strokeArc(cx, cy, r * 0.64, angle + 145, angle + 210, "cpencil", PAL.warmWhite, 0.34);

    // Microscopic trapped air bubble in the spun glass
    if (r > 7) {
      let ba = angle + 95;
      let bx = cx + cos(ba) * (r * 0.65);
      let by = cy + sin(ba) * (r * 0.65);
      strokeArc(bx, by, r * 0.13, 0, 360, "rotring", PAL.icePale, 0.16);
      stippleDot(bx, by, PAL.white, 0.28, "cpencil");
    }
  } else {
    // --- RADIAL BARREL / PROFILE VIEW (Showing Internal Bore Tunnel) ---
    let blen = r * 1.75; // width of bead barrel
    let bht = r * 1.25;  // height of bead along bore axis
    let hw = blen * 0.5;
    let hh = bht * 0.5;
    let boreW = hw * 0.38;

    function toBead(lx, ly) {
      return [
        cx + lx * cos(angle) - ly * sin(angle),
        cy + lx * sin(angle) + ly * cos(angle)
      ];
    }

    // Rounded barrel silhouette points
    const barrelLocal = [
      [-hw * 0.72, -hh],
      [hw * 0.72, -hh],
      [hw, -hh * 0.45],
      [hw, hh * 0.45],
      [hw * 0.72, hh],
      [-hw * 0.72, hh],
      [-hw, hh * 0.45],
      [-hw, -hh * 0.45]
    ];
    const barrelPts = barrelLocal.map(p => toBead(p[0], p[1]));

    fillPolyWash(barrelPts, tintVariant === 2 ? "#421830" : "#153659", 40);

    // Chromatic fringes on the curved barrel flanks
    let flL1 = toBead(-hw * 0.9, -hh * 0.95);
    let flL2 = toBead(hw * 0.9, -hh * 0.95);
    let flR1 = toBead(-hw * 0.9, hh * 0.95);
    let flR2 = toBead(hw * 0.9, hh * 0.95);
    strokeLine(flL1[0], flL1[1], flL2[0], flL2[1], "rotring", PAL.cerulean, 0.24);
    strokeLine(flR1[0], flR1[1], flR2[0], flR2[1], "rotring", PAL.roseMadder, 0.24);

    // Internal cylindrical perforation bore seen right through the transparent glass!
    let bTop1 = toBead(-hw * 0.85, -boreW);
    let bTop2 = toBead(hw * 0.85, -boreW);
    let bBot1 = toBead(-hw * 0.85, boreW);
    let bBot2 = toBead(hw * 0.85, boreW);

    strokeLine(bTop1[0], bTop1[1], bTop2[0], bTop2[1], "rotring", PAL.ceruleanBright, 0.2);
    strokeLine(bBot1[0], bBot1[1], bBot2[0], bBot2[1], "rotring", PAL.roseBright, 0.2);
    stippleAlongSegment(bTop1[0], bTop1[1], bTop2[0], bTop2[1], 12, 0.6, PAL.white, 0.18, "rotring");
    stippleAlongSegment(bBot1[0], bBot1[1], bBot2[0], bBot2[1], 12, 0.6, PAL.iceBlue, 0.18, "rotring");

    // Curved contour hatching across the barrel
    for (let h = -3; h <= 3; h++) {
      let yOff = (h / 4) * hh * 0.85;
      let p1 = toBead(-hw * 0.65, yOff);
      let p2 = toBead(0, yOff * 1.08);
      let p3 = toBead(hw * 0.65, yOff);
      strokeSpline([p1, p2, p3], 0.5, "2H", h < 0 ? PAL.icePale : PAL.slateLight, 0.15);
    }

    // Outer smooth spline contour of the barrel bead
    for (let i = 0; i < 8; i++) {
      let p1 = barrelPts[i];
      let p2 = barrelPts[(i + 1) % 8];
      let isBright = i <= 3 || i === 7;
      strokeLine(p1[0], p1[1], p2[0], p2[1], "rotring", PAL.icePale, 0.26);
      if (isBright) {
        strokeLine(p1[0], p1[1], p2[0], p2[1], "cpencil", PAL.white, 0.36);
      }
    }

    // Dazzling longitudinal specular highlight strip along the upper glass curve
    let h1 = toBead(-hw * 0.55, -hh * 0.58);
    let h2 = toBead(hw * 0.55, -hh * 0.58);
    strokeLine(h1[0], h1[1], h2[0], h2[1], "cpencil", PAL.white, 0.44);
    stippleAlongSegment(h1[0], h1[1], h2[0], h2[1], 10, 0.8, PAL.white, 0.24, "cpencil");
  }
}

// ============================================================================
// 5. CONCENTRIC RINGS OF THE VICTORIAN ROSETTE
// ============================================================================

function drawColletBeadRing(cx, cy, rRing, count) {
  // Ring 1 (r = 57): 8 Axial Glass Seed Beads + 8 Interstitial Micro-Salt Grains
  for (let i = 0; i < count; i++) {
    let a = i * (360 / count) + random(-0.4, 0.4);
    let r = rRing + random(-0.5, 0.5);
    let x = cx + cos(a) * r;
    let y = cy + sin(a) * r;
    drawSeedBead(x, y, 9.8, a, "axial", i % 3);

    // Interstitial micro-salt cube on the half-angle
    let ha = a + 180 / count;
    let hx = cx + cos(ha) * (rRing + 2);
    let hy = cy + sin(ha) * (rRing + 2);
    drawSaltCrystal(hx, hy, 5.8, ha + 45, 22, -18, {
      hopperSteps: 1,
      cleavageCount: 0,
      inclusions: 0
    });
  }
}

function drawInnerPetalRing(cx, cy, rRing, count) {
  // Ring 2 (r = 108): 8 Primary Monoclinic Sucrose Prisms + 8 Tilted Halite Hopper Cubes
  for (let i = 0; i < count; i++) {
    let a = i * (360 / count) + random(-0.35, 0.35);
    let x = cx + cos(a) * rRing;
    let y = cy + sin(a) * rRing;
    drawSugarCrystal(x, y, 54, 24, a);

    // Alternating tilted sea salt hopper cubes on the 22.5-degree intervals
    let ha = a + 180 / count + random(-0.35, 0.35);
    let hx = cx + cos(ha) * (rRing + 4);
    let hy = cy + sin(ha) * (rRing + 4);
    drawSaltCrystal(hx, hy, 17.5, ha + 15, 28, -22, {
      hopperSteps: 3,
      cleavageCount: 2,
      inclusions: 2
    });
  }
}

function drawBeadNecklaceRing(cx, cy, rRing, count) {
  // Ring 3 (r = 164): 16 Glass Seed Beads (Alternating Axial & Radial Barrel) + 16 Sugar Diamonds
  for (let i = 0; i < count; i++) {
    let a = i * (360 / count) + random(-0.3, 0.3);
    let x = cx + cos(a) * rRing;
    let y = cy + sin(a) * rRing;
    let mode = i % 2 === 0 ? "axial" : "barrel";
    drawSeedBead(x, y, 10.2, mode === "barrel" ? a : a + 90, mode, i % 4);

    // Small tabular sugar diamond between each bead
    let ha = a + 180 / count;
    let sx = cx + cos(ha) * rRing;
    let sy = cy + sin(ha) * rRing;
    drawSugarCrystal(sx, sy, 23, 12.5, ha + 90);
  }
}

function drawMainHaliteRing(cx, cy, rRing, count) {
  // Ring 4 (r = 222): 16 Large 3D Halite Hopper Cubes (Alternating Stepped-Face & Corner-Up Isometric)
  for (let i = 0; i < count; i++) {
    let a = i * (360 / count) + random(-0.3, 0.3);
    let r = rRing + random(-0.6, 0.6);
    let x = cx + cos(a) * r;
    let y = cy + sin(a) * r;

    if (i % 2 === 0) {
      // Flat-tilted cube with deep 4-step hopper cavity facing objective
      drawSaltCrystal(x, y, 23.5, a + 12, 18 + (i % 3) * 4, -15, {
        hopperSteps: 4,
        cleavageCount: 2,
        inclusions: 3
      });
    } else {
      // Corner-up isometric cube (classic 3-rhomb hexagonal silhouette)
      drawSaltCrystal(x, y, 22.5, a + 45, 35, 32, {
        hopperSteps: 3,
        cleavageCount: 2,
        inclusions: 2
      });
    }
  }
}

function drawGrandSugarRing(cx, cy, rRing, count) {
  // Ring 5 (r = 302): 16 Grand Radial Sucrose Prisms + Interstitial Salt Cubes & Twin Bead Satellites
  for (let i = 0; i < count; i++) {
    let a = i * (360 / count) + random(-0.25, 0.25);
    let x = cx + cos(a) * rRing;
    let y = cy + sin(a) * rRing;

    // Grand radial monoclinic sugar crystal
    drawSugarCrystal(x, y, 72, 25, a, { asym: (i % 2 === 0 ? 1 : -1) * 0.09 });

    // Interstitial arrangement on the half-angle (at r = 282 and r = 324)
    let ha = a + 180 / count;

    // Inner medium halite cube at r = 280
    let sx = cx + cos(ha) * 280;
    let sy = cy + sin(ha) * 280;
    drawSaltCrystal(sx, sy, 15.5, ha + 25, 24, -19, {
      hopperSteps: 3,
      cleavageCount: 1,
      inclusions: 2
    });

    // Outer radial glass seed bead pair at r = 322
    let bx = cx + cos(ha) * 322;
    let by = cy + sin(ha) * 322;
    drawSeedBead(bx, by, 9.2, ha, "axial", (i + 1) % 4);
  }
}

function drawCrownRing(cx, cy, rRing, count) {
  // Ring 6 (r = 386): 24-fold Crown alternating Large Halite Hopper Cubes & Beveled Sugar Tablets with Bead Collets
  for (let i = 0; i < count; i++) {
    let a = i * (360 / count) + random(-0.25, 0.25);
    let x = cx + cos(a) * rRing;
    let y = cy + sin(a) * rRing;

    if (i % 2 === 0) {
      // Large 3D Halite Hopper Cube
      drawSaltCrystal(x, y, 22, a + 20, 26, -24, {
        hopperSteps: 4,
        cleavageCount: 2,
        inclusions: 2
      });
    } else {
      // Broad Monoclinic Sugar Tablet flanked by a tiny axial seed bead
      drawSugarCrystal(x, y, 44, 24, a);
      let bx = cx + cos(a) * (rRing - 33);
      let by = cy + sin(a) * (rRing - 33);
      drawSeedBead(bx, by, 7.2, a, "axial", i % 3);
