// ============================================================================
// SAFE GEOMETRY & SPLINE HELPERS
// ============================================================================

function safeSpline(pts, curvature = 0.5) {
  if (!pts || pts.length < 2) return;
  let clean = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    let prev = clean[clean.length - 1];
    let dx = pts[i][0] - prev[0];
    let dy = pts[i][1] - prev[1];
    if (dx * dx + dy * dy > 2.25) {
      clean.push(pts[i]);
    }
  }
  if (clean.length >= 3) {
    brush.spline(clean, curvature);
  } else if (clean.length === 2) {
    brush.line(clean[0][0], clean[0][1], clean[1][0], clean[1][1]);
  }
}

// ============================================================================
// 3D LOWRIDER HOOD OPTICAL & SURFACE MODEL
// ============================================================================

// Perspective spread widens as the hood sweeps toward the viewer at the bottom
function getSpread(y) {
  return 1.0 + (y - 550) * 0.00028;
}

// Computes virtual reflected sky coordinates and surface lighting for any point (x, y) on the hood
function getHoodOptics(x, y) {
  let sp = getSpread(y);
  let dx = x - 600;
  let u = dx / (600 * sp);
  let absU = Math.abs(u);
  let signU = dx >= 0 ? 1 : -1;

  // Central hood spine pinch (creates the iconic V-cusp along x = 600)
  let spinePinch = -88 * Math.exp(-Math.pow(absU / 0.055, 1.8));

  // Main convex dome curvature across the twin hood crowns
  let domeCurve = 250 * Math.pow(absU, 1.85);

  // Sculpted side cove / feature crease at |u| ≈ 0.58 (classic 60s lowrider sheet metal S-bend)
  let creaseDist = (absU - 0.585) / 0.058;
  let creaseWave = 72 * creaseDist * Math.exp(-creaseDist * creaseDist);

  // Outer fender drop-off beyond |u| > 0.65
  let outerRoll = absU > 0.63 ? 310 * Math.pow(absU - 0.63, 1.6) : 0;

  // Slight diagonal cruising tilt in the reflected sky
  let skyTilt = dx * 0.085;

  // Virtual elevation in the reflected sky (0 = high cool twilight zenith, 680 = dusk-orange horizon, 1000+ = deep lower shadow)
  let reflY = y * 0.78 + 75 + spinePinch + domeCurve + creaseWave + outerRoll + skyTilt;
  let reflX = x + signU * (28 * Math.exp(-Math.pow(absU / 0.07, 2)) + 42 * Math.exp(-creaseDist * creaseDist));

  // Specular ridge factor for longitudinal sheet-metal highlights
  let spineHighlight = Math.exp(-Math.pow((u + 0.012) / 0.016, 2)) - 0.7 * Math.exp(-Math.pow((u - 0.014) / 0.018, 2));
  let creaseHighlight = Math.exp(-Math.pow((absU - 0.572) / 0.022, 2)) - 0.65 * Math.exp(-Math.pow((absU - 0.608) / 0.025, 2));

  return {
    u,
    absU,
    signU,
    reflX,
    reflY,
    spineHighlight,
    creaseHighlight
  };
}

// Warps a world-space reflection point (wx, wy) through the hood's curved mirror surface
function warpReflectionPt(wx, wy, pressure = 1.0) {
  let sp = getSpread(wy);
  let dx = wx - 600;
  let u = dx / (600 * sp);
  let absU = Math.abs(u);
  let signU = dx >= 0 ? 1 : -1;

  // Inverse optical warp so straight sky features & palm fronds bend across the hood ridges
  let spineCusp = 64 * Math.exp(-Math.pow(absU / 0.065, 1.7));
  let domeArc = -155 * Math.pow(absU, 1.8);
  let creaseDist = (absU - 0.585) / 0.058;
  let creaseKink = -54 * creaseDist * Math.exp(-creaseDist * creaseDist);
  let outerDrop = absU > 0.63 ? -170 * Math.pow(absU - 0.63, 1.5) : 0;

  let xOut = wx - signU * (18 * Math.exp(-Math.pow(absU / 0.08, 2)) + 28 * creaseDist * Math.exp(-creaseDist * creaseDist));
  let yOut = wy + spineCusp + domeArc + creaseKink + outerDrop - dx * 0.065;

  return [xOut, yOut, pressure];
}

// Maps color from virtual reflected sky altitude + candy-apple red lacquer absorption
function getLacquerColor(reflY, absU, spineH, creaseH) {
  // Cool palette foundation transitioning through candy-apple red into the warped dusk-orange horizon
  let stops = [
    { y: 120, c: [12, 18, 42] },    // Deep midnight cobalt zenith
    { y: 260, c: [26, 42, 82] },    // Cool twilight slate-indigo
    { y: 370, c: [58, 46, 102] },   // Cool violet-slate transition
    { y: 455, c: [110, 20, 68] },   // Cool magenta-berry lacquer
    { y: 535, c: [178, 20, 56] },   // Deep Candy-Apple Red
    { y: 605, c: [224, 38, 62] },   // Luminous Candy-Apple Red
    { y: 665, c: [242, 96, 56] },   // Glowing Dusk-Orange upper band
    { y: 715, c: [255, 158, 78] },  // Molten Dusk-Orange / Amber core
    { y: 760, c: [232, 74, 58] },   // Dusk-Coral lower horizon
    { y: 825, c: [168, 18, 52] },   // Rich Kandy Cherry return
    { y: 920, c: [88, 12, 48] },    // Deep Burgundy-Plum
    { y: 1040, c: [38, 10, 42] },   // Cool Midnight Eggplant
    { y: 1200, c: [16, 8, 28] }     // Deepest Cool Obsidian-Violet
  ];

  let r = stops[stops.length - 1].c[0];
  let g = stops[stops.length - 1].c[1];
  let b = stops[stops.length - 1].c[2];

  if (reflY <= stops[0].y) {
    r = stops[0].c[0];
    g = stops[0].c[1];
    b = stops[0].c[2];
  } else {
    for (let i = 0; i < stops.length - 1; i++) {
      if (reflY >= stops[i].y && reflY <= stops[i + 1].y) {
        let t = (reflY - stops[i].y) / (stops[i + 1].y - stops[i].y);
        t = t * t * (3 - 2 * t);
        r = lerp(stops[i].c[0], stops[i + 1].c[0], t);
        g = lerp(stops[i].c[1], stops[i + 1].c[1], t);
        b = lerp(stops[i].c[2], stops[i + 1].c[2], t);
        break;
      }
    }
  }

  // Cool twilight atmospheric shift toward outer fenders
  if (absU > 0.45) {
    let coolFactor = constrain((absU - 0.45) / 0.55, 0, 1);
    r = lerp(r, 22, coolFactor * 0.55);
    g = lerp(g, 28, coolFactor * 0.45);
    b = lerp(b, 68, coolFactor * 0.4);
  }

  // Sheet-metal ridge highlights and shadow bevels
  let ridgeBoost = spineH * 42 + creaseH * 36;
  r = constrain(r + ridgeBoost * 1.1, 8, 255);
  g = constrain(g + ridgeBoost * 1.15, 6, 255);
  b = constrain(b + ridgeBoost * 1.45, 14, 255);

  return color(r, g, b);
}

// ============================================================================
// MAIN RENDER PIPELINE
// ============================================================================

function draw() {
  translate(-width / 2, -height / 2);
  background("#0d0718");

  // 1. Base Underpainting: Warped Contour Washes
  drawBaseUnderpainting();

  // 2. First Lacquer Pass & Contour Glaze Ribbons
  drawLacquerGlazePass(1);

  // 3. Dense Silver & Ruby Metalflake Speckles (Under Deep Lacquer)
  drawMetalflakeLayer(1);

  // 4. Translucent Kandy-Apple Red & Dusk-Orange Over-Glaze
  drawLacquerGlazePass(2);

  // 5. Warped Mirror Reflection of Palm Trees & Feathery Fronds
  drawWarpedPalmReflections();

  // 6. Surface Clearcoat Sheen, Ridge Speculars & Top Micro-Flake Glints
  drawClearcoatAndRidgeSheen();
  drawMetalflakeLayer(2);

  // 7. Hand-Pulled Pinstripes in Cream & Gold Leaf (Single-Pass Pen Lines)
  drawLowriderPinstriping();

  // 8. Glinting Chrome Hood Ornament at Top Center
  drawChromeHoodOrnament();

  noLoop();
}

// ============================================================================
// LAYER 1: BASE UNDERPAINTING WASHES
// ============================================================================

function drawBaseUnderpainting() {
  brush.noStroke();
  brush.noHatch();

  // Build warped horizontal contour bands from top to bottom
  let bandStep = 36;
  for (let wy = -80; wy <= 1320; wy += bandStep) {
    let optMid = getHoodOptics(600, constrain(wy, 0, 1200));
    let col = getLacquerColor(wy * 0.82 + 120, 0.22, 0, 0);

    brush.wash(col, 195);
    brush.beginShape(0.35);
    for (let wx = -40; wx <= 1240; wx += 40) {
      let p = warpReflectionPt(wx, wy);
      brush.vertex(p[0], p[1]);
    }
    for (let wx = 1240; wx >= -40; wx -= 40) {
      let p = warpReflectionPt(wx, wy + bandStep + 28);
      brush.vertex(p[0], p[1]);
    }
    brush.endShape(true);
  }
  brush.noWash();

  // Soft watercolor-style bleed bands for the glowing dusk-orange horizon & cool indigo zenith
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.35, 0.15);

  let accentBands = [
    { wy: 190, h: 110, col: "#182952", op: 95 },
    { wy: 320, h: 95,  col: "#2d3e75", op: 85 },
    { wy: 470, h: 90,  col: "#8c1444", op: 95 },
    { wy: 575, h: 85,  col: "#cf1d3e", op: 110 },
    { wy: 650, h: 75,  col: "#ed6038", op: 125 },
    { wy: 695, h: 55,  col: "#ff9e54", op: 130 },
    { wy: 755, h: 80,  col: "#bd183b", op: 105 },
    { wy: 880, h: 120, col: "#4a0b2e", op: 100 }
  ];

  for (let b of accentBands) {
    brush.fill(b.col, b.op);
    brush.beginShape(0.4);
    for (let wx = -20; wx <= 1220; wx += 45) {
      let p = warpReflectionPt(wx, b.wy);
      brush.vertex(p[0], p[1]);
    }
    for (let wx = 1220; wx >= -20; wx -= 45) {
      let p = warpReflectionPt(wx, b.wy + b.h);
      brush.vertex(p[0], p[1]);
    }
    brush.endShape(true);
  }
  brush.noFill();
}

// ============================================================================
// LAYER 2 & 4: CONTOUR LACQUER GLAZES
// ============================================================================

function drawLacquerGlazePass(passNum) {
  let yStep = passNum === 1 ? 11 : 16;
  let brushName = passNum === 1 ? "lacquer_wide" : "lacquer_blend";

  for (let wy = -60; wy <= 1340; wy += yStep) {
    // Split across left and right hood halves so strokes respect the central spine cusp
    for (let side = -1; side <= 1; side += 2) {
      let segments = 3;
      for (let s = 0; s < segments; s++) {
        let xStart = side === -1 ? 600 - s * 205 : 600 + s * 205;
        let xEnd = side === -1 ? 600 - (s + 1) * 205 - 20 : 600 + (s + 1) * 205 + 20;
        let xMid = (xStart + xEnd) * 0.5;

        let pMid = warpReflectionPt(xMid, wy);
        let opt = getHoodOptics(pMid[0], pMid[1]);
        let col = getLacquerColor(opt.reflY, opt.absU, opt.spineHighlight, opt.creaseHighlight);

        let pts = [];
        let steps = 7;
        for (let i = 0; i <= steps; i++) {
          let t = i / steps;
          let wx = lerp(xStart, xEnd, t);
          let wyJitter = wy + Math.sin(t * 180) * 3;
          let wp = warpReflectionPt(wx, wyJitter, 0.5 + 0.7 * Math.sin(t * 180));
          pts.push(wp);
        }

        let wMult = passNum === 1 ? random(0.85, 1.25) : random(0.7, 1.1);
        brush.set(brushName, col, wMult);
        safeSpline(pts, 0.5);
      }
    }
  }
}

// ============================================================================
// LAYER 3 & 6: SILVER & RUBY METALFLAKE SPECKLES
// ============================================================================

function drawMetalflakeLayer(passNum) {
  // Pass 1: Heavy base silver, cool ice-blue, ruby & amber metalflake under the candy glaze
  // Pass 2: Fine pinpoint diamond-silver, crimson & gold sparkles catching the top light
  let rowStep = passNum === 1 ? 14 : 22;

  for (let y = 40; y < 1190; y += rowStep) {
    for (let x = 25; x < 1175; x += random(28, 48)) {
      let opt = getHoodOptics(x, y);

      // Determine local flake color palette from the hood's optical zone
      let flakeCol;
      let rVal = random();

      if (opt.reflY > 560 && opt.reflY < 775) {
        // Hot Candy-Apple Red & Dusk-Orange horizon zone: brilliant silver, champagne gold, ruby-pink
        if (rVal < 0.38) flakeCol = "#e8f2ff";
        else if (rVal < 0.65) flakeCol = "#ffc285";
        else if (rVal < 0.85) flakeCol = "#ff4d6d";
        else flakeCol = "#ffffff";
      } else if (opt.reflY <= 440) {
        // Cool twilight sky reflection zone: icy silver-blue, cool cyan-silver, lavender-silver
        if (rVal < 0.45) flakeCol = "#9bb8e8";
        else if (rVal < 0.78) flakeCol = "#d0e4ff";
        else if (rVal < 0.92) flakeCol = "#7a8ec7";
        else flakeCol = "#f0f7ff";
      } else {
        // Deep Kandy Apple Red & Cool Plum zone: sterling silver, crimson-rose, cool steel-blue
        if (rVal < 0.35) flakeCol = "#c2d6f5";
        else if (rVal < 0.68) flakeCol = "#ff3358";
        else if (rVal < 0.88) flakeCol = "#9e2456";
        else flakeCol = "#e6f0ff";
      }

      let bName = passNum === 1 ? (random() < 0.55 ? "flake_coarse" : "flake_micro") : "flake_micro";
      let weight = passNum === 1 ? random(0.8, 1.35) : random(0.55, 0.95);

      brush.set(bName, flakeCol, weight);

      // Short contour-following spray burst
      let span = random(24, 52) * opt.signU;
      let p1 = warpReflectionPt(x, y, 0.6);
      let p2 = warpReflectionPt(x + span * 0.5, y + random(-3, 3), 1.1);
      let p3 = warpReflectionPt(x + span, y + random(-4, 4), 0.6);
      safeSpline([p1, p2, p3], 0.4);
    }
  }
}

// ============================================================================
// LAYER 5: WARPED MIRROR REFLECTION OF PALM FRONDS & TRUNKS
// ============================================================================

function drawWarpedPalmReflections() {
  // Subtle distant dusk cloud wisps warped in the upper-mid reflection before the palms
  let cloudWisps = [
    { x1: 120, x2: 560, wy: 635, col: "#ff8c52", w: 0.65 },
    { x1: 630, x2: 1090, wy: 650, col: "#ffa866", w: 0.7 },
    { x1: 180, x2: 540, wy: 415, col: "#425c96", w: 0.55 },
    { x1: 650, x2: 1040, wy: 390, col: "#385085", w: 0.55 }
  ];

  for (let cw of cloudWisps) {
    let pts = [];
    for (let i = 0; i <= 10; i++) {
      let t = i / 10;
      let wx = lerp(cw.x1, cw.x2, t);
      let wy = cw.wy + Math.sin(t * 360) * 8;
      pts.push(warpReflectionPt(wx, wy, Math.sin(t * 180) * 1.1));
    }
    brush.set("lacquer_blend", cw.col, cw.w);
    safeSpline(pts, 0.5);
  }

  // Define 3 California fan/queen palms in reflection space that warp across the hood ridges:
  // 1) Hero Right-Center Palm (fronds sweep across the central spine x = 600 and dusk-orange sky)
  // 2) Tall Left-Dome Palm (fronds sweep across the left S-crease and upper cool-to-candy sky)
  // 3) Lower Horizon Silhouette Palm on the right shoulder
  let palms = [
    {
      crownX: 775,
      crownY: 545,
      trunkBaseX: 965,
      trunkBaseY: 985,
      trunkCtrlX: 830,
      trunkCtrlY: 770,
      trunkWidth: 1.5,
      frondCount: 15,
      scale: 1.08
    },
    {
      crownX: 355,
      crownY: 445,
      trunkBaseX: 145,
      trunkBaseY: 910,
      trunkCtrlX: 285,
      trunkCtrlY: 675,
      trunkWidth: 1.25,
      frondCount: 14,
      scale: 0.94
    },
    {
      crownX: 1035,
      crownY: 685,
      trunkBaseX: 1165,
      trunkBaseY: 1040,
      trunkCtrlX: 1095,
      trunkCtrlY: 855,
      trunkWidth: 1.0,
      frondCount: 10,
      scale: 0.72
    }
  ];

  for (let palm of palms) {
    // Draw warped palm trunk with dark lacquer core + crimson/amber horizon rim-glow
    drawWarpedPalmTrunk(palm);

    // Draw radiating, drooping palm fronds with dense individual leaflets
    for (let f = 0; f < palm.frondCount; f++) {
      let frac = f / (palm.frondCount - 1);
      // Fan angles from -165 deg (left-drooping) through -90 (upward) to +25 deg (right-drooping)
      let baseAngle = lerp(-162, 22, frac) + random(-5, 5);
      let frondLen = random(185, 295) * palm.scale * (1.0 - 0.18 * Math.abs(frac - 0.5));
      let droop = random(55, 115) * palm.scale;

      drawWarpedFrond(palm.crownX, palm.crownY, baseAngle, frondLen, droop);
    }
  }

  // Glaze a thin veil of candy-red & cool twilight lacquer sheen over the palms
  // so they sit physically INSIDE the mirror paint depth rather than on top
  for (let wy = 340; wy <= 880; wy += 32) {
    for (let side = -1; side <= 1; side += 2) {
      let pts = [];
      for (let i = 0; i <= 8; i++) {
        let t = i / 8;
        let wx = side === -1 ? lerp(80, 595, t) : lerp(605, 1120, t);
        pts.push(warpReflectionPt(wx, wy, 0.35 + 0.5 * Math.sin(t * 180)));
      }
      let col = wy > 580 && wy < 760 ? "#d92b38" : (wy < 460 ? "#243766" : "#8c1138");
      brush.set("lacquer_blend", col, 0.42);
      safeSpline(pts, 0.5);
    }
  }
}

function drawWarpedPalmTrunk(palm) {
  let steps = 22;
  let rimPts = [];
  let corePts = [];

  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let inv = 1 - t;
    let wx = inv * inv * palm.trunkBaseX + 2 * inv * t * palm.trunkCtrlX + t * t * palm.crownX;
    let wy = inv * inv * palm.trunkBaseY + 2 * inv * t * palm.trunkCtrlY + t * t * palm.crownY;
    let p = lerp(1.5, 0.75, t) * palm.trunkWidth;

    rimPts.push(warpReflectionPt(wx + 4, wy, p * 1.15));
    corePts.push(warpReflectionPt(wx, wy, p));
  }

  // Warm crimson-amber optical bleed around trunk silhouette
  brush.set("palm_frond", "#7a112c", 1.5 * palm.trunkWidth);
  safeSpline(rimPts, 0.5);

  // Deep cool oxblood-indigo silhouette core
  brush.set("palm_frond", "#14071c", 1.35 * palm.trunkWidth);
  safeSpline(corePts, 0.5);

  // Horizontal bark ring notches warped along trunk
  for (let i = 2; i < steps - 1; i += 2) {
    let t = i / steps;
    let inv = 1 - t;
    let wx = inv * inv * palm.trunkBaseX + 2 * inv * t * palm.trunkCtrlX + t * t * palm.crownX;
    let wy = inv * inv * palm.trunkBaseY + 2 * inv * t * palm.trunkCtrlY + t * t * palm.crownY;
    let wSpan = lerp(12, 6, t) * palm.trunkWidth;
    let p1 = warpReflectionPt(wx - wSpan, wy - 2, 0.5);
    let p2 = warpReflectionPt(wx, wy + 1, 1.0);
    let p3 = warpReflectionPt(wx + wSpan, wy - 2, 0.5);
    brush.set("palm_frond", "#240929", 0.65);
    safeSpline([p1, p2, p3], 0.4);
  }
}

function drawWarpedFrond(cx, cy, angleDeg, len, droop) {
  // Build the curved rachis (central stem of the palm frond) in reflection coordinates
  let spineSteps = 16;
  let spineWorld = [];
  let spineWarped = [];
  let spineRimWarped = [];

  let endX = cx + cos(angleDeg) * len;
  let endY = cy + sin(angleDeg) * len + droop;
  let ctrlX = cx + cos(angleDeg) * (len * 0.55);
  let ctrlY = cy + sin(angleDeg) * (len * 0.55) + droop * 0.22;

  for (let i = 0; i <= spineSteps; i++) {
    let t = i / spineSteps;
    let inv = 1 - t;
    let wx = inv * inv * cx + 2 * inv * t * ctrlX + t * t * endX;
    let wy = inv * inv * cy + 2 * inv * t * ctrlY + t * t * endY;
    spineWorld.push({ wx, wy, t });
    spineWarped.push(warpReflectionPt(wx, wy, lerp(1.15, 0.15, t)));
    spineRimWarped.push(warpReflectionPt(wx, wy + 2.5, lerp(1.25, 0.2, t)));
  }

  // Subtle crimson-orange optical bloom along the rachis
  brush.set("palm_frond", "#6e102b", 0.9);
  safeSpline(spineRimWarped, 0.5);

  // Dark cool burgundy-indigo rachis stem
  brush.set("palm_frond", "#14061b", 0.8);
  safeSpline(spineWarped, 0.5);

  // Draw dense, feathery tapering leaflets along both sides of the frond rachis
  let leafletCount = 34;
  for (let i = 2; i < leafletCount; i++) {
    let t = i / leafletCount;
    let inv = 1 - t;
    let bx = inv * inv * cx + 2 * inv * t * ctrlX + t * t * endX;
    let by = inv * inv * cy + 2 * inv * t * ctrlY + t * t * endY;

    // Tangent direction of the rachis at parameter t
    let tx = 2 * inv * (ctrlX - cx) + 2 * t * (endX - ctrlX);
    let ty = 2 * inv * (ctrlY - cy) + 2 * t * (endY - ctrlY);
    let tangAngle = atan2(ty, tx);

    let env = Math.sin(pow(t, 0.75) * 180);
    let leafLen = (26 + 52 * env) * (1.0 - 0.25 * t);

    for (let side = -1; side <= 1; side += 2) {
      // Leaflets sweep forward toward the tip and hang downward with gravity
      let lAngle = tangAngle + side * lerp(62, 24, t) + random(-6, 6);
      let tipX = bx + cos(lAngle) * leafLen;
      let tipY = by + sin(lAngle) * leafLen + leafLen * 0.34;
      let midX = bx + cos(lAngle) * (leafLen * 0.52);
      let midY = by + sin(lAngle) * (leafLen * 0.52) + leafLen * 0.12;

      let p0 = warpReflectionPt(bx, by, 0.85);
      let p1 = warpReflectionPt(midX, midY, 0.65);
      let p2 = warpReflectionPt(tipX, tipY, 0.12);

      // Sample local reflection altitude to tint the leaflet silhouette naturally
      let opt = getHoodOptics(p1[0], p1[1]);
      let leafCol = opt.reflY > 560 && opt.reflY < 760
        ? (random() < 0.7 ? "#1a071e" : "#3b0a24")
        : (opt.reflY < 450 ? "#0f1026" : "#14061a");

      brush.set("palm_frond", leafCol, random(0.45, 0.72));
      safeSpline([p0, p1, p2], 0.45);
    }
  }
}

