function drawClearcoatAndRidgeSheen() {
  // 1. Sharp longitudinal highlight & shadow bevel along the central hood spine (x = 600)
  for (let pass = 0; pass < 3; pass++) {
    let ptsLight = [];
    let ptsCore = [];
    let ptsShadow = [];

    for (let y = 265; y <= 1190; y += 28) {
      let t = (y - 265) / 925;
      let p = 0.5 + 0.7 * Math.sin(t * 180);
      ptsLight.push([594 - pass * 2.5, y, p]);
      ptsCore.push([598, y, p * 0.9]);
      ptsShadow.push([604 + pass * 2.2, y, p]);
    }

    brush.set("lacquer_sheen", pass === 0 ? "#ffd6e0" : "#ff4d6d", 0.55 - pass * 0.12);
    safeSpline(ptsLight, 0.5);

    if (pass === 0) {
      brush.set("pinstripe_mack", "#fff0f5", 0.5);
      safeSpline(ptsCore, 0.5);
    }

    brush.set("lacquer_sheen", "#1c0519", 0.65 - pass * 0.15);
    safeSpline(ptsShadow, 0.5);
  }

  // 2. Sculpted S-crease longitudinal highlights along the left and right hood shoulders (|u| ≈ 0.58)
  for (let side = -1; side <= 1; side += 2) {
    let ridgeGlowPts = [];
    let ridgeCorePts = [];
    let ridgeDarkPts = [];

    for (let y = 120; y <= 1190; y += 30) {
      let sp = getSpread(y);
      let xRidge = 600 + side * (0.575 * 600 * sp);
      let xDark = 600 + side * (0.608 * 600 * sp);
      let p = 0.4 + 0.8 * Math.sin(((y - 120) / 1070) * 180);

      ridgeGlowPts.push([xRidge - side * 5, y, p]);
      ridgeCorePts.push([xRidge, y, p * 0.8]);
      ridgeDarkPts.push([xDark, y, p]);
    }

    // Cool sky-blue & candy-pink reflection along the sculpted feature line
    brush.set("lacquer_sheen", "#78a2d9", 0.85);
    safeSpline(ridgeGlowPts, 0.5);

    brush.set("lacquer_sheen", "#d8ecff", 0.45);
    safeSpline(ridgeCorePts, 0.5);

    brush.set("lacquer_sheen", "#120824", 0.95);
    safeSpline(ridgeDarkPts, 0.5);
  }

  // 3. Glassy dusk-orange & cool cyan-white horizon gleams on the twin hood crowns
  for (let side = -1; side <= 1; side += 2) {
    for (let k = 0; k < 5; k++) {
      let wy = 655 + k * 14;
      let pts = [];
      for (let i = 0; i <= 8; i++) {
        let t = i / 8;
        let wx = 600 + side * lerp(45, 310, t);
        pts.push(warpReflectionPt(wx, wy, Math.sin(t * 180) * 1.15));
      }
      brush.set("lacquer_sheen", k === 2 ? "#fff2d6" : "#ffae66", k === 2 ? 0.65 : 0.45);
      safeSpline(pts, 0.5);
    }
  }
}

