// Maps symmetrical pinstriping coordinates (dx from center 600, y) onto the 3D hood surface
function pinPt(dx, y, pressure = 1.0) {
  let sp = getSpread(y);
  let x = 600 + dx * sp;
  let u = Math.abs(dx) / 600;
  // Subtle physical camber of the hood surface
  let yCamber = y - 14 * Math.sin(constrain(u / 0.6, 0, 1) * 180) + 6 * Math.exp(-Math.pow(u / 0.04, 2));
  return [x, yCamber, pressure];
}

// Renders a crisp, single-pass mirrored pinstripe spline with subtle lacquer drop-shadow
function drawMirroredPinstripe(ctrlPts, col, weight = 0.85, curvature = 0.55) {
  for (let side = -1; side <= 1; side += 2) {
    let shadowPts = [];
    let mainPts = [];

    for (let pt of ctrlPts) {
      let dx = pt[0] * side;
      let y = pt[1];
      let p = pt[2] !== undefined ? pt[2] : 1.0;
      let mapped = pinPt(dx, y, p);
      mainPts.push(mapped);
      shadowPts.push([mapped[0] + 1.6, mapped[1] + 2.2, p]);
    }

    // Crisp dark oxblood drop-shadow under the enamel line
    brush.set("pinstripe_mack", "#1a0412", weight * 0.82);
    safeSpline(shadowPts, curvature);

    // Single-pass Mack pinstripe stroke
    brush.set("pinstripe_mack", col, weight);
    safeSpline(mainPts, curvature);
  }
}

// Renders a single-pass tapering teardrop (dagger stroke) in cream and/or gold leaf
function drawMirroredTeardrop(dxStart, yStart, dxEnd, yEnd, curveBulge, maxWeight, isGold = false, mirrored = true) {
  let sides = mirrored ? [-1, 1] : [1];
  let steps = 14;

  for (let side of sides) {
    let sx0 = dxStart * side;
    let sy0 = yStart;
    let sx1 = dxEnd * side;
    let sy1 = yEnd;
    let cx = (sx0 + sx1) * 0.5 + curveBulge * side;
    let cy = (sy0 + sy1) * 0.5;

    let shadowPts = [];
    let mainPts = [];
    let highlightPts = [];

    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let inv = 1 - t;
      let dx = inv * inv * sx0 + 2 * inv * t * cx + t * t * sx1;
      let y = inv * inv * sy0 + 2 * inv * t * cy + t * t * sy1;

      // Authentic Mack-brush dagger pressure profile: swells rapidly to belly at t = 0.24, then tapers to needle tip
      let p;
      if (t < 0.24) {
        p = lerp(0.32, 1.85, Math.sin((t / 0.24) * 90));
      } else {
        p = lerp(1.85, 0.08, Math.pow((t - 0.24) / 0.76, 0.82));
      }

      let mapped = pinPt(dx, y, p);
      mainPts.push(mapped);
      shadowPts.push([mapped[0] + 1.5, mapped[1] + 2.0, p]);
      if (t > 0.08 && t < 0.78) {
        highlightPts.push([mapped[0] - 0.4, mapped[1] - 0.4, p * 0.52]);
      }
    }

    // Shadow bevel
    brush.set("pinstripe_mack", "#1a0412", maxWeight * 0.85);
    safeSpline(shadowPts, 0.5);

    if (isGold) {
      // Rich 23k Gold Leaf base pass + bright burnished gold leaf highlight core
      brush.set("pinstripe_mack", "#c99228", maxWeight * 1.05);
      safeSpline(mainPts, 0.5);

      brush.set("pinstripe_mack", "#ffe382", maxWeight * 0.62);
      safeSpline(highlightPts, 0.5);
    } else {
      // Vintage Warm Cream enamel pass + ivory specular core
      brush.set("pinstripe_mack", "#f5e6c8", maxWeight);
      safeSpline(mainPts, 0.5);

      brush.set("pinstripe_mack", "#fffdf7", maxWeight * 0.5);
      safeSpline(highlightPts, 0.5);
    }
  }
}

// Renders a smooth single-pass mirrored volute curl / scroll
function drawMirroredCurl(cx, cy, rStart, rEnd, degStart, degEnd, col, weight = 0.78) {
  let steps = 22;
  let pts = [];
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let ang = lerp(degStart, degEnd, t);
    let r = lerp(rStart, rEnd, t);
    let dx = cx + cos(ang) * r;
    let y = cy + sin(ang) * r * 0.92;
    let p = lerp(1.15, 0.18, Math.pow(t, 0.85));
    pts.push([dx, y, p]);
  }
  drawMirroredPinstripe(pts, col, weight, 0.55);
}

