// ============================================================================
// CORE GEOMETRY & RENDERING HELPERS
// ============================================================================

function multiLerpColor(stops, t) {
  t = constrain(t, 0, 1);
  let n = stops.length - 1;
  if (n <= 0) return color(stops[0]);
  let idx = floor(t * n);
  if (idx >= n) return color(stops[n]);
  let f = t * n - idx;
  return lerpColor(color(stops[idx]), color(stops[idx + 1]), f);
}

function washPoly(pts, col, opacity = 225, strokeCol = null, strokeW = 0.4, strokeBrush = "pen") {
  if (!pts || pts.length < 3) return;
  brush.noFill();
  brush.noHatch();
  brush.wash(col, opacity);
  if (strokeCol) {
    brush.set(strokeBrush, strokeCol, strokeW);
  } else {
    brush.noStroke();
  }
  brush.beginShape(0);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noWash();
}

function strokePoly(pts, closeShape, brushName, col, weight, curvature = 0) {
  if (!pts || pts.length < 2) return;
  let clean = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    let dx = pts[i][0] - clean[clean.length - 1][0];
    let dy = pts[i][1] - clean[clean.length - 1][1];
    if (dx * dx + dy * dy > 1.2) clean.push(pts[i]);
  }
  if (clean.length < 2) return;
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set(brushName, col, weight);
  if (clean.length === 2) {
    brush.line(clean[0][0], clean[0][1], clean[1][0], clean[1][1]);
    return;
  }
  brush.beginShape(curvature);
  for (let i = 0; i < clean.length; i++) {
    brush.vertex(clean[i][0], clean[i][1]);
  }
  brush.endShape(closeShape);
}

// Smooth graded marker quad: interpolates between edge (p0->p3) and edge (p1->p2)
function gradedQuad(p0, p1, p2, p3, steps, colorStops, brushName = "glaze", weight = 0.9, baseWashCol = null, baseOpacity = 235) {
  if (baseWashCol) {
    washPoly([p0, p1, p2, p3], baseWashCol, baseOpacity);
  }
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  for (let i = 0; i <= steps; i++) {
    let t = i / max(1, steps);
    let ax = lerp(p0[0], p3[0], t);
    let ay = lerp(p0[1], p3[1], t);
    let bx = lerp(p1[0], p2[0], t);
    let by = lerp(p1[1], p2[1], t);
    if (dist(ax, ay, bx, by) > 0.8) {
      let c = multiLerpColor(colorStops, t);
      brush.set(brushName, c, weight);
      brush.line(ax, ay, bx, by);
    }
  }
}

function evalCubicBezier(p0, p1, p2, p3, t) {
  let u = 1 - t;
  let b0 = u * u * u;
  let b1 = 3 * u * u * t;
  let b2 = 3 * u * t * t;
  let b3 = t * t * t;
  return [
    b0 * p0[0] + b1 * p1[0] + b2 * p2[0] + b3 * p3[0],
    b0 * p0[1] + b1 * p1[1] + b2 * p2[1] + b3 * p3[1]
  ];
}

function sampleBezierChain(segments, stepsPerSeg = 22) {
  let pts = [];
  for (let s = 0; s < segments.length; s++) {
    let seg = segments[s];
    let startI = s === 0 ? 0 : 1;
    for (let i = startI; i <= stepsPerSeg; i++) {
      let t = i / stepsPerSeg;
      pts.push(evalCubicBezier(seg[0], seg[1], seg[2], seg[3], t));
    }
  }
  return pts;
}

