// ============================================================================
// 4. 3D BANDONEÓN PROJECTION & HYPERREALISTIC ENGINE
// ============================================================================

function project3D(pt) {
  // Camera pitch looking down at 22.5 degrees
  let pitch = 22.5;
  let cp = cos(pitch), sp = sin(pitch);
  let x = pt[0];
  let y = pt[1];
  let z = pt[2];

  let y1 = y * cp - z * sp;
  let z1 = y * sp + z * cp;

  let camDist = 2350;
  let sc = (camDist / (camDist - z1)) * 1.07;

  return [
    592 + x * sc,
    688 - y1 * sc
  ];
}

// Build local orthonormal basis (T, U, V) and transform local (tOff, u, v) -> 2D screen point
function makeFrame3D(origin, yaw, pitchF, rollF) {
  let cy = cos(yaw), sy = sin(yaw);
  let T0 = [cy, 0, -sy];
  let U0 = [sy, 0, cy];
  let V0 = [0, 1, 0];

  let cp = cos(pitchF), sp = sin(pitchF);
  let T = [
    T0[0] * cp - V0[0] * sp,
    T0[1] * cp - V0[1] * sp,
    T0[2] * cp - V0[2] * sp
  ];
  let V1 = [
    T0[0] * sp + V0[0] * cp,
    T0[1] * sp + V0[1] * cp,
    T0[2] * sp + V0[2] * cp
  ];

  let cr = cos(rollF), sr = sin(rollF);
  let U = [
    U0[0] * cr - V1[0] * sr,
    U0[1] * cr - V1[1] * sr,
    U0[2] * cr - V1[2] * sr
  ];
  let V = [
    U0[0] * sr + V1[0] * cr,
    U0[1] * sr + V1[1] * cr,
    U0[2] * sr + V1[2] * cr
  ];

  return {
    origin: origin,
    T: T,
    U: U,
    V: V,
    pt3D: function(tOff, u, v) {
      return [
        origin[0] + tOff * T[0] + u * U[0] + v * V[0],
        origin[1] + tOff * T[1] + u * U[1] + v * V[1],
        origin[2] + tOff * T[2] + u * U[2] + v * V[2]
      ];
    },
    pt2D: function(tOff, u, v) {
      return project3D(this.pt3D(tOff, u, v));
    },
    // Returns the 8 vertices of an octagonal chamfered bandoneón cross-section
    ring2D: function(tOff, w, h, c, vBottom = 0) {
      let hw = w * 0.5;
      let vTop = vBottom + h;
      return [
        this.pt2D(tOff, -hw + c, vBottom),      // 0: Bottom-Back
        this.pt2D(tOff, +hw - c, vBottom),      // 1: Bottom-Front-Lower
        this.pt2D(tOff, +hw, vBottom + c),      // 2: Bottom-Front-Upper (1-2 = Lower-Front Chamfer)
        this.pt2D(tOff, +hw, vTop - c),         // 3: Top-Front-Lower    (2-3 = Main Front Face)
        this.pt2D(tOff, +hw - c, vTop),         // 4: Top-Front-Upper    (3-4 = Upper-Front Chamfer)
        this.pt2D(tOff, -hw + c, vTop),         // 5: Top-Back-Upper     (4-5 = Main Top Face)
        this.pt2D(tOff, -hw, vTop - c),         // 6: Top-Back-Lower     (5-6 = Upper-Back Chamfer)
        this.pt2D(tOff, -hw, vBottom + c)       // 7: Bottom-Back-Upper  (6-7 = Main Back Face)
      ];
    }
  };
}

// Parametric spine for the 14 bellows pleats (s in [0, 1], from Left Housing to Right Housing)
function getBellowsFrame(s) {
  // Curved half-open posture: arches slightly in middle and fans open in yaw & pitch
  let ox = lerp(-132, 185, s);
  let oy = lerp(2, 22, s) + 24 * sin(s * 180);
  let oz = lerp(82, -88, s) + 18 * sin(s * 180);

  let yaw = lerp(37.5, 14.5, pow(s, 0.92));
  let pitchF = lerp(-2.0, -13.5, s);
  let rollF = lerp(2.5, -5.5, s);

  return makeFrame3D([ox, oy, oz], yaw, pitchF, rollF);
}

function drawBandoneon3D() {
  let numPleats = 14;
  let wPeak = 266, hPeak = 274, cPeak = 42;
  let wVal = 216, hVal = 226, cVal = 32, vValBot = 22;

  // -------------------------------------------------------------------------
  // STEP A: RIGHT HOUSING (CABEZAL DERECHO - Furthest in Z, drawn first)
  // -------------------------------------------------------------------------
  let rightFrame = getBellowsFrame(1.0);
  drawRightCabezal(rightFrame, wPeak, hPeak, cPeak);

  // -------------------------------------------------------------------------
  // STEP B: FOLDED BELLOWS WITH GILT-EDGED CORNER LEATHER (Pleats 13 down to 0)
  // -------------------------------------------------------------------------
  let peaks = [];
  let valleys = [];
  for (let k = 0; k <= numPleats; k++) {
    let s = k / numPleats;
    let f = getBellowsFrame(s);
    peaks.push({
      frame: f,
      ring: f.ring2D(0, wPeak, hPeak, cPeak, 0),
      s: s
    });
  }
  for (let k = 0; k < numPleats; k++) {
    let s = (k + 0.52) / numPleats; // slight asymmetry for gravity-weighted folds
    let f = getBellowsFrame(s);
    valleys.push({
      frame: f,
      ring: f.ring2D(0, wVal, hVal, cVal, vValBot),
      s: s
    });
  }

  for (let k = numPleats - 1; k >= 0; k--) {
    drawBellowsPleat(k, numPleats, peaks[k], valleys[k], peaks[k + 1], wPeak, hPeak, cPeak);
  }

  // -------------------------------------------------------------------------
  // STEP C: LEFT HOUSING (CABEZAL IZQUIERDO - Closest in Z, with 38 Pearl Buttons)
  // -------------------------------------------------------------------------
  let leftFrame = getBellowsFrame(0.0);
  drawLeftCabezal(leftFrame, wPeak, hPeak, cPeak);
}

// ============================================================================
// RIGHT HOUSING (CABEZAL DERECHO)
// ============================================================================

function drawRightCabezal(F, wBase, hBase, cBase) {
  // 1. Protruding Bass Mother-of-Pearl Buttons & Hand Strap on the far-right edge (drawn behind housing)
  drawRightProtrudingStrapAndButtons(F, wBase, hBase, cBase);

  // 2. Stepped Lacquered Cabinet Layers from outer right (t = +134) to bellows joint (t = 0)
  let rOuter = F.ring2D(134, wBase - 12, hBase - 12, cBase - 2, 6);
  let rBevel = F.ring2D(115, wBase + 10, hBase + 10, cBase + 2, -5);
  let rMain  = F.ring2D(18,  wBase + 10, hBase + 10, cBase + 2, -5);
  let rMount = F.ring2D(0,   wBase + 2,  hBase + 2,  cBase, -1);

  // Outer Stepped Bevel (t = 115 .. 134)
  gradedQuad(rBevel[5], rOuter[5], rOuter[4], rBevel[4], 12, [PAL.lacquerDark, PAL.lacquerCool, PAL.lacquerSpec, PAL.lacquerMid], "glaze", 0.7, PAL.lacquerDark);
  gradedQuad(rBevel[4], rOuter[4], rOuter[3], rBevel[3], 10, [PAL.lacquerSpec, PAL.lacquerSlate, PAL.lacquerMid], "glaze", 0.7, PAL.lacquerMid);
  gradedQuad(rBevel[3], rOuter[3], rOuter[2], rBevel[2], 20, [PAL.lacquerMid, PAL.lacquerWarm, PAL.lacquerDeep, PAL.lacquerAmber, PAL.lacquerDark], "glaze", 0.8, PAL.lacquerDeep);
  gradedQuad(rBevel[2], rOuter[2], rOuter[1], rBevel[1], 8,  [PAL.lacquerDeep, "#050405"], "glaze", 0.7, PAL.lacquerDeep);

  // Main Resonance Cabinet (t = 18 .. 115)
  // Upper-Back Chamfer (5-6)
  washPoly([rMain[6], rBevel[6], rBevel[5], rMain[5]], PAL.lacquerDeep, 240);
  // Main Top Face (4-5)
  gradedQuad(
    rMain[5], rBevel[5], rBevel[4], rMain[4], 26,
    [PAL.lacquerDeep, PAL.lacquerDark, PAL.lacquerCool, PAL.lacquerSlate, PAL.lacquerSpec, PAL.lacquerCool, PAL.lacquerDark],
    "glaze", 0.9, PAL.lacquerDark
  );
  // Upper-Front Chamfer (3-4) - Bright lacquer bevel
  gradedQuad(
    rMain[4], rBevel[4], rBevel[3], rMain[3], 14,
    [PAL.lacquerSpec, PAL.lacquerSlate, PAL.lacquerWarm, PAL.lacquerMid],
    "glaze", 0.75, PAL.lacquerMid
  );
  // Main Front Face (2-3) - Mirror-gloss black lacquer with oxblood stage reflections
  gradedQuad(
    rMain[3], rBevel[3], rBevel[2], rMain[2], 36,
    [PAL.lacquerMid, PAL.lacquerSlate, PAL.lacquerDark, PAL.lacquerDeep, PAL.lacquerWarm, PAL.lacquerAmber, PAL.lacquerWarm, PAL.lacquerDeep, "#050406"],
    "glaze", 0.95, PAL.lacquerDeep
  );
  // Lower-Front Chamfer (1-2)
  gradedQuad(
    rMain[2], rBevel[2], rBevel[1], rMain[1], 10,
    [PAL.lacquerDeep, PAL.lacquerWarm, "#040304"],
    "glaze", 0.75, "#050405"
  );

  // Ornate Pierced Fretwork Grille (Calado) on the Right Housing Front Face
  drawHousingFretworkGrille(F, 34, 98, wBase + 10.5, 45, 225);

  // Nickel-silver corner hardware plates (Cantoneras) on Right Housing
  drawCornerHardware(F, 18, 42, wBase + 11, hBase + 11, cBase + 2, -5);
  drawCornerHardware(F, 92, 115, wBase + 11, hBase + 11, cBase + 2, -5);

  // Bellows Mounting Frame (t = 0 .. 18)
  gradedQuad(rMount[5], rMain[5], rMain[4], rMount[4], 10, [PAL.lacquerDark, PAL.lacquerCool, PAL.lacquerDeep], "glaze", 0.65, PAL.lacquerDark);
  gradedQuad(rMount[4], rMain[4], rMain[3], rMount[3], 8,  [PAL.lacquerSpec, PAL.lacquerMid], "glaze", 0.6, PAL.lacquerMid);
  gradedQuad(rMount[3], rMain[3], rMain[2], rMount[2], 18, [PAL.lacquerDark, PAL.lacquerWarm, PAL.lacquerDeep], "glaze", 0.7, PAL.lacquerDeep);
  gradedQuad(rMount[2], rMain[2], rMain[1], rMount[1], 6,  [PAL.lacquerDeep, "#040304"], "glaze", 0.6, "#050405");

  // Inner recessed step where bellows meet Right Housing (visible in 3/4 view!)
  washPoly([rMain[5], rMount[5], rMount[4], rMain[4]], "#0c0b0e", 180);
  strokePoly([rMain[5], rMain[4], rMain[3], rMain[2], rMain[1]], false, "liner", PAL.lacquerSpec, 0.55);
  strokePoly([rBevel[5], rBevel[4], rBevel[3], rBevel[2], rBevel[1]], false, "liner", PAL.lacquerWhite, 0.65);

  // Mounting screws along the frame
  for (let f = 0.18; f <= 0.84; f += 0.22) {
    let pTop = [lerp(rMount[4][0], rMount[5][0], f), lerp(rMount[4][1], rMount[5][1], f)];
    let pFront = [lerp(rMount[2][0], rMount[3][0], f), lerp(rMount[2][1], rMount[3][1], f)];
    drawTinyScrew(pTop[0] + 4, pTop[1] - 2);
    drawTinyScrew(pFront[0] + 5, pFront[1]);
  }

  // Hyperreal Fingerprint Smears, Lacquer Scuffs & Wood Chips on Right Housing
  drawFingerprintSmear(F.pt2D(72, (wBase + 11) * 0.5, 195), 22, 14, -20);
  drawFingerprintSmear(F.pt2D(86, (wBase + 11) * 0.5, 155), 19, 13, 12);
  drawFingerprintSmear(F.pt2D(58, (wBase + 11) * 0.3, hBase + 5), 24, 12, -8);
  drawLacquerScuffsAndChips(F, 24, 110, wBase + 10, hBase + 10, cBase + 2, -5);
}

function drawRightProtrudingStrapAndButtons(F, wBase, hBase, cBase) {
  // Curved leather hand strap arching out beyond the right edge (t = 95..165)
  let strapPtsOuter = [];
  let strapPtsInner = [];
  let steps = 18;
  for (let i = 0; i <= steps; i++) {
    let s = i / steps;
    let v = lerp(12, hBase - 8, s);
    let u = lerp(wBase * 0.25, wBase * 0.12, s);
    let arch = sin(s * 180) * 44;
    strapPtsOuter.push(F.pt2D(118 + arch, u + 16, v));
    strapPtsInner.push(F.pt2D(108 + arch * 0.82, u, v));
  }
  let strapPoly = strapPtsOuter.concat(strapPtsInner.slice().reverse());
  washPoly(strapPoly, PAL.leatherDark, 240, "#090606", 0.5, "pen");

  // Velvet lining edge & leather creases on right strap
  for (let i = 1; i < steps; i++) {
    brush.set("glaze", i % 2 === 0 ? PAL.leatherMid : "#3d1817", 0.65);
    brush.line(strapPtsInner[i][0], strapPtsInner[i][1], strapPtsOuter[i][0], strapPtsOuter[i][1]);
    brush.set("micro_pen", PAL.leatherLight, 0.45);
    brush.line(strapPtsOuter[i - 1][0], strapPtsOuter[i - 1][1], strapPtsOuter[i][0], strapPtsOuter[i][1]);
  }

  // Brass thumbscrew bracket at top of Right Housing
  let brkBase = F.pt2D(92, 10, hBase + 6);
  let brkTop  = F.pt2D(102, 10, hBase + 26);
  washPoly([
    [brkBase[0] - 12, brkBase[1]], [brkBase[0] + 12, brkBase[1]],
    [brkTop[0] + 9, brkTop[1]], [brkTop[0] - 9, brkTop[1]]
  ], PAL.giltBase, 235, PAL.leatherDark, 0.5, "rotring");
  brush.set("liner", PAL.giltSpec, 0.7);
  brush.line(brkTop[0] - 8, brkTop[1], brkTop[0] + 8, brkTop[1]);

  // Protruding Bass Mother-of-Pearl Buttons along the outer right silhouette
  let uRows = [wBase * 0.44, wBase * 0.30, wBase * 0.14];
  for (let r = 0; r < uRows.length; r++) {
    let u = uRows[r];
    let count = 9 - r;
    for (let j = 0; j < count; j++) {
      let v = map(j, 0, count - 1, 38 + r * 14, hBase - 34 - r * 10);
      let pBase = F.pt2D(132, u, v);
      let pTip  = F.pt2D(149 - r * 2, u, v);
      drawProfilePearlButton(pBase, pTip, 6.8 - r * 0.5);
    }
  }
}

function drawProfilePearlButton(pBase, pTip, rad) {
  let dx = pTip[0] - pBase[0];
  let dy = pTip[1] - pBase[1];
  let ang = atan2(dy, dx);
  let nx = -sin(ang) * rad;
  let ny = cos(ang) * rad;

  // Bone/ivory button stem
  let stemPoly = [
    [pBase[0] - nx, pBase[1] - ny],
    [pTip[0] - nx, pTip[1] - ny],
    [pTip[0] + nx, pTip[1] + ny],
    [pBase[0] + nx, pBase[1] + ny]
  ];
  washPoly(stemPoly, PAL.pearlStem, 235, PAL.pearlShadow, 0.35, "rotring");
  brush.set("liner", PAL.pearlBase, 0.55);
  brush.line(pBase[0] - nx * 0.5, pBase[1] - ny * 0.5, pTip[0] - nx * 0.5, pTip[1] - ny * 0.5);

  // Mother-of-pearl cap ellipse in profile
  let capPts = [];
  for (let a = 0; a < 360; a += 30) {
    let ca = cos(a), sa = sin(a);
    capPts.push([
      pTip[0] + cos(ang) * ca * (rad * 0.48) - sin(ang) * sa * rad,
      pTip[1] + sin(ang) * ca * (rad * 0.48) + cos(ang) * sa * rad
    ]);
  }
  washPoly(capPts, PAL.pearlBase, 245, PAL.pearlShadow, 0.35, "rotring");
  brush.set("liner", PAL.pearlSpec, 0.65);
  brush.line(pTip[0] - nx * 0.6, pTip[1] - ny * 0.6, pTip[0] + nx * 0.2, pTip[1] + ny * 0.2);
}

// ============================================================================
// BELLOWS PLEATS & GILT-EDGED CORNER LEATHER
// ============================================================================

function drawBellowsPleat(k, numPleats, peakL, valley, peakR, wPeak, hPeak, cPeak) {
  let pL = peakL.ring;
  let vM = valley.ring;
  let pR = peakR.ring;

  // 1. UPPER-BACK CHAMFER (5-6) - dark cloth spine along back top edge
  washPoly([pL[6], vM[6], vM[5], pL[5]], "#141010", 240);
  washPoly([vM[6], pR[6], pR[5], vM[5]], "#0b0808", 240);

  // 2. MAIN TOP FACE (4-5)
  // Facet facing right/away (vM -> pR): deep shadow fold
  gradedQuad(
    vM[5], pR[5], pR[4], vM[4], 10,
    [PAL.bellowsShadow, PAL.bellowsDark, "#1b1413"],
    "glaze", 0.65, PAL.bellowsShadow
  );
  // Facet facing left/upward toward light (pL -> vM): lit cloth fold
  gradedQuad(
    pL[5], vM[5], vM[4], pL[4], 12,
    [PAL.bellowsMid, PAL.bellowsLight, PAL.bellowsMid, PAL.bellowsDark],
    "glaze", 0.65, PAL.bellowsMid
  );

  // 3. MAIN FRONT FACE (2-3)
  // Facet facing right/inward (vM -> pR): deep dramatic accordion fold shadow
  gradedQuad(
    vM[3], pR[3], pR[2], vM[2], 18,
    [PAL.bellowsDark, PAL.bellowsShadow, "#080606", PAL.bellowsDark],
    "glaze", 0.7, PAL.bellowsShadow
  );
  // Facet facing left/viewer (pL -> vM): warm earth-toned cloth pleat
  gradedQuad(
    pL[3], vM[3], vM[2], pL[2], 20,
    [PAL.bellowsLight, PAL.bellowsMid, "#2d1f1c", PAL.bellowsMid, PAL.bellowsDark],
    "glaze", 0.75, PAL.bellowsMid
  );

  // Central Ornate Gilt-Trimmed Diamond Motif across the middle pleats (k = 3..10)
  if (k >= 3 && k <= 10) {
    let centerDist = abs(k - 6.5) / 4.0;
    let span = lerp(0.34, 0.08, centerDist);
    let fTop = 0.5 - span;
    let fBot = 0.5 + span;
    let dL1 = [lerp(pL[3][0], pL[2][0], fTop), lerp(pL[3][1], pL[2][1], fTop)];
    let dL2 = [lerp(pL[3][0], pL[2][0], fBot), lerp(pL[3][1], pL[2][1], fBot)];
    let dV1 = [lerp(vM[3][0], vM[2][0], fTop + 0.03), lerp(vM[3][1], vM[2][1], fTop + 0.03)];
    let dV2 = [lerp(vM[3][0], vM[2][0], fBot - 0.03), lerp(vM[3][1], vM[2][1], fBot - 0.03)];
    let dR1 = [lerp(pR[3][0], pR[2][0], fTop), lerp(pR[3][1], pR[2][1], fTop)];
    let dR2 = [lerp(pR[3][0], pR[2][0], fBot), lerp(pR[3][1], pR[2][1], fBot)];

    washPoly([dL1, dV1, dV2, dL2], "#3b231e", 215, PAL.giltMid, 0.55, "liner");
    washPoly([dV1, dR1, dR2, dV2], "#1f1210", 225, PAL.giltShadow, 0.45, "liner");
    brush.set("liner", PAL.giltBright, 0.5);
    brush.line(dL1[0], dL1[1], dV1[0], dV1[1]);
    brush.line(dL2[0], dL2[1], dV2[0], dV2[1]);
  }

  // 4. GILT-EDGED CORNER LEATHER GUSSETS (ESQUINEROS)
  // Upper-Front Chamfer (3-4): Hero zig-zag diamond leather folds with embossed gilt borders!
  drawGiltCornerLeatherGusset(pL, vM, pR, 3, 4, 2, 5, true);

  // Lower-Front Chamfer (1-2): Lower row of gilt-edged corner leather folds!
  drawGiltCornerLeatherGusset(pL, vM, pR, 1, 2, 0, 3, false);

  // 5. Fine Pen Creases, Cloth Weave & Ridge Binding Highlights on Pleat k
  // Valley crease lines
  brush.set("rotring", "#050304", 0.55);
  brush.line(vM[5][0], vM[5][1], vM[4][0], vM[4][1]);
  brush.line(vM[3][0], vM[3][1], vM[2][0], vM[2][1]);

  // Subtle horizontal cloth stress creases inside the pleat
  for (let c = 1; c <= 4; c++) {
    let f = c / 5.0;
    let a = [lerp(pL[3][0], pL[2][0], f), lerp(pL[3][1], pL[2][1], f)];
    let b = [lerp(vM[3][0], vM[2][0], f), lerp(vM[3][1], vM[2][1], f)];
    brush.set("micro_pen", c % 2 === 0 ? "#120d0c" : "#42332d", 0.35);
    brush.line(a[0], a[1], b[0], b[1]);
  }

  // Peak ridge binding tape (perciana) along pL
  strokePoly([pL[5], pL[4]], false, "liner", PAL.bellowsEdge, 0.9);
  strokePoly([pL[3], pL[2]], false, "liner", PAL.bellowsEdge, 0.95);
  brush.set("micro_pen", "#6e584d", 0.4);
  brush.line(pL[5][0], pL[5][1], pL[4][0], pL[4][1]);
  brush.line(pL[3][0], pL[3][1], pL[2][0], pL[2][1]);
}

function drawGiltCornerLeatherGusset(pL, vM, pR, idxA, idxB, adjA, adjB, isUpper) {
  // Pinched valley center point where the diamond leather folds inward
  let vc = [
    (vM[idxA][0] + vM[idxB][0]) * 0.5,
    (vM[idxA][1] + vM[idxB][1]) * 0.5
  ];

  // Leather flap extension onto adjacent Top and Front faces
  let flap = 0.13;
  let lExtA = [lerp(pL[idxA][0], pL[adjA][0], flap), lerp(pL[idxA][1], pL[adjA][1], flap)];
  let lExtB = [lerp(pL[idxB][0], pL[adjB][0], flap), lerp(pL[idxB][1], pL[adjB][1], flap)];
  let rExtA = [lerp(pR[idxA][0], pR[adjA][0], flap), lerp(pR[idxA][1], pR[adjA][1], flap)];
  let rExtB = [lerp(pR[idxB][0], pR[adjB][0], flap), lerp(pR[idxB][1], pR[adjB][1], flap)];
  let vExtA = [lerp(vM[idxA][0], vM[adjA][0], flap * 0.55), lerp(vM[idxA][1], vM[adjA][1], flap * 0.55)];
  let vExtB = [lerp(vM[idxB][0], vM[adjB][0], flap * 0.55), lerp(vM[idxB][1], vM[adjB][1], flap * 0.55)];

  // 1. Gilt-edged leather overlap tabs on the adjacent faces
  let giltColL = isUpper ? PAL.giltMid : PAL.giltBase;
  let giltColR = isUpper ? PAL.giltBase : PAL.giltShadow;
  washPoly([pL[idxB], lExtB, vExtB, vc], giltColL, 240, PAL.giltShadow, 0.35, "rotring");
  washPoly([vc, vExtB, rExtB, pR[idxB]], giltColR, 235, PAL.giltShadow, 0.35, "rotring");
  washPoly([pL[idxA], lExtA, vExtA, vc], giltColL, 240, PAL.giltShadow, 0.35, "rotring");
  washPoly([vc, vExtA, rExtA, pR[idxA]], giltColR, 235, PAL.giltShadow, 0.35, "rotring");

  // 2. Central kidskin leather diamond gusset facets (4 triangles meeting at vc)
  // Upper-right triangle (vc - pR[idxB] - pL[idxB] split or standard 4-way gusset fold)
  // On a real bandoneón corner gusset, the diagonal creases go from pL[idxA] to vc, pL[idxB] to vc, pR[idxA] to vc, pR[idxB] to vc:
  // Right-facing leather fold (pR[idxA] - pR[idxB] - vc): in shadow
  washPoly([pR[idxA], pR[idxB], vc], PAL.leatherDark, 245, "#080505", 0.4, "rotring");
  // Top-sloping triangle (pL[idxB] - pR[idxB] - vc): catches warm upper stage light
  washPoly([pL[idxB], pR[idxB], vc], isUpper ? PAL.leatherLight : PAL.leatherMid, 245, "#120c09", 0.4, "rotring");
  // Bottom-sloping triangle (pL[idxA] - vc - pR[idxA]): deep crease shadow
  washPoly([pL[idxA], vc, pR[idxA]], "#140d0a", 245, "#080505", 0.4, "rotring");
  // Left-facing leather fold (pL[idxA] - pL[idxB] - vc): warm lit kidskin leather
  washPoly([pL[idxA], pL[idxB], vc], isUpper ? PAL.leatherMid : PAL.leatherDark, 245, "#120c09", 0.4, "rotring");

  // 3. Crisp Embossed Gold-Leaf (Gilt) Borders & Specular Highlights
  let inset = 0.28;
  let inLA = [lerp(pL[idxA][0], lExtA[0], inset), lerp(pL[idxA][1], lExtA[1], inset)];
  let inLB = [lerp(pL[idxB][0], lExtB[0], inset), lerp(pL[idxB][1], lExtB[1], inset)];

  // Bright gold tooling lines along outer chevron edges
  brush.set("liner", isUpper ? PAL.giltBright : PAL.giltMid, isUpper ? 0.72 : 0.55);
  brush.line(lExtB[0], lExtB[1], vExtB[0], vExtB[1]);
  brush.line(lExtA[0], lExtA[1], vExtA[0], vExtA[1]);
  brush.line(pL[idxB][0], pL[idxB][1], lExtB[0], lExtB[1]);
  brush.line(pL[idxA][0], pL[idxA][1], lExtA[0], lExtA[1]);

  brush.set("liner", isUpper ? PAL.giltMid : PAL.giltBase, 0.55);
  brush.line(vExtB[0], vExtB[1], rExtB[0], rExtB[1]);
  brush.line(vExtA[0], vExtA[1], rExtA[0], rExtA[1]);

  // Specular gold-leaf glint right on the peak corner ridge (pL[idxA] -> pL[idxB])
  brush.set("liner", isUpper ? PAL.giltSpec : PAL.giltBright, isUpper ? 0.85 : 0.6);
  brush.line(pL[idxA][0], pL[idxA][1], pL[idxB][0], pL[idxB][1]);

  // Fine dark inner leather crease line
  brush.set("micro_pen", "#1a110b", 0.4);
  brush.line(inLA[0], inLA[1], vc[0], vc[1]);
  brush.line(inLB[0], inLB[1], vc[0], vc[1]);
}

// ============================================================================
// LEFT HOUSING (CABEZAL IZQUIERDO - Foreground 3/4 View with 38 Pearl Buttons)
// ============================================================================

function drawLeftCabezal(F, wBase, hBase, cBase) {
  // Stepped Lacquered Cabinet Layers from bellows joint (t = 0) outward to buttonboard (t = -142)
  let lMount = F.ring2D(0,    wBase + 2,  hBase + 2,  cBase, -1);
  let lMain0 = F.ring2D(-16,  wBase + 12, hBase + 12, cBase + 2, -6);
  let lMain1 = F.ring2D(-110, wBase + 12, hBase + 12, cBase + 2, -6);
  let lBevel = F.ring2D(-128, wBase - 2,  hBase - 2,  cBase, 1);
  let lFace  = F.ring2D(-142, wBase - 14, hBase - 14, cBase - 3, 7);

  // 1. Bellows Mounting Frame (t = 0 .. -16)
  gradedQuad(lMain0[5], lMount[5], lMount[4], lMain0[4], 10, [PAL.lacquerDark, PAL.lacquerCool, PAL.lacquerDeep], "glaze", 0.7, PAL.lacquerDark);
  gradedQuad(lMain0[4], lMount[4], lMount[3], lMain0[3], 8,  [PAL.lacquerSpec, PAL.lacquerMid], "glaze", 0.65, PAL.lacquerMid);
  gradedQuad(lMain0[3], lMount[3], lMount[2], lMain0[2], 18, [PAL.lacquerDark, PAL.lacquerWarm, PAL.lacquerDeep], "glaze", 0.75, PAL.lacquerDeep);
  gradedQuad(lMain0[2], lMount[2], lMount[1], lMain0[1], 6,  [PAL.lacquerDeep, "#040304"], "glaze", 0.65, "#050405");

  // Mounting screws along bellows joint
  for (let f = 0.18; f <= 0.84; f += 0.22) {
    let pTop = [lerp(lMount[4][0], lMount[5][0], f), lerp(lMount[4][1], lMount[5][1], f)];
    let pFront = [lerp(lMount[2][0], lMount[3][0], f), lerp(lMount[2][1], lMount[3][1], f)];
    drawTinyScrew(pTop[0] - 4, pTop[1] - 2);
    drawTinyScrew(pFront[0] - 4, pFront[1]);
  }

  // 2. Main Resonance Cabinet (t = -16 .. -110)
  // Upper-Back Chamfer (5-6)
  washPoly([lMain1[6], lMain0[6], lMain0[5], lMain1[5]], PAL.lacquerDeep, 240);
  // Main Top Face (4-5)
  gradedQuad(
    lMain1[5], lMain0[5], lMain0[4], lMain1[4], 28,
    [PAL.lacquerDeep, PAL.lacquerDark, PAL.lacquerCool, PAL.lacquerSlate, PAL.lacquerSpec, PAL.lacquerCool, PAL.lacquerDark],
    "glaze", 0.9, PAL.lacquerDark
  );
  // Upper-Front Chamfer (3-4) - Bright lacquer bevel
  gradedQuad(
    lMain1[4], lMain0[4], lMain0[3], lMain1[3], 15,
    [PAL.lacquerWhite, PAL.lacquerSpec, PAL.lacquerSlate, PAL.lacquerWarm, PAL.lacquerMid],
    "glaze", 0.8, PAL.lacquerMid
  );
  // Main Front Face (2-3) - Mirror-gloss black lacquer with oxblood stage reflections
  gradedQuad(
    lMain1[3], lMain0[3], lMain0[2], lMain1[2], 38,
    [PAL.lacquerMid, PAL.lacquerSlate, PAL.lacquerDark, PAL.lacquerDeep, PAL.lacquerWarm, PAL.lacquerAmber, PAL.lacquerWarm, PAL.lacquerDeep, "#040305"],
    "glaze", 0.95, PAL.lacquerDeep
  );
  // Lower-Front Chamfer (1-2)
  gradedQuad(
    lMain1[2], lMain0[2], lMain0[1], lMain1[1], 10,
    [PAL.lacquerDeep, PAL.lacquerWarm, "#040304"],
    "glaze", 0.75, "#050405"
  );

  // Ornate Pierced Fretwork Grille (Calado) on Left Housing Front Face
  drawHousingFretworkGrille(F, -94, -32, wBase + 12.5, 42, 228);

  // Nickel-silver corner hardware plates (Cantoneras) on Left Housing
  drawCornerHardware(F, -38, -16, wBase + 13, hBase + 13, cBase + 2, -6);
  drawCornerHardware(F, -110, -86, wBase + 13, hBase + 13, cBase + 2, -6);

  // Scuffs, Fingerprints & Wood Chips on Left Housing Side/Top
  drawFingerprintSmear(F.pt2D(-62, (wBase + 12) * 0.5, 205), 24, 15, 18);
  drawFingerprintSmear(F.pt2D(-82, (wBase + 12) * 0.5, 145), 20, 14, -14);
  drawFingerprintSmear(F.pt2D(-52, (wBase + 12) * 0.25, hBase + 6), 26, 14, 10);
  drawLacquerScuffsAndChips(F, -105, -22, wBase + 12, hBase + 12, cBase + 2, -6);

  // 3. Stepped Molded Bevel (t = -110 .. -128) & Outer Keyboard Rim (t = -128 .. -142)
  gradedQuad(lBevel[5], lMain1[5], lMain1[4], lBevel[4], 12, [PAL.lacquerDark, PAL.lacquerCool, PAL.lacquerSpec], "glaze", 0.7, PAL.lacquerDark);
  gradedQuad(lBevel[4], lMain1[4], lMain1[3], lBevel[3], 10, [PAL.lacquerWhite, PAL.lacquerSpec, PAL.lacquerMid], "glaze", 0.7, PAL.lacquerMid);
  gradedQuad(lBevel[3], lMain1[3], lMain1[2], lBevel[2], 22, [PAL.lacquerMid, PAL.lacquerWarm, PAL.lacquerDeep, PAL.lacquerAmber], "glaze", 0.75, PAL.lacquerDeep);
  gradedQuad(lBevel[2], lMain1[2], lMain1[1], lBevel[1], 8,  [PAL.lacquerDeep, "#040304"], "glaze", 0.65, "#050405");

  gradedQuad(lFace[5], lBevel[5], lBevel[4], lFace[4], 10, [PAL.lacquerDeep, PAL.lacquerCool, PAL.lacquerDark], "glaze", 0.65, PAL.lacquerDark);
  gradedQuad(lFace[4], lBevel[4], lBevel[3], lFace[3], 8,  [PAL.lacquerSpec, PAL.lacquerMid], "glaze", 0.65, PAL.lacquerMid);
  gradedQuad(lFace[3], lBevel[3], lBevel[2], lFace[2], 18, [PAL.lacquerDark, PAL.lacquerWarm, PAL.lacquerDeep], "glaze", 0.7, PAL.lacquerDeep);
  gradedQuad(lFace[2], lBevel[2], lBevel[1], lFace[1], 6,  [PAL.lacquerDeep, "#040304"], "glaze", 0.6, "#050405");

  // Specular highlights along the stepped moldings
  strokePoly([lMain0[5], lMain0[4], lMain0[3], lMain0[2]], false, "liner", PAL.lacquerSpec, 0.55);
  strokePoly([lMain1[5], lMain1[4], lMain1[3], lMain1[2]], false, "liner", PAL.lacquerWhite, 0.75);
  strokePoly([lBevel[5], lBevel[4], lBevel[3], lBevel[2]], false, "liner", PAL.lacquerSpec, 0.6);

  // 4. THE 3/4 BUTTONBOARD FACE (t = -142)
  drawLeftButtonboardFace(F, lFace, wBase, hBase, cBase);
}

function drawLeftButtonboardFace(F, lFace, wBase, hBase, cBase) {
  // Base octagonal lacquered face
  washPoly(lFace, PAL.lacquerDeep, 250, PAL.lacquerMid, 0.7, "rotring");

  // Graded reflection across the buttonboard face (between top edge 5-4 and bottom edge 0-1)
  gradedQuad(
    lFace[6], lFace[3], lFace[2], lFace[7], 36,
    [PAL.lacquerDeep, PAL.lacquerDark, PAL.lacquerCool, PAL.lacquerMid, PAL.lacquerWarm, PAL.lacquerAmber, PAL.lacquerDark, PAL.lacquerDeep],
    "glaze", 0.9, PAL.lacquerDeep
  );

  // Inner recessed molding line around the buttonboard
  let lInset = F.ring2D(-141.5, wBase - 30, hBase - 30, cBase - 8, 15);
  strokePoly(lInset, true, "rotring", "#040305", 0.7);
  strokePoly([lInset[5], lInset[4], lInset[3], lInset[2]], false, "liner", PAL.lacquerSlate, 0.5);

  // Ornate Silver-Nickel Lyre Fretwork Plate in upper center of buttonboard
  drawButtonboardLyrePlate(F, -142.5, 0, 198, 54, 42);

  // Fingerprint smears & thumb wear around the heavily played tango button rows
  drawFingerprintSmear(F.pt2D(-142.5, 65, 145), 28, 18, 30);
  drawFingerprintSmear(F.pt2D(-142.5, 35, 95), 25, 16, -15);
  drawFingerprintSmear(F.pt2D(-142.5, -25, 125), 24, 15, 22);
  drawFingerprintSmear(F.pt2D(-142.5, 85, 205), 22, 13, 45);

  // 38 WORN MOTHER-OF-PEARL BUTTONS in 5 authentic staggered rows
  // Drawn back-to-front (from smaller u / lower z to larger u / higher z)
  let buttonRows = [
    { u: -86, vStart: 48, vEnd: 218, count: 7, rad: 6.2 },
    { u: -48, vStart: 38, vEnd: 232, count: 8, rad: 6.5 },
    { u: -10, vStart: 32, vEnd: 152, count: 6, rad: 6.8 }, // space above for lyre plate
    { u: +30, vStart: 32, vEnd: 162, count: 6, rad: 7.0 },
    { u: +68, vStart: 38, vEnd: 236, count: 8, rad: 7.3 },
    { u: +98, vStart: 58, vEnd: 208, count: 4, rad: 7.4 }
  ];

  let keyNum = 1;
  for (let r = 0; r < buttonRows.length; r++) {
    let row = buttonRows[r];
    for (let j = 0; j < row.count; j++) {
      let f = row.count === 1 ? 0.5 : j / (row.count - 1);
      let v = lerp(row.vStart, row.vEnd, f) + ((j % 2) * 3.5);
      let u = row.u + sin(f * 180) * 6;
      let pHole = F.pt2D(-142, u, v);
      let pCap  = F.pt2D(-155, u, v);
      drawFront3DPearlButton(pHole, pCap, row.rad, keyNum++);
    }
  }

  // Thick Stitched Leather & Burgundy-Velvet Hand Strap arching over the Left Housing
  drawLeftHandStrap(F, wBase, hBase);
}

function drawFront3DPearlButton(pHole, pCap, rad, keyIndex) {
  let dx = pCap[0] - pHole[0];
  let dy = pCap[1] - pHole[1];
  let ang = atan2(dy, dx);
  let nx = -sin(ang) * rad;
  let ny = cos(ang) * rad;

  // 1. Dark recessed button well in the black lacquer
  let holePts = [];
  for (let a = 0; a < 360; a += 30) {
    let ca = cos(a), sa = sin(a);
    holePts.push([
      pHole[0] + cos(ang) * ca * (rad * 0.78) - sin(ang) * sa * (rad * 1.18),
      pHole[1] + sin(ang) * ca * (rad * 0.78) + cos(ang) * sa * (rad * 1.18)
    ]);
  }
  washPoly(holePts, "#030203", 250, PAL.lacquerSlate, 0.35, "micro_pen");

  // Subtle crimson felt bushing ring inside hole
  brush.set("liner", PAL.carmineBase, 0.45);
  brush.line(pHole[0] - nx * 0.7, pHole[1] - ny * 0.7, pHole[0] + nx * 0.7, pHole[1] + ny * 0.7);

  // 2. Cylindrical aged bone/ivory stem protruding from pHole to pCap
  let stemPoly = [
    [pHole[0] - nx * 0.88, pHole[1] - ny * 0.88],
    [pCap[0]  - nx * 0.88, pCap[1]  - ny * 0.88],
    [pCap[0]  + nx * 0.88, pCap[1]  + ny * 0.88],
    [pHole[0] + nx * 0.88, pHole[1] + ny * 0.88]
  ];
  washPoly(stemPoly, PAL.pearlShadow, 240);
  // Lit upper half of cylindrical stem
  let stemLit = [
    [pHole[0] - nx * 0.1, pHole[1] - ny * 0.1],
    [pCap[0]  - nx * 0.1, pCap[1]  - ny * 0.1],
    [pCap[0]  + nx * 0.85, pCap[1]  + ny * 0.85],
    [pHole[0] + nx * 0.85, pHole[1] + ny * 0.85]
  ];
  washPoly(stemLit, PAL.pearlStem, 235);
  brush.set("micro_pen", PAL.pearlBase, 0.45);
  brush.line(pHole[0] + nx * 0.55, pHole[1] + ny * 0.55, pCap[0] + nx * 0.55, pCap[1] + ny * 0.55);

  // 3. Worn Mother-of-Pearl (Nácar) Cap Face at pCap
  let capPts = [];
  for (let a = 0; a < 360; a += 24) {
    let ca = cos(a), sa = sin(a);
    capPts.push([
      pCap[0] + cos(ang) * ca * (rad * 0.72) - sin(ang) * sa * rad,
      pCap[1] + sin(ang) * ca * (rad * 0.72) + cos(ang) * sa * rad
    ]);
  }
  let isHeavilyWorn = (keyIndex % 3 === 0 || keyIndex % 5 === 0);
  washPoly(capPts, isHeavilyWorn ? PAL.pearlWorn : PAL.pearlBase, 250, PAL.pearlShadow, 0.4, "rotring");

  // Iridescent nacre flashes (rose carmine, verdigris emerald, gold ochre)
  brush.set("glaze", PAL.pearlRose, 0.38);
  brush.line(pCap[0] - nx * 0.35, pCap[1] - ny * 0.35, pCap[0] + nx * 0.2, pCap[1] + ny * 0.2);
  brush.set("glaze", PAL.pearlEmerald, 0.35);
  brush.line(pCap[0] + nx * 0.1, pCap[1] + ny * 0.1, pCap[0] + nx * 0.55, pCap[1] + ny * 0.55);

  // Worn concave finger hollow in center
  if (isHeavilyWorn) {
    brush.set("glaze", "#826e57", 0.42);
    brush.line(pCap[0] - 1.5, pCap[1] - 1, pCap[0] + 1.5, pCap[1] + 1);
  }

  // Tiny incised key mark in center
  brush.set("micro_pen", "#45392d", 0.35);
  brush.line(pCap[0] - 1.2, pCap[1] - 0.8, pCap[0] + 1.2, pCap[1] + 0.8);

  // Crisp crescent pearl highlight on upper rim
  brush.set("liner", PAL.pearlSpec, 0.65);
  brush.line(
    pCap[0] + nx * 0.35 + cos(ang) * rad * 0.25,
    pCap[1] + ny * 0.35 + sin(ang) * rad * 0.25,
    pCap[0] + nx * 0.75 - cos(ang) * rad * 0.2,
    pCap[1] + ny * 0.75 - sin(ang) * rad * 0.2
  );
}

function drawLeftHandStrap(F, wBase, hBase) {
  // Brass & nickel adjustment bracket on top of the Left Housing
  let b1 = F.pt2D(-62, -18, hBase + 10);
  let b2 = F.pt2D(-98, -18, hBase + 10);
  let b3 = F.pt2D(-98, -18, hBase + 28);
  let b4 = F.pt2D(-62, -18, hBase + 28);
  washPoly([b1, b2, b3, b4], PAL.giltBase, 240, "#120c08", 0.5, "rotring");
  // Knurled brass thumbscrew on top
  let s1 = F.pt2D(-80, -18, hBase + 28);
  let s2 = F.pt2D(-80, -18, hBase + 42);
  washPoly([
    [s1[0] - 11, s1[1]], [s1[0] + 11, s1[1]],
    [s2[0] + 14, s2[1]], [s2[0] - 14, s2[1]]
  ], PAL.giltMid, 245, PAL.giltShadow, 0.5, "rotring");
  brush.set("liner", PAL.giltSpec, 0.75);
  brush.line(s2[0] - 12, s2[1], s2[0] + 12, s2[1]);

  // Wide arched leather hand strap from top bracket (-80, -18, hBase+18) over buttonboard (-174) to bottom (-80, -18, 4)
  let steps = 24;
  let outerTop = [], outerBot = [], velvetEdge = [];
  for (let i = 0; i <= steps; i++) {
    let s = i / steps;
    let v = lerp(hBase + 16, 4, s);
    let tArch = lerp(-82, -82, s) - sin(s * 180) * 94;
    let uArch = lerp(-18, -10, s) - sin(s * 180) * 32;
    outerTop.push(F.pt2D(tArch - 12, uArch - 18, v));
    outerBot.push(F.pt2D(tArch + 14, uArch + 14, v));
    velvetEdge.push(F.pt2D(tArch + 20, uArch + 19, v));
  }

  // Plush burgundy velvet lining along inner edge
  let velvetPoly = outerBot.concat(velvetEdge.slice().reverse());
  washPoly(velvetPoly, "#421517", 240, "#1a0708", 0.45, "pen");

  // Thick saddle-leather exterior band
  let leatherPoly = outerTop.concat(outerBot.slice().reverse());
  washPoly(leatherPoly, PAL.leatherDark, 248, "#080505", 0.6, "rotring");

  // Graded marker sheen & worn leather creases along the strap
  for (let i = 0; i < steps; i++) {
    let s = i / steps;
    let col = multiLerpColor([PAL.leatherDark, PAL.leatherLight, PAL.leatherMid, PAL.leatherDark, "#0d0908"], s);
    gradedQuad(outerTop[i], outerBot[i], outerBot[i + 1], outerTop[i + 1], 4, [col, PAL.leatherDark], "glaze", 0.65);

    // Transverse leather flex creases in fine pen
    if (i % 2 === 0) {
      brush.set("micro_pen", "#070404", 0.45);
      brush.line(outerTop[i][0], outerTop[i][1], outerBot[i][0], outerBot[i][1]);
      brush.set("micro_pen", "#634939", 0.35);
      brush.line(outerTop[i][0] + 1, outerTop[i][1] + 1, outerBot[i][0] + 1, outerBot[i][1] + 1);
    }
  }

  // Saddle-stitching & edge highlight along strap
  strokePoly(outerTop, false, "liner", "#755846", 0.65);
  strokePoly(outerBot, false, "micro_pen", "#594032", 0.45);
}

// ============================================================================
// FRETWORK GRILLES, HARDWARE, FINGERPRINTS & SCUFFS
// ============================================================================

function drawHousingFretworkGrille(F, tStart, tEnd, uFront, vBot, vTop) {
  let p0 = F.pt2D(tStart, uFront, vTop);
  let p1 = F.pt2D(tEnd,   uFront, vTop);
  let p2 = F.pt2D(tEnd,   uFront, vBot);
  let p3 = F.pt2D(tStart, uFront, vBot);

  // Recessed crimson-brown silk backing behind fretwork
  washPoly([p0, p1, p2, p3], "#2b0d0f", 240, "#050304", 0.75, "rotring");
  gradedQuad(p0, p1, p2, p3, 12, ["#1c0809", "#3d1416", "#1a0708"], "glaze", 0.6);

  // Fretwork lattice bars & scrolled lyre cutouts in dark lacquer + pewter highlights
  let rows = 6;
  for (let r = 1; r < rows; r++) {
    let f = r / rows;
    let a = [lerp(p0[0], p3[0], f), lerp(p0[1], p3[1], f)];
    let b = [lerp(p1[0], p2[0], f), lerp(p1[1], p2[1], f)];
    let m = [(a[0] + b[0]) * 0.5, (a[1] + b[1]) * 0.5];

    // Diamond/volute fretwork struts
    brush.set("rotring", PAL.lacquerDeep, 1.3);
    brush.line(a[0], a[1], b[0], b[1]);
    brush.set("liner", PAL.lacquerSlate, 0.5);
    brush.line(a[0], a[1] - 1, b[0], b[1] - 1);

    // Diagonal scroll struts
    let fPrev = (r - 0.5) / rows;
    let mPrev = [lerp((p0[0] + p1[0]) * 0.5, (p3[0] + p2[0]) * 0.5, fPrev), lerp((p0[1] + p1[1]) * 0.5, (p3[1] + p2[1]) * 0.5, fPrev)];
    brush.set("liner", PAL.lacquerCool, 0.55);
    brush.line(a[0], a[1], mPrev[0], mPrev[1]);
    brush.line(b[0], b[1], mPrev[0], mPrev[1]);
    drawTinyScrew(m[0], m[1]);
  }

  // Beveled lacquer frame around the fretwork panel
  strokePoly([p0, p1, p2, p3], true, "liner", PAL.lacquerSpec, 0.6);
}

function drawButtonboardLyrePlate(F, tOff, uCenter, vCenter, halfU, halfV) {
  let pts = [];
  let n = 16;
  for (let i = 0; i < n; i++) {
    let ang = (i / n) * 360;
    let rScale = 1.0 + 0.12 * cos(ang * 2);
    pts.push(F.pt2D(tOff, uCenter + cos(ang) * halfU * rScale, vCenter + sin(ang) * halfV));
  }
  // Tarnished nickel-silver lyre plate
  washPoly(pts, "#59554f", 240, "#141210", 0.55, "rotring");
  let innerPts = [];
  for (let i = 0; i < n; i++) {
    let ang = (i / n) * 360;
    innerPts.push(F.pt2D(tOff, uCenter + cos(ang) * halfU * 0.72, vCenter + sin(ang) * halfV * 0.72));
  }
  washPoly(innerPts, "#260c0e", 230, "#a8a296", 0.5, "liner");

  // Lyre strings & scrolled horns in bright silver-cream
  for (let s = -2; s <= 2; s++) {
    let pTop = F.pt2D(tOff - 0.5, uCenter + s * 8, vCenter + halfV * 0.62);
    let pBot = F.pt2D(tOff - 0.5, uCenter + s * 6, vCenter - halfV * 0.62);
    brush.set("micro_pen", PAL.lacquerWhite, 0.45);
    brush.line(pTop[0], pTop[1], pBot[0], pBot[1]);
  }
  strokePoly(pts, true, "liner", PAL.lacquerSpec, 0.65);
}

function drawCornerHardware(F, t0, t1, w, h, c, vBot) {
  let r0 = F.ring2D(t0, w, h, c, vBot);
  let r1 = F.ring2D(t1, w, h, c, vBot);
  // Nickel-silver corner bracket on Upper-Front Chamfer (3-4) and Lower-Front Chamfer (1-2)
  let metalStops = ["#383a40", "#7c808a", "#d9d4c7", "#54575e"];
  gradedQuad(r0[4], r1[4], r1[3], r0[3], 6, metalStops, "glaze", 0.55, "#4a4c52");
  strokePoly([r0[4], r1[4], r1[3], r0[3]], true, "micro_pen", "#141416", 0.4);
  drawTinyScrew((r0[4][0] + r1[3][0]) * 0.5, (r0[4][1] + r1[3][1]) * 0.5);

  gradedQuad(r0[2], r1[2], r1[1], r0[1], 5, ["#26272b", "#5c5f66", "#2b2c30"], "glaze", 0.5, "#33353a");
}

function drawTinyScrew(x, y) {
  brush.set("rotring", "#120e0a", 0.7);
  brush.line(x - 1.8, y, x + 1.8, y);
  brush.set("liner", PAL.giltBright, 0.65);
  brush.line(x - 1.2, y - 0.8, x + 1.2, y + 0.8);
}

function drawFingerprintSmear(center, rx, ry, angleDeg) {
  let ca = cos(angleDeg), sa = sin(angleDeg);
  // Soft oily marker smudge
  brush.set("glaze", PAL.smearWarm, 0.45);
  brush.line(center[0] - ca * rx * 0.6, center[1] - sa * rx * 0.6, center[0] + ca * rx * 0.6, center[1] + sa * rx * 0.6);

  // Concentric whorled ridge arcs in ultra-fine pen
  for (let r = 0.25; r <= 1.0; r += 0.22) {
    let arcPts = [];
    let aStart = random(-150, -90);
    let aEnd = aStart + random(140, 230);
    for (let a = aStart; a <= aEnd; a += 20) {
      let lx = cos(a) * rx * r;
      let ly = sin(a) * ry * r;
      arcPts.push([
        center[0] + lx * ca - ly * sa,
        center[1] + lx * sa + ly * ca
      ]);
    }
    strokePoly(arcPts, false, "micro_pen", r > 0.6 ? PAL.smearWarm : PAL.smearLight, 0.32);
  }
}

function drawLacquerScuffsAndChips(F, tMin, tMax, w, h, c, vBot) {
  // Fine surface hairline scratches on Front and Top lacquer faces
  for (let i = 0; i < 18; i++) {
    let t1 = random(tMin, tMax);
    let t2 = t1 + random(-18, 18);
    let v1 = random(25, h - 25);
    let v2 = v1 + random(-22, 22);
    let p1 = F.pt2D(t1, w * 0.5, v1);
    let p2 = F.pt2D(t2, w * 0.5, v2);
    brush.set("micro_pen", i % 3 === 0 ? "#6e655c" : "#38332e", 0.3);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Two small chipped-lacquer spots along the lower edge revealing warm walnut wood
  let chip1 = F.pt2D(lerp(tMin, tMax, 0.3), w * 0.5, c + 4);
  let chip2 = F.pt2D(lerp(tMin, tMax, 0.75), w * 0.5 - 8, c - 6);
  for (let ch of [chip1, chip2]) {
    let pts = [
      [ch[0] - 5, ch[1] - 2], [ch[0] + 4, ch[1] - 3],
      [ch[0] + 6, ch[1] + 2], [ch[0] - 3, ch[1] + 3]
    ];
    washPoly(pts, PAL.woodChipDark, 235, PAL.woodChipLight, 0.35, "micro_pen");
    brush.set("micro_pen", "#a67549", 0.35);
    brush.line(ch[0] - 3, ch[1], ch[0] + 3, ch[1] - 1);
  }
}

