function drawAllFileteadoCorners() {
  // Render all 4 corners curling inward toward the bandoneón
  drawFileteadoCorner(false, false); // Top-Left
  drawFileteadoCorner(true,  false); // Top-Right
  drawFileteadoCorner(false, true);  // Bottom-Left
  drawFileteadoCorner(true,  true);  // Bottom-Right

  // Side-center ornamental clasps at (600, 48), (600, 1152), (48, 600), (1152, 600)
  drawCenterBorderClasp(600, 48, false);
  drawCenterBorderClasp(600, 1152, false);
  drawCenterBorderClasp(48, 600, true);
  drawCenterBorderClasp(1152, 600, true);
}

// Transform corner-local (u, v) to canvas (x, y)
function cornerMap(u, v, flipX, flipY) {
  let margin = 38;
  let x = flipX ? (1200 - margin - u) : (margin + u);
  let y = flipY ? (1200 - margin - v) : (margin + v);
  return [x, y];
}

// Shaded Fileteado Whip / Volute / Ribbon Renderer with Crisp Liner & Fine White Highlight Line
function drawFileteadoWhip(spinePts, widthFn, palette, highlightSide = 1, closedTip = true) {
  let n = spinePts.length;
  if (n < 3) return;

  let leftPts = [];
  let rightPts = [];
  let hlPts = [];
  let shadowPoly = [];

  for (let i = 0; i < n; i++) {
    let t = i / (n - 1);
    let p = spinePts[i];
    let pPrev = spinePts[max(0, i - 1)];
    let pNext = spinePts[min(n - 1, i + 1)];
    let dx = pNext[0] - pPrev[0];
    let dy = pNext[1] - pPrev[1];
    let len = sqrt(dx * dx + dy * dy) || 1;
    let nx = -dy / len;
    let ny = dx / len;

    // Ensure normal generally points upward-left for consistent highlight ridge
    let w = widthFn(t);
    leftPts.push([p[0] + nx * w, p[1] + ny * w]);
    rightPts.push([p[0] - nx * w, p[1] - ny * w]);

    if (t >= 0.08 && t <= 0.92) {
      let hw = w * 0.58 * highlightSide;
      hlPts.push([p[0] + nx * hw, p[1] + ny * hw]);
    }
  }

  let poly = leftPts.concat(rightPts.slice().reverse());
  for (let pt of poly) {
    shadowPoly.push([pt[0] + 6, pt[1] + 8]);
  }

  // 1. Trompe-l'œil drop shadow
  washPoly(shadowPoly, "#050203", 175);

  // 2. Base pigment wash
  washPoly(poly, palette.base, 245);

  // 3. Smooth graded marker shading bands along the scroll
  let bands = 5;
  for (let b = 0; b <= bands; b++) {
    let s = b / bands; // 0 = right edge (shadow), 1 = left edge (lit)
    let bandPts = [];
    for (let i = 0; i < n; i++) {
      bandPts.push([
        lerp(rightPts[i][0], leftPts[i][0], s),
        lerp(rightPts[i][1], leftPts[i][1], s)
      ]);
    }
    let col = multiLerpColor([palette.shadow, palette.base, palette.mid, palette.light], s);
    strokePoly(bandPts, false, "glaze", col, 0.55);
  }

  // Base overlap shadow where scroll emerges (t < 0.25)
  let baseDarkL = leftPts.slice(0, floor(n * 0.28));
  let baseDarkR = rightPts.slice(0, floor(n * 0.28));
  if (baseDarkL.length >= 2) {
    washPoly(baseDarkL.concat(baseDarkR.reverse()), palette.shadow, 165);
  }

  // 4. Crisp dark liner contour strokes
  strokePoly(leftPts, false, "liner", "#120808", 0.72);
  strokePoly(rightPts, false, "liner", "#120808", 0.72);

  // 5. Signature Fileteado Porteño Fine White Highlight Line
  if (hlPts.length >= 3) {
    strokePoly(hlPts, false, "liner", PAL.highlightCream, 0.72);
    let hlCore = hlPts.slice(floor(hlPts.length * 0.12), ceil(hlPts.length * 0.85));
    strokePoly(hlCore, false, "micro_pen", PAL.highlightWhite, 0.52);
  }
}

function drawFileteadoCorner(flipX, flipY) {
  let M = (u, v) => cornerMap(u, v, flipX, flipY);
  let hSide = (flipX !== flipY) ? -1 : 1;

  let palGold = {
    shadow: PAL.ochreShadow,
    base: PAL.ochreBase,
    mid: PAL.ochreMid,
    light: PAL.ochreLight
  };
  let palEmerald = {
    shadow: PAL.emeraldShadow,
    base: PAL.emeraldBase,
    mid: PAL.emeraldMid,
    light: PAL.emeraldLight
  };
  let palCarmine = {
    shadow: PAL.carmineShadow,
    base: PAL.carmineBase,
    mid: PAL.carmineMid,
    light: PAL.carmineLight
  };

  // --- LAYER 1: EMERALD ACANTHUS WHIPLASH FRONDS (Curling inward along both axes & diagonal) ---
  // Horizontal Emerald Acanthus Whip
  let emHoriz = sampleBezierChain([
    [M(52, 48), M(115, 18), M(195, 22), M(255, 62)],
    [M(255, 62), M(305, 95), M(355, 92), M(385, 58)],
    [M(385, 58), M(405, 34), M(375, 12), M(352, 28)]
  ], 18);
  drawFileteadoWhip(emHoriz, t => 14 * sin(pow(t, 0.65) * 180) * (1 - 0.35 * t) + 1.2, palEmerald, hSide);

  // Acanthus side-lobe on Horizontal Emerald Whip
  let emLobeH = sampleBezierChain([
    [M(165, 32), M(210, 58), M(245, 108), M(225, 145)],
    [M(225, 145), M(210, 168), M(180, 158), M(190, 135)]
  ], 16);
  drawFileteadoWhip(emLobeH, t => 11 * sin(t * 180) + 1.0, palEmerald, hSide);

  // Vertical Emerald Acanthus Whip
  let emVert = sampleBezierChain([
    [M(48, 52), M(18, 115), M(22, 195), M(62, 255)],
    [M(62, 255), M(95, 305), M(92, 355), M(58, 385)],
    [M(58, 385), M(34, 405), M(12, 375), M(28, 352)]
  ], 18);
  drawFileteadoWhip(emVert, t => 14 * sin(pow(t, 0.65) * 180) * (1 - 0.35 * t) + 1.2, palEmerald, -hSide);

  // Acanthus side-lobe on Vertical Emerald Whip
  let emLobeV = sampleBezierChain([
    [M(32, 165), M(58, 210), M(108, 245), M(145, 225)],
    [M(145, 225), M(168, 210), M(158, 180), M(135, 190)]
  ], 16);
  drawFileteadoWhip(emLobeV, t => 11 * sin(t * 180) + 1.0, palEmerald, -hSide);

  // Central Diagonal Emerald Spear Whip curling toward the bandoneón
  let emDiag = sampleBezierChain([
    [M(65, 65), M(125, 110), M(185, 155), M(238, 218)],
    [M(238, 218), M(268, 252), M(245, 285), M(212, 265)]
  ], 18);
  drawFileteadoWhip(emDiag, t => 13 * sin(t * 180) + 1.0, palEmerald, hSide);

  // --- LAYER 2: GOLD OCHRE SHADED VOLUTES & ACANTHUS WHIPS ---
  // Main Horizontal Gold Ochre S-Volute
  let goldHoriz = sampleBezierChain([
    [M(85, 92), M(62, 68), M(78, 32), M(122, 36)],
    [M(122, 36), M(178, 42), M(225, 86), M(288, 74)],
    [M(288, 74), M(338, 64), M(348, 22), M(312, 16)],
    [M(312, 16), M(285, 12), M(278, 38), M(298, 44)]
  ], 18);
  drawFileteadoWhip(goldHoriz, t => 16 * sin(pow(t, 0.55) * 180) * (1 - 0.25 * t) + 1.4, palGold, hSide);

  // Secondary Gold Acanthus Whip branching inward horizontally
  let goldBranchH = sampleBezierChain([
    [M(145, 46), M(195, 78), M(265, 118), M(318, 102)],
    [M(318, 102), M(348, 92), M(342, 62), M(318, 70)]
  ], 16);
  drawFileteadoWhip(goldBranchH, t => 11 * sin(t * 180) + 1.0, palGold, hSide);

  // Main Vertical Gold Ochre S-Volute
  let goldVert = sampleBezierChain([
    [M(92, 85), M(68, 62), M(32, 78), M(36, 122)],
    [M(36, 122), M(42, 178), M(86, 225), M(74, 288)],
    [M(74, 288), M(64, 338), M(22, 348), M(16, 312)],
    [M(16, 312), M(12, 285), M(38, 278), M(44, 298)]
  ], 18);
  drawFileteadoWhip(goldVert, t => 16 * sin(pow(t, 0.55) * 180) * (1 - 0.25 * t) + 1.4, palGold, -hSide);

  // Secondary Gold Acanthus Whip branching inward vertically
  let goldBranchV = sampleBezierChain([
    [M(46, 145), M(78, 195), M(118, 265), M(102, 318)],
    [M(102, 318), M(92, 348), M(62, 342), M(70, 318)]
  ], 16);
  drawFileteadoWhip(goldBranchV, t => 11 * sin(t * 180) + 1.0, palGold, -hSide);

  // Diagonal Inner Gold Ochre Lyre-Volute Pair framing the corner
  let goldDiag1 = sampleBezierChain([
    [M(78, 78), M(135, 105), M(198, 138), M(208, 185)],
    [M(208, 185), M(216, 218), M(182, 232), M(168, 205)]
  ], 16);
  drawFileteadoWhip(goldDiag1, t => 12.5 * sin(t * 180) + 1.2, palGold, hSide);

  let goldDiag2 = sampleBezierChain([
    [M(78, 78), M(105, 135), M(138, 198), M(185, 208)],
    [M(185, 208), M(218, 216), M(232, 182), M(205, 168)]
  ], 16);
  drawFileteadoWhip(goldDiag2, t => 12.5 * sin(t * 180) + 1.2, palGold, -hSide);

  // --- LAYER 3: TIGHT CARMINE RIBBONS (CINTAS) & VOLUTES ---
  // Dark ribbon fold-unders (drawn just before the carmine ribbons)
  washPoly([M(122, 18), M(148, 14), M(158, 34), M(132, 38)], PAL.carmineShadow, 240, "#080304", 0.5, "liner");
  washPoly([M(18, 122), M(14, 148), M(34, 158), M(38, 132)], PAL.carmineShadow, 240, "#080304", 0.5, "liner");

  // Tight Carmine Ribbon wrapping across the Horizontal Volutes
  let carmRibbonH = sampleBezierChain([
    [M(112, 82), M(118, 42), M(145, 16), M(175, 26)],
    [M(175, 26), M(205, 36), M(212, 78), M(245, 86)],
    [M(245, 86), M(275, 92), M(292, 55), M(268, 42)]
  ], 18);
  drawFileteadoWhip(carmRibbonH, t => 9.5 * (0.65 + 0.35 * sin(t * 180)), palCarmine, hSide);

  // Tight Carmine Ribbon wrapping across the Vertical Volutes
  let carmRibbonV = sampleBezierChain([
    [M(82, 112), M(42, 118), M(16, 145), M(26, 175)],
    [M(26, 175), M(36, 205), M(78, 212), M(86, 245)],
    [M(86, 245), M(92, 275), M(55, 292), M(42, 268)]
  ], 18);
  drawFileteadoWhip(carmRibbonV, t => 9.5 * (0.65 + 0.35 * sin(t * 180)), palCarmine, -hSide);

  // Sweeping Diagonal Carmine Banner Ribbon bridging the corner
  let carmBanner = sampleBezierChain([
    [M(88, 192), M(105, 155), M(132, 128), M(165, 112)],
    [M(165, 112), M(195, 98), M(218, 108), M(235, 92)]
  ], 18);
  drawFileteadoWhip(carmBanner, t => 11.5 * sin(t * 180) + 3.5, palCarmine, hSide);

  // Inner Carmine Volute Curls
  let carmCurl = sampleBezierChain([
    [M(45, 45), M(82, 55), M(128, 82), M(155, 125)],
    [M(155, 125), M(175, 158), M(148, 178), M(128, 155)]
  ], 16);
  drawFileteadoWhip(carmCurl, t => 10.5 * sin(t * 180) + 1.0, palCarmine, hSide);

  // --- LAYER 4: CORNER 5-PETAL TANGO FLOWER & TEARDROP GEM ---
  drawFileteadoRosette(M(68, 68), 26, palCarmine, palGold, palEmerald);
}

function drawFileteadoRosette(center, rad, palCarmine, palGold, palEmerald) {
  // Drop shadow
  let shPts = [];
  for (let a = 0; a < 360; a += 30) {
    shPts.push([center[0] + 5 + cos(a) * rad, center[1] + 7 + sin(a) * rad]);
  }
  washPoly(shPts, "#050203", 180);

  // 5 scalloped carmine petals with graded ochre throats and crisp white highlight arcs
  let petals = 5;
  for (let p = 0; p < petals; p++) {
    let baseAng = p * (360 / petals) - 45;
    let pPts = [center];
    for (let a = -32; a <= 32; a += 8) {
      let r = rad * (0.75 + 0.28 * cos(a * 2.5));
      pPts.push([
        center[0] + cos(baseAng + a) * r,
        center[1] + sin(baseAng + a) * r
      ]);
    }
    washPoly(pPts, palCarmine.base, 245, "#120607", 0.65, "liner");

    // Inner warm highlight & white rim line on each petal
    let tip = [center[0] + cos(baseAng) * rad * 0.65, center[1] + sin(baseAng) * rad * 0.65];
    brush.set("glaze", palCarmine.light, 0.55);
    brush.line(center[0], center[1], tip[0], tip[1]);

    let hlArc = [];
    for (let a = -22; a <= 18; a += 10) {
      let r = rad * 0.82;
      hlArc.push([
        center[0] + cos(baseAng + a) * r,
        center[1] + sin(baseAng + a) * r
      ]);
    }
    strokePoly(hlArc, false, "liner", PAL.highlightCream, 0.65);
  }

  // Gold ochre flower center Cabochon
  let corePts = [];
  for (let a = 0; a < 360; a += 30) {
    corePts.push([center[0] + cos(a) * (rad * 0.34), center[1] + sin(a) * (rad * 0.34)]);
  }
  washPoly(corePts, palGold.mid, 250, "#120806", 0.6, "liner");
  brush.set("liner", PAL.highlightWhite, 0.75);
  brush.line(center[0] - rad * 0.16, center[1] - rad * 0.14, center[0] + rad * 0.08, center[1] - rad * 0.18);
}

function drawCenterBorderClasp(cx, cy, isVertical) {
  let dx = isVertical ? 14 : 42;
  let dy = isVertical ? 42 : 14;

  // Drop shadow
  washPoly([
    [cx - dx + 4, cy + 5], [cx + 4, cy - dy + 5],
    [cx + dx + 4, cy + 5], [cx + 4, cy + dy + 5]
  ], "#050203", 170);

  // Emerald outer diamond
  let dOuter = [[cx - dx, cy], [cx, cy - dy], [cx + dx, cy], [cx, cy + dy]];
  washPoly(dOuter, PAL.emeraldBase, 240, "#100807", 0.6, "liner");

  // Gold ochre inner diamond
  let dInner = [[cx - dx * 0.62, cy], [cx, cy - dy * 0.62], [cx + dx * 0.62, cy], [cx, cy + dy * 0.62]];
  washPoly(dInner, PAL.ochreMid, 245, "#100807", 0.55, "liner");

  // Carmine center jewel & white highlight
  let dCore = [[cx - dx * 0.28, cy], [cx, cy - dy * 0.28], [cx + dx * 0.28, cy], [cx, cy + dy * 0.28]];
  washPoly(dCore, PAL.carmineMid, 250, "#100807", 0.5, "liner");

  brush.set("liner", PAL.highlightWhite, 0.6);
  brush.line(cx - dx * 0.75, cy - 1.5, cx, cy - dy * 0.75 - 1.5);
  brush.line(cx, cy - dy * 0.75 - 1.5, cx + dx * 0.5, cy - 1.5);
}

