function drawScuffedBackdrop(PAL) {
  const plankCount = 6;
  const plankW = width / plankCount;

  // Base painted bands: classic carnival cream-ochre boards with bold painted dado bands
  brush.noStroke();
  for (let p = 0; p < plankCount; p++) {
    let x0 = p * plankW;
    let toneShift = (p % 2 === 0) ? PAL.boardBase : PAL.boardWarm;
    brush.wash(toneShift, 220);
    brush.rect(x0, 0, plankW, 962, "corner");
  }

  // Painted fairground dado stripes across the boards (turquoise, vermilion & chrome yellow)
  brush.noStroke();
  brush.wash(PAL.boardTurquoise, 235);
  brush.rect(0, 0, width, 118, "corner");
  brush.rect(0, 745, width, 74, "corner");

  brush.wash(PAL.chromeYellow, 240);
  brush.rect(0, 118, width, 24, "corner");
  brush.rect(0, 725, width, 20, "corner");
  brush.rect(0, 819, width, 18, "corner");

  brush.wash(PAL.vermilion, 235);
  brush.rect(0, 142, width, 14, "corner");
  brush.rect(0, 837, width, 12, "corner");

  // Heavy vertical brush-drag texture across every plank
  for (let p = 0; p < plankCount; p++) {
    let x0 = p * plankW;

    // Cream & ochre vertical brush-drag streaks
    for (let i = 0; i < 68; i++) {
      let lx = x0 + random(4, plankW - 4);
      let y1 = random(156, 725);
      let y2 = min(725, y1 + random(80, 420));
      let col = random() < 0.45 ? PAL.boardHighlight : (random() < 0.5 ? PAL.boardWarm : "#B89F74");
      brush.set("board_drag", col, random(0.45, 1.35));
      brush.line(lx, y1, lx + random(-1.5, 1.5), y2);
    }

    // Lower board zone brush-drag
    for (let i = 0; i < 28; i++) {
      let lx = x0 + random(4, plankW - 4);
      let y1 = random(849, 958);
      let y2 = min(960, y1 + random(35, 100));
      let col = random() < 0.5 ? PAL.boardHighlight : "#B49B70";
      brush.set("board_drag", col, random(0.4, 1.1));
      brush.line(lx, y1, lx, y2);
    }

    // Turquoise dado brush-drag streaks
    for (let i = 0; i < 26; i++) {
      let lx = x0 + random(4, plankW - 4);
      let col = random() < 0.5 ? PAL.boardTurqLight : "#1D5669";
      brush.set("board_drag", col, random(0.4, 1.1));
      brush.line(lx, random(0, 45), lx, random(65, 116));
      brush.line(lx, random(746, 775), lx, random(785, 818));
    }

    // Dry-brush woodgrain scuffing with charcoal/pencil
    for (let i = 0; i < 35; i++) {
      let lx = x0 + random(6, plankW - 6);
      let y1 = random(20, 940);
      let len = random(30, 140);
      brush.set("2B", PAL.rawWoodLight, random(0.25, 0.55));
      brush.line(lx, y1, lx + random(-1, 1), min(958, y1 + len));
    }
  }

  // Chipped gloss enamel patches revealing muted raw earth wood underneath
  drawChippedPaintPatches(PAL, plankCount, plankW);

  // Deep vertical plank seams, chamfered highlights & rusty nail holes
  for (let p = 1; p < plankCount; p++) {
    let sx = p * plankW;

    // Bevel shadow left of seam
    brush.set("charcoal", PAL.rawWoodMid, 0.9);
    brush.line(sx - 3, 0, sx - 3, 962);

    // Thick dark gap
    brush.set("rotring", PAL.huskDeep, 1.9);
    brush.line(sx, 0, sx, 962);
    brush.set("pen", PAL.rawWoodDark, 1.2);
    brush.line(sx + 1.5, 0, sx + 1.5, 962);

    // Gloss paint buildup ridge right of seam
    brush.set("pen", PAL.boardHighlight, 0.95);
    brush.line(sx + 4, 0, sx + 4, 962);

    // Double nail holes at top, dado, and bottom of each plank
    let nailYs = [42, 185, 782, 922];
    for (let ny of nailYs) {
      for (let side of [-22, 22]) {
        let nx = sx + side + random(-2, 2);
        // Chipped wood pocket around nail
        brush.noStroke();
        brush.wash(PAL.rawWoodDark, 230);
        brush.circle(nx, ny, 5.5, 0.25);
        // Rust bleed downward
        brush.set("board_drag", PAL.huskSienna, 0.35);
        brush.line(nx, ny + 3, nx, ny + random(18, 42));
        // Deep nail head
        brush.set("rotring", PAL.huskDeep, 1.1);
        brush.circle(nx, ny, 3.2, 0.1);
        // Lip highlight
        brush.set("pen", PAL.boardHighlight, 0.6);
        brush.arc(nx, ny, 5.5, 20, 150);
      }
    }
  }

  // Ball impact dents on the board (where stray wooden balls missed the coconuts!)
  const dents = [
    { x: 418, y: 390, r: 24 },
    { x: 785, y: 330, r: 21 },
    { x: 112, y: 540, r: 19 },
    { x: 1095, y: 455, r: 23 },
    { x: 432, y: 610, r: 17 },
    { x: 768, y: 565, r: 22 }
  ];
  for (let d of dents) {
    // Crushed wood core
    brush.noStroke();
    brush.wash(PAL.rawWoodMid, 210);
    brush.circle(d.x, d.y, d.r, 0.35);
    brush.wash(PAL.rawWoodDark, 180);
    brush.circle(d.x - 3, d.y - 3, d.r * 0.65, 0.3);

    // Radial cracked enamel lines around impact
    brush.set("rotring", PAL.rawWoodDark, 0.55);
    for (let a = 0; a < 360; a += random(28, 52)) {
      let r1 = d.r * 0.5;
      let r2 = d.r * random(1.05, 1.45);
      brush.line(
        d.x + cos(a) * r1,
        d.y + sin(a) * r1,
        d.x + cos(a) * r2,
        d.y + sin(a) * r2
      );
    }
    // Thick chipped white/cream paint rim on lower right
    brush.set("pen", PAL.enamelWhite, 0.95);
    brush.arc(d.x, d.y, d.r, -20, 140);
  }
}

function drawChippedPaintPatches(PAL, plankCount, plankW) {
  // Long vertical paint peels along plank edges + scattered flakes
  let chips = [];

  for (let p = 0; p < plankCount; p++) {
    let seamX = p * plankW;
    for (let k = 0; k < 7; k++) {
      chips.push({
        x: seamX + random(-6, 12),
        y: random(30, 930),
        w: random(10, 28),
        h: random(35, 130)
      });
    }
    // Mid-plank chips
    for (let k = 0; k < 5; k++) {
      chips.push({
        x: seamX + random(35, plankW - 35),
        y: random(50, 920),
        w: random(12, 34),
        h: random(18, 65)
      });
    }
  }

  for (let c of chips) {
    let pts = [
      [c.x, c.y],
      [c.x + c.w * random(0.6, 1.1), c.y + c.h * 0.12],
      [c.x + c.w, c.y + c.h * 0.55],
      [c.x + c.w * random(0.5, 0.9), c.y + c.h],
      [c.x + c.w * 0.1, c.y + c.h * 0.88],
      [c.x - c.w * 0.15, c.y + c.h * 0.4]
    ];

    // Raw muted earth wood inside chip
    brush.noStroke();
    brush.wash(PAL.rawWoodMid, 235);
    brush.beginShape(0.05);
    for (let pt of pts) brush.vertex(pt[0], pt[1]);
    brush.endShape(true);

    // Wood grain lines inside exposed chip
    brush.set("rotring", PAL.rawWoodDark, 0.45);
    for (let gx = c.x + 2; gx < c.x + c.w - 2; gx += 3.5) {
      brush.line(gx, c.y + c.h * 0.15, gx, c.y + c.h * 0.85);
    }

    // Crisp shadow along top/left lip of paint thickness
    brush.set("rotring", PAL.huskDeep, 0.65);
    brush.line(pts[5][0], pts[5][1], pts[0][0], pts[0][1]);
    brush.line(pts[0][0], pts[0][1], pts[1][0], pts[1][1]);

    // Bright gloss paint thickness highlight on bottom/right edge
    brush.set("pen", PAL.pureEnamel, 0.85);
    brush.line(pts[1][0], pts[1][1], pts[2][0], pts[2][1]);
    brush.line(pts[2][0], pts[2][1], pts[3][0], pts[3][1]);
    brush.line(pts[3][0], pts[3][1], pts[4][0], pts[4][1]);
  }
}

// =============================================================================
// 2. COUNTER LEDGE / WOODEN RAIL
// =============================================================================
function drawCounterLedge(PAL, topY) {
  const lipH = 44;

  // Top horizontal plane of the wooden counter rail (receding slightly)
  brush.noStroke();
  brush.wash("#8F6D4D", 250);
  brush.rect(0, topY - 26, width, 28, "corner");

  // Scuffed vermilion & raw wood front face of the beam
  brush.wash(PAL.rawWoodDark, 255);
  brush.rect(0, topY, width, height - topY, "corner");

  // Painted vermilion & chrome yellow fairground fascia below the lip
  brush.wash(PAL.vermilionDark, 230);
  brush.rect(0, topY + lipH, width, height - (topY + lipH), "corner");

  // Chrome yellow molding strip
  brush.wash(PAL.chromeYellow, 240);
  brush.rect(0, topY + lipH, width, 18, "corner");

  // Horizontal brush-drag along top lip and beam face
  for (let i = 0; i < 95; i++) {
    let y = random(topY - 24, topY + lipH - 2);
    let x1 = random(0, width - 150);
    let x2 = min(width, x1 + random(120, 420));
    let col = y < topY
      ? (random() < 0.5 ? "#B89672" : PAL.rawWoodMid)
      : (random() < 0.6 ? PAL.rawWoodMid : "#75553B");
    brush.set("board_drag", col, random(0.45, 1.15));
    brush.line(x1, y, x2, y + random(-1, 1));
  }

  // Scuffed drag on lower vermilion fascia
  for (let i = 0; i < 75; i++) {
    let y = random(topY + lipH + 20, height - 4);
    let x1 = random(0, width - 120);
    let x2 = min(width, x1 + random(100, 380));
    let col = random() < 0.5 ? PAL.vermilion : (random() < 0.5 ? PAL.rawWoodDark : "#B32010");
    brush.set("board_drag", col, random(0.5, 1.3));
    brush.line(x1, y, x2, y);
  }

  // Crisp edge highlight along front corner of timber rail
  brush.set("flat_stripe", PAL.boardHighlight, 0.55);
  brush.line(0, topY, width, topY);
  brush.set("rotring", PAL.huskDeep, 1.1);
  brush.line(0, topY - 26, width, topY - 26);
  brush.line(0, topY + lipH, width, topY + lipH);
  brush.line(0, topY + lipH + 18, width, topY + lipH + 18);
}

// =============================================================================
// 3. HARD OFFSET DROP-SHADOWS IN DEEP ULTRAMARINE
// =============================================================================
function drawUltramarineDropShadow(shy, off, PAL) {
  const sx = shy.cx + off.x;
  const syCoco = shy.cocoY + off.y;
  const syCupTop = shy.cupTopY + off.y;
  const syCupBot = min(960, shy.cupBotY + 18);

  // 1) Cast shadow of coconut onto the vertical board backdrop
  let cocoShadowPts = [];
  const steps = 48;
  for (let i = 0; i < steps; i++) {
    let a = map(i, 0, steps, 0, 360);
    let rad = getCoconutRadiusAtAngle(a, shy.cocoRx, shy.cocoRy, shy.seed);
    let px = cos(a) * rad;
    let py = sin(a) * rad;
    let rotX = px * cos(shy.tilt) - py * sin(shy.tilt);
    let rotY = px * sin(shy.tilt) + py * cos(shy.tilt);
    cocoShadowPts.push([sx + rotX, syCoco + rotY]);
  }

  brush.noStroke();
  brush.wash(PAL.ultramarine, 235);
  brush.beginShape(0.15);
  for (let pt of cocoShadowPts) brush.vertex(pt[0], pt[1]);
  brush.endShape(true);

  // Second pass inner core in deeper ultramarine for rich sign-enamel density
  brush.wash(PAL.ultraDeep, 150);
  brush.beginShape(0.15);
  for (let pt of cocoShadowPts) {
    brush.vertex(
      lerp(sx, pt[0], 0.92),
      lerp(syCoco, pt[1], 0.92)
    );
  }
  brush.endShape(true);

  // Crisp sign-painter ultramarine outline + fibrous shadow whiskers jutting from silhouette
  brush.set("flat_stripe", PAL.ultramarine, 0.65);
  brush.beginShape(0.15);
  for (let pt of cocoShadowPts) brush.vertex(pt[0], pt[1]);
  brush.endShape(true);

  // Hard ultramarine shadow of spiky husk tufts around the coconut shadow
  randomSeed(shy.seed + 500);
  for (let i = 0; i < 95; i++) {
    let a = random(360);
    let rad = getCoconutRadiusAtAngle(a, shy.cocoRx, shy.cocoRy, shy.seed);
    let px = cos(a) * (rad - 4);
    let py = sin(a) * (rad - 4);
    let x1 = sx + px * cos(shy.tilt) - py * sin(shy.tilt);
    let y1 = syCoco + px * sin(shy.tilt) + py * cos(shy.tilt);

    let outLen = random(14, 44) * (abs( sin(a) ) > 0.7 ? 1.35 : 0.85);
    let outAng = a + shy.tilt + random(-22, 22);
    let mx = x1 + cos(outAng) * outLen * 0.55;
    let my = y1 + sin(outAng) * outLen * 0.55;
    let x2 = x1 + cos(outAng + random(-18, 18)) * outLen;
    let y2 = y1 + sin(outAng + random(-18, 18)) * outLen;

    brush.set("pen", PAL.ultramarine, random(0.65, 1.35));
    brush.spline([[x1, y1, 1.0], [mx, my, 0.7], [x2, y2, 0.15]], 0.5);
  }

  // 2) Cast shadow of the turned wooden cup onto the board backdrop
  let cupOutline = getCupProfilePoints(sx, syCupTop, syCupBot, 1.02);
  brush.noStroke();
  brush.wash(PAL.ultramarine, 235);
  brush.beginShape(0.05);
  for (let pt of cupOutline) brush.vertex(pt[0], pt[1]);
  brush.endShape(true);

  brush.set("flat_stripe", PAL.ultramarine, 0.55);
  brush.beginShape(0.05);
  for (let pt of cupOutline) brush.vertex(pt[0], pt[1]);
  brush.endShape(true);

  // 3) Cast shadow across the horizontal counter ledge at the cup base
  brush.noStroke();
  brush.wash(PAL.ultraDeep, 230);
  brush.beginShape(0.1);
  brush.vertex(shy.cx - 45, shy.cupBotY - 6);
  brush.vertex(shy.cx + 75, shy.cupBotY - 12);
  brush.vertex(shy.cx + 128, shy.cupBotY + 2);
  brush.vertex(shy.cx + 128, shy.cupBotY + 44);
  brush.vertex(shy.cx + 22, shy.cupBotY + 44);
  brush.vertex(shy.cx + 8, shy.cupBotY + 2);
  brush.endShape(true);
}

// =============================================================================
// 4. STRIPED WOODEN CUPS (Vermilion, Chrome Yellow & White Enamel Marker)
// =============================================================================
function getCupWidthAtT(t) {
  // t from 0 (top lip) to 1 (base plinth on rail)
  // Turned fairground goblet/chalice silhouette:
  // 0.00 - 0.08: thick rolled top rim (w ≈ 98)
  // 0.08 - 0.52: tapered cup bowl (w goes from 92 down to 37)
  // 0.52 - 0.62: turned decorative wooden collar/knop (bulges to 48)
  // 0.62 - 0.82: stem flaring gently (36 to 52)
  // 0.82 - 1.00: stepped circular wooden base flange (flares to 78)
  if (t < 0.08) {
    let u = t / 0.08;
    return 95 + sin(u * 180) * 6;
  } else if (t < 0.52) {
    let u = (t - 0.08) / 0.44;
    return lerp(92, 36, pow(u, 0.78));
  } else if (t < 0.63) {
    let u = (t - 0.52) / 0.11;
    return 36 + sin(u * 180) * 12;
  } else if (t < 0.82) {
    let u = (t - 0.63) / 0.19;
    return lerp(36, 50, u * u);
  } else {
    let u = (t - 0.82) / 0.18;
    return lerp(50, 78, pow(u, 0.55));
  }
}

function getCupProfilePoints(cx, topY, botY, scaleW = 1.0) {
  let leftPts = [];
  let rightPts = [];
  const n = 28;
  for (let i = 0; i <= n; i++) {
    let t = i / n;
    let y = lerp(topY, botY, t);
    let w = getCupWidthAtT(t) * scaleW;
    let sag = 10;
    leftPts.push([cx - w, y]);
    rightPts.unshift([cx + w, y]);
  }
  return leftPts.concat(rightPts);
}

function drawStripedCup(shy, PAL) {
  const cx = shy.cx;
  const topY = shy.cupTopY;
  const botY = shy.cupBotY;

  // Number of radial vertical stripes visible across front 180 degrees of the turned cup
  // Alternating Vermilion, Enamel White, Chrome Yellow, Enamel White
  const stripeColors = [
    PAL.vermilion,
    PAL.enamelWhite,
    PAL.chromeYellow,
    PAL.enamelWhite,
    PAL.vermilion,
    PAL.enamelWhite,
    PAL.chromeYellow,
    PAL.enamelWhite,
    PAL.vermilion
  ];
  const numStripes = stripeColors.length;
  const rowSteps = 26;

  // 1) Draw bold flat marker stripes mapped onto the 3D turned cylinder
  for (let s = 0; s < numStripes; s++) {
    let a1 = map(s, 0, numStripes, 180, 0);
    let a2 = map(s + 1, 0, numStripes, 180, 0);
    let col = stripeColors[s];

    let poly = [];
    for (let r = 0; r <= rowSteps; r++) {
      let t = r / rowSteps;
      let w = getCupWidthAtT(t);
      let yBase = lerp(topY, botY, t);
      let sag = lerp(14, 18, t);
      let x = cx + cos(a1) * w;
      let y = yBase + sin(a1) * sag;
      poly.push([x, y]);
    }
    for (let r = rowSteps; r >= 0; r--) {
      let t = r / rowSteps;
      let w = getCupWidthAtT(t);
      let yBase = lerp(topY, botY, t);
      let sag = lerp(14, 18, t);
      let x = cx + cos(a2) * w;
      let y = yBase + sin(a2) * sag;
      poly.push([x, y]);
    }

    // Flat opaque wash + bold marker strokes filling the stripe
    brush.noStroke();
    brush.wash(col, 250);
    brush.beginShape(0.02);
    for (let pt of poly) brush.vertex(pt[0], pt[1]);
    brush.endShape(true);

    // Bold vertical marker pass along the center of each stripe for authentic marker sheen
    let aMid = (a1 + a2) * 0.5;
    let markerPts = [];
    for (let r = 0; r <= rowSteps; r += 2) {
      let t = r / rowSteps;
      let w = getCupWidthAtT(t);
      let yBase = lerp(topY, botY, t);
      let sag = lerp(14, 18, t);
      markerPts.push([cx + cos(aMid) * w, yBase + sin(aMid) * sag]);
    }
    brush.set("flat_stripe", col, 1.35);
    brush.spline(markerPts, 0.25);

    // Crisp hand-painted stripe divider line
    if (s > 0) {
      let edgePts = [];
      for (let r = 0; r <= rowSteps; r += 2) {
        let t = r / rowSteps;
        let w = getCupWidthAtT(t);
        let yBase = lerp(topY, botY, t);
        let sag = lerp(14, 18, t);
        edgePts.push([cx + cos(a1) * w, yBase + sin(a1) * sag]);
      }
      brush.set("rotring", PAL.huskUmber, 0.65);
      brush.spline(edgePts, 0.2);
    }
  }

  // 2) Turned horizontal wood lathe rings (rim, waist collar, base steps)
  const ringTs = [0.08, 0.52, 0.575, 0.63, 0.82, 0.91, 1.0];
  for (let rt of ringTs) {
    let w = getCupWidthAtT(rt);
    let yBase = lerp(topY, botY, rt);
    let sag = lerp(14, 18, rt);
    let ringPts = [];
    for (let a = 180; a >= 0; a -= 12) {
      ringPts.push([cx + cos(a) * w, yBase + sin(a) * sag]);
    }
    brush.set("rotring", PAL.rawWoodDark, 0.85);
    brush.spline(ringPts, 0.3);

    // Subtle highlight immediately below each turned groove
    let hiPts = [];
    for (let a = 165; a >= 70; a -= 15) {
      hiPts.push([cx + cos(a) * w, yBase + sin(a) * sag + 2.5]);
    }
    brush.set("pen", PAL.pureEnamel, 0.75);
    brush.spline(hiPts, 0.3);
  }

  // 3) Hard Ultramarine & Umber Cylindrical Form Shadow on the Right Side of the Cup
  let rightShadowPoly = [];
  for (let r = 0; r <= rowSteps; r++) {
    let t = r / rowSteps;
    let w = getCupWidthAtT(t);
    let yBase = lerp(topY, botY, t);
    let sag = lerp(14, 18, t);
    let aShadowEdge = 54 + sin(t * 360) * 4;
    rightShadowPoly.push([cx + cos(aShadowEdge) * w, yBase + sin(aShadowEdge) * sag]);
  }
  for (let r = rowSteps; r >= 0; r--) {
    let t = r / rowSteps;
    let w = getCupWidthAtT(t);
    let yBase = lerp(topY, botY, t);
    let sag = lerp(14, 18, t);
    rightShadowPoly.push([cx + w, yBase]);
  }
  brush.noStroke();
  brush.wash(PAL.ultramarine, 130);
  brush.beginShape(0.05);
  for (let pt of rightShadowPoly) brush.vertex(pt[0], pt[1]);
  brush.endShape(true);

  // 4) Cast shadow of the coconut directly onto the top rim and upper bowl of the cup
  let rimCastPts = [];
  for (let a = 172; a >= 0; a -= 10) {
    let w = getCupWidthAtT(0.0);
    rimCastPts.push([cx + cos(a) * w, topY + sin(a) * 14]);
  }
  for (let a = 0; a <= 172; a += 10) {
    let depthT = map(sin(a), 0, 1, 0.06, 0.21) + (a < 90 ? 0.08 : -0.02);
    let w = getCupWidthAtT(depthT);
    let yBase = lerp(topY, botY, depthT);
    rimCastPts.push([cx + cos(a) * w, yBase + sin(a) * 15]);
  }
  brush.noStroke();
  brush.wash(PAL.ultramarine, 195);
  brush.beginShape(0.1);
  for (let pt of rimCastPts) brush.vertex(pt[0], pt[1]);
  brush.endShape(true);

  // Dark inner wooden hollow of the cup mouth
  let mouthPts = [];
  for (let a = 0; a < 360; a += 15) {
    mouthPts.push([cx + cos(a) * 86, topY + sin(a) * 11]);
  }
  brush.noStroke();
  brush.wash(PAL.huskDeep, 245);
  brush.beginShape(0.2);
  for (let pt of mouthPts) brush.vertex(pt[0], pt[1]);
  brush.endShape(true);

  // 5) Chipped enamel scars on the wooden cup (showing raw earth wood underneath)
  randomSeed(shy.seed + 88);
  for (let k = 0; k < 7; k++) {
    let t = random(0.06, 0.88);
    let a = random(25, 160);
    let w = getCupWidthAtT(t);
    let yBase = lerp(topY, botY, t);
    let chipX = cx + cos(a) * w;
    let chipY = yBase + sin(a) * 15;
    let cw = random(9, 20);
    let ch = random(5, 11);

    brush.noStroke();
    brush.wash(PAL.rawWoodDark, 235);
    brush.rect(chipX - cw * 0.5, chipY - ch * 0.5, cw, ch, "corner");
    brush.set("pen", PAL.pureEnamel, 0.75);
    brush.line(chipX - cw * 0.5, chipY + ch * 0.5, chipX + cw * 0.5, chipY + ch * 0.5);
  }

  // 6) Confident sign-writer's white enamel specular flicks along the left side of the cup & rim
  let cupFlick1 = [];
  for (let r = 2; r <= 12; r++) {
    let t = r / rowSteps;
    let w = getCupWidthAtT(t);
    let yBase = lerp(topY, botY, t);
    cupFlick1.push([cx + cos(142) * w, yBase + sin(142) * 15, map(r, 2, 12, 1.1, 0.2)]);
  }
  brush.set("sign_chisel", PAL.pureEnamel, 0.75);
  brush.spline(cupFlick1, 0.3);

  // Rim highlight flick
  brush.set("sign_chisel", PAL.pureEnamel, 0.65);
  brush.spline([
    [cx - 82, topY + 6, 0.9],
    [cx - 52, topY + 12, 1.1],
    [cx - 18, topY + 14, 0.2]
  ], 0.35);

  // Crisp showman outer contour of the cup
  let leftEdge = [];
  let rightEdge = [];
  for (let r = 0; r <= rowSteps; r += 2) {
    let t = r / rowSteps;
    let w = getCupWidthAtT(t);
    let yBase = lerp(topY, botY, t);
    leftEdge.push([cx - w, yBase]);
    rightEdge.push([cx + w, yBase]);
  }
  brush.set("rotring", PAL.huskDeep, 1.25);
  brush.spline(leftEdge, 0.25);
  brush.spline(rightEdge, 0.25);

  // Heavy iron mounting bolts at the base flange
  for (let ba of [150, 90, 30]) {
    let bx = cx + cos(ba) * 68;
    let by = botY + sin(ba) * 16 - 4;
    brush.noStroke();
    brush.wash(PAL.ironDark, 245);
    brush.circle(bx, by, 6.5, 0.15);
    brush.set("pen", PAL.pureEnamel, 0.75);
    brush.arc(bx, by, 5.5, 190, 320);
  }
}

// =============================================================================
// 5. HYPERREAL HAIRY COCONUTS + SIGN-WRITER'S ENAMEL HIGHLIGHT FLICK
// =============================================================================
function getCoconutRadiusAtAngle(a, rx, ry, seed) {
  // Natural drupe asymmetry: slightly pointed apex at top (-90 deg) and three-lobed base
  let radX = cos(a) * rx;
  let radY = sin(a) * ry;
  let baseR = sqrt(radX * radX + radY * radY);

  // Pointed fibrous crown at top (a ≈ -90 / 270)
  let topPeak = exp(-pow(angleDiff(a, 270) / 38, 2)) * 16;
  // Slightly boxy shoulder lumps
  let shoulders = cos(a * 3 + seed) * 3.5 + sin(a * 2 - seed) * 2.8;
  return baseR + topPeak + shoulders;
}

function angleDiff(a, b) {
  let d = (a - b + 540) % 360 - 180;
  return d;
}

// Project 3D spherical/ovoid coordinates (lat -90..90, lon -90..90) onto tilted 2D coconut
function projectCocoPoint(lat, lon, shy) {
  // lat: -90 (top pole) to +90 (bottom pole nestled in cup)
  // lon: -90 (left limb) to +90 (right limb)
  let yNorm = sin(lat);
  let ringR = cos(lat);
  let xNorm = sin(lon) * ringR;
  let zNorm = cos(lon) * ringR; // depth towards viewer

  // Taper top apex into a natural coconut point
  let topPinch = lat < -25 ? map(lat, -25, -90, 1.0, 0.35) : 1.0;
  let px = xNorm * shy.cocoRx * topPinch;
  let py = yNorm * shy.cocoRy;
  if (lat < -45) {
    py -= map(lat, -45, -90, 0, 14);
  }

  // Longitudinal central seam ridge of the coconut husk (around lon = 12 deg)
  let ridgeBulge = exp(-pow((lon - 12) / 18, 2)) * 7 * ringR;
  px += ridgeBulge * 0.45;
  py -= ridgeBulge * 0.25;

  // Apply coconut tilt
  let rx = px * cos(shy.tilt) - py * sin(shy.tilt);
  let ry = px * sin(shy.tilt) + py * cos(shy.tilt);

  return {
    x: shy.cx + rx,
    y: shy.cocoY + ry,
    z: zNorm
  };
}

function drawHyperrealCoconut(shy, PAL) {
  randomSeed(shy.seed);
  noiseSeed(shy.seed);

  // 1) Base silhouette & solid earthy underpainting
  let hullPts = [];
  const hullSteps = 56;
  for (let i = 0; i < hullSteps; i++) {
    let a = map(i, 0, hullSteps, 0, 360);
    let rad = getCoconutRadiusAtAngle(a, shy.cocoRx, shy.cocoRy, shy.seed);
    let px = cos(a) * rad;
    let py = sin(a) * rad;
    let rx = px * cos(shy.tilt) - py * sin(shy.tilt);
    let ry = px * sin(shy.tilt) + py * cos(shy.tilt);
    hullPts.push([shy.cx + rx, shy.cocoY + ry]);
  }

  // Deep umber base wash
  brush.noStroke();
  brush.wash(PAL.huskUmber, 252);
  brush.beginShape(0.15);
  for (let pt of hullPts) brush.vertex(pt[0], pt[1]);
  brush.endShape(true);

  // Warm sienna & ochre midtone zone on upper-left sunlit hemisphere
  let midPts = [];
  for (let a = 115; a <= 335; a += 12) {
    let rad = getCoconutRadiusAtAngle(a, shy.cocoRx * 0.92, shy.cocoRy * 0.92, shy.seed);
    let px = cos(a) * rad - 8;
    let py = sin(a) * rad - 10;
    let rx = px * cos(shy.tilt) - py * sin(shy.tilt);
    let ry = px * sin(shy.tilt) + py * cos(shy.tilt);
    midPts.push([shy.cx + rx, shy.cocoY + ry]);
  }
  brush.wash(PAL.huskSienna, 220);
  brush.beginShape(0.2);
  for (let pt of midPts) brush.vertex(pt[0], pt[1]);
  brush.endShape(true);

  // Sunlit ochre dome on upper-left
  let lightPts = [];
  for (let a = 155; a <= 295; a += 15) {
    let rad = getCoconutRadiusAtAngle(a, shy.cocoRx * 0.68, shy.cocoRy * 0.68, shy.seed);
    let px = cos(a) * rad - 18;
    let py = sin(a) * rad - 22;
    let rx = px * cos(shy.tilt) - py * sin(shy.tilt);
    let ry = px * sin(shy.tilt) + py * cos(shy.tilt);
    lightPts.push([shy.cx + rx, shy.cocoY + ry]);
  }
  brush.wash(PAL.huskOchre, 210);
  brush.beginShape(0.25);
  for (let pt of lightPts) brush.vertex(pt[0], pt[1]);
  brush.endShape(true);

  // Deep espresso core shadow on right/bottom hemisphere
  let corePts = [];
  for (let a = -55; a <= 115; a += 12) {
    let rad = getCoconutRadiusAtAngle(a, shy.cocoRx * 0.96, shy.cocoRy * 0.96, shy.seed);
    let px = cos(a) * rad;
    let py = sin(a) * rad;
    let rx = px * cos(shy.tilt) - py * sin(shy.tilt);
    let ry = px * sin(shy.tilt) + py * cos(shy.tilt);
    corePts.push([shy.cx + rx, shy.cocoY + ry]);
  }
  for (let lat = 65; lat >= -45; lat -= 18) {
    let p = projectCocoPoint(lat, 18, shy);
    corePts.push([p.x, p.y]);
  }
  brush.wash(PAL.huskDeep, 210);
  brush.beginShape(0.2);
  for (let pt of corePts) brush.vertex(pt[0], pt[1]);
  brush.endShape(true);

  // Warm vermilion & chrome-yellow reflected bounce light along the bottom edge from the cup!
  let bouncePts = [];
  for (let lon = -65; lon <= 65; lon += 16) {
    let p = projectCocoPoint(68, lon, shy);
    bouncePts.push([p.x, p.y]);
  }
  brush.set("board_drag", PAL.vermilionBright, 0.9);
  brush.spline(bouncePts, 0.35);
  brush.set("board_drag", PAL.chromeYellow, 0.75);
  brush.spline(bouncePts, 0.35);

  // 2) OBSESSIVE FIBROUS PEN WORK (Multi-layered 3D meridian coir strands)
  // Light direction in (lat, lon) space is roughly lat = -28, lon = -38
  const totalStrands = 920;
  for (let s = 0; s < totalStrands; s++) {
    let latStart = random(-86, 62);
    let latSpan = random(18, 46);
    let latEnd = min(86, latStart + latSpan);
    let latMid = (latStart + latEnd) * 0.5;

    let lonBase = random(-88, 88);
    // Clump fibers slightly into natural braided husk bundles
    let bundleWave = (noise(lonBase * 0.08, latStart * 0.05, shy.seed) - 0.5) * 22;
    let lon1 = constrain(lonBase, -89, 89);
    let lon2 = constrain(lonBase + bundleWave * 0.5, -89, 89);
    let lon3 = constrain(lonBase + bundleWave, -89, 89);

    let p1 = projectCocoPoint(latStart, lon1, shy);
    let p2 = projectCocoPoint(latMid, lon2, shy);
    let p3 = projectCocoPoint(latEnd, lon3, shy);

    // Illumination calculation relative to upper-left light source (lat = -28, lon = -38)
    let dLight = dist(latMid, lon2, -28, -38);
    let col;
    let brushName = "husk_pen";
    let w = random(0.55, 1.35);

    if (dLight < 36) {
      let r = random();
      if (r < 0.32) col = PAL.huskPale;
      else if (r < 0.68) col = PAL.huskStraw;
      else if (r < 0.9) col = PAL.huskOchre;
      else col = PAL.huskSienna;
    } else if (dLight < 68) {
      let r = random();
      if (r < 0.22) col = PAL.huskStraw;
      else if (r < 0.55) col = PAL.huskOchre;
      else if (r < 0.82) col = PAL.huskRust;
      else col = PAL.huskDeep;
    } else if (latMid > 52) {
      // Reflected cup light zone at the bottom of the husk
      let r = random();
      if (r < 0.28) col = PAL.chromeYellow;
      else if (r < 0.52) col = PAL.vermilion;
      else if (r < 0.78) col = PAL.huskUmber;
      else col = PAL.huskDeep;
    } else {
      // Shadow side
      let r = random();
      if (r < 0.58) col = PAL.huskDeep;
      else if (r < 0.85) col = PAL.huskUmber;
      else if (r < 0.95) col = PAL.huskSienna;
      else col = PAL.ultramarine; // cool reflected shadow hair
    }

    if (random() < 0.35) {
      brushName = "rotring";
      w = random(0.45, 0.95);
    }

    brush.set(brushName, col, w);
    brush.spline([
      [p1.x, p1.y, random(0.3, 0.8)],
      [p2.x, p2.y, random(0.9, 1.3)],
      [p3.x, p3.y, random(0.2, 0.7)]
    ], 0.45);
  }

  // 3) THE THREE DARK GERMINATION PORES ("EYES") OR CENTRAL HUSK RIDGE KNOTS
  // Positioned near the upper-right / crown where the husk parts slightly
  const eyeOffsets = [
    { lat: -38, lon: -6, r: 9.5 },
    { lat: -24, lon: 14, r: 8.5 },
    { lat: -44, lon: 22, r: 7.5 }
  ];
  for (let eo of eyeOffsets) {
    let ep = projectCocoPoint(eo.lat, eo.lon, shy);
    brush.noStroke();
    brush.wash(PAL.huskDeep, 245);
    brush.circle(ep.x, ep.y, eo.r, 0.35);

    // Swirling fibrous ring around each pore
    for (let k = 0; k < 16; k++) {
      let a1 = k * 22.5;
      let a2 = a1 + 55;
      let r1 = eo.r * random(0.75, 1.35);
      let r2 = eo.r * random(0.9, 1.55);
      brush.set("rotring", k % 2 === 0 ? PAL.huskDeep : PAL.huskStraw, 0.65);
      brush.line(
        ep.x + cos(a1) * r1,
        ep.y + sin(a1) * r1,
        ep.x + cos(a2) * r2,
        ep.y + sin(a2) * r2
      );
    }
  }

  // 4) WILD UNRAVELED COIR FIBERS & TORN HUSK STRANDS JUTTING OFF THE SILHOUETTE
  // Especially dense at the top crown peak, rough sides, and bottom where it nests in the cup
  for (let i = 0; i < 240; i++) {
    let a = random(360);
    // Bias slightly toward top crown (270 deg) and bottom cup rim (90 deg)
    if (random() < 0.35) a = random(235, 305);
    else if (random() < 0.25) a = random(40, 140);

    let rad = getCoconutRadiusAtAngle(a, shy.cocoRx, shy.cocoRy, shy.seed);
    let px = cos(a) * (rad - random(2, 14));
    let py = sin(a) * (rad - random(2, 14));
    let x1 = shy.cx + px * cos(shy.tilt) - py * sin(shy.tilt);
    let y1 = shy.cocoY + px * sin(shy.tilt) + py * cos(shy.tilt);

    let isCrown = abs(angleDiff(a, 270)) < 38;
    let isCupLip = abs(angleDiff(a, 90)) < 48;
    let len = isCrown
      ? random(24, 68)
      : (isCupLip ? random(16, 46) : random(10, 38));

    let worldAng = a + shy.tilt + random(-28, 28);
    if (isCrown) worldAng = -90 + shy.tilt + random(-36, 36);
    if (isCupLip) worldAng = 90 + random(-55, 55); // splaying out over the painted cup lip!

    let curl = random(-38, 38);
    let mx = x1 + cos(worldAng) * (len * 0.52);
    let my = y1 + sin(worldAng) * (len * 0.52);
    let x2 = mx + cos(worldAng + curl) * (len * 0.52);
    let y2 = my + sin(worldAng + curl) * (len * 0.52);

    // Choose sunlit straw vs dark ink outline fiber based on angle
    let isSunlitSide = a > 135 && a < 305;
    let col;
    if (isSunlitSide) {
      col = random() < 0.45 ? PAL.huskPale : (random() < 0.6 ? PAL.huskStraw : PAL.huskSienna);
    } else {
      col = random() < 0.55 ? PAL.huskDeep : (random() < 0.7 ? PAL.huskUmber : PAL.huskOchre);
    }

    // Draw dark backing ink hair first so light hairs pop with crisp showman contrast against light board
    if (isSunlitSide && random() < 0.6) {
      brush.set("rotring", PAL.huskDeep, random(0.75, 1.25));
      brush.spline([[x1 + 1.2, y1 + 1.2, 1.0], [mx + 1.2, my + 1.2, 0.7], [x2 + 1.2, y2 + 1.2, 0.15]], 0.5);
    }

    brush.set("husk_pen", col, random(0.6, 1.35));
    brush.spline([[x1, y1, 1.1], [mx, my, 0.75], [x2, y2, 0.1]], 0.55);
  }

  // 5) ONE CONFIDENT WHITE ENAMEL HIGHLIGHT LAID ON LIKE A SIGN-WRITER'S FLICK!
  drawSignWriterHighlightFlick(shy, PAL);
}

function drawSignWriterHighlightFlick(shy, PAL) {
  // Compute a bold, sweeping arc across the upper-left swell of the coconut shell
  let flickLatStart = -54;
  let flickLatEnd = 12;
  let flickLon = -42;

  let mainFlickPts = [];
  let underGlowPts = [];
  const steps = 10;

  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let lat = lerp(flickLatStart, flickLatEnd, t);
    let lon = flickLon + sin(t * 180) * 6 - t * 8;
    let p = projectCocoPoint(lat, lon, shy);

    // Sign-writer's brush pressure: heavy chisel entry, full belly, rapid flicked taper at exit!
    let pressure = t < 0.18
      ? map(t, 0, 0.18, 1.15, 1.45)
      : pow(1.0 - (t - 0.18) / 0.82, 1.35) * 1.45;

    mainFlickPts.push([p.x, p.y, max(0.06, pressure)]);
    underGlowPts.push([p.x + 2.5, p.y + 2.0, max(0.06, pressure * 0.9)]);
  }

  // Subtle cool-blue/ultramarine enamel shadow lip right underneath the thick white paint stroke
  brush.set("sign_chisel", PAL.ultramarine, 0.85);
  brush.spline(underGlowPts, 0.35);

  // Cream-white enamel body pass
  brush.set("sign_chisel", PAL.enamelWhite, 1.35);
  brush.spline(mainFlickPts, 0.35);

  // Pure titanium white loaded center flick
  brush.set("sign_chisel", PAL.pureEnamel, 1.05);
  brush.spline(mainFlickPts, 0.35);

  // Squared chisel entry edge at the top of the stroke + split bristle tail marks at the bottom flick
  let pStart = mainFlickPts[0];
  let pNext = mainFlickPts[1];
  let entryAng = atan2(pNext[1] - pStart[1], pNext[0] - pStart[0]);

  // Crisp chisel-corner entry
  brush.set("flat_stripe", PAL.pureEnamel, 0.9);
  brush.line(
    pStart[0] - cos(entryAng + 75) * 9,
    pStart[1] - sin(entryAng + 75) * 9,
    pStart[0] + cos(entryAng + 75) * 9,
    pStart[1] + sin(entryAng + 75) * 9
  );

  // 4 razor-sharp split-bristle enamel hairs trailing off the end of the flick
  let pMid = mainFlickPts[6];
  let pEnd = mainFlickPts[steps];
  let exitAng = atan2(pEnd[1] - pMid[1], pEnd[0] - pMid[0]);
  for (let b = -2; b <= 2; b++) {
    let offset = b * 3.8;
    let sx = pMid[0] + cos(exitAng + 90) * offset;
    let sy = pMid[1] + sin(exitAng + 90) * offset;
    let ex = pEnd[0] + cos(exitAng + b * 4) * random(18, 36) + cos(exitAng + 90) * offset * 0.6;
    let ey = pEnd[1] + sin(exitAng + b * 4) * random(18, 36) + sin(exitAng + 90) * offset * 0.6;
    brush.set("rotring", PAL.pureEnamel, random(0.85, 1.35));
    brush.spline([
      [sx, sy, 1.1],
      [(sx + ex) * 0.5, (sy + ey) * 0.5, 0.7],
      [ex, ey, 0.05]
    ], 0.3);
  }
}

// =============================================================================
// 6. FOREGROUND FAIRGROUND GRIT, STRAY COIR FIBERS & SHOWMAN BORDER ACCENTS
// =============================================================================
function drawFinalShowmanTouches(shys, PAL) {
  // Fallen coconut husk fibers resting on the wooden counter rail around the cup bases
  for (let shy of shys) {
    randomSeed(shy.seed + 999);
    for (let i = 0; i < 28; i++) {
      let fx = shy.cx + random(-115, 125);
      let fy = shy.cupBotY + random(-18, 12);
      let flen = random(14, 38);
      let fang = random(-25, 25);
      let x2 = fx + cos(fang) * flen;
      let y2 = fy + sin(fang) * flen;

      // Tiny ultramarine shadow under fallen fiber
      brush.set("rotring", PAL.ultramarine, 0.65);
      brush.line(fx + 2, fy + 2.5, x2 + 2, y2 + 2.5);

      // Fallen coir hair
      let col = random() < 0.5 ? PAL.huskStraw : (random() < 0.5 ? PAL.huskSienna : PAL.huskDeep);
      brush.set("husk_pen", col, random(0.65, 1.15));
      brush.spline([
        [fx, fy, 0.8],
        [(fx + x2) * 0.5, (fy + y2) * 0.5 - random(2, 6), 1.0],
        [x2, y2, 0.2]
      ], 0.4);
    }
  }

  // Painted showman pinstripe & corner diamond flourishes at the top dado band of the backdrop
  const diamondXs = [100, 418, 782, 1100];
  for (let dx of diamondXs) {
    let dy = 58;
    let rx = 24;
    let ry = 16;

    // Hard ultramarine offset shadow of painted star/diamond motif
    brush.noStroke();
    brush.wash(PAL.ultramarine, 220);
    brush.beginShape(0.05);
    brush.vertex(dx + 6, dy - ry + 5);
    brush.vertex(dx + rx + 6, dy + 5);
    brush.vertex(dx + 6, dy + ry + 5);
    brush.vertex(dx - rx + 6, dy + 5);
    brush.endShape(true);

    // Chrome yellow & vermilion sign-painted diamond
    brush.wash(PAL.chromeYellow, 240);
    brush.beginShape(0.05);
    brush.vertex(dx, dy - ry);
    brush.vertex(dx + rx, dy);
    brush.vertex(dx, dy + ry);
    brush.vertex(dx - rx, dy);
    brush.endShape(true);

    brush.set("flat_stripe", PAL.enamelWhite, 0.45);
    brush.line(dx - rx, dy, dx, dy - ry);
    brush.line(dx, dy - ry, dx + rx, dy);
  }
}

