const CX = 568;
const CY = 625;
const SCALE_3D = 1.38;
const YAW_DEG = -21;
const PITCH_Y = 0.80;
const PITCH_Z = 0.64;

// Tin dimensions in 3D model units
const TIN_RX = 196;
const TIN_RY = 128;
const TIN_RC = 48;
const TIN_H = 88;
