function draw() {
  translate(-width / 2, -height / 2);
  background(PAL.parchment);
  brush.noField();

  // 1. Sacred burnished gold leaf ground with square seams, red bole & craquelure
  renderGoldLeafGround();

  // 2. Cast shadows of the tin, curled lid, and key across the gold ground
  renderCastShadows();

  // 3. Exterior tin walls, bottom seam flange, and scuffed printed label
  renderTinExteriorAndLabel();

  // 4. Recessed tin interior well and deep olive oil pool
  renderTinInteriorAndOilPool();

  // 5. Three plump hyperreal sardines in cobalt, silver grey & olive oil glazes
  renderAllSardines();

  // 6. Top double-seamed rim, jagged cut metal lip, and pooled rim oil
  renderTopRimAndCutEdge();

  // 7. Curled metal lid scroll and slotted sardine key
  renderCurledLidAndKey();

  // 8. Final specular highlights & burnish unity
  renderFinalSpecularGlints();

  noLoop();
}

// ============================================================================
// 3D PROJECTION & GEOMETRY HELPERS
// ============================================================================

function proj(x, y, z = 0) {
  const c = cos(YAW_DEG);
  const s = sin(YAW_DEG);
  const rx = x * c - y * s;
  const ry = x * s + y * c;
  return [
    CX + rx * SCALE_3D,
    CY + (ry * PITCH_Y - z * PITCH_Z) * SCALE_3D
  ];
}

function rotXY(x, y) {
  const c = cos(YAW_DEG);
  const s = sin(YAW_DEG);
  return [x * c - y * s, x * s + y * c];
}

// Shadow projection onto z = 0 plane from upper-left directional light
function projShadow(x, y, z) {
  const lx = 0.72;
  const ly = 0.56;
  return proj(x + z * lx, y + z * ly, 0);
}

// Parametric rounded rectangle for the sardine tin
// s in [0, 1) -> returns { x, y, nx, ny, tx, ty }
function getTinRimData(s, inset = 0) {
  const rx = max(12, TIN_RX - inset);
  const ry = max(12, TIN_RY - inset);
  const rc = clampVal(TIN_RC - inset * 0.75, 6, min(rx - 2, ry - 2));

  const sx = rx - rc;
  const sy = ry - rc;
  const arcLen = HALF_PI * rc;
  const totalLen = 4 * sx + 4 * sy + 4 * arcLen;
  let d = ((s % 1) + 1) % 1 * totalLen;

  // Segment 0: Front-facing long edge (y = +ry, x from -sx to +sx)
  if (d < 2 * sx) {
    const u = d - sx;
    return { x: u, y: ry, nx: 0, ny: 1, tx: 1, ty: 0 };
  }
  d -= 2 * sx;

  // Segment 1: Bottom-right corner (center +sx, +sy, angle 90 -> 0 -> wait: from (sx, ry) to (rx, sy))
  if (d < arcLen) {
    const ang = 90 - (d / arcLen) * 90;
    return {
      x: sx + rc * cos(ang),
      y: sy + rc * sin(ang),
      nx: cos(ang),
      ny: sin(ang),
      tx: sin(ang),
      ty: -cos(ang)
    };
  }
  d -= arcLen;

  // Segment 2: Right short edge (x = +rx, y from +sy to -sy)
  if (d < 2 * sy) {
    const v = sy - d;
    return { x: rx, y: v, nx: 1, ny: 0, tx: 0, ty: -1 };
  }
  d -= 2 * sy;

  // Segment 3: Back-right corner (angle 0 -> -90)
  if (d < arcLen) {
    const ang = -(d / arcLen) * 90;
    return {
      x: sx + rc * cos(ang),
      y: -sy + rc * sin(ang),
      nx: cos(ang),
      ny: sin(ang),
      tx: sin(ang),
      ty: -cos(ang)
    };
  }
  d -= arcLen;

  // Segment 4: Back long edge (y = -ry, x from +sx to -sx)
  if (d < 2 * sx) {
    const u = sx - d;
    return { x: u, y: -ry, nx: 0, ny: -1, tx: -1, ty: 0 };
  }
  d -= 2 * sx;

  // Segment 5: Back-left corner (angle -90 -> -180)
  if (d < arcLen) {
    const ang = -90 - (d / arcLen) * 90;
    return {
      x: -sx + rc * cos(ang),
      y: -sy + rc * sin(ang),
      nx: cos(ang),
      ny: sin(ang),
      tx: sin(ang),
      ty: -cos(ang)
    };
  }
  d -= arcLen;

  // Segment 6: Left short edge (x = -rx, y from -sy to +sy)
  if (d < 2 * sy) {
    const v = -sy + d;
    return { x: -rx, y: v, nx: -1, ny: 0, tx: 0, ty: 1 };
  }
  d -= 2 * sy;

  // Segment 7: Front-left corner (angle 180 -> 90)
  const ang = 180 - (d / arcLen) * 90;
  return {
    x: -sx + rc * cos(ang),
    y: sy + rc * sin(ang),
    nx: cos(ang),
    ny: sin(ang),
    tx: sin(ang),
    ty: -cos(ang)
  };
}

function clampVal(v, lo, hi) {
  return max(lo, min(hi, v));
}

// ============================================================================
// SAFE P5.BRUSH WRAPPERS
// ============================================================================

function cleanPoints(pts) {
  if (!pts || pts.length === 0) return [];
  const out = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    const p = pts[i];
    const prev = out[out.length - 1];
    if (dist(p[0], p[1], prev[0], prev[1]) > 0.6) {
      out.push(p);
    }
  }
  if (out.length > 2) {
    const first = out[0];
    const last = out[out.length - 1];
    if (dist(first[0], first[1], last[0], last[1]) < 0.6) {
      out.pop();
    }
  }
  return out;
}

function drawFillShape(pts, col, opacity, bleed = 0.15, tex = 0.5, border = 0.35, curv = 0.08) {
  const cPts = cleanPoints(pts);
  if (cPts.length < 3) return;
  brush.noStroke();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.fill(col, opacity);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, border);
  brush.beginShape(curv);
  for (let i = 0; i < cPts.length; i++) {
    brush.vertex(cPts[i][0], cPts[i][1]);
  }
  brush.endShape(true);
  brush.noFill();
}

function drawWashShape(pts, col, opacity, curv = 0.05) {
  const cPts = cleanPoints(pts);
  if (cPts.length < 3) return;
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.noMass();
  brush.wash(col, opacity);
  brush.beginShape(curv);
  for (let i = 0; i < cPts.length; i++) {
    brush.vertex(cPts[i][0], cPts[i][1]);
  }
  brush.endShape(true);
  brush.noWash();
}

function drawHatchShape(pts, brushName, col, weight, spacing, angle, opts = { rand: 0.05 }, curv = 0.05) {
  const cPts = cleanPoints(pts);
  if (cPts.length < 3) return;
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  brush.noMass();
  brush.hatchStyle(brushName, col, weight);
  brush.hatch(spacing, angle, opts);
  brush.beginShape(curv);
  for (let i = 0; i < cPts.length; i++) {
    brush.vertex(cPts[i][0], cPts[i][1]);
  }
  brush.endShape(true);
  brush.noHatch();
}

function drawMassShape(pts, brushName, col, opts = { precision: 0.7, strength: 0.6, outline: false }, curv = 0.06) {
  const cPts = cleanPoints(pts);
  if (cPts.length < 3) return;
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.mass(brushName, col, opts);
  brush.beginShape(curv);
  for (let i = 0; i < cPts.length; i++) {
    brush.vertex(cPts[i][0], cPts[i][1]);
  }
  brush.endShape(true);
  brush.noMass();
}

function strokeLine(brushName, col, weight, x1, y1, x2, y2) {
  if (dist(x1, y1, x2, y2) < 0.4) return;
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.set(brushName, col, weight);
  brush.line(x1, y1, x2, y2);
}

function strokeSpline(brushName, col, weight, pts, curv = 0.5) {
  if (!pts || pts.length < 2) return;
  const cPts = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    if (dist(pts[i][0], pts[i][1], cPts[cPts.length - 1][0], cPts[cPts.length - 1][1]) > 0.5) {
      cPts.push(pts[i]);
    }
  }
  if (cPts.length < 2) return;
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.set(brushName, col, weight);
  brush.spline(cPts, curv);
}

function makeJitterRect(x, y, w, h, stepsPerSide = 4, jitter = 3) {
  const pts = [];
  for (let i = 0; i < stepsPerSide; i++) {
    const t = i / stepsPerSide;
    pts.push([x + w * t + random(-jitter, jitter), y + random(-jitter, jitter)]);
  }
  for (let i = 0; i < stepsPerSide; i++) {
    const t = i / stepsPerSide;
    pts.push([x + w + random(-jitter, jitter), y + h * t + random(-jitter, jitter)]);
  }
  for (let i = 0; i < stepsPerSide; i++) {
    const t = i / stepsPerSide;
    pts.push([x + w * (1 - t) + random(-jitter, jitter), y + h + random(-jitter, jitter)]);
  }
  for (let i = 0; i < stepsPerSide; i++) {
    const t = i / stepsPerSide;
    pts.push([x + random(-jitter, jitter), y + h * (1 - t) + random(-jitter, jitter)]);
  }
  return pts;
}

// ============================================================================
// 1. SACRED BURNISHED GOLD LEAF GROUND
// ============================================================================

function renderGoldLeafGround() {
  // Grid coordinates for 5x5 square gold leaves (~240x240px per leaf)
  const seamX = [0, 128, 366, 604, 842, 1078, 1200];
  const seamY = [0, 124, 362, 600, 838, 1074, 1200];

  // Warm terracotta bole undertone wash across the whole panel
  drawWashShape(
    [[0, 0], [1200, 0], [1200, 1200], [0, 1200]],
    "#d8be84",
    160,
    0
  );

  // Batch 1: Naples Yellow watercolour base squares
  const naplesBatch = [];
  const ochreBatch = [];
  const siennaBatch = [];

  for (let r = 0; r < seamY.length - 1; r++) {
    for (let c = 0; c < seamX.length - 1; c++) {
      const x1 = seamX[c] - 5;
      const y1 = seamY[r] - 5;
      const w = (seamX[c + 1] - seamX[c]) + 10;
      const h = (seamY[r + 1] - seamY[r]) + 10;

      const poly = makeJitterRect(x1, y1, w, h, 3, 2.5);
      naplesBatch.push(poly);

      // Secondary glazed patches inside each square for uneven burnished gold leaf sheen
      const subW = w * random(0.55, 0.85);
      const subH = h * random(0.5, 0.82);
      const subX = x1 + random(0, w - subW);
      const subY = y1 + random(0, h - subH);
      ochreBatch.push(makeJitterRect(subX, subY, subW, subH, 3, 4));

      if (random() < 0.78) {
        const sW = w * random(0.32, 0.62);
        const sH = h * random(0.28, 0.55);
        const sX = x1 + random(0, w - sW);
        const sY = y1 + random(0, h - sH);
        siennaBatch.push(makeJitterRect(sX, sY, sW, sH, 3, 5));
      }
    }
  }

  // Render batched watercolour washes in Naples Yellow, Yellow Ochre, Raw Sienna
  for (let i = 0; i < naplesBatch.length; i++) {
    const col = i % 2 === 0 ? PAL.naples : PAL.naplesLight;
    drawFillShape(naplesBatch[i], col, 95, 0.24, 0.62, 0.38, 0.08);
  }

  for (let i = 0; i < ochreBatch.length; i++) {
    const col = i % 2 === 0 ? PAL.ochre : PAL.ochreLight;
    drawFillShape(ochreBatch[i], col, 78, 0.28, 0.68, 0.42, 0.1);
  }

  for (let i = 0; i < siennaBatch.length; i++) {
    const col = i % 3 === 0 ? PAL.rawSiennaDark : PAL.rawSienna;
    drawFillShape(siennaBatch[i], col, 64, 0.30, 0.72, 0.45, 0.12);
  }

  // Subtle luminous halo of pale Naples Yellow behind the tin icon
  const haloPts = [];
  for (let a = 0; a < 360; a += 15) {
    const radX = 365 + random(-14, 14);
    const radY = 275 + random(-14, 14);
    haloPts.push([CX + cos(a) * radX, CY - 15 + sin(a) * radY]);
  }
  drawFillShape(haloPts, PAL.naplesLight, 70, 0.35, 0.45, 0.25, 0.15);

  // Deeper raw sienna & antique gold vignette at outer panel borders
  const borderStrips = [
    [[0, 0], [1200, 0], [1200, 95], [0, 85]],
    [[0, 1110], [1200, 1100], [1200, 1200], [0, 1200]],
    [[0, 0], [90, 0], [80, 1200], [0, 1200]],
    [[1115, 0], [1200, 0], [1200, 1200], [1105, 1200]]
  ];
  for (const bPoly of borderStrips) {
    drawFillShape(bPoly, PAL.rawSienna, 65, 0.32, 0.75, 0.5, 0.05);
  }

  // Dry metallic grain hatching across the gold leaves
  for (let r = 0; r < seamY.length - 1; r++) {
    for (let c = 0; c < seamX.length - 1; c++) {
      const x1 = seamX[c] + 4;
      const y1 = seamY[r] + 4;
      const w = seamX[c + 1] - seamX[c] - 8;
      const h = seamY[r + 1] - seamY[r] - 8;
      const rectPts = [[x1, y1], [x1 + w, y1], [x1 + w, y1 + h], [x1, y1 + h]];
      const ang = (r + c) % 2 === 0 ? 3 : -2;
      const hCol = (r * 3 + c) % 2 === 0 ? PAL.ochreDeep : PAL.naplesMuted;
      drawHatchShape(rectPts, "2H", hCol, 0.65, 11, ang, { rand: 0.08 }, 0.02);
    }
  }

  // RUBBED PATCHES REVEALING RED BOLE UNDERNEATH
  // Positioned organically along leaf seams, panel corners, and worn zones
  const bolePatches = [
    { x: 128, y: 235, rx: 32, ry: 14, ang: -12 },
    { x: 366, y: 126, rx: 28, ry: 18, ang: 15 },
    { x: 842, y: 210, rx: 38, ry: 15, ang: 82 },
    { x: 1076, y: 362, rx: 26, ry: 22, ang: -25 },
    { x: 245, y: 362, rx: 44, ry: 12, ang: 4 },
    { x: 955, y: 600, rx: 35, ry: 14, ang: -8 },
    { x: 128, y: 740, rx: 19, ry: 42, ang: 88 },
    { x: 366, y: 955, rx: 22, ry: 36, ang: 78 },
    { x: 604, y: 1074, rx: 48, ry: 15, ang: 3 },
    { x: 842, y: 980, rx: 18, ry: 34, ang: 92 },
    { x: 1030, y: 838, rx: 36, ry: 14, ang: -6 },
    { x: 180, y: 1074, rx: 34, ry: 16, ang: 11 },
    { x: 604, y: 185, rx: 16, ry: 32, ang: 86 },
    { x: 75, y: 490, rx: 24, ry: 15, ang: -18 },
    { x: 1125, y: 165, rx: 28, ry: 19, ang: 32 },
    { x: 1078, y: 1045, rx: 30, ry: 22, ang: -38 },
    { x: 485, y: 362, rx: 26, ry: 10, ang: 2 },
    { x: 720, y: 838, rx: 32, ry: 11, ang: -4 }
  ];

  // Batch red bole watercolour fills
  for (const bp of bolePatches) {
    const outerPts = [];
    const innerPts = [];
    const steps = 14;
    for (let i = 0; i < steps; i++) {
      const a = (i / steps) * 360;
      const n = noise(bp.x * 0.02 + cos(a), bp.y * 0.02 + sin(a));
      const r1x = bp.rx * (0.65 + 0.65 * n);
      const r1y = bp.ry * (0.65 + 0.65 * n);
      const px = bp.x + cos(a) * r1x * cos(bp.ang) - sin(a) * r1y * sin(bp.ang);
      const py = bp.y + cos(a) * r1x * sin(bp.ang) + sin(a) * r1y * cos(bp.ang);
      outerPts.push([px, py]);
      innerPts.push([
        bp.x + (px - bp.x) * 0.58 + random(-2, 2),
        bp.y + (py - bp.y) * 0.58 + random(-2, 2)
      ]);
    }
    // Warm raw sienna halo around rubbed spot
    drawFillShape(outerPts, PAL.rawSiennaDark, 85, 0.25, 0.65, 0.45, 0.12);
    // Exposed Armenian red bole clay
    drawFillShape(outerPts, PAL.bole, 155, 0.16, 0.72, 0.58, 0.10);
    drawFillShape(innerPts, PAL.boleDeep, 170, 0.10, 0.65, 0.50, 0.10);

    // Dry rubbed texture & tiny flaking gold leaf specks at bole edges
    drawHatchShape(outerPts, "cpencil", PAL.boleLight, 0.7, 4.5, bp.ang + 25, { rand: 0.15 }, 0.08);
    for (let k = 0; k < 7; k++) {
      const p = outerPts[(k * 2) % outerPts.length];
      strokeLine(
        "agate_burnish",
        PAL.burnishGold,
        0.9,
        p[0] - 4,
        p[1] - 1,
        p[0] + 5,
        p[1] + 1
      );
    }
  }

  // Additional micro-rubbed red bole scratches along leaf seams
  for (let i = 0; i < 65; i++) {
    const isVert = random() < 0.5;
    let sx, sy, len, ang;
    if (isVert) {
      sx = seamX[ int(random(1, seamX.length - 1)) ] + random(-6, 6);
      sy = random(40, 1160);
      len = random(8, 28);
      ang = random(82, 98);
    } else {
      sx = random(40, 1160);
      sy = seamY[ int(random(1, seamY.length - 1)) ] + random(-6, 6);
      len = random(8, 28);
      ang = random(-8, 8);
    }
    const bCol = random() < 0.5 ? PAL.bole : PAL.boleDeep;
    strokeLine("cpencil", bCol, random(0.8, 1.5), sx, sy, sx + cos(ang) * len, sy + sin(ang) * len);
  }

  // SQUARE LEAF SEAMS (Overlap ridges, raw sienna burnish shadow, white pencil edge)
  // Vertical seams
  for (let i = 1; i < seamX.length - 1; i++) {
    const xBase = seamX[i];
    // Overlap strip wash
    const seamStrip = [
      [xBase - 4, 0],
      [xBase + 5, 0],
      [xBase + 4, 1200],
      [xBase - 5, 1200]
    ];
    drawWashShape(seamStrip, PAL.ochreDeep, 58, 0.02);

    // Segmented hand-laid leaf seam lines
    for (let y = 10; y < 1190; y += 34) {
      const yNext = min(1192, y + random(26, 36));
      const jx1 = xBase + (noise(i * 10, y * 0.01) - 0.5) * 4.5;
      const jx2 = xBase + (noise(i * 10, yNext * 0.01) - 0.5) * 4.5;

      // Dark raw sienna / bole seam shadow
      strokeLine("2B", PAL.rawSiennaDark, 0.75, jx1 - 1.8, y, jx2 - 1.8, yNext);
      if (random() < 0.42) {
        strokeLine("sable_fine", PAL.boleDeep, 0.65, jx1 - 0.5, y + 3, jx2 - 0.5, yNext - 3);
      }
      // Sharp white pencil & Naples yellow burnished overlap highlight
      strokeLine("cpencil", PAL.burnishCream, 0.85, jx1 + 1.8, y, jx2 + 1.8, yNext);
      if (random() < 0.65) {
        strokeLine("2H", PAL.burnishWhite, 0.7, jx1 + 2.8, y + 4, jx2 + 2.8, yNext - 2);
      }
    }
  }

  // Horizontal seams
  for (let j = 1; j < seamY.length - 1; j++) {
    const yBase = seamY[j];
    const seamStrip = [
      [0, yBase - 4],
      [1200, yBase - 5],
      [1200, yBase + 4],
      [0, yBase + 5]
    ];
    drawWashShape(seamStrip, PAL.ochreDeep, 54, 0.02);

    for (let x = 10; x < 1190; x += 34) {
      const xNext = min(1192, x + random(26, 36));
      const jy1 = yBase + (noise(x * 0.01, j * 10) - 0.5) * 4.5;
      const jy2 = yBase + (noise(xNext * 0.01, j * 10) - 0.5) * 4.5;

      strokeLine("2B", PAL.rawSiennaDark, 0.75, x, jy1 - 1.8, xNext, jy2 - 1.8);
      if (random() < 0.42) {
        strokeLine("sable_fine", PAL.boleDeep, 0.65, x + 3, jy1 - 0.5, xNext - 3, jy2 - 0.5);
      }
      strokeLine("cpencil", PAL.burnishCream, 0.88, x, jy1 + 1.8, xNext, jy2 + 1.8);
      if (random() < 0.68) {
        strokeLine("2H", PAL.burnishWhite, 0.75, x + 4, jy1 + 2.8, xNext - 2, jy2 + 2.8);
      }
    }
  }

  // TINY CRACKS (CRAQUELURE) IN THE GOLD GROUND
  for (let c = 0; c < 52; c++) {
    // Anchor cracks preferentially near seams and corners
    let cx, cy;
    if (c < 34) {
      const onVert = c % 2 === 0;
      cx = onVert ? seamX[1 + (c % 5)] + random(-35, 35) : random(50, 1150);
      cy = onVert ? random(50, 1150) : seamY[1 + (c % 5)] + random(-35, 35);
    } else {
      cx = random(60, 1140);
      cy = random(60, 1140);
    }

    const pts = [[cx, cy]];
    let curX = cx;
    let curY = cy;
    let baseAng = random() < 0.5 ? random(-15, 15) : random(75, 105);
    const segs = int(random(4, 9));

    for (let s = 0; s < segs; s++) {
      baseAng += random(-28, 28);
      const step = random(8, 22);
      curX += cos(baseAng) * step;
      curY += sin(baseAng) * step;
      pts.push([curX, curY]);

      // Occasional forked micro-branch
      if (s === 2 && random() < 0.6) {
        const bAng = baseAng + (random() < 0.5 ? 48 : -48);
        const bx = curX + cos(bAng) * random(10, 20);
        const by = curY + sin(bAng) * random(10, 20);
        strokeLine("needle_crack", PAL.boleDark, 0.55, curX, curY, bx, by);
      }
    }

    const crackCol = c % 3 === 0 ? PAL.boleDark : PAL.umberGold;
    strokeSpline("needle_crack", crackCol, random(0.5, 0.85), pts, 0.25);

    // Subtle pale gold catch-light on the lower lip of main cracks
    if (pts.length >= 3 && random() < 0.55) {
      strokeLine(
        "2H",
        PAL.burnishCream,
        0.5,
        pts[1][0] + 1.2,
        pts[1][1] + 1.2,
        pts[2][0] + 1.2,
        pts[2][1] + 1.2
      );
    }
  }

  // SHARP WHITE PENCIL BURNISH LINES ACROSS THE GOLD FIELD
  // Clustered agate-stone burnishing strokes catching directional studio light
  for (let b = 0; b < 240; b++) {
    const bx = random(35, 1165);
    const by = random(35, 1165);
    // Concentrate extra burnish sheen around the icon center & seam intersections
    const distCenter = dist(bx, by, CX, CY);
    const isNearSeam =
      seamX.some((sx) => abs(bx - sx) < 28) ||
      seamY.some((sy) => abs(by - sy) < 28);

    if (distCenter > 520 && !isNearSeam && random() < 0.35) continue;

    const len = random(18, 68);
    const ang = random(-6, 4); // Subtle horizontal agate burnish direction
    const x2 = bx + cos(ang) * len;
    const y2 = by + sin(ang) * len;

    const col =
      b % 3 === 0
        ? PAL.burnishWhite
        : b % 3 === 1
        ? PAL.burnishCream
        : PAL.burnishGold;
    const brName = b % 2 === 0 ? "cpencil" : "2H";
    const w = random(0.55, 1.15);

    strokeLine(brName, col, w, bx, by, x2, y2);
  }
}

// ============================================================================
// 2. CAST SHADOWS ON THE GOLD GROUND
// ============================================================================

function renderCastShadows() {
  // Compute shadow polygon cast by the top rim (z = TIN_H) onto z = 0
  const shadowOuter = [];
  const shadowInner = [];
  const shadowCore = [];
  const N = 84;

  for (let i = 0; i < N; i++) {
    const s = i / N;
    const p = getTinRimData(s, -4);
    const [rx, ry] = rotXY(p.x, p.y);
    // Lower wall base & cast shadow envelope
    const spOuter = projShadow(p.x, p.y, TIN_H * 1.06);
    const spInner = projShadow(p.x, p.y, TIN_H * 0.82);
    const spCore = projShadow(p.x, p.y, TIN_H * 0.45);
    shadowOuter.push(spOuter);
    shadowInner.push(spInner);
    shadowCore.push(spCore);
  }

  // Warm golden-amber bounce light / penumbra on the gold leaf
  drawFillShape(shadowOuter, PAL.rawSiennaDark, 92, 0.35, 0.65, 0.35, 0.12);
  drawFillShape(shadowInner, PAL.shadowWarm, 118, 0.25, 0.68, 0.45, 0.10);
  drawFillShape(shadowCore, PAL.shadowUmber, 145, 0.16, 0.60, 0.50, 0.08);

  // Shadow of the curled lid cylinder on the right end
  const lidShadowPts = [];
  const lidX = 148;
  const lidZ = TIN_H + 34;
  const lidBox = [
    [lidX - 28, -134, lidZ],
    [lidX + 46, -134, lidZ + 12],
    [lidX + 46, 134, lidZ + 12],
    [lidX - 28, 134, lidZ]
  ];
  for (const pt of lidBox) {
    lidShadowPts.push(projShadow(pt[0], pt[1], pt[2]));
  }
  drawFillShape(lidShadowPts, PAL.shadowUmber, 130, 0.24, 0.65, 0.42, 0.12);

  // Shadow of the protruding slotted key handle (y = 128..218)
  const keyShadowShaft = [
    projShadow(lidX - 5, 125, lidZ - 4),
    projShadow(lidX + 7, 125, lidZ - 4),
    projShadow(lidX + 7, 182, lidZ - 4),
    projShadow(lidX - 5, 182, lidZ - 4)
  ];
  drawFillShape(keyShadowShaft, PAL.shadowUmber, 125, 0.18, 0.5, 0.4, 0.08);

  const keyShadowLoop = [];
  for (let a = 0; a < 360; a += 24) {
    const ky = 200 + cos(a) * 24;
    const kx = lidX + sin(a) * 15;
    keyShadowLoop.push(projShadow(kx, ky, lidZ - 4));
  }
  drawFillShape(keyShadowLoop, PAL.shadowUmber, 130, 0.20, 0.55, 0.42, 0.12);

  // Fine cross-hatched umber shading inside the cast shadow
  drawHatchShape(shadowInner, "2B", PAL.shadowDeep, 0.7, 5.5, -22, { rand: 0.07 }, 0.08);
  drawHatchShape(shadowCore, "charcoal", PAL.shadowDeep, 0.65, 6.5, 38, { rand: 0.08 }, 0.08);

  // Warm metallic caustic reflection on the gold leaf right beside the front tin wall
  for (let i = 0; i < 36; i++) {
    const s = (i / 36) * 0.44; // along front wall & corner
    const p = getTinRimData(s, -12);
    const sp1 = proj(p.x + 12, p.y + 18, 0);
    const sp2 = proj(p.x + 28, p.y + 34, 0);
    strokeLine("agate_burnish", PAL.ochreLight, 1.1, sp1[0], sp1[1], sp2[0], sp2[1]);
  }
}

// ============================================================================
// 3. EXTERIOR TIN BODY, BOTTOM FLANGE & SCUFFED PRINTED LABEL
// ============================================================================

function isWallVisible(nx, ny) {
  const [, ry] = rotXY(nx, ny);
  return ry > -0.02;
}

function renderTinExteriorAndLabel() {
  const N = 160;
  const visSamples = [];

  // Collect all perimeter samples facing the viewer
  // Ordered continuously around the visible front-left, front-corner, front-long, and front-right walls
  for (let i = -52; i <= 54; i++) {
    const s = ((i / N) % 1 + 1) % 1;
    const d = getTinRimData(s, 0);
    if (isWallVisible(d.nx, d.ny)) {
      visSamples.push({ s, ...d });
    }
  }

  // 3A. Dark contact occlusion crease directly under the bottom flange (z = 0)
  const contactPts = [];
  for (let i = 0; i < visSamples.length; i++) {
    const v = visSamples[i];
    contactPts.push(proj(v.x + v.nx * 3, v.y + v.ny * 3, 0));
  }
  strokeSpline("charcoal", "#120902", 1.8, contactPts, 0.4);
  strokeSpline("sable_fine", "#080401", 1.3, contactPts, 0.4);

  // 3B. Base exterior metallic body wall (z = 3 to z = TIN_H)
  const wallPoly = [];
  for (let i = 0; i < visSamples.length; i++) {
    const v = visSamples[i];
    wallPoly.push(proj(v.x, v.y, 3));
  }
  for (let i = visSamples.length - 1; i >= 0; i--) {
    const v = visSamples[i];
    wallPoly.push(proj(v.x, v.y, TIN_H));
  }
  drawWashShape(wallPoly, PAL.silverMid, 235, 0.04);
  drawFillShape(wallPoly, PAL.cobaltMist, 85, 0.10, 0.45, 0.35, 0.04);

  // Shaded vertical metal strips around the curved corners and walls
  for (let i = 0; i < visSamples.length - 1; i += 2) {
    const v1 = visSamples[i];
    const v2 = visSamples[min(visSamples.length - 1, i + 2)];
    const [rx, ry] = rotXY(v1.nx, v1.ny);

    // Lighting factor: left-facing (-rx) is lit; right-facing (+rx) is in core shadow
    const strip = [
      proj(v1.x, v1.y, 4),
      proj(v2.x, v2.y, 4),
      proj(v2.x, v2.y, TIN_H - 2),
      proj(v1.x, v1.y, TIN_H - 2)
    ];

    if (rx < -0.25) {
      // Bright silver-blue studio highlight on front-left corner
      drawWashShape(strip, PAL.silverLight, 150, 0.02);
    } else if (rx > 0.35) {
      // Dark pewter core shadow & gold bounce on front-right corner
      drawWashShape(strip, PAL.silverDark, 165, 0.02);
      drawWashShape(strip, PAL.ochreDeep, 55, 0.02);
    } else {
      // Front-facing long wall midtone
      drawWashShape(strip, PAL.silver, 110, 0.02);
    }
  }

  // 3C. Bottom Stamped Rim Flange (z = 0 to z = 7)
  const botFlangePoly = [];
  const botHighlightPts = [];
  for (let i = 0; i < visSamples.length; i++) {
    const v = visSamples[i];
    const pOut = getTinRimData(v.s, -3.5);
    botFlangePoly.push(proj(pOut.x, pOut.y, 0.5));
    botHighlightPts.push(proj(pOut.x, pOut.y, 5.2));
  }
  for (let i = visSamples.length - 1; i >= 0; i--) {
    const v = visSamples[i];
    const pOut = getTinRimData(v.s, -3.5);
    botFlangePoly.push(proj(pOut.x, pOut.y, 6.8));
  }
  drawWashShape(botFlangePoly, PAL.silverDark, 210, 0.03);
  // Warm gold ground reflection in the bottom bead
  drawFillShape(botFlangePoly, PAL.ochre, 90, 0.08, 0.4, 0.3, 0.03);
  strokeSpline("sable_fine", PAL.silverBright, 0.95, botHighlightPts, 0.4);
  strokeSpline("2B", "#2b3238", 0.85, contactPts, 0.4);

  // 3D. THE PRINTED LABEL (SLIGHTLY SCUFFED)
  // Wraps around the front-left corner and along the entire front long wall (z = 13 to z = 73)
  const labelSamples = visSamples.filter((_, idx) => idx >= 6 && idx <= visSamples.length - 8);
  const zBot = 13;
  const zTop = 73;

  // Helper to get a sub-band polygon along the label
  function getLabelBandPoly(idxStart, idxEnd, z1, z2) {
    const pts = [];
    for (let i = idxStart; i <= idxEnd; i++) {
      const v = labelSamples[i];
      pts.push(proj(v.x + v.nx * 0.8, v.y + v.ny * 0.8, z1));
    }
    for (let i = idxEnd; i >= idxStart; i--) {
      const v = labelSamples[i];
      pts.push(proj(v.x + v.nx * 0.8, v.y + v.ny * 0.8, z2));
    }
    return pts;
  }

  const LCount = labelSamples.length - 1;

  // Cream/buff vintage lithographed paper base
  const fullLabelPoly = getLabelBandPoly(0, LCount, zBot, zTop);
  drawWashShape(fullLabelPoly, PAL.labelCream, 235, 0.03);
  drawFillShape(fullLabelPoly, PAL.labelAged, 95, 0.14, 0.62, 0.40, 0.03);

  // Subtle cylindrical shading across the paper label (brighter on left curve, warmer/darker on right)
  const leftCurvePoly = getLabelBandPoly(0, int(LCount * 0.26), zBot, zTop);
  drawWashShape(leftCurvePoly, "#f5ecd8", 95, 0.03);

  const rightCurvePoly = getLabelBandPoly(int(LCount * 0.78), LCount, zBot, zTop);
  drawFillShape(rightCurvePoly, PAL.rawSienna, 72, 0.15, 0.5, 0.3, 0.03);

  // Top & bottom Venetian red ornamental bands
  const topRedBand = getLabelBandPoly(0, LCount, zTop - 10, zTop - 2.5);
  const botRedBand = getLabelBandPoly(0, LCount, zBot + 2.5, zBot + 10);
  drawWashShape(topRedBand, PAL.labelRed, 210, 0.02);
  drawWashShape(botRedBand, PAL.labelRed, 210, 0.02);

  // Prussian/cobalt ink rules & gold ochre pinstripe borders
  function drawLabelRule(zVal, brushName, col, w) {
    const pts = [];
    for (let i = 0; i <= LCount; i++) {
      const v = labelSamples[i];
      pts.push(proj(v.x + v.nx * 1.0, v.y + v.ny * 1.0, zVal));
    }
    strokeSpline(brushName, col, w, pts, 0.35);
  }

  drawLabelRule(zTop, "2B", "#3d3427", 0.75);
  drawLabelRule(zBot, "2B", "#3d3427", 0.85);
  drawLabelRule(zTop - 10.5, "sable_fine", PAL.labelInk, 0.8);
  drawLabelRule(zTop - 13.5, "sable_fine", PAL.labelGold, 0.75);
  drawLabelRule(zBot + 10.5, "sable_fine", PAL.labelInk, 0.8);
  drawLabelRule(zBot + 13.5, "sable_fine", PAL.labelGold, 0.75);

  // Ornamental vintage medallions on left and right of the front wall
  function drawWallPoint(uNorm, vNorm) {
    // uNorm in [0, 1] along the flat front wall x in [-138, +138], vNorm in [0, 1] along z in [zBot, zTop]
    const wx = lerp(-134, 134, uNorm);
    const wy = TIN_RY + 1.1;
    const wz = lerp(zBot, zTop, vNorm);
    return proj(wx, wy, wz);
  }

  // Left & Right decorative ochre/red diamonds on the front label
  for (const uCenter of [0.10, 0.90]) {
    const dPts = [
      drawWallPoint(uCenter, 0.50 + 0.22),
      drawWallPoint(uCenter + 0.045, 0.50),
      drawWallPoint(uCenter, 0.50 - 0.22),
      drawWallPoint(uCenter - 0.045, 0.50)
    ];
    drawWashShape(dPts, PAL.labelGold, 195, 0.02);
    strokeSpline("sable_fine", PAL.labelInk, 0.7, [...dPts, dPts[0]], 0.05);

    const dInner = [
      drawWallPoint(uCenter, 0.50 + 0.11),
      drawWallPoint(uCenter + 0.022, 0.50),
      drawWallPoint(uCenter, 0.50 - 0.11),
      drawWallPoint(uCenter - 0.022, 0.50)
    ];
    drawWashShape(dInner, PAL.labelRed, 210, 0.02);
  }

  // 3D-PROJECTED VINTAGE BLOCK SERIF TYPOGRAPHY: "SARDINES"
  // Each glyph defined in normalized glyph space [0..1, 0..1] (y=0 bottom, y=1 top)
  const glyphs = {
    S: [
      [[0.88, 0.84], [0.55, 0.98], [0.15, 0.86], [0.15, 0.60], [0.85, 0.42], [0.88, 0.14], [0.48, 0.02], [0.12, 0.16]]
    ],
    A: [
      [[0.08, 0.02], [0.50, 0.98], [0.92, 0.02]],
      [[0.24, 0.36], [0.76, 0.36]]
    ],
    R: [
      [[0.15, 0.02], [0.15, 0.98], [0.68, 0.98], [0.88, 0.76], [0.68, 0.52], [0.15, 0.52]],
      [[0.52, 0.52], [0.90, 0.02]]
    ],
    D: [
      [[0.15, 0.02], [0.15, 0.98], [0.62, 0.98], [0.90, 0.72], [0.90, 0.28], [0.62, 0.02], [0.15, 0.02]]
    ],
    I: [
      [[0.50, 0.02], [0.50, 0.98]],
      [[0.24, 0.98], [0.76, 0.98]],
      [[0.24, 0.02], [0.76, 0.02]]
    ],
    N: [
      [[0.14, 0.02], [0.14, 0.98], [0.86, 0.02], [0.86, 0.98]]
    ],
    E: [
      [[0.85, 0.98], [0.16, 0.98], [0.16, 0.02], [0.88, 0.02]],
      [[0.16, 0.52], [0.72, 0.52]]
    ]
  };

  const word = ["S", "A", "R", "D", "I", "N", "E", "S"];
  const uStart = 0.20;
  const uEnd = 0.80;
  const charStep = (uEnd - uStart) / word.length;
  const charW = charStep * 0.68;

  for (let cIdx = 0; cIdx < word.length; cIdx++) {
    const ch = word[cIdx];
    const strokes = glyphs[ch];
    const u0 = uStart + cIdx * charStep + charStep * 0.16;

    for (const st of strokes) {
      // Offset ochre drop-shadow of vintage print
      const shadowPts = st.map(([gx, gy]) =>
        drawWallPoint(u0 + gx * charW + 0.004, 0.36 + gy * 0.31 - 0.015)
      );
      strokeSpline("sable_fine", PAL.labelGold, 1.05, shadowPts, 0.12);

      // Main deep Prussian/cobalt ink stroke
      const inkPts = st.map(([gx, gy]) =>
        drawWallPoint(u0 + gx * charW, 0.36 + gy * 0.31)
      );
      strokeSpline("rotring", PAL.labelInk, 1.35, inkPts, 0.12);
      // Double pass for bold block stem weight
      const inkPts2 = st.map(([gx, gy]) =>
        drawWallPoint(u0 + gx * charW + 0.0022, 0.36 + gy * 0.31)
      );
      strokeSpline("sable_fine", PAL.labelInk, 1.0, inkPts2, 0.12);
    }
  }

  // Secondary smaller vintage sub-caption line ("HUILE D'OLIVE EXTRA")
  for (let k = 0; k < 14; k++) {
    const uA = 0.28 + k * 0.032;
    const uB = uA + 0.021;
    const p1 = drawWallPoint(uA, 0.25);
    const p2 = drawWallPoint(uB, 0.25);
    strokeLine("sable_fine", PAL.labelRedDark, 0.75, p1[0], p1[1], p2[0], p2[1]);
  }

  // 3E. HYPERREAL SCUFFS, ABRASIONS & OLIVE OIL DRIPS ON THE LABEL
  // Scuffed patches where paper/ink is scraped away to bare silver-grey tinplate
  const scuffZones = [
    { u: 0.42, v: 0.56, du: 0.075, dv: 0.26 },
    { u: 0.71, v: 0.38, du: 0.065, dv: 0.24 },
    { u: 0.18, v: 0.72, du: 0.050, dv: 0.18 }
  ];

  for (const sc of scuffZones) {
    const scPts = [
      drawWallPoint(sc.u - sc.du * 0.5, sc.v + sc.dv * 0.3),
      drawWallPoint(sc.u + sc.du * 0.2, sc.v + sc.dv * 0.5),
      drawWallPoint(sc.u + sc.du * 0.6, sc.v - sc.dv * 0.1),
      drawWallPoint(sc.u + sc.du * 0.1, sc.v - sc.dv * 0.5),
      drawWallPoint(sc.u - sc.du * 0.6, sc.v - sc.dv * 0.2)
    ];
    // Torn white paper edge
    drawWashShape(scPts, "#f2ebd9", 210, 0.08);
    // Underlying bare steel showing through the scuff
    const barePts = [
      drawWallPoint(sc.u - sc.du * 0.3, sc.v + sc.dv * 0.2),
      drawWallPoint(sc.u + sc.du * 0.35, sc.v + sc.dv * 0.15),
      drawWallPoint(sc.u + sc.du * 0.2, sc.v - sc.dv * 0.3),
      drawWallPoint(sc.u - sc.du * 0.35, sc.v - sc.dv * 0.15)
    ];
    drawWashShape(barePts, PAL.silver, 220, 0.06);

    // Diagonal metallic scratch marks across the scuffed label
    for (let m = 0; m < 6; m++) {
      const pA = drawWallPoint(
        sc.u - sc.du * 0.6 + random(-0.02, 0.02),
        sc.v + random(-sc.dv * 0.4, sc.dv * 0.4)
      );
      const pB = drawWallPoint(
        sc.u + sc.du * 0.6 + random(-0.02, 0.02),
        sc.v + random(-sc.dv * 0.4, sc.dv * 0.4) - 0.08
      );
      strokeLine("cpencil", m % 2 === 0 ? PAL.silverBright : PAL.silverDark, 0.75, pA[0], pA[1], pB[0], pB[1]);
    }
  }

  // Translucent golden olive oil drip seeping down from the rim over the label
  const oilDripPoly = [
    drawWallPoint(0.56, 1.02),
    drawWallPoint(0.64, 1.02),
    drawWallPoint(0.63, 0.45),
    drawWallPoint(0.60, 0.18),
    drawWallPoint(0.57, 0.42)
  ];
  drawFillShape(oilDripPoly, PAL.oliveYellow, 115, 0.18, 0.55, 0.45, 0.12);
  const dripHighlight = [
    drawWallPoint(0.615, 0.95),
    drawWallPoint(0.61, 0.55),
    drawWallPoint(0.60, 0.24)
  ];
  strokeSpline("sable_fine", PAL.burnishWhite, 0.85, dripHighlight, 0.3);
}

// ============================================================================
// 4. TIN INTERIOR WELL & DEEP OLIVE OIL POOL
// ============================================================================

function renderTinInteriorAndOilPool() {
  const N = 120;
  const innerRimTop = [];
  const oilSurfacePts = [];

  for (let i = 0; i < N; i++) {
    const s = i / N;
    const d = getTinRimData(s, 11);
    innerRimTop.push(proj(d.x, d.y, TIN_H - 1));
    oilSurfacePts.push(proj(d.x, d.y, OIL_Z));
  }

  // Recessed interior metal wall visible on the back-left and back-long sides
  drawWashShape(innerRimTop, "#2b3036", 240, 0.05);

  for (let i = 0; i < N; i++) {
    const s1 = i / N;
    const s2 = (i + 1) / N;
    const d1 = getTinRimData(s1, 11);
    const d2 = getTinRimData(s2, 11);
    const [rx, ry] = rotXY(d1.nx, d1.ny);

    // Interior wall is visible where outward normal points away from viewer (ry < 0.15)
    if (ry < 0.15) {
      const quad = [
        proj(d1.x, d1.y, OIL_Z - 2),
        proj(d2.x, d2.y, OIL_Z - 2),
        proj(d2.x, d2.y, TIN_H - 1),
        proj(d1.x, d1.y, TIN_H - 1)
      ];
      // Back-right wall catches bright studio light; back-left is in cool shadow under the rim
      const col = rx > 0.1 ? PAL.silverLight : rx > -0.35 ? PAL.silverMid : PAL.silverDark;
      drawWashShape(quad, col, 210, 0.02);
      // Warm amber reflection from the olive oil pool
      drawWashShape(quad, PAL.olive, 70, 0.02);
    }
  }

  // Deep golden-amber Olive Oil pool filling the interior well
  drawWashShape(oilSurfacePts, PAL.oliveDeep, 245, 0.05);
  drawFillShape(oilSurfacePts, PAL.oliveDark, 165, 0.20, 0.62, 0.40, 0.05);

  // Luminous golden sub-surface glow in the oil pool
  const glowRegions = [
    { x: -115, y: -65, rx: 65, ry: 38, col: PAL.oliveYellow },
    { x: 35, y: 58, rx: 75, ry: 36, col: PAL.olive },
    { x: -40, y: 82, rx: 85, ry: 28, col: PAL.oliveBright },
    { x: 85, y: -72, rx: 58, ry: 34, col: PAL.oliveYellow }
  ];

  for (const gr of glowRegions) {
    const gPts = [];
    for (let a = 0; a < 360; a += 30) {
      gPts.push(proj(gr.x + cos(a) * gr.rx, gr.y + sin(a) * gr.ry, OIL_Z));
    }
    drawFillShape(gPts, gr.col, 115, 0.28, 0.55, 0.30, 0.15);
  }
}

// ============================================================================
// 5. THREE PLUMP HYPERREAL SARDINES
// Built in cool glazes of cobalt, silver grey, and olive oil yellow
// ============================================================================

function getFishPoint3D(fish, u, v, zLift = 0) {
  // u in [0, 1] along spine; v in [-1, 1] across flank (-1 toward back wall, +1 toward front wall)
  const x = lerp(fish.x0, fish.x1, u);

  // Taper profile: broad at cut collar end, tapering toward tail end
  const headU = fish.headLeft ? u : 1 - u;
  const widthFactor =
    0.50 +
    0.52 * sin(pow(headU, 0.62) * 142) * (1 - 0.26 * pow(headU, 1.4));
  const halfW = fish.maxHalfW * clampVal(widthFactor, 0.34, 1.04);

  // Gentle organic S-curve along the spine
  const spineWave =
    fish.curveAmp * sin(u * 180 + fish.curvePhase) +
    fish.curveSkew * (u - 0.5);

  const y = fish.yCenter + spineWave + v * halfW;

  // Plump cylindrical cross-section emerging above the olive oil pool
  const arch = sqrt(max(0, 1 - v * v));
  const endDip = sin(clampVal(u, 0.02, 0.98) * 180);
  const z =
    OIL_Z -
    3 +
    fish.thickness * arch * (0.48 + 0.52 * pow(endDip, 0.45)) +
    zLift;

  return { x, y, z, headU, arch, halfW };
}

function getFishStripPoly(fish, u0, u1, v0, v1, uSteps = 12, zLift = 0) {
  const pts = [];
  for (let i = 0; i <= uSteps; i++) {
    const u = lerp(u0, u1, i / uSteps);
    const p = getFishPoint3D(fish, u, v0, zLift);
    pts.push(proj(p.x, p.y, p.z));
  }
  for (let i = uSteps; i >= 0; i--) {
    const u = lerp(u0, u1, i / uSteps);
    const p = getFishPoint3D(fish, u, v1, zLift);
    pts.push(proj(p.x, p.y, p.z));
  }
  return pts;
}

function renderSingleSardine(fish, idx) {
  // 5A. Submerged dark olive-umber shadow around the fish in the oil pool
  const oilShadowPts = [];
  const M = 24;
  for (let i = 0; i <= M; i++) {
    const u = i / M;
    const p = getFishPoint3D(fish, u, -1.16, -2);
    oilShadowPts.push(proj(p.x, p.y, OIL_Z));
  }
  for (let i = M; i >= 0; i--) {
    const u = i / M;
    const p = getFishPoint3D(fish, u, 1.16, -2);
    oilShadowPts.push(proj(p.x, p.y, OIL_Z));
  }
  drawFillShape(oilShadowPts, PAL.oliveDeep, 175, 0.20, 0.55, 0.40, 0.08);

  // 5B. Full fish silhouette base in cool silver-grey wash
  const baseSilhouette = getFishStripPoly(fish, 0.02, 0.98, -0.98, 0.98, 22, 0);
  drawWashShape(baseSilhouette, PAL.silver, 240, 0.06);

  // 5C. WATERCOLOUR GLAZES: COBALT BLUE, SILVER GREY, AND OLIVE OIL YELLOW
  // Dorsal side (-v or +v depending on orientation): deep cool Cobalt Blue glazes
  const dorsalSign = fish.dorsalFront ? 1 : -1;
  const d0 = dorsalSign > 0 ? 0.12 : -0.96;
  const d1 = dorsalSign > 0 ? 0.96 : -0.12;

  const cobaltBandOuter = getFishStripPoly(fish, 0.03, 0.97, d0, d1, 20, 0.2);
  drawFillShape(cobaltBandOuter, PAL.cobaltMid, 130, 0.22, 0.65, 0.38, 0.08);

  const dCore0 = dorsalSign > 0 ? 0.38 : -0.94;
  const dCore1 = dorsalSign > 0 ? 0.94 : -0.38;
  const cobaltBandCore = getFishStripPoly(fish, 0.04, 0.95, dCore0, dCore1, 18, 0.3);
  drawFillShape(cobaltBandCore, PAL.cobalt, 155, 0.18, 0.68, 0.45, 0.08);

  const dDeep0 = dorsalSign > 0 ? 0.58 : -0.92;
  const dDeep1 = dorsalSign > 0 ? 0.92 : -0.58;
  const cobaltBandDeep = getFishStripPoly(fish, 0.06, 0.92, dDeep0, dDeep1, 16, 0.4);
  drawFillShape(cobaltBandDeep, PAL.cobaltDeep, 145, 0.15, 0.60, 0.42, 0.08);

  // Ventral/Flank side: luminous Silver Grey & gleaming Guanine sheen
  const v0 = dorsalSign > 0 ? -0.92 : -0.25;
  const v1 = dorsalSign > 0 ? 0.25 : 0.92;
  const silverFlank = getFishStripPoly(fish, 0.04, 0.96, v0, v1, 20, 0.3);
  drawFillShape(silverFlank, PAL.silverLight, 140, 0.18, 0.50, 0.32, 0.08);

  const silverRidge = getFishStripPoly(fish, 0.08, 0.90, -0.35, 0.32, 18, 0.5);
  drawWashShape(silverRidge, PAL.silverBright, 165, 0.06);

  // Olive Oil Yellow glazes pooling along the lower flanks and hollows
  const oilFlankLeft = getFishStripPoly(fish, 0.03, 0.96, -0.98, -0.52, 16, 0.2);
  const oilFlankRight = getFishStripPoly(fish, 0.03, 0.96, 0.52, 0.98, 16, 0.2);
  drawFillShape(oilFlankLeft, PAL.oliveYellow, 115, 0.24, 0.58, 0.36, 0.08);
  drawFillShape(oilFlankRight, PAL.oliveYellow, 125, 0.24, 0.58, 0.36, 0.08);

  // Golden oil puddle glazed directly across the mid-body dip
  const oilGlazePatch = getFishStripPoly(fish, 0.28, 0.74, -0.48, 0.48, 12, 0.6);
  drawFillShape(oilGlazePatch, PAL.oliveBright, 78, 0.28, 0.52, 0.28, 0.10);

  // 5D. CUT COLLAR (HEAD END) & TAIL PEDUNCLE ANATOMY
  const uCollar = fish.headLeft ? 0.025 : 0.975;
  const uCollarIn = fish.headLeft ? 0.085 : 0.915;
  const collarPts = [];
  for (let s = -0.88; s <= 0.88; s += 0.22) {
    const p = getFishPoint3D(fish, uCollar, s, 0);
    collarPts.push(proj(p.x, p.y, p.z));
  }
  for (let s = 0.88; s >= -0.88; s -= 0.22) {
    const p = getFishPoint3D(fish, uCollarIn, s, 0.4);
    collarPts.push(proj(p.x, p.y, p.z));
  }
  // Cooked flaky salmon-ochre / buff flesh at the cut collar
  drawWashShape(collarPts, PAL.fleshMid, 225, 0.08);
  drawFillShape(collarPts, PAL.fleshDark, 135, 0.14, 0.65, 0.45, 0.08);

  // Pale ring of the severed vertebra at center of collar cut
  const spineCenter = getFishPoint3D(fish, lerp(uCollar, uCollarIn, 0.45), 0, -1.5);
  const spProj = proj(spineCenter.x, spineCenter.y, spineCenter.z);
  const vertRing = [];
  for (let a = 0; a < 360; a += 45) {
    vertRing.push([spProj[0] + cos(a) * 5.5, spProj[1] + sin(a) * 4.2]);
  }
  drawWashShape(vertRing, PAL.fleshCream, 230, 0.15);
  strokeLine("sable_fine", PAL.fleshDark, 0.85, spProj[0] - 2, spProj[1], spProj[0] + 2, spProj[1]);

  // Small split in the fragile silver skin revealing cooked flesh underneath
  const splitU0 = fish.splitU - 0.065;
  const splitU1 = fish.splitU + 0.065;
  const splitV0 = fish.splitV - 0.28;
  const splitV1 = fish.splitV + 0.28;
  const skinSplitPoly = getFishStripPoly(fish, splitU0, splitU1, splitV0, splitV1, 6, 0.7);
  drawWashShape(skinSplitPoly, PAL.fleshLight, 215, 0.12);
  drawFillShape(skinSplitPoly, PAL.fleshDark, 110, 0.16, 0.65, 0.45, 0.12);

  // Flaky myomere muscle striations inside the exposed flesh patch
  for (let k = 0; k < 5; k++) {
    const uu = lerp(splitU0 + 0.01, splitU1 - 0.01, k / 4);
    const p1 = getFishPoint3D(fish, uu, splitV0 + 0.05, 0.8);
    const p2 = getFishPoint3D(fish, uu + 0.015, splitV1 - 0.05, 0.8);
    const s1 = proj(p1.x, p1.y, p1.z);
    const s2 = proj(p2.x, p2.y, p2.z);
    strokeLine("sable_fine", PAL.fleshDark, 0.65, s1[0], s1[1], s2[0], s2[1]);
    strokeLine("cpencil", PAL.fleshCream, 0.6, s1[0] + 1.2, s1[1], s2[0] + 1.2, s2[1]);
  }

  // 5E. HYPERREAL SCALE POCKETS, LATERAL LINE & CHEVRON MYOMERES
  // Longitudinal lateral line running from collar to tail
  const latV = dorsalSign * 0.26;
  const latPts = [];
  for (let i = 0; i <= 24; i++) {
    const u = lerp(0.06, 0.94, i / 24);
    const p = getFishPoint3D(fish, u, latV, 0.8);
    latPts.push(proj(p.x, p.y, p.z));
  }
  strokeSpline("sable_fine", PAL.cobaltDeep, 0.85, latPts, 0.4);

  // Dotted pores along the lateral line & dorsal spine scar
  for (let i = 1; i < 23; i++) {
    const u = lerp(0.08, 0.92, i / 23);
    const p1 = getFishPoint3D(fish, u, latV - 0.04, 0.9);
    const p2 = getFishPoint3D(fish, u + 0.008, latV + 0.04, 0.9);
    const s1 = proj(p1.x, p1.y, p1.z);
    const s2 = proj(p2.x, p2.y, p2.z);
    strokeLine("sable_fine", PAL.cobaltDeep, 0.7, s1[0], s1[1], s2[0], s2[1]);
  }

  // Diamond / crescent scale mesh and chevron skin striations across the 3D surface
  const uRows = 22;
  const vCols = 7;
  for (let iu = 1; iu < uRows; iu++) {
    const u = lerp(0.07, 0.93, iu / uRows);
    for (let iv = 0; iv < vCols; iv++) {
      const v = lerp(-0.82, 0.82, (iv + (iu % 2) * 0.45) / vCols);
      // Skip inside the flaked skin split
      if (u > splitU0 && u < splitU1 && v > splitV0 && v < splitV1) continue;

      const pMid = getFishPoint3D(fish, u, v, 0.9);
      const pTop = getFishPoint3D(fish, u + 0.018, v - 0.11, 0.9);
      const pBot = getFishPoint3D(fish, u + 0.018, v + 0.11, 0.9);

      const sMid = proj(pMid.x, pMid.y, pMid.z);
      const sTop = proj(pTop.x, pTop.y, pTop.z);
      const sBot = proj(pBot.x, pBot.y, pBot.z);

      const isDorsal = v * dorsalSign > 0.18;
      const edgeCol = isDorsal
        ? iu % 2 === 0
          ? PAL.cobaltDeep
          : PAL.cobalt
        : iu % 2 === 0
        ? PAL.silverDark
        : PAL.cobaltMist;

      // Scale crescent pocket
      strokeSpline("sable_fine", edgeCol, 0.58, [sTop, sMid, sBot], 0.45);

      // Iridescent guanine silver or olive-gold glint on the scale ridge
      if ((iu + iv + idx) % 2 === 0) {
        const glintCol =
          abs(v) < 0.35
            ? PAL.silverBright
            : isDorsal
            ? PAL.cobaltMist
            : PAL.oliveGleam;
        strokeLine(
          "cpencil",
          glintCol,
          0.72,
          sMid[0] + 1.2,
          sMid[1] - 0.8,
          (sMid[0] + sBot[0]) * 0.5 + 1.2,
          (sMid[1] + sBot[1]) * 0.5 - 0.8
        );
      }
    }
  }

  // 5F. LIQUID OLIVE OIL MENISCUS & WET SPECULAR HIGHLIGHTS
  // Golden ring of refracted olive oil where the fish flanks meet the oil pool
  for (const vSide of [-0.94, 0.94]) {
    const meniscusPts = [];
    for (let i = 0; i <= 20; i++) {
      const u = lerp(0.05, 0.95, i / 20);
      const p = getFishPoint3D(fish, u, vSide, 0.2);
      meniscusPts.push(proj(p.x, p.y, OIL_Z + 0.5));
    }
    strokeSpline("glaze_wash", PAL.oliveYellow, 0.9, meniscusPts, 0.4);
    strokeSpline("cpencil", PAL.oliveGleam, 0.85, meniscusPts, 0.4);

    // Broken razor-sharp white specular dashes along the wet meniscus
    for (let i = 1; i < 19; i += 2) {
      if ((i + idx) % 3 === 0) continue;
      const pA = meniscusPts[i];
      const pB = meniscusPts[i + 1];
      strokeLine("sable_fine", PAL.burnishWhite, 0.9, pA[0], pA[1], pB[0], pB[1]);
    }
  }

  // Blinding wet specular highlight strip along the upper-left lit crown of the sardine
  const specV = -0.18;
  const specCrownPts = [];
  for (let i = 0; i <= 18; i++) {
    const u = lerp(0.10, 0.88, i / 18);
    const p = getFishPoint3D(fish, u, specV + sin(u * 360) * 0.04, 1.1);
    specCrownPts.push(proj(p.x, p.y, p.z));
  }
  strokeSpline("agate_burnish", PAL.burnishCream, 1.35, specCrownPts, 0.45);

  // Interrupted pure white wet oil catch-lights along the crown
  for (let i = 1; i < specCrownPts.length - 2; i += 2) {
    const p0 = specCrownPts[i];
    const p1 = specCrownPts[i + 1];
    strokeLine("sable_fine", "#ffffff", 1.15, p0[0], p0[1], p1[0], p1[1]);
    strokeLine("cpencil", "#ffffff", 0.9, p0[0] + 0.8, p0[1] - 0.8, p1[0] + 0.8, p1[1] - 0.8);
  }

  // Tiny trapped golden oil bubbles in the meniscus near the collar and crevices
  const bubbleLocations = [
    { u: 0.12, v: 0.88, r: 3.4 },
    { u: 0.16, v: 0.92, r: 2.2 },
    { u: 0.78, v: -0.88, r: 3.0 },
    { u: 0.48, v: 0.90, r: 2.5 }
  ];
  for (const b of bubbleLocations) {
    const bp = getFishPoint3D(fish, b.u, b.v, 0.4);
    const sc = proj(bp.x, bp.y, OIL_Z + 1);
    strokeLine("sable_fine", PAL.oliveDark, 0.8, sc[0] - b.r, sc[1], sc[0] + b.r, sc[1]);
    strokeLine("sable_fine", "#ffffff", 0.95, sc[0] - b.r * 0.5, sc[1] - b.r * 0.5, sc[0] + b.r * 0.3, sc[1] - b.r * 0.5);
  }
}

function renderAllSardines() {
  // Three plump sardines nestled side-by-side from back wall (y < 0) to front wall (y > 0)
  // Ordered back-to-front so front sardines naturally overlap back ones
  const sardines = [
    {
      // Back sardine (head at left, tail tucked under curled lid at right)
      x0: -174,
      x1: 146,
      yCenter: -68,
      maxHalfW: 36,
      thickness: 22,
      headLeft: true,
      dorsalFront: false,
      curveAmp: 4.5,
      curvePhase: 15,
      curveSkew: -3,
      splitU: 0.36,
      splitV: 0.12
    },
    {
      // Middle sardine (alternating: tail at left, plump cut collar toward right)
      x0: -172,
      x1: 144,
      yCenter: 0,
      maxHalfW: 38,
      thickness: 24,
      headLeft: false,
      dorsalFront: true,
      curveAmp: -5.0,
      curvePhase: 40,
      curveSkew: 2,
      splitU: 0.58,
      splitV: -0.15
    },
    {
      // Front sardine (head at left, plump silver belly pressed against front wall)
      x0: -170,
      x1: 142,
      yCenter: 68,
      maxHalfW: 37,
      thickness: 23,
      headLeft: true,
      dorsalFront: false,
      curveAmp: 4.0,
      curvePhase: -20,
      curveSkew: 4,
      splitU: 0.44,
      splitV: -0.10
    }
  ];

  for (let i = 0; i < sardines.length; i++) {
    renderSingleSardine(sardines[i], i);
  }

  // Deep golden-amber oil meniscus pooling in the crevasse between adjacent sardines
  for (const yCrevasse of [-34, 34]) {
    const crevPts = [];
    for (let i = 0; i <= 20; i++) {
      const x = lerp(-162, 136, i / 20);
      const wave = 3.5 * sin((i / 20) * 180 + 25);
      crevPts.push(proj(x, yCrevasse + wave, OIL_Z + 1.2));
    }
    strokeSpline("glaze_wash", PAL.oliveDeep, 1.3, crevPts, 0.4);
    strokeSpline("sable_fine", PAL.oliveBright, 0.85, crevPts, 0.4);

    // Specular oil pinpoints along the inter-fish valley
    for (let i = 2; i < 18; i += 3) {
      const p0 = crevPts[i];
      const p1 = crevPts[i + 1];
      strokeLine("sable_fine", "#ffffff", 0.85, p0[0], p0[1], p1[0], p1[1]);
    }
  }
}

// ============================================================================
// 6. TOP ROLLED RIM, DOUBLE SEAM & JAGGED CUT METAL LIP
// ============================================================================

function renderTopRimAndCutEdge() {
  const N = 160;

  // 6A. Recessed flat metal shelf between outer rolled bead (inset = 1) and cut lip (inset = 11)
  for (let i = 0; i < N; i++) {
    const s1 = i / N;
    const s2 = (i + 1) / N;
    const out1 = getTinRimData(s1, 1);
    const out2 = getTinRimData(s2, 1);
    const in1 = getTinRimData(s1, 11);
    const in2 = getTinRimData(s2, 11);

    const [rx, ry] = rotXY(out1.nx, out1.ny);
    const quad = [
      proj(out1.x, out1.y, TIN_H - 1.5),
      proj(out2.x, out2.y, TIN_H - 1.5),
      proj(in2.x, in2.y, TIN_H - 2.0),
      proj(in1.x, in1.y, TIN_H - 2.0)
    ];

    const shelfCol =
      rx + ry < -0.4
        ? PAL.silverLight
        : rx + ry > 0.4
        ? PAL.silverDark
        : PAL.silver;
    drawWashShape(quad, shelfCol, 220, 0.02);
  }

  // 6B. Sharp, slightly serrated cut inner metal lip where the lid was sheared open
  const cutEdgePts = [];
  const cutShadowPts = [];
  for (let i = 0; i <= N; i++) {
    const s = i / N;
    // Slight micro-serration from key-opening shear
    const serration = (i % 2 === 0 ? 0.65 : -0.65) + sin(i * 37) * 0.4;
    const d = getTinRimData(s, 11.2 + serration);
    // Stop cut lip under the attached lid roll on the far right (x > 138)
    if (d.x > 142) continue;
    cutEdgePts.push(proj(d.x, d.y, TIN_H - 1.8));
    cutShadowPts.push(proj(d.x, d.y, TIN_H - 3.6));
  }
  strokeSpline("sable_fine", "#1b2226", 1.15, cutShadowPts, 0.25);
  strokeSpline("sable_fine", PAL.silverBright, 0.95, cutEdgePts, 0.25);

  // Razor-sharp white glints along the sheared inner edge
  for (let i = 2; i < cutEdgePts.length - 3; i += 4) {
    const p0 = cutEdgePts[i];
    const p1 = cutEdgePts[i + 1];
    strokeLine("sable_fine", "#ffffff", 0.95, p0[0], p0[1], p1[0], p1[1]);
  }

  // 6C. Outer Rolled Rim Bead (3D tubular double-seam flange around the perimeter)
  const outerCreasePts = [];
  const innerCreasePts = [];
  const crownHighlightPts = [];

  for (let i = 0; i < N; i++) {
    const s1 = i / N;
    const s2 = (i + 1) / N;

    const pOut1 = getTinRimData(s1, -6.5);
    const pOut2 = getTinRimData(s2, -6.5);
    const pMid1 = getTinRimData(s1, -2.2);
    const pMid2 = getTinRimData(s2, -2.2);
    const pIn1 = getTinRimData(s1, 1.8);
    const pIn2 = getTinRimData(s2, 1.8);

    const [rx, ry] = rotXY(pMid1.nx, pMid1.ny);

    // Outer bevel of the rolled bead
    const outerQuad = [
      proj(pOut1.x, pOut1.y, TIN_H - 0.5),
      proj(pOut2.x, pOut2.y, TIN_H - 0.5),
      proj(pMid2.x, pMid2.y, TIN_H + 3.8),
      proj(pMid1.x, pMid1.y, TIN_H + 3.8)
    ];

    // Inner bevel of the rolled bead
    const innerQuad = [
      proj(pMid1.x, pMid1.y, TIN_H + 3.8),
      proj(pMid2.x, pMid2.y, TIN_H + 3.8),
      proj(pIn2.x, pIn2.y, TIN_H - 1.0),
      proj(pIn1.x, pIn1.y, TIN_H - 1.0)
    ];

    const lightDot = -(rx * 0.72 + ry * 0.58);
    const colOuter =
      lightDot > 0.35
        ? PAL.silverBright
        : lightDot > -0.15
        ? PAL.silver
        : PAL.silverDark;
    const colInner =
      lightDot < -0.25
        ? PAL.silverLight
        : lightDot < 0.25
        ? PAL.silverMid
        : PAL.silverDark;

    drawWashShape(outerQuad, colOuter, 235, 0.02);
    drawWashShape(innerQuad, colInner, 225, 0.02);

    // Warm gold reflection on the outer underside of the front bead
    if (ry > 0.25) {
      drawWashShape(outerQuad, PAL.ochreLight, 65, 0.02);
    }

    outerCreasePts.push(proj(pOut1.x, pOut1.y, TIN_H - 1.0));
    innerCreasePts.push(proj(pIn1.x, pIn1.y, TIN_H - 1.2));
    crownHighlightPts.push(proj(pMid1.x, pMid1.y, TIN_H + 3.8));
  }

  outerCreasePts.push(outerCreasePts[0]);
  innerCreasePts.push(innerCreasePts[0]);
  crownHighlightPts.push(crownHighlightPts[0]);

  strokeSpline("2B", "#2b333b", 0.9, innerCreasePts, 0.35);
  strokeSpline("2B", "#323b42", 0.85, outerCreasePts, 0.35);
  strokeSpline("sable_fine", PAL.silverBright, 1.05, crownHighlightPts, 0.35);

  // Gleaming white specular arcs on the rounded corners of the top rim
  for (let i = 0; i < N; i++) {
    const s = i / N;
    const d = getTinRimData(s, -2.2);
    const [rx, ry] = rotXY(d.nx, d.ny);
    if (abs(rx + ry) < 0.42 || rx < -0.55) {
      const pA = crownHighlightPts[i];
      const pB = crownHighlightPts[(i + 1) % N];
      strokeLine("sable_fine", "#ffffff", 1.25, pA[0], pA[1], pB[0], pB[1]);
    }
  }

  // Droplets of golden olive oil clinging to the flat rim shelf
  const rimDrops = [
    { s: 0.08, inset: 6.5, r: 4.5 },
    { s: 0.19, inset: 5.5, r: 6.0 },
    { s: 0.62, inset: 6.0, r: 5.2 },
    { s: 0.84, inset: 6.2, r: 4.0 }
  ];
  for (const rd of rimDrops) {
    const d = getTinRimData(rd.s, rd.inset);
    const c = proj(d.x, d.y, TIN_H - 1.2);
    const dropPts = [];
    for (let a = 0; a < 360; a += 45) {
      dropPts.push([c[0] + cos(a) * rd.r, c[1] + sin(a) * rd.r * 0.68]);
    }
    drawFillShape(dropPts, PAL.oliveYellow, 180, 0.12, 0.45, 0.40, 0.2);
    strokeLine("sable_fine", "#ffffff", 0.95, c[0] - 1.5, c[1] - 1.2, c[0] + 1.5, c[1] - 1.2);
  }
}

// ============================================================================
// 7. THE CURLED METAL LID & SLOTTED SARDINE KEY
// ============================================================================

function renderCurledLidAndKey() {
  // The lid remains attached along the right end of the tin (x ≈ 132..172)
  // and curls upward into a tight 3.5-turn cylindrical spiral scroll centered at:
  const rollX = 148;
  const rollZ = TIN_H + 33;
  const rollR = 32;
  const yMin = -114;
  const yMax = 114;

  // 7A. Curved ramp of the lid peeling up from the recessed tin lip into the spiral roll
  const rampSteps = 14;
  for (let i = 0; i < rampSteps; i++) {
    const t1 = i / rampSteps;
    const t2 = (i + 1) / rampSteps;

    // Curve from (x = 128, z = TIN_H - 2) up to bottom-right of cylinder (phi = -35 deg)
    const x1 = lerp(126, rollX + rollR * 0.82, t1);
    const z1 = lerp(TIN_H - 2, rollZ - rollR * 0.45, pow(t1, 0.75));
    const x2 = lerp(126, rollX + rollR * 0.82, t2);
    const z2 = lerp(TIN_H - 2, rollZ - rollR * 0.45, pow(t2, 0.75));

    // Taper y slightly near the rounded corners of the tin
    const ySpan1 = min(yMax, sqrt(max(100, TIN_RY * TIN_RY - max(0, abs(x1) - 85) * 80)));
    const ySpan2 = min(yMax, sqrt(max(100, TIN_RY * TIN_RY - max(0, abs(x2) - 85) * 80)));

    const quad = [
      proj(x1, -ySpan1, z1),
      proj(x2, -ySpan2, z2),
      proj(x2, ySpan2, z2),
      proj(x1, ySpan1, z1)
    ];

    // Underside of peeling lid: warm golden canning lacquer & olive oil reflection
    const col = i < 5 ? PAL.oliveDark : i < 10 ? PAL.ochre : PAL.silverMid;
    drawWashShape(quad, col, 215, 0.02);
  }

  // 7B. THE CYLINDRICAL SPIRAL SCROLL (Outer surface of the rolled lid)
  // Angle phi around cylinder axis (y): 0 is +x, 90 is +z (top), 180 is -x (facing inside tin), 270 is -z
  const phiSteps = 28;
  for (let i = 0; i < phiSteps; i++) {
    const phi1 = lerp(-35, 235, i / phiSteps);
    const phi2 = lerp(-35, 235, (i + 1) / phiSteps);

    const x1 = rollX + cos(phi1) * rollR;
    const z1 = rollZ + sin(phi1) * rollR;
    const x2 = rollX + cos(phi2) * rollR;
    const z2 = rollZ + sin(phi2) * rollR;

    const stripQuad = [
      proj(x1, yMin, z1),
      proj(x2, yMin, z2),
      proj(x2, yMax, z2),
      proj(x1, yMax, z1)
    ];

    // Cylindrical studio lighting (bright specular ridge around phi = 118 deg)
    const angDiff = abs(phi1 - 118);
    let stripCol;
    if (angDiff < 16) {
      stripCol = PAL.silverBright;
    } else if (angDiff < 42) {
      stripCol = PAL.silverLight;
    } else if (phi1 < 35) {
      // Lower-right curve reflecting the burnished gold leaf ground!
      stripCol = PAL.ochreLight;
    } else if (phi1 > 185) {
      // Lower-left curve reflecting the dark cobalt & olive oil interior
      stripCol = PAL.cobalt;
    } else {
      stripCol = PAL.silverMid;
    }

    drawWashShape(stripQuad, stripCol, 230, 0.02);

    // Remnant of the scuffed printed top label wrapping around the cylinder (y in [-72, +72])
    if (phi1 > 20 && phi1 < 175) {
      const labelQuad = [
        proj(x1, -72, z1),
        proj(x2, -72, z2),
        proj(x2, 72, z2),
        proj(x1, 72, z1)
      ];
      const lblCol =
        phi1 > 55 && phi1 < 85
          ? PAL.labelRed
          : phi1 > 135 && phi1 < 158
          ? PAL.labelInk
          : PAL.labelCream;
      drawWashShape(labelQuad, lblCol, angDiff < 20 ? 115 : 175, 0.02);
    }
  }

  // Stamped expansion ridges & winding crimp marks along the rolled metal lid
  for (const yCrimp of [-92, -58, -22, 18, 56, 90]) {
    const arcPts = [];
    for (let phi = -20; phi <= 215; phi += 15) {
      const x = rollX + cos(phi) * (rollR + 0.6);
      const z = rollZ + sin(phi) * (rollR + 0.6);
      arcPts.push(proj(x, yCrimp, z));
    }
    strokeSpline("sable_fine", PAL.silverDark, 0.72, arcPts, 0.4);
    strokeSpline("cpencil", PAL.silverBright, 0.65, arcPts.slice(3, 11), 0.4);
  }

  // Blinding longitudinal specular highlight bar along the crown of the curled lid (phi = 118 deg)
  const lidCrownPts = [];
  const lidCrownSub = [];
  for (let k = 0; k <= 16; k++) {
    const yy = lerp(yMin + 3, yMax - 3, k / 16);
    const x = rollX + cos(118) * (rollR + 0.8);
    const z = rollZ + sin(118) * (rollR + 0.8);
    lidCrownPts.push(proj(x, yy, z));
    lidCrownSub.push(proj(x - 2.5, yy, z - 1.2));
  }
  strokeSpline("agate_burnish", PAL.burnishWhite, 1.6, lidCrownPts, 0.3);
  strokeSpline("sable_fine", "#ffffff", 1.25, lidCrownPts, 0.3);
  strokeSpline("2B", PAL.cobaltDeep, 0.85, lidCrownSub, 0.3);

  // 7C. ARCHIMEDEAN SPIRAL CROSS-SECTIONS AT BOTH ENDS OF THE LID ROLL
  // Back-left end (y = yMin) and front-right end (y = yMax, facing viewer!)
  for (const yEnd of [yMin, yMax]) {
    const isFrontEnd = yEnd === yMax;
    // Dark hollow shadow inside the coiled metal turns
    const endDisc = [];
    for (let a = 0; a < 360; a += 20) {
      endDisc.push(proj(rollX + cos(a) * rollR, yEnd, rollZ + sin(a) * rollR));
    }
    drawWashShape(endDisc, isFrontEnd ? "#1b2229" : "#2d3740", 240, 0.1);

    // 3.5 concentric spiral wraps of sheared silver tinplate edge
    const spiralPts = [];
    const totalTurns = 3.4;
    const steps = 68;
    for (let s = 0; s <= steps; s++) {
      const t = s / steps;
      const ang = t * totalTurns * 360 + 25;
      const rad = lerp(5.5, rollR, pow(t, 0.88));
      const sx = rollX + cos(ang) * rad;
      const sz = rollZ + sin(ang) * rad;
      spiralPts.push(proj(sx, yEnd, sz));
    }
    // Warm golden lacquer on inside face of the spiral coil
    strokeSpline("sable_fine", PAL.ochreLight, 1.05, spiralPts, 0.35);
    // Razor-sharp silver-white cut metal spiral edge
    strokeSpline("sable_fine", PAL.silverBright, 0.95, spiralPts, 0.35);
    if (isFrontEnd) {
      strokeSpline("cpencil", "#ffffff", 0.75, spiralPts.slice(24), 0.35);
    }
  }

  // 7D. THE SLOTTED METAL SARDINE KEY
  // Protruding from the center of the spiral roll (y = yMax) out toward y = yMax + 92
  const keyY0 = yMax - 4;
  const keyY1 = yMax + 52;
  const shaftR = 4.5;

  const shaftPoly = [
    proj(rollX - shaftR, keyY0, rollZ - 2),
    proj(rollX + shaftR, keyY0, rollZ - 2),
    proj(rollX + shaftR, keyY1, rollZ + 2),
    proj(rollX - shaftR, keyY1, rollZ + 2)
  ];
  drawWashShape(shaftPoly, PAL.silverDark, 235, 0.04);

  const shaftHi1 = proj(rollX - 1.5, keyY0, rollZ + 2.5);
  const shaftHi2 = proj(rollX - 1.5, keyY1, rollZ + 2.5);
  strokeLine("sable_fine", "#ffffff", 1.15, shaftHi1[0], shaftHi1[1], shaftHi2[0], shaftHi2[1]);

  // Iconic flat-stamped oval/teardrop finger loop at the end of the key
  const loopCenterY = keyY1 + 24;
  const loopOuter = [];
  const loopInner = [];
  const loopThick = [];

  for (let a = 0; a < 360; a += 18) {
    const ly = loopCenterY + cos(a) * 24;
    const lx = rollX + sin(a) * 16;
    const lz = rollZ + 2 + sin(a) * 3;
    loopOuter.push(proj(lx, ly, lz));
    loopThick.push(proj(lx, ly, lz - 4.5));

    const inY = loopCenterY + cos(a) * 13.5;
    const inX = rollX + sin(a) * 8.5;
    loopInner.push(proj(inX, inY, lz));
  }

  // Draw metal loop ring using two half-annuli so the central keyhole stays open showing the gold ground!
  const halfLen = int(loopOuter.length / 2);
  const ringSideA = [
    ...loopOuter.slice(0, halfLen + 1),
    ...loopInner.slice(0, halfLen + 1).reverse()
  ];
  const ringSideB = [
    ...loopOuter.slice(halfLen),
    loopOuter[0],
    loopInner[0],
    ...loopInner.slice(halfLen).reverse()
  ];

  drawWashShape(ringSideA, PAL.silver, 240, 0.1);
  drawWashShape(ringSideB, PAL.silverMid, 240, 0.1);

  // Dark steel bottom thickness of the stamped key loop
  strokeSpline("2B", "#222a30", 1.35, [...loopThick, loopThick[0]], 0.45);
  strokeSpline("sable_fine", PAL.silverDark, 1.0, [...loopInner, loopInner[0]], 0.45);
  strokeSpline("sable_fine", PAL.silverBright, 1.1, [...loopOuter, loopOuter[0]], 0.45);
  // Crisp white catch-light on the top-left curve of the key handle
  strokeSpline("sable_fine", "#ffffff", 1.15, loopOuter.slice(8, 16), 0.45);
}

