// Local-to-world coordinate frame helper for tilted geometric planes
function createFrame(cx, cy, angleDeg) {
  const rad = (angleDeg * Math.PI) / 180;
  const c = Math.cos(rad);
  const s = Math.sin(rad);
  return {
    cx,
    cy,
    angle: angleDeg,
    pt(lx, ly) {
      return [cx + lx * c - ly * s, cy + lx * s + ly * c];
    },
    pts(arr) {
      return arr.map(([lx, ly]) => [cx + lx * c - ly * s, cy + lx * s + ly * c]);
    },
    line(x1, y1, x2, y2) {
      const [wx1, wy1] = this.pt(x1, y1);
      const [wx2, wy2] = this.pt(x2, y2);
      brush.line(wx1, wy1, wx2, wy2);
    },
    spline(pts, curv = 0.5) {
      const wpts = pts.map((p) => {
        const [wx, wy] = this.pt(p[0], p[1]);
        return p.length > 2 ? [wx, wy, p[2]] : [wx, wy];
      });
      brush.spline(wpts, curv);
    },
    poly(pts, curv = 0) {
      brush.beginShape(curv);
      for (let i = 0; i < pts.length; i++) {
        const [wx, wy] = this.pt(pts[i][0], pts[i][1]);
        brush.vertex(wx, wy);
      }
      brush.endShape(true);
    }
  };
}

function drawWorldPoly(pts, curv = 0) {
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

function resetBrushState() {
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.noField();
}

function draw() {
  translate(-width / 2, -height / 2);

  // 1. Subtle bone-white void atmospheric grain (barely-there museum paper tooth)
  drawBoneVoidAtmosphere();

  // Frames for the 4 floating geometric breakfast objects
  const bookFrame = createFrame(410, 415, -33.5);
  const toastFrame = createFrame(695, 675, -24.5);
  const cupFrame = createFrame(830, 340, 56.5);
  const peelFrame = createFrame(430, 775, -33.5);

  // 2. Soft hovering contact shadows (batched first so all objects float in pure void)
  drawAllHoveringShadows(bookFrame, toastFrame, cupFrame, peelFrame);

  // 3. Object 1: The Red Paperback
  drawRedPaperback(bookFrame);

  // 4. Object 2: The Slab of Buttered Toast
  drawButteredToast(toastFrame);

  // 5. Object 3: The Black Coffee Cup Seen Square from Above
  drawBlackCoffeeCup(cupFrame);

  // 6. Object 4: The Thin Yellow Strip of Lemon Peel
  drawLemonPeel(peelFrame);

  // 7. Weightless Crumbs, Crust Flakes & Butter/Sugar Micro-Incidents
  drawFloatingCrumbs(toastFrame, peelFrame, cupFrame);

  noLoop();
}

