function drawBoneVoidAtmosphere() {
  resetBrushState();
  // Ultra-faint warm bone paper tone along the diagonal axis
  brush.hatchStyle("2H", "#EBE5D8", 0.45);
  brush.hatch(14, -33.5, { rand: 0.15 });
  brush.rect(600, 600, 1120, 1120, "center");
