  // Sparse micro-fibers in the bone-white paper
  brush.set("2H", "#E5DECFE0", 0.3);
  for (let i = 0; i < 90; i++) {
    let x = random(60, 1140);
    let y = random(60, 1140);
    let a = random(360);
    let len = random(4, 14);
    brush.line(x, y, x + cos(a) * len, y + sin(a) * len);
  }
}

// ============================================================================
// 2. HOVERING CONTACT SHADOWS (NO TABLE, NO GROUND)
// ============================================================================
function drawAllHoveringShadows(bookF, toastF, cupF, peelF) {
  resetBrushState();

  // Helper to offset local polygon points into world shadow coordinates
  const shadowPts = (frame, localPts, dx, dy, scaleX = 1, scaleY = 1) => {
    return localPts.map(([lx, ly]) => {
      const [wx, wy] = frame.pt(lx * scaleX, ly * scaleY);
      return [wx + dx, wy + dy];
    });
  };

  const bookRect = [
    [-128, -188],
    [134, -188],
    [134, 194],
    [-128, 194]
  ];

  const toastOutline = [
    [-122, -128],
    [-40, -135],
    [45, -134],
    [124, -124],
    [129, -45],
    [124, 126],
    [5, 132],
    [-122, 124],
    [-127, -40]
  ];

  // Lemon peel arches in the middle: ends hover close, center hovers higher
  const peelShadowOuter = [
    [-118, -10],
    [-35, -10],
    [45, -9],
    [118, -12],
    [112, 12],
    [40, 19],
    [-35, 18],
    [-124, 12]
  ];

  // PASS A: Wide soft outer penumbra (#DFD8CA)
  brush.noStroke();
  brush.fill("#DDD5C6", 52);
  brush.fillBleed(0.38, "out");
  brush.fillTexture(0.22, 0.05);

  drawWorldPoly(shadowPts(bookF, bookRect, 28, 38, 1.03, 1.03), 0.08);
  drawWorldPoly(shadowPts(toastF, toastOutline, 26, 35, 1.04, 1.04), 0.15);
  brush.circle(cupF.cx + 26, cupF.cy + 35, 136, 0.04);
  drawWorldPoly(shadowPts(peelF, peelShadowOuter, 20, 28, 1.04, 1.15), 0.2);

  // PASS B: Mid penumbra (#C4B9A7)
  brush.fill("#C4B9A7", 68);
  brush.fillBleed(0.26, "out");
  brush.fillTexture(0.25, 0.08);

  drawWorldPoly(shadowPts(bookF, bookRect, 20, 27, 1.0, 1.0), 0.06);
  drawWorldPoly(shadowPts(toastF, toastOutline, 19, 25, 1.0, 1.0), 0.12);
  brush.circle(cupF.cx + 19, cupF.cy + 26, 128, 0.03);
  // Handle shadow
  drawWorldPoly(
    shadowPts(
      cupF,
      [
        [75, -13],
        [120, -13],
        [120, 13],
        [75, 13]
      ],
      20,
      27
    ),
    0.05
  );
  drawWorldPoly(shadowPts(peelF, peelShadowOuter, 14, 19, 0.98, 0.95), 0.2);

  // PASS C: Tight core contact umbra (#9B8F7E)
  brush.fill("#9B8F7E", 78);
  brush.fillBleed(0.16, "out");
  brush.fillTexture(0.3, 0.1);

  drawWorldPoly(shadowPts(bookF, bookRect, 12, 17, 0.97, 0.97), 0.04);
  drawWorldPoly(shadowPts(toastF, toastOutline, 12, 16, 0.97, 0.97), 0.1);
  brush.circle(cupF.cx + 12, cupF.cy + 16, 118, 0.02);
  // Lemon peel contact shadow is tight at the two tips where it nearly touches
  drawWorldPoly(
    shadowPts(
      peelF,
      [
        [-118, -9],
        [-65, -7],
        [-65, 10],
        [-122, 11]
      ],
      8,
      11
    ),
    0.15
  );
  drawWorldPoly(
    shadowPts(
      peelF,
      [
        [65, -8],
        [116, -10],
        [110, 11],
        [65, 11]
      ],
      8,
      11
    ),
    0.15
  );

  resetBrushState();

  // PASS D: Fine graphite pencil hatch & grain inside shadows for hyperreal softness
  brush.hatchStyle("2H", "#8E8272", 0.5);
  brush.hatch(4.5, -33.5, { rand: 0.08 });
  drawWorldPoly(shadowPts(bookF, bookRect, 15, 21, 0.99, 0.99), 0.02);
  drawWorldPoly(shadowPts(toastF, toastOutline, 15, 20, 0.99, 0.99), 0.08);
  brush.circle(cupF.cx + 15, cupF.cy + 20, 123, 0.02);
  drawWorldPoly(shadowPts(peelF, peelShadowOuter, 13, 18, 0.96, 0.9), 0.15);
  resetBrushState();

  // Soft pencil edge feathering on shadow rims
  brush.set("soft_graphite", "#ACA190", 0.75);
  for (let a = -20; a < 110; a += 4) {
    let r = 128 + random(-3, 4);
    let x1 = cupF.cx + 20 + cos(a) * r;
    let y1 = cupF.cy + 27 + sin(a) * r;
    brush.line(x1, y1, x1 + cos(a + 90) * 10, y1 + sin(a + 90) * 10);
  }
}

// ============================================================================
// 3. THE RED PAPERBACK (Crisp Marker Plane + Hyperreal Graphite & Gloss)
// ============================================================================
function drawRedPaperback(f) {
  resetBrushState();
  const w = 256;
  const h = 376;
  const hw = w / 2; // 128
  const hh = h / 2; // 188

  // --- A. 3D Page-Block Edge (Bottom and Right sliver) ---
  const bottomPages = [
    [-hw + 3, hh],
    [hw, hh],
    [hw + 9, hh + 10],
    [-hw + 10, hh + 10]
  ];
  const rightPages = [
    [hw, -hh + 3],
    [hw + 9, -hh + 12],
    [hw + 9, hh + 10],
    [hw, hh]
  ];

  // Marker base for cream page block
  brush.wash("#E4D8C1", 240);
  f.poly(bottomPages, 0);
  brush.wash("#CFC0A6", 240);
  f.poly(rightPages, 0);
  resetBrushState();

  // Fine compressed paper-sheet striations with Rotring & 2H pencil
  for (let i = 1; i <= 8; i++) {
    let t = i / 9;
    brush.set(i % 2 === 0 ? "2H" : "rotring", i % 3 === 0 ? "#8F7E66" : "#B5A58B", 0.35);
    f.line(-hw + 3 + t * 7, hh + t * 10, hw + t * 9, hh + t * 10);
    f.line(hw + t * 9, -hh + 3 + t * 9, hw + t * 9, hh + t * 10);
  }

  // Shadow under the overhanging front cover lip
  brush.set("2B", "#5A4938", 0.65);
  f.line(-hw + 4, hh + 1.2, hw + 1, hh + 1.2);
  f.line(hw + 1.2, -hh + 4, hw + 1.2, hh + 1);

  // --- B. Main Front Cover: Crisp Terracotta/Oxblood Red Marker Plane ---
  const coverPoly = [
    [-hw, -hh],
    [hw, -hh],
    [hw, hh],
    [-hw, hh]
  ];

  brush.wash("#9E3224", 248);
  f.poly(coverPoly, 0);
  resetBrushState();

  // Chisel-marker flat strokes along the cover's vertical axis for authentic marker plane
  brush.hatchStyle("chisel_marker", "#A83728", 1.05);
  brush.hatch(8.5, f.angle + 90, { rand: 0.015 });
  f.poly(coverPoly, 0);
  resetBrushState();

  // --- C. Constructivist / Vintage Paperback Cream Bands & Typography ---
  const topBand = [
    [-hw + 18, -118],
    [hw - 14, -118],
    [hw - 14, -36],
    [-hw + 18, -36]
  ];
  const botBand = [
    [-hw + 18, 114],
    [hw - 14, 114],
    [hw - 14, 146],
    [-hw + 18, 146]
  ];

  brush.wash("#EFE8D8", 242);
  f.poly(topBand, 0);
  f.poly(botBand, 0);
  resetBrushState();

  // Marker texture inside the cream bands
  brush.hatchStyle("chisel_marker", "#F4EFE2", 0.8);
  brush.hatch(7, f.angle, { rand: 0.01 });
  f.poly(topBand, 0);
  f.poly(botBand, 0);
  resetBrushState();

  // Crisp warm-black graphic rules framing the bands
  brush.set("rotring", "#28221E", 0.65);
  f.line(-hw + 18, -118, hw - 14, -118);
  f.line(-hw + 18, -36, hw - 14, -36);
  f.line(-hw + 18, -113, hw - 14, -113);
  f.line(-hw + 18, -41, hw - 14, -41);

  f.line(-hw + 18, 114, hw - 14, 114);
  f.line(-hw + 18, 146, hw - 14, 146);

  // Minimalist typographic blocks inside the top band (author / title bars)
  // Title line 1 (bold condensed earth-black)
  brush.set("rotring", "#241E1B", 0.9);
  for (let lx = -82; lx <= 78; lx += 7.5) {
    if (Math.abs(lx - 10) < 6) continue; // word space
    let charW = random(3.2, 5.2);
    f.line(lx, -92, lx + charW, -92);
    f.line(lx, -89.5, lx + charW, -89.5);
    f.line(lx, -87, lx + charW * 0.85, -87);
    f.line(lx, -92, lx, -85);
    if (random() > 0.4) f.line(lx + charW, -92, lx + charW, -85);
  }
  // Title line 2 (shorter centered)
  for (let lx = -54; lx <= 56; lx += 7) {
    if (Math.abs(lx + 8) < 5) continue;
    let charW = random(3.0, 4.8);
    f.line(lx, -74, lx + charW, -74);
    f.line(lx, -71, lx + charW * 0.9, -71);
    f.line(lx, -74, lx, -68);
  }
  // Small terracotta-red subtitle rule & author text
  brush.set("rotring", "#962E20", 0.7);
  f.line(-35, -58, 38, -58);
  brush.set("rotring", "#3A312C", 0.55);
  for (let lx = -46; lx <= 48; lx += 5.2) {
    if (Math.abs(lx) < 4) continue;
    f.line(lx, -50, lx + 3, -50);
    f.line(lx, -48, lx + 2.8, -48);
  }

  // Publisher emblem in bottom band (minimalist geometric circle + colophon ticks)
  const [emX, emY] = f.pt(2, 130);
  brush.set("rotring", "#28221E", 0.6);
  brush.circle(emX, emY, 8.5, 0.02);
  brush.set("rotring", "#962E20", 0.55);
  f.line(-4, 127, 8, 127);
  f.line(-2, 133, 6, 133);

  // --- D. Hyperrealistic Pencil Shading, Spine Hinge Groove & Surface Gloss ---
  // 1. Deep shadow toward bottom-right of cover (pencil cross-hatching)
  const shadeZone = [
    [-hw + 20, 10],
    [hw, -60],
    [hw, hh],
    [-hw, hh]
  ];
  brush.hatchStyle("cpencil", "#781F15", 0.65);
  brush.hatch(3.5, f.angle + 35, { rand: 0.06, gradient: 0.65 });
  f.poly(shadeZone, 0);
  resetBrushState();

  brush.hatchStyle("2B", "#52140D", 0.5);
  brush.hatch(4.5, f.angle - 25, { rand: 0.08, gradient: 0.75 });
  f.poly(
    [
      [0, 60],
      [hw, -10],
      [hw, hh],
      [-hw + 40, hh]
    ],
    0
  );
  resetBrushState();

  // 2. Upper-left raking light & satin laminate gloss across the cover
  const glossZone = [
    [-hw, -hh],
    [hw - 20, -hh],
    [25, 45],
    [-hw, 95]
  ];
  brush.hatchStyle("cpencil", "#C85A49", 0.6);
  brush.hatch(3.2, f.angle + 45, { rand: 0.04, gradient: 0.6 });
  f.poly(glossZone, 0);
  resetBrushState();

  // Bright specular sheen streak across upper-left of cover
  const specStreak = [
    [-hw + 16, -hh + 8],
    [45, -hh + 8],
    [-25, 25],
    [-hw + 16, 55]
  ];
  brush.hatchStyle("2H", "#EFA696", 0.55);
  brush.hatch(2.6, f.angle + 42, { rand: 0.03, gradient: 0.7 });
  f.poly(specStreak, 0);
  resetBrushState();

  // 3. The Spine Rounding & Reader's Hinge Crease (x = -hw + 16)
  // Left spine edge dark roll-off
  for (let dx = -hw; dx <= -hw + 7; dx += 1.2) {
    let col = dx < -hw + 3 ? "#4D130C" : "#752016";
    brush.set("2B", col, 0.55);
    f.line(dx, -hh, dx, hh);
  }
  // Spine crown highlight (x = -hw + 8 to -hw + 12)
  for (let dx = -hw + 8.5; dx <= -hw + 12.5; dx += 1.0) {
    brush.set("cpencil", "#E68D7C", 0.55);
    f.line(dx, -hh + 2, dx, hh - 2);
  }
  // Razor-sharp gloss highlight along the spine ridge
  brush.set("gloss_pen", "#FCE3DC", 0.65);
  f.line(-hw + 10, -hh + 6, -hw + 10, 40);
  brush.set("gloss_pen", "#F5B8A8", 0.45);
  f.line(-hw + 10, 45, -hw + 10, hh - 12);

  // Deep hinge crease groove at x = -hw + 17.5
  brush.set("rotring", "#3D0E08", 0.6);
  f.line(-hw + 17.5, -hh + 1, -hw + 17.5, hh - 1);
  brush.set("2B", "#631910", 0.5);
  f.line(-hw + 16.3, -hh + 2, -hw + 16.3, hh - 2);
  // Crisp highlight catching the right lip of the hinge groove (x = -hw + 19)
  brush.set("gloss_pen", "#F7CFC4", 0.6);
  f.line(-hw + 19, -hh + 4, -hw + 19, hh - 8);

  // 4. Thumb-worn corners, laminate micro-scratches & dog-ear crease
  // Top-left & bottom-right worn card corners exposing pale board (#E3D6BF)
  brush.set("gloss_pen", "#E8DCC6", 0.85);
  f.line(hw - 6, hh - 0.5, hw, hh - 0.5);
  f.line(hw - 0.5, hh - 7, hw - 0.5, hh);
  f.line(hw - 4, hh - 2, hw - 1, hh - 5);
  f.line(-hw, -hh + 5, -hw + 5, -hh);

  // Subtle diagonal reader's crease near bottom-right corner catching specular light
  brush.set("2B", "#59150E", 0.4);
  f.line(hw - 48, hh, hw, hh - 54);
  brush.set("gloss_pen", "#F2B6A7", 0.5);
  f.line(hw - 46.8, hh, hw, hh - 52.5);

  // Top edge highlight catching overhead light
  brush.set("gloss_pen", "#F9D6CC", 0.65);
  f.line(-hw + 2, -hh + 0.6, hw - 10, -hh + 0.6);

  // Crisp outer contour definition
  brush.set("rotring", "#3B110B", 0.45);
  f.line(-hw, -hh, hw, -hh);
  f.line(-hw, -hh, -hw, hh);
  f.line(-hw, hh, hw, hh);
  f.line(hw, -hh, hw, hh);
}

// ============================================================================
// 4. THE SLAB OF BUTTERED TOAST (Marker Planes + Pores, Crust & Melting Butter)
// ============================================================================
function drawButteredToast(f) {
  resetBrushState();

  // Slightly vaulted artisanal sandwich-loaf silhouette (local coords)
  const topFace = [
    [-120, -118],
    [-85, -132],
    [0, -136],
    [85, -132],
    [122, -116],
    [126, -72],
    [118, -32],
    [120, 45],
    [118, 122],
    [40, 127],
    [-40, 127],
    [-118, 120],
    [-121, 35],
    [-118, -35],
    [-125, -75]
  ];

  // Inner crumb boundary (inset from crust rim by ~11-15px)
  const innerCrumb = [
    [-106, -104],
    [-75, -117],
    [0, -121],
    [75, -117],
    [108, -102],
    [111, -68],
    [104, -32],
    [106, 42],
    [104, 108],
    [35, 113],
    [-35, 113],
    [-104, 106],
    [-107, 32],
    [-104, -32],
    [-110, -70]
  ];

  // --- A. 3D Side Crust Thickness (Visible along bottom and right edges) ---
  const sideCrust = [
    [122, -116],
    [134, -104],
    [138, -60],
    [130, -20],
    [132, 55],
    [129, 134],
    [50, 140],
    [-30, 140],
    [-106, 132],
    [-118, 120],
    [-40, 127],
    [40, 127],
    [118, 122],
    [120, 45],
    [118, -32],
    [126, -72]
  ];

  brush.wash("#4F2D16", 248);
  f.poly(sideCrust, 0.12);
  resetBrushState();

  brush.hatchStyle("chisel_marker", "#3D210E", 0.9);
  brush.hatch(6, f.angle + 45, { rand: 0.05 });
  f.poly(sideCrust, 0.12);
  resetBrushState();

  // Baking striations, blisters & flour dusting on side crust
  brush.set("2B", "#261205", 0.65);
  for (let i = 0; i < 28; i++) {
    let t = i / 28;
    let lx = -105 + t * 222;
    f.line(lx, 123, lx + 9, 136);
  }
  for (let i = 0; i < 24; i++) {
    let t = i / 24;
    let ly = -105 + t * 225;
    f.line(120, ly, 131, ly + 11);
  }
  // Pale artisanal flour crevices on side crust
  brush.set("cpencil", "#D4BE9C", 0.5);
  f.line(-65, 131, -20, 134);
  f.line(35, 133, 85, 131);
  f.line(126, 15, 127, 68);

  // --- B. Top Crust Rim (Crisp Dark Roasted Umber Marker) ---
  brush.wash("#63391C", 248);
  f.poly(topFace, 0.14);
  resetBrushState();

  // --- C. Interior Bread Crumb Plane (Warm Wheat & Golden Maillard Marker Planes) ---
  brush.wash("#E5CFA6", 248);
  f.poly(innerCrumb, 0.14);
  resetBrushState();

  // Flat chisel-marker base pass across the bread interior
  brush.hatchStyle("chisel_marker", "#DEC393", 1.0);
  brush.hatch(8, f.angle, { rand: 0.02 });
  f.poly(innerCrumb, 0.14);
  resetBrushState();

  // Distinct Maillard toasted patches laid in warm ochre & amber-brown marker
  const toastZones = [
    // Upper-left golden-brown toasted patch
    {
      col: "#C78E46",
      pts: [
        [-95, -95],
        [-15, -110],
        [-5, -35],
        [-92, -20]
      ]
    },
    // Upper-right rich amber patch
    {
      col: "#B87832",
      pts: [
        [10, -108],
        [96, -92],
        [95, -15],
        [15, -25]
      ]
    },
    // Lower-left toasted patch
    {
      col: "#C28640",
      pts: [
        [-96, 15],
        [-20, 20],
        [-15, 102],
        [-92, 95]
      ]
    },
    // Lower-right deeply toasted patch
    {
      col: "#AC6C28",
      pts: [
        [15, 15],
        [96, 10],
        [94, 96],
        [5, 102]
      ]
    },
    // Darker caramelized toaster-bar ridges
    {
      col: "#874D1A",
      pts: [
        [-78, -82],
        [-32, -88],
        [-28, -48],
        [-72, -42]
      ]
    },
    {
      col: "#824917",
      pts: [
        [35, -85],
        [82, -75],
        [78, -30],
        [30, -40]
      ]
    },
    {
      col: "#8A501C",
      pts: [
        [28, 42],
        [80, 38],
        [76, 84],
        [22, 86]
      ]
    }
  ];

  for (let z of toastZones) {
    brush.wash(z.col, 165);
    f.poly(z.pts, 0.25);
    resetBrushState();
    brush.hatchStyle("cpencil", z.col, 0.65);
    brush.hatch(3.5, f.angle + 25, { rand: 0.08 });
    f.poly(z.pts, 0.25);
    resetBrushState();
  }

  // --- D. Melted Butter Translucent Golden Pool (Soaking into the Bread Center) ---
  const meltedPool = [
    [-68, -58],
    [-12, -74],
    [52, -62],
    [76, -15],
    [68, 48],
    [22, 74],
    [-45, 68],
    [-75, 22]
  ];

  brush.noStroke();
  brush.fill("#D9A63B", 135);
  brush.fillBleed(0.22, "out");
  brush.fillTexture(0.35, 0.15);
  f.poly(meltedPool, 0.25);

  brush.fill("#E8C258", 115);
  brush.fillBleed(0.15, "in");
  f.poly(
    [
      [-52, -42],
      [38, -46],
      [54, 34],
      [-42, 46]
    ],
    0.25
  );
  resetBrushState();

  // --- E. Hyperreal Bread Crumb Matrix: 420 Aerated Pores (Alveoli) & Char Ridges ---
  for (let i = 0; i < 420; i++) {
    let lx = random(-102, 102);
    let ly = random(-112, 106);

    // Skip the opaque center where the unmelted butter pat sits
    if (lx > -36 && lx < 36 && ly > -28 && ly < 28) continue;

    // Determine if point is inside the melted butter zone
    let dCenter = Math.hypot(lx * 0.95, ly * 1.05);
    let inMelted = dCenter < 68;

    let poreR = random(1.1, 4.2);
    if (dCenter < 85 && random() < 0.25) poreR = random(3.5, 6.2); // occasional larger sourdough alveoli

    const [wx, wy] = f.pt(lx, ly);

    // 1. Dark recessed pore shadow (upper-left inner wall)
    let shadowCol = inMelted ? "#7A4B14" : dCenter > 88 ? "#8F5E2E" : "#6E3F17";
    brush.set("2B", shadowCol, random(0.45, 0.75));
    brush.arc(wx, wy, poreR, 175, 355);

    // Deepest pinhole center for larger alveoli
    if (poreR > 2.8) {
      brush.set("rotring", "#3D1F08", 0.45);
      brush.circle(wx - 0.5, wy - 0.5, poreR * 0.45, 0.15);
    }

    // 2. Lit toasted ridge on lower-right rim of the pore
    let rimCol = inMelted ? "#F7DF88" : random() > 0.4 ? "#F2E0BC" : "#E0B26B";
    brush.set("gloss_pen", rimCol, random(0.45, 0.7));
    brush.arc(wx, wy, poreR, -5, 155);

    // 3. Occasional dark caramelized char fleck on raised crumb bridges
    if (!inMelted && random() < 0.22) {
      brush.set("rotring", "#3B1D09", random(0.4, 0.65));
      brush.line(wx + poreR, wy - 1, wx + poreR + random(1.5, 3.5), wy + random(-1.5, 1.5));
    }

    // 4. Tiny glistening melted-butter oil droplet inside soaked pores
    if (inMelted && random() < 0.38) {
      brush.set("gloss_pen", "#FFFDF2", random(0.55, 0.85));
      brush.line(wx + 0.8, wy + 0.8, wx + 2.2, wy + 1.4);
    }
  }

  // Crust perimeter detail: dark blistered Maillard rim & crisp crumb-to-crust seam
  for (let i = 0; i < topFace.length; i++) {
    let p1 = topFace[i];
    let p2 = topFace[(i + 1) % topFace.length];
    let c1 = innerCrumb[i];
    let c2 = innerCrumb[(i + 1) % innerCrumb.length];

    brush.set("2B", "#2E1708", 0.75);
    f.line(p1[0], p1[1], p2[0], p2[1]);

    brush.set("cpencil", "#8A5324", 0.65);
    f.line(c1[0], c1[1], c2[0], c2[1]);

    // Specular crust blisters along the top vaulted crown
    if (p1[1] < -60) {
      brush.set("gloss_pen", "#D9A46C", 0.55);
      f.line(
        (p1[0] + c1[0]) * 0.5,
        (p1[1] + c1[1]) * 0.5,
        (p2[0] + c2[0]) * 0.5,
        (p2[1] + c2[1]) * 0.5
      );
    }
  }

  // --- F. The Softening Pat of Butter in the Center ---
  // Tilted slightly relative to the toast for natural placement
  const butterFrame = createFrame(f.cx - 2, f.cy - 4, f.angle - 9);

  // 1. Soft translucent skirt of slumping butter around the pat
  const butterSkirt = [
    [-54, -40],
    [0, -44],
    [54, -38],
    [58, 0],
    [52, 40],
    [-4, 44],
    [-55, 38],
    [-58, -2]
  ];
  brush.wash("#E8CA6B", 220);
  butterFrame.poly(butterSkirt, 0.28);
  resetBrushState();

  // 2. Side bevel of the butter pat (lower and right thickness)
  const butterSide = [
    [-46, 30],
    [46, 29],
    [45, -29],
    [53, -22],
    [52, 36],
    [-39, 37]
  ];
  brush.wash("#D4B14A", 245);
  butterFrame.poly(butterSide, 0.12);
  resetBrushState();

  // 3. Crisp top plane of the butter pat (creamy pale yellow marker)
  const butterTop = [
    [-46, -30],
    [45, -29],
    [46, 29],
    [-46, 30]
  ];
  brush.wash("#F5E6A4", 250);
  butterFrame.poly(butterTop, 0.12);
  resetBrushState();

  brush.hatchStyle("chisel_marker", "#F8ECBA", 0.85);
  brush.hatch(6, butterFrame.angle, { rand: 0.02 });
  butterFrame.poly(butterTop, 0.12);
  resetBrushState();

  // 4. Knife-spread ridges & creamy shading across the butter pat
  brush.hatchStyle("cpencil", "#DFC165", 0.55);
  brush.hatch(3.5, butterFrame.angle + 12, { rand: 0.05, gradient: 0.5 });
  butterFrame.poly(
    [
      [-44, -5],
      [44, -12],
      [45, 28],
      [-45, 29]
    ],
    0.1
  );
  resetBrushState();

  // Diagonal knife-blade wave striations across the soft butter top
  for (let y = -24; y <= 24; y += 4.5) {
    brush.set("2H", "#D6B656", 0.45);
    butterFrame.spline(
      [
        [-40, y],
        [-10, y - 2.5],
        [20, y + 1.5],
        [40, y - 1]
      ],
      0.4
    );
    if (y % 9 === 0) {
      brush.set("gloss_pen", "#FFFDF6", 0.65);
      butterFrame.spline(
        [
          [-38, y - 1],
          [-8, y - 3.5],
          [22, y + 0.5],
          [38, y - 2]
        ],
        0.4
      );
    }
  }

  // 5. Wet Surface Gloss on the Melting Butter Edges & Clarified Oil Pool
  brush.set("gloss_pen", "#FFFFFF", 0.95);
  // Bright liquid-gloss rim along top-left & bottom-right bevel of butter pat
  butterFrame.spline(
    [
      [-44, 24],
      [-46, -28],
      [38, -28]
    ],
    0.25
  );
  butterFrame.spline(
    [
      [-32, 29.5],
      [12, 29.5],
      [44, 26],
      [45.5, -12]
    ],
    0.25
  );

  // Specular pools of melted liquid butter catching overhead light
  const glossPools = [
    [
      [-55, -18],
      [-48, -32],
      [-36, -34]
    ],
    [
      [48, -8],
      [56, 12],
      [46, 28]
    ],
    [
      [-28, 36],
      [0, 41],
      [28, 37]
    ],
    [
      [-18, -39],
      [15, -40],
      [35, -34]
    ]
  ];
  for (let gp of glossPools) {
    brush.set("gloss_pen", "#FFFFFF", 0.85);
    butterFrame.spline(gp, 0.5);
  }
}

// ============================================================================
// 5. THE BLACK COFFEE CUP SEEN SQUARE FROM ABOVE
// ============================================================================
function drawBlackCoffeeCup(f) {
  resetBrushState();
  const cx = f.cx;
  const cy = f.cy;

  // --- A. Ceramic Saucer (R = 130) in Muted Stone-Putty Earth Tone ---
  brush.wash("#D5CEC2", 248);
  brush.circle(cx, cy, 130, 0.012);
  resetBrushState();

  brush.hatchStyle("chisel_marker", "#CFC7B9", 0.95);
  brush.hatch(8.5, f.angle - 90, { rand: 0.015 });
  brush.circle(cx, cy, 129, 0.01);
  resetBrushState();

  // Radial ceramic glaze shading on saucer slope (lower-right shaded, upper-left lit)
  for (let a = 0; a < 360; a += 2.5) {
    let rad = (a * Math.PI) / 180;
    let c = Math.cos(rad);
    let s = Math.sin(rad);
    // Light from upper-left (-135 deg)
    let lightDot = Math.cos(((a + 135) * Math.PI) / 180);

    if (lightDot < 0) {
      // Shaded lower-right slope of saucer
      brush.set("soft_graphite", "#A39A8B", 0.45 * Math.abs(lightDot));
      brush.line(cx + c * 86, cy + s * 86, cx + c * 127, cy + s * 127);
    } else {
      // Lit upper-left slope of saucer
      brush.set("cpencil", "#EAE5DA", 0.45 * lightDot);
      brush.line(cx + c * 88, cy + s * 88, cx + c * 126, cy + s * 126);
    }
  }

  // Saucer inner well ring (R = 86)
  brush.set("2H", "#9E9485", 0.55);
  brush.arc(cx, cy, 86, 145, 325);
  brush.set("gloss_pen", "#F7F4EC", 0.65);
  brush.arc(cx, cy, 86, -35, 145);

  // Cast shadow of the cup body onto the saucer well
  brush.noStroke();
  brush.fill("#857B6D", 110);
  brush.fillBleed(0.18, "out");
  brush.circle(cx + 13, cy + 17, 83, 0.02);

  brush.fill("#5E564B", 125);
  brush.fillBleed(0.1, "out");
  brush.circle(cx + 8, cy + 11, 81, 0.02);
  resetBrushState();

  // Handle cast shadow on saucer rim & beyond
  const handleShadow = f.pts([
    [76, -11],
    [118, -11],
    [118, 11],
    [76, 11]
  ]).map(([wx, wy]) => [wx + 11, wy + 15]);
  brush.noStroke();
  brush.fill("#7A7062", 105);
  brush.fillBleed(0.15, "out");
  drawWorldPoly(handleShadow, 0.08);
  resetBrushState();

  // Saucer outer rim specular glaze highlight & dark lower edge
  brush.set("gloss_pen", "#FFFFFF", 0.9);
  brush.arc(cx, cy, 129, 175, 295);
  brush.set("gloss_pen", "#F2EFE8", 0.65);
  brush.arc(cx, cy, 127.5, 165, 310);
  brush.set("2B", "#7D7467", 0.6);
  brush.arc(cx, cy, 130, -15, 135);

  // Tiny realism incident on saucer: a faint amber coffee splash ring & speck
  const [stX, stY] = f.pt(-55, 85);
  brush.set("cpencil", "#9E6430", 0.45);
  brush.arc(stX, stY, 6.5, 20, 290);
  brush.set("rotring", "#6E3F16", 0.4);
  brush.circle(stX + 2, stY + 1, 1.2, 0.1);

  // --- B. The Cup Handle (Flat Rectangular Ear Sticking Out at +56.5 deg) ---
  const handlePoly = [
    [78, -11.5],
    [118, -10.5],
    [118, 10.5],
    [78, 11.5]
  ];
  brush.wash("#221F1D", 252);
  f.poly(handlePoly, 0.06);
  resetBrushState();

  // Matte-satin charcoal shading & crisp ceramic ridge highlight on handle
  brush.set("2B", "#12100F", 0.7);
  f.line(79, 8.5, 117, 8.5);
  f.line(117.5, -9, 117.5, 9);
  brush.set("cpencil", "#544E49", 0.6);
  f.line(79, -6, 116, -6);
  brush.set("gloss_pen", "#EAE4D9", 0.85);
  f.line(80, -8.5, 115, -8);
  brush.set("gloss_pen", "#FFFFFF", 0.95);
  f.line(83, -9, 108, -8.6);

  // --- C. Cup Exterior Wall & Ceramic Lip (R = 84 outer, R = 74 inner) ---
  brush.wash("#211E1C", 255);
  brush.circle(cx, cy, 84, 0.01);
  resetBrushState();

  // Ceramic rim shading
  for (let r = 74.5; r <= 83.5; r += 1.2) {
    brush.set("2B", "#141210", 0.55);
    brush.arc(cx, cy, r, -25, 155);
    brush.set("cpencil", "#3B3632", 0.5);
    brush.arc(cx, cy, r, 155, 335);
  }

  // Razor-sharp ceramic rim lip highlight (R = 78.8)
  brush.set("gloss_pen", "#DFD9CE", 0.75);
  brush.arc(cx, cy, 79, 150, 330);
  brush.set("gloss_pen", "#FFFFFF", 0.95);
  brush.arc(cx, cy, 78.8, 185, 285);
  // Secondary bounce highlight on opposite rim
  brush.set("gloss_pen", "#C9C2B6", 0.65);
  brush.arc(cx, cy, 79, 15, 85);

  // --- D. Deep Black Coffee Liquid & Crema Meniscus (R = 74) ---
  brush.wash("#140F0C", 255);
  brush.circle(cx, cy, 74, 0.008);
  resetBrushState();

  // Warm mahogany-espresso subsurface depth on lower-right of liquid
  for (let r = 42; r <= 68; r += 2.2) {
    brush.set("cpencil", "#381F11", 0.55);
    brush.arc(cx, cy, r, -15, 115);
    brush.set("2B", "#0C0907", 0.65);
    brush.arc(cx, cy, r, 140, 320);
  }

  // Golden-hazelnut crema ring hugging the inner ceramic wall (r = 62 to 73.5)
  for (let r = 64; r <= 73.2; r += 1.1) {
    let col = r > 70 ? "#7A4419" : r > 67 ? "#B57336" : "#8F5322";
    brush.set("cpencil", col, 0.65);
    brush.arc(cx, cy, r, 0, 360);
  }
  // Feathered inner crema wisps bleeding into the black coffee
  brush.set("cpencil", "#9E5E28", 0.45);
  for (let a = 0; a < 360; a += 5) {
    let rad = (a * Math.PI) / 180;
    let rIn = 57 + noise(a * 0.1) * 9;
    brush.line(
      cx + Math.cos(rad) * rIn,
      cy + Math.sin(rad) * rIn,
      cx + Math.cos(rad) * 71,
      cy + Math.sin(rad) * 71
    );
  }

  // --- E. Surface Gloss (Curved Window Reflection on the Liquid Mirror) ---
  // Upper-left curved skylight reflection split by a window mullion bar
  const winPane1 = [];
  const winPane2 = [];
  for (let a = 178; a <= 232; a += 4) {
    let rad = (a * Math.PI) / 180;
    winPane1.push([cx + Math.cos(rad) * 63, cy + Math.sin(rad) * 63]);
  }
  for (let a = 232; a >= 178; a -= 4) {
    let rad = (a * Math.PI) / 180;
    winPane1.push([cx + Math.cos(rad) * 36, cy + Math.sin(rad) * 36]);
  }

  for (let a = 240; a <= 288; a += 4) {
    let rad = (a * Math.PI) / 180;
    winPane2.push([cx + Math.cos(rad) * 63, cy + Math.sin(rad) * 63]);
  }
  for (let a = 288; a >= 240; a -= 4) {
    let rad = (a * Math.PI) / 180;
    winPane2.push([cx + Math.cos(rad) * 38, cy + Math.sin(rad) * 38]);
  }

  brush.wash("#E8E2D6", 95);
  drawWorldPoly(winPane1, 0.15);
  drawWorldPoly(winPane2, 0.15);
  resetBrushState();

  // Crisp bright highlight streaks inside the liquid reflection
  for (let r = 42; r <= 61; r += 2.2) {
    brush.set("gloss_pen", r > 54 ? "#FFFFFF" : "#E5DFD3", r > 54 ? 0.75 : 0.45);
    brush.arc(cx, cy, r, 182, 228);
    brush.arc(cx, cy, r, 244, 284);
  }

  // --- F. Crema Micro-Bubbles (Foam Cells Hugging the Meniscus) ---
  // Dense clusters around the rim, each with a dark roasted ring & white pinpoint glint
  for (let i = 0; i < 135; i++) {
    // Cluster mostly along two crescent zones + complete thin perimeter ring
    let a =
      i < 55
        ? random(-45, 75)
        : i < 100
          ? random(135, 245)
          : random(0, 360);
    let rad = (a * Math.PI) / 180;
    let distFromWall = i < 100 ? random(1.5, 14) : random(1.2, 6.5);
    let r = 72.5 - distFromWall;
    let bx = cx + Math.cos(rad) * r;
    let by = cy + Math.sin(rad) * r;
    let bSize = map(distFromWall, 1, 14, 2.8, 0.9) * random(0.7, 1.35);

    // Bubble body
    brush.set("cpencil", "#DDA46A", 0.7);
    brush.circle(bx, by, bSize, 0.08);
    // Dark bubble wall
    brush.set("rotring", "#592E0E", 0.45);
    brush.arc(bx, by, bSize, 0, 240);
    // Pinpoint wet white reflection on every bubble
    if (bSize > 1.2) {
      brush.set("gloss_pen", "#FFFFFF", 0.9);
      brush.line(bx - bSize * 0.35, by - bSize * 0.35, bx - bSize * 0.1, by - bSize * 0.35);
    }
  }

  // Continuous razor-sharp liquid meniscus highlight where coffee meets cup wall
  brush.set("gloss_pen", "#FFFFFF", 0.9);
  brush.arc(cx, cy, 73.2, 165, 295);
  brush.set("gloss_pen", "#F7DFBA", 0.75);
  brush.arc(cx, cy, 72.8, -30, 95);
}

