function drawLemonPeel(f) {
  resetBrushState();

  // A pared geometric ribbon of citrus zest, chisel-cut at the ends,
  // with a creamy-white pith edge visible along the lower bevel and pared tip.
  const flavedoRibbon = [
    [-116, -11],
    [-40, -15],
    [40, -14],
    [118, -9],
    [104, 11],
    [35, 7],
    [-40, 6],
    [-124, 9]
  ];

  // White pith underside bevel along lower edge and left pared tip
  const pithBevel = [
    [-124, 9],
    [-40, 6],
    [35, 7],
    [104, 11],
    [118, -9],
    [123, -5],
    [108, 16],
    [35, 13],
    [-40, 12],
    [-128, 14],
    [-120, -9],
    [-116, -11]
  ];

  // --- A. Creamy-White Pith Bevel ---
  brush.wash("#EFE6CA", 248);
