      [-40, 10],
      [35, 11],
      [106, 14.5]
    ],
    0.35
  );
  brush.set("cpencil", "#9C8B65", 0.5);
  f.line(106, 15, 122, -5);

  // --- B. Crisp Citron / Ochre-Yellow Marker Plane ---
  brush.wash("#DCB338", 250);
  f.poly(flavedoRibbon, 0.18);
  resetBrushState();

  brush.hatchStyle("chisel_marker", "#E3BC42", 0.9);
  brush.hatch(5.5, f.angle, { rand: 0.015 });
  f.poly(flavedoRibbon, 0.18);
  resetBrushState();

  // --- C. 3D Arch Shading (Bright Crown in Middle, Shaded Turning Ends) ---
  // Left & right ends curve downward into warm golden-olive shadow
  const leftShade = [
    [-116, -11],
    [-55, -14],
    [-55, 6],
    [-124, 9]
  ];
  const rightShade = [
    [55, -13],
    [118, -9],
    [104, 11],
    [55, 7]
  ];

  brush.hatchStyle("cpencil", "#B08418", 0.6);
  brush.hatch(2.8, f.angle + 65, { rand: 0.05, gradient: 0.65 });
  f.poly(leftShade, 0.1);
  f.poly(rightShade, 0.1);
  resetBrushState();

  // Lower-edge cylinder roll-off shadow along the yellow peel
  for (let t = 0.65; t <= 0.95; t += 0.1) {
    brush.set("cpencil", t > 0.8 ? "#916A0E" : "#B88C1C", 0.55);
    f.spline(
      [
        [-120, -11 + t * 20],
        [-40, -15 + t * 21],
        [38, -14 + t * 21],
        [108, -9 + t * 20]
      ],
      0.35
    );
  }

  // Luminous sunlit citron crown along the arched center
  for (let t = 0.18; t <= 0.48; t += 0.08) {
    brush.set("cpencil", "#FAE482", 0.65);
    f.spline(
      [
        [-75, -13 + t * 20],
        [-15, -15 + t * 21],
        [45, -14 + t * 20]
      ],
      0.35
    );
  }

  // --- D. Essential-Oil Gland Dimples & Wet Citrus Specular Gloss ---
  for (let i = 0; i < 165; i++) {
    let lx = random(-112, 104);
    // Curve offset following the ribbon's gentle arch
    let archY = -4.5 * Math.cos((lx / 120) * (Math.PI * 0.5));
    let ly = archY + random(-7.5, 7.5);
    const [wx, wy] = f.pt(lx, ly);

    let inHighlight = lx > -65 && lx < 50 && ly < archY + 2;
    let dimpleCol = inHighlight ? "#B88E1E" : "#87620B";

    // Tiny recessed oil-gland pore
    brush.set("rotring", dimpleCol, random(0.35, 0.55));
    brush.arc(wx, wy, random(0.8, 1.5), 160, 350);

    // Bright specular crescent on the rim of each dimple in the lit zone
    if (inHighlight || random() < 0.35) {
      brush.set("gloss_pen", inHighlight ? "#FFFFFF" : "#FFF6C4", random(0.55, 0.9));
      brush.line(wx + 0.5, wy + 0.5, wx + 1.6, wy + 0.9);
    }
  }

  // Continuous wet citrus sheen along the upper arched ridge
  brush.set("gloss_pen", "#FFFFFF", 0.9);
  f.spline(
    [
      [-58, -11.5],
      [-10, -12.8],
      [38, -11.5]
    ],
    0.4
  );
  // Crisp pare-cut edge highlight where yellow skin meets white pith
  brush.set("gloss_pen", "#FFFDF2", 0.75);
  f.spline(
    [
      [-122, 8.5],
      [-40, 5.8],
      [35, 6.8],
      [103, 10.5]
    ],
    0.35
  );
}

