function drawFloatingCrumbs(toastF, peelF, cupF) {
  resetBrushState();

  // Hand-curated + procedural constellation of crumbs drifting along the diagonal
  const crumbs = [
    // Major golden & dark crust crumbs near toast bottom-left & lemon peel
    { x: 548, y: 748, r: 6.5, type: "crust" },
    { x: 562, y: 760, r: 3.8, type: "golden" },
    { x: 532, y: 774, r: 2.6, type: "pale" },
    { x: 576, y: 732, r: 4.5, type: "golden" },
    { x: 518, y: 722, r: 3.2, type: "crust" },

    // Cluster between book, toast, and cup
    { x: 585, y: 535, r: 5.2, type: "golden" },
    { x: 602, y: 522, r: 2.8, type: "crust" },
    { x: 572, y: 552, r: 2.2, type: "pale" },
    { x: 642, y: 495, r: 3.6, type: "golden" },
    { x: 728, y: 492, r: 4.2, type: "crust" },
    { x: 742, y: 505, r: 2.4, type: "pale" },

    // Cluster drifting off lower-right of toast
    { x: 845, y: 785, r: 7.2, type: "crust" },
    { x: 862, y: 798, r: 4.4, type: "golden" },
    { x: 832, y: 812, r: 3.5, type: "pale" },
    { x: 878, y: 772, r: 2.8, type: "golden" },
    { x: 892, y: 815, r: 5.0, type: "crust" },
    { x: 775, y: 838, r: 4.6, type: "golden" },
    { x: 758, y: 852, r: 2.9, type: "pale" },

    // Near lemon peel tail
    { x: 325, y: 845, r: 3.6, type: "golden" },
    { x: 342, y: 858, r: 2.2, type: "crust" },
    { x: 488, y: 825, r: 3.9, type: "golden" }
  ];

  // Add 35 fine micro-specks along the diagonal stream
  for (let i = 0; i < 35; i++) {
    let t = random(0.15, 0.88);
    let baseX = lerp(330, 920, t) + random(-140, 140);
    let baseY = lerp(860, 460, t) + random(-140, 140);
    // Avoid landing directly inside the cup or book
    if (Math.hypot(baseX - cupF.cx, baseY - cupF.cy) < 145) continue;
    if (Math.hypot(baseX - 410, baseY - 415) < 210) continue;

    let types = ["golden", "crust", "pale", "butter_crystal"];
    crumbs.push({
      x: baseX,
      y: baseY,
      r: random(1.2, 3.4),
      type: types[Math.floor(random(types.length))]
    });
  }

  for (let c of crumbs) {
    // Build irregular angular crumb polygon
    let pts = [];
    let sides = c.r > 3.5 ? 6 : 5;
    for (let s = 0; s < sides; s++) {
      let a = (s / sides) * 360 + random(-18, 18);
      let rad = (a * Math.PI) / 180;
      let rr = c.r * random(0.65, 1.25);
      pts.push([c.x + Math.cos(rad) * rr, c.y + Math.sin(rad) * rr]);
    }

    // 1. Tiny hovering contact shadow offset beneath each crumb
    let sdx = map(c.r, 1.2, 7.5, 4.5, 9.5);
    let sdy = map(c.r, 1.2, 7.5, 6.5, 13.0);
    let sPts = pts.map(([px, py]) => [px + sdx, py + sdy]);

    brush.wash("#C2B7A6", 150);
    drawWorldPoly(sPts, 0.15);
    resetBrushState();

    if (c.r > 2.5) {
      brush.set("2H", "#9E9280", 0.45);
      brush.circle(c.x + sdx * 0.85, c.y + sdy * 0.85, c.r * 0.7, 0.2);
    }

    // 2. Crumb body plane
    let baseCol =
      c.type === "crust"
        ? "#5C3419"
        : c.type === "golden"
          ? "#C99246"
          : c.type === "pale"
            ? "#E8D2A6"
            : "#F5E69B";
    let shadeCol =
      c.type === "crust"
        ? "#2E1708"
        : c.type === "golden"
          ? "#8A561E"
          : c.type === "pale"
            ? "#B5935B"
            : "#C9A842";
    let hiCol =
      c.type === "crust"
        ? "#A86E3E"
        : c.type === "golden"
          ? "#F5DFB0"
          : "#FFFFFF";

    brush.wash(baseCol, 250);
    drawWorldPoly(pts, 0.1);
    resetBrushState();

    // 3. Lower-right facet shadow & upper-left crisp specular glint
    brush.set("rotring", shadeCol, 0.45);
    brush.line(pts[1][0], pts[1][1], pts[2][0], pts[2][1]);
    if (pts.length > 3) {
      brush.line(pts[2][0], pts[2][1], pts[3][0], pts[3][1]);
    }

    brush.set("gloss_pen", hiCol, 0.85);
    brush.line(pts[0][0], pts[0][1], pts[pts.length - 1][0], pts[pts.length - 1][1]);
  }
}

// Hyperreal Barbershop at Closing Time — p5.js 2.x + p5.brush

let CAM;
let SCONCE = { x: 0.22, y: 7.22, z: 11.48 };
let CHAIR_POS = { x: -0.28, z: 8.55, rot: -27 };

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  pixelDensity(1);
  brush.scaleBrushes(2);
  angleMode(DEGREES);
  randomSeed(7391);
  noiseSeed(7391);

  initCamera();
}

function initCamera() {
  CAM = {
    x: -1.38,
    y: 4.72,
    z: -0.65,
    lookX: 0.25,
    lookY: 3.34,
    lookZ: 12.0,
    f: 1160,
    cx: 608,
    cy: 536
  };

  let fx = CAM.lookX - CAM.x;
  let fy = CAM.lookY - CAM.y;
  let fz = CAM.lookZ - CAM.z;
  let flen = Math.hypot(fx, fy, fz);
  CAM.F = [fx / flen, fy / flen, fz / flen];

  // Right = normalize(cross(F, [0,1,0])) in right-handed view where +X is right, +Y is up, +Z is forward
  let rx = CAM.F[2];
  let ry = 0;
  let rz = -CAM.F[0];
  let rlen = Math.hypot(rx, ry, rz);
  CAM.R = [rx / rlen, ry / rlen, rz / rlen];

  // Up = cross(R, F) -> in this convention:
  // Ux = R.y*F.z - R.z*F.y, Uy = R.z*F.x - R.x*F.z, Uz = R.x*F.y - R.y*F.x
  // Flip sign so +Y world maps to +yc camera up
  CAM.U = [
    -(CAM.R[1] * CAM.F[2] - CAM.R[2] * CAM.F[1]),
    -(CAM.R[2] * CAM.F[0] - CAM.R[0] * CAM.F[2]),
    -(CAM.R[0] * CAM.F[1] - CAM.R[1] * CAM.F[0])
  ];

  // Apply subtle -1.1 deg off-axis camera roll for cinematic doorway framing
  let rollRad = (-1.1 * Math.PI) / 180;
  let cr = Math.cos(rollRad);
  let sr = Math.sin(rollRad);
  let R0 = [...CAM.R];
  let U0 = [...CAM.U];
  for (let i = 0; i < 3; i++) {
    CAM.R[i] = R0[i] * cr + U0[i] * sr;
    CAM.U[i] = -R0[i] * sr + U0[i] * cr;
  }
}

function proj(x, y, z) {
  let dx = x - CAM.x;
  let dy = y - CAM.y;
  let dz = z - CAM.z;
  let zc = dx * CAM.F[0] + dy * CAM.F[1] + dz * CAM.F[2];
  if (zc < 0.2) zc = 0.2;
  let xc = dx * CAM.R[0] + dy * CAM.R[1] + dz * CAM.R[2];
  let yc = dx * CAM.U[0] + dy * CAM.U[1] + dz * CAM.U[2];
  return [CAM.cx + CAM.f * (xc / zc), CAM.cy - CAM.f * (yc / zc)];
}

function chairTransform(lx, ly, lz) {
  let rad = (CHAIR_POS.rot * Math.PI) / 180;
  let c = Math.cos(rad);
  let s = Math.sin(rad);
  return [
    CHAIR_POS.x + lx * c - lz * s,
    ly,
    CHAIR_POS.z + lx * s + lz * c
  ];
}

function projChair(lx, ly, lz) {
  let w = chairTransform(lx, ly, lz);
  return proj(w[0], w[1], w[2]);
}

function resetBrush() {
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.noField();
}

function drawShape(pts, curvature = 0, closed = true) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closed);
}

function interpPt(a, b, t) {
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t];
}

function interp3D(a, b, t) {
  return [
    a[0] + (b[0] - a[0]) * t,
    a[1] + (b[1] - a[1]) * t,
    a[2] + (b[2] - a[2]) * t
  ];
}

// Compute tungsten light intensity at world coordinate (x,y,z)
function getLightAt(x, y, z) {
  let dx = x - SCONCE.x;
  let dy = y - SCONCE.y;
  let dz = z - SCONCE.z;
  let d2 = dx * dx + dy * dy + dz * dz;
  let d = Math.sqrt(d2);

  // Fast inverse-power falloff into deep umber corners
  let base = 1.0 / (1.0 + 0.055 * d2 + 0.0022 * d2 * d2);

  // Downward & forward cone bias from wall sconce
  let cone = 1.0;
  if (dy > 0.4) cone *= Math.max(0.35, 1.0 - (dy - 0.4) * 0.28);

  // Secondary warm bounce from mirror and wall around chair
  let bdx = x - 0.15;
  let bdy = y - 3.6;
  let bdz = z - 10.2;
  let bd2 = bdx * bdx + bdy * bdy + bdz * bdz;
  let bounce = 0.34 / (1.0 + 0.08 * bd2);

  // Shadow occlusion from barber chair onto floor
  let shadowMult = 1.0;
  if (y < 0.5) {
    let cdx = x - (CHAIR_POS.x - 0.18);
    let cdz = z - (CHAIR_POS.z - 0.35);
    let cdist = Math.hypot(cdx * 0.85, cdz * 0.95);
    if (cdist < 1.95) {
      let sFactor = Math.max(0, 1.0 - cdist / 1.95);
      shadowMult *= 1.0 - 0.68 * Math.pow(sFactor, 1.3);
    }
    // Under-counter shadow near back wall
    if (z > 10.6 && x > -3.1 && x < 3.6) {
      let uFactor = Math.min(1.0, (z - 10.6) / 1.1);
      shadowMult *= 1.0 - 0.55 * uFactor;
    }
  }

  return Math.min(1.0, (base * cone + bounce) * shadowMult);
}

function draw() {
  translate(-width / 2, -height / 2);

  // Warm raw-sienna/buff paper ground so watercolor washes glow without artificial white bloom
  background("#c7a26b");

  // 1. Base atmospheric washes & wall architecture
  drawWallsAndWashes();

  // 2. Chequered linoleum floor in perspective + watercolor light pool + charcoal corner shadows
  drawChequeredFloor();

  // 3. Wainscoting, baseboards, right-wall details & back-wall molding
  drawWainscotingAndWalls();

  // 4. Multiplied mirrors & nested infinity reflections of the room behind
  drawMultipliedMirrors();

  // 5. Barber station cabinet, marble countertop, blue Barbicide jar with combs & tools
  drawBarberCounterAndBarbicide();

  // 6. Bare-bulb tungsten wall sconce (warm without glowing)
  drawWallSconce();

  // 7. Cracked oxblood leather barber chair & chrome footrests
  drawBarberChair();

  // 8. Hair clippings on the chequered linoleum sharpened with pencil
  drawHairClippings();

  // 9. Off-axis doorway frame in deep charcoal mass & umber shadow
  drawDoorwayFrame();

  // 10. Final hyperreal pencil sharpening & atmospheric unification
  drawFinalPencilAccents();

  noLoop();
}

// ============================================================================
// 1. WALLS, CEILING & LAYERED WATERCOLOR WASHES / CHARCOAL MASS SHADOWS
// ============================================================================
function drawWallsAndWashes() {
  resetBrush();

  // Base warm ochre/raw-sienna wash across entire canvas
  brush.wash("#b88d52", 95);
  drawShape([[0, 0], [1200, 0], [1200, 1200], [0, 1200]]);
  resetBrush();

  // Layered watercolor washes for the tungsten lit zone on the back wall
  let sx = SCONCE.x;
  let sy = SCONCE.y;
  let sz = 11.98;

  // Radial organic polygons on the back wall (z = 11.98) around the sconce
  let radii = [
    { rx: 5.8, ry: 4.8, col: "#4a2c15", op: 115, bleed: 0.35 }, // Outer raw umber
    { rx: 4.6, ry: 3.9, col: "#6e3416", op: 105, bleed: 0.32 }, // Deep burnt sienna
    { rx: 3.5, ry: 3.0, col: "#8f3b16", op: 110, bleed: 0.28 }, // Rich burnt sienna
    { rx: 2.5, ry: 2.2, col: "#b85219", op: 105, bleed: 0.25 }, // Burnt sienna / cadmium orange
    { rx: 1.65, ry: 1.45, col: "#d66e1c", op: 110, bleed: 0.22 }, // Cadmium orange
    { rx: 0.95, ry: 0.85, col: "#e38c2b", op: 95, bleed: 0.18 }   // Heavy amber tungsten core
  ];

  for (let r = 0; r < radii.length; r++) {
    let info = radii[r];
    let pts = [];
    let steps = 20;
    for (let i = 0; i < steps; i++) {
      let ang = (i / steps) * 360;
      let wob = 1.0 + 0.08 * sin(ang * 3 + r * 37);
      let wx = sx + cos(ang) * info.rx * wob;
      let wy = sy - 0.45 + sin(ang) * info.ry * wob;
      wx = constrain(wx, -5.2, 5.4);
      wy = constrain(wy, 0.2, 9.2);
      pts.push(proj(wx, wy, sz));
    }
    brush.fill(info.col, info.op);
    brush.fillBleed(info.bleed, "out");
    brush.fillTexture(0.65, 0.4);
    drawShape(pts, 0.25);
  }
  resetBrush();

  // Right wall plane (x = 5.2, z = 1.5 to 12.0, y = 0 to 9.2)
  let rwQuad1 = [
    proj(5.2, 9.2, 12.0),
    proj(5.2, 9.2, 2.0),
    proj(5.2, 0.0, 2.0),
    proj(5.2, 0.0, 12.0)
  ];
  brush.fill("#362010", 155);
  brush.fillBleed(0.22, "in");
  brush.fillTexture(0.6, 0.45);
  drawShape(rwQuad1, 0);

  // Far-right wall deep falloff wash
  let rwShadow = [
    proj(5.2, 9.2, 8.5),
    proj(5.2, 9.2, 1.8),
    proj(5.2, 0.0, 1.8),
    proj(5.2, 0.0, 7.5)
  ];
  brush.fill("#1e1209", 180);
  brush.fillBleed(0.25, "in");
  drawShape(rwShadow, 0);

  // Left wall behind doorway (x = -4.6, z = 4.5 to 12.0)
  let lwShadow = [
    proj(-4.6, 9.2, 12.0),
    proj(-3.0, 9.2, 12.0),
    proj(-3.2, 0.0, 12.0),
    proj(-4.6, 0.0, 12.0)
  ];
  brush.fill("#2b190d", 165);
  brush.fillBleed(0.25, "out");
  drawShape(lwShadow, 0);

  // Ceiling plane above (y = 8.55, z = 3.0 to 12.0)
  let ceilQuad = [
    proj(-4.8, 8.55, 12.0),
    proj(5.2, 8.55, 12.0),
    proj(5.2, 8.55, 3.0),
    proj(-4.8, 8.55, 3.0)
  ];
  brush.fill("#26170c", 175);
  brush.fillBleed(0.2, "in");
  drawShape(ceilQuad, 0);
  resetBrush();

  // Warm burnt sienna / cadmium orange ceiling bounce right above the sconce
  let ceilGlow = [
    proj(-1.2, 8.55, 12.0),
    proj(1.8, 8.55, 12.0),
    proj(1.4, 8.55, 9.6),
    proj(-0.9, 8.55, 9.6)
  ];
  brush.fill("#8f3d16", 110);
  brush.fillBleed(0.3, "out");
  drawShape(ceilGlow, 0.2);
  resetBrush();

  // CHARCOAL MASS for the deep umber corners of the room
  let cornerMasses = [
    // Top-left back corner
    [proj(-4.8, 8.8, 12.0), proj(-1.8, 8.8, 12.0), proj(-2.7, 5.2, 12.0), proj(-4.8, 3.0, 12.0)],
    // Top-right back & side corner
    [proj(2.4, 8.8, 12.0), proj(5.2, 8.8, 12.0), proj(5.2, 8.8, 4.5), proj(5.2, 3.8, 6.0), proj(3.3, 5.5, 12.0)],
    // Lower-right wall deep corner
    [proj(5.2, 5.2, 7.5), proj(5.2, 5.2, 2.0), proj(5.2, 0.0, 2.0), proj(5.2, 0.0, 8.5)]
  ];

  for (let i = 0; i < cornerMasses.length; i++) {
    brush.mass("charcoal", "#1a1009", {
      precision: 0.65,
      strength: 0.75,
      gradient: 0.45,
      outline: false
    });
    drawShape(cornerMasses[i], 0.05);
  }
  resetBrush();

  // Plaster wall fine vertical & diagonal cross-hatching and hairline cracks
  brush.hatchStyle("2H", "#3b2312", 0.55);
  brush.hatch(9, 88, { rand: 0.08, gradient: 0.4 });
  drawShape([
    proj(-4.2, 8.5, 12.0),
    proj(5.0, 8.5, 12.0),
    proj(5.0, 3.0, 12.0),
    proj(-4.2, 3.0, 12.0)
  ]);
  resetBrush();

  // Subtle plaster cracks & vintage wallpaper seam lines on upper wall
  brush.set("2H", "#331e0f", 0.5);
  for (let xw = -3.2; xw <= 4.2; xw += 1.25) {
    let p1 = proj(xw, 8.52, 12.0);
    let p2 = proj(xw, 3.05, 12.0);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
  // Hairline crack near top left of mirror
  let crk1 = [
    proj(-1.85, 6.62, 12.0),
    proj(-1.95, 7.05, 12.0),
    proj(-1.78, 7.45, 12.0),
    proj(-2.05, 7.92, 12.0)
  ];
  brush.set("2H", "#29170b", 0.6);
  brush.spline(crk1, 0.3);
  resetBrush();
}

// ============================================================================
// 2. CHEQUERED LINOLEUM FLOOR IN PERSPECTIVE
// ============================================================================
function drawChequeredFloor() {
  resetBrush();

  // Base raw umber wash over entire floor plane (y = 0, z = 3.2 to 12.0)
  let floorBase = [
    proj(-4.8, 0, 12.0),
    proj(5.2, 0, 12.0),
    proj(5.2, 0, 3.2),
    proj(-4.8, 0, 3.2)
  ];
  brush.fill("#593a1d", 140);
  brush.fillBleed(0.2, "in");
  brush.fillTexture(0.6, 0.35);
  drawShape(floorBase, 0);
  resetBrush();

  // Layered watercolor washes for the warm tungsten light pool on the floor around the chair
  let floorPools = [
    { cx: 0.1, cz: 8.6, rx: 3.8, rz: 3.1, col: "#783214", op: 105, bleed: 0.3 },  // Burnt sienna outer
    { cx: 0.2, cz: 8.5, rx: 2.9, rz: 2.4, col: "#a84618", op: 100, bleed: 0.25 }, // Burnt sienna / cadmium
    { cx: 0.3, cz: 8.3, rx: 2.0, rz: 1.7, col: "#d16a1d", op: 95, bleed: 0.22 },  // Cadmium orange lit zone
    { cx: 0.45, cz: 8.0, rx: 1.25, rz: 1.1, col: "#e08b2c", op: 85, bleed: 0.18 } // Warm amber core
  ];

  for (let p of floorPools) {
    let pts = [];
    for (let i = 0; i < 18; i++) {
      let a = (i / 18) * 360;
      let wx = constrain(p.cx + cos(a) * p.rx, -4.6, 5.0);
      let wz = constrain(p.cz + sin(a) * p.rz, 3.5, 11.9);
      pts.push(proj(wx, 0, wz));
    }
    brush.fill(p.col, p.op);
    brush.fillBleed(p.bleed, "out");
    brush.fillTexture(0.55, 0.3);
    drawShape(pts, 0.25);
  }
  resetBrush();

  // Chequered linoleum grid: tile size = 0.78 units
  let tileSize = 0.78;
  let ixMin = -6;
  let ixMax = 7;
  let izMin = 5;
  let izMax = 15;

  // Batch tiles by tonal group for fast, lush watercolor/wash rendering
  let darkTilesLit = [];
  let darkTilesMid = [];
  let darkTilesShadow = [];
  let lightTilesShadow = [];
  let lightTilesLit = [];
  let allTileQuads = [];

  for (let iz = izMin; iz < izMax; iz++) {
    for (let ix = ixMin; ix < ixMax; ix++) {
      let x0 = ix * tileSize;
      let x1 = (ix + 1) * tileSize;
      let z0 = iz * tileSize;
      let z1 = (iz + 1) * tileSize;
      if (z1 > 12.0) z1 = 12.0;
      if (x1 > 5.2) x1 = 5.2;
      if (x0 < -4.8) x0 = -4.8;
      if (x1 <= x0 || z1 <= z0) continue;

      let xm = (x0 + x1) * 0.5;
      let zm = (z0 + z1) * 0.5;
      let quad = [
        proj(x0, 0, z0),
        proj(x1, 0, z0),
        proj(x1, 0, z1),
        proj(x0, 0, z1)
      ];

      let lum = getLightAt(xm, 0.05, zm);
      let isDark = ((ix + iz) & 1) === 0;
      allTileQuads.push({ quad, xm, zm, lum, isDark, x0, x1, z0, z1 });

      if (isDark) {
        if (lum > 0.34) darkTilesLit.push(quad);
        else if (lum > 0.18) darkTilesMid.push(quad);
        else darkTilesShadow.push(quad);
      } else {
        if (lum < 0.24) lightTilesShadow.push(quad);
        else if (lum > 0.38) lightTilesLit.push(quad);
      }
    }
  }

  // Render light tiles in shadow (muted raw umber wash)
  brush.wash("#5c3d20", 110);
  for (let q of lightTilesShadow) drawShape(q, 0);
  resetBrush();

  // Render light tiles in warm tungsten light (cadmium/ochre glaze)
  brush.wash("#d99a48", 75);
  for (let q of lightTilesLit) drawShape(q, 0);
  resetBrush();

  // Render dark tiles in lit zone (warm burnt-umber / sienna-slate)
  brush.fill("#3d2414", 185);
  brush.fillBleed(0.06, "in");
  brush.fillTexture(0.5, 0.4);
  for (let q of darkTilesLit) drawShape(q, 0);
  resetBrush();

  // Render dark tiles in mid zone (deep raw umber)
  brush.fill("#29180d", 205);
  brush.fillBleed(0.06, "in");
  brush.fillTexture(0.5, 0.4);
  for (let q of darkTilesMid) drawShape(q, 0);
  resetBrush();

  // Render dark tiles in shadow zone (near-black bistre/charcoal)
  brush.wash("#1a0f08", 225);
  for (let q of darkTilesShadow) drawShape(q, 0);
  resetBrush();

  // Cast shadow of the barber chair & footrest across the chequered linoleum
  let chairShadowPts = [];
  for (let i = 0; i < 20; i++) {
    let a = (i / 20) * 360;
    let sx = CHAIR_POS.x - 0.25 + cos(a) * 1.48;
    let sz = CHAIR_POS.z - 0.32 + sin(a) * 1.32;
    chairShadowPts.push(proj(sx, 0.01, sz));
  }
  brush.fill("#1c1008", 155);
  brush.fillBleed(0.18, "out");
  brush.fillTexture(0.6, 0.3);
  drawShape(chairShadowPts, 0.25);
  resetBrush();

  // Footrest cast shadow on floor
  let footShadowPts = [
    projChair(-0.55, 0.01, -0.8),
    projChair(0.55, 0.01, -0.8),
    projChair(0.62, 0.01, -2.05),
    projChair(-0.62, 0.01, -2.05)
  ];
  brush.fill("#170d06", 165);
  brush.fillBleed(0.14, "out");
  drawShape(footShadowPts, 0.15);
  resetBrush();

  // Charcoal mass in the deep foreground & back floor corners
  let floorCornerMasses = [
    [proj(-4.8, 0, 12.0), proj(-2.3, 0, 12.0), proj(-3.1, 0, 8.2), proj(-4.8, 0, 7.5)],
    [proj(3.2, 0, 12.0), proj(5.2, 0, 12.0), proj(5.2, 0, 6.2), proj(3.4, 0, 8.5)],
    [proj(2.2, 0, 6.5), proj(5.2, 0, 6.5), proj(5.2, 0, 3.5), proj(1.8, 0, 3.5)],
    [proj(-4.8, 0, 7.5), proj(-1.9, 0, 6.8), proj(-1.8, 0, 3.5), proj(-4.8, 0, 3.5)]
  ];
  for (let m of floorCornerMasses) {
    brush.mass("charcoal", "#160d07", {
      precision: 0.6,
      strength: 0.8,
      gradient: 0.45,
      outline: false
    });
    drawShape(m, 0.05);
  }
  resetBrush();

  // Pencil sharpening of linoleum tile seams, wear marks, and tungsten sheen
  brush.set("2H", "#24150b", 0.55);
  for (let iz = izMin; iz <= izMax; iz++) {
    let z = Math.min(12.0, iz * tileSize);
    let p1 = proj(-4.6, 0, z);
    let p2 = proj(5.2, 0, z);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
  for (let ix = ixMin; ix <= ixMax; ix++) {
    let x = constrain(ix * tileSize, -4.6, 5.2);
    let p1 = proj(x, 0, 3.9);
    let p2 = proj(x, 0, 12.0);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Worn linoleum marbling, scuff arcs around chair & warm specular edge highlights
  for (let t of allTileQuads) {
    if (t.zm < 4.5 || t.zm > 11.8) continue;
    // Subtle tile corner bevel highlight on lit tiles
    if (t.lum > 0.32 && random() < 0.75) {
      brush.set("cpencil", t.isDark ? "#704826" : "#ebd5a7", 0.45);
      let a = interpPt(t.quad[0], t.quad[1], 0.12);
      let b = interpPt(t.quad[0], t.quad[1], 0.88);
      brush.line(a[0], a[1], b[0], b[1]);
    }
    // Linoleum mottled veins in pencil
    if (random() < 0.55) {
      brush.set("2H", t.isDark ? "#140b06" : "#78532b", 0.4);
      let s1 = interpPt(t.quad[0], t.quad[3], random(0.2, 0.8));
      let s2 = interpPt(t.quad[1], t.quad[2], random(0.2, 0.8));
      let sm = [(s1[0] + s2[0]) * 0.5 + random(-6, 6), (s1[1] + s2[1]) * 0.5 + random(-2, 2)];
      brush.spline([s1, sm, s2], 0.4);
    }
  }

  // Circular scuff tracks worn into the linoleum around the barber chair
  for (let i = 0; i < 28; i++) {
    let a1 = random(-160, 160);
    let a2 = a1 + random(14, 34);
    let rad = random(1.35, 2.25);
    let pts = [];
    for (let k = 0; k <= 4; k++) {
      let a = a1 + ((a2 - a1) * k) / 4;
      let sx = CHAIR_POS.x + cos(a) * rad;
      let sz = CHAIR_POS.z + sin(a) * rad;
      if (sz > 4.6 && sz < 11.4 && sx > -3.8 && sx < 4.5) {
        pts.push(proj(sx, 0.01, sz));
      }
    }
    if (pts.length >= 3) {
      brush.set("HB", random() < 0.5 ? "#382212" : "#9c7240", 0.4);
      brush.spline(pts, 0.4);
    }
  }
  resetBrush();
}

// ============================================================================
// 3. WAINSCOTING, MOLDINGS & WALL FIXTURES
// ============================================================================
function drawWainscotingAndWalls() {
  resetBrush();

  // Back wall wood wainscoting (y = 0 to 2.95, z = 11.96)
  let backWainscot = [
    proj(-4.6, 2.95, 11.96),
    proj(5.2, 2.95, 11.96),
    proj(5.2, 0.0, 11.96),
    proj(-4.6, 0.0, 11.96)
  ];
  brush.fill("#2b170b", 210);
  brush.fillBleed(0.08, "in");
  brush.fillTexture(0.6, 0.5);
  drawShape(backWainscot, 0);

  // Right wall wood wainscoting (x = 5.18, y = 0 to 2.95, z = 2.5 to 12.0)
  let rightWainscot = [
    proj(5.18, 2.95, 12.0),
    proj(5.18, 2.95, 2.5),
    proj(5.18, 0.0, 2.5),
    proj(5.18, 0.0, 12.0)
  ];
  brush.fill("#211108", 225);
  brush.fillBleed(0.08, "in");
  drawShape(rightWainscot, 0);
  resetBrush();

  // Recessed panels on right wall wainscoting
  for (let z0 = 3.2; z0 < 11.2; z0 += 1.35) {
    let z1 = z0 + 1.05;
    let pQuad = [
      proj(5.16, 2.55, z1),
      proj(5.16, 2.55, z0),
      proj(5.16, 0.55, z0),
      proj(5.16, 0.55, z1)
    ];
    brush.wash("#140a05", 190);
    drawShape(pQuad, 0);
    resetBrush();

    brush.set("2H", "#452915", 0.55);
    drawShape(pQuad, 0, true);
  }

  // Chair rail molding along right wall & back wall
  brush.set("HB", "#5e3619", 0.9);
  let crBack1 = proj(-4.6, 2.98, 11.95);
  let crBack2 = proj(5.18, 2.98, 11.95);
