  brush.line(crBack1[0], crBack1[1], crBack2[0], crBack2[1]);
  brush.line(crBack2[0], crBack2[1], crRight[0], crRight[1]);

  // Warm burnt-sienna highlight along top edge of chair rail near the light
  brush.set("cpencil", "#b56526", 0.65);
  let crLit1 = proj(-3.2, 3.01, 11.95);
  let crLit2 = proj(4.2, 3.01, 11.95);
  brush.line(crLit1[0], crLit1[1], crLit2[0], crLit2[1]);

  // Crown molding at ceiling (y = 8.48)
  brush.set("2B", "#1a0e07", 1.2);
  let cm1 = proj(-4.6, 8.48, 11.95);
  let cm2 = proj(5.18, 8.48, 11.95);
  let cm3 = proj(5.18, 8.48, 2.8);
  brush.line(cm1[0], cm1[1], cm2[0], cm2[1]);
  brush.line(cm2[0], cm2[1], cm3[0], cm3[1]);

  // Vintage framed hair-tonic lithograph / price list on the right wall in deep umber shadow
  let picOuter = [
    proj(5.15, 6.25, 8.8),
    proj(5.15, 6.25, 6.9),
    proj(5.15, 4.15, 6.9),
    proj(5.15, 4.15, 8.8)
  ];
  let picInner = [
    proj(5.15, 6.02, 8.62),
    proj(5.15, 6.02, 7.08),
    proj(5.15, 4.38, 7.08),
    proj(5.15, 4.38, 8.62)
  ];
  brush.wash("#1a0e07", 220);
  drawShape(picOuter, 0);
  brush.wash("#4f351e", 170);
  drawShape(picInner, 0);
  resetBrush();

  brush.set("2H", "#120904", 0.7);
  drawShape(picOuter, 0, true);
  brush.set("2H", "#78512d", 0.5);
  drawShape(picInner, 0, true);

  // Faint typography lines on the framed barbershop price card
  for (let py = 5.65; py >= 4.65; py -= 0.22) {
    let l1 = proj(5.14, py, 8.38);
    let l2 = proj(5.14, py, 7.32);
    brush.set("2H", "#2b1a0e", 0.45);
    brush.line(l1[0], l1[1], l2[0], l2[1]);
  }
  resetBrush();
}

// ============================================================================
// 4. MULTIPLIED MIRRORS & INFINITY REFLECTIONS OF THE ROOM BEHIND
// ============================================================================
function drawMultipliedMirrors() {
  resetBrush();

  // Main mirror coordinates on back wall (z = 11.90)
  // Outer carved mahogany frame: x = -2.35 to 2.85, y = 2.95 to 6.82
  // Glass aperture: x = -1.98 to 2.48, y = 3.18 to 6.48
  let mx0 = -1.98, mx1 = 2.48;
  let my0 = 3.18, my1 = 6.48;
  let mz = 11.90;

  let glassQuad = [
    proj(mx0, my1, mz),
    proj(mx1, my1, mz),
    proj(mx1, my0, mz),
    proj(mx0, my0, mz)
  ];

  // 1. Base smoky warm-umber silvered mirror glass ground
  brush.fill("#362212", 215);
  brush.fillBleed(0.06, "in");
  brush.fillTexture(0.55, 0.35);
  drawShape(glassQuad, 0);
  resetBrush();

  // Helper to project a virtual 3D point inside the mirror reflection, clamped to the mirror glass aperture
  function projRefl(vx, vy, vz) {
    // Intersect ray from CAM to (vx, vy, vz) with mirror plane z = mz
    let t = (mz - CAM.z) / (vz - CAM.z);
    let ix = CAM.x + (vx - CAM.x) * t;
    let iy = CAM.y + (vy - CAM.y) * t;
    ix = constrain(ix, mx0 + 0.03, mx1 - 0.03);
    iy = constrain(iy, my0 + 0.03, my1 - 0.03);
    return proj(ix, iy, mz);
  }

  // 2. Reflected Room Level 1 (Virtual z = 12.0 to 23.6 — the opposite wall behind the viewer)
  // Warm tungsten wall & ceiling glow reflected in upper mirror
  let reflGlow1 = [
    projRefl(-1.9, 6.4, 15.0),
    projRefl(2.4, 6.4, 15.0),
    projRefl(2.2, 4.1, 21.0),
    projRefl(-1.7, 4.1, 21.0)
  ];
  brush.fill("#7a3415", 130);
  brush.fillBleed(0.18, "in");
  drawShape(reflGlow1, 0.1);
  resetBrush();

  // Reflected chequered floor visible in the lower portion of the mirror
  for (let vz = 13.5; vz < 22.5; vz += 1.1) {
    for (let vx = -2.2; vx < 2.6; vx += 0.9) {
      let isDark = ((Math.floor(vx + 5) + Math.floor(vz)) & 1) === 0;
      let q = [
        projRefl(vx, 0.0, vz),
        projRefl(vx + 0.85, 0.0, vz),
        projRefl(vx + 0.85, 0.0, vz + 1.0),
        projRefl(vx, 0.0, vz + 1.0)
      ];
      brush.wash(isDark ? "#1f1209" : "#6e4924", 125);
      drawShape(q, 0);
    }
  }
  resetBrush();

  // Opposite wall wainscoting in reflection (at virtual z = 23.2)
  let oppWallLow = [
    projRefl(-3.5, 3.2, 23.2),
    projRefl(4.0, 3.2, 23.2),
    projRefl(4.0, 0.0, 23.2),
    projRefl(-3.5, 0.0, 23.2)
  ];
  brush.wash("#1c1008", 195);
  drawShape(oppWallLow, 0);
  resetBrush();

  // 3. MULTIPLIED MIRROR CORRIDOR (Levels 1, 2, 3, 4 receding into the mirror!)
  // Each bounce adds ~11.4 units of virtual z and gets slightly darker and more olive-amber
  let mirrorBounces = [
    {
      vz: 23.2,
      fx0: -1.95, fx1: 2.45, fy0: 3.05, fy1: 6.65,
      gx0: -1.65, gx1: 2.15, gy0: 3.28, gy1: 6.32,
      frameCol: "#211209", glassCol: "#3d2614", sconceY: 7.15, glowCol: "#b5531a"
    },
    {
      vz: 34.6,
      fx0: -1.85, fx1: 2.35, fy0: 3.10, fy1: 6.55,
      gx0: -1.55, gx1: 2.05, gy0: 3.32, gy1: 6.22,
      frameCol: "#1a0e07", glassCol: "#2e1c0f", sconceY: 7.12, glowCol: "#994216"
    },
    {
      vz: 46.0,
      fx0: -1.75, fx1: 2.25, fy0: 3.15, fy1: 6.45,
      gx0: -1.45, gx1: 1.95, gy0: 3.35, gy1: 6.15,
      frameCol: "#140b05", glassCol: "#24150b", sconceY: 7.10, glowCol: "#7d3312"
    },
    {
      vz: 57.4,
      fx0: -1.65, fx1: 2.15, fy0: 3.20, fy1: 6.35,
      gx0: -1.35, gx1: 1.85, gy0: 3.40, gy1: 6.05,
      frameCol: "#0f0804", glassCol: "#1a0f08", sconceY: 7.05, glowCol: "#5e250e"
    }
  ];

  for (let b = 0; b < mirrorBounces.length; b++) {
    let mb = mirrorBounces[b];

    // Warm sconce halo in this reflected level
    let haloPts = [];
    for (let i = 0; i < 12; i++) {
      let a = (i / 12) * 360;
      haloPts.push(projRefl(0.22 + cos(a) * 1.45, mb.sconceY - 0.55 + sin(a) * 1.15, mb.vz - 0.2));
    }
    brush.fill(mb.glowCol, 95 - b * 15);
    brush.fillBleed(0.18, "out");
    drawShape(haloPts, 0.2);
    resetBrush();

    // Reflected wooden mirror frame at virtual depth mb.vz
    let fQuad = [
      projRefl(mb.fx0, mb.fy1, mb.vz),
      projRefl(mb.fx1, mb.fy1, mb.vz),
      projRefl(mb.fx1, mb.fy0, mb.vz),
      projRefl(mb.fx0, mb.fy0, mb.vz)
    ];
    brush.wash(mb.frameCol, 225);
    drawShape(fQuad, 0);

    // Reflected inner mirror glass at virtual depth mb.vz
    let gQuad = [
      projRefl(mb.gx0, mb.gy1, mb.vz),
      projRefl(mb.gx1, mb.gy1, mb.vz),
      projRefl(mb.gx1, mb.gy0, mb.vz),
      projRefl(mb.gx0, mb.gy0, mb.vz)
    ];
    brush.wash(mb.glassCol, 210);
    drawShape(gQuad, 0);
    resetBrush();

    // Crisp pencil outlines & warm brass inner trim of the multiplied mirror frames
    brush.set("2H", "#120904", 0.65 - b * 0.1);
    drawShape(fQuad, 0, true);
    brush.set("cpencil", "#9c5823", 0.5 - b * 0.08);
    drawShape(gQuad, 0, true);

    // Reflected bare sconce bulb at this bounce depth!
    let bulbPt = projRefl(0.22, mb.sconceY - 0.35, mb.vz - 0.35);
    let rBulb = Math.max(2.5, 9 - b * 2.1);
    brush.wash("#d98b2b", 190 - b * 20);
    brush.circle(bulbPt[0], bulbPt[1], rBulb, 0.1);
    resetBrush();
    brush.set("cpencil", "#f2c66d", 0.55);
    brush.circle(bulbPt[0], bulbPt[1], rBulb * 0.55, 0.05);
    resetBrush();

    // Reflected silhouette of the oxblood chair back in each nested mirror
    let cBackQuad = [
      projRefl(-0.75, 4.15, mb.vz - 3.2),
      projRefl(0.25, 4.15, mb.vz - 3.2),
      projRefl(0.35, 2.55, mb.vz - 3.2),
      projRefl(-0.85, 2.55, mb.vz - 3.2)
    ];
    brush.wash(b === 0 ? "#3b110d" : "#240a08", 185);
    drawShape(cBackQuad, 0.1);
    resetBrush();
  }

  // Reflected vintage wall clock (with reversed dial) & coat rack on the opposite wall (vz = 23.0)
  let clockCenter = projRefl(-2.55, 5.55, 22.8);
  brush.wash("#241309", 215);
  brush.circle(clockCenter[0], clockCenter[1], 19, 0.08);
  brush.wash("#9e7948", 180);
  brush.circle(clockCenter[0], clockCenter[1], 14, 0.06);
  resetBrush();
  brush.set("2H", "#1a0e07", 0.55);
  brush.circle(clockCenter[0], clockCenter[1], 14, 0.05);
  brush.line(clockCenter[0], clockCenter[1], clockCenter[0] - 5, clockCenter[1] - 7);
  brush.line(clockCenter[0], clockCenter[1], clockCenter[0] + 7, clockCenter[1] + 2);
  resetBrush();

  // Immediate reflection of the back of the oxblood chair headrest/shoulders (vz = 2*11.9 - 8.55 = 15.25)
  let reflChairBack = [
    projRefl(-0.92, 3.85, 15.3),
    projRefl(0.42, 3.85, 15.3),
    projRefl(0.55, 3.19, 15.3),
    projRefl(-1.05, 3.19, 15.3)
  ];
  brush.fill("#330e0b", 210);
  brush.fillBleed(0.06, "in");
  drawShape(reflChairBack, 0.12);
  resetBrush();

  let reflHeadrest = [
    projRefl(-0.55, 4.35, 15.4),
    projRefl(0.08, 4.35, 15.4),
    projRefl(0.12, 3.82, 15.4),
    projRefl(-0.58, 3.82, 15.4)
  ];
  brush.fill("#45120e", 215);
  brush.fillBleed(0.05, "in");
  drawShape(reflHeadrest, 0.12);
  resetBrush();

  // Chrome headrest bar reflected in mirror
  brush.set("HB", "#b89058", 0.8);
  let rBar1 = projRefl(-0.23, 3.85, 15.35);
  let rBar2 = projRefl(-0.23, 3.22, 15.35);
  brush.line(rBar1[0], rBar1[1], rBar2[0], rBar2[1]);

  // Immediate reflection of the Blue Barbicide Jar in the lower right of the mirror (vz = 12.75)
  let reflJar = [
    projRefl(1.22, 3.82, 12.75),
    projRefl(1.86, 3.82, 12.75),
    projRefl(1.86, 3.19, 12.75),
    projRefl(1.22, 3.19, 12.75)
  ];
  brush.fill("#144d75", 165);
  brush.fillBleed(0.08, "in");
  drawShape(reflJar, 0.05);
  resetBrush();

  // Mirror glass bevel lines & diagonal silvering streaks in fine 2H pencil
  let bev0 = -1.86, bev1 = 2.36, bevy0 = 3.28, bevy1 = 6.38;
  let bevelQuad = [
    proj(bev0, bevy1, mz),
    proj(bev1, bevy1, mz),
    proj(bev1, bevy0, mz),
    proj(bev0, bevy0, mz)
  ];
  brush.set("2H", "#8f6838", 0.5);
  drawShape(bevelQuad, 0, true);
  // Miter lines at bevel corners
  for (let c = 0; c < 4; c++) {
    brush.line(glassQuad[c][0], glassQuad[c][1], bevelQuad[c][0], bevelQuad[c][1]);
  }

  // Faint diagonal glass sheen lines & aged silvering speckles near mirror bottom edge
  brush.set("cpencil", "#c79752", 0.38);
  for (let i = 0; i < 9; i++) {
    let sx = random(-1.6, 2.0);
    let sy = random(3.8, 6.1);
    let p1 = proj(sx, sy, mz);
    let p2 = proj(sx + 0.32, sy + 0.48, mz);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
  brush.set("2B", "#140b05", 0.55);
  for (let i = 0; i < 45; i++) {
    let fx = random(mx0 + 0.05, mx1 - 0.05);
    let fy = my0 + Math.pow(random(), 2.5) * 0.45;
    let fp = proj(fx, fy, mz);
    brush.line(fp[0], fp[1], fp[0] + random(-2, 2), fp[1] + random(-2, 2));
  }
  resetBrush();

  // 4. CARVED ARCHITECTURAL WOOD MIRROR FRAME (Surrounding the glass)
  let fx0 = -2.36, fx1 = 2.86, fy0 = 2.95, fy1 = 6.82, fz = 11.82;
  let framePieces = [
    // Top entablature / pediment bar
    [proj(fx0 - 0.08, fy1, fz), proj(fx1 + 0.08, fy1, fz), proj(fx1, my1, fz), proj(mx0, my1, fz)],
    // Bottom frame rail
    [proj(fx0, my0, fz), proj(fx1, my0, fz), proj(fx1, fy0, fz), proj(fx0, fy0, fz)],
    // Left pilaster column
    [proj(fx0, fy1, fz), proj(mx0, fy1, fz), proj(mx0, fy0, fz), proj(fx0, fy0, fz)],
    // Right pilaster column
    [proj(mx1, fy1, fz), proj(fx1, fy1, fz), proj(fx1, fy0, fz), proj(mx1, fy0, fz)]
  ];

  for (let fp of framePieces) {
    brush.fill("#2b150a", 230);
    brush.fillBleed(0.04, "in");
    brush.fillTexture(0.6, 0.5);
    drawShape(fp, 0);
  }
  resetBrush();

  // Warm burnt sienna / amber highlight on the top cornice directly under the sconce
  let corniceTop = [
    proj(fx0 - 0.12, fy1 + 0.12, fz - 0.06),
    proj(fx1 + 0.12, fy1 + 0.12, fz - 0.06),
    proj(fx1 + 0.08, fy1, fz),
    proj(fx0 - 0.08, fy1, fz)
  ];
  brush.fill("#8c3e18", 210);
  brush.fillBleed(0.05, "in");
  drawShape(corniceTop, 0);
  resetBrush();

  // Fluted pilaster grooves and wood grain on mirror frame in pencil
  brush.set("2B", "#120904", 0.75);
  for (let fp of framePieces) drawShape(fp, 0, true);
  drawShape(glassQuad, 0, true);

  // Brass inner fillet strip catching tungsten light
  brush.set("cpencil", "#d48a35", 0.7);
  let gTop1 = proj(mx0, my1 + 0.02, fz);
  let gTop2 = proj(mx1, my1 + 0.02, fz);
  let gBot1 = proj(mx0, my0 - 0.01, fz);
  let gBot2 = proj(mx1, my0 - 0.01, fz);
  brush.line(gTop1[0], gTop1[1], gTop2[0], gTop2[1]);
  brush.line(gBot1[0], gBot1[1], gBot2[0], gBot2[1]);

  // Pilaster fluting lines
  brush.set("HB", "#4d2712", 0.55);
  for (let k = 1; k <= 3; k++) {
    let lx = fx0 + (mx0 - fx0) * (k / 4);
    let rx = mx1 + (fx1 - mx1) * (k / 4);
    let lp1 = proj(lx, my1 - 0.1, fz), lp2 = proj(lx, my0 + 0.1, fz);
    let rp1 = proj(rx, my1 - 0.1, fz), rp2 = proj(rx, my0 + 0.1, fz);
    brush.line(lp1[0], lp1[1], lp2[0], lp2[1]);
    brush.line(rp1[0], rp1[1], rp2[0], rp2[1]);
  }
  resetBrush();
}

// ============================================================================
// 5. BARBER COUNTER, COMBS IN BLUE BARBICIDE & STATION TOOLS
// ============================================================================
function drawBarberCounterAndBarbicide() {
  resetBrush();

  // Wooden cabinet body below counter (x = -2.65 to 3.15, y = 0.0 to 2.76, z = 10.95 to 11.95)
  let cabFront = [
    proj(-2.65, 2.76, 10.95),
    proj(3.15, 2.76, 10.95),
    proj(3.15, 0.25, 10.95),
    proj(-2.65, 0.25, 10.95)
  ];
  let cabRight = [
    proj(3.15, 2.76, 10.95),
    proj(3.15, 2.76, 11.95),
    proj(3.15, 0.25, 11.95),
    proj(3.15, 0.25, 10.95)
  ];
  brush.fill("#261309", 230);
  brush.fillBleed(0.06, "in");
  brush.fillTexture(0.6, 0.5);
  drawShape(cabFront, 0);
  brush.wash("#170b05", 235);
  drawShape(cabRight, 0);
  resetBrush();

  // Charcoal mass in the recessed shadow under the cabinet toe-kick and side
  brush.mass("charcoal", "#120a05", {
    precision: 0.7,
    strength: 0.85,
    gradient: 0.3,
    outline: false
  });
  drawShape([
    proj(-2.65, 0.55, 10.95),
    proj(3.15, 0.55, 10.95),
    proj(3.15, 0.0, 11.2),
    proj(-2.65, 0.0, 11.2)
  ], 0);
  resetBrush();

  // Cabinet drawers, doors & brass pulls
  for (let dx = -2.4; dx < 2.8; dx += 1.32) {
    let dw = 1.15;
    // Upper drawer
    let drw = [
      proj(dx, 2.62, 10.93),
      proj(dx + dw, 2.62, 10.93),
      proj(dx + dw, 2.15, 10.93),
      proj(dx, 2.15, 10.93)
    ];
    // Lower cabinet door
    let door = [
      proj(dx, 2.02, 10.93),
      proj(dx + dw, 2.02, 10.93),
      proj(dx + dw, 0.52, 10.93),
      proj(dx, 0.52, 10.93)
    ];
    brush.wash("#1b0d06", 200);
    drawShape(drw, 0);
    drawShape(door, 0);
    resetBrush();

    brush.set("2H", "#4a2914", 0.6);
    drawShape(drw, 0, true);
    drawShape(door, 0, true);

    // Brass cup pull on drawer
    let pullPt = proj(dx + dw * 0.5, 2.38, 10.90);
    brush.set("cpencil", "#c77d2e", 0.8);
    brush.arc(pullPt[0], pullPt[1], 5, 180, 360);
  }
  resetBrush();

  // Aged Marble Countertop Slab (y = 2.76 to 2.92, x = -2.78 to 3.28, z = 10.82 to 11.92)
  let marbleTop = [
    proj(-2.78, 2.92, 11.92),
    proj(3.28, 2.92, 11.92),
    proj(3.28, 2.92, 10.82),
    proj(-2.78, 2.92, 10.82)
  ];
  let marbleFront = [
    proj(-2.78, 2.92, 10.82),
    proj(3.28, 2.92, 10.82),
    proj(3.28, 2.76, 10.82),
    proj(-2.78, 2.76, 10.82)
  ];
  let marbleRight = [
    proj(3.28, 2.92, 10.82),
    proj(3.28, 2.92, 11.92),
    proj(3.28, 2.76, 11.92),
    proj(3.28, 2.76, 10.82)
  ];

  // Warm burnt sienna / ochre watercolor wash on marble top
  brush.fill("#b88348", 190);
  brush.fillBleed(0.08, "in");
  brush.fillTexture(0.55, 0.35);
  drawShape(marbleTop, 0);

  // Hotter cadmium-amber light pool on center of marble counter
  let marbleGlow = [
    proj(-1.2, 2.92, 11.90),
    proj(2.1, 2.92, 11.90),
    proj(1.9, 2.92, 10.85),
    proj(-1.0, 2.92, 10.85)
  ];
  brush.fill("#d98b32", 115);
  brush.fillBleed(0.15, "in");
  drawShape(marbleGlow, 0);

  brush.wash("#7d4f25", 215);
  drawShape(marbleFront, 0);
  brush.wash("#4a2c14", 225);
  drawShape(marbleRight, 0);
  resetBrush();

  // Marble veining & crisp edges in 2H pencil
  brush.set("2H", "#3b2210", 0.65);
  drawShape(marbleTop, 0, true);
  drawShape(marbleFront, 0, true);
  brush.set("cpencil", "#f0c97d", 0.65);
  let mf1 = proj(-2.4, 2.92, 10.82);
  let mf2 = proj(2.8, 2.92, 10.82);
  brush.line(mf1[0], mf1[1], mf2[0], mf2[1]);

  // Subtle grey-umber veins in marble
  brush.set("2H", "#634323", 0.4);
  for (let i = 0; i < 12; i++) {
    let vx = random(-2.5, 3.0);
    let p1 = proj(vx, 2.92, 11.85);
    let p2 = proj(vx + random(-0.35, 0.35), 2.92, 11.35);
    let p3 = proj(vx + random(-0.5, 0.5), 2.92, 10.88);
    brush.spline([p1, p2, p3], 0.4);
  }
  resetBrush();

  // ==========================================================================
  // HERO DETAIL: COMBS IN BLUE BARBICIDE JAR (Positioned at x = 1.56, z = 11.22)
  // ==========================================================================
  let jx = 1.56, jy = 2.92, jz = 11.22;
  let jRad = 0.33;
  let jHeight = 1.02;
  let liqHeight = 0.74;

  // Cast shadow + blue-teal refracted caustic on the marble counter behind/right of jar!
  let causticPts = [
    proj(jx - 0.15, jy + 0.01, jz),
    proj(jx + 0.52, jy + 0.01, jz + 0.15),
    proj(jx + 0.48, jy + 0.01, jz + 0.52),
    proj(jx - 0.12, jy + 0.01, jz + 0.45)
  ];
  brush.fill("#1d698c", 130);
  brush.fillBleed(0.14, "out");
  drawShape(causticPts, 0.2);
  resetBrush();

  // Glass cylinder outer body (y = jy to jy + jHeight)
  let jarLeftBot = proj(jx - jRad, jy, jz);
  let jarRightBot = proj(jx + jRad, jy, jz);
  let jarLeftTop = proj(jx - jRad, jy + jHeight, jz);
  let jarRightTop = proj(jx + jRad, jy + jHeight, jz);
  let jarLeftLiq = proj(jx - jRad * 0.92, jy + liqHeight, jz);
  let jarRightLiq = proj(jx + jRad * 0.92, jy + liqHeight, jz);

  // Clear glass upper air zone
  let glassAirQuad = [jarLeftTop, jarRightTop, jarRightLiq, jarLeftLiq];
  brush.wash("#d6ab6d", 85);
  drawShape(glassAirQuad, 0);
  resetBrush();

  // Vivid yet earthy-lit Blue Barbicide disinfectant liquid
  let liqQuad = [
    jarLeftLiq,
    jarRightLiq,
    proj(jx + jRad * 0.92, jy + 0.06, jz),
    proj(jx - jRad * 0.92, jy + 0.06, jz)
  ];
  brush.fill("#16689e", 205);
  brush.fillBleed(0.06, "in");
  brush.fillTexture(0.55, 0.4);
  drawShape(liqQuad, 0.05);

  // Deeper Prussian-cerulean shadow side of the Barbicide liquid (right side)
  let liqRightShadow = [
    interpPt(jarLeftLiq, jarRightLiq, 0.55),
    jarRightLiq,
    proj(jx + jRad * 0.92, jy + 0.06, jz),
    proj(jx + 0.04, jy + 0.06, jz)
  ];
  brush.fill("#0b3d63", 175);
  brush.fillBleed(0.08, "in");
  drawShape(liqRightShadow, 0);

  // Luminous cyan-blue core glow where tungsten light transmits through the liquid
  let liqCoreGlow = [
    interpPt(jarLeftLiq, jarRightLiq, 0.15),
    interpPt(jarLeftLiq, jarRightLiq, 0.58),
    proj(jx + 0.04, jy + 0.12, jz),
    proj(jx - jRad * 0.65, jy + 0.12, jz)
  ];
  brush.fill("#369bd4", 150);
  brush.fillBleed(0.1, "in");
  drawShape(liqCoreGlow, 0.1);
  resetBrush();

  // Top elliptical meniscus of the blue Barbicide liquid
  let menCenter = proj(jx, jy + liqHeight, jz);
  let menW = (jarRightLiq[0] - jarLeftLiq[0]) * 0.5;
  let menPts = [];
  for (let i = 0; i < 16; i++) {
    let a = (i / 16) * 360;
    menPts.push([menCenter[0] + cos(a) * menW, menCenter[1] + sin(a) * (menW * 0.22)]);
  }
  brush.wash("#4fb3e8", 185);
  drawShape(menPts, 0.2);
  resetBrush();
  brush.set("2H", "#0a3352", 0.6);
  drawShape(menPts, 0.2, true);

  // Central stainless steel lifting rod & round bottom basket plate inside the jar
  let rodTop = proj(jx, jy + jHeight + 0.02, jz);
  let rodLiq = proj(jx, jy + liqHeight, jz);
  let rodBot = proj(jx + 0.02, jy + 0.10, jz);
  brush.set("HB", "#d9c7a3", 0.75);
  brush.line(rodTop[0], rodTop[1], rodLiq[0], rodLiq[1]);
  brush.set("HB", "#7dc4e8", 0.85);
  brush.line(rodLiq[0], rodLiq[1], rodBot[0], rodBot[1]);

  // SUBMERGED COMBS IN THE BARBICIDE (Sharpened with pencil + refraction kink at meniscus!)
  // Comb 1: Black hard-rubber barber comb leaning left-to-right
  let c1Top = [jarLeftTop[0] + 10, jarLeftLiq[1] - 9];
  let c1Men = [jarLeftLiq[0] + 15, jarLeftLiq[1] + 1];
  let c1MenRefr = [jarLeftLiq[0] + 18, jarLeftLiq[1] + 2]; // Refraction shift in liquid!
  let c1Bot = [jarRightBot[0] - 11, jarRightBot[1] - 8];

  // Spine of Comb 1 above liquid
  brush.set("2B", "#140e0a", 1.15);
  brush.line(c1Top[0], c1Top[1], c1Men[0], c1Men[1]);
  // Spine of Comb 1 submerged in blue Barbicide
  brush.set("2B", "#081f33", 1.25);
  brush.line(c1MenRefr[0], c1MenRefr[1], c1Bot[0], c1Bot[1]);

  // Fine teeth of Comb 1 sharpened with 2H pencil
  brush.set("2H", "#081f33", 0.48);
  let numTeeth1 = 18;
  for (let k = 0; k <= numTeeth1; k++) {
    let t = k / numTeeth1;
    let sx = lerp(c1MenRefr[0], c1Bot[0], t);
    let sy = lerp(c1MenRefr[1], c1Bot[1], t);
    brush.line(sx, sy, sx - 9, sy + 5);
  }
  // Teeth above meniscus
  brush.set("2H", "#1a110b", 0.45);
  for (let k = 0; k <= 4; k++) {
    let t = k / 4;
    let sx = lerp(c1Top[0], c1Men[0], t);
    let sy = lerp(c1Top[1], c1Men[1], t);
    brush.line(sx, sy, sx - 8, sy + 4);
  }

  // Comb 2: Ivory/bone tail-comb leaning right-to-left inside the blue liquid
  let c2Top = [jarRightLiq[0] - 11, jarRightLiq[1] + 5];
  let c2Bot = [jarLeftBot[0] + 12, jarLeftBot[1] - 7];
  brush.set("cpencil", "#9ad9f5", 1.0);
  brush.line(c2Top[0], c2Top[1], c2Bot[0], c2Bot[1]);
  brush.set("2H", "#0e3b5c", 0.45);
  brush.line(c2Top[0] + 1, c2Top[1], c2Bot[0] + 1, c2Bot[1]);
  for (let k = 0; k <= 15; k++) {
    let t = k / 15;
    let sx = lerp(c2Top[0], c2Bot[0], t);
    let sy = lerp(c2Top[1], c2Bot[1], t);
    brush.set("cpencil", "#85cae8", 0.42);
    brush.line(sx, sy, sx + 8, sy + 4);
  }

  // Comb 3: Tortoiseshell/amber comb standing nearly vertical on left
  let c3Top = [jarLeftLiq[0] + 9, jarLeftLiq[1] + 8];
  let c3Bot = [jarLeftBot[0] + 8, jarLeftBot[1] - 6];
  brush.set("HB", "#1b3d4a", 0.95);
  brush.line(c3Top[0], c3Top[1], c3Bot[0], c3Bot[1]);
  for (let k = 0; k <= 12; k++) {
    let t = k / 12;
    let sx = lerp(c3Top[0], c3Bot[0], t);
    let sy = lerp(c3Top[1], c3Bot[1], t);
    brush.set("2H", "#0d2c3d", 0.4);
    brush.line(sx, sy, sx + 7, sy + 1);
  }

  // Crisp glass cylinder contours, thick glass base & vertical fluting in 2H + cpencil
  let baseRimPts = [
    jarLeftBot,
    [jarLeftBot[0] + menW, jarLeftBot[1] + 5],
    jarRightBot,
    [jarRightBot[0], jarRightBot[1] - 6],
    [jarLeftBot[0] + menW, jarLeftBot[1] - 2],
    [jarLeftBot[0], jarLeftBot[1] - 6]
  ];
  brush.wash("#7ca8c4", 145);
  drawShape(baseRimPts, 0.15);
  resetBrush();

  // Glass outline & vertical refraction ridges
  brush.set("2H", "#0d293d", 0.65);
  brush.line(jarLeftTop[0], jarLeftTop[1], jarLeftBot[0], jarLeftBot[1]);
  brush.line(jarRightTop[0], jarRightTop[1], jarRightBot[0], jarRightBot[1]);
  brush.line(jarLeftBot[0], jarLeftBot[1], jarRightBot[0], jarRightBot[1]);

  // Warm tungsten specular highlight strips down the glass cylinder
  brush.set("cpencil", "#f5dca8", 0.85);
  brush.line(jarLeftTop[0] + 5, jarLeftTop[1] + 3, jarLeftBot[0] + 5, jarLeftBot[1] - 4);
  brush.set("cpencil", "#7dc8f0", 0.65);
  brush.line(jarRightLiq[0] - 4, jarRightLiq[1] + 3, jarRightBot[0] - 4, jarRightBot[1] - 5);

  // Subtle BARBICIDE white/silver band lettering across center of jar
  let lblY = (jarLeftLiq[1] + jarLeftBot[1]) * 0.52;
  brush.set("cpencil", "#c7e6f5", 0.55);
  brush.line(jarLeftBot[0] + 9, lblY, jarRightBot[0] - 9, lblY);
  brush.line(jarLeftBot[0] + 12, lblY + 4, jarRightBot[0] - 12, lblY + 4);

  // Chrome Domed Lid & Finial Handle of the Barbicide Jar
  let lidPts = [
    [jarLeftTop[0] - 2, jarLeftTop[1] + 2],
    [jarLeftTop[0] + 5, jarLeftTop[1] - 9],
    [menCenter[0], jarLeftTop[1] - 13],
    [jarRightTop[0] - 5, jarRightTop[1] - 9],
    [jarRightTop[0] + 2, jarRightTop[1] + 2]
  ];
  brush.wash("#8a6d4b", 215);
  drawShape(lidPts, 0.25);
  resetBrush();

  // Chrome dark reflection band & bright specular highlight on lid
  brush.set("2B", "#1c1108", 0.95);
  brush.line(jarLeftTop[0] - 2, jarLeftTop[1] + 1, jarRightTop[0] + 2, jarRightTop[1] + 1);
  brush.line(menCenter[0] - 4, jarLeftTop[1] - 10, jarRightTop[0] - 3, jarRightTop[1] - 2);
  brush.set("cpencil", "#fae3a7", 0.95);
  brush.line(jarLeftTop[0] + 4, jarLeftTop[1] - 6, menCenter[0] - 2, jarLeftTop[1] - 11);
  // Top ball finial
  brush.set("2B", "#1a0f08", 0.8);
  brush.circle(menCenter[0], jarLeftTop[1] - 16, 4, 0.05);
  brush.set("cpencil", "#fae3a7", 0.75);
  brush.circle(menCenter[0] - 1, jarLeftTop[1] - 17, 2, 0.05);
  resetBrush();

  // ==========================================================================
  // OTHER COUNTERTOP ITEMS (Amber Tonic Bottle, Shaving Brush, Shears & Towel)
  // ==========================================================================
  // 1. Amber Bay-Rum Tonic Bottle (at x = 2.28, y = 2.92, z = 11.30)
  let bx = 2.28, by = 2.92, bz = 11.30;
  let bBotL = proj(bx - 0.18, by, bz);
  let bBotR = proj(bx + 0.18, by, bz);
  let bShldL = proj(bx - 0.18, by + 0.55, bz);
  let bShldR = proj(bx + 0.18, by + 0.55, bz);
  let bNeckL = proj(bx - 0.06, by + 0.85, bz);
  let bNeckR = proj(bx + 0.06, by + 0.85, bz);
  let bottlePts = [bBotL, bShldL, bNeckL, bNeckR, bShldR, bBotR];
  brush.fill("#8f3914", 205);
  brush.fillBleed(0.06, "in");
  drawShape(bottlePts, 0.15);
  resetBrush();
  // Cream paper label on tonic bottle
  let bLbl = [
    proj(bx - 0.15, by + 0.42, bz),
    proj(bx + 0.15, by + 0.42, bz),
    proj(bx + 0.15, by + 0.16, bz),
    proj(bx - 0.15, by + 0.16, bz)
  ];
  brush.wash("#c9a36b", 195);
  drawShape(bLbl, 0);
  resetBrush();
  brush.set("2H", "#241208", 0.6);
  drawShape(bottlePts, 0.15, true);
  drawShape(bLbl, 0, true);
  brush.set("cpencil", "#f0be69", 0.7);
  brush.line(bShldL[0] + 3, bShldL[1], bBotL[0] + 3, bBotL[1]);

  // 2. Neck Duster Brush on Counter (x = 0.92, y = 2.92, z = 11.38)
  let dx = 0.92, dy = 2.92, dz = 11.38;
  let dBaseL = proj(dx - 0.12, dy, dz);
  let dBaseR = proj(dx + 0.12, dy, dz);
  let dMidL = proj(dx - 0.09, dy + 0.34, dz);
  let dMidR = proj(dx + 0.09, dy + 0.34, dz);
  let dTopL = proj(dx - 0.20, dy + 0.68, dz);
  let dTopR = proj(dx + 0.20, dy + 0.68, dz);
  brush.wash("#6e3819", 215);
  drawShape([dBaseL, dMidL, dMidR, dBaseR], 0.1);
  brush.wash("#9e7c52", 190);
  drawShape([dMidL, dTopL, dTopR, dMidR], 0.2);
  resetBrush();
  // Fine bristle lines in pencil
  brush.set("2H", "#2e1c0e", 0.45);
  for (let k = 0; k <= 10; k++) {
    let t = k / 10;
    let p1 = interpPt(dMidL, dMidR, t);
    let p2 = interpPt(dTopL, dTopR, t);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // 3. Folded Linen Barber Towel & Chrome Clippers on left counter (x = -1.65, z = 11.15)
  let twlPts = [
    proj(-2.25, 2.93, 11.35),
    proj(-1.25, 2.93, 11.42),
    proj(-1.18, 2.93, 10.85),
    proj(-2.32, 2.93, 10.85)
  ];
  brush.wash("#b89564", 185);
  drawShape(twlPts, 0.1);
  resetBrush();
  brush.set("2H", "#452b16", 0.5);
  drawShape(twlPts, 0.1, true);

  // Barber shears resting on the towel
  let sh1 = proj(-1.85, 2.95, 11.18);
  let sh2 = proj(-1.35, 2.95, 11.02);
  let sh3 = proj(-1.38, 2.95, 11.12);
  brush.set("2B", "#1f1209", 0.75);
  brush.line(sh1[0], sh1[1], sh2[0], sh2[1]);
  brush.line(sh1[0], sh1[1] + 3, sh3[0], sh3[1]);
  brush.circle(sh1[0] - 4, sh1[1] - 2, 4, 0.1);
  brush.circle(sh1[0] - 3, sh1[1] + 4, 4, 0.1);
  brush.set("cpencil", "#f2cf88", 0.6);
  brush.line(sh1[0], sh1[1], sh2[0], sh2[1]);

  // Coiled black clipper cord hanging below left counter edge
  let cordPts = [];
  for (let k = 0; k <= 14; k++) {
    let t = k / 14;
    let cx = -1.12 + sin(k * 95) * 0.08;
    let cy = 2.88 - t * 0.95;
    let cz = 10.82 + cos(k * 95) * 0.05;
    cordPts.push(proj(cx, cy, cz));
  }
  brush.set("2B", "#120905", 0.85);
  brush.spline(cordPts, 0.5);
  resetBrush();
}

// ============================================================================
// 6. SINGLE BARE-BULB WALL SCONCE (WARM WITHOUT GLOWING)
// ============================================================================
function drawWallSconce() {
  resetBrush();

  let sx = SCONCE.x;
  let sy = SCONCE.y;
  let wallPt = proj(sx, sy + 0.25, 11.95);
  let elbowPt = proj(sx, sy + 0.34, 11.42);
  let socketPt = proj(sx, sy + 0.16, 11.42);
  let bulbCenter = proj(sx, sy - 0.06, 11.42);

  // Cast shadow of the brass wall plate and arm upward-right onto the plaster wall
  let sconceShadow = [
    [wallPt[0] - 10, wallPt[1] - 14],
    [wallPt[0] + 22, wallPt[1] - 22],
    [wallPt[0] + 26, wallPt[1] + 6],
    [wallPt[0] - 8, wallPt[1] + 10]
  ];
  brush.fill("#45210d", 150);
  brush.fillBleed(0.15, "out");
  drawShape(sconceShadow, 0.2);
  resetBrush();

  // Warm pigment halo immediately behind the bare bulb (burnt sienna + cadmium orange, no white bloom)
  brush.fill("#d97218", 115);
  brush.fillBleed(0.25, "out");
  brush.circle(bulbCenter[0], bulbCenter[1] + 4, 48, 0.15);
  resetBrush();

  // Tarnished brass wall backplate
  brush.wash("#3b200e", 230);
  brush.circle(wallPt[0], wallPt[1], 16, 0.08);
  resetBrush();
  brush.set("2B", "#170c06", 0.85);
  brush.circle(wallPt[0], wallPt[1], 16, 0.06);
  brush.set("cpencil", "#c77d28", 0.7);
  brush.arc(wallPt[0], wallPt[1], 13, 200, 340);

  // Curved brass gooseneck arm & bakelite turn-key socket
  brush.set("2B", "#211108", 2.2);
  brush.spline([wallPt, [wallPt[0] - 2, elbowPt[1] - 6], elbowPt, socketPt], 0.4);
  brush.set("cpencil", "#d98e32", 0.9);
  brush.spline([[wallPt[0], wallPt[1] + 2], [elbowPt[0], elbowPt[1] - 3], socketPt], 0.4);

  // Brass socket cylinder & turn-key
  let sockQuad = [
    [socketPt[0] - 8, socketPt[1] - 10],
    [socketPt[0] + 8, socketPt[1] - 10],
    [socketPt[0] + 7, socketPt[1] + 5],
    [socketPt[0] - 7, socketPt[1] + 5]
  ];
  brush.wash("#361d0c", 235);
  drawShape(sockQuad, 0);
  resetBrush();
  brush.set("2H", "#140a05", 0.7);
  drawShape(sockQuad, 0, true);
  // Turn-key paddle on right of socket
  brush.set("2B", "#1c0e06", 1.1);
  brush.line(socketPt[0] + 8, socketPt[1] - 4, socketPt[0] + 17, socketPt[1] - 4);
  brush.circle(socketPt[0] + 18, socketPt[1] - 4, 3.5, 0.05);

  // Bare Edison-style Pear Glass Bulb (warm ochre/amber wash, crisp graphite contour & filament)
  let bulbPts = [
    [socketPt[0] - 6, socketPt[1] + 5],
    [bulbCenter[0] - 14, bulbCenter[1] - 2],
    [bulbCenter[0] - 12, bulbCenter[1] + 15],
    [bulbCenter[0], bulbCenter[1] + 22],
    [bulbCenter[0] + 12, bulbCenter[1] + 15],
    [bulbCenter[0] + 14, bulbCenter[1] - 2],
    [socketPt[0] + 6, socketPt[1] + 5]
  ];
  brush.fill("#e6a33e", 215);
  brush.fillBleed(0.06, "in");
  drawShape(bulbPts, 0.35);
  resetBrush();

  // Warm cadmium-amber core inside bulb
  brush.wash("#f2c261", 195);
  brush.circle(bulbCenter[0], bulbCenter[1] + 6, 11, 0.1);
  resetBrush();

  // Crisp glass envelope & dark umber reflection streak on bulb glass (pencil)
  brush.set("2H", "#4a250e", 0.65);
  drawShape(bulbPts, 0.35, true);
  brush.set("HB", "#703614", 0.55);
  brush.arc(bulbCenter[0], bulbCenter[1] + 6, 11, 25, 145);

  // Delicate glowing tungsten hairpin filament inside the bulb
  brush.set("2H", "#8c3d14", 0.5);
  brush.line(socketPt[0] - 2, socketPt[1] + 5, bulbCenter[0] - 4, bulbCenter[1] + 8);
  brush.line(socketPt[0] + 2, socketPt[1] + 5, bulbCenter[0] + 4, bulbCenter[1] + 8);
  brush.set("cpencil", "#faDF96", 0.95);
  brush.spline([
    [bulbCenter[0] - 4, bulbCenter[1] + 8],
    [bulbCenter[0] - 3, bulbCenter[1] + 15],
    [bulbCenter[0], bulbCenter[1] + 12],
    [bulbCenter[0] + 3, bulbCenter[1] + 15],
    [bulbCenter[0] + 4, bulbCenter[1] + 8]
  ], 0.3);
  resetBrush();
}

// ============================================================================
// 7. CRACKED OXBLOOD LEATHER BARBER CHAIR & CHROME FOOTRESTS
// ============================================================================
function drawBarberChair() {
  resetBrush();

  // --------------------------------------------------------------------------
  // A. ROUND PORCELAIN & CHROME PEDESTAL BASE + HYDRAULIC COLUMN
  // --------------------------------------------------------------------------
  // Base rubber ring & chrome outer flange on floor (y = 0.0 to 0.14, rad = 1.15)
  let baseRingBot = [];
  let baseRingMid = [];
  let baseConeTop = [];
  let steps = 20;
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360;
    baseRingBot.push(projChair(cos(a) * 1.15, 0.02, sin(a) * 1.15));
    baseRingMid.push(projChair(cos(a) * 1.06, 0.14, sin(a) * 1.06));
    baseConeTop.push(projChair(cos(a) * 0.34, 0.46, sin(a) * 0.34));
  }

  // Dark rubber gasket & chrome rim
  brush.wash("#1a0e07", 235);
  drawShape(baseRingBot, 0.2);
  resetBrush();

  // Porcelain cone of pedestal base (warm cream-ochre in tungsten light, raw umber in shadow)
  let conePoly = [
    baseRingMid[0],
    baseRingMid[2],
    baseRingMid[5],
    baseRingMid[8],
    baseRingMid[10],
    baseConeTop[10],
    baseConeTop[5],
    baseConeTop[0]
  ];
  brush.fill("#9e7240", 215);
  brush.fillBleed(0.06, "in");
  drawShape(conePoly, 0.2);

  // Shadow side (left) of porcelain base cone
  let coneShadow = [
    baseRingMid[5],
    baseRingMid[8],
    baseRingMid[11],
    baseConeTop[11],
    baseConeTop[8],
    baseConeTop[5]
  ];
  brush.fill("#331d0e", 210);
  brush.fillBleed(0.08, "in");
  drawShape(coneShadow, 0.15);

  // Warm tungsten highlight on right-front of porcelain cone
  let coneLit = [
    baseRingMid[18],
    baseRingMid[1],
    baseRingMid[3],
    baseConeTop[3],
    baseConeTop[1],
    baseConeTop[18]
  ];
  brush.fill("#d9a55b", 180);
  brush.fillBleed(0.08, "in");
  drawShape(coneLit, 0.15);
  resetBrush();

  // Central Hydraulic Chrome Column (y = 0.44 to 1.85, rad = 0.28)
  let colLBot = projChair(-0.28, 0.44, 0);
  let colRBot = projChair(0.28, 0.44, 0);
  let colLTop = projChair(-0.26, 1.85, 0);
  let colRTop = projChair(0.26, 1.85, 0);
  brush.wash("#241309", 235);
  drawShape([colLBot, colLTop, colRTop, colRBot], 0);
  resetBrush();

  // High-contrast chrome reflection stripes on hydraulic column
  brush.set("cpencil", "#f0cb80", 1.1);
  let cStr1 = interpPt(colLBot, colRBot, 0.68);
  let cStr2 = interpPt(colLTop, colRTop, 0.68);
  brush.line(cStr1[0], cStr1[1], cStr2[0], cStr2[1]);
  brush.set("HB", "#8f6536", 0.9);
  let cStr3 = interpPt(colLBot, colRBot, 0.28);
  let cStr4 = interpPt(colLTop, colRTop, 0.28);
  brush.line(cStr3[0], cStr3[1], cStr4[0], cStr4[1]);

  // Cast-iron under-seat spider mechanism & hydraulic foot-pump lever
  let mechQuad = [
    projChair(-0.68, 1.88, -0.35),
    projChair(0.68, 1.88, -0.35),
    projChair(0.42, 1.48, 0.15),
    projChair(-0.42, 1.48, 0.15)
  ];
  brush.wash("#140b05", 240);
  drawShape(mechQuad, 0.1);
  resetBrush();

  // Hydraulic pump pedal lever jutting out to the left-rear
  let ped1 = projChair(-0.22, 1.25, 0.15);
  let ped2 = projChair(-0.98, 0.88, 0.45);
  let ped3 = projChair(-1.12, 0.92, 0.52);
  brush.set("2B", "#1a0e07", 1.4);
  brush.line(ped1[0], ped1[1], ped2[0], ped2[1]);
  brush.circle(ped3[0], ped3[1], 8, 0.1);
  brush.set("cpencil", "#e8be72", 0.75);
  brush.line(ped1[0], ped1[1] - 2, ped2[0], ped2[1] - 2);
  brush.arc(ped3[0], ped3[1], 7, 190, 340);

  // Pencil sharpening of pedestal base rings
  brush.set("2B", "#140b05", 0.85);
  drawShape(baseRingBot, 0.2, true);
  brush.set("2H", "#38200f", 0.65);
  drawShape(baseRingMid, 0.2, true);
  brush.set("cpencil", "#f2cf88", 0.85);
  brush.spline([baseRingMid[18], baseRingMid[0], baseRingMid[2], baseRingMid[4]], 0.4);
  resetBrush();

  // --------------------------------------------------------------------------
  // B. CRACKED OXBLOOD LEATHER SEAT CUSHION & APRON
  // --------------------------------------------------------------------------
  // Seat cushion bounds in chair-local coords:
  // lx = -0.95 to +0.95, ly = 1.82 to 2.34, lz = -0.92 (front) to +0.85 (back)
  let sFLB = projChair(-0.95, 1.82, -0.90);
  let sFRB = projChair(0.95, 1.82, -0.90);
  let sBLB = projChair(-0.92, 1.82, 0.82);
  let sBRB = projChair(0.92, 1.82, 0.82);

  let sFLT = projChair(-0.96, 2.32, -0.88);
  let sFRT = projChair(0.96, 2.32, -0.88);
  let sBLT = projChair(-0.92, 2.30, 0.80);
  let sBRT = projChair(0.92, 2.30, 0.80);
  let sMidFront = projChair(0.0, 2.36, -0.94);
  let sCenterDip = projChair(0.0, 2.22, -0.05);

  // Cast-iron/chrome seat apron under the oxblood cushion
  let apronFront = [
    sFLB,
    sFRB,
    projChair(0.92, 1.66, -0.85),
    projChair(-0.92, 1.66, -0.85)
  ];
  let apronLeft = [
    sBLB,
    sFLB,
    projChair(-0.92, 1.66, -0.85),
    projChair(-0.88, 1.66, 0.78)
  ];
  brush.wash("#24140a", 230);
  drawShape(apronFront, 0);
  brush.wash("#170c06", 235);
  drawShape(apronLeft, 0);
  resetBrush();
  brush.set("cpencil", "#e6ba6e", 0.75);
  brush.line(apronFront[0][0], apronFront[0][1] + 3, apronFront[1][0], apronFront[1][1] + 3);

  // Oxblood Leather Seat Side & Front Boxing
  let seatLeftSide = [sBLT, sFLT, sFLB, sBLB];
  let seatFrontSide = [sFLT, sMidFront, sFRT, sFRB, sFLB];
  let seatTop = [sBLT, sFLT, sMidFront, sFRT, sBRT];

  // Shadowed left side of oxblood seat
  brush.fill("#360b09", 230);
  brush.fillBleed(0.06, "in");
  brush.fillTexture(0.65, 0.5);
  drawShape(seatLeftSide, 0.1);

  // Front roll of oxblood seat (deep oxblood + burnt sienna)
  brush.fill("#5e1611", 225);
  brush.fillBleed(0.06, "in");
  brush.fillTexture(0.65, 0.45);
  drawShape(seatFrontSide, 0.15);

  // Top plane of oxblood seat (lit by overhead tungsten bulb!)
  brush.fill("#7a1f16", 220);
  brush.fillBleed(0.08, "in");
  brush.fillTexture(0.65, 0.45);
  drawShape(seatTop, 0.15);

  // Warm burnt sienna & cadmium-orange highlight on front-right crown of oxblood seat
  let seatCrownGlow = [
    interpPt(sFLT, sMidFront, 0.35),
    sMidFront,
    sFRT,
    interpPt(sFRT, sBRT, 0.55),
    sCenterDip
  ];
  brush.fill("#a8381c", 160);
  brush.fillBleed(0.14, "in");
  drawShape(seatCrownGlow, 0.25);

  // Darker worn depression in the middle of the seat cushion
  let seatHollow = [
    interpPt(sBLT, sFLT, 0.45),
    interpPt(sFLT, sMidFront, 0.4),
    interpPt(sFRT, sBRT, 0.45),
    interpPt(sBLT, sBRT, 0.5)
  ];
  brush.fill("#3d0c09", 165);
  brush.fillBleed(0.15, "in");
  drawShape(seatHollow, 0.3);
  resetBrush();

  // Piping seams & HYPERREAL CRACKS in the oxblood leather seat (Pencil)
  brush.set("2B", "#1c0504", 0.9);
  drawShape(seatTop, 0.15, true);
  drawShape(seatFrontSide, 0.15, true);
  brush.set("cpencil", "#d96b38", 0.65);
  brush.spline([sFLT, sMidFront, sFRT], 0.3);

  // Network of alligator cracks, radial sit-creases & worn scuff highlights on seat
  let crackSeeds = [
    [[-0.45, 2.31, -0.55], [-0.15, 2.25, -0.20], [0.12, 2.23, 0.05], [0.42, 2.28, 0.25]],
    [[-0.25, 2.33, -0.78], [-0.08, 2.28, -0.42], [0.05, 2.24, -0.10], [-0.12, 2.26, 0.32]],
    [[0.22, 2.34, -0.82], [0.15, 2.29, -0.45], [0.35, 2.28, -0.15], [0.62, 2.30, 0.10]],
    [[0.48, 2.33, -0.72], [0.38, 2.12, -0.89], [0.42, 1.92, -0.89]],
    [[-0.38, 2.32, -0.75], [-0.32, 2.10, -0.89], [-0.36, 1.90, -0.89]],
    [[0.02, 2.35, -0.92], [0.05, 2.12, -0.91], [-0.02, 1.92, -0.90]],
    [[-0.58, 2.30, -0.25], [-0.22, 2.24, -0.15], [0.18, 2.25, -0.28], [0.58, 2.31, -0.42]]
  ];

  for (let cPath of crackSeeds) {
    let pts2d = cPath.map(p => projChair(p[0], p[1], p[2]));
    // Worn lighter sienna scuff edge alongside crack
    brush.set("cpencil", "#c95d2e", 0.5);
    let offsetPts = pts2d.map(p => [p[0] + 1.2, p[1] - 1.0]);
    brush.spline(offsetPts, 0.35);
    // Crisp dark crack fissure
    brush.set("2B", "#170403", 0.72);
    brush.spline(pts2d, 0.35);

    // Tiny branching secondary cracks
    for (let k = 1; k < pts2d.length - 1; k++) {
      let bp = pts2d[k];
      let ang = random(-70, 70);
      let len = random(6, 15);
      brush.set("2H", "#1f0504", 0.5);
      brush.line(bp[0], bp[1], bp[0] + cos(ang) * len, bp[1] + sin(ang) * len);
    }
  }
  resetBrush();

  // --------------------------------------------------------------------------
  // C. TUFTED OXBLOOD LEATHER BACKREST & CURVED HEADREST
  // --------------------------------------------------------------------------
  // Backrest in chair-local coords: lx = -0.88 to +0.88, ly = 2.35 to 3.78, lz = 0.72 to 1.08
  let bBL = projChair(-0.88, 2.32, 0.72);
  let bBR = projChair(0.88, 2.32, 0.72);
  let bTL = projChair(-0.82, 3.68, 1.02);
  let bTR = projChair(0.82, 3.68, 1.02);
  let bTopCrown = projChair(0.0, 3.82, 1.06);

  // Outer chrome U-frame around the backrest
  let chromeFrameOuter = [
    projChair(-0.96, 2.32, 0.74),
    projChair(-0.90, 3.74, 1.05),
    projChair(0.0, 3.90, 1.09),
    projChair(0.90, 3.74, 1.05),
    projChair(0.96, 2.32, 0.74)
  ];
  brush.set("2B", "#211108", 2.0);
  brush.spline(chromeFrameOuter, 0.25);
  brush.set("cpencil", "#f2ce85", 0.95);
  brush.spline([chromeFrameOuter[1], chromeFrameOuter[2], chromeFrameOuter[3]], 0.25);

  // Oxblood backrest main leather pad
  let backPadPts = [bBL, bTL, bTopCrown, bTR, bBR];
  brush.fill("#59140f", 230);
  brush.fillBleed(0.06, "in");
  brush.fillTexture(0.65, 0.5);
  drawShape(backPadPts, 0.2);

  // Lit upper-right zone of oxblood backrest (burnt sienna + cadmium orange warmth)
  let backLitPts = [
    projChair(-0.15, 2.95, 0.85),
    bTopCrown,
    bTR,
    projChair(0.85, 2.75, 0.82)
  ];
  brush.fill("#9c3018", 165);
  brush.fillBleed(0.14, "in");
  drawShape(backLitPts, 0.2);

  // Deep shadow on lower-left of backrest
  let backShadowPts = [
    bBL,
    projChair(-0.85, 3.25, 0.92),
    projChair(-0.05, 2.85, 0.84),
    projChair(0.15, 2.32, 0.72)
  ];
  brush.fill("#2e0806", 180);
  brush.fillBleed(0.12, "in");
  drawShape(backShadowPts, 0.15);
  resetBrush();

  // Diamond button tufting & leather creases on backrest (Pencil)
  brush.set("2B", "#1a0403", 0.85);
  drawShape(backPadPts, 0.2, true);

  let tuftCoords = [
    [-0.44, 3.35, 0.94], [0.0, 3.38, 0.95], [0.44, 3.35, 0.94],
    [-0.24, 2.98, 0.86], [0.24, 2.98, 0.86],
    [-0.44, 2.62, 0.78], [0.0, 2.62, 0.78], [0.44, 2.62, 0.78]
  ];
  let tuftPts = tuftCoords.map(c => projChair(c[0], c[1], c[2]));

  // Diamond fold lines connecting buttons
  let diamondPairs = [
    [0, 3], [1, 3], [1, 4], [2, 4],
    [3, 5], [3, 6], [4, 6], [4, 7]
  ];
  for (let dp of diamondPairs) {
    let pA = tuftPts[dp[0]];
    let pB = tuftPts[dp[1]];
    brush.set("cpencil", "#bd5128", 0.5);
    brush.line(pA[0] + 1.5, pA[1], pB[0] + 1.5, pB[1]);
    brush.set("2B", "#170403", 0.75);
    brush.line(pA[0], pA[1], pB[0], pB[1]);
  }

  // Tuft buttons & radiating crinkles
  for (let tp of tuftPts) {
    brush.wash("#120302", 235);
    brush.circle(tp[0], tp[1], 4.2, 0.08);
    resetBrush();
    brush.set("cpencil", "#d96e38", 0.55);
    brush.arc(tp[0], tp[1], 4.5, 200, 350);
  }
  resetBrush();

  // Curved Oxblood Headrest & Chrome Support Bar (ly = 3.82 to 4.38)
  let hBarB = projChair(0.0, 3.82, 1.08);
  let hBarT = projChair(0.0, 4.06, 1.12);
  brush.set("2B", "#1a0e07", 1.8);
  brush.line(hBarB[0], hBarB[1], hBarT[0], hBarT[1]);
  brush.set("cpencil", "#f2cf88", 0.9);
  brush.line(hBarB[0] + 2, hBarB[1], hBarT[0] + 2, hBarT[1]);

  let hrPts = [
    projChair(-0.44, 4.02, 1.06),
    projChair(-0.42, 4.34, 1.12),
    projChair(0.0, 4.38, 1.14),
    projChair(0.42, 4.34, 1.12),
    projChair(0.44, 4.02, 1.06)
  ];
  brush.fill("#661812", 230);
  brush.fillBleed(0.06, "in");
  drawShape(hrPts, 0.25);

  // Darkened worn center of headrest + warm top edge highlight
  brush.fill("#2b0705", 175);
  brush.fillBleed(0.12, "in");
  brush.circle((hrPts[0][0] + hrPts[4][0]) * 0.5, (hrPts[1][1] + hrPts[0][1]) * 0.52, 16, 0.2);
  resetBrush();

  brush.set("2B", "#170403", 0.85);
  drawShape(hrPts, 0.25, true);
  brush.set("cpencil", "#e0783c", 0.75);
  brush.spline([hrPts[1], hrPts[2], hrPts[3]], 0.3);
  // Fine cracks on headrest
  brush.set("2H", "#140302", 0.5);
  brush.line(hrPts[2][0] - 8, hrPts[2][1] + 4, hrPts[2][0] - 2, hrPts[2][1] + 16);
  brush.line(hrPts[2][0] + 5, hrPts[2][1] + 3, hrPts[2][0] + 9, hrPts[2][1] + 15);
  resetBrush();

  // --------------------------------------------------------------------------
  // D. PADDED OXBLOOD ARMRESTS & WHITE PORCELAIN / CHROME KNUCKLES
  // --------------------------------------------------------------------------
  let arms = [
    { side: -1, lx: -0.98 }, // Left armrest (closer to viewer)
    { side: 1, lx: 0.98 }    // Right armrest (further/angled toward light)
  ];

  for (let arm of arms) {
    let lx = arm.lx;
    let w = 0.15;

    // Chrome upright support bracket from seat frame to armrest
    let supBot = projChair(lx, 1.88, -0.55);
    let supTop = projChair(lx, 2.65, -0.65);
    brush.set("2B", "#1c0f08", 1.8);
    brush.line(supBot[0], supBot[1], supTop[0], supTop[1]);
    brush.set("cpencil", "#f0cb80", 0.85);
    brush.line(supBot[0] + 2, supBot[1], supTop[0] + 2, supTop[1]);

    // Oxblood leather armrest pad (lz = -0.68 to +0.76, ly = 2.66 to 2.86)
    let aFL = projChair(lx - w, 2.78, -0.68);
    let aFR = projChair(lx + w, 2.78, -0.68);
    let aBL = projChair(lx - w, 2.75, 0.76);
    let aBR = projChair(lx + w, 2.75, 0.76);
    let aFLB = projChair(lx - w, 2.62, -0.66);
    let aBLB = projChair(lx - w, 2.60, 0.76);

    // Side of armrest
    brush.fill("#3d0d0a", 230);
    brush.fillBleed(0.05, "in");
    drawShape([aBL, aFL, aFLB, aBLB], 0.1);

    // Top of armrest
    brush.fill(arm.side === 1 ? "#8c2818" : "#6b1c13", 225);
    brush.fillBleed(0.06, "in");
    drawShape([aBL, aFL, aFR, aBR], 0.1);
    resetBrush();

    // Outlines & leather cracks on armrest
    brush.set("2B", "#170403", 0.8);
    drawShape([aBL, aFL, aFR, aBR], 0.1, true);
    brush.set("cpencil", "#d96b34", 0.65);
    brush.line(aFL[0], aFL[1], aBL[0], aBL[1]);

    for (let k = 1; k <= 5; k++) {
      let t = k / 6;
      let p1 = interpPt(aFL, aBL, t);
      let p2 = interpPt(aFR, aBR, t);
      brush.set("2H", "#1a0403", 0.5);
      brush.line(p1[0], p1[1], (p1[0] + p2[0]) * 0.5, (p1[1] + p2[1]) * 0.5 + 2);
    }

    // White porcelain / chrome front knuckle cap at front of armrest (lz = -0.78)
    let knuckPt = projChair(lx, 2.70, -0.78);
    brush.wash("#d9b47a", 230);
    brush.circle(knuckPt[0], knuckPt[1], 9.5, 0.08);
    resetBrush();
    brush.set("2B", "#1f1108", 0.8);
    brush.circle(knuckPt[0], knuckPt[1], 9.5, 0.06);
    brush.set("cpencil", "#faebc0", 0.9);
    brush.arc(knuckPt[0], knuckPt[1], 6.5, 200, 340);
  }
  resetBrush();

  // --------------------------------------------------------------------------
  // E. HERO DETAIL: CHROME FOOTRESTS (SHARPENED WITH PENCIL)
  // --------------------------------------------------------------------------
  // 1. Curved Chrome Side Struts descending from seat frame (lz = -0.82, ly = 1.72)
  //    through the calf rest to the front footrest platform (lz = -1.92, ly = 0.22)
  for (let side of [-1, 1]) {
    let lx = side * 0.56;
    let st1 = projChair(lx, 1.72, -0.82);
    let st2 = projChair(lx, 0.92, -1.18);
    let st3 = projChair(lx, 0.30, -1.48);
    let st4 = projChair(lx, 0.22, -1.92);

    // Dark chrome core of strut
    brush.set("2B", "#170d06", 2.1);
    brush.spline([st1, st2, st3, st4], 0.35);
    // Warm mid-tone reflection
    brush.set("HB", "#8f6434", 1.1);
    brush.spline([
      [st1[0] + 2, st1[1]],
      [st2[0] + 2, st2[1]],
      [st3[0] + 2, st3[1]],
      [st4[0] + 2, st4[1]]
    ], 0.35);
    // Razor-sharp specular highlight in colored pencil
    brush.set("cpencil", "#faebba", 0.95);
    brush.spline([
      [st1[0] - 1.5, st1[1]],
      [st2[0] - 1.5, st2[1]],
      [st3[0] - 1.5, st3[1]],
      [st4[0] - 1.5, st4[1]]
    ], 0.35);

    // Ornate filigree scroll bracket under the strut
    let fil1 = projChair(lx, 0.62, -1.32);
    let fil2 = projChair(lx, 0.38, -1.62);
    let filMid = projChair(lx, 0.35, -1.38);
    brush.set("2H", "#1c1008", 0.75);
    brush.spline([fil1, filMid, fil2], 0.5);
    brush.circle(filMid[0], filMid[1], 5, 0.1);
    brush.set("cpencil", "#e8be72", 0.6);
    brush.arc(filMid[0], filMid[1], 4.5, 180, 350);
  }

  // 2. Tilted Chrome Leg / Calf Rest Plate (ly = 0.55 to 1.05, lz = -1.35 to -1.12)
  let calfBL = projChair(-0.52, 0.55, -1.35);
  let calfBR = projChair(0.52, 0.55, -1.35);
  let calfTL = projChair(-0.52, 1.05, -1.12);
  let calfTR = projChair(0.52, 1.05, -1.12);
  let calfQuad = [calfTL, calfTR, calfBR, calfBL];

  brush.wash("#593d20", 215);
  drawShape(calfQuad, 0);
  // Dark reflection band across middle of calf rest
  brush.wash("#1c1008", 210);
  drawShape([
    interpPt(calfTL, calfBL, 0.35),
    interpPt(calfTR, calfBR, 0.35),
    interpPt(calfTR, calfBR, 0.72),
    interpPt(calfTL, calfBL, 0.72)
  ], 0);
  resetBrush();

  // Ribbed vertical chrome grooves on calf rest (sharpened with 2H & cpencil)
  brush.set("2B", "#140b05", 0.85);
  drawShape(calfQuad, 0, true);
  let numCalfRibs = 14;
  for (let k = 1; k < numCalfRibs; k++) {
    let t = k / numCalfRibs;
    let pTop = interpPt(calfTL, calfTR, t);
    let pBot = interpPt(calfBL, calfBR, t);
    brush.set("2H", "#1a0e07", 0.55);
    brush.line(pTop[0], pTop[1], pBot[0], pBot[1]);
    if (k % 2 === 0) {
      brush.set("cpencil", "#e8be72", 0.5);
      brush.line(pTop[0] + 1, pTop[1] + 2, pBot[0] + 1, pBot[1] - 2);
    }
  }
  // Top chrome bevel highlight on calf rest
  brush.set("cpencil", "#faebc0", 0.9);
  brush.line(calfTL[0] + 2, calfTL[1] + 1, calfTR[0] - 2, calfTR[1] + 1);
  resetBrush();

  // 3. Main Horizontal Chrome Footrest Platform (ly = 0.22 to 0.28, lz = -1.48 to -2.02)
  let fBL = projChair(-0.58, 0.28, -1.48);
  let fBR = projChair(0.58, 0.28, -1.48);
  let fFL = projChair(-0.62, 0.20, -2.02);
  let fFR = projChair(0.62, 0.20, -2.02);
  let fFLBot = projChair(-0.62, 0.13, -2.02);
  let fFRBot = projChair(0.62, 0.13, -2.02);
  let fBLBot = projChair(-0.58, 0.21, -1.48);

  let footTopQuad = [fBL, fBR, fFR, fFL];
  let footFrontLip = [fFL, fFR, fFRBot, fFLBot];
  let footLeftLip = [fBL, fFL, fFLBot, fBLBot];

  // Base metallic tone on footrest platform
  brush.fill("#8c6538", 220);
  brush.fillBleed(0.04, "in");
  drawShape(footTopQuad, 0);

  // Bright warm amber/cream reflection band on right half of chrome footrest
  let footLitBand = [
    interpPt(fBL, fBR, 0.45),
    fBR,
    fFR,
    interpPt(fFL, fFR, 0.35)
  ];
  brush.fill("#dec082", 185);
  brush.fillBleed(0.06, "in");
  drawShape(footLitBand, 0);

  // Dark chrome reflection on front & side beveled edges
  brush.wash("#1c1008", 235);
  drawShape(footFrontLip, 0);
  drawShape(footLeftLip, 0);
  resetBrush();

  // Inner recessed tread area with cast-metal grid & central emblem
  let inBL = projChair(-0.48, 0.28, -1.55);
  let inBR = projChair(0.48, 0.28, -1.55);
  let inFL = projChair(-0.51, 0.21, -1.94);
  let inFR = projChair(0.51, 0.21, -1.94);
  let inQuad = [inBL, inBR, inFR, inFL];

  brush.wash("#24150b", 220);
  drawShape(inQuad, 0);
  resetBrush();

  // Pencil sharpening of the chrome footrest grid, slotted bars & oval nameplate!
  brush.set("2B", "#120904", 0.9);
  drawShape(footTopQuad, 0, true);
  drawShape(footFrontLip, 0, true);
  drawShape(footLeftLip, 0, true);
  brush.set("HB", "#170c06", 0.75);
  drawShape(inQuad, 0, true);

  // Longitudinal & transverse chrome tread bars inside footrest
  let numGridX = 12;
  for (let i = 1; i < numGridX; i++) {
    let t = i / numGridX;
    let p1 = interpPt(inBL, inBR, t);
    let p2 = interpPt(inFL, inFR, t);
    brush.set("2H", "#120904", 0.6);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
    brush.set("cpencil", "#e8c47a", 0.55);
    brush.line(p1[0] + 1.2, p1[1], p2[0] + 1.2, p2[1]);
  }
  for (let j = 1; j <= 4; j++) {
    let t = j / 5;
    let p1 = interpPt(inBL, inFL, t);
    let p2 = interpPt(inBR, inFR, t);
    brush.set("2H", "#140b05", 0.55);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
    brush.set("cpencil", "#d9b066", 0.5);
    brush.line(p1[0], p1[1] - 1, p2[0], p2[1] - 1);
  }

  // Central oval cast-chrome emblem plate in the middle of the footrest
  let embCenter = projChair(0.0, 0.245, -1.75);
  let embPts = [];
  for (let i = 0; i < 14; i++) {
    let a = (i / 14) * 360;
    embPts.push([embCenter[0] + cos(a) * 22, embCenter[1] + sin(a) * 8]);
  }
  brush.wash("#331d0e", 230);
  drawShape(embPts, 0.25);
  resetBrush();
  brush.set("2H", "#120904", 0.65);
  drawShape(embPts, 0.25, true);
  brush.set("cpencil", "#f2cf88", 0.65);
  drawShape(embPts.map(p => [p[0], p[1] - 1]), 0.25, true);
  // Embossed lettering ticks inside oval ("PAIDAR")
  for (let k = -3; k <= 3; k++) {
    let lx = embCenter[0] + k * 4.2;
    brush.set("cpencil", "#f0cb80", 0.55);
    brush.line(lx, embCenter[1] - 2.5, lx + 1.5, embCenter[1] + 2.5);
  }

  // Stark specular pencil highlights along front and right bevels of the chrome footrest
  brush.set("cpencil", "#faebc0", 1.1);
  brush.line(fFL[0] + 3, fFL[1], fFR[0] - 2, fFR[1]);
  brush.line(fBR[0], fBR[1], fFR[0], fFR[1]);
  brush.set("cpencil", "#e6ba6e", 0.8);
  brush.line(fBL[0] + 4, fBL[1] + 1, fBR[0] - 4, fBR[1] + 1);
  brush.line(fFLBot[0] + 6, fFLBot[1] - 1, fFRBot[0] - 6, fFRBot[1] - 1);
  resetBrush();
}

// ============================================================================
// 8. HAIR CLIPPINGS ON THE CHEQUERED LINOLEUM (SHARPENED WITH PENCIL)
// ============================================================================
function drawHairClippings() {
  resetBrush();

  // Realistic clusters & swept crescent arcs of hair clippings around the chair base & footrest
  let clusters = [
    { cx: 0.45, cz: 6.75, rx: 0.65, rz: 0.45, count: 85 },  // Around & in front of chrome footrest
    { cx: -0.35, cz: 7.25, rx: 0.72, rz: 0.52, count: 75 }, // Left-front of chair base
    { cx: 0.85, cz: 7.85, rx: 0.78, rz: 0.62, count: 95 },  // Swept arc to the right of chair
    { cx: 1.25, cz: 8.65, rx: 0.55, rz: 0.48, count: 65 },  // Denser swept pile near right side
    { cx: -1.15, cz: 8.35, rx: 0.62, rz: 0.55, count: 55 }, // Left side of chair base
    { cx: 0.15, cz: 6.05, rx: 0.85, rz: 0.45, count: 55 }   // Foreground linoleum tiles
  ];

  // Soft raw-umber pencil smudging beneath the densest hair clusters
  for (let c of clusters) {
    let pCenter = proj(c.cx, 0.01, c.cz);
    brush.fill("#29180c", 65);
    brush.fillBleed(0.25, "out");
    brush.circle(pCenter[0], pCenter[1], 24, 0.3);
  }
  resetBrush();

  // Hundreds of fine curved pencil strokes (2B, HB, 2H, cpencil) representing individual locks & wisps
  for (let c of clusters) {
    for (let i = 0; i < c.count; i++) {
      // Non-uniform tuft distribution (locks cluster together)
      let a = random(360);
      let r = Math.pow(random(), 0.75);
      let hx = c.cx + cos(a) * c.rx * r;
      let hz = c.cz + sin(a) * c.rz * r;

      let p0 = proj(hx, 0.01, hz);
      let baseAng = random(360);
      let len = random(5, 17);
      let curveBend = random(-7, 7);

      let p1 = [
        p0[0] + cos(baseAng) * len * 0.5 - sin(baseAng) * curveBend * 0.4,
        p0[1] + sin(baseAng) * len * 0.25 + cos(baseAng) * curveBend * 0.2
      ];
      let p2 = [
        p0[0] + cos(baseAng) * len,
        p0[1] + sin(baseAng) * len * 0.45
      ];

      // Mix of dark espresso, charcoal-black, chestnut, and silver-grey hairs catching tungsten light
      let rnd = random();
      if (rnd < 0.52) {
        brush.set("2B", "#140b06", random(0.42, 0.68));
      } else if (rnd < 0.84) {
        brush.set("HB", "#2b190d", random(0.38, 0.58));
      } else {
        // Salt-and-pepper grey/silver hair catching warm amber light
        brush.set("cpencil", "#b59669", random(0.38, 0.52));
      }
      brush.spline([p0, p1, p2], 0.45);

      // Add 2-3 companion strands in the same lock for hyperreal clumping
      if (random() < 0.55) {
        let ox = random(-2.5, 2.5);
        let oy = random(-1.5, 1.5);
        brush.set("2H", "#1a0e07", 0.38);
        brush.spline([
          [p0[0] + ox, p0[1] + oy],
          [p1[0] + ox * 1.2, p1[1] + oy * 1.2],
          [p2[0] + ox * 0.8, p2[1] + oy * 0.8]
        ], 0.45);
      }
    }
  }

  // Stray fine hair clippings clinging to the chrome footrest and porcelain chair base rim!
  for (let i = 0; i < 24; i++) {
    let lx = random(-0.48, 0.48);
    let lz = random(-1.95, -1.52);
    let hp = projChair(lx, 0.25, lz);
    let ang = random(360);
    let len = random(4, 10);
    brush.set("2H", "#170c06", 0.42);
    brush.line(hp[0], hp[1], hp[0] + cos(ang) * len, hp[1] + sin(ang) * len * 0.5);
  }
  resetBrush();
}

// ============================================================================
// 9. OFF-AXIS DOORWAY FRAME IN DEEP CHARCOAL MASS & UMBER SHADOW
// ============================================================================
function drawDoorwayFrame() {
  resetBrush();

  // Left doorway jamb & wall (angled slightly from x=192 at top to x=156 at bottom for off-axis perspective)
  let leftWallOuter = [
    [0, 0],
    [142, 0],
    [112, 1200],
    [0, 1200]
  ];
  // Molded wood door casing on left
  let leftCasing = [
    [138, 0],
    [192, 0],
    [156, 1200],
    [108, 1200]
  ];
  // Inner door stop & thickness reveal (catches grazing burnt-sienna light!)
  let leftReveal = [
    [190, 74],
    [206, 82],
    [172, 1200],
    [154, 1200]
  ];

  // Top doorway lintel / header (sloping from y=76 on left to y=104 on right)
  let topLintel = [
    [0, 0],
    [1200, 0],
    [1200, 104],
    [190, 76],
    [0, 76]
  ];

  // Right edge of doorway / partially open wooden door
  let rightDoorEdge = [
    [1134, 96],
    [1200, 96],
    [1200, 1200],
    [1146, 1200]
