  // Grazing warm burnt sienna on the inner edge of the doorway reveal facing the sconce
  brush.fill("#5c2811", 210);
  brush.fillBleed(0.06, "in");
  drawShape(leftReveal, 0);
  resetBrush();

  // CHARCOAL MASS across the doorway frame for rich, velvety dry-pigment shadow texture
