  brush.line(206, 82, 172, 1200);
  brush.line(190, 76, 1200, 104);
  brush.line(190, 56, 1200, 84);
  brush.line(1134, 96, 1146, 1200);

  // Fluted molding grooves down the left casing
  brush.set("HB", "#381e0e", 0.6);
  for (let offset of [12, 24, 38]) {
    brush.line(138 + offset, 76, 108 + offset, 1200);
  }

  // Warm burnt sienna / amber grazing pencil highlight along the inner edge of the doorway reveal
  brush.set("cpencil", "#b85d22", 0.75);
  brush.line(205, 84, 184, 780);
  brush.set("cpencil", "#803b14", 0.55);
  brush.line(206, 82, 1134, 102);

  // Tarnished brass mortise strike-plate on the left door jamb at y = 635
  let strikeQuad = [
    [182, 608],
    [194, 610],
    [192, 668],
    [180, 666]
  ];
  brush.wash("#45240f", 230);
  drawShape(strikeQuad, 0);
  resetBrush();
  brush.set("2B", "#0f0704", 0.75);
  drawShape(strikeQuad, 0, true);
  // Latch hole in strike plate + tiny warm amber edge glint
  brush.wash("#0a0503", 245);
  drawShape([[184, 624], [191, 625], [190, 648], [183, 647]], 0);
  resetBrush();
  brush.set("cpencil", "#e09238", 0.75);
  brush.line(193, 611, 191, 667);

  // Vintage brass doorknob & escutcheon plate in shadow on the right door edge (x = 1134, y = 655)
  brush.wash("#2e180a", 235);
  brush.circle(1118, 658, 14, 0.08);
  resetBrush();
  brush.set("2B", "#0d0603", 0.9);
  brush.circle(1118, 658, 14, 0.06);
  brush.line(1128, 655, 1140, 655);
  brush.set("cpencil", "#c97a2b", 0.7);
  brush.arc(1118, 658, 11, 160, 285);
  resetBrush();
}

// ============================================================================
// 10. FINAL HYPERREAL PENCIL SHARPENING & ATMOSPHERIC UNIFICATION
// ============================================================================
function drawFinalPencilAccents() {
  resetBrush();

  // Subtle cross-hatched graphite shadow veil in the four deep corners for tonal depth
  let cornerHatchZones = [
    [[195, 78], [460, 84], [340, 290], [188, 340]],
    [[860, 92], [1132, 98], [1136, 390], [920, 290]],
    [[160, 940], [360, 980], [320, 1200], [154, 1200]],
    [[920, 920], [1142, 880], [1146, 1200], [880, 1200]]
  ];

  brush.hatchStyle("charcoal", "#140b06", 0.65);
  for (let z of cornerHatchZones) {
    brush.hatch(11, 38, { rand: 0.12, gradient: 0.5 });
    drawShape(z, 0.05);
  }
  resetBrush();

  // Fine dust motes & subtle paper grain in the upper tungsten light cone (2H + cpencil)
