// ============================================================================
// GEOMETRY & OPTICAL COORDINATE HELPERS
// ============================================================================

// Back edge of the scarred oak table runs from (0, 385) to (1200, 135)
const TABLE_Y0 = 385;
const TABLE_DX = 1200;
const TABLE_DY = -250;
const TABLE_LEN = Math.hypot(TABLE_DX, TABLE_DY);
const UX = TABLE_DX / TABLE_LEN; //  0.9790
const UY = TABLE_DY / TABLE_LEN; // -0.2039
const VX = -UY;                  //  0.2039
const VY = UX;                   //  0.9790

function tableEdgeY(x) {
  return TABLE_Y0 + (TABLE_DY / TABLE_DX) * x;
}

function tableToWorld(s, t) {
  return [
    s * UX + t * VX,
    TABLE_Y0 + s * UY + t * VY
  ];
}

function worldToTable(x, y) {
  let dx = x;
  let dy = y - TABLE_Y0;
  return [
    dx * UX + dy * UY,
    dx * VX + dy * VY
  ];
}

// Plank seams in table-perpendicular coordinate t
const PLANK_SEAMS = [0, 265, 610, 955, 1350];

// Oak knots positioned across the planks, with three directly in the spectral fan path
const KNOTS = [
  { s: 535, t: 445, rs: 68, rt: 30, amp: 42, coreR: 22, plank: 1, inFan: true },  // World ~(615, 712) - Orange/Lemon/Viridian
  { s: 795, t: 505, rs: 78, rt: 34, amp: 48, coreR: 25, plank: 1, inFan: true },  // World ~(881, 717) - Red/Orange/Lemon
  { s: 675, t: 755, rs: 82, rt: 36, amp: 50, coreR: 26, plank: 2, inFan: true },  // World ~(815, 986) - Viridian/Ultramarine/Violet
  { s: 175, t: 505, rs: 54, rt: 25, amp: 32, coreR: 17, plank: 1, inFan: false }, // World ~(274, 843) - Lower-left plank
  { s: 885, t: 135, rs: 48, rt: 22, amp: 26, coreR: 14, plank: 0, inFan: false }  // World ~(894, 336) - Upper-right plank
];

// Glass tumbler geometry (pushed to upper-left of the diagonal composition)
const GLASS = {
  cx: 310,
  rimY: 184,
  rimRx: 115,
  rimRy: 41,
  waterY: 248,
  waterRx: 108,
  waterRy: 39,
  shamTopY: 396,
  shamTopRx: 95,
  shamTopRy: 35,
  baseY: 432,
  baseRx: 92,
  baseRy: 34
};

function glassRadiusAtY(y) {
  let u = constrain((y - GLASS.rimY) / (GLASS.baseY - GLASS.rimY), 0, 1);
  return {
    rx: lerp(GLASS.rimRx, GLASS.baseRx, u),
    ry: lerp(GLASS.rimRy, GLASS.baseRy, u)
  };
}

// Spectral fan coordinate mapping:
// u in [0, 1]: distance from right side/base of glass toward lower-right corner
// v in [0, 1]: spectral wavelength from Cadmium Red (0) to Violet (1)
function fanPoint(u, v) {
  // Origin curve hugging the sunlit exit wall of the tumbler
  let ang0 = lerp(-12, 68, v);
  let x0 = GLASS.cx + cos(ang0) * lerp(98, 92, v) + 6;
  let y0 = lerp(298, 404, Math.pow(v, 0.85)) + sin(ang0) * 32;

  // Far reach across the lower-right oak table
  let x1 = lerp(1235, 735, Math.pow(v, 0.96));
  let y1 = lerp(740, 1235, Math.pow(v, 0.92));

  // Optical caustic curvature along the ray path
  let spread = Math.pow(u, 1.08);
  let arch = Math.sin(u * 180) * lerp(28, -22, v);
  let x = lerp(x0, x1, spread) + arch * 0.45;
  let y = lerp(y0, y1, spread) - arch * 0.55;
  return [x, y];
}

// Check if a world point (x, y) lies inside the bright spectral fan corridor
function isInSpectralFan(x, y) {
  if (x < 330 || y < 290) return false;
  let dx = x - 355;
  let dy = y - 355;
  let ang = atan2(dy, dx);
  let dist = Math.hypot(dx, dy);
  return ang >= 16 && ang <= 67 && dist > 30 && dist < 1100;
}

// Draw a filled polygon using p5.brush field-aware shape vertices
function drawFilledShape(pts, curvature = 0.12) {
  if (pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

// Compute oak grain deflection around knots and cathedral arches
function sampleOakGrainT(s, tBase, plankIdx) {
  let t = tBase;
  let tMin = PLANK_SEAMS[plankIdx] + 4;
  let tMax = PLANK_SEAMS[plankIdx + 1] - 4;
  let tMid = 0.5 * (tMin + tMax);

  // Subtle cathedral arch modulation along plank length
  let archFreq = 0.22 + plankIdx * 0.05;
  let archShift = plankIdx * 130;
  let distFromCenter = (tBase - tMid) / ((tMax - tMin) * 0.5);
  t += Math.sin((s + archShift) * archFreq) * (1.0 - Math.abs(distFromCenter) * 0.5) * 9.5;
  t += (noise(s * 0.004, tBase * 0.015 + plankIdx * 10) - 0.5) * 14.0;

  // Smooth deflection around knots in the same plank
  for (let k of KNOTS) {
    if (k.plank !== plankIdx) continue;
    let ds = (s - k.s) / k.rs;
    let dt = (t - k.t) / k.rt;
    let d2 = ds * ds + dt * dt;
    if (d2 < 9.0) {
      let sign = dt >= 0 ? 1 : -1;
      let push = k.amp * Math.exp(-d2 * 0.65) * (Math.abs(dt) + 0.18) * sign;
      t += push;
    }
  }
  return constrain(t, tMin, tMax);
}

// ============================================================================
// MAIN RENDER PIPELINE
// ============================================================================

function draw() {
  translate(-width / 2, -height / 2);

  // Warm sunlit cotton watercolor paper base
  background("#faf4e6");

  // 1. Morning wall & base warm oak washes (preserving paper brightness for the spectrum)
  renderMorningGroundAndWall();

  // 2. Scarred oak tabletop: cathedral grain washes, knots, rays, plank seams & knife scars
  renderOakTableUnderlayer();

  // 3. Soft cast shadow & bright caustic envelope behind/beside the tumbler
  renderGlassCastShadowAndCaustics();

  // 4. Wet-on-dry watercolor spectral fan glazes (Cadmium Red -> Violet) & knot overlaps
  renderSpectralFanGlazes();

  // 5. Re-integrated wood grain, knot cracks & optical caustic filaments over the glazes
  renderOakGrainAndCausticOverglaze();

  // 6. Water tumbler: refracted table edge, meniscus, prism rim, bubbles & fine graphite
  renderWaterTumbler();

  // 7. Final quiet morning details: tabletop water droplets, highlight pinpoints & pencil notes
  renderFinalSurfaceIncidents();

  noLoop();
}

