// ============================================================================
// 2. SCARRED OAK TABLE UNDERLAYER (GRAIN WASHES, KNOTS, SEAMS, SCARS)
// ============================================================================

function renderOakTableUnderlayer() {
  brush.noStroke();
  brush.fillBleed(0.12, "out");
  brush.fillTexture(0.6, 0.45);

  // 2A. Cathedral oak grain watercolor ribbons across each plank
  let ribbonColors = ["#d6a467", "#c98f50", "#e0b67e", "#b87b3e"];
  for (let cIdx = 0; cIdx < ribbonColors.length; cIdx++) {
    brush.fill(ribbonColors[cIdx], 34);
    for (let p = 0; p < 3; p++) {
      let tMin = PLANK_SEAMS[p] + 18;
      let tMax = PLANK_SEAMS[p + 1] - 18;
      let numRibbons = 4;
      for (let r = 0; r < numRibbons; r++) {
        if ((p + r + cIdx) % 3 !== 0) continue;
        let tCenter = lerp(tMin, tMax, (r + 0.5) / numRibbons) + (cIdx - 1.5) * 14;
        let halfW = random(8, 18);
        let upperPts = [];
        let lowerPts = [];
        for (let s = -80; s <= 1360; s += 45) {
          let tU = sampleOakGrainT(s, tCenter - halfW, p);
          let tL = sampleOakGrainT(s, tCenter + halfW, p);
          let wU = tableToWorld(s, tU);
          let wL = tableToWorld(s, tL);
          // Keep spectral fan area slightly cleaner by narrowing grain ribbons inside it
          if (isInSpectralFan(wU[0], wU[1])) {
            wL[0] = lerp(wU[0], wL[0], 0.55);
            wL[1] = lerp(wU[1], wL[1], 0.55);
          }
          upperPts.push(wU);
          lowerPts.unshift(wL);
        }
        drawFilledShape(upperPts.concat(lowerPts), 0.2);
      }
    }
  }

  // 2B. Oak knot watercolor bases (warm sienna & umber cores before the spectrum passes over)
  for (let k of KNOTS) {
    let center = tableToWorld(k.s, k.t);
    let haloPts = [];
    let corePts = [];
    for (let a = 0; a < 360; a += 24) {
      let ds = cos(a) * k.coreR * 1.85;
      let dt = sin(a) * k.coreR * 0.95;
      haloPts.push(tableToWorld(k.s + ds, k.t + dt));
      corePts.push(tableToWorld(k.s + ds * 0.55, k.t + dt * 0.58));
    }
    brush.fill("#c28344", k.inFan ? 48 : 68);
    drawFilledShape(haloPts, 0.25);
    brush.fill("#8c5223", k.inFan ? 62 : 85);
    drawFilledShape(corePts, 0.25);
  }
  brush.noFill();

  // 2C. Fine oak grain lines bending around the knots
  let grainPalette = ["#b8834b", "#9e6936", "#c99862", "#7d4e24"];
  for (let p = 0; p < 4; p++) {
    let tStart = PLANK_SEAMS[p] + 6;
    let tEnd = PLANK_SEAMS[p + 1] - 6;
    let stepT = 5.2;

    for (let tBase = tStart; tBase <= tEnd; tBase += stepT) {
      let col = grainPalette[Math.floor(noise(tBase * 0.08, p) * grainPalette.length)];
      let weight = map(noise(tBase * 0.15, p * 3), 0, 1, 0.45, 1.15);
      brush.set("oak_fiber", col, weight);

      let pts = [];
      for (let s = -100; s <= 1380; s += 28) {
        let t = sampleOakGrainT(s, tBase, p);
        let wp = tableToWorld(s, t);
        if (wp[0] >= -30 && wp[0] <= 1230 && wp[1] >= 120 && wp[1] <= 1230) {
          // Skip interior of the glass tumbler (we will draw refracted grain inside the glass separately)
          let gx = (wp[0] - GLASS.cx) / 112;
          let gy = (wp[1] - 310) / 135;
          if (gx * gx + gy * gy < 0.88 && wp[1] < GLASS.baseY + 8) {
            if (pts.length > 2) brush.spline(pts, 0.35);
            pts = [];
          } else {
            let pressure = isInSpectralFan(wp[0], wp[1]) ? 0.65 : 1.0;
            pts.push([wp[0], wp[1], pressure]);
          }
        }
      }
      if (pts.length > 2) {
        brush.spline(pts, 0.35);
      }
    }
  }

  // 2D. Detailed concentric knot rings & radial shrinkage checks
  for (let k of KNOTS) {
    // Concentric elliptical growth rings inside each knot
    for (let ring = 1; ring <= 7; ring++) {
      let frac = ring / 7.0;
      let rx = k.coreR * 1.75 * frac;
      let ry = k.coreR * 0.92 * frac;
      let ringPts = [];
      for (let a = 0; a <= 360; a += 20) {
        let jitter = (noise(k.s + cos(a) * 2, k.t + sin(a) * 2, ring) - 0.5) * 3.5;
        let ds = cos(a) * (rx + jitter);
        let dt = sin(a) * (ry + jitter * 0.5);
        ringPts.push(tableToWorld(k.s + ds, k.t + dt));
      }
      brush.set("2B", ring <= 3 ? "#4a2810" : "#6e411f", map(ring, 1, 7, 0.85, 0.5));
      brush.spline(ringPts, 0.4);
    }

    // Dark radial star-checks (cracks) in the dry heartwood of the knot
    brush.set("micro_graphite", "#2e1808", 0.9);
    let numCracks = 5;
    for (let c = 0; c < numCracks; c++) {
      let ang = c * (360 / numCracks) + (k.s % 37);
      let len = k.coreR * random(0.75, 1.35);
      let p0 = tableToWorld(k.s + cos(ang) * 2, k.t + sin(ang) * 1.2);
      let p1 = tableToWorld(k.s + cos(ang + 8) * len * 0.5, k.t + sin(ang + 8) * len * 0.28);
      let p2 = tableToWorld(k.s + cos(ang - 5) * len, k.t + sin(ang - 5) * len * 0.52);
      brush.spline([p0, p1, p2], 0.25);
    }
  }

  // 2E. Quarter-sawn oak medullary rays (silky short flecks across the grain)
  for (let i = 0; i < 240; i++) {
    let s = random(-40, 1280);
    let t = random(15, 1050);
    let wp = tableToWorld(s, t);
    if (wp[0] < 0 || wp[0] > 1200 || wp[1] < 140 || wp[1] > 1200) continue;
    if (Math.hypot(wp[0] - GLASS.cx, wp[1] - 315) < 125) continue;

    let rayLen = random(10, 28);
    let p2 = tableToWorld(s + rayLen * 0.85, t + random(-4, 4));
    brush.set("cpencil", random() < 0.5 ? "#cfa068" : "#9c6734", random(0.4, 0.8));
    brush.line(wp[0], wp[1], p2[0], p2[1]);
  }

  // 2F. Plank seams and back table edge bevel
  for (let i = 0; i < PLANK_SEAMS.length - 1; i++) {
    let t = PLANK_SEAMS[i];
    let pStart = tableToWorld(-60, t);
    let pEnd = tableToWorld(1320, t);

    if (i === 0) {
      // Back edge of the table (broken across the glass tumbler so we can refract it cleanly)
      let xLeftGlass = GLASS.cx - GLASS.rimRx + 4;
      let xRightGlass = GLASS.cx + GLASS.rimRx - 4;

      brush.set("2B", "#523218", 0.95);
      brush.line(0, tableEdgeY(0), xLeftGlass, tableEdgeY(xLeftGlass));
      brush.line(xRightGlass, tableEdgeY(xRightGlass), 1200, tableEdgeY(1200));

      // Sunlit top bevel highlight along the oak table's back edge
      brush.set("cpencil", "#fff8e8", 0.9);
      brush.line(0, tableEdgeY(0) + 2.2, xLeftGlass, tableEdgeY(xLeftGlass) + 2.2);
      brush.line(xRightGlass, tableEdgeY(xRightGlass) + 2.2, 1200, tableEdgeY(1200) + 2.2);

      brush.set("HB", "#785332", 0.55);
      brush.line(0, tableEdgeY(0) + 4.5, xLeftGlass, tableEdgeY(xLeftGlass) + 4.5);
      brush.line(xRightGlass, tableEdgeY(xRightGlass) + 4.5, 1200, tableEdgeY(1200) + 4.5);
    } else {
      // Recessed plank joint line + warm sunlit lower lip
      let segPts1 = [];
      let segPts2 = [];
      for (let s = -40; s <= 1300; s += 35) {
        let wp = tableToWorld(s, t + (noise(s * 0.02, i) - 0.5) * 1.8);
        segPts1.push([wp[0], wp[1], 0.85]);
        segPts2.push([wp[0] + VX * 2.2, wp[1] + VY * 2.2, 0.75]);
      }
      brush.set("2B", "#4d2d14", 0.78);
      brush.spline(segPts1, 0.2);
      brush.set("cpencil", "#fae8c8", 0.75);
      brush.spline(segPts2, 0.2);
    }
  }

  // 2G. Old kitchen knife scars, gouges, and a faint antique cup ring on the oak
  let scars = [
    { s1: 420, t1: 310, s2: 590, t2: 395 },
    { s1: 445, t1: 300, s2: 575, t2: 375 },
    { s1: 610, t1: 480, s2: 760, t2: 430 },
    { s1: 710, t1: 640, s2: 890, t2: 710 },
    { s1: 120, t1: 360, s2: 280, t2: 425 },
    { s1: 155, t1: 350, s2: 265, t2: 440 },
    { s1: 230, t1: 680, s2: 410, t2: 635 },
    { s1: 820, t1: 260, s2: 980, t2: 315 },
    { s1: 520, t1: 810, s2: 690, t2: 865 }
  ];

  for (let sc of scars) {
    let p1 = tableToWorld(sc.s1, sc.t1);
    let p2 = tableToWorld(sc.s2, sc.t2);
    brush.set("micro_graphite", "#4a2c14", 0.8);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
    brush.set("cpencil", "#fff7e2", 0.65);
    brush.line(p1[0] + 1.2, p1[1] + 1.6, p2[0] + 1.2, p2[1] + 1.6);
  }

  // Subtle old tea-mug stain ring on the lower-left plank
  let ringCenter = tableToWorld(215, 620);
  brush.set("cpencil", "#b58350", 0.55);
  brush.arc(ringCenter[0], ringCenter[1], 68, 15, 295);
  brush.set("fine_graphite", "#8f6034", 0.38);
  brush.arc(ringCenter[0] + 2, ringCenter[1] + 1, 66, 40, 260);
}

