      v0: 0.475, v1: 0.680,
      cMain: "#169c66", cWarm: "#26b87c", cKnot: "#0e8052",
      alphaMain: 88, alphaSecond: 54
    },
    {
      name: "Ultramarine",
      v0: 0.640, v1: 0.845,
      cMain: "#1d52c4", cWarm: "#326ce3", cKnot: "#143da1",
      alphaMain: 86, alphaSecond: 52
    },
    {
      name: "Violet",
      v0: 0.805, v1: 1.000,
      cMain: "#632d99", cWarm: "#7d42b8", cKnot: "#4c1d7d",
      alphaMain: 84, alphaSecond: 50
    }
  ];

  // Pass 1: Primary clean wet-on-dry spectral ribbons fanning from glass to lower right
  brush.fillBleed(0.07, "out");
  brush.fillTexture(0.58, 0.52);

  for (let b of bands) {
    brush.fill(b.cMain, b.alphaMain);
    let edgeTop = [];
    let edgeBot = [];
    let steps = 16;
    for (let i = 0; i <= steps; i++) {
      let u = i / steps;
      let jitterTop = (noise(u * 4, b.v0 * 10) - 0.5) * 0.012;
      let jitterBot = (noise(u * 4, b.v1 * 10 + 5) - 0.5) * 0.012;
      edgeTop.push(fanPoint(u, b.v0 + jitterTop));
      edgeBot.unshift(fanPoint(u, b.v1 + jitterBot));
    }
    drawFilledShape(edgeTop.concat(edgeBot), 0.15);
  }

  // Pass 2: Secondary luminous glaze pass (shifted slightly inward/along the fan)
  // to build wet-on-dry richness and crisp overlap seams
  brush.fillBleed(0.05, "in");
  brush.fillTexture(0.65, 0.58);

  for (let b of bands) {
    brush.fill(b.cWarm, b.alphaSecond);
    let edgeTop = [];
    let edgeBot = [];
    let steps = 14;
    for (let i = 0; i <= steps; i++) {
      let u = lerp(0.03, 0.92, i / steps);
      let vA = lerp(b.v0, b.v1, 0.08);
      let vB = lerp(b.v0, b.v1, 0.92);
      edgeTop.push(fanPoint(u, vA));
      edgeBot.unshift(fanPoint(u, vB));
    }
    drawFilledShape(edgeTop.concat(edgeBot), 0.15);
  }

  // Pass 3: Overlapping wet-on-dry glaze petals where the spectral bands cross the oak knots!
  // This creates the exact optical & pigment pooling over the knots described in the directives.
  brush.fillBleed(0.09, "out");
  brush.fillTexture(0.7, 0.65);

  const knotGlazes = [
    // Knot 1 ~(615, 712): crossed by Cadmium Orange, Lemon Yellow, and Viridian
    { knot: KNOTS[0], color: "#f58216", alpha: 64, ds: -18, dt: -8, scale: 1.45 },
    { knot: KNOTS[0], color: "#fae02c", alpha: 70, ds: 6,   dt: 2,  scale: 1.55 },
    { knot: KNOTS[0], color: "#19a66c", alpha: 62, ds: 24,  dt: 12, scale: 1.40 },

    // Knot 2 ~(881, 717): crossed by Cadmium Red, Cadmium Orange, and Lemon Yellow
    { knot: KNOTS[1], color: "#de3821", alpha: 68, ds: -14, dt: -10, scale: 1.50 },
    { knot: KNOTS[1], color: "#f57c18", alpha: 64, ds: 12,  dt: 4,   scale: 1.55 },
    { knot: KNOTS[1], color: "#f7dc24", alpha: 60, ds: 28,  dt: 14,  scale: 1.35 },

    // Knot 3 ~(815, 986): crossed by Viridian, Ultramarine, and Violet
    { knot: KNOTS[2], color: "#18a16a", alpha: 62, ds: -16, dt: -10, scale: 1.45 },
    { knot: KNOTS[2], color: "#2159cc", alpha: 66, ds: 8,   dt: 2,   scale: 1.55 },
    { knot: KNOTS[2], color: "#6a30a3", alpha: 64, ds: 26,  dt: 14,  scale: 1.45 }
  ];

  for (let kg of knotGlazes) {
    brush.fill(kg.color, kg.alpha);
    let pts = [];
    let k = kg.knot;
    for (let a = 0; a < 360; a += 24) {
      let rMod = 1 + 0.15 * sin(a * 2 + k.s);
      let s = k.s + kg.ds + cos(a) * k.coreR * 1.9 * kg.scale * rMod;
      let t = k.t + kg.dt + sin(a) * k.coreR * 0.95 * kg.scale * rMod;
      pts.push(tableToWorld(s, t));
    }
    drawFilledShape(pts, 0.25);
  }

  // Intense near-field spectral flare right at the glass exit boundary (u = 0..0.18)
  brush.fillBleed(0.04, "in");
  for (let b of bands) {
    brush.fill(b.cMain, 72);
    let p0 = fanPoint(0.0, b.v0);
    let p1 = fanPoint(0.18, b.v0 + 0.01);
    let p2 = fanPoint(0.18, b.v1 - 0.01);
    let p3 = fanPoint(0.0, b.v1);
    drawFilledShape([p0, p1, p2, p3], 0.12);
  }

  brush.noFill();
}

// ============================================================================
// 5. OVERGLAZE KNOT DETAILS, CAUSTIC FILAMENTS & WOOD RE-INTEGRATION
// ============================================================================

function renderOakGrainAndCausticOverglaze() {
  // 5A. Re-establish crispness of the oak knots and wood pores *through* the spectral glazes
  // using colored pencil & fine graphite tinted by the local spectrum
  for (let k of KNOTS) {
    if (!k.inFan) continue;
    for (let ring = 1; ring <= 5; ring++) {
      let frac = ring / 5.0;
      let rx = k.coreR * 1.65 * frac;
      let ry = k.coreR * 0.88 * frac;
      let ringPts = [];
      for (let a = 0; a <= 360; a += 24) {
        let ds = cos(a) * rx;
        let dt = sin(a) * ry;
        ringPts.push(tableToWorld(k.s + ds, k.t + dt));
      }
      brush.set("fine_graphite", "#45220d", 0.65);
      brush.spline(ringPts, 0.4);
    }

    // Re-touch the central knot checks so they look sharply embedded beneath the glaze
    brush.set("micro_graphite", "#261206", 0.85);
    for (let c = 0; c < 4; c++) {
      let ang = c * 90 + 25;
      let p0 = tableToWorld(k.s, k.t);
      let p1 = tableToWorld(k.s + cos(ang) * k.coreR * 0.9, k.t + sin(ang) * k.coreR * 0.45);
      brush.line(p0[0], p0[1], p1[0], p1[1]);
    }
  }

  // 5B. Luminous optical caustic filaments & dispersion rays along the spectral fan
  const rayColors = [
    { v: 0.08, col: "#ff5c38" },
    { v: 0.18, col: "#ff8524" },
    { v: 0.28, col: "#ffae2b" },
    { v: 0.41, col: "#fff566" },
    { v: 0.50, col: "#78e08f" },
    { v: 0.59, col: "#26c988" },
    { v: 0.73, col: "#4285f4" },
    { v: 0.82, col: "#5c6bc0" },
    { v: 0.91, col: "#8e44ad" }
  ];

  for (let rc of rayColors) {
    for (let j = 0; j < 5; j++) {
      let uStart = random(0.01, 0.35);
      let uEnd = constrain(uStart + random(0.22, 0.48), 0.15, 0.96);
      let vOff = rc.v + random(-0.035, 0.035);
      let pts = [];
      for (let k = 0; k <= 6; k++) {
        let u = lerp(uStart, uEnd, k / 6);
        let p = fanPoint(u, vOff);
        pts.push([p[0], p[1], k === 3 ? 1.1 : 0.4]);
      }
      brush.set("caustic_filament", rc.col, random(0.55, 1.0));
      brush.spline(pts, 0.25);
    }
  }

  // 5C. Bright white-gold caustic cusp curves emerging from the tumbler base across the grain
  for (let i = 0; i < 14; i++) {
    let tNorm = i / 13.0;
    let pts = [];
    for (let step = 0; step <= 8; step++) {
      let sNorm = step / 8.0;
      let p = fanPoint(sNorm * 0.48, lerp(0.02, 0.95, tNorm));
      // Pull toward a nephroid caustic envelope curve
      let cuspPull = Math.sin(sNorm * 180) * (tNorm - 0.45) * 42;
      pts.push([p[0] - cuspPull * 0.4, p[1] + cuspPull * 0.6, 1.0 - sNorm * 0.6]);
    }
    brush.set("cpencil", "#fffdf0", map(i, 0, 13, 0.85, 0.5));
    brush.spline(pts, 0.35);
  }
}

// ============================================================================
// 6. THE WATER TUMBLER (REFRACTION, PRISM FLASHES, BUBBLES & FINE GRAPHITE)
// ============================================================================

function renderWaterTumbler() {
  const cx = GLASS.cx;

  // --------------------------------------------------------------------------
  // 6A. Translucent Watercolor Washes Inside the Glass & Water Column
  // --------------------------------------------------------------------------
  brush.noStroke();
  brush.fillBleed(0.06, "in");
  brush.fillTexture(0.45, 0.35);

  // Subtle cool-warm water clarity wash (clean paper preserved on the sunlit left side)
  brush.fill("#e8f2f0", 46);
  drawFilledShape([
    [cx - GLASS.waterRx + 4, GLASS.waterY],
    [cx + GLASS.waterRx - 4, GLASS.waterY],
    [cx + GLASS.shamTopRx - 4, GLASS.shamTopY],
    [cx - GLASS.shamTopRx + 4, GLASS.shamTopY]
  ], 0.08);

  // Refracted warm oak tone inside the upper half of the water cylinder
  // (Cylindrical water lens inverts the horizontal slope of the table edge!)
  brush.fill("#d9aa72", 52);
  drawFilledShape([
    [cx - GLASS.waterRx + 10, GLASS.waterY + 18],
    [cx + GLASS.waterRx - 10, GLASS.waterY + 12],
    [cx + GLASS.waterRx - 14, 342],
    [cx, 326],
    [cx - GLASS.waterRx + 12, 298]
  ], 0.2);

  // Refracted sunlit cream wall tone in the lower-left portion of the water lens
  brush.fill("#fff8e3", 68);
  drawFilledShape([
    [cx - GLASS.waterRx + 12, 300],
    [cx + 15, 328],
    [cx + GLASS.shamTopRx - 16, GLASS.shamTopY - 8],
    [cx - GLASS.shamTopRx + 10, GLASS.shamTopY - 8]
  ], 0.18);

  // Soda-lime aqua-green glass tint in the thick heavy glass bottom (sham)
  brush.fill("#b8d8cc", 68);
  let shamPts = [];
  for (let a = 0; a <= 180; a += 15) {
    shamPts.push([cx + cos(a) * GLASS.shamTopRx, GLASS.shamTopY + sin(a) * GLASS.shamTopRy]);
  }
  for (let a = 180; a >= 0; a -= 15) {
    shamPts.push([cx + cos(a) * GLASS.baseRx, GLASS.baseY + sin(a) * GLASS.baseRy]);
  }
  drawFilledShape(shamPts, 0.15);

  // Deep internal reflection crescents in the heavy glass base & meniscus
  brush.fill("#5e7073", 64);
  drawFilledShape([
    [cx - GLASS.baseRx + 8, GLASS.baseY - 4],
    [cx - 18, GLASS.baseY + GLASS.baseRy - 4],
    [cx + 42, GLASS.baseY + GLASS.baseRy - 6],
    [cx - 25, GLASS.shamTopY + 16]
  ], 0.25);

  // Incipient prism flashes inside the glass rim, meniscus, and right wall
  // showing where the sunlight splits before spilling onto the table
  const internalPrisms = [
    { x: cx + GLASS.waterRx - 14, y: GLASS.waterY + 6, r: 16, col: "#e63922", a: 85 },
    { x: cx + GLASS.waterRx - 10, y: GLASS.waterY + 18, r: 15, col: "#f7941d", a: 82 },
    { x: cx + GLASS.waterRx - 8,  y: GLASS.waterY + 30, r: 15, col: "#faeb30", a: 88 },
    { x: cx + GLASS.shamTopRx - 12, y: GLASS.shamTopY - 6, r: 18, col: "#e63922", a: 88 },
    { x: cx + GLASS.shamTopRx - 16, y: GLASS.shamTopY + 6, r: 18, col: "#f7d41d", a: 88 },
    { x: cx + GLASS.baseRx - 20, y: GLASS.baseY - 4, r: 18, col: "#17a368", a: 84 },
    { x: cx + GLASS.baseRx - 34, y: GLASS.baseY + 8, r: 18, col: "#1f57c9", a: 84 },
    { x: cx + GLASS.baseRx - 50, y: GLASS.baseY + 15, r: 16, col: "#662d96", a: 80 },
    // Small spectral touch on the left sunlit rim
    { x: cx - GLASS.rimRx + 18, y: GLASS.rimY + 12, r: 11, col: "#f7941d", a: 72 },
    { x: cx - GLASS.rimRx + 28, y: GLASS.rimY + 18, r: 11, col: "#2462d1", a: 68 }
  ];

  brush.fillBleed(0.05, "out");
  for (let ip of internalPrisms) {
    brush.fill(ip.col, ip.a);
    brush.circle(ip.x, ip.y, ip.r, 0.2);
  }
  brush.noFill();

  // --------------------------------------------------------------------------
  // 6B. Refracted Table Edge & Distorted Wood Grain Inside the Water Column
  // --------------------------------------------------------------------------
  // Outside the glass, the table edge slopes UP-RIGHT from (195, 344) to (425, 296).
  // Inside the cylindrical water lens, optical refraction bends and INVERTS this line
  // into a crisp S-curved lens horizon from ~(210, 296) down-right to ~(405, 344)!
  let refEdgePts = [
    [cx - 101, 338, 0.9],
    [cx - 92,  298, 1.0],
    [cx - 55,  304, 0.85],
    [cx,       322, 0.95],
    [cx + 55,  338, 0.9],
    [cx + 88,  340, 1.0],
    [cx + 98,  302, 0.85]
  ];
  brush.set("HB", "#3a2818", 0.9);
  brush.spline(refEdgePts, 0.35);

  // Secondary chromatic/meniscus double-refraction line just below the primary refracted edge
  let refEdgePts2 = refEdgePts.map(p => [p[0], p[1] + 4.2, p[2] * 0.75]);
  brush.set("fine_graphite", "#6b4c30", 0.65);
  brush.spline(refEdgePts2, 0.35);

  // Sunlit highlight hugging the refracted table bevel inside the water
  let refEdgeHi = refEdgePts.map(p => [p[0], p[1] + 2.0, p[2] * 0.8]);
  brush.set("cpencil", "#fff9e6", 0.85);
  brush.spline(refEdgeHi, 0.35);

  // Refracted & magnified oak grain curves above/around the refracted table edge inside the water
  for (let g = 0; g < 9; g++) {
    let yOffset = map(g, 0, 8, -42, 36);
    let gPts = [];
    for (let i = 0; i < refEdgePts.length; i++) {
      let p = refEdgePts[i];
      let lensMag = Math.sin((i / (refEdgePts.length - 1)) * 180) * 9.0;
      let gy = p[1] + yOffset + (yOffset < 0 ? -lensMag : lensMag * 0.6);
      if (gy > GLASS.waterY + 12 && gy < GLASS.shamTopY - 12) {
        gPts.push([p[0] * 0.96 + cx * 0.04, gy, 0.6]);
      }
    }
    if (gPts.length > 2) {
      brush.set("fine_graphite", yOffset < 0 ? "#7a5432" : "#9c7a54", 0.52);
      brush.spline(gPts, 0.35);
    }
  }

  // Also faintly refract the table edge in the dry upper glass zone (above the water meniscus)
  // where only the thin cylindrical glass walls deflect it slightly
  brush.set("2H", "#8c7355", 0.45);
  brush.line(cx - GLASS.rimRx + 3, 343, cx - GLASS.rimRx + 11, 338);
  brush.line(cx + GLASS.rimRx - 11, 300, cx + GLASS.rimRx - 3, 297);

  // --------------------------------------------------------------------------
  // 6C. Precision Graphite Architecture of Rim, Meniscus, Walls & Sham Base
  // --------------------------------------------------------------------------

  // Helper to draw an elliptical glass ring with modulated pencil weight & pressure
  function drawEllipticalRing(cy, rx, ry, brushName, col, baseWeight, startAng = 0, endAng = 360) {
    let pts = [];
    for (let a = startAng; a <= endAng; a += 10) {
      let x = cx + cos(a) * rx;
      let y = cy + sin(a) * ry;
      // Modulate pressure: sharper/heavier on the front & shadow curves, delicate in direct glare
      let p = 0.55 + 0.45 * Math.sin((a - 25) * (Math.PI / 180));
      pts.push([x, y, constrain(p, 0.25, 1.15)]);
    }
    brush.set(brushName, col, baseWeight);
    brush.spline(pts, 0.4);
  }

  // 1. TOP GLASS RIM (outer lip, inner lip, and fine rim thickness)
  drawEllipticalRing(GLASS.rimY, GLASS.rimRx, GLASS.rimRy, "HB", "#2b2623", 0.85, 0, 360);
  drawEllipticalRing(GLASS.rimY + 1.5, GLASS.rimRx - 4.8, GLASS.rimRy - 2.2, "fine_graphite", "#453e38", 0.75, 0, 360);
  drawEllipticalRing(GLASS.rimY - 1.2, GLASS.rimRx - 2.2, GLASS.rimRy - 1.0, "2H", "#7a7268", 0.5, 15, 195);

  // Brilliant specular rim highlights on the top lip
  drawEllipticalRing(GLASS.rimY, GLASS.rimRx - 2.0, GLASS.rimRy - 0.8, "cpencil", "#ffffff", 1.15, 115, 235);
  drawEllipticalRing(GLASS.rimY + 1.2, GLASS.rimRx - 3.5, GLASS.rimRy - 1.5, "cpencil", "#fffef5", 0.95, 310, 45);

  // 2. WATER MENISCUS (surface ellipse + concave capillary climb up the inner glass wall)
  drawEllipticalRing(GLASS.waterY, GLASS.waterRx, GLASS.waterRy, "HB", "#302c28", 0.8, 0, 360);
  drawEllipticalRing(GLASS.waterY + 3.8, GLASS.waterRx - 3.2, GLASS.waterRy - 1.6, "fine_graphite", "#524c44", 0.65, 0, 180);
  drawEllipticalRing(GLASS.waterY - 2.5, GLASS.waterRx - 1.5, GLASS.waterRy - 0.8, "2H", "#6e675f", 0.5, 180, 360);

  // Meniscus bright reflection arcs
  drawEllipticalRing(GLASS.waterY + 1.8, GLASS.waterRx - 2.0, GLASS.waterRy - 0.8, "cpencil", "#ffffff", 1.1, 125, 220);
  drawEllipticalRing(GLASS.waterY - 1.0, GLASS.waterRx - 4.0, GLASS.waterRy - 1.5, "cpencil", "#fff9e6", 0.85, 325, 40);

  // 3. HEAVY SOLID GLASS BASE (sham top water floor & bottom table contact ellipse)
  drawEllipticalRing(GLASS.shamTopY, GLASS.shamTopRx, GLASS.shamTopRy, "HB", "#332e2a", 0.78, 0, 360);
  drawEllipticalRing(GLASS.shamTopY + 5, GLASS.shamTopRx - 5, GLASS.shamTopRy - 2.5, "2B", "#211e1b", 0.85, 10, 170);
  drawEllipticalRing(GLASS.shamTopY - 4, GLASS.shamTopRx - 7, GLASS.shamTopRy - 3.0, "fine_graphite", "#5c554e", 0.6, 190, 350);

  drawEllipticalRing(GLASS.baseY, GLASS.baseRx, GLASS.baseRy, "2B", "#1f1b18", 0.95, 0, 185);
  drawEllipticalRing(GLASS.baseY, GLASS.baseRx, GLASS.baseRy, "fine_graphite", "#59524b", 0.6, 185, 360);
  drawEllipticalRing(GLASS.baseY - 6, GLASS.baseRx - 6, GLASS.baseRy - 3, "HB", "#38322e", 0.75, 0, 360);

  // Internal distortion loops inside the thick glass sham
  drawEllipticalRing(GLASS.baseY - 14, GLASS.baseRx - 14, GLASS.baseRy - 8, "2B", "#2b2622", 0.8, 15, 165);
  drawEllipticalRing(GLASS.baseY - 18, GLASS.baseRx - 22, GLASS.baseRy - 12, "cpencil", "#ffffff", 1.15, 130, 235);
  drawEllipticalRing(GLASS.baseY - 10, GLASS.baseRx - 10, GLASS.baseRy - 5, "cpencil", "#fff6d6", 0.95, 315, 55);

  // 4. LEFT & RIGHT GLASS WALL CONTOURS (Outer & inner wall thickness)
  // Left outer wall (sunlit edge)
  brush.set("HB", "#2e2925", 0.85);
  brush.line(cx - GLASS.rimRx, GLASS.rimY, cx - GLASS.baseRx, GLASS.baseY);
  // Left inner wall thickness
  brush.set("fine_graphite", "#5c534a", 0.6);
  brush.line(cx - GLASS.rimRx + 5.5, GLASS.rimY + 4, cx - GLASS.shamTopRx + 5.0, GLASS.shamTopY);

  // Right outer wall (exit side where spectrum emerges)
  brush.set("HB", "#292420", 0.9);
  brush.line(cx + GLASS.rimRx, GLASS.rimY, cx + GLASS.baseRx, GLASS.baseY);
  // Right inner wall thickness
  brush.set("fine_graphite", "#4f473f", 0.65);
  brush.line(cx + GLASS.rimRx - 5.5, GLASS.rimY + 4, cx + GLASS.shamTopRx - 5.0, GLASS.shamTopY);

  // Vertical cylindrical specular highlight columns & graphite shadow striations
  for (let k = 0; k < 7; k++) {
    let yTop = GLASS.rimY + 22 + k * 4;
    let yBot = GLASS.shamTopY - 14 + (k % 3) * 4;
    let xOffTop = -GLASS.rimRx + 14 + k * 3.2;
    let xOffBot = -GLASS.shamTopRx + 12 + k * 2.8;
    brush.set("cpencil", k < 4 ? "#ffffff" : "#fff9e6", map(k, 0, 6, 1.15, 0.65));
    brush.line(cx + xOffTop, yTop, cx + xOffBot, yBot);
  }

  // Secondary vertical reflection ribbon near the right wall
  for (let k = 0; k < 4; k++) {
    let xOffTop = GLASS.rimRx - 18 - k * 2.8;
    let xOffBot = GLASS.shamTopRx - 16 - k * 2.4;
    brush.set("cpencil", "#fffcf0", 0.8);
    brush.line(cx + xOffTop, GLASS.rimY + 28, cx + xOffBot, GLASS.shamTopY - 12);
  }

  // Fine vertical graphite shading ribs along the dark glass wall bands
  for (let k = 0; k < 9; k++) {
    let frac = k / 8.0;
    let xTopL = cx - GLASS.rimRx + 6 + frac * 7;
    let xBotL = cx - GLASS.shamTopRx + 5 + frac * 6;
    brush.set("micro_graphite", "#3d3630", 0.55);
    brush.line(xTopL, GLASS.rimY + 18, xBotL, GLASS.shamTopY - 6);

    let xTopR = cx + GLASS.rimRx - 6 - frac * 8;
    let xBotR = cx + GLASS.shamTopRx - 5 - frac * 7;
    brush.set("micro_graphite", "#362f2a", 0.6);
    brush.line(xTopR, GLASS.rimY + 18, xBotR, GLASS.shamTopY - 6);
  }

  // --------------------------------------------------------------------------
  // 6D. Tiny Bubbles Clinging Inside the Water & Meniscus (Hyperrealist Study)
  // --------------------------------------------------------------------------
  // Generate organic clusters of nucleation bubbles on the inner glass wall:
  // - Dense cluster along the sunlit left curve
  // - Scattered rising trails in the middle water column
  // - Micro-bubble pearl necklace clinging to the water meniscus & sham floor
  let bubbles = [];

  // 1. Clinging to the inner water wall
  for (let i = 0; i < 95; i++) {
    let y = random(GLASS.waterY + 14, GLASS.shamTopY - 10);
    let rad = glassRadiusAtY(y);
    // Bias bubbles slightly toward the sunlit left side and lower half of the glass
    let ang = random() < 0.62 ? random(105, 245) : random(-55, 95);
    let rSpread = random(0.42, 0.92);
    let bx = cx + cos(ang) * rad.rx * rSpread;
    let by = y + sin(ang) * rad.ry * 0.35;
    let br = random() < 0.18 ? random(3.2, 5.4) : random(1.1, 2.9);
    bubbles.push({ x: bx, y: by, r: br });
  }

  // 2. Rising vertical micro-bubble chains
  let chains = [
    { xOff: -48, yStart: 382, count: 9 },
    { xOff: -18, yStart: 388, count: 7 },
    { xOff: 34,  yStart: 376, count: 8 },
    { xOff: 62,  yStart: 368, count: 6 }
  ];
  for (let ch of chains) {
    for (let j = 0; j < ch.count; j++) {
      let by = ch.yStart - j * random(11, 16);
      if (by > GLASS.waterY + 10) {
        let bx = cx + ch.xOff + sin(j * 45) * 2.5;
        let br = map(j, 0, ch.count, 1.3, 3.6);
        bubbles.push({ x: bx, y: by, r: br });
      }
    }
  }

  // 3. Meniscus rim micro-bubbles
  for (let a = 15; a < 345; a += random(8, 18)) {
    let bx = cx + cos(a) * (GLASS.waterRx - 4.5);
    let by = GLASS.waterY + sin(a) * (GLASS.waterRy - 2.0);
    bubbles.push({ x: bx, y: by, r: random(1.0, 2.4) });
  }

  // Render each bubble with optical precision:
  // Dark total-internal-reflection ring in fine graphite + bright pinpoint highlight facing the sun
  for (let b of bubbles) {
    if (b.r > 2.2) {
      // Crisp graphite outer crescent on lower-right
      brush.set("micro_graphite", "#2b2622", 0.78);
      brush.arc(b.x, b.y, b.r, 320, 175);

      // Soft upper-left graphite rim
      brush.set("2H", "#665e54", 0.5);
      brush.arc(b.x, b.y, b.r, 175, 320);

      // Internal dark refraction core on light-facing side (air-in-water optics)
      brush.set("micro_graphite", "#3d3630", 0.65);
      brush.arc(b.x - b.r * 0.2, b.y - b.r * 0.2, b.r * 0.55, 140, 300);

      // Brilliant white specular pinpoint on the upper-left
      brush.set("cpencil", "#ffffff", 1.05);
      brush.line(b.x - b.r * 0.38, b.y - b.r * 0.38, b.x - b.r * 0.12, b.y - b.r * 0.45);
    } else {
      // Microscopic nucleation pearl
      brush.set("micro_graphite", "#38312b", 0.65);
      brush.circle(b.x, b.y, b.r, 0.1);
      brush.set("cpencil", "#ffffff", 0.85);
      brush.line(b.x - 0.6, b.y - 0.6, b.x + 0.1, b.y - 0.8);
    }
  }
}

