// ============================================================================
// HELPER FUNCTIONS FOR GEOMETRY & WATERCOLOR SHAPES
// ============================================================================

function drawPolyShape(pts, curvature = 0.35, closed = true) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closed ? CLOSE : undefined);
}

// Evaluates point and local frame on a cashew (boteh) in natural coordinates:
// t in [0, 1] (0 = bulbous basal head, 1 = curled distal boteh tip)
// v in [-1, 1] (-1 = concave inner belly / cleft, +1 = convex outer back)
function evalCashew(nut, t, v) {
  t = constrain(t, 0.001, 0.999);
  const L = nut.L;
  const flip = nut.flip;
  const curl = nut.curl;
  const plump = nut.plump;

  // Cubic Bezier spine control points (normalized by L)
  const p0x = -0.66, p0y = 0.21 * flip;
  const p1x = -0.61, p1y = -0.58 * flip;
  const p2x = 0.59,  p2y = -0.49 * flip;
  const p3x = 0.52 - 0.09 * curl, p3y = (0.30 + 0.11 * curl) * flip;

  const mt = 1 - t;
  const mt2 = mt * mt;
  const t2 = t * t;

  // Spine position
  const sx = (mt2 * mt * p0x + 3 * mt2 * t * p1x + 3 * mt * t2 * p2x + t2 * t * p3x) * L;
  const sy = (mt2 * mt * p0y + 3 * mt2 * t * p1y + 3 * mt * t2 * p2y + t2 * t * p3y) * L;

  // Spine derivative (tangent)
  const dx = 3 * mt2 * (p1x - p0x) + 6 * mt * t * (p2x - p1x) + 3 * t2 * (p3x - p2x);
  const dy = 3 * mt2 * (p1y - p0y) + 6 * mt * t * (p2y - p1y) + 3 * t2 * (p3y - p2y);
  const dLen = Math.hypot(dx, dy) || 1e-6;
  const tx = dx / dLen;
  const ty = dy / dLen;

  // Unit normal pointing toward the convex outer back (v > 0)
  const nx = ty * flip;
  const ny = -tx * flip;

  // Smooth rounded cap envelope at head (t=0) and tip (t=1)
  const sVal = Math.max(0, sin(t * 180));
  const env = Math.pow(sVal, 0.54);

  // Outer convex back width profile
  const wOuter = L * plump * env * (0.37 - 0.11 * t + 0.045 * sin(t * 180));

  // Inner concave belly width profile with characteristic umbilical pinch at t ~ 0.47
  const pinch = 0.185 * Math.exp(-Math.pow((t - 0.47) / 0.155, 2));
  const headLobe = 0.075 * Math.exp(-Math.pow((t - 0.17) / 0.14, 2));
  const tailLobe = 0.025 * Math.exp(-Math.pow((t - 0.78) / 0.12, 2));
  const wInner = L * plump * env * Math.max(0.06, 0.33 - 0.13 * t + headLobe + tailLobe - pinch);

  // Slight organic asymmetry from noise
  const nWobble = (noise(nut.seed + t * 3.2, (v + 1) * 1.7) - 0.5) * L * 0.035 * env;

  const r = (v >= 0 ? v * wOuter : v * wInner) + nWobble;

  // Slight end-cap rounding extension along tangent at very poles
  const capPush = L * 0.03 * (t < 0.08 ? -Math.pow(1 - t / 0.08, 2) : (t > 0.92 ? Math.pow((t - 0.92) / 0.08, 2) : 0));

  const lx = sx + nx * r + tx * capPush;
  const ly = sy + ny * r + ty * capPush;

  const ca = cos(nut.angle);
  const sa = sin(nut.angle);

  return [
    nut.x + lx * ca - ly * sa,
    nut.y + lx * sa + ly * ca
  ];
}

// Builds a closed polygon inside a cashew over a (tMin..tMax, vMin..vMax) domain
function buildCashewPatch(nut, tMin, tMax, vMin, vMax, stepsT = 10, offsetX = 0, offsetY = 0) {
  const pts = [];
  // Forward along vMax (outer side of patch)
  for (let i = 0; i <= stepsT; i++) {
    const u = i / stepsT;
    const t = lerp(tMin, tMax, u);
    // Taper v slightly at ends of sub-patches for smooth organic teardrop shapes
    const endTap = (tMin > 0.02 || tMax < 0.98) ? Math.pow(sin(u * 180), 0.35) : 1.0;
    const vMid = 0.5 * (vMin + vMax);
    const vCur = lerp(vMid, vMax, endTap);
    const p = evalCashew(nut, t, vCur);
    pts.push([p[0] + offsetX, p[1] + offsetY]);
  }
  // Backward along vMin (inner side of patch)
  for (let i = stepsT - 1; i >= 1; i--) {
    const u = i / stepsT;
    const t = lerp(tMin, tMax, u);
    const endTap = (tMin > 0.02 || tMax < 0.98) ? Math.pow(sin(u * 180), 0.35) : 1.0;
    const vMid = 0.5 * (vMin + vMax);
    const vCur = lerp(vMid, vMin, endTap);
    const p = evalCashew(nut, t, vCur);
    pts.push([p[0] + offsetX, p[1] + offsetY]);
  }
  return pts;
}

// Full silhouette contour of a cashew
function buildCashewSilhouette(nut, steps = 12, offsetX = 0, offsetY = 0, scaleMul = 1.0) {
  const pts = [];
  const savedL = nut.L;
  nut.L = savedL * scaleMul;
  for (let i = 0; i <= steps; i++) {
    const t = map(i, 0, steps, 0.01, 0.99);
    const p = evalCashew(nut, t, 1.0);
    pts.push([p[0] + offsetX, p[1] + offsetY]);
  }
  for (let i = steps - 1; i >= 1; i--) {
    const t = map(i, 0, steps, 0.01, 0.99);
    const p = evalCashew(nut, t, -1.0);
    pts.push([p[0] + offsetX, p[1] + offsetY]);
  }
  nut.L = savedL;
  return pts;
}

// ============================================================================
// STAGE 1: SAFFRON-DYED COTTON CLOTH & WOVEN PAISLEY WET-IN-WET BLEEDS
// ============================================================================

function drawSaffronCloth(hollowX, hollowY) {
  brush.noField();
  brush.noStroke();
  brush.noHatch();

  // 1. Warm damp cotton base washes with wet-in-wet outer bleeds
  const clothWashes = [
    // Outer luminous golden-turmeric bleed clouds near edges
    { x: 580, y: 580, rx: 560, ry: 550, col: "#ffbe2e", op: 85, bleed: 0.48, tex: 0.65, seed: 10 },
    { x: 550, y: 570, rx: 510, ry: 500, col: "#f79d07", op: 95, bleed: 0.44, tex: 0.72, seed: 20 },
    // Vivid saturated saffron core
    { x: 540, y: 565, rx: 450, ry: 440, col: "#eb7800", op: 105, bleed: 0.38, tex: 0.76, seed: 30 },
    // Deep marigold & spice-orange cloth richness
    { x: 525, y: 565, rx: 360, ry: 350, col: "#d95300", op: 90, bleed: 0.35, tex: 0.78, seed: 40 },
    // Off-centre hollow deep saffron-madder shadow well
    { x: hollowX, y: hollowY, rx: 145, ry: 135, col: "#9c2804", op: 115, bleed: 0.32, tex: 0.82, seed: 50 },
    { x: hollowX + 8, y: hollowY + 6, rx: 92, ry: 86, col: "#6b1702", op: 120, bleed: 0.25, tex: 0.85, seed: 60 }
  ];

  for (let w of clothWashes) {
    const pts = [];
    const nPts = 18;
    for (let i = 0; i < nPts; i++) {
      const a = (i / nPts) * 360;
      const n = noise(w.seed + cos(a) * 1.4, w.seed + sin(a) * 1.4);
      const radX = w.rx * (0.82 + 0.34 * n);
      const radY = w.ry * (0.82 + 0.34 * n);
      pts.push([w.x + cos(a) * radX, w.y + sin(a) * radY]);
    }
    brush.fill(w.col, w.op);
    brush.fillBleed(w.bleed, "out");
    brush.fillTexture(w.tex, 0.58);
    drawPolyShape(pts, 0.45, true);
  }

  // 2. Wet-in-wet peripheral blooms & cauliflower water-edge bleeds at canvas borders
  const edgeBlooms = [
    { x: 140, y: 150, r: 170, col: "#ffaa00", op: 75, bleed: 0.5 },
    { x: 1050, y: 140, r: 185, col: "#f07c00", op: 70, bleed: 0.5 },
    { x: 1060, y: 1040, r: 195, col: "#e66000", op: 80, bleed: 0.5 },
    { x: 135, y: 1030, r: 175, col: "#ff9900", op: 72, bleed: 0.5 },
    { x: 600, y: 85, r: 150, col: "#ffb71c", op: 65, bleed: 0.48 },
    { x: 85, y: 580, r: 155, col: "#f28500", op: 68, bleed: 0.48 },
    { x: 1110, y: 590, r: 155, col: "#d94e04", op: 68, bleed: 0.48 },
    { x: 610, y: 1110, r: 150, col: "#e86800", op: 70, bleed: 0.48 }
  ];

  for (let i = 0; i < edgeBlooms.length; i++) {
    const b = edgeBlooms[i];
    const pts = [];
    for (let k = 0; k < 14; k++) {
      const a = (k / 14) * 360;
      const rr = b.r * (0.65 + 0.65 * noise(i * 13 + cos(a) * 1.8, sin(a) * 1.8));
      pts.push([b.x + cos(a) * rr, b.y + sin(a) * rr]);
    }
    brush.fill(b.col, b.op);
    brush.fillBleed(b.bleed, "out");
    brush.fillTexture(0.82, 0.72);
    drawPolyShape(pts, 0.45, true);
  }
  brush.noFill();

  // 3. Soft radial fabric folds draping into the off-centre hollow
  const foldAngles = [-155, -105, -42, 18, 72, 132, 168];
  for (let i = 0; i < foldAngles.length; i++) {
    const baseA = foldAngles[i];
    const len = 540;
    // Shadow trough of fold
    const foldPts = [];
    for (let s = 0; s <= 10; s++) {
      const u = s / 10;
      const d = lerp(45, len, u);
      const wave = sin(u * 180) * 28 * (i % 2 === 0 ? 1 : -1);
      const a = baseA + wave * 0.18;
      const w = lerp(14, 52, u);
      const px = hollowX + cos(a) * d;
      const py = hollowY + sin(a) * d;
      const nx = -sin(a);
      const ny = cos(a);
      foldPts.push([px + nx * w, py + ny * w]);
    }
    for (let s = 10; s >= 0; s--) {
      const u = s / 10;
      const d = lerp(45, len, u);
      const wave = sin(u * 180) * 28 * (i % 2 === 0 ? 1 : -1);
      const a = baseA + wave * 0.18;
      const px = hollowX + cos(a) * d;
      const py = hollowY + sin(a) * d;
      foldPts.push([px, py]);
    }
    brush.noStroke();
    brush.fill(i % 2 === 0 ? "#b83604" : "#cc4402", 42);
    brush.fillBleed(0.35, "out");
    brush.fillTexture(0.65, 0.4);
    drawPolyShape(foldPts, 0.4, true);
    brush.noFill();

    // Luminous saffron-gold highlight crest alongside the fold
    const crestPts = [];
    for (let s = 0; s <= 8; s++) {
      const u = s / 8;
      const d = lerp(55, len * 0.92, u);
      const wave = sin(u * 180) * 28 * (i % 2 === 0 ? 1 : -1);
      const a = baseA + wave * 0.18 - 4;
      crestPts.push([hollowX + cos(a) * d, hollowY + sin(a) * d, 0.4 + 0.6 * sin(u * 180)]);
    }
    brush.set("glaze_wide", "#ffd147", 1.8);
    brush.spline(crestPts, 0.45);
  }

  // 4. Woven cotton warp & weft threads (fading softly into the wet-in-wet margins)
  const threadColors = ["#d95b00", "#f59c00", "#a82903", "#ffe082"];
  for (let c = 0; c < threadColors.length; c++) {
    brush.set("weave_thread", threadColors[c], 0.9);
    const count = 95;
    for (let i = 0; i < count; i++) {
      // Horizontal weft segment
      const y = random(55, 1145);
      const x1 = random(45, 960);
      const segLen = random(90, 240);
      const x2 = min(1155, x1 + segLen);
      const distEdge = min(min(x1, 1200 - x2), min(y, 1200 - y));
      if (distEdge > 35 || random() < 0.45) {
        brush.line(x1, y + random(-1.5, 1.5), x2, y + random(-1.5, 1.5));
      }
      // Vertical warp segment
      const x = random(55, 1145);
      const y1 = random(45, 960);
      const vLen = random(90, 240);
      const y2 = min(1155, y1 + vLen);
      const distEdgeV = min(min(x, 1200 - x), min(y1, 1200 - y2));
      if (distEdgeV > 35 || random() < 0.45) {
        brush.line(x + random(-1.5, 1.5), y1, x + random(-1.5, 1.5), y2);
      }
    }
  }

  // 5. The Cloth's Woven Paisley (Boteh) Print — crisp in mid-cloth, bleeding wet-in-wet at edges
  const clothMotifs = [
    // Outer corner & border paisley motifs (dissolving into wet-in-wet bleeds)
    { x: 145, y: 165, L: 95, angle: 42, flip: 1, bleedAmt: 0.45, alphaMul: 0.78 },
    { x: 340, y: 105, L: 74, angle: 12, flip: -1, bleedAmt: 0.38, alphaMul: 0.85 },
    { x: 865, y: 110, L: 82, angle: -22, flip: 1, bleedAmt: 0.40, alphaMul: 0.82 },
    { x: 1055, y: 195, L: 96, angle: 128, flip: -1, bleedAmt: 0.46, alphaMul: 0.76 },
    { x: 1085, y: 440, L: 76, angle: 85, flip: 1, bleedAmt: 0.38, alphaMul: 0.82 },
    { x: 1075, y: 830, L: 84, angle: 145, flip: -1, bleedAmt: 0.42, alphaMul: 0.80 },
    { x: 1020, y: 1045, L: 98, angle: -135, flip: 1, bleedAmt: 0.48, alphaMul: 0.74 },
    { x: 750, y: 1090, L: 78, angle: -170, flip: -1, bleedAmt: 0.40, alphaMul: 0.82 },
    { x: 350, y: 1085, L: 82, angle: 165, flip: 1, bleedAmt: 0.42, alphaMul: 0.80 },
    { x: 145, y: 1015, L: 94, angle: -48, flip: -1, bleedAmt: 0.46, alphaMul: 0.76 },
    { x: 105, y: 740, L: 78, angle: -82, flip: 1, bleedAmt: 0.38, alphaMul: 0.82 },
    { x: 110, y: 420, L: 75, angle: -18, flip: -1, bleedAmt: 0.38, alphaMul: 0.84 },
    // Partially visible cloth paisley inside the central hollow
    { x: hollowX - 12, y: hollowY + 8, L: 58, angle: 28, flip: 1, bleedAmt: 0.16, alphaMul: 0.92 }
  ];

  for (let m of clothMotifs) {
    drawClothPaisleyMotif(m);
  }

  // 6. Delicate watercolor water-marks & pigment granulation rings near outer borders
  for (let i = 0; i < 18; i++) {
    const a = (i / 18) * 360 + random(-8, 8);
    const dist = random(490, 575);
    const bx = 600 + cos(a) * dist;
    const by = 600 + sin(a) * dist;
    const rad = random(28, 72);
    brush.set("glaze_detail", i % 2 === 0 ? "#d44d00" : "#f08c00", 0.7);
    brush.arc(bx, by, rad, a + 90, a + 270);
  }
}

// Draws an ornate woven/dyed paisley boteh motif on the saffron cloth
function drawClothPaisleyMotif(m) {
  const dummyNut = {
    x: m.x,
    y: m.y,
    L: m.L,
    angle: m.angle,
    flip: m.flip,
    plump: 1.05,
    curl: 1.35,
    seed: m.x * 0.13 + m.y * 0.29
  };

  // Wet-in-wet madder crimson & deep saffron dyed base of the cloth boteh
  const outerPts = buildCashewSilhouette(dummyNut, 14, 0, 0, 1.0);
  brush.noStroke();
  brush.fill("#a61c04", 62 * m.alphaMul);
  brush.fillBleed(m.bleedAmt, "out");
  brush.fillTexture(0.75, 0.65);
  drawPolyShape(outerPts, 0.4, true);

  // Inner golden-turmeric reserve inside the cloth boteh
  const innerPts = buildCashewPatch(dummyNut, 0.10, 0.86, -0.58, 0.58, 10);
  brush.fill("#ffba24", 58 * m.alphaMul);
  brush.fillBleed(m.bleedAmt * 0.7, "out");
  brush.fillTexture(0.65, 0.5);
  drawPolyShape(innerPts, 0.4, true);
  brush.noFill();

  // Woven paisley scroll outline & scalloped double-border
  brush.set("glaze_detail", "#781102", 0.85);
  const spinePts = [];
  for (let i = 0; i <= 14; i++) {
    const t = map(i, 0, 14, 0.04, 0.96);
    const p = evalCashew(dummyNut, t, 0.95);
    spinePts.push([p[0], p[1], 0.6]);
  }
  brush.spline(spinePts, 0.4);

  const bellyPts = [];
  for (let i = 0; i <= 14; i++) {
    const t = map(i, 0, 14, 0.04, 0.96);
    const p = evalCashew(dummyNut, t, -0.95);
    bellyPts.push([p[0], p[1], 0.6]);
  }
  brush.spline(bellyPts, 0.4);

  // Internal floral palmette & seed pearls along the boteh centerline
  brush.set("glaze_detail", "#690e02", 0.65);
  const centerLine = [];
  for (let i = 0; i <= 10; i++) {
    const t = map(i, 0, 10, 0.14, 0.88);
    const p = evalCashew(dummyNut, t, 0.0);
    centerLine.push([p[0], p[1], 0.5]);
  }
  brush.spline(centerLine, 0.4);

  // Floral petals radiating from the boteh spine
  for (let i = 1; i <= 6; i++) {
    const t = map(i, 0, 7, 0.16, 0.82);
    const cPt = evalCashew(dummyNut, t, 0.0);
    const oPt = evalCashew(dummyNut, t + 0.04, 0.55);
    const iPt = evalCashew(dummyNut, t + 0.04, -0.52);
    brush.set("glaze_detail", i % 2 === 0 ? "#8c1603" : "#ffe07d", 0.6);
    brush.line(cPt[0], cPt[1], oPt[0], oPt[1]);
    brush.line(cPt[0], cPt[1], iPt[0], iPt[1]);
  }

  // Beaded border dots around the paisley contour
  brush.set("sepia_pen", "#801504", 0.9);
  for (let i = 0; i < 16; i++) {
    const t = map(i, 0, 15, 0.08, 0.92);
    const pOut = evalCashew(dummyNut, t, 1.14);
    const pIn = evalCashew(dummyNut, t, -1.14);
    brush.circle(pOut[0], pOut[1], 2.2, 0.2);
    brush.circle(pIn[0], pIn[1], 2.2, 0.2);
  }
}

// ============================================================================
// STAGE 2: SWIRLING PAISLEY (BOTEH) CASHEW HEAP GENERATOR
// ============================================================================

function generateCashewHeap(hollowX, hollowY) {
  const nuts = [];
  let idCounter = 1;

  function addNut(x, y, L, angle, flip, zTier, roastBias = 0.5, isSplitHalf = false) {
    nuts.push({
      id: idCounter++,
      x: x,
      y: y,
      L: L,
      angle: angle,
      flip: flip,
      plump: random(0.94, 1.09),
      curl: random(0.85, 1.25),
      roast: constrain(roastBias + random(-0.18, 0.18), 0.12, 0.96),
      z: zTier + random(-0.08, 0.08),
      seed: idCounter * 37.3,
      isSplit: isSplitHalf
    });
  }

  // --- TIER 0: Deep bed cashews forming the foundation of the spiral heap ---
  const bedCount = 15;
  for (let i = 0; i < bedCount; i++) {
    const a = (i / bedCount) * 360 + 14;
    const r = random(135, 345);
    const swirlA = a + 68 + 22 * sin(a * 2);
    const x = hollowX + cos(a) * r * 1.04;
    const y = hollowY + sin(a) * r * 0.98;
    const flip = (i % 2 === 0) ? 1 : -1;
    addNut(x, y, random(52, 62), swirlA, flip, 0.2 + 0.15 * (1 - r / 400), 0.68, false);
  }

  // --- TIER 1: Inner Hollow Ring — 8 cashews curling tightly around the off-centre hollow ---
  const ringCount = 8;
  for (let i = 0; i < ringCount; i++) {
    const a = (i / ringCount) * 360;
    const r = 96 + (i % 2) * 14;
    const x = hollowX + cos(a) * r;
    const y = hollowY + sin(a) * r;
    // Oriented tangentially so their concave bellies cradle the hollow in a boteh wreath
    const swirlAngle = a + 98;
    addNut(x, y, random(50, 58), swirlAngle, 1, 1.1 + (i % 2) * 0.25, 0.52, i === 5);
  }

  // --- TIER 2: 5 Swirling Paisley Spiral Arms radiating from the hollow ---
  // Each arm is a logarithmic spiral where cashews nest belly-to-back in paisley chains
  const numArms = 5;
  for (let arm = 0; arm < numArms; arm++) {
    const armBaseAngle = arm * (360 / numArms) - 25;
    const stepsInArm = 5;
    for (let s = 0; s < stepsInArm; s++) {
      const u = s / (stepsInArm - 1); // 0 to 1 along the spiral arm
      const r = lerp(148, 415, Math.pow(u, 0.92));
      const theta = armBaseAngle + u * 118; // Clockwise paisley swirl!
      const x = hollowX + cos(theta) * r * 1.03;
      const y = hollowY + sin(theta) * r * 0.97;

      // Tangent angle of the logarithmic spiral
      const tangentAngle = theta + 62 + 12 * sin(u * 180);
      const flip = (arm + s) % 2 === 0 ? 1 : -1;
      const sizeL = lerp(64, 52, u * 0.6) + random(-3, 4);
      const zVal = 2.0 + (1 - Math.abs(u - 0.35)) * 0.8 + s * 0.08;
      const isHalf = (arm === 2 && s === 3) || (arm === 4 && s === 4);

      addNut(x, y, sizeL, tangentAngle, flip, zVal, 0.45 + 0.3 * u, isHalf);

      // Nested companion nut tucked directly into the concave belly or curled tip of the main arm nut!
      if (s < stepsInArm - 1 && (arm + s) % 2 === 0) {
        const compR = r + 36;
        const compTheta = theta - 13;
        const cx = hollowX + cos(compTheta) * compR * 1.03;
        const cy = hollowY + sin(compTheta) * compR * 0.97;
        addNut(cx, cy, sizeL * 0.88, tangentAngle - 24 * flip, -flip, zVal - 0.35, 0.58, false);
      }
    }
  }

  // --- TIER 3: Top Hero Crown Cashews (largest, sharpest focal nuts forming interlocking botehs) ---
  const heroSpecs = [
    // Sweeping focal paisley pair on the upper-left / center-left crest
    { dx: -135, dy: -75, L: 72, angle: 38, flip: 1, z: 3.8, roast: 0.56, split: false },
    { dx: -185, dy: -18, L: 65, angle: 18, flip: 1, z: 3.5, roast: 0.42, split: false },
    // Hero pair curving around the upper-right crest
    { dx: 78, dy: -138, L: 74, angle: 118, flip: -1, z: 3.9, roast: 0.64, split: false },
    { dx: 152, dy: -92, L: 66, angle: 142, flip: 1, z: 3.6, roast: 0.38, split: false },
    // Hero cluster on the lower-right paisley wave
    { dx: 162, dy: 82, L: 73, angle: -152, flip: 1, z: 3.85, roast: 0.68, split: false },
    { dx: 105, dy: 148, L: 64, angle: -125, flip: -1, z: 3.55, roast: 0.48, split: true },
    // Hero cluster on the lower-left swirl
    { dx: -68, dy: 156, L: 71, angle: -48, flip: 1, z: 3.75, roast: 0.62, split: false },
    { dx: -158, dy: 118, L: 66, angle: -72, flip: -1, z: 3.45, roast: 0.35, split: false },
    // Outer solitary/paired boteh nuts trailing onto the saffron cloth
    { dx: 375, dy: -225, L: 60, angle: 155, flip: 1, z: 1.5, roast: 0.55, split: false },
    { dx: -345, dy: -265, L: 58, angle: 48, flip: -1, z: 1.5, roast: 0.62, split: false },
    { dx: 395, dy: 245, L: 61, angle: -132, flip: 1, z: 1.5, roast: 0.48, split: false },
    { dx: -320, dy: 295, L: 57, angle: -38, flip: -1, z: 1.5, roast: 0.72, split: true },
    // One small broken cashew nestled right at the edge of the off-centre hollow
    { dx: 24, dy: -32, L: 44, angle: 75, flip: -1, z: 0.9, roast: 0.60, split: true }
  ];

  for (let h of heroSpecs) {
    addNut(hollowX + h.dx, hollowY + h.dy, h.L, h.angle, h.flip, h.z, h.roast, h.split);
  }

  // Sort strictly from lowest z (deepest in heap) to highest z (top crown nuts)
  nuts.sort((a, b) => a.z - b.z);
  return nuts;
}

// ============================================================================
// STAGE 3: HYPERREALISTIC WATERCOLOR GLAZING, OIL SHEEN, SALT & FISSURES
// ============================================================================

function drawClothDropShadows(nuts, hollowX, hollowY) {
  brush.noField();
  brush.noStroke();
  brush.noHatch();

  // Warm ambient shadow cast by the entire cashew heap onto the saffron cloth
  for (let n of nuts) {
    if (n.z < 2.4) {
      const shPts = buildCashewSilhouette(n, 10, 14, 18, 1.06);
      brush.fill("#5e1602", 52);
      brush.fillBleed(0.28, "out");
      brush.fillTexture(0.65, 0.45);
      drawPolyShape(shPts, 0.4, true);
    }
  }
  brush.noFill();
}

function renderCashew(nut) {
  brush.noField();
  brush.noStroke();
  brush.noHatch();

  // --------------------------------------------------------------------------
  // 1. CAST SHADOW ONTO UNDERLYING NUTS (Top-left light -> Bottom-right shadow)
  // --------------------------------------------------------------------------
  const shOffX = 8.5 + nut.z * 1.4;
  const shOffY = 10.5 + nut.z * 1.6;
  const shadowPoly = buildCashewSilhouette(nut, 11, shOffX, shOffY, 1.01);
  brush.fill("#2e0e02", 82);
  brush.fillBleed(0.16, "out");
  brush.fillTexture(0.6, 0.45);
  drawPolyShape(shadowPoly, 0.38, true);

  // Tighter dark core of cast shadow right beneath the nut rim
  const coreShadowPoly = buildCashewSilhouette(nut, 10, shOffX * 0.45, shOffY * 0.45, 0.99);
  brush.wash("#1c0701", 95);
  drawPolyShape(coreShadowPoly, 0.35, true);
  brush.noWash();

  // --------------------------------------------------------------------------
  // 2. BASE COTYLEDON LAYER: Buttery Naples Yellow & Warm Ivory-Cream
  // --------------------------------------------------------------------------
  const fullBodyPoly = buildCashewSilhouette(nut, 14, 0, 0, 1.0);

  // Opaque buttery underpainting so underlying dark nuts are cleanly occluded
  const baseCream = nut.roast > 0.62 ? "#f6cc68" : (nut.roast < 0.38 ? "#ffea9f" : "#fbd97a");
  brush.wash(baseCream, 238);
  drawPolyShape(fullBodyPoly, 0.38, true);
  brush.noWash();

  // First transparent watercolor glaze in luminous Naples yellow
  const naplesCol = nut.roast > 0.6 ? "#f2b438" : "#ffcf5c";
  brush.fill(naplesCol, 115);
  brush.fillBleed(0.06, "in");
  brush.fillTexture(0.68, 0.52);
  drawPolyShape(fullBodyPoly, 0.38, true);
  brush.noFill();

  // If this is a split cotyledon half, render its flat scooped interior face
  if (nut.isSplit) {
    renderSplitCashewInterior(nut, fullBodyPoly);
    return;
  }

  // --------------------------------------------------------------------------
  // 3. LAYERED WATERCOLOR GLAZES: Golden Ochre, Burnt Sienna & Raw Umber
  // --------------------------------------------------------------------------

  // Glaze A: Warm Golden Ochre / Raw Sienna 3D cylinder turn (belly & outer rim)
  const ochreBellyPatch = buildCashewPatch(nut, 0.05, 0.95, -0.98, 0.05, 11);
  brush.fill("#d97e14", 98);
  brush.fillBleed(0.12, "in");
  brush.fillTexture(0.72, 0.5);
  drawPolyShape(ochreBellyPatch, 0.38, true);

  // Glaze B: Reflected Saffron-Gold Bounce Light along the shadowed underside edge
  const bouncePatch = buildCashewPatch(nut, 0.12, 0.88, -0.96, -0.45, 9);
  brush.fill("#ff9900", 82);
  brush.fillBleed(0.14, "in");
  brush.fillTexture(0.6, 0.4);
  drawPolyShape(bouncePatch, 0.38, true);

  // Glaze C: Caramelized Burnt Sienna Roast on the plump convex back & hooked tip
  const siennaStart = constrain(0.14 - nut.roast * 0.08, 0.04, 0.25);
  const siennaEnd = constrain(0.84 + nut.roast * 0.12, 0.78, 0.97);
  const burntSiennaPatch = buildCashewPatch(nut, siennaStart, siennaEnd, 0.08, 0.94, 11);
  const siennaCol = nut.roast > 0.55 ? "#a83206" : "#c74d10";
  brush.fill(siennaCol, 110 + nut.roast * 45);
  brush.fillBleed(0.15, "in");
  brush.fillTexture(0.82, 0.68);
  drawPolyShape(burntSiennaPatch, 0.38, true);

  // Secondary toasted blush on the bulbous head dome
  const headRoastPatch = buildCashewPatch(nut, 0.03, 0.28, -0.42, 0.68, 7);
  brush.fill("#b83e09", 78 + nut.roast * 40);
  brush.fillBleed(0.16, "in");
  brush.fillTexture(0.78, 0.62);
  drawPolyShape(headRoastPatch, 0.38, true);

  // Glaze D: Deep Raw Umber scorched roast blisters on the peak of the back & distal hook
  if (nut.roast > 0.32) {
    const umberPatch = buildCashewPatch(nut, 0.24, 0.76, 0.32, 0.88, 9);
    brush.fill("#5c2006", 75 + nut.roast * 65);
    brush.fillBleed(0.12, "in");
    brush.fillTexture(0.86, 0.74);
    drawPolyShape(umberPatch, 0.38, true);

    // Toasted distal tip cap
    const tipPatch = buildCashewPatch(nut, 0.76, 0.97, -0.35, 0.85, 6);
    brush.fill("#6e2607", 85 + nut.roast * 50);
    brush.fillBleed(0.12, "in");
    brush.fillTexture(0.8, 0.65);
    drawPolyShape(tipPatch, 0.38, true);
  }
  brush.noFill();

  // --------------------------------------------------------------------------
  // 4. SCULPTURAL 3D GLAZE STROKES & BOTANICAL SURFACE WRINKLES
  // --------------------------------------------------------------------------

  // Soft longitudinal shading bands following the curved boteh anatomy
  const bandSpecs = [
    { v: -0.82, t1: 0.08, t2: 0.92, col: "#612205", w: 1.15 }, // Deep belly core shadow
    { v: -0.58, t1: 0.10, t2: 0.90, col: "#b34709", w: 1.35 }, // Warm sienna belly turn
    { v: -0.25, t1: 0.08, t2: 0.92, col: "#f0a830", w: 1.50 }, // Golden Naples transition
    { v:  0.48, t1: 0.12, t2: 0.88, col: "#9e2f06", w: 1.45 }, // Roasted upper arch
    { v:  0.78, t1: 0.10, t2: 0.90, col: "#591d05", w: 1.10 }  // Outer back turning edge
  ];

  for (let b of bandSpecs) {
    const pts = [];
    const steps = 10;
    for (let i = 0; i <= steps; i++) {
      const u = i / steps;
      const t = lerp(b.t1, b.t2, u);
      const p = evalCashew(nut, t, b.v);
      pts.push([p[0], p[1], 0.3 + 0.8 * sin(u * 180)]);
    }
    brush.set("glaze_wide", b.col, b.w * (nut.L / 62));
    brush.spline(pts, 0.45);
  }

  // Fine botanical growth striations & shrinkage wrinkles along the cashew curve
  const numStriations = 9;
  for (let s = 0; s < numStriations; s++) {
    const vBase = map(s, 0, numStriations - 1, -0.68, 0.72);
    const tStart = random(0.08, 0.25);
    const tEnd = random(0.72, 0.92);
    const strPts = [];
    for (let k = 0; k <= 7; k++) {
      const u = k / 7;
      const t = lerp(tStart, tEnd, u);
      const vWob = vBase + 0.06 * sin(u * 360 + s * 45);
      const p = evalCashew(nut, t, vWob);
      strPts.push([p[0], p[1], 0.25 + 0.65 * sin(u * 180)]);
    }
    const strCol = vBase > 0.2 ? "#7a2405" : (vBase < -0.2 ? "#ad490b" : "#d9881e");
    brush.set("glaze_detail", strCol, 0.52 * (nut.L / 62));
    brush.spline(strPts, 0.4);
  }

  // Mottled roast blister rings on the convex shoulder and back
  const numBlisters = floor(3 + nut.roast * 5);
  for (let b = 0; b < numBlisters; b++) {
    const bt = random(0.18, 0.82);
    const bv = random(0.18, 0.75);
    const bp = evalCashew(nut, bt, bv);
    const bRad = nut.L * random(0.04, 0.09);
    brush.set("glaze_detail", b % 2 === 0 ? "#4a1703" : "#8c2804", 0.55);
    brush.circle(bp[0], bp[1], bRad, 0.35);
  }

  // Papery reddish-brown testa (skin remnant) tucked in the pinched umbilical cleft (t ~ 0.47, v ~ -0.88)
  const testaPatch = buildCashewPatch(nut, 0.39, 0.56, -0.99, -0.58, 6);
  brush.noStroke();
  brush.wash("#4d1604", 175);
  drawPolyShape(testaPatch, 0.3, true);
  brush.noWash();

  // --------------------------------------------------------------------------
  // 5. RESERVED HIGHLIGHTS FOR THE OIL SHEEN
  // --------------------------------------------------------------------------

  // Primary elongated oil-sheen highlight ribbon along the high 3D ridge (v ~ 0.08..0.28)
  const sheenHaloPatch = buildCashewPatch(nut, 0.15, 0.76, -0.06, 0.32, 9);
  brush.noStroke();
  brush.wash("#fff3bd", 155);
  drawPolyShape(sheenHaloPatch, 0.4, true);

  const sheenCorePatch = buildCashewPatch(nut, 0.20, 0.66, 0.04, 0.22, 8);
  brush.wash("#fffdf5", 225);
  drawPolyShape(sheenCorePatch, 0.4, true);

  // Secondary bulbous head oil highlight
  const headSheenPatch = buildCashewPatch(nut, 0.07, 0.17, -0.22, 0.15, 6);
  brush.wash("#fffdf4", 205);
  drawPolyShape(headSheenPatch, 0.38, true);
  brush.noWash();

  // Crisp glistening specular oil streaks & micro-beads
  const glossPts = [];
  for (let i = 0; i <= 7; i++) {
    const u = i / 7;
    const t = lerp(0.18, 0.70, u);
    const p = evalCashew(nut, t, 0.13 + 0.03 * sin(u * 180));
    glossPts.push([p[0], p[1], 0.3 + 0.85 * sin(u * 180)]);
  }
  brush.set("oil_gloss", "#ffffff", 0.95 * (nut.L / 62));
  brush.spline(glossPts, 0.45);

  // Secondary fine parallel oil reflection line
  const glossPts2 = [];
  for (let i = 0; i <= 5; i++) {
    const u = i / 5;
    const t = lerp(0.26, 0.58, u);
    const p = evalCashew(nut, t, -0.02);
    glossPts2.push([p[0], p[1], 0.25 + 0.7 * sin(u * 180)]);
  }
  brush.set("oil_gloss", "#fff9de", 0.6 * (nut.L / 62));
  brush.spline(glossPts2, 0.45);

  // --------------------------------------------------------------------------
  // 6. FINE SEPIA PEN: OCCLUSION CONTOURS, HAIRLINE FISSURES & SALT CRYSTALS
  // --------------------------------------------------------------------------

  // A. Crisp dark sepia occlusion line along the concave belly & shadowed outer edge
  const bellyEdgePts = [];
  for (let i = 0; i <= 12; i++) {
    const t = map(i, 0, 12, 0.04, 0.96);
    const p = evalCashew(nut, t, -0.99);
    // Heavier pressure right in the pinched umbilical cleft (t ~ 0.47)
    const cleftPress = 0.45 + 0.85 * Math.exp(-Math.pow((t - 0.47) / 0.18, 2));
    bellyEdgePts.push([p[0], p[1], cleftPress]);
  }
  brush.set("sepia_pen", "#260b01", 0.95);
  brush.spline(bellyEdgePts, 0.4);

  // Delicate sepia contour around the outer convex back & curled tip
  const backEdgePts = [];
  for (let i = 0; i <= 12; i++) {
    const t = map(i, 0, 12, 0.02, 0.98);
    const p = evalCashew(nut, t, 0.99);
    backEdgePts.push([p[0], p[1], 0.35 + 0.35 * sin(t * 180)]);
  }
  brush.set("sepia_pen", "#4a1905", 0.68);
  brush.spline(backEdgePts, 0.4);

  // B. Umbilical notch fold & basal attachment dimple (hilum scar)
  const cleftFold = [
    evalCashew(nut, 0.41, -0.95),
    evalCashew(nut, 0.47, -0.58),
    evalCashew(nut, 0.53, -0.35)
  ];
  brush.set("sepia_pen", "#1f0801", 1.05);
  brush.spline([
    [cleftFold[0][0], cleftFold[0][1], 1.0],
    [cleftFold[1][0], cleftFold[1][1], 0.75],
    [cleftFold[2][0], cleftFold[2][1], 0.2]
  ], 0.35);

  // Basal dimple at head (t ~ 0.06, v ~ -0.35)
  const scar1 = evalCashew(nut, 0.05, -0.45);
  const scar2 = evalCashew(nut, 0.08, -0.18);
  const scar3 = evalCashew(nut, 0.11, -0.42);
  brush.set("sepia_pen", "#361103", 0.85);
  brush.spline([
    [scar1[0], scar1[1], 0.4],
    [scar2[0], scar2[1], 0.9],
    [scar3[0], scar3[1], 0.3]
  ], 0.4);

  // C. Hairline fissures (cotyledon suture split at tip & toasted surface micro-cracks)
  const tipSeamPts = [];
  for (let i = 0; i <= 5; i++) {
    const u = i / 5;
    const t = lerp(0.74, 0.98, u);
    const vJit = (noise(nut.seed + i * 2.1) - 0.5) * 0.14;
    const p = evalCashew(nut, t, vJit);
    tipSeamPts.push([p[0], p[1], 0.25 + 0.75 * u]);
  }
  brush.set("sepia_pen", "#290c02", 0.78);
  brush.spline(tipSeamPts, 0.25);

  // 2 to 4 transverse hairline roast fissures across the caramelized back
  const numFissures = floor(2 + nut.roast * 3);
  for (let f = 0; f < numFissures; f++) {
    const ft = random(0.22, 0.78);
    const fv1 = random(-0.15, 0.25);
    const fv2 = fv1 + random(0.28, 0.52);
    const fPts = [];
    for (let s = 0; s <= 3; s++) {
      const u = s / 3;
      const tCur = ft + (noise(nut.seed + f * 7 + s) - 0.5) * 0.06;
      const vCur = lerp(fv1, fv2, u);
      const p = evalCashew(nut, tCur, vCur);
      fPts.push([p[0], p[1], sin(u * 180) * 0.8 + 0.15]);
    }
    brush.set("sepia_pen", "#381203", 0.58);
    brush.spline(fPts, 0.2);
  }

  // D. Crystalline Sea-Salt Grains picked out in fine sepia pen & white glints
  const numSalt = floor(6 + (nut.L / 65) * 7);
  for (let s = 0; s < numSalt; s++) {
    const st = random(0.12, 0.86);
    const sv = random(-0.48, 0.68);
    const sp = evalCashew(nut, st, sv);
    const grainSz = random(1.8, 3.8) * (nut.L / 62);
    drawSaltCrystal(sp[0], sp[1], grainSz);
  }
}

// Renders a split cashew half (showing the flat inner cotyledon face & central groove)
function renderSplitCashewInterior(nut, outerPoly) {
  // Warm toasted amber outer bevel rim
  brush.noStroke();
  brush.fill("#d47a16", 115);
  brush.fillBleed(0.08, "in");
  brush.fillTexture(0.65, 0.45);
  drawPolyShape(outerPoly, 0.38, true);

  // Flat pale ivory-butter inner cotyledon face
  const innerFace = buildCashewPatch(nut, 0.05, 0.95, -0.82, 0.82, 12);
  brush.wash("#fff6d6", 230);
  drawPolyShape(innerFace, 0.38, true);
  brush.noWash();

  // Central longitudinal cotyledon groove/depression
  const groovePatch = buildCashewPatch(nut, 0.20, 0.78, -0.26, 0.24, 8);
  brush.fill("#dead54", 105);
  brush.fillBleed(0.12, "in");
  brush.fillTexture(0.6, 0.4);
  drawPolyShape(groovePatch, 0.38, true);
  brush.noFill();

  // Embryonic germ nib near the head-belly curve
  const germPatch = buildCashewPatch(nut, 0.12, 0.28, -0.68, -0.18, 6);
  brush.wash("#f2c86b", 190);
  drawPolyShape(germPatch, 0.35, true);
  brush.noWash();

  // Sepia pen detail around broken rim, embryo nib, and salt grains
  const rimPts = [];
  for (let i = 0; i <= 12; i++) {
    const t = map(i, 0, 12, 0.04, 0.96);
    const p = evalCashew(nut, t, -0.98);
    rimPts.push([p[0], p[1], 0.7]);
  }
  brush.set("sepia_pen", "#2b0d02", 0.9);
  brush.spline(rimPts, 0.38);

  const innerRimPts = [];
  for (let i = 0; i <= 10; i++) {
    const t = map(i, 0, 10, 0.08, 0.92);
    const p = evalCashew(nut, t, 0.82);
    innerRimPts.push([p[0], p[1], 0.45]);
  }
  brush.set("sepia_pen", "#7a3608", 0.55);
  brush.spline(innerRimPts, 0.38);

  for (let s = 0; s < 5; s++) {
    const sp = evalCashew(nut, random(0.18, 0.82), random(-0.5, 0.5));
    drawSaltCrystal(sp[0], sp[1], random(1.8, 3.2));
  }
}

// Renders a tiny 3D cubic/rhomboid sea-salt crystal with sepia facet lines and bright white glint
function drawSaltCrystal(x, y, sz) {
  const ang = random(0, 90);
  const c = cos(ang) * sz;
  const s = sin(ang) * sz;

  const p1 = [x - c, y - s];
  const p2 = [x + s, y - c];
  const p3 = [x + c, y + s];
  const p4 = [x - s, y + c];

  // Tiny dark sepia micro-shadow on the bottom-right facet
  brush.noStroke();
  brush.wash("#3b1403", 155);
  drawPolyShape([
    [p2[0] + 1.1, p2[1] + 1.3],
    [p3[0] + 1.1, p3[1] + 1.3],
    [p4[0] + 1.1, p4[1] + 1.3]
  ], 0.05, true);

  // Bright crystalline white facet core
  brush.wash("#fffef9", 242);
  drawPolyShape([p1, p2, p3, p4], 0.05, true);
  brush.noWash();

  // Crisp fine sepia pen facet outline
  brush.set("sepia_pen", "#331002", 0.52);
  brush.line(p1[0], p1[1], p2[0], p2[1]);
  brush.line(p2[0], p2[1], p3[0], p3[1]);
  brush.line(p3[0], p3[1], p4[0], p4[1]);
}

