function drawHollowAndClothCrumbs(hollowX, hollowY) {
  // Fallen sea-salt crystals and tiny roasted testa flakes inside the off-centre hollow
  for (let i = 0; i < 28; i++) {
    const a = random(0, 360);
    const r = random(8, 68);
    const sx = hollowX + cos(a) * r;
    const sy = hollowY + sin(a) * r;
    if (i % 4 === 0) {
      // Tiny toasted skin flake
      brush.noStroke();
      brush.wash(i % 8 === 0 ? "#4a1503" : "#872604", 195);
      const sz = random(2.5, 5.5);
      drawPolyShape([
        [sx - sz, sy],
        [sx, sy - sz * 0.7],
        [sx + sz * 0.9, sy + sz * 0.4],
        [sx - sz * 0.3, sy + sz * 0.8]
      ], 0.25, true);
      brush.noWash();
    } else {
      drawSaltCrystal(sx, sy, random(2.0, 3.8));
    }
  }

  // Scattered salt crystals and spice crumbs around the outer perimeter of the heap
  for (let i = 0; i < 42; i++) {
    const a = random(0, 360);
    const r = random(350, 485);
    const sx = hollowX + cos(a) * r;
    const sy = hollowY + sin(a) * r;
    if (sx > 65 && sx < 1135 && sy > 65 && sy < 1135) {
      drawSaltCrystal(sx, sy, random(1.8, 3.6));
    }
  }
}

