// Hyperrealist Watercolor & Ink Study:
// Split Pomegranate on Slate — Garnet Crystal Arils & Banded Chalcedony Pith

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(7482);
  noiseSeed(7482);
}

// ============================================================================
// GEOMETRY & CRYSTAL FACET UTILITIES
// ============================================================================

function drawPoly(pts, curvature = 0) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

function polyCentroid(pts) {
  let sx = 0, sy = 0;
  for (let i = 0; i < pts.length; i++) {
    sx += pts[i][0];
    sy += pts[i][1];
  }
  return [sx / pts.length, sy / pts.length];
}

function polyArea(pts) {
  if (!pts || pts.length < 3) return 0;
  let a = 0;
  for (let i = 0; i < pts.length; i++) {
    let j = (i + 1) % pts.length;
    a += pts[i][0] * pts[j][1] - pts[j][0] * pts[i][1];
  }
  return Math.abs(a) * 0.5;
}

function pointInPoly(x, y, poly) {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    let xi = poly[i][0], yi = poly[i][1];
    let xj = poly[j][0], yj = poly[j][1];
    let intersect = ((yi > y) !== (yj > y)) &&
      (x < (xj - xi) * (y - yi) / ((yj - yi) || 0.00001) + xi);
    if (intersect) inside = !inside;
  }
  return inside;
}

// Sutherland-Hodgman half-plane clip: keeps points where (P - P0) . N <= 0
function clipPolyHalfPlane(poly, px, py, nx, ny) {
  if (!poly || poly.length < 3) return [];
  let out = [];
  let n = poly.length;
  for (let i = 0; i < n; i++) {
    let cur = poly[i];
    let prev = poly[(i + n - 1) % n];
    let dCur = (cur[0] - px) * nx + (cur[1] - py) * ny;
    let dPrev = (prev[0] - px) * nx + (prev[1] - py) * ny;
    if (dCur <= 0) {
      if (dPrev > 0) {
        let t = dPrev / (dPrev - dCur || 0.00001);
        out.push([
          prev[0] + t * (cur[0] - prev[0]),
          prev[1] + t * (cur[1] - prev[1])
        ]);
      }
      out.push(cur);
    } else if (dPrev <= 0) {
      let t = dPrev / (dPrev - dCur || 0.00001);
      out.push([
        prev[0] + t * (cur[0] - prev[0]),
        prev[1] + t * (cur[1] - prev[1])
      ]);
    }
  }
  return out;
}

// Clip a polygon against a convex clipPoly (assumed clockwise/CCW consistent)
function clipPolyAgainstConvex(subject, clipPoly) {
  let out = subject.slice();
  let c = polyCentroid(clipPoly);
  for (let i = 0; i < clipPoly.length; i++) {
    let a = clipPoly[i];
    let b = clipPoly[(i + 1) % clipPoly.length];
    let dx = b[0] - a[0];
    let dy = b[1] - a[1];
    let nx = -dy, ny = dx;
    let len = Math.hypot(nx, ny) || 1;
    nx /= len; ny /= len;
    // Ensure normal points outward from centroid c
    if ((a[0] - c[0]) * nx + (a[1] - c[1]) * ny < 0) {
      nx = -nx; ny = -ny;
    }
    out = clipPolyHalfPlane(out, a[0], a[1], nx, ny);
    if (out.length < 3) return [];
  }
  return out;
}

// Merge close vertices so crystal facets stay crisp and non-degenerate
function simplifyCrystalPoly(poly, minDist = 4.5) {
  if (!poly || poly.length < 4) return poly;
  let cleaned = [poly[0]];
  for (let i = 1; i < poly.length; i++) {
    let last = cleaned[cleaned.length - 1];
    if ( Math.hypot(poly[i][0] - last[0], poly[i][1] - last[1]) >= minDist ) {
      cleaned.push(poly[i]);
    }
  }
  if (cleaned.length > 3) {
    let first = cleaned[0];
    let last = cleaned[cleaned.length - 1];
    if (Math.hypot(first[0] - last[0], first[1] - last[1]) < minDist) {
      cleaned.pop();
    }
  }
  return cleaned;
}

// Offset polygon radially from its centroid (positive = expand, negative = shrink)
function offsetPolyRadial(poly, dist, jitter = 0) {
  let c = polyCentroid(poly);
  let out = [];
  for (let i = 0; i < poly.length; i++) {
    let dx = poly[i][0] - c[0];
    let dy = poly[i][1] - c[1];
    let d = Math.hypot(dx, dy) || 1;
    let j = jitter ? (noise(i * 0.7, dist * 0.1) - 0.5) * jitter : 0;
    let nd = Math.max(2, d + dist + j);
    out.push([c[0] + (dx / d) * nd, c[1] + (dy / d) * nd]);
  }
  return out;
}

// Build complete faceted garnet crystal geometry for a single aril
function buildGarnetGem(outerPoly, coreX, coreY, isLoose = false) {
  let V = simplifyCrystalPoly(outerPoly, 4.0);
  if (!V || V.length < 4) return null;

  let C = polyCentroid(V);
  let k = V.length;

  // Average radius of the crystal
  let avgR = 0;
  for (let i = 0; i < k; i++) {
    avgR += Math.hypot(V[i][0] - C[0], V[i][1] - C[1]);
  }
  avgR /= k;
  if (avgR < 8) return null;

  // Shift the inner table slightly toward the upper-left light source
  let tableCx = C[0] - avgR * 0.11 + random(-1.5, 1.5);
  let tableCy = C[1] - avgR * 0.11 + random(-1.5, 1.5);

  // Table polygon vertices T[i] corresponding to outer V[i]
  let T = [];
  for (let i = 0; i < k; i++) {
    let ratio = random(0.42, 0.57);
    T.push([
      lerp(tableCx, V[i][0], ratio),
      lerp(tableCy, V[i][1], ratio)
    ]);
  }

  // Deep pavilion culet point visible through the translucent garnet
  let culet = [
    C[0] + avgR * random(0.10, 0.22),
    C[1] + avgR * random(0.10, 0.22)
  ];

  // Lateral bevel/crown facets Q[i] and their light orientation
  // Light comes from upper-left (-132 degrees)
  let lightAngle = -132;
  let crownFacets = [];
  let bestIdx = 0;
  let bestScore = -999;
  let secondIdx = -1;
  let secondScore = -999;

  for (let i = 0; i < k; i++) {
    let next = (i + 1) % k;
    let quad = [V[i], V[next], T[next], T[i]];
    let mx = (V[i][0] + V[next][0]) * 0.5 - C[0];
    let my = (V[i][1] + V[next][1]) * 0.5 - C[1];
    let ang = atan2(my, mx);
    let score = cos(ang - lightAngle) + random(-0.08, 0.08);
    crownFacets.push({
      poly: quad,
      score: score,
      idx: i,
      isHighlight: false,
      isSecondaryGlint: false
    });
    if (score > bestScore) {
      secondScore = bestScore;
      secondIdx = bestIdx;
      bestScore = score;
      bestIdx = i;
    } else if (score > secondScore) {
      secondScore = score;
      secondIdx = i;
    }
  }

  // Primary bare-paper highlight facet on every gem
  crownFacets[bestIdx].isHighlight = true;

  // 42% of gems also have a secondary sharp bare-paper highlight on an adjacent crown facet
  if (secondIdx >= 0 && secondScore > 0.48 && random() < 0.42) {
    crownFacets[secondIdx].isHighlight = true;
  }

  // Internal pavilion refraction triangles inside the table
  let pavilionFacets = [];
  for (let i = 0; i < k; i++) {
    let next = (i + 1) % k;
    let tri = [T[i], T[next], culet];
    let mx = (T[i][0] + T[next][0]) * 0.5 - culet[0];
    let my = (T[i][1] + T[next][1]) * 0.5 - culet[1];
    let ang = atan2(my, mx);
    // Internal refraction reverses light across the pavilion!
    let refScore = cos(ang - (lightAngle + 155)) + random(-0.15, 0.15);
    let isTableHi = (i === bestIdx && random() < 0.68);
    pavilionFacets.push({
      poly: tri,
      score: refScore,
      isHighlight: isTableHi
    });
  }

  // Build glaze polygons that EXCLUDE the primary bare-paper highlight facet
  // so the highlight stays virgin watercolor paper
  let nonHighlightBody = [];
  for (let i = 0; i < k; i++) {
    if (i === bestIdx) {
      nonHighlightBody.push(T[i]);
      nonHighlightBody.push(T[(i + 1) % k]);
    } else {
      nonHighlightBody.push(V[i]);
      nonHighlightBody.push(V[(i + 1) % k]);
    }
  }

  // Deep shadow glaze polygon covering lower-right half of the gem
  let shadowPoly = [culet];
  for (let i = 0; i < k; i++) {
    if (crownFacets[i].score < 0.05) {
      shadowPoly.push(T[i]);
      shadowPoly.push(V[i]);
      shadowPoly.push(V[(i + 1) % k]);
      shadowPoly.push(T[(i + 1) % k]);
    }
  }

  // Internal pale seed-kernel (the translucent whitish-coral pip inside the aril)
  let radAng = atan2(coreY - C[1], coreX - C[0]) + random(-18, 18);
  let pipLen = avgR * random(0.28, 0.40);
  let pipWid = avgR * random(0.11, 0.16);
  let pipCx = C[0] + cos(radAng) * avgR * 0.06;
  let pipCy = C[1] + sin(radAng) * avgR * 0.06;
  let ca = cos(radAng), sa = sin(radAng);
  let pa = cos(radAng + 90), psa = sin(radAng + 90);
  let pipPoly = [
    [pipCx + ca * pipLen, pipCy + sa * pipLen],
    [pipCx + ca * pipLen * 0.3 + pa * pipWid, pipCy + sa * pipLen * 0.3 + psa * pipWid],
    [pipCx - ca * pipLen * 0.7 + pa * pipWid * 0.7, pipCy - sa * pipLen * 0.7 + psa * pipWid * 0.7],
    [pipCx - ca * pipLen, pipCy - sa * pipLen],
    [pipCx - ca * pipLen * 0.7 - pa * pipWid * 0.7, pipCy - sa * pipLen * 0.7 - psa * pipWid * 0.7],
    [pipCx + ca * pipLen * 0.3 - pa * pipWid, pipCy + sa * pipLen * 0.3 - psa * pipWid]
  ];

  return {
    V, T, C, avgR, culet,
    crownFacets,
    pavilionFacets,
    nonHighlightBody: simplifyCrystalPoly(nonHighlightBody, 2.5),
    shadowPoly: simplifyCrystalPoly(shadowPoly, 2.5),
    pipPoly,
    bestIdx,
    toneBias: random(-0.22, 0.22), // slight variation from rose madder to deep claret per aril
    isLoose
  };
}

// Pack aril seeds inside a chamber polygon and compute Voronoi crystal polygons
function generateChamberArils(chamberPoly, coreX, coreY, spacing = 39, allowEdgeOverhang = false) {
  let bMinX = 9999, bMaxX = -9999, bMinY = 9999, bMaxY = -9999;
  for (let p of chamberPoly) {
    if (p[0] < bMinX) bMinX = p[0];
    if (p[0] > bMaxX) bMaxX = p[0];
    if (p[1] < bMinY) bMinY = p[1];
    if (p[1] > bMaxY) bMaxY = p[1];
  }

  // Initial hexagonal grid of seeds inside chamber
  let seeds = [];
  let row = 0;
  let stepY = spacing * 0.86;
  for (let y = bMinY + spacing * 0.42; y <= bMaxY - spacing * 0.35; y += stepY) {
    let offsetX = (row % 2) * (spacing * 0.5);
    for (let x = bMinX + spacing * 0.42 + offsetX; x <= bMaxX - spacing * 0.35; x += spacing) {
      let jx = x + random(-spacing * 0.22, spacing * 0.22);
      let jy = y + random(-spacing * 0.22, spacing * 0.22);
      if (pointInPoly(jx, jy, chamberPoly)) {
        seeds.push([jx, jy]);
      }
    }
    row++;
  }

  // 10 iterations of repulsion relaxation so arils pack tightly and organically
  let shrunkChamber = offsetPolyRadial(chamberPoly, -spacing * 0.36);
  for (let iter = 0; iter < 10; iter++) {
    for (let i = 0; i < seeds.length; i++) {
      let fx = 0, fy = 0;
      for (let j = 0; j < seeds.length; j++) {
        if (i === j) continue;
        let dx = seeds[i][0] - seeds[j][0];
        let dy = seeds[i][1] - seeds[j][1];
        let d = Math.hypot(dx, dy) || 0.1;
        if (d < spacing * 1.15) {
          let push = (spacing * 1.15 - d) * 0.18;
          fx += (dx / d) * push;
          fy += (dy / d) * push;
        }
      }
      let nx = seeds[i][0] + fx;
      let ny = seeds[i][1] + fy;
      if (pointInPoly(nx, ny, shrunkChamber)) {
        seeds[i][0] = nx;
        seeds[i][1] = ny;
      }
    }
  }

  // Build bounded Voronoi polyhedron for each seed
  let gems = [];
  let clipBoundary = allowEdgeOverhang
    ? offsetPolyRadial(chamberPoly, 6, 4)
    : offsetPolyRadial(chamberPoly, -1.5, 2);

  for (let i = 0; i < seeds.length; i++) {
    let sx = seeds[i][0];
    let sy = seeds[i][1];

    // Start with an 8-sided crystal polygon oriented toward the chamber core
    let baseAng = atan2(coreY - sy, coreX - sx);
    let cell = [];
    let sides = 8;
    let maxR = spacing * 0.72;
    for (let s = 0; s < sides; s++) {
      let a = baseAng + s * (360 / sides) + random(-8, 8);
      // Slight radial elongation toward core
      let stretch = (s === 0 || s === 4) ? 1.14 : 0.96;
      let r = maxR * stretch * random(0.92, 1.06);
      cell.push([sx + cos(a) * r, sy + sin(a) * r]);
    }

    // Clip against neighbor bisectors
    for (let j = 0; j < seeds.length; j++) {
      if (i === j) continue;
      let ox = seeds[j][0];
      let oy = seeds[j][1];
      let dx = ox - sx;
      let dy = oy - sy;
      let d = Math.hypot(dx, dy);
      if (d > spacing * 1.85 || d < 0.1) continue;

      let nx = dx / d;
      let ny = dy / d;
      // Leave a tiny 0.9px cleavage seam between gems
      let mx = sx + dx * 0.5 - nx * 0.9;
      let my = sy + dy * 0.5 - ny * 0.9;
      cell = clipPolyHalfPlane(cell, mx, my, nx, ny);
      if (cell.length < 3) break;
    }

    // Clip against chamber boundary segments (local half-planes near seed)
    if (cell.length >= 3) {
      let chC = polyCentroid(clipBoundary);
      for (let e = 0; e < clipBoundary.length; e++) {
        let a = clipBoundary[e];
        let b = clipBoundary[(e + 1) % clipBoundary.length];
        let emx = (a[0] + b[0]) * 0.5;
        let emy = (a[1] + b[1]) * 0.5;
        if (Math.hypot(emx - sx, emy - sy) > spacing * 1.45) continue;

        let edx = b[0] - a[0];
        let edy = b[1] - a[1];
        let enx = -edy, eny = edx;
        let elen = Math.hypot(enx, eny) || 1;
        enx /= elen; eny /= elen;
        if ((a[0] - chC[0]) * enx + (a[1] - chC[1]) * eny < 0) {
          enx = -enx; eny = -eny;
        }
        cell = clipPolyHalfPlane(cell, a[0], a[1], enx, eny);
        if (cell.length < 3) break;
      }
    }

    if (cell.length >= 4 && polyArea(cell) > 180) {
      let gem = buildGarnetGem(cell, coreX, coreY, false);
      if (gem) gems.push(gem);
    }
  }

  return gems;
}

// ============================================================================
// MAIN ARTWORK RENDERING
// ============================================================================

function draw() {
  translate(-width / 2, -height / 2);

  // Cold-pressed bright ivory-white watercolor paper (reserved for sharp highlights)
  background("#FCF9F7");

  // Always initialize a default brush state before any stroke operations
  brush.set("2H", "#8A92A0", 0.5);

  // --------------------------------------------------------------------------
  // 1. DEFINE MACRO GEOMETRY OF THE SPLIT POMEGRANATE & CLEFT SHARD
  // --------------------------------------------------------------------------
  const mainCx = 555;
  const mainCy = 555;
  const coreCx = 538;
  const coreCy = 562;

  // Jagged fractured face perimeter (off-centre, tilted -16 deg)
  const fractureRim = [];
  const rimCount = 44;
  for (let i = 0; i < rimCount; i++) {
    let a = i * (360 / rimCount);
    // Asymmetric organic-crystalline break profile
    let rx = 315 + 24 * sin(a * 3 + 20) + 16 * cos(a * 5 - 40);
    let ry = 355 + 28 * cos(a * 2 - 15) + 18 * sin(a * 7 + 10);
    // Dramatic jagged step-fracture notch on upper-left & lower-left
    let jag = (i % 3 === 0) ? 16 : (i % 2 === 0 ? -11 : 4);
    if (a > 135 && a < 230) jag += 14 * sin(a * 9);
    let radX = (rx + jag) * cos(a);
    let radY = (ry + jag) * sin(a);
    // Rotate -16 degrees
    let rot = -16;
    let x = mainCx + radX * cos(rot) - radY * sin(rot);
    let y = mainCy + radX * sin(rot) + radY * cos(rot);
    fractureRim.push([x, y]);
  }

  // Bulbous 3D outer rind silhouette (sweeping out to upper-right, right, and bottom)
  const outerRindDome = [];
  for (let i = 0; i < rimCount; i++) {
    let a = i * (360 / rimCount);
    // The 3D sphere of the pomegranate bulges strongly toward upper-right & lower-right
    let bulge = 0;
    let angleDiff = ((a - (-18) + 540) % 360) - 180;
    if (Math.abs(angleDiff) < 135) {
      bulge = 148 * Math.pow(cos(angleDiff * (90 / 135)), 1.35);
    } else {
      bulge = 18 + 10 * sin(a * 4);
    }
    let pt = fractureRim[i];
    let dx = pt[0] - mainCx;
    let dy = pt[1] - mainCy;
    let d = Math.hypot(dx, dy) || 1;
    // Push outward plus shift toward upper-right (105, -35)
    let shiftX = bulge * 0.72 + (dx / d) * bulge * 0.55;
    let shiftY = -bulge * 0.12 + (dy / d) * bulge * 0.55;
    outerRindDome.push([pt[0] + shiftX, pt[1] + shiftY]);
  }

  // Calyx (the regal 6-pointed leathery crown at upper-right)
  const calyxNeckPoly = [
    [835, 225], [888, 175], [978, 128], [1038, 152],
    [1062, 208], [1005, 268], [945, 318], [875, 295]
  ];
  const calyxCrownPoly = [
    [888, 175],
    [932, 102], [958, 148], // Lobe 1
    [996, 86],  [1008, 145], // Lobe 2
    [1062, 104], [1042, 168], // Lobe 3
    [1102, 148], [1058, 198], // Lobe 4
    [1098, 212], [1035, 238], // Lobe 5
    [1055, 272], [975, 282],  // Lobe 6
    [945, 318]
  ];

  // Broken cleft wedge shard resting on the lower-left slate
  const shardCx = 248, shardCy = 868;
  const shardRindPoly = [
    [102, 815], [148, 725], [255, 708], [362, 765],
    [402, 865], [368, 978], [268, 1042], [158, 1018], [92, 928]
