    for (let pf of g.pavilionFacets) {
      if (pf.isHighlight) {
        facetBarePaper.push(pf.poly);
      } else {
        let s = pf.score + g.toneBias;
        if (s > 0.42) facetBlush.push(pf.poly);
        else if (s > 0.05) facetRoseMadder.push(pf.poly);
        else if (s > -0.32) facetAlizarin.push(pf.poly);
        else facetDeepClaret.push(pf.poly);
      }
    }
  }

  // Render crisp planar crystal facets using semi-transparent wash passes
  brush.noStroke();
  brush.wash("#FAD2DC", 85); // Pastel rose-quartz lit facets
  for (let p of facetBlush) drawPoly(p, 0);

  brush.wash("#D9365A", 78); // Rose madder facets
  for (let p of facetRoseMadder) drawPoly(p, 0);

  brush.wash("#9B0E2C", 92); // Alizarin crimson facets
  for (let p of facetAlizarin) drawPoly(p, 0);

  brush.wash("#5C051A", 115); // Deep claret facets
  for (let p of facetDeepClaret) drawPoly(p, 0);

  brush.wash("#33010D", 145); // Mulberry-claret abyss facets
  for (let p of facetAbyss) drawPoly(p, 0);

  // Faint internal seed pips glowing warmly inside the translucent center of the gems
  brush.wash("#F5B8B0", 85);
  for (let p of pipPolys) drawPoly(p, 0.15);

  // Step 7C: Razor-Sharp Bare Paper White Highlights!
  // Restores 100% pure untouched #FCF9F7 paper on all specular highlight facets
  brush.wash("#FCF9F7", 255);
  for (let p of facetBarePaper) drawPoly(p, 0);
  brush.noWash();

  // --------------------------------------------------------------------------
  // 8. FINE CRYSTAL HATCHING & TECHNICAL PEN INTERNAL FACET LINES
  // --------------------------------------------------------------------------
  // Delicate mineralogical hatching inside select shadow & midtone facets
  brush.noFill();
  brush.hatchStyle("rotring", "#4F0518", 0.32);
  for (let i = 0; i < facetDeepClaret.length; i += 2) {
    brush.hatch(4.5, (i * 37) % 180, { rand: 0.04 });
    drawPoly(facetDeepClaret[i], 0);
  }
  brush.hatchStyle("2H", "#B8284B", 0.30);
  for (let i = 0; i < facetAlizarin.length; i += 3) {
    brush.hatch(5.5, (i * 53) % 180, { rand: 0.04 });
    drawPoly(facetAlizarin[i], 0);
  }
  brush.noHatch();

  // Fine Pen Lines Drawing the Internal Facets ("fine pen lines draw the internal facets")
  // Pass 1: Internal pavilion refraction lines (from table vertices to culet) in rose-crimson ink
  brush.set("rotring", "#851633", 0.32);
  for (let g of allGems) {
    let k = g.T.length;
    for (let i = 0; i < k; i++) {
      brush.line(g.T[i][0], g.T[i][1], g.culet[0], g.culet[1]);
    }
  }

  // Pass 2: Crown-to-Table lateral facet ridges and table polygon in deep claret ink
  brush.set("rotring", "#470516", 0.42);
  for (let g of allGems) {
    drawPoly(g.T, 0);
    let k = g.V.length;
    for (let i = 0; i < k; i++) {
      brush.line(g.V[i][0], g.V[i][1], g.T[i][0], g.T[i][1]);
    }
  }

  // Pass 3: Outer polyhedral crystal boundaries in dark oxblood-claret ink
  brush.set("pen", "#2E020D", 0.48);
  for (let g of allGems) {
    drawPoly(g.V, 0);
  }

  // Pass 4: Razor-sharp white/silver facet ridge highlights along the bare-paper facets
  brush.set("cpencil", "#FCF9F7", 0.65);
  for (let g of allGems) {
    let hi = g.crownFacets[g.bestIdx].poly;
    brush.line(hi[0][0], hi[0][1], hi[1][0], hi[1][1]);
    brush.line(hi[2][0], hi[2][1], hi[3][0], hi[3][1]);
  }
  // Outline the bare paper highlight facets with a whisper-thin mineral grey-rose pen line
  brush.set("rotring", "#C4687E", 0.28);
  for (let p of facetBarePaper) {
    drawPoly(p, 0);
  }

  // --------------------------------------------------------------------------
  // 9. TRANSLUCENT CHALCEDONY MEMBRANE VEILS & RUBY JUICE DROPLETS
  // --------------------------------------------------------------------------
  // Semi-transparent papery chalcedony septa flaps veiling a few edge arils
  // ("Jewel-cold yet juicy" hyperrealist detail)
  const membraneVeils = [
    [[482, 468], [528, 455], [545, 512], [492, 535]],
    [[568, 468], [625, 478], [615, 532], [562, 522]],
    [[552, 588], [608, 612], [585, 668], [528, 635]],
    [[365, 482], [428, 495], [412, 545], [348, 522]]
  ];
  brush.noStroke();
  brush.wash("#FAF6F5", 145);
  for (let mv of membraneVeils) drawPoly(mv, 0.18);
  brush.noWash();

  brush.set("2H", "#B8AEBA", 0.4);
  for (let mv of membraneVeils) {
    drawPoly(mv, 0.18);
    brush.line(mv[0][0], mv[0][1], mv[2][0], mv[2][1]);
  }

  // Juicy translucent ruby watercolor droplets & tiny splatters on the slate and pith
  const droplets = [
    { x: 412, y: 948, r: 7.5 },
    { x: 458, y: 1032, r: 6.0 },
    { x: 505, y: 955, r: 5.5 },
    { x: 568, y: 1018, r: 8.5 },
    { x: 638, y: 1052, r: 5.0 },
    { x: 688, y: 988, r: 6.5 },
    { x: 342, y: 1005, r: 7.0 },
    { x: 198, y: 682, r: 5.5 },
    { x: 855, y: 985, r: 6.5 },
    { x: 912, y: 938, r: 5.0 },
    { x: 525, y: 882, r: 6.0 },
    { x: 312, y: 715, r: 5.5 }
  ];

  for (let d of droplets) {
    brush.noStroke();
    brush.fillBleed(0.12, "out");
    brush.fill("#C82349", 135);
    brush.circle(d.x, d.y, d.r, 0.25);
    brush.noFill();

    // Dark lower crescent rim of droplet
    brush.set("rotring", "#590418", 0.35);
    brush.arc(d.x, d.y, d.r, 15, 145);

    // Tiny bare-paper specular dot on upper-left of each droplet
    brush.noStroke();
    brush.wash("#FCF9F7", 255);
    drawPoly([
      [d.x - d.r * 0.45, d.y - d.r * 0.45],
      [d.x - d.r * 0.12, d.y - d.r * 0.52],
      [d.x - d.r * 0.18, d.y - d.r * 0.18],
      [d.x - d.r * 0.52, d.y - d.r * 0.15]
    ], 0);
    brush.noWash();
  }

  noLoop();
}

