// ============================================================================
// GEOMETRY HELPERS
// ============================================================================

function drawPoly(pts, curvature = 0.08) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(CLOSE);
}

// Map diagonal plait coordinates (u, v) to canvas (x, y) with subtle organic pandanus wave
function uvToXY(u, v) {
  const c = Math.SQRT1_2; // cos(45°) = 0.70710678
  const warpU = 4.5 * Math.sin(v * 0.0045 + u * 0.0015);
  const warpV = 4.5 * Math.cos(u * 0.0045 - v * 0.0015);
  const uu = u + warpU;
  const vv = v + warpV;
  const x = 600 + (uu - vv) * c;
  const y = 600 + (uu + vv) * c;
  return [x, y];
}

function buildLauhalaGrid() {
  const uEdges = [];
  const vEdges = [];
  const baseWidth = 74;

  let curU = -960;
  while (curU <= 960) {
    uEdges.push(curU);
    curU += baseWidth + random(-4.5, 4.5);
  }
  let curV = -960;
  while (curV <= 960) {
    vEdges.push(curV);
    curV += baseWidth + random(-4.5, 4.5);
  }

  const numU = uEdges.length - 1;
  const numV = vEdges.length - 1;

  const stripColors = [
    PALETTE.matStrawLight,
    PALETTE.matStrawWarm,
    PALETTE.matOchreBuff,
    PALETTE.matRawUmber,
    PALETTE.matBurntUmber,
    PALETTE.matDeepUmber
  ];

  // Assign each continuous strip a natural pandanus leaf tone
  const uTones = [];
  const vTones = [];
  for (let i = 0; i < numU; i++) {
    // Bias slightly warmer/darker toward lower-right
    const bias = map(i, 0, numU, -0.4, 0.8);
    const idx = constrain(floor(random(0, 5.2) + bias), 0, 5);
    uTones.push({ idx, col: stripColors[idx], grainSeed: random(1000) });
  }
  for (let j = 0; j < numV; j++) {
    const bias = map(j, 0, numV, -0.3, 0.7);
    const idx = constrain(floor(random(0, 5.2) + bias), 0, 5);
    vTones.push({ idx, col: stripColors[idx], grainSeed: random(1000) });
  }

  const cells = [];
  for (let i = 0; i < numU; i++) {
    for (let j = 0; j < numV; j++) {
      const u0 = uEdges[i], u1 = uEdges[i + 1];
      const v0 = vEdges[j], v1 = vEdges[j + 1];
      const uc = (u0 + u1) * 0.5;
      const vc = (v0 + v1) * 0.5;
      const [cx, cy] = uvToXY(uc, vc);

      // Cull cells well outside the 1200x1200 canvas
      if (cx < -75 || cx > 1275 || cy < -75 || cy > 1275) continue;

      const p00 = uvToXY(u0, v0);
      const p10 = uvToXY(u1, v0);
      const p11 = uvToXY(u1, v1);
      const p01 = uvToXY(u0, v1);

      // (i + j) % 2 === 0 => U-strip (running along V, i.e., 135° on screen) is ON TOP
      // (i + j) % 2 !== 0 => V-strip (running along U, i.e., 45° on screen) is ON TOP
      const uOnTop = (i + j) % 2 === 0;
      const topTone = uOnTop ? uTones[i] : vTones[j];
      const underTone = uOnTop ? vTones[j] : uTones[i];

      cells.push({
        i, j, u0, u1, v0, v1,
        cx, cy,
        pts: [p00, p10, p11, p01],
        uOnTop,
        topTone,
        underTone,
        stripAngle: uOnTop ? 135 : 45
      });
    }
  }

  return { uEdges, vEdges, numU, numV, uTones, vTones, stripColors, cells };
}

// ============================================================================
// LEI SPIRAL GEOMETRY (KUKUI NUTS, TI LEAVES, 'ILIMA STRAND)
// ============================================================================

function getSpiralPoint(thetaDeg) {
  const cx0 = 582;
  const cy0 = 576;
  const tNorm = (thetaDeg - 110) / 740;
  // Calm, loose spiral with gentle organic breathing
  const r =
    108 +
    tNorm * 358 +
    11 * Math.sin((thetaDeg * Math.PI) / 90) +
    7 * Math.cos((thetaDeg * Math.PI) / 60);
  const rad = (thetaDeg * Math.PI) / 180;
  const x = cx0 + r * Math.cos(rad);
  const y = cy0 + r * Math.sin(rad);
  return { x, y, r, thetaDeg };
}

function buildLeiGeometry() {
  // Sample dense spine along the spiral to place elements by true arc-length
  const spine = [];
  let totalLen = 0;
  const dTheta = 1.0;
  for (let th = 105; th <= 865; th += dTheta) {
    const pt = getSpiralPoint(th);
    if (spine.length > 0) {
      const prev = spine[spine.length - 1];
      const ds = Math.hypot(pt.x - prev.x, pt.y - prev.y);
      totalLen += ds;
    }
    spine.push({ ...pt, s: totalLen });
  }

  function pointAtArc(sTarget) {
    const clamped = constrain(sTarget, 0, totalLen);
    let lo = 0, hi = spine.length - 1;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (spine[mid].s < clamped) lo = mid + 1;
      else hi = mid;
    }
    const idx = max(1, lo);
    const p0 = spine[idx - 1];
    const p1 = spine[idx];
    const f = (clamped - p0.s) / max(0.0001, p1.s - p0.s);
    const x = lerp(p0.x, p1.x, f);
    const y = lerp(p0.y, p1.y, f);
    const dx = p1.x - p0.x;
    const dy = p1.y - p0.y;
    const tang = (Math.atan2(dy, dx) * 180) / Math.PI;
    return { x, y, tang, s: clamped };
  }

  const nuts = [];
  const tiKnots = [];
  const tiFronds = [];
  const ilimaUnder = [];
  const ilimaOver = [];

  // Leave room at inner start (0..165) and outer end (totalLen-185..totalLen) for braided ti-leaf ties
  const startS = 168;
  const endS = totalLen - 188;
  const numNuts = 31;
  const stepS = (endS - startS) / (numNuts - 1);

  for (let k = 0; k < numNuts; k++) {
    const sNut = startS + k * stepS + random(-2.5, 2.5);
    const pt = pointAtArc(sNut);

    // Kukui nut proportions: ovoid/sub-cordate ~41px semi-major, ~36px semi-minor
    const rx = random(38.5, 42.5);
    const ry = random(34.5, 38.5);
    const tilt = pt.tang + random(-11, 11);
    const ridgeOffset = random(-0.14, 0.14);

    // Check if an 'ilima flower rests close to this nut (for warm yellow lacquer reflection)
    const hasYellowNeighbor = k % 2 === 0 || k % 3 === 0;

    const nutObj = {
      index: k,
      x: pt.x,
      y: pt.y,
      rx,
      ry,
      rot: tilt,
      ridgeOffset,
      shapeSeed: random(1000),
      hasYellowNeighbor,
      yellowSide: k % 2 === 0 ? 1 : -1
    };
    nuts.push(nutObj);

    // Between consecutive nuts: twisted dried ti-leaf knot + threaded yellow 'ilima blossoms
    if (k < numNuts - 1) {
      const sMid = sNut + stepS * 0.5;
      const midPt = pointAtArc(sMid);
      const normRad = ((midPt.tang + 90) * Math.PI) / 180;
      const nx = Math.cos(normRad);
      const ny = Math.sin(normRad);

      tiKnots.push({
        x: midPt.x,
        y: midPt.y,
        tang: midPt.tang,
        w: random(22, 28),
        h: random(16, 22),
        seed: random(1000)
      });

      // Occasional crinkled dried ti-leaf blade tip flaring out from the inter-nut knot
      if (k % 2 === 1 || k % 5 === 0) {
        const side = k % 4 < 2 ? 1 : -1;
        const flareAng = midPt.tang + side * random(48, 82);
        tiFronds.push({
          x: midPt.x + nx * side * 8,
          y: midPt.y + ny * side * 8,
          angle: flareAng,
          len: random(36, 58),
          wid: random(14, 22),
          layer: k % 3 === 0 ? "over" : "under",
          seed: random(1000)
        });
      }

      // Threaded yellow 'ilima flowers nestled right between the kukui nuts
      const clusterCount = floor(random(2, 4.5));
      for (let c = 0; c < clusterCount; c++) {
        const sideShift = (c - (clusterCount - 1) * 0.5) * random(13, 18) + random(-4, 4);
        const alongShift = random(-7, 7);
        const tangRad = (midPt.tang * Math.PI) / 180;
        const fx = midPt.x + Math.cos(tangRad) * alongShift + nx * sideShift;
        const fy = midPt.y + Math.sin(tangRad) * alongShift + ny * sideShift;
        const flower = {
          x: fx,
          y: fy,
          r: random(13, 18.5),
          rot: midPt.tang + sideShift * 2.2 + random(-35, 35),
          type: c % 2 === 0 ? "cup" : "rosette",
          seed: random(1000)
        };
        if (abs(sideShift) > 10 && c % 2 === 0) {
          ilimaOver.push(flower);
        } else {
          ilimaUnder.push(flower);
        }
      }
    }
  }

  // Continuous delicate strand of yellow 'ilima winding alongside and weaving across the kukui spiral
  for (let s = 95; s <= totalLen - 95; s += 21) {
    const pt = pointAtArc(s);
    const normRad = ((pt.tang + 90) * Math.PI) / 180;
    // Graceful sinusoidal weave flanking the kukui nuts
    const wave = Math.sin(s * 0.0175 - 0.6);
    const offset = wave * 39 + 6 * Math.cos(s * 0.043);
    const fx = pt.x + Math.cos(normRad) * offset + random(-3, 3);
    const fy = pt.y + Math.sin(normRad) * offset + random(-3, 3);

    // Skip if right inside the center of a kukui nut unless crossing over the shoulder
    let minNutDist = 999;
    for (let n of nuts) {
      const d = Math.hypot(fx - n.x, fy - n.y);
      if (d < minNutDist) minNutDist = d;
    }

    const flower = {
      x: fx,
      y: fy,
      r: random(13.5, 19),
      rot: pt.tang + wave * 35 + random(-25, 25),
      type: random() < 0.55 ? "rosette" : "cup",
      seed: random(1000)
    };

    if (minNutDist < 34) {
      // Draping over the glossy shoulder of a kukui nut or between nuts
      ilimaOver.push(flower);
    } else if (abs(offset) > 26 && random() < 0.65) {
      ilimaUnder.push(flower);
    } else {
      ilimaOver.push(flower);
    }
  }

  // Terminal braided dried ti-leaf knots and leafy ribbons at inner start & outer end
  const innerStart = pointAtArc(startS - 18);
  const outerEnd = pointAtArc(endS + 18);

  // Inner terminal rosette & trailing dried ti-leaf ribbons
  for (let b = 0; b < 6; b++) {
    const ang = innerStart.tang + 180 + map(b, 0, 5, -52, 52) + random(-6, 6);
    tiFronds.push({
      x: innerStart.x,
      y: innerStart.y,
      angle: ang,
      len: random(68, 118),
      wid: random(16, 26),
      layer: b % 2 === 0 ? "under" : "over",
      seed: random(1000),
      isTerminal: true
    });
  }
  tiKnots.push({
    x: innerStart.x,
    y: innerStart.y,
    tang: innerStart.tang,
    w: 34,
    h: 26,
    seed: random(1000)
  });

  // Outer terminal tie & sweeping dried ti-leaf ribbons
  for (let b = 0; b < 7; b++) {
    const ang = outerEnd.tang + map(b, 0, 6, -48, 55) + random(-6, 6);
    tiFronds.push({
      x: outerEnd.x,
      y: outerEnd.y,
      angle: ang,
      len: random(85, 145),
      wid: random(18, 28),
      layer: b % 2 === 0 ? "under" : "over",
      seed: random(1000),
      isTerminal: true
    });
  }
  tiKnots.push({
    x: outerEnd.x,
    y: outerEnd.y,
    tang: outerEnd.tang,
    w: 36,
    h: 28,
    seed: random(1000)
  });

  return { nuts, tiKnots, tiFronds, ilimaUnder, ilimaOver };
}

// Generate 24-vertex organic kukui-nut polygon (slightly heart-shaped / sub-cordate with lateral facets)
function getKukuiPolygon(nut, scale = 1.0, offsetX = 0, offsetY = 0, insetAngle = null) {
  const pts = [];
  const steps = 24;
  const rotRad = (nut.rot * Math.PI) / 180;
  const cosR = Math.cos(rotRad);
  const sinR = Math.sin(rotRad);

  for (let i = 0; i < steps; i++) {
    const a = (i / steps) * Math.PI * 2;
    // Sub-cordate kukui shape: slightly pointed apex at a=0, slightly bilobed base at a=PI, subtle cheek facets
    const pointiness = 0.08 * Math.cos(a) - 0.045 * Math.cos(2 * a) + 0.03 * Math.cos(3 * a);
    const cheek = 0.035 * Math.sin(2 * a + nut.shapeSeed);
    let lx = nut.rx * scale * (Math.cos(a) + pointiness);
    let ly = nut.ry * scale * (Math.sin(a) * (1 - 0.06 * Math.cos(a)) + cheek);

    // Optional directional shift for crescent shadow glazes
    if (insetAngle !== null) {
      lx += insetAngle.dx;
      ly += insetAngle.dy;
    }

    const wx = nut.x + offsetX + lx * cosR - ly * sinR;
    const wy = nut.y + offsetY + lx * sinR + ly * cosR;
    pts.push([wx, wy]);
  }
  return pts;
}

// ============================================================================
// LAYER 1: RENDER WOVEN LAUHALA MAT
// ============================================================================

function renderLauhalaMat(matData) {
  const { uEdges, vEdges, numU, numV, uTones, vTones, stripColors, cells } = matData;

  // Pass 1A: Continuous watercolor strip washes batched by color
  brush.noStroke();
  brush.fillBleed(0.14, "out");
  brush.fillTexture(0.48, 0.28);

  for (let cIdx = 0; cIdx < stripColors.length; cIdx++) {
    brush.fill(stripColors[cIdx], 68);
    // U-strips
    for (let i = 0; i < numU; i++) {
      if (uTones[i].idx !== cIdx) continue;
      const u0 = uEdges[i], u1 = uEdges[i + 1];
      const poly = [
        uvToXY(u0, -960),
        uvToXY(u1, -960),
        uvToXY(u1, 960),
        uvToXY(u0, 960)
      ];
      drawPoly(poly, 0.02);
    }
    // V-strips
    for (let j = 0; j < numV; j++) {
      if (vTones[j].idx !== cIdx) continue;
      const v0 = vEdges[j], v1 = vEdges[j + 1];
      const poly = [
        uvToXY(-960, v0),
        uvToXY(960, v0),
        uvToXY(960, v1),
        uvToXY(-960, v1)
      ];
      drawPoly(poly, 0.02);
    }
  }

  // Pass 1B: Individual plaited cell glazes batched by tone to accentuate the over/under weave
  brush.fillBleed(0.08, "in");
  brush.fillTexture(0.52, 0.35);
  for (let cIdx = 0; cIdx < stripColors.length; cIdx++) {
    brush.fill(stripColors[cIdx], 82);
    for (let cell of cells) {
      if (cell.topTone.idx !== cIdx) continue;
      // Draw every top-strip cell for mid/dark umber strips, and a rich subset of straw strips
      if (cIdx >= 2 || (cell.i * 3 + cell.j * 5) % 2 === 0) {
        drawPoly(cell.pts, 0.02);
      }
    }
  }
  brush.noFill();

  // Pass 1C: Fine pencil hatching inside EVERY plaited square aligned with the top strip's grain
  for (let cell of cells) {
    const { pts, uOnTop, topTone, stripAngle, u0, u1, v0, v1 } = cell;

    // Fine directional pencil hatching showing the fibrous pandanus grain
    const hatchCol = topTone.idx >= 3 ? PALETTE.matCrevice : PALETTE.matDeepUmber;
    const spacing = map(topTone.idx, 0, 5, 6.2, 4.0);
    brush.noStroke();
    brush.hatchStyle("2H", hatchCol, 0.32);
    brush.hatch(spacing, stripAngle, { rand: 0.05, gradient: 0.28 });
    drawPoly(pts, 0);
    brush.noHatch();

    // Secondary burnt-umber cross-shading at the two tuck-under ends where the top strip dives under
    const tuckDepth = 14;
    if (uOnTop) {
      // U-strip runs along V (from v0 to v1), diving under at v0 and v1
      const tuckBand0 = [
        uvToXY(u0, v0),
        uvToXY(u1, v0),
        uvToXY(u1, v0 + tuckDepth),
        uvToXY(u0, v0 + tuckDepth)
      ];
      const tuckBand1 = [
        uvToXY(u0, v1 - tuckDepth),
        uvToXY(u1, v1 - tuckDepth),
        uvToXY(u1, v1),
        uvToXY(u0, v1)
      ];
      brush.hatchStyle("HB", PALETTE.matCrevice, 0.34);
      brush.hatch(3.4, 135, { rand: 0.04 });
      drawPoly(tuckBand0, 0);
      drawPoly(tuckBand1, 0);
      brush.noHatch();

      // Slight sunlit crown highlight in the middle of the bowed pandanus segment
      brush.set("cpencil", PALETTE.matHighlight, 0.42);
      for (let f = 0.22; f <= 0.78; f += 0.28) {
        const uu = lerp(u0, u1, f);
        const pA = uvToXY(uu, lerp(v0, v1, 0.28));
        const pB = uvToXY(uu, lerp(v0, v1, 0.65));
        brush.line(pA[0], pA[1], pB[0], pB[1]);
      }

      // Crisp seam shadow lines at the dive edges (v0 and v1)
      brush.set("2B", PALETTE.matCrevice, 0.46);
      brush.line(pts[0][0], pts[0][1], pts[1][0], pts[1][1]);
      brush.line(pts[3][0], pts[3][1], pts[2][0], pts[2][1]);
    } else {
      // V-strip runs along U (from u0 to u1), diving under at u0 and u1
      const tuckBand0 = [
        uvToXY(u0, v0),
        uvToXY(u0 + tuckDepth, v0),
        uvToXY(u0 + tuckDepth, v1),
        uvToXY(u0, v1)
      ];
      const tuckBand1 = [
        uvToXY(u1 - tuckDepth, v0),
        uvToXY(u1, v0),
        uvToXY(u1, v1),
        uvToXY(u1 - tuckDepth, v1)
      ];
      brush.hatchStyle("HB", PALETTE.matCrevice, 0.34);
      brush.hatch(3.4, 45, { rand: 0.04 });
      drawPoly(tuckBand0, 0);
      drawPoly(tuckBand1, 0);
      brush.noHatch();

      // Sunlit crown highlight in the middle of the bowed V-strip segment
      brush.set("cpencil", PALETTE.matHighlight, 0.42);
      for (let f = 0.22; f <= 0.78; f += 0.28) {
        const vv = lerp(v0, v1, f);
        const pA = uvToXY(lerp(u0, u1, 0.25), vv);
        const pB = uvToXY(lerp(u0, u1, 0.62), vv);
        brush.line(pA[0], pA[1], pB[0], pB[1]);
      }

      // Crisp seam shadow lines at the dive edges (u0 and u1)
      brush.set("2B", PALETTE.matCrevice, 0.46);
      brush.line(pts[0][0], pts[0][1], pts[3][0], pts[3][1]);
      brush.line(pts[1][0], pts[1][1], pts[2][0], pts[2][1]);
    }

    // Tiny dark corner pinholes where 4 strips interlock
    brush.set("fine_liner", PALETTE.matCrevice, 0.55);
    brush.line(pts[0][0] - 2, pts[0][1] - 2, pts[0][0] + 2, pts[0][1] + 2);
  }
}

// ============================================================================
// LAYER 2: SLANTED AFTERNOON CAST SHADOWS ON THE MAT
// ============================================================================

function renderAfternoonShadows(leiData) {
  const { nuts, tiKnots, tiFronds, ilimaUnder, ilimaOver } = leiData;

  brush.noStroke();

  // Pass 2A: Soft warm burnt-umber outer penumbra (slanted furthest along afternoon sun vector)
  brush.fill(PALETTE.shadowWarm, 88);
  brush.fillBleed(0.26, "out");
  brush.fillTexture(0.45, 0.2);

  for (let nut of nuts) {
    const poly = getKukuiPolygon(nut, 1.06, SUN_DX * 36, SUN_DY * 36);
    drawPoly(poly, 0.12);
  }
  for (let f of tiFronds) {
    const poly = getFrondPolygon(f, SUN_DX * 28, SUN_DY * 28, 1.05);
    drawPoly(poly, 0.1);
  }
  for (let fl of ilimaUnder) {
    const poly = getCirclePoly(fl.x + SUN_DX * 22, fl.y + SUN_DY * 22, fl.r * 1.08, 10);
    drawPoly(poly, 0.12);
  }
  for (let fl of ilimaOver) {
    const poly = getCirclePoly(fl.x + SUN_DX * 26, fl.y + SUN_DY * 26, fl.r * 1.05, 10);
    drawPoly(poly, 0.12);
  }

  // Pass 2B: Mid sepia core shadow on the weave
  brush.fill(PALETTE.shadowSepia, 115);
  brush.fillBleed(0.16, "out");
  brush.fillTexture(0.5, 0.3);

  for (let nut of nuts) {
    const poly = getKukuiPolygon(nut, 1.0, SUN_DX * 22, SUN_DY * 22);
    drawPoly(poly, 0.1);
  }
  for (let knot of tiKnots) {
    const poly = getCirclePoly(knot.x + SUN_DX * 18, knot.y + SUN_DY * 18, knot.w * 0.62, 10);
    drawPoly(poly, 0.1);
  }

  // Pass 2C: Tight Payne's grey + deep sepia contact occlusion directly under nuts & knots
  brush.fill(PALETTE.shadowPayne, 140);
  brush.fillBleed(0.08, "in");
  brush.fillTexture(0.4, 0.35);

  for (let nut of nuts) {
    const poly = getKukuiPolygon(nut, 0.94, SUN_DX * 9, SUN_DY * 9);
    drawPoly(poly, 0.1);
  }
  brush.noFill();

  // Pass 2D: Fine diagonal pencil hatching inside the cast shadows so the mat weave reads through the shadow
  for (let nut of nuts) {
    const shadowPoly = getKukuiPolygon(nut, 0.98, SUN_DX * 25, SUN_DY * 25);
    brush.noStroke();
    brush.hatchStyle("HB", PALETTE.shadowSepia, 0.34);
    brush.hatch(3.8, nut.index % 2 === 0 ? 45 : 135, { rand: 0.05 });
    drawPoly(shadowPoly, 0);
    brush.noHatch();
  }
}

function getCirclePoly(cx, cy, r, steps = 12) {
  const pts = [];
  for (let i = 0; i < steps; i++) {
    const a = (i / steps) * Math.PI * 2;
    const rad = r * (0.92 + 0.12 * Math.sin(i * 2.3));
    pts.push([cx + Math.cos(a) * rad, cy + Math.sin(a) * rad]);
  }
  return pts;
}

function getFrondPolygon(f, ox = 0, oy = 0, scale = 1.0) {
  const rad = (f.angle * Math.PI) / 180;
  const tx = Math.cos(rad);
  const ty = Math.sin(rad);
  const nx = -ty;
  const ny = tx;
  const L = f.len * scale;
  const W = f.wid * scale;
  const bx = f.x + ox;
  const by = f.y + oy;
  const curl = Math.sin(f.seed) * 14;

  return [
    [bx - nx * W * 0.25, by - ny * W * 0.25],
    [bx + tx * L * 0.35 - nx * W * 0.55, by + ty * L * 0.35 - ny * W * 0.55],
    [bx + tx * L * 0.72 - nx * (W * 0.35 - curl * 0.4), by + ty * L * 0.72 - ny * (W * 0.35 - curl * 0.4)],
    [bx + tx * L + nx * curl, by + ty * L + ny * curl],
    [bx + tx * L * 0.68 + nx * (W * 0.38 + curl * 0.5), by + ty * L * 0.68 + ny * (W * 0.38 + curl * 0.5)],
    [bx + tx * L * 0.32 + nx * W * 0.52, by + ty * L * 0.32 + ny * W * 0.52],
    [bx + nx * W * 0.25, by + ny * W * 0.25]
  ];
}

// ============================================================================
// LAYER 3 & 8: DRIED TI LEAVES (LĀʻĪ) — KNOTS, RIBBONS & TERMINAL TIES
// ============================================================================

function renderDriedTiLeaves(leiData, targetLayer) {
  const { tiKnots, tiFronds } = leiData;
  const activeFronds = tiFronds.filter((f) => f.layer === targetLayer);

  brush.noStroke();
  brush.fillBleed(0.08, "in");
  brush.fillTexture(0.55, 0.42);

  // Batch 1: Warm parchment/umber base of dried ti-leaf fronds
  brush.fill(PALETTE.tiUmber, 155);
  for (let f of activeFronds) {
    drawPoly(getFrondPolygon(f, 0, 0, 1.0), 0.12);
  }
  if (targetLayer === "under") {
    for (let knot of tiKnots) {
      drawPoly(getCirclePoly(knot.x, knot.y, knot.w * 0.56, 12), 0.12);
    }
  }

  // Batch 2: Deep sepia folds along the shadow side of each dried ti leaf
  brush.fill(PALETTE.tiSepia, 165);
  for (let f of activeFronds) {
    drawPoly(getFrondPolygon(f, SUN_DX * 2.5, SUN_DY * 2.5, 0.72), 0.1);
  }
  if (targetLayer === "over") {
    for (let knot of tiKnots) {
      // Twisted collar wrap sitting between consecutive nuts
      const rad = (knot.tang * Math.PI) / 180;
      const nx = -Math.sin(rad);
      const ny = Math.cos(rad);
      const collarPts = [
        [knot.x - nx * knot.h * 0.55 - Math.cos(rad) * 7, knot.y - ny * knot.h * 0.55 - Math.sin(rad) * 7],
        [knot.x + nx * knot.h * 0.55 - Math.cos(rad) * 5, knot.y + ny * knot.h * 0.55 - Math.sin(rad) * 5],
        [knot.x + nx * knot.h * 0.48 + Math.cos(rad) * 7, knot.y + ny * knot.h * 0.48 + Math.sin(rad) * 7],
        [knot.x - nx * knot.h * 0.48 + Math.cos(rad) * 5, knot.y - ny * knot.h * 0.48 + Math.sin(rad) * 5]
      ];
      drawPoly(collarPts, 0.12);
    }
  }
  brush.noFill();

  // Crinkled fibrous venation and sunlit parchment ridges on each dried ti leaf
  for (let f of activeFronds) {
    const rad = (f.angle * Math.PI) / 180;
    const tx = Math.cos(rad);
    const ty = Math.sin(rad);
    const nx = -ty;
    const ny = tx;
    const curl = Math.sin(f.seed) * 14;

    // Fine parallel leaf veins in dark sepia
    brush.set("fine_liner", PALETTE.tiDark, 0.42);
    for (let v = -2; v <= 2; v++) {
      const frac = v * 0.18;
      const p0 = [f.x + nx * f.wid * frac * 0.5, f.y + ny * f.wid * frac * 0.5];
      const p1 = [
        f.x + tx * f.len * 0.48 + nx * f.wid * frac,
        f.y + ty * f.len * 0.48 + ny * f.wid * frac
      ];
      const p2 = [
        f.x + tx * f.len * 0.96 + nx * (curl + f.wid * frac * 0.3),
        f.y + ty * f.len * 0.96 + ny * (curl + f.wid * frac * 0.3)
      ];
      brush.spline([p0, p1, p2], 0.35);
    }

    // Crisp sunlit parchment edge highlight along the sunward rib
    brush.set("cpencil", PALETTE.tiParchment, 0.55);
    const h0 = [f.x - nx * f.wid * 0.2, f.y - ny * f.wid * 0.2];
    const h1 = [f.x + tx * f.len * 0.45 - nx * f.wid * 0.42, f.y + ty * f.len * 0.45 - ny * f.wid * 0.42];
    const h2 = [f.x + tx * f.len * 0.88 + nx * curl * 0.6, f.y + ty * f.len * 0.88 + ny * curl * 0.6];
    brush.spline([h0, h1, h2], 0.35);
  }

  // Twisted cordage striations on the inter-nut knots
  if (targetLayer === "over") {
    for (let knot of tiKnots) {
      const rad = (knot.tang * Math.PI) / 180;
      const tx = Math.cos(rad);
      const ty = Math.sin(rad);
      const nx = -ty;
      const ny = tx;

      brush.set("fine_liner", PALETTE.tiDark, 0.48);
      for (let t = -3; t <= 3; t++) {
        const s = t * 2.6;
        brush.line(
          knot.x + tx * s - nx * 9,
          knot.y + ty * s - ny * 9,
          knot.x + tx * (s + 4) + nx * 9,
          knot.y + ty * (s + 4) + ny * 9
        );
      }
      // Sunlit twist highlight on upper-left of knot
      brush.set("cpencil", PALETTE.tiParchment, 0.52);
      brush.line(
        knot.x - SUN_DX * 5 - nx * 5,
        knot.y - SUN_DY * 5 - ny * 5,
        knot.x - SUN_DX * 2 + nx * 3,
        knot.y - SUN_DY * 2 + ny * 3
      );
    }
  }
}

// ============================================================================
// LAYER 4: HYPERREAL KUKUI NUTS (SEPIA & PAYNE'S GREY GLAZES + WINDOW REFLECTION)
// ============================================================================

function renderKukuiNuts(nuts) {
  brush.noStroke();

  // Glaze 1: Warm Mahogany-Sepia subsurface base across the entire nut
  brush.fill(PALETTE.nutAmberGlow, 175);
  brush.fillBleed(0.06, "in");
  brush.fillTexture(0.45, 0.35);
  for (let nut of nuts) {
    drawPoly(getKukuiPolygon(nut, 1.0), 0.1);
  }

  // Glaze 2: Rich Medium-Dark Sepia covering ~88% of shell, shifted toward shadow side
  brush.fill(PALETTE.nutSepiaMid, 185);
  brush.fillBleed(0.07, "in");
  brush.fillTexture(0.5, 0.38);
  for (let nut of nuts) {
    drawPoly(getKukuiPolygon(nut, 0.95, SUN_DX * 2.2, SUN_DY * 2.2), 0.1);
  }

  // Glaze 3: Deep Sepia body glaze
  brush.fill(PALETTE.nutSepiaDeep, 195);
  brush.fillBleed(0.06, "in");
  for (let nut of nuts) {
    drawPoly(getKukuiPolygon(nut, 0.88, SUN_DX * 3.8, SUN_DY * 3.8), 0.1);
  }

  // Glaze 4: Cool Payne's Grey glaze over the core shadow hemisphere
  brush.fill(PALETTE.nutPayneGlaze, 185);
  brush.fillBleed(0.08, "in");
  brush.fillTexture(0.52, 0.4);
  for (let nut of nuts) {
    // Shifted slightly away from the very edge so the shadow rim retains warm mat bounce light
    drawPoly(getKukuiPolygon(nut, 0.78, SUN_DX * 4.5, SUN_DY * 4.5), 0.1);
  }

  // Glaze 5: Deep Black-Brown Lacquer Abyss in the heart of each nut
  brush.fill(PALETTE.nutLacquerCore, 200);
  brush.fillBleed(0.05, "in");
  for (let nut of nuts) {
    drawPoly(getKukuiPolygon(nut, 0.64, SUN_DX * 3.0, SUN_DY * 3.0), 0.1);
  }
  brush.noFill();

  // Per-Nut Fine Modeling: Contour Hatching, Longitudinal Ridge, Bounced Light & Crisp Window Reflection
  for (let nut of nuts) {
    const rotRad = (nut.rot * Math.PI) / 180;
    const tx = Math.cos(rotRad);
    const ty = Math.sin(rotRad);
    const nx = -ty;
    const ny = tx;

    // 1. Curved graphite/sepia shading strokes hugging the spherical shell contour
    brush.set("graphite_shader", PALETTE.nutLacquerCore, 0.55);
    for (let ring = 0.55; ring <= 0.88; ring += 0.16) {
      const arcPts = [];
      for (let a = -35; a <= 115; a += 25) {
        const ar = (a * Math.PI) / 180;
        const px = nut.x + Math.cos(ar) * nut.rx * ring;
        const py = nut.y + Math.sin(ar) * nut.ry * ring;
        arcPts.push([px, py]);
      }
      brush.spline(arcPts, 0.4);
    }

    // 2. Warm Straw-Ochre Reflected Light Rim along the lower-right shadow edge (bounced from mat)
    brush.set("cpencil", PALETTE.nutBounceLight, 0.62);
    const rimPts = [];
    for (let a = -20; a <= 88; a += 18) {
      const ar = (a * Math.PI) / 180;
      const px = nut.x + Math.cos(ar) * (nut.rx * 0.91);
      const py = nut.y + Math.sin(ar) * (nut.ry * 0.91);
      rimPts.push([px, py]);
    }
    brush.spline(rimPts, 0.45);

    // 3. If a yellow 'ilima blossom sits beside this nut, add a subtle golden reflection in the dark lacquer!
    if (nut.hasYellowNeighbor) {
      const side = nut.yellowSide;
      brush.set("cpencil", PALETTE.ilimaGold, 0.48);
      const yRefPts = [];
      for (let s = -0.35; s <= 0.35; s += 0.35) {
        const px = nut.x + tx * nut.rx * s + nx * side * nut.ry * 0.82;
        const py = nut.y + ty * nut.rx * s + ny * side * nut.ry * 0.82;
        yRefPts.push([px, py]);
      }
      brush.spline(yRefPts, 0.4);
    }

    // 4. Subtle longitudinal dorsal ridge running from pole to pole across the nut
    const ridgeMidOffset = nut.ridgeOffset * nut.ry;
    const rP0 = [nut.x - tx * nut.rx * 0.86, nut.y - ty * nut.rx * 0.86];
    const rP1 = [nut.x + nx * ridgeMidOffset, nut.y + ny * ridgeMidOffset];
    const rP2 = [nut.x + tx * nut.rx * 0.88, nut.y + ty * nut.rx * 0.88];
    brush.set("fine_liner", PALETTE.nutLacquerCore, 0.5);
    brush.spline([rP0, rP1, rP2], 0.35);
    // Faint warm ridge highlight on the sunward half
    brush.set("cpencil", PALETTE.nutAmberGlow, 0.45);
    brush.spline([rP0, rP1], 0.35);

    // 5. Drilled threading hole dimple at the apex pole where the cord enters
    const holeX = nut.x + tx * nut.rx * 0.84;
    const holeY = nut.y + ty * nut.rx * 0.84;
    brush.set("fine_liner", PALETTE.nutLacquerCore, 0.75);
    brush.arc(holeX, holeY, 4.2, 0, 360);
    // Tiny specular catchlight on the rim of the drilled hole
    brush.set("fine_liner", PALETTE.nutWindowWarm, 0.48);
    brush.arc(holeX, holeY, 4.6, 120, 250);

    // 6. Crisp Outer Contour in Deep Sepia / Payne's Grey
    const contour = getKukuiPolygon(nut, 0.99);
    brush.set("fine_liner", PALETTE.nutSepiaDeep, 0.52);
    drawPoly(contour, 0.12);

    // 7. THE CRISP LIFTED WINDOW REFLECTION (4-pane casement window warped over the upper-left dome)
    renderWarpedWindowReflection(nut);
  }
}

function renderWarpedWindowReflection(nut) {
  // Position the window reflection on the sun-facing upper-left dome (-148 degrees)
  const refAngle = (SUN_ANGLE + 180 + (nut.shapeSeed % 14) - 7) * (Math.PI / 180);
  const ux = Math.cos(refAngle); // points toward upper-left (-0.85)
  const uy = Math.sin(refAngle); // points toward upper-left (-0.53)
  // Tangent vector along the latitude of the dome
  const vx = -uy;
  const vy = ux;

  const rDome = Math.min(nut.rx, nut.ry);
  const winCx = nut.x + ux * rDome * 0.46;
  const winCy = nut.y + uy * rDome * 0.46;

  // Map local window coordinates (s along radial dome slope, t along tangent arc) to curved nut surface
  function mapWin(s, t) {
    // Spherical dome warp: lines curve around the nut's convexity
    const bend = -0.18 * (t * t) * rDome;
    const radialDist = s * rDome * 0.24 + bend;
    const tangDist = t * rDome * 0.31 * (1 - 0.16 * s);
    return [
      winCx + ux * radialDist + vx * tangDist,
      winCy + uy * radialDist + vy * tangDist
    ];
  }

  // Soft warm amber-sky halation glow around the lifted window reflection
  brush.noStroke();
  brush.wash(PALETTE.nutAmberGlow, 95);
  const haloPoly = [
    mapWin(-0.78, -0.85),
    mapWin(0.78, -0.85),
    mapWin(0.78, 0.85),
    mapWin(-0.78, 0.85)
  ];
  drawPoly(haloPoly, 0.15);
  brush.noWash();

  // Four warped window panes separated by the curved dark muntin crossbars (+)
  const gap = 0.085;
  const panes = [
    // Upper-left & upper-right panes (brightest sunlit sky)
    { s0: gap, s1: 0.62, t0: -0.68, t1: -gap, col: PALETTE.nutWindowBright, op: 242 },
    { s0: gap, s1: 0.62, t0: gap, t1: 0.68, col: PALETTE.nutWindowBright, op: 235 },
    // Lower-left & lower-right panes (slightly softer warm-sky reflection)
    { s0: -0.58, s1: -gap, t0: -0.66, t1: -gap, col: PALETTE.nutWindowWarm, op: 220 },
    { s0: -0.58, s1: -gap, t0: gap, t1: 0.66, col: PALETTE.nutWindowSky, op: 195 }
  ];

  for (let p of panes) {
    const quad = [
      mapWin(p.s0, p.t0),
      mapWin(p.s1, p.t0),
      mapWin(p.s1, p.t1),
      mapWin(p.s0, p.t1)
    ];
    brush.noStroke();
    brush.wash(p.col, p.op);
    drawPoly(quad, 0.06);
    brush.noWash();

    // Crisp lifted watercolor/gouache edge on each window pane
    brush.set("fine_liner", PALETTE.nutWindowBright, 0.45);
    brush.line(quad[0][0], quad[0][1], quad[1][0], quad[1][1]);
    brush.line(quad[1][0], quad[1][1], quad[2][0], quad[2][1]);
  }

  // Reinforce the curved dark window muntin crossbar (+) between the panes for optical hyperrealism
  brush.set("fine_liner", PALETTE.nutSepiaDeep, 0.52);
  const mV0 = mapWin(-0.62, 0);
  const mV1 = mapWin(0, 0);
  const mV2 = mapWin(0.65, 0);
  brush.spline([mV0, mV1, mV2], 0.35);

  const mH0 = mapWin(0, -0.72);
  const mH1 = mapWin(0, 0);
  const mH2 = mapWin(0, 0.72);
  brush.spline([mH0, mH1, mH2], 0.35);

  // Tiny secondary pinpoint specular glint near the crown of the nut
  const glintPt = mapWin(-0.88, 0.25);
  brush.set("fine_liner", PALETTE.nutWindowBright, 0.65);
  brush.line(glintPt[0] - 1.5, glintPt[1] - 1, glintPt[0] + 2, glintPt[1] + 1);
}

// ============================================================================
// LAYER 6 & 8: THE YELLOW ʻILIMA STRAND (SINGLE CHROMATIC ACCENT)
// ============================================================================

function getPetalPoly(fx, fy, angleDeg, len, wid, shiftX = 0, shiftY = 0) {
  const rad = (angleDeg * Math.PI) / 180;
  const tx = Math.cos(rad);
  const ty = Math.sin(rad);
  const nx = -ty;
  const ny = tx;
  const bx = fx + shiftX;
  const by = fy + shiftY;

  // Delicate crinkled fan-shaped 'ilima petal
  return [
    [bx, by],
    [bx + tx * len * 0.42 - nx * wid * 0.38, by + ty * len * 0.42 - ny * wid * 0.38],
    [bx + tx * len * 0.88 - nx * wid * 0.56, by + ty * len * 0.88 - ny * wid * 0.56],
    [bx + tx * len * 1.02 - nx * wid * 0.18, by + ty * len * 1.02 - ny * wid * 0.18],
    [bx + tx * len * 0.96 + nx * wid * 0.22, by + ty * len * 0.96 + ny * wid * 0.22],
    [bx + tx * len * 0.85 + nx * wid * 0.54, by + ty * len * 0.85 + ny * wid * 0.54],
    [bx + tx * len * 0.4 + nx * wid * 0.36, by + ty * len * 0.4 + ny * wid * 0.36]
  ];
}

function renderIlimaFlowers(flowerList) {
  if (!flowerList || flowerList.length === 0) return;

  brush.noStroke();
  brush.fillBleed(0.07, "out");
  brush.fillTexture(0.45, 0.32);

  // Batch 1: Deep Saffron-Ochre shadow petals
  brush.fill(PALETTE.ilimaOchre, 185);
  for (let fl of flowerList) {
    const numPetals = 5;
    for (let p = 0; p < numPetals; p++) {
      const ang = fl.rot + p * 72 + ((fl.seed * (p + 1)) % 16) - 8;
      // Draw shadow-side petals slightly larger
      const poly = getPetalPoly(fl.x, fl.y, ang, fl.r * 1.02, fl.r * 0.68, SUN_DX * 2, SUN_DY * 2);
      drawPoly(poly, 0.14);
    }
  }

  // Batch 2: Luminous Golden-Yellow main petal bodies
  brush.fill(PALETTE.ilimaGold, 210);
  for (let fl of flowerList) {
    const numPetals = 5;
    for (let p = 0; p < numPetals; p++) {
      const ang = fl.rot + p * 72 + 12;
      const poly = getPetalPoly(fl.x, fl.y, ang, fl.r * 0.94, fl.r * 0.62);
      drawPoly(poly, 0.15);
    }
  }

  // Batch 3: Sunlit Lemon-Gold upper petals (facing upper-left sun)
  brush.fill(PALETTE.ilimaBright, 220);
  for (let fl of flowerList) {
    for (let p = 0; p < 3; p++) {
      const ang = SUN_ANGLE + 180 + (p - 1) * 58 + ((fl.seed * 7) % 24) - 12;
      const poly = getPetalPoly(fl.x, fl.y, ang, fl.r * 0.88, fl.r * 0.55, -SUN_DX * 1.5, -SUN_DY * 1.5);
      drawPoly(poly, 0.15);
    }
  }
  brush.noFill();

  // Crisp botanical detailing: petal folds, delicate veins, sunlit ruffled rims, and deep amber calyx centers
  for (let fl of flowerList) {
    // Ruffled sunlit petal rims in pale butter-yellow
    brush.set("cpencil", PALETTE.ilimaHighlight, 0.55);
    for (let p = 0; p < 3; p++) {
      const ang = (SUN_ANGLE + 180 + (p - 1) * 58) * (Math.PI / 180);
      const tx = Math.cos(ang);
      const ty = Math.sin(ang);
      const nx = -ty;
      const ny = tx;
      const rim0 = [fl.x + tx * fl.r * 0.82 - nx * fl.r * 0.35, fl.y + ty * fl.r * 0.82 - ny * fl.r * 0.35];
      const rim1 = [fl.x + tx * fl.r * 0.96, fl.y + ty * fl.r * 0.96];
      const rim2 = [fl.x + tx * fl.r * 0.82 + nx * fl.r * 0.35, fl.y + ty * fl.r * 0.82 + ny * fl.r * 0.35];
      brush.spline([rim0, rim1, rim2], 0.4);
    }

    // Fine warm-ochre petal creases & radiating veins
    brush.set("fine_liner", PALETTE.ilimaShadow, 0.38);
    for (let p = 0; p < 5; p++) {
      const ang = ((fl.rot + p * 72) * Math.PI) / 180;
      brush.line(
        fl.x + Math.cos(ang) * 2.5,
        fl.y + Math.sin(ang) * 2.5,
        fl.x + Math.cos(ang) * fl.r * 0.72,
        fl.y + Math.sin(ang) * fl.r * 0.72
      );
    }

    // Tiny deep-amber calyx & stamen center
    brush.set("fine_liner", PALETTE.ilimaCalyx, 0.65);
    brush.arc(fl.x, fl.y, 2.8, 0, 360);
    brush.set("cpencil", PALETTE.ilimaHighlight, 0.5);
    brush.line(fl.x - 1.5, fl.y - 1.5, fl.x + 0.5, fl.y - 0.5);
  }
}

