function renderFinalMicroDetails(leiData) {
  // 1. A few detached yellow 'ilima petals resting naturally on the woven mat near the coil
  const fallenPetals = [
    { x: 355, y: 745, ang: 28, r: 16 },
    { x: 382, y: 768, ang: 112, r: 14 },
    { x: 825, y: 315, ang: -42, r: 15 },
    { x: 765, y: 890, ang: 64, r: 16.5 },
    { x: 495, y: 465, ang: 155, r: 13.5 }
  ];

  for (let fp of fallenPetals) {
    // Tiny afternoon shadow of the fallen petal on the mat
    const shPoly = getPetalPoly(fp.x, fp.y, fp.ang, fp.r, fp.r * 0.65, SUN_DX * 9, SUN_DY * 9);
    brush.noStroke();
    brush.fill(PALETTE.shadowWarm, 110);
    brush.fillBleed(0.1, "out");
    drawPoly(shPoly, 0.14);

    // Golden petal body
    const petPoly = getPetalPoly(fp.x, fp.y, fp.ang, fp.r, fp.r * 0.65);
    brush.fill(PALETTE.ilimaGold, 215);
    drawPoly(petPoly, 0.14);
    brush.noFill();

    // Sunlit edge & vein
    brush.set("cpencil", PALETTE.ilimaHighlight, 0.52);
    brush.line(fp.x, fp.y, fp.x + Math.cos((fp.ang * Math.PI) / 180) * fp.r * 0.85, fp.y + Math.sin((fp.ang * Math.PI) / 180) * fp.r * 0.85);
    brush.set("fine_liner", PALETTE.ilimaShadow, 0.35);
    drawPoly(petPoly, 0.14);
  }

  // 2. Delicate curled wisps of dried ti-leaf fiber around the terminal knots and inter-nut ties
  for (let knot of leiData.tiKnots) {
    if (random() < 0.55) continue;
    const baseAng = knot.tang + (random() < 0.5 ? 75 : -75);
    const r0 = (baseAng * Math.PI) / 180;
    const r1 = ((baseAng + random(-35, 35)) * Math.PI) / 180;
    const p0 = [knot.x, knot.y];
    const p1 = [knot.x + Math.cos(r0) * 24, knot.y + Math.sin(r0) * 24];
    const p2 = [p1[0] + Math.cos(r1) * 22, p1[1] + Math.sin(r1) * 22];

    // Hairline shadow on mat
    brush.set("fine_liner", PALETTE.shadowSepia, 0.32);
    brush.spline(
      [
        [p0[0] + SUN_DX * 12, p0[1] + SUN_DY * 12],
        [p1[0] + SUN_DX * 14, p1[1] + SUN_DY * 14],
        [p2[0] + SUN_DX * 15, p2[1] + SUN_DY * 15]
      ],
      0.45
    );

    // Sunlit dried fiber
    brush.set("fine_liner", PALETTE.tiUmber, 0.38);
    brush.spline([p0, p1, p2], 0.45);
  }
}

const PAPER = "#fffef7";
const INK = "#0c0d12";

const MAGENTA_1 = "#ff007f";
const MAGENTA_2 = "#d90368";
const MAGENTA_3 = "#ff5ca8";
const MAGENTA_DARK = "#80003a";

const GREEN_1 = "#38b000";
const GREEN_2 = "#70e000";
const GREEN_3 = "#007200";
const GREEN_LIGHT = "#b5e48c";

const YELLOW_1 = "#ffbe0b";
const YELLOW_2 = "#ffee32";
const YELLOW_3 = "#fb8500";
const YELLOW_DARK = "#e85d04";

const CYAN_1 = "#00bbf9";
const CYAN_2 = "#00f5d4";
const CYAN_3 = "#0077b6";
const CYAN_LIGHT = "#90e0ef";

const CHROME_DARK = "#1a1d28";
const CHROME_MID = "#5c6b7c";
const CHROME_LIGHT = "#ced8e2";

const BELL_X = 432;
const BELL_Y = 668;
const BELL_R = 238;
const DOME_R = 216;

let masks = [];

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(7391);
  noiseSeed(7391);
  background(PAPER);
}

function cleanPts(pts, minDist = 0.8) {
  if (!pts || pts.length === 0) return [];
  let out = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    let prev = out[out.length - 1];
    let cur = pts[i];
    if (Math.hypot(cur[0] - prev[0], cur[1] - prev[1]) >= minDist) {
      out.push(cur);
    }
  }
  while (
    out.length > 2 &&
    Math.hypot(out[out.length - 1][0] - out[0][0], out[out.length - 1][1] - out[0][1]) < minDist
  ) {
    out.pop();
  }
  return out;
}

function polyArea(pts) {
  if (pts.length < 3) return 0;
  let a = 0;
  for (let i = 0; i < pts.length; i++) {
    let p1 = pts[i];
    let p2 = pts[(i + 1) % pts.length];
    a += p1[0] * p2[1] - p2[0] * p1[1];
  }
  return Math.abs(a) * 0.5;
}

function addCircleMask(cx, cy, r, layer) {
  masks.push({ type: "circle", cx, cy, r, rBound: r, layer });
}

function addPolyMask(rawPts, layer) {
  let pts = cleanPts(rawPts, 0.5);
  if (pts.length < 3) return;
  let cx = 0, cy = 0;
  for (let p of pts) {
    cx += p[0];
    cy += p[1];
  }
  cx /= pts.length;
  cy /= pts.length;
  let rBound = 0;
  for (let p of pts) {
    let d = Math.hypot(p[0] - cx, p[1] - cy);
    if (d > rBound) rBound = d;
  }
  let edges = [];
  for (let i = 0; i < pts.length; i++) {
    let p1 = pts[i];
    let p2 = pts[(i + 1) % pts.length];
    let dx = p2[0] - p1[0];
    let dy = p2[1] - p1[1];
    let len = Math.hypot(dx, dy) || 1;
    let nx = dy / len;
    let ny = -dx / len;
    if ((p1[0] - cx) * nx + (p1[1] - cy) * ny < 0) {
      nx = -nx;
      ny = -ny;
    }
    edges.push({ x0: p1[0], y0: p1[1], nx, ny });
  }
  masks.push({ type: "poly", pts, edges, cx, cy, rBound, layer });
}

function isPointInsideMask(x, y, m, margin = 0) {
  let dx = x - m.cx;
  let dy = y - m.cy;
  let rb = m.rBound + margin;
  if (dx * dx + dy * dy > rb * rb) return false;
  if (m.type === "circle") {
    let rr = m.r + margin;
    return dx * dx + dy * dy < rr * rr;
  } else {
    for (let i = 0; i < m.edges.length; i++) {
      let e = m.edges[i];
      if ((x - e.x0) * e.nx + (y - e.y0) * e.ny >= margin) return false;
    }
    return true;
  }
}

function isPointOccluded(x, y, layer, margin = 0) {
  for (let i = 0; i < masks.length; i++) {
    let m = masks[i];
    if (m.layer <= layer) continue;
    if (isPointInsideMask(x, y, m, margin)) return true;
  }
  return false;
}

function clipPolyHalfPlane(pts, x0, y0, nx, ny) {
  if (pts.length < 3) return [];
  let out = [];
  for (let i = 0; i < pts.length; i++) {
    let cur = pts[i];
    let prev = pts[(i + pts.length - 1) % pts.length];
    let dCur = (cur[0] - x0) * nx + (cur[1] - y0) * ny;
    let dPrev = (prev[0] - x0) * nx + (prev[1] - y0) * ny;
    if (dCur >= 0) {
      if (dPrev < 0) {
        let t = dPrev / (dPrev - dCur);
        out.push([prev[0] + t * (cur[0] - prev[0]), prev[1] + t * (cur[1] - prev[1])]);
      }
      out.push(cur);
    } else if (dPrev >= 0) {
      let t = dPrev / (dPrev - dCur);
      out.push([prev[0] + t * (cur[0] - prev[0]), prev[1] + t * (cur[1] - prev[1])]);
    }
  }
  return out;
}

function clipPolyAgainstMasks(rawPts, layer) {
  let pts = rawPts;
  if (pts.length < 3) return [];
  for (let mIdx = 0; mIdx < masks.length; mIdx++) {
    let m = masks[mIdx];
    if (m.layer <= layer) continue;
    let px = 0, py = 0;
    for (let p of pts) {
      px += p[0];
      py += p[1];
    }
    px /= pts.length;
    py /= pts.length;
    let pr = 0;
    for (let p of pts) {
      let d = Math.hypot(p[0] - px, p[1] - py);
      if (d > pr) pr = d;
    }
    let distCenters = Math.hypot(px - m.cx, py - m.cy);
    if (distCenters > pr + m.rBound + 2) continue;

    let inCount = 0;
    let outX = 0, outY = 0, outCount = 0;
    for (let p of pts) {
      if (isPointInsideMask(p[0], p[1], m, 0.5)) {
        inCount++;
      } else {
        outX += p[0];
        outY += p[1];
        outCount++;
      }
    }
    if (inCount === pts.length) return [];
    let centerInside = isPointInsideMask(px, py, m, 1.5);
    if (inCount === 0 && !centerInside && distCenters > m.rBound + pr * 0.45) continue;

    let rx = outCount > 0 ? outX / outCount : px;
    let ry = outCount > 0 ? outY / outCount : py;

    if (m.type === "circle") {
      let ux = rx - m.cx;
      let uy = ry - m.cy;
      let ulen = Math.hypot(ux, uy) || 1;
      ux /= ulen;
      uy /= ulen;
      let bx = m.cx + ux * m.r;
      let by = m.cy + uy * m.r;
      pts = clipPolyHalfPlane(pts, bx, by, ux, uy);
    } else {
      let bestEdge = m.edges[0];
      let bestDist = -1e9;
      for (let e of m.edges) {
        let d = (rx - e.x0) * e.nx + (ry - e.y0) * e.ny;
        if (d > bestDist) {
          bestDist = d;
          bestEdge = e;
        }
      }
      pts = clipPolyHalfPlane(pts, bestEdge.x0, bestEdge.y0, bestEdge.nx, bestEdge.ny);
    }
    if (pts.length < 3) return [];
  }
  return pts;
}

function drawShape(rawPts, opts = {}) {
  let layer = opts.layer !== undefined ? opts.layer : 0;
  let clipped = opts.skipClip ? rawPts : clipPolyAgainstMasks(rawPts, layer);
  let pts = cleanPts(clipped, 0.7);
  if (pts.length < 3) return;
  let area = polyArea(pts);
  if (area < 3.5) return;

  if (opts.washCol) {
    brush.wash(opts.washCol, opts.washAlpha !== undefined ? opts.washAlpha : 242);
  } else {
    brush.noWash();
  }

  let minAreaForHatch = opts.minHatchArea !== undefined ? opts.minHatchArea : 160;
  if (opts.hatchCol && area > minAreaForHatch) {
    brush.hatchStyle(opts.hatchBrush || "marker", opts.hatchCol, opts.hatchWeight || 0.65);
    brush.hatch(opts.hatchDist || 6.5, opts.hatchAngle !== undefined ? opts.hatchAngle : 45, {
      rand: opts.hatchRand !== undefined ? opts.hatchRand : 0.02,
    });
  } else {
    brush.noHatch();
  }

  if (opts.strokeCol !== null) {
    brush.set(opts.strokeBrush || "rotring", opts.strokeCol || INK, opts.strokeWeight || 0.55);
  } else {
    brush.noStroke();
  }

  brush.beginShape(opts.curvature !== undefined ? opts.curvature : 0.03);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);

  brush.noWash();
  brush.noHatch();
}

function drawClippedLine(x1, y1, x2, y2, layer, brushName = "rotring", col = INK, weight = 0.55) {
  let len = Math.hypot(x2 - x1, y2 - y1);
  if (len < 1) return;
  let steps = Math.max(2, Math.ceil(len / 5));
  let segStart = null;
  brush.noWash();
  brush.noHatch();
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let x = x1 + (x2 - x1) * t;
    let y = y1 + (y2 - y1) * t;
    let occ = isPointOccluded(x, y, layer, 0.4);
    if (!occ) {
      if (!segStart) segStart = [x, y];
    } else {
      if (segStart) {
        let prevT = (i - 1) / steps;
        let px = x1 + (x2 - x1) * prevT;
        let py = y1 + (y2 - y1) * prevT;
        if (Math.hypot(px - segStart[0], py - segStart[1]) >= 1.2) {
          brush.set(brushName, col, weight);
          brush.line(segStart[0], segStart[1], px, py);
        }
        segStart = null;
      }
    }
  }
  if (segStart) {
    if (Math.hypot(x2 - segStart[0], y2 - segStart[1]) >= 1.2) {
      brush.set(brushName, col, weight);
      brush.line(segStart[0], segStart[1], x2, y2);
    }
  }
}

function drawClippedPolyline(pts, layer, brushName = "rotring", col = INK, weight = 0.55, curvature = 0.2) {
  if (!pts || pts.length < 2) return;
  brush.noWash();
  brush.noHatch();
  let run = [];
  for (let i = 0; i < pts.length; i++) {
    let p = pts[i];
    if (!isPointOccluded(p[0], p[1], layer, 0.4)) {
      run.push(p);
    } else {
      if (run.length >= 2) {
        let cRun = cleanPts(run, 1.0);
        if (cRun.length >= 2) {
          brush.set(brushName, col, weight);
          if (cRun.length === 2) {
            brush.line(cRun[0][0], cRun[0][1], cRun[1][0], cRun[1][1]);
          } else {
            brush.spline(cRun, curvature);
          }
        }
      }
      run = [];
    }
  }
  if (run.length >= 2) {
    let cRun = cleanPts(run, 1.0);
    if (cRun.length >= 2) {
      brush.set(brushName, col, weight);
      if (cRun.length === 2) {
        brush.line(cRun[0][0], cRun[0][1], cRun[1][0], cRun[1][1]);
      } else {
        brush.spline(cRun, curvature);
      }
    }
  }
}

function makeCirclePts(cx, cy, r, n = 20, startAng = 0) {
  let pts = [];
  for (let i = 0; i < n; i++) {
    let a = startAng + (i * 360) / n;
    pts.push([cx + r * cos(a), cy + r * sin(a)]);
  }
  return pts;
}

function makeRingSectorPts(cx, cy, rIn, rOut, a0, a1, steps = 8) {
  let pts = [];
  for (let i = 0; i <= steps; i++) {
    let a = a0 + ((a1 - a0) * i) / steps;
    pts.push([cx + rOut * cos(a), cy + rOut * sin(a)]);
  }
  for (let i = steps; i >= 0; i--) {
    let a = a0 + ((a1 - a0) * i) / steps;
    pts.push([cx + rIn * cos(a), cy + rIn * sin(a)]);
  }
  return pts;
}

// =========================================================================
// SPHERICAL CHROME BELL ENVIRONMENT MAPPING
// =========================================================================
function envToBell(az, el) {
  let tilt = -12;
  let rx0 = cos(el) * sin(az);
  let ry0 = sin(el);
  let rz0 = cos(el) * cos(az);

  let rx = rx0 * cos(tilt) - ry0 * sin(tilt);
  let ry = rx0 * sin(tilt) + ry0 * cos(tilt);
  let rz = rz0;

  let clampedRz = Math.max(-0.96, rz);
  let denom = Math.sqrt(2 * (1 + clampedRz));
  let nx = rx / denom;
  let ny = ry / denom;

  return [BELL_X + DOME_R * nx, BELL_Y + DOME_R * ny];
}

function makeBellPatch(az0, az1, el0, el1, nAz = 6, nEl = 5) {
  let pts = [];
  for (let i = 0; i <= nAz; i++) {
    let az = az0 + ((az1 - az0) * i) / nAz;
    pts.push(envToBell(az, el0));
  }
  for (let i = 1; i <= nEl; i++) {
    let el = el0 + ((el1 - el0) * i) / nEl;
    pts.push(envToBell(az1, el));
  }
  for (let i = nAz - 1; i >= 0; i--) {
    let az = az0 + ((az1 - az0) * i) / nAz;
    pts.push(envToBell(az, el1));
  }
  for (let i = nEl - 1; i >= 1; i--) {
    let el = el0 + ((el1 - el0) * i) / nEl;
    pts.push(envToBell(az0, el));
  }
  return pts;
}

