function getRibbonQuad(r, s0 = -0.5, s1 = 0.5, t0 = 0, t1 = 1) {
  let steps = 5;
  let left = [];
  let right = [];
  for (let i = 0; i <= steps; i++) {
    let t = t0 + ((t1 - t0) * i) / steps;
    let mt = 1 - t;
    let cx = mt * mt * r.x0 + 2 * mt * t * r.ctrlX + t * t * r.x1;
    let cy = mt * mt * r.y0 + 2 * mt * t * r.ctrlY + t * t * r.y1;
    let tx = 2 * mt * (r.ctrlX - r.x0) + 2 * t * (r.x1 - r.ctrlX);
    let ty = 2 * mt * (r.ctrlY - r.y0) + 2 * t * (r.y1 - r.ctrlY);
    let tlen = Math.hypot(tx, ty) || 1;
    let nx = -ty / tlen;
    let ny = tx / tlen;
    let wLocal = r.w * (0.85 + 0.3 * t);
    left.push([cx + nx * wLocal * s0, cy + ny * wLocal * s0]);
    right.push([cx + nx * wLocal * s1, cy + ny * wLocal * s1]);
  }
  return left.concat(right.reverse());
}

function registerAllMasks() {
  masks = [];

  // Layer 3: Chrome Bicycle Bell Dome, Clamp Bracket, and Striker Lever
