  // Bell Striker Thumb Lever Mask (lower-right of bell)
  addPolyMask(
    [
      [540, 815],
      [615, 805],
      [716, 905],
      [690, 962],
      [608, 938],
      [525, 865],
    ],
    3.1
  );

  // Bell Steel Mounting Bracket (lower-left strut)
  addPolyMask(
    [
      [0, 895],
      [252, 745],
      [295, 815],
      [0, 1005],
    ],
    2.8
  );

  // Layer 2: Mirrored Star Appliqués
  for (let st of STAR_CONFIGS) {
    addCircleMask(st.cx, st.cy, st.r * 0.94, 2.0);
  }

  // Layer 4: Tassel Caps, PomPoms, Beads & Ribbons
  for (let b of tasselBeads) {
    addCircleMask(b.cx, b.cy, b.r - 1, b.layer);
  }
  for (let c of tasselCaps) {
    addPolyMask(
      [
        [c.cx - c.w * 0.32, c.cy - c.h * 0.5],
        [c.cx + c.w * 0.32, c.cy - c.h * 0.5],
        [c.cx + c.w * 0.52, c.cy + c.h * 0.5],
        [c.cx - c.w * 0.52, c.cy + c.h * 0.5],
      ],
      c.layer
    );
  }
  for (let p of tasselPomPoms) {
    addCircleMask(p.cx, p.cy, p.r * 0.88, p.layer);
  }
  for (let r of tasselRibbons) {
    let quad = getRibbonQuad(r, -0.48, 0.48, 0.02, 0.96);
    // Split ribbon into 2 convex halves for tight mask occlusion
    let mid = Math.floor(quad.length / 2);
    let pA = [quad[0], quad[2], quad[3], quad[mid + 2], quad[mid + 3], quad[quad.length - 1]];
    let pB = [quad[2], quad[5], quad[mid], quad[mid + 2]];
    addPolyMask(pA, r.layer);
    addPolyMask(pB, r.layer);
  }
}

