function drawPanelBorders() {
  let layer = 1.0;
  let cols = [MAGENTA_1, YELLOW_1, GREEN_1, CYAN_1];

  // Outer bolted sheet-metal strips (top, bottom, left, right)
  let tileW = 40;
  // Top & Bottom Checkerboard & Bolted Seam
  for (let side = 0; side < 2; side++) {
    let yBase = side === 0 ? 0 : 1128;
    for (let i = 0; i < 30; i++) {
      let x0 = i * tileW;
      let colA = cols[(i + side * 2) % cols.length];
      let colB = cols[(i + 1 + side * 2) % cols.length];

      // Row 1
      drawShape(
        [
          [x0, yBase],
          [x0 + tileW, yBase],
          [x0 + tileW, yBase + 36],
          [x0, yBase + 36],
        ],
        {
          layer,
          washCol: colA,
          hatchCol: colA,
          hatchAngle: 45,
          hatchDist: 6,
          strokeWeight: 0.55,
        }
      );
      // Specular corner triangle left as bare paper inside every 3rd tile
      if (i % 3 === 0) {
        drawShape(
          [
            [x0 + 5, yBase + 5],
            [x0 + 22, yBase + 5],
            [x0 + 5, yBase + 22],
          ],
          { layer, washCol: PAPER, strokeWeight: 0.4 }
        );
      }

      // Row 2
      drawShape(
        [
          [x0, yBase + 36],
          [x0 + tileW, yBase + 36],
          [x0 + tileW, yBase + 72],
          [x0, yBase + 72],
        ],
        {
          layer,
          washCol: colB,
          hatchCol: colB,
          hatchAngle: -45,
          hatchDist: 6,
          strokeWeight: 0.55,
        }
      );

      // Chrome dome rivets every 2 tiles
      if (i % 2 === 1) {
        let rx = x0 + tileW * 0.5;
        let ry = yBase + 36;
        drawShape(makeCirclePts(rx, ry, 10, 14), {
          layer,
          washCol: CHROME_DARK,
          strokeWeight: 0.6,
