        // Bare paper specular crescent on rivet
        drawShape(makeCirclePts(rx - 2.5, ry - 2.5, 4.5, 10), {
          layer,
          washCol: null,
          strokeWeight: 0.4,
        });
      }
    }
  }

  // Left & Right Vertical Trim Strips
  for (let side = 0; side < 2; side++) {
    let xBase = side === 0 ? 0 : 1140;
    for (let j = 2; j < 28; j++) {
      let y0 = j * 40;
      let colA = cols[(j + side) % cols.length];
      let colB = cols[(j + 2 + side) % cols.length];
      drawShape(
        [
          [xBase, y0],
          [xBase + 30, y0],
          [xBase + 30, y0 + 40],
          [xBase, y0 + 40],
        ],
        { layer, washCol: colA, hatchCol: colA, hatchAngle: 30, strokeWeight: 0.5 }
      );
      drawShape(
        [
          [xBase + 30, y0],
          [xBase + 60, y0],
          [xBase + 60, y0 + 40],
          [xBase + 30, y0 + 40],
        ],
        { layer, washCol: colB, hatchCol: colB, hatchAngle: -30, strokeWeight: 0.5 }
      );
    }
  }

  // Scalloped Lotus Molding Arch along Top (y = 72..112) and Bottom (y = 1088..1128)
  for (let i = 1; i < 22; i++) {
    let cx = i * 52 + 10;
    let colP = cols[i % cols.length];
    let colSub = cols[(i + 1) % cols.length];
    // Top scalloped arch
    let archTop = [];
    for (let k = 0; k <= 10; k++) {
      let a = (k * 180) / 10;
      archTop.push([cx - 26 + (k * 52) / 10, 72 + sin(a) * 36]);
    }
    drawShape(archTop, {
      layer: 0.8,
      washCol: colP,
      hatchCol: colP,
      hatchAngle: 90,
      strokeWeight: 0.55,
    });
    drawShape(makeCirclePts(cx, 86, 8, 10), {
      layer: 0.8,
      washCol: colSub,
      strokeWeight: 0.45,
