    // Bottom scalloped arch
    let archBot = [];
    for (let k = 0; k <= 10; k++) {
      let a = (k * 180) / 10;
      archBot.push([cx - 26 + (k * 52) / 10, 1128 - sin(a) * 36]);
    }
    drawShape(archBot, {
      layer: 0.8,
      washCol: colSub,
      hatchCol: colSub,
      hatchAngle: 90,
      strokeWeight: 0.55,
    });
  }
}

function drawPeacockOcellus(cx, cy, r, angle, layer = 0.2) {
  if (isPointOccluded(cx, cy, layer, -r * 0.7)) return;

  let ca = cos(angle);
  let sa = sin(angle);
  function rotPt(lx, ly) {
    return [cx + lx * ca - ly * sa, cy + lx * sa + ly * ca];
  }

  // 1. Radiating barbed feather frond segments around the eye
  let nFronds = 16;
  let frondCols = [GREEN_1, GREEN_2, YELLOW_1, GREEN_3, CYAN_2, GREEN_1];
  for (let i = 0; i < nFronds; i++) {
    let a0 = -155 + (i * 310) / nFronds;
    let a1 = a0 + 310 / nFronds - 2;
    let rIn = r * 0.55;
    let rOut = r * (1.05 + 0.18 * cos(a0 * 0.8));
    let p0 = rotPt(rIn * cos(a0), rIn * sin(a0));
    let p1 = rotPt(rOut * cos(a0), rOut * sin(a0));
    let p2 = rotPt(rOut * cos(a1), rOut * sin(a1));
    let p3 = rotPt(rIn * cos(a1), rIn * sin(a1));
    let fCol = frondCols[i % frondCols.length];
    drawShape([p0, p1, p2, p3], {
      layer,
      washCol: fCol,
      hatchCol: fCol,
      hatchAngle: angle + (a0 + a1) * 0.5,
      hatchDist: 5.5,
      strokeWeight: 0.45,
      curvature: 0.02,
    });
  }

  // 2. Outer Magenta Enamel Ring (with reserved bare-paper glare notch)
  let magRing = [];
  for (let i = 0; i < 18; i++) {
    let a = (i * 360) / 18;
    let rx = r * 0.72 * cos(a);
    let ry = r * 0.62 * sin(a);
    magRing.push(rotPt(rx, ry));
  }
  drawShape(magRing, {
    layer: layer + 0.02,
    washCol: MAGENTA_1,
    hatchCol: MAGENTA_2,
    hatchAngle: angle + 45,
    hatchDist: 5,
    strokeWeight: 0.55,
  });

  // 3. Chrome Yellow Inner Oval (split to leave a bare-paper specular crescent!)
  let yelPts = [];
  for (let i = 0; i <= 14; i++) {
    let a = -40 + (i * 290) / 14;
    yelPts.push(rotPt(r * 0.52 * cos(a), r * 0.45 * sin(a)));
  }
  drawShape(yelPts, {
    layer: layer + 0.03,
    washCol: YELLOW_1,
    hatchCol: YELLOW_3,
    hatchAngle: angle,
    hatchDist: 5,
    strokeWeight: 0.5,
  });

  // Bare-paper highlight crescent on the upper-left of the yellow ring
  let specPts = [];
  for (let i = 0; i <= 6; i++) {
    let a = 250 + (i * 70) / 6;
    specPts.push(rotPt(r * 0.52 * cos(a), r * 0.45 * sin(a)));
  }
  for (let i = 6; i >= 0; i--) {
    let a = 250 + (i * 70) / 6;
    specPts.push(rotPt(r * 0.36 * cos(a), r * 0.31 * sin(a)));
  }
  drawShape(specPts, {
    layer: layer + 0.04,
    washCol: null,
    strokeWeight: 0.45,
  });

  // 4. Electric Cyan Heart
  let cyanPts = [];
  for (let i = 0; i < 16; i++) {
    let a = (i * 360) / 16;
    cyanPts.push(rotPt(r * 0.35 * cos(a) + r * 0.04, r * 0.3 * sin(a)));
  }
  drawShape(cyanPts, {
    layer: layer + 0.05,
    washCol: CYAN_1,
    hatchCol: CYAN_3,
    hatchAngle: angle - 30,
    hatchDist: 4.5,
    strokeWeight: 0.5,
  });

  // 5. Deep Ink Pupil with Notch
  let pupilPts = [];
  for (let i = 0; i < 12; i++) {
    let a = (i * 360) / 12;
    let rad = i === 6 ? r * 0.08 : r * 0.18;
    pupilPts.push(rotPt(rad * cos(a) + r * 0.07, rad * sin(a)));
  }
  drawShape(pupilPts, {
    layer: layer + 0.06,
    washCol: INK,
    strokeWeight: 0.5,
  });
}

function drawFolkRosette(cx, cy, r, layer = 0.25) {
  if (isPointOccluded(cx, cy, layer, -r * 0.7)) return;
  let petals = 10;
  let pCols = [MAGENTA_1, YELLOW_1, MAGENTA_3, YELLOW_2];

  // Outer serrated parrot-green leaves
  for (let i = 0; i < 6; i++) {
    let a = i * 60 + 15;
    let lx = cx + cos(a) * r * 1.15;
    let ly = cy + sin(a) * r * 1.15;
    let nx = -sin(a) * r * 0.26;
    let ny = cos(a) * r * 0.26;
    let mx = cx + cos(a) * r * 0.62;
    let my = cy + sin(a) * r * 0.62;
    drawShape(
      [
        [cx + cos(a) * r * 0.3, cy + sin(a) * r * 0.3],
        [mx + nx, my + ny],
        [lx, ly],
        [mx - nx, my - ny],
      ],
      {
        layer: layer - 0.02,
        washCol: i % 2 === 0 ? GREEN_1 : GREEN_2,
        hatchCol: GREEN_3,
        hatchAngle: a,
        strokeWeight: 0.5,
      }
    );
  }

  // Enamel Lotus/Marigold Petals
  for (let i = 0; i < petals; i++) {
    let a0 = (i * 360) / petals;
    let aMid = a0 + 180 / petals;
    let a1 = a0 + 360 / petals;
    let col = pCols[i % pCols.length];
    let pts = [
      [cx + cos(a0) * r * 0.24, cy + sin(a0) * r * 0.24],
      [cx + cos(a0 + 6) * r * 0.78, cy + sin(a0 + 6) * r * 0.78],
      [cx + cos(aMid) * r * 0.96, cy + sin(aMid) * r * 0.96],
      [cx + cos(a1 - 6) * r * 0.78, cy + sin(a1 - 6) * r * 0.78],
      [cx + cos(a1) * r * 0.24, cy + sin(a1) * r * 0.24],
    ];
    drawShape(pts, {
      layer,
      washCol: col,
      hatchCol: col,
      hatchAngle: aMid,
      hatchDist: 5,
      strokeWeight: 0.5,
    });
  }

  // Cyan & Bare-Paper Center Medallion
  drawShape(makeCirclePts(cx, cy, r * 0.32, 14), {
    layer: layer + 0.02,
    washCol: CYAN_1,
    hatchCol: CYAN_3,
    strokeWeight: 0.55,
  });
  drawShape(makeCirclePts(cx - r * 0.06, cy - r * 0.06, r * 0.13, 10), {
    layer: layer + 0.03,
    washCol: null,
    strokeWeight: 0.45,
  });
}

function drawBackgroundEnamelTapestry() {
  // 1. Tile the entire interior panel (60..1140, 72..1128) with an interlocking
  // sunburst & scalloped enamel field so zero background is left empty
  let hubX = 635;
  let hubY = 445;
  let rays = 44;
  let rings = 14;
  let maxR = 880;
  let palette = [GREEN_1, CYAN_1, YELLOW_1, MAGENTA_1, GREEN_2, CYAN_2, YELLOW_3, MAGENTA_2];

  for (let rIdx = 0; rIdx < rings; rIdx++) {
    let r0 = rIdx * (maxR / rings);
    let r1 = (rIdx + 1) * (maxR / rings);
    for (let aIdx = 0; aIdx < rays; aIdx++) {
      let a0 = (aIdx * 360) / rays + (rIdx % 2) * (180 / rays);
      let a1 = a0 + 360 / rays;
      let aMid = (a0 + a1) * 0.5;
      let mx = hubX + ((r0 + r1) * 0.5) * cos(aMid);
      let my = hubY + ((r0 + r1) * 0.5) * sin(aMid);
      if (mx < 45 || mx > 1155 || my < 55 || my > 1145) continue;

      let p0 = [hubX + r0 * cos(a0), hubY + r0 * sin(a0)];
      let p1 = [hubX + r1 * cos(a0), hubY + r1 * sin(a0)];
      let pTip = [hubX + (r1 + 14) * cos(aMid), hubY + (r1 + 14) * sin(aMid)];
      let p2 = [hubX + r1 * cos(a1), hubY + r1 * sin(a1)];
      let p3 = [hubX + r0 * cos(a1), hubY + r0 * sin(a1)];

      let col = palette[(rIdx * 3 + aIdx) % palette.length];
      // Leave every 9th tile with a bare-paper specular glare sliver
      let isGlare = (rIdx + aIdx * 2) % 9 === 0;
      drawShape([p0, p1, pTip, p2, p3], {
        layer: 0.05,
        washCol: isGlare ? null : col,
        hatchCol: isGlare ? null : col,
        hatchAngle: aMid,
        hatchDist: 6.5,
        strokeWeight: 0.45,
        curvature: 0.02,
      });
    }
  }

  // 2. Radiating Train of 42 Peacock Eye-Feathers (Ocelli) across the panel
  let ocelliArcs = [
    { r: 225, count: 9, aStart: -155, aEnd: 145, size: 54 },
    { r: 345, count: 13, aStart: -165, aEnd: 165, size: 62 },
    { r: 475, count: 15, aStart: -170, aEnd: 175, size: 68 },
    { r: 615, count: 14, aStart: -175, aEnd: 175, size: 72 },
  ];

  for (let arc of ocelliArcs) {
    for (let i = 0; i < arc.count; i++) {
      let a = arc.aStart + (i * (arc.aEnd - arc.aStart)) / Math.max(1, arc.count - 1);
      let ox = hubX + arc.r * cos(a);
      let oy = hubY + arc.r * sin(a);
      if (ox < 85 || ox > 1115 || oy < 105 || oy > 1095) continue;
      // Skip the immediate head/neck window so the peacock head reads cleanly
      if (ox > 465 && ox < 635 && oy > 155 && oy < 360) continue;
      drawPeacockOcellus(ox, oy, arc.size, a, 0.2);
    }
  }

  // 3. Folk Marigold & Lotus Rosettes in interstitial zones
  let rosettes = [
    [125, 495, 58],
    [255, 435, 52],
    [355, 195, 48],
    [135, 765, 56],
    [295, 995, 58],
    [585, 995, 62],
    [845, 945, 54],
    [1085, 475, 50],
    [1085, 835, 52],
    [855, 195, 54],
  ];
  for (let r of rosettes) {
    drawFolkRosette(r[0], r[1], r[2], 0.25);
  }
}

function drawHandPaintedPeacock() {
  let layer = 0.5;

  // 1. SCULPTED FOLDED WING (x ~ 575..855, y ~ 355..615)
  // Wing primary flight feathers sweeping backward/downward
  let wingHubX = 635;
  let wingHubY = 435;
  let flightCols = [MAGENTA_1, CYAN_1, YELLOW_1, GREEN_1, MAGENTA_2, CYAN_2];
  for (let i = 0; i < 11; i++) {
    let a = -12 + i * 9.5;
    let rIn = 80;
    let rOut = 235 - i * 4;
    let aW = 8.2;
    let p0 = [wingHubX + rIn * cos(a - aW * 0.5), wingHubY + rIn * sin(a - aW * 0.5)];
    let p1 = [wingHubX + (rOut - 18) * cos(a - aW * 0.55), wingHubY + (rOut - 18) * sin(a - aW * 0.55)];
    let pTip = [wingHubX + rOut * cos(a), wingHubY + rOut * sin(a)];
    let p2 = [wingHubX + (rOut - 18) * cos(a + aW * 0.55), wingHubY + (rOut - 18) * sin(a + aW * 0.55)];
    let p3 = [wingHubX + rIn * cos(a + aW * 0.5), wingHubY + rIn * sin(a + aW * 0.5)];

    let col = flightCols[i % flightCols.length];
    drawShape([p0, p1, pTip, p2, p3], {
      layer: layer + 0.02,
      washCol: col,
      hatchCol: col,
      hatchAngle: a,
      hatchDist: 5,
      strokeWeight: 0.6,
    });
    // Bare-paper specular shaft stripe along every alternate flight feather
    if (i % 2 === 0) {
      let s0 = [wingHubX + (rIn + 25) * cos(a - 1.4), wingHubY + (rIn + 25) * sin(a - 1.4)];
      let s1 = [wingHubX + (rOut - 32) * cos(a - 1.2), wingHubY + (rOut - 32) * sin(a - 1.2)];
      let s2 = [wingHubX + (rOut - 32) * cos(a + 1.2), wingHubY + (rOut - 32) * sin(a + 1.2)];
      let s3 = [wingHubX + (rIn + 25) * cos(a + 1.4), wingHubY + (rIn + 25) * sin(a + 1.4)];
      drawShape([s0, s1, s2, s3], {
        layer: layer + 0.03,
        washCol: null,
        strokeWeight: 0.4,
      });
    }
  }

  // Wing Covert Feather Rows (Parrot Green & Chrome Yellow scalloped rows)
  for (let row = 2; row >= 0; row--) {
    let rRow = 72 + row * 38;
    let nScales = 7 + row * 2;
    for (let j = 0; j < nScales; j++) {
      let a = -15 + (j * 105) / nScales;
      let scX = wingHubX + rRow * cos(a);
      let scY = wingHubY + rRow * sin(a);
      let scR = 24;
      let scCol = row === 0 ? MAGENTA_1 : row === 1 ? YELLOW_1 : GREEN_1;
      drawShape(makeCirclePts(scX, scY, scR, 12, a), {
        layer: layer + 0.05 + (2 - row) * 0.01,
        washCol: scCol,
        hatchCol: scCol,
        hatchAngle: a,
        hatchDist: 5,
        strokeWeight: 0.55,
      });
      if ((j + row) % 2 === 0) {
        drawShape(makeCirclePts(scX - 4, scY - 4, scR * 0.35, 8), {
          layer: layer + 0.08,
          washCol: null,
          strokeWeight: 0.4,
        });
      }
    }
  }

  // Ornate Shoulder Rosette on Wing
  drawFolkRosette(wingHubX + 10, wingHubY + 8, 52, layer + 0.1);

  // 2. S-CURVED NECK & SCALLOPED BREAST SCALES
  // Spine from Head (538, 240) through Throat (575, 330) to Breast (565, 435) and Belly (605, 515)
  let neckSpine = [
    { x: 605, y: 515, w: 138 },
    { x: 582, y: 478, w: 128 },
    { x: 565, y: 440, w: 116 },
    { x: 562, y: 402, w: 102 },
    { x: 568, y: 365, w: 86 },
    { x: 574, y: 330, w: 72 },
    { x: 566, y: 295, w: 62 },
    { x: 550, y: 262, w: 54 },
  ];

  let cyanShades = [CYAN_1, CYAN_3, CYAN_2, CYAN_1];
  // Draw overlapping scales from bottom (belly) up to throat so upper scales overlap lower scales
  for (let rIdx = 0; rIdx < neckSpine.length; rIdx++) {
    let row = neckSpine[rIdx];
    let nSc = Math.max(4, Math.floor(row.w / 18));
    let isCollar = rIdx === 4; // Folk-art yellow & magenta necklace collar row!
    for (let k = 0; k < nSc; k++) {
      let f = (k + 0.5) / nSc - 0.5;
      let sx = row.x + f * row.w;
      let sy = row.y + Math.abs(f) * 14;
      let sr = (row.w / nSc) * 0.68;
      let col = isCollar
        ? k % 2 === 0
          ? YELLOW_1
          : MAGENTA_1
        : cyanShades[(rIdx + k) % cyanShades.length];

      // Scale body
      let scPts = [];
      for (let m = 0; m < 12; m++) {
        let a = (m * 360) / 12;
        scPts.push([sx + sr * 0.92 * cos(a), sy + sr * 1.15 * sin(a)]);
      }
      drawShape(scPts, {
        layer: layer + 0.12 + rIdx * 0.005,
        washCol: col,
        hatchCol: col,
        hatchAngle: 85,
        hatchDist: 4.5,
        strokeWeight: 0.55,
      });

      // Bare-paper specular highlight crescent on every 2nd scale
      if ((rIdx + k) % 2 === 0) {
        let hiPts = [
          [sx - sr * 0.45, sy - sr * 0.25],
          [sx, sy - sr * 0.68],
          [sx + sr * 0.45, sy - sr * 0.25],
          [sx, sy - sr * 0.35],
        ];
        drawShape(hiPts, {
          layer: layer + 0.122 + rIdx * 0.005,
          washCol: null,
          strokeWeight: 0.38,
        });
      }
    }
  }

  // Crisp outer contour lines of the peacock's neck & breast
  let leftNeckEdge = neckSpine.map((r) => [r.x - r.w * 0.52, r.y]);
  let rightNeckEdge = neckSpine.map((r) => [r.x + r.w * 0.52, r.y]);
  drawClippedPolyline(leftNeckEdge, layer + 0.18, "rotring", INK, 0.9, 0.25);
  drawClippedPolyline(rightNeckEdge, layer + 0.18, "rotring", INK, 0.9, 0.25);

  // 3. ROYAL CREST PLUMES (Kalgi) fanning above the head
  let crestBaseX = 556;
  let crestBaseY = 204;
  let plumeCols = [CYAN_1, MAGENTA_1, YELLOW_1, GREEN_1];
  for (let i = 0; i < 9; i++) {
    let a = -112 + i * 11;
    let len = 82 + sin(i * 40) * 10;
    let tx = crestBaseX + len * cos(a);
    let ty = crestBaseY + len * sin(a);
    drawClippedLine(crestBaseX, crestBaseY, tx, ty, layer + 0.15, "rotring", INK, 0.7);

    // Spade feather tip
    let nx = -sin(a) * 9;
    let ny = cos(a) * 9;
    let bx = crestBaseX + (len - 18) * cos(a);
    let by = crestBaseY + (len - 18) * sin(a);
    let ex = crestBaseX + (len + 8) * cos(a);
    let ey = crestBaseY + (len + 8) * sin(a);
    let pCol = plumeCols[i % plumeCols.length];
    drawShape(
      [
        [bx, by],
        [tx + nx, ty + ny],
        [ex, ey],
        [tx - nx, ty - ny],
      ],
      {
        layer: layer + 0.17,
        washCol: pCol,
        hatchCol: pCol,
        hatchAngle: a,
        strokeWeight: 0.5,
      }
    );
  }

  // 4. PEACOCK HEAD, FACIAL MASK, EYE & HOOKED BEAK
  let hx = 538;
  let hy = 232;
  // Cranium dome in Electric Cyan
  let headPts = [
    [hx - 36, hy - 6],
    [hx - 18, hy - 30],
    [hx + 18, hy - 32],
    [hx + 40, hy - 14],
    [hx + 38, hy + 20],
    [hx + 8, hy + 32],
    [hx - 28, hy + 22],
  ];
  drawShape(headPts, {
    layer: layer + 0.2,
    washCol: CYAN_1,
    hatchCol: CYAN_3,
    hatchAngle: -15,
    hatchDist: 4.5,
    strokeWeight: 0.75,
    curvature: 0.12,
  });

  // Bare-paper white facial cheek patch around the eye
  let cheekPts = [
    [hx - 26, hy - 4],
    [hx - 4, hy - 16],
    [hx + 22, hy - 10],
    [hx + 24, hy + 10],
    [hx - 2, hy + 16],
    [hx - 24, hy + 10],
  ];
  drawShape(cheekPts, {
    layer: layer + 0.22,
    washCol: null,
    strokeWeight: 0.65,
    curvature: 0.1,
  });

  // Expressive Almond Eye (Golden Iris + Black Pupil + Bare-Paper Catchlight)
  drawShape(makeCirclePts(hx - 2, hy - 1, 10, 12), {
    layer: layer + 0.23,
    washCol: YELLOW_1,
    strokeWeight: 0.6,
  });
  drawShape(makeCirclePts(hx - 3, hy - 1, 5.5, 10), {
    layer: layer + 0.24,
    washCol: INK,
    strokeWeight: 0.5,
  });
  drawShape(makeCirclePts(hx - 5, hy - 3, 2.5, 8), {
    layer: layer + 0.25,
    washCol: null,
    strokeWeight: 0.35,
  });

  // Hooked Chrome-Yellow Beak pointing left
  // Upper Mandible (with bare-paper ridge highlight)
  drawShape(
    [
      [hx - 28, hy - 10],
      [hx - 62, hy - 6],
      [hx - 88, hy + 8],
      [hx - 60, hy + 6],
      [hx - 28, hy + 4],
    ],
    {
      layer: layer + 0.22,
      washCol: YELLOW_1,
      hatchCol: YELLOW_3,
      hatchAngle: -10,
      strokeWeight: 0.65,
    }
  );
  // Lower Mandible
  drawShape(
    [
      [hx - 28, hy + 4],
      [hx - 62, hy + 6],
      [hx - 76, hy + 14],
      [hx - 28, hy + 15],
    ],
    {
      layer: layer + 0.22,
      washCol: YELLOW_DARK,
      strokeWeight: 0.6,
    }
  );
}

