// LAYER 2: MIRRORED STAR APPLIQUÉS (SITARA / CHAMKI)
// =========================================================================
function drawMirroredStars() {
  let layer = 2.0;
  for (let st of STAR_CONFIGS) {
    let { cx, cy, r, points, rot, palette } = st;

    // 1. Outer Scalloped Foil Collar
    let nScallops = points * 2;
    for (let i = 0; i < nScallops; i++) {
      let a0 = rot + (i * 360) / nScallops;
      let a1 = a0 + 360 / nScallops;
      let aMid = (a0 + a1) * 0.5;
      let col = palette[i % palette.length];
      let pts = [
        [cx + r * 0.68 * cos(a0), cy + r * 0.68 * sin(a0)],
        [cx + r * 0.94 * cos(a0 + 4), cy + r * 0.94 * sin(a0 + 4)],
        [cx + r * 1.0 * cos(aMid), cy + r * 1.0 * sin(aMid)],
        [cx + r * 0.94 * cos(a1 - 4), cy + r * 0.94 * sin(a1 - 4)],
        [cx + r * 0.68 * cos(a1), cy + r * 0.68 * sin(a1)],
      ];
      drawShape(pts, {
        layer,
        washCol: col,
        hatchCol: col,
        hatchAngle: aMid,
        hatchDist: 5,
        strokeWeight: 0.5,
      });
    }

    // 2. Bevelled 8-Pointed Mirror Star Facets (16 triangular facets)
    let rTip = r * 0.92;
    let rValley = r * 0.42;
    let rCore = r * 0.26;
    for (let i = 0; i < points; i++) {
      let aTip = rot + (i * 360) / points;
      let aPrev = aTip - 180 / points;
      let aNext = aTip + 180 / points;

      let pTip = [cx + rTip * cos(aTip), cy + rTip * sin(aTip)];
      let pPrev = [cx + rValley * cos(aPrev), cy + rValley * sin(aPrev)];
      let pNext = [cx + rValley * cos(aNext), cy + rValley * sin(aNext)];
      let pCore = [cx + rCore * cos(aTip), cy + rCore * sin(aTip)];

      // Left bevel facet: pure bare paper specular mirror reflection on sunny sides!
      let isSpecLeft = i === 0 || i === 1 || i === 5 || i === 6 || i === 7;
      let leftCol = isSpecLeft ? null : i % 2 === 0 ? CYAN_2 : YELLOW_2;
      drawShape([pCore, pPrev, pTip], {
        layer: layer + 0.02,
        washCol: leftCol,
        hatchCol: leftCol,
        hatchAngle: aTip - 25,
        hatchDist: 4.5,
        strokeWeight: 0.55,
      });

      // Right bevel facet: high-contrast dark chrome, electric cyan, or magenta reflection
      let rightCols = [INK, CYAN_3, MAGENTA_1, CHROME_DARK, CYAN_1, YELLOW_3, INK, MAGENTA_2];
      let rightCol = rightCols[i % rightCols.length];
      drawShape([pCore, pTip, pNext], {
        layer: layer + 0.02,
        washCol: rightCol,
        hatchCol: rightCol,
        hatchAngle: aTip + 25,
        hatchDist: 4.5,
        strokeWeight: 0.55,
      });
    }

    // 3. Central Circular Glass Mirror & Brass Eyelet Rivet
    // Upper-left half of center mirror left as bare paper; lower-right half in deep cyan/ink
    let mHalf1 = makeRingSectorPts(cx, cy, r * 0.1, r * 0.28, 135, 315, 7);
    let mHalf2 = makeRingSectorPts(cx, cy, r * 0.1, r * 0.28, -45, 135, 7);
    drawShape(mHalf1, {
      layer: layer + 0.04,
      washCol: null,
      strokeWeight: 0.55,
    });
    drawShape(mHalf2, {
      layer: layer + 0.04,
      washCol: CYAN_3,
      hatchCol: INK,
      hatchAngle: 45,
      strokeWeight: 0.55,
    });
    // Central Sequin Washer & Rivet Hole
    drawShape(makeCirclePts(cx, cy, r * 0.11, 10), {
      layer: layer + 0.05,
      washCol: palette[0],
      strokeWeight: 0.5,
    });
    drawShape(makeCirclePts(cx, cy, r * 0.045, 8), {
      layer: layer + 0.06,
      washCol: INK,
      strokeWeight: 0.4,
    });
  }
}

