function drawChromeBicycleBell() {
  let layer = 3.0;

  // 1. OUTER STEPPED & KNURLED CHROME BEZEL RIM (Radius 216 to 238)
  let nTeeth = 48;
  let rimPalette = [
    INK, null, CYAN_1, null, MAGENTA_1, INK, null, YELLOW_1,
    INK, null, GREEN_1, CYAN_2, INK, null, MAGENTA_2, YELLOW_2,
  ];
  for (let i = 0; i < nTeeth; i++) {
    let a0 = (i * 360) / nTeeth;
    let a1 = ((i + 1) * 360) / nTeeth;
    let col = rimPalette[i % rimPalette.length];
    let pts = makeRingSectorPts(BELL_X, BELL_Y, DOME_R, BELL_R, a0, a1, 3);
    drawShape(pts, {
      layer,
      skipClip: false,
      washCol: col,
      hatchCol: col,
      hatchAngle: a0 + 90,
      hatchDist: 4.5,
      strokeWeight: 0.55,
      minHatchArea: 60,
    });
  }

  // Inner Chrome Lip Ring (Radius 206 to 216) reflecting warped bands of the panel
  let nLip = 24;
  let lipCols = [MAGENTA_1, null, CYAN_1, YELLOW_1, INK, null, GREEN_1, MAGENTA_2];
  for (let i = 0; i < nLip; i++) {
    let a0 = (i * 360) / nLip;
    let a1 = ((i + 1) * 360) / nLip;
    let col = lipCols[i % lipCols.length];
    drawShape(makeRingSectorPts(BELL_X, BELL_Y, DOME_R - 11, DOME_R, a0, a1, 4), {
      layer: layer + 0.01,
      washCol: col,
      hatchCol: col,
      hatchAngle: a0,
      hatchDist: 5,
      strokeWeight: 0.5,
    });
  }

  // 2. SPHERICAL FISHEYE STREET REFLECTION ON THE DOME (az in [-165, 165], el in [-84, 84])
  // We partition the environment grid (az, el) into non-overlapping curvilinear reflection zones
  // so that bare-paper specular highlights are 100% untouched paper!

  // --- A. SKY VAULT & BLINDING SOLAR SPECULAR GLARE (el from -84 to -6) ---
  let skyElBands = [-84, -66, -48, -30, -16, -6];
  let skyAzBands = [-165, -125, -88, -62, -26, 8, 45, 88, 128, 165];

  for (let ei = 0; ei < skyElBands.length - 1; ei++) {
    let el0 = skyElBands[ei];
    let el1 = skyElBands[ei + 1];
    for (let ai = 0; ai < skyAzBands.length - 1; ai++) {
      let az0 = skyAzBands[ai];
      let az1 = skyAzBands[ai + 1];

      // Determine sky/sun/cloud color for this spherical cell
      let col = CYAN_1;
      let hatchCol = CYAN_3;

      // Blinding Midday Sun Specular Core (left as 100% BARE PAPER!)
      let isSunCore =
        (ei === 1 && (ai === 2 || ai === 3 || ai === 4)) ||
        (ei === 2 && (ai === 2 || ai === 3 || ai === 4)) ||
        (ei === 3 && ai === 3);
      // Bright Cloud / Glare Band on right sky (also BARE PAPER!)
      let isCloudGlare = (ei === 2 || ei === 3) && (ai === 5 || ai === 6);
      // Yellow Solar Halation Ring around the Sun Core
      let isSunHalo =
        (ei === 0 && (ai === 2 || ai === 3 || ai === 4)) ||
        (ei === 1 && (ai === 1 || ai === 5)) ||
        (ei === 3 && (ai === 2 || ai === 4));

      if (isSunCore || isCloudGlare) {
        col = null;
        hatchCol = null;
      } else if (isSunHalo) {
        col = YELLOW_2;
        hatchCol = YELLOW_1;
      } else if (ei === 0) {
        col = CYAN_3;
        hatchCol = INK;
      } else if (ei === 1 || ei === 2) {
        col = ai === 0 || ai === 8 ? MAGENTA_1 : CYAN_1;
        hatchCol = ai === 0 || ai === 8 ? MAGENTA_2 : CYAN_3;
      } else {
        col = CYAN_2;
        hatchCol = CYAN_1;
      }

      let patch = makeBellPatch(az0, az1, el0, el1, 5, 4);
      drawShape(patch, {
        layer: layer + 0.02,
        washCol: col,
        hatchCol: hatchCol,
        hatchAngle: (az0 + az1) * 0.25,
        hatchDist: 5.5,
        strokeWeight: 0.5,
      });
    }
  }

  // --- B. STREET ARCHITECTURE, TREES & FOLLOWING RICKSHAW (el from -6 to +32) ---
  // Left Bazaar Buildings & Shopfronts (az from -165 to -32)
  let leftBldgCells = [
    // Peripheral magenta/yellow tassel reflection at far left edge
    { az0: -165, az1: -132, el0: -6, el1: 32, col: MAGENTA_1, hCol: MAGENTA_2 },
    // Tall Chrome-Yellow & White Colonial Building (az -132 to -82)
    { az0: -132, az1: -82, el0: -34, el1: -14, col: YELLOW_1, hCol: YELLOW_3 },
    { az0: -132, az1: -108, el0: -14, el1: 4, col: null, hCol: null }, // Sunlit white wall glare!
    { az0: -108, az1: -92, el0: -14, el1: 4, col: INK, hCol: INK }, // Arched dark window
    { az0: -92, az1: -82, el0: -14, el1: 4, col: YELLOW_2, hCol: YELLOW_1 },
    // Striped Shop Awning & Cyan Signboard (el 4 to 22)
    { az0: -132, az1: -105, el0: 4, el1: 18, col: MAGENTA_1, hCol: MAGENTA_2 },
    { az0: -105, az1: -82, el0: 4, el1: 18, col: CYAN_1, hCol: CYAN_3 },
    { az0: -132, az1: -82, el0: 18, el1: 32, col: INK, hCol: CHROME_DARK },
    // Mid-Left Building & Parrot Green Street Tree (az -82 to -30)
    { az0: -82, az1: -52, el0: -26, el1: -6, col: MAGENTA_2, hCol: INK },
    { az0: -82, az1: -54, el0: -6, el1: 14, col: GREEN_1, hCol: GREEN_3 }, // Tree canopy
    { az0: -54, az1: -30, el0: -16, el1: 12, col: GREEN_2, hCol: GREEN_1 }, // Bright sunlit tree crown
    { az0: -48, az1: -34, el0: -12, el1: -2, col: null, hCol: null }, // Bare-paper leaf glare
    { az0: -82, az1: -30, el0: 12, el1: 32, col: CHROME_DARK, hCol: INK },
  ];

  // Right Bazaar Buildings, Billboards & Trees (az from +30 to +165)
  let rightBldgCells = [
    // Parrot Green Street Tree on right (az 30 to 62)
    { az0: 30, az1: 62, el0: -18, el1: 10, col: GREEN_1, hCol: GREEN_3 },
    { az0: 36, az1: 52, el0: -12, el1: -2, col: GREEN_2, hCol: GREEN_1 },
    { az0: 30, az1: 62, el0: 10, el1: 32, col: INK, hCol: CHROME_DARK },
    // Multi-story Cyan & Magenta Shop Building (az 62 to 128)
    { az0: 62, az1: 96, el0: -32, el1: -12, col: MAGENTA_1, hCol: MAGENTA_2 }, // Rooftop billboard
    { az0: 96, az1: 128, el0: -28, el1: -8, col: YELLOW_1, hCol: YELLOW_3 },
    { az0: 62, az1: 84, el0: -12, el1: 8, col: CYAN_1, hCol: CYAN_3 },
    { az0: 84, az1: 102, el0: -12, el1: 8, col: INK, hCol: INK }, // Dark window arcade
    { az0: 102, az1: 128, el0: -8, el1: 10, col: null, hCol: null }, // Sun-bleached wall glare!
    { az0: 62, az1: 98, el0: 8, el1: 22, col: YELLOW_1, hCol: YELLOW_DARK }, // Shop awning
    { az0: 98, az1: 128, el0: 10, el1: 24, col: GREEN_1, hCol: GREEN_3 },
    { az0: 62, az1: 128, el0: 22, el1: 32, col: CHROME_DARK, hCol: INK },
    // Far-right peripheral reflection of the Rickshaw's own Plastic Tassels! (az 128 to 165)
    { az0: 128, az1: 165, el0: -16, el1: 12, col: YELLOW_1, hCol: YELLOW_3 },
    { az0: 128, az1: 165, el0: 12, el1: 36, col: MAGENTA_1, hCol: MAGENTA_2 },
  ];

  // Center Horizon & Following Auto-Rickshaw Reflection (az from -30 to +30)
  let centerRickshawCells = [
    // Distant overpass & horizon sky gap
    { az0: -30, az1: 30, el0: -12, el1: -4, col: CYAN_2, hCol: CYAN_1 },
    // Following Auto-Rickshaw Arched Yellow Canopy Roof
    { az0: -24, az1: 24, el0: -4, el1: 5, col: YELLOW_1, hCol: YELLOW_3 },
    // Rickshaw Windshield (split into dark glass & bare-paper sky glare slash!)
    { az0: -22, az1: -4, el0: 5, el1: 18, col: INK, hCol: CHROME_DARK },
    { az0: -4, az1: 10, el0: 5, el1: 18, col: null, hCol: null }, // Bare-paper windshield glare!
    { az0: 10, az1: 22, el0: 5, el1: 18, col: CYAN_3, hCol: INK },
    // Rickshaw Parrot-Green & Yellow Front Cowl
    { az0: -26, az1: -8, el0: 18, el1: 34, col: GREEN_1, hCol: GREEN_3 },
    { az0: 8, az1: 26, el0: 18, el1: 34, col: GREEN_1, hCol: GREEN_3 },
    { az0: -8, az1: 8, el0: 18, el1: 34, col: YELLOW_1, hCol: YELLOW_DARK },
    // Central Round Chrome Headlight of Following Rickshaw (pure bare paper!)
    { az0: -5, az1: 5, el0: 21, el1: 30, col: null, hCol: null },
  ];

  let allMidCells = leftBldgCells.concat(rightBldgCells, centerRickshawCells);
  for (let c of allMidCells) {
    let patch = makeBellPatch(c.az0, c.az1, c.el0, c.el1, 5, 4);
    drawShape(patch, {
      layer: layer + 0.04,
      washCol: c.col,
      hatchCol: c.hCol,
      hatchAngle: (c.az0 + c.az1) * 0.3,
      hatchDist: 5,
      strokeWeight: 0.55,
      minHatchArea: 90,
    });
  }

  // --- C. LOWER HEMISPHERE: CURVED ASPHALT ROADWAY, LANE STRIPES & PANEL REFLECTION (el +32 to +84) ---
  let roadCells = [
    // Upper road shadow band & bright midday pavement glare
    { az0: -155, az1: -75, el0: 32, el1: 52, col: CHROME_DARK, hCol: INK },
    { az0: -75, az1: -18, el0: 32, el1: 48, col: null, hCol: null }, // Blinding road glare!
    { az0: -18, az1: 22, el0: 34, el1: 52, col: INK, hCol: INK }, // Under-rickshaw shadow
    { az0: 22, az1: 82, el0: 32, el1: 48, col: CYAN_LIGHT, hCol: CYAN_1 },
    { az0: 82, az1: 155, el0: 32, el1: 52, col: CHROME_DARK, hCol: INK },
    // Chrome-yellow traffic lane stripe curving down the street
    { az0: -48, az1: -32, el0: 42, el1: 72, col: YELLOW_1, hCol: YELLOW_3 },
    { az0: 34, az1: 50, el0: 42, el1: 72, col: YELLOW_1, hCol: YELLOW_3 },
    // Mid-lower road bands reflecting colourful bazaar colors
    { az0: -155, az1: -48, el0: 52, el1: 68, col: MAGENTA_2, hCol: INK },
    { az0: -32, az1: 34, el0: 52, el1: 68, col: CHROME_DARK, hCol: INK },
    { az0: 50, az1: 155, el0: 52, el1: 68, col: GREEN_3, hCol: INK },
    // Bottom grazing reflection of the rickshaw's own magenta/cyan/yellow rear panel (el 68 to 84)
    { az0: -160, az1: -80, el0: 68, el1: 84, col: CYAN_1, hCol: CYAN_3 },
    { az0: -80, az1: 0, el0: 68, el1: 84, col: MAGENTA_1, hCol: MAGENTA_2 },
    { az0: 0, az1: 80, el0: 68, el1: 84, col: YELLOW_1, hCol: YELLOW_3 },
    { az0: 80, az1: 160, el0: 68, el1: 84, col: GREEN_1, hCol: GREEN_3 },
  ];
  for (let c of roadCells) {
    let patch = makeBellPatch(c.az0, c.az1, c.el0, c.el1, 6, 4);
    drawShape(patch, {
      layer: layer + 0.05,
      washCol: c.col,
      hatchCol: c.hCol,
      hatchAngle: (c.az0 + c.az1) * 0.35,
      hatchDist: 5,
      strokeWeight: 0.55,
      minHatchArea: 80,
    });
  }

  // --- D. CURVED OVERHEAD POWERLINES & STREET BUNTING ACROSS THE UPPER DOME ---
  let wireElevs = [-58, -51, -26, -20];
  for (let wEl of wireElevs) {
    let wirePts = [];
    for (let az = -155; az <= 155; az += 8) {
      wirePts.push(envToBell(az, wEl));
    }
    drawClippedPolyline(wirePts, layer + 0.08, "rotring", INK, 0.65, 0.2);
  }

  // Little colorful triangular bunting flags hanging along the -36° street wire
  let buntWire = [];
  let buntCols = [MAGENTA_1, YELLOW_1, GREEN_1, CYAN_1];
  for (let i = 0; i <= 14; i++) {
    let az = -126 + i * 18;
    buntWire.push(envToBell(az, -36));
    if (i < 14) {
      let pA = envToBell(az + 2, -36);
      let pB = envToBell(az + 16, -36);
      let pTip = envToBell(az + 9, -27);
      drawShape([pA, pB, pTip], {
        layer: layer + 0.09,
        washCol: buntCols[i % buntCols.length],
        strokeWeight: 0.45,
      });
    }
  }
  drawClippedPolyline(buntWire, layer + 0.09, "rotring", INK, 0.55, 0.2);

  // --- E. CENTRAL RAISED HEXAGONAL CHROME APEX NUT (Crown of the Bell) ---
  let nutX = BELL_X - 6;
  let nutY = BELL_Y - 8;
  // Chrome washer ring
  drawShape(makeCirclePts(nutX, nutY, 30, 18), {
    layer: layer + 0.12,
    washCol: INK,
    strokeWeight: 0.7,
  });
  // Hexagonal nut facets (top-left left as bare paper!)
  for (let i = 0; i < 6; i++) {
    let a0 = i * 60 - 15;
    let a1 = a0 + 60;
    let fCol = i === 2 || i === 3 ? null : i === 0 ? INK : i === 1 ? CYAN_1 : YELLOW_1;
    drawShape(makeRingSectorPts(nutX, nutY, 10, 24, a0, a1, 2), {
      layer: layer + 0.14,
      washCol: fCol,
      strokeWeight: 0.6,
    });
  }
  // Center screw cap & machined black slot
  drawShape(makeCirclePts(nutX, nutY, 10, 12), {
    layer: layer + 0.15,
    washCol: null,
    strokeWeight: 0.6,
  });
  drawShape(
    [
      [nutX - 9, nutY - 2],
      [nutX + 9, nutY - 4],
      [nutX + 9, nutY + 2],
      [nutX - 9, nutY + 4],
    ],
    {
      layer: layer + 0.16,
      washCol: INK,
      strokeWeight: 0.45,
    }
  );

  // Crisp outer master contour of the Chrome Bell
  drawClippedPolyline(
    makeCirclePts(BELL_X, BELL_Y, BELL_R, 64).concat([[BELL_X + BELL_R, BELL_Y]]),
    layer + 0.18,
    "rotring",
    INK,
    1.1,
    0.1
  );
  drawClippedPolyline(
    makeCirclePts(BELL_X, BELL_Y, DOME_R, 60).concat([[BELL_X + DOME_R, BELL_Y]]),
    layer + 0.18,
    "rotring",
    INK,
    0.85,
    0.1
  );
}

// =========================================================================
// LAYER 4: GLOSSY PLASTIC TASSELS, POM-POMS, JHUMKA CAPS & BEADS
// =========================================================================
function drawPlasticTassels() {
  // 1. Draw Glossy Cut-Plastic Fringe Ribbons
  for (let i = 0; i < tasselRibbons.length; i++) {
    let r = tasselRibbons[i];
    let ang = atan2(r.y1 - r.y0, r.x1 - r.x0);

    if (r.hasSpec) {
      // Split ribbon into 3 segments so the central glossy highlight is left as BARE PAPER!
      let qTop = getRibbonQuad(r, -0.5, 0.5, 0.0, 0.22);
      let qMidLeft = getRibbonQuad(r, -0.5, -0.15, 0.22, 0.68);
      let qSpec = getRibbonQuad(r, -0.15, 0.22, 0.22, 0.68); // Bare paper specular stripe!
      let qMidRight = getRibbonQuad(r, 0.22, 0.5, 0.22, 0.68);
      let qBot = getRibbonQuad(r, -0.5, 0.5, 0.68, 1.0);

      for (let q of [qTop, qMidLeft, qMidRight, qBot]) {
        drawShape(q, {
          layer: r.layer,
          washCol: r.col,
          hatchCol: r.col,
          hatchAngle: ang,
          hatchDist: 4.5,
          strokeWeight: 0.5,
          minHatchArea: 70,
        });
      }
      // Draw the crisp outline around the bare-paper highlight core
      drawShape(qSpec, {
        layer: r.layer + 0.005,
        washCol: null,
        strokeWeight: 0.42,
      });
    } else {
      let fullQuad = getRibbonQuad(r, -0.5, 0.5, 0.0, 1.0);
      drawShape(fullQuad, {
        layer: r.layer,
        washCol: r.col,
        hatchCol: r.col,
        hatchAngle: ang,
        hatchDist: 4.5,
        strokeWeight: 0.55,
        minHatchArea: 70,
      });
    }
  }

  // 2. Draw Fluffy Pleated Plastic Pom-Pom Balls
  for (let p of tasselPomPoms) {
    let { cx, cy, r, cols, layer } = p;
    // Outer ring of crimped plastic petals (28 petals)
    let nOuter = 28;
    for (let i = 0; i < nOuter; i++) {
      let a0 = (i * 360) / nOuter;
      let a1 = a0 + 360 / nOuter;
      let aMid = (a0 + a1) * 0.5;
      let rOut = r * (0.92 + 0.12 * sin(i * 70));
      let col = cols[i % cols.length];
      let isSpec = i % 7 === 0;
      let pts = [
        [cx + r * 0.25 * cos(a0), cy + r * 0.25 * sin(a0)],
        [cx + rOut * cos(a0 + 2), cy + rOut * sin(a0 + 2)],
        [cx + (rOut + 5) * cos(aMid), cy + (rOut + 5) * sin(aMid)],
        [cx + rOut * cos(a1 - 2), cy + rOut * sin(a1 - 2)],
        [cx + r * 0.25 * cos(a1), cy + r * 0.25 * sin(a1)],
      ];
      drawShape(pts, {
        layer,
        washCol: isSpec ? null : col,
        hatchCol: isSpec ? null : col,
        hatchAngle: aMid,
        hatchDist: 4.5,
        strokeWeight: 0.48,
      });
    }

    // Inner rosette core of the pom-pom (16 shorter crimped petals)
    let nInner = 16;
    for (let i = 0; i < nInner; i++) {
      let a0 = 11 + (i * 360) / nInner;
      let a1 = a0 + 360 / nInner;
      let aMid = (a0 + a1) * 0.5;
      let rInOut = r * 0.54;
      let col = cols[(i + 2) % cols.length];
      let isSpec = i % 5 === 0;
      let pts = [
        [cx + r * 0.08 * cos(a0), cy + r * 0.08 * sin(a0)],
        [cx + rInOut * cos(a0 + 3), cy + rInOut * sin(a0 + 3)],
        [cx + (rInOut + 4) * cos(aMid), cy + (rInOut + 4) * sin(aMid)],
        [cx + rInOut * cos(a1 - 3), cy + rInOut * sin(a1 - 3)],
        [cx + r * 0.08 * cos(a1), cy + r * 0.08 * sin(a1)],
      ];
      drawShape(pts, {
        layer: layer + 0.02,
        washCol: isSpec ? null : col,
        hatchCol: isSpec ? null : col,
        hatchAngle: aMid,
        hatchDist: 4,
        strokeWeight: 0.48,
      });
    }
  }

  // 3. Draw Conical Silver & Enamel Jhumka Caps
  for (let c of tasselCaps) {
    let { cx, cy, w, h, col1, col2, layer } = c;
    let strips = 8;
    for (let i = 0; i < strips; i++) {
      let f0 = i / strips - 0.5;
      let f1 = (i + 1) / strips - 0.5;
      let xTop0 = cx + f0 * w * 0.58;
      let xTop1 = cx + f1 * w * 0.58;
      let xBot0 = cx + f0 * w;
      let xBot1 = cx + f1 * w;
      let yTop = cy - h * 0.48;
      let yBot = cy + h * 0.38;

      // Vertical fluted cone facet (with bare-paper chrome highlight on strips 2 and 3!)
      let isHighlight = i === 2 || i === 3;
      let fCol = isHighlight ? null : i === 0 || i === 7 ? INK : i % 2 === 0 ? col1 : col2;
      drawShape(
        [
          [xTop0, yTop],
          [xTop1, yTop],
          [xBot1, yBot],
          [xBot0, yBot],
        ],
        {
          layer,
          washCol: fCol,
          hatchCol: fCol,
          hatchAngle: 85,
          hatchDist: 4.5,
          strokeWeight: 0.55,
        }
      );

      // Scalloped bottom bead along the jhumka rim
      let bx = (xBot0 + xBot1) * 0.5;
      let by = yBot + 6;
      drawShape(makeCirclePts(bx, by, w / strips * 0.52, 8), {
        layer: layer + 0.01,
        washCol: i % 2 === 0 ? col2 : null,
        strokeWeight: 0.48,
      });
    }
  }

  // 4. Draw Glossy Plastic Beads & Mounting Rings
  for (let b of tasselBeads) {
    let { cx, cy, r, col, layer } = b;
    // Main colored bead body
    drawShape(makeCirclePts(cx, cy, r, 14), {
      layer,
      washCol: col,
      hatchCol: col,
      hatchAngle: 35,
      hatchDist: 4.5,
      strokeWeight: 0.65,
    });
    // Bare-paper specular highlight window on upper-left of bead
    drawShape(makeCirclePts(cx - r * 0.32, cy - r * 0.32, r * 0.32, 10), {
      layer: layer + 0.01,
      washCol: null,
      strokeWeight: 0.45,
    });
  }
}

// =========================================================================
// CRISP INK ACCENTS, BEADED CHAINS & ENAMEL DOT-WORK
// =========================================================================
function drawInkFinalsAndBeadChains() {
  // Hang decorative beaded plastic chains curving between the top stars and tassels
  let chains = [
    { x0: 162, y0: 118, ctrlX: 295, ctrlY: 225, x1: 425, y1: 128 },
    { x0: 425, y0: 128, ctrlX: 585, ctrlY: 205, x1: 748, y1: 132 },
    { x0: 748, y0: 132, ctrlX: 855, ctrlY: 195, x1: 955, y1: 118 },
  ];
  let beadCols = [YELLOW_1, MAGENTA_1, CYAN_1, GREEN_1];

  for (let ch of chains) {
    let nBeads = 16;
    for (let i = 1; i < nBeads; i++) {
      let t = i / nBeads;
      let mt = 1 - t;
      let bx = mt * mt * ch.x0 + 2 * mt * t * ch.ctrlX + t * t * ch.x1;
      let by = mt * mt * ch.y0 + 2 * mt * t * ch.ctrlY + t * t * ch.y1;
      let col = i % 4 === 0 ? null : beadCols[i % beadCols.length];
      drawShape(makeCirclePts(bx, by, 7.5, 10), {
        layer: 1.8,
        washCol: col,
        strokeWeight: 0.5,
      });
    }
  }
}

function draw() {
  translate(-width / 2, -height / 2);

  buildTasselGeometry();
  registerAllMasks();

  // Layer 0 & 1: Enamel Tapestry, Peacock Train, Folk Rosettes, Borders & Peacock Body
  drawBackgroundEnamelTapestry();
  drawHandPaintedPeacock();
  drawPanelBorders();
  drawInkFinalsAndBeadChains();

  // Layer 2: Mirrored Star Appliqués
  drawMirroredStars();

  // Layer 3: Chrome Bicycle Bell, Clamp & Striker Lever
  drawBellBracketAndLever();
  drawChromeBicycleBell();

  // Layer 4: Cascading Plastic Tassels, Pom-Poms & Jhumka Caps
  drawPlasticTassels();

  noLoop();
}
